INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00002', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-27T23:48:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T00:33:21+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2023-10-01T10:00:00+09:00に発生したストレージ溢れのインシデントが確認されました。現象として、同一アラートが短時間に数百件発報しており、運用部門のみが影響を受けています。大規模セール開始直前での発生が契機となっています。特定された影響コンポーネントはMercury AWS Storage（ゾーンA）およびアラートマネージャです。推定原因として、アラート抑制ルールの未設定が考えられます。検知は2023-10-01T10:29:00+09:00に行われ、検知までの時間は29分です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00002', 'INC-2020-00002', 'インシデントの原因を調査したところ、アラート抑制ルールが未設定であることが主な要因であることが判明しました。これにより、大規模セール開始直前に同一アラートが短時間に数百件発報するという状態が引き起こされました。運用部門においては、これらのアラートが監視業務に支障をきたすことが懸念されます。', 'インシデントの原因を調査したところ、アラート抑制ルールが未設定であることが主な要因であることが判明しました。これにより、大規模セール開始直前に同一アラートが短時間に数百件発報するという状態が引き起こされました。運用部門においては、これらのアラートが監視業務に支障をきたすことが懸念されます。', TIMESTAMP WITH TIME ZONE '2020-04-29T00:33:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00003', 'INC-2020-00002', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T00:48:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T01:48:21+09:00', '【初期対応】【監視・可用性障害】アラート疲労', 'インシデント発生直後に運用部員が集まり、問題の確認を行いました。アラートの抑制についてのルールが未設定であることが即座に特定され、今後の対策としてこのルールを速やかに設定することが決定されました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00004', 'INC-2020-00002', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T02:18:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T03:18:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
