INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00007', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-03T01:04:42+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T03:04:42+09:00', '【障害報告】【棚卸・POS突合障害】月次突合不一致', '2023-10-01T09:30:00+09:00 に、株式会社ストッククラウドの顧客店舗POSにおいて、月次突合レポートの合計が帳票と不一致であるという事象が発生しました。エラーコードは INV-05-00007 であり、発生は月末棚卸の開始時でありました。今回の事象は、同一顧客の全店舗に影響を及ぼすものであり、返品データの符号反転漏れが原因として考えられます。これにより、正確な月次突合が行えず、帳票との不一致が生じました。月次突合に関する影響範囲が広く、早急な対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00007', 'INC-2020-00007', '調査の結果、月末棚卸の開始時に発生した月次突合レポートの合計が帳票と不一致だった原因として、返品データの符号反転漏れが確認されました。このため、同一顧客の全店舗に対して影響が及び、正確なレポート作成が妨げられています。月次集計ジョブにおけるデータの整合性を保つため、迅速な是正措置を講じる必要があります。', '調査の結果、月末棚卸の開始時に発生した月次突合レポートの合計が帳票と不一致だった原因として、返品データの符号反転漏れが確認されました。このため、同一顧客の全店舗に対して影響が及び、正確なレポート作成が妨げられています。月次集計ジョブにおけるデータの整合性を保つため、迅速な是正措置を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-04T03:04:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00012', 'INC-2020-00007', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T03:19:42+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T04:19:42+09:00', '【初期対応】【棚卸・POS突合障害】月次突合不一致', '2023-10-01T10:00:00+09:00 に初期対応を実施し、影響を受けた顧客店舗POSの月次集計ジョブを一時停止しました。また、返品データの確認を行い、符号反転漏れに関する詳細な調査を開始しました。顧客への影響を最小限に抑えるため、状況を注視し、必要な報告を行う準備をしています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00009', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-29T04:33:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T05:03:23+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2023年10月01日 14:15:00に、株式会社ストッククラウドのサービスMercuryにおいて、在庫登録APIがHTTP 500を返し、SKUの登録が失敗するという障害が発生しました。この障害は、定例リリース直後に発生し、影響範囲は単一店舗の登録機能のみにとどまりました。原因としては、単位換算係数の設定漏れが推測されます。エラーコードはMST-01-00009であり、影響コンポーネントはMercury AWS AP（ゾーンB）の在庫登録APIです。今後、同様の問題が発生しないよう、手順の見直しを含めた対策を講じる必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00009', 'INC-2020-00009', '本障害について調査した結果、定例リリース直後にSKU登録APIがHTTP 500を返し、在庫反映に失敗する事象が確認されました。推定原因としては、単位換算係数の設定漏れが考えられます。エラーの詳細を分析し、関連する設定ファイルの確認を実施しましたが、設定漏れが原因であることが裏付けられました。当該APIの正常稼働を確保するためには、設定の適正化が急務です。', '本障害について調査した結果、定例リリース直後にSKU登録APIがHTTP 500を返し、在庫反映に失敗する事象が確認されました。推定原因としては、単位換算係数の設定漏れが考えられます。エラーの詳細を分析し、関連する設定ファイルの確認を実施しましたが、設定漏れが原因であることが裏付けられました。当該APIの正常稼働を確保するためには、設定の適正化が急務です。', TIMESTAMP WITH TIME ZONE '2020-04-30T05:03:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00014', 'INC-2020-00009', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-29T05:18:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T06:18:23+09:00', '【対応】【在庫マスター設定障害】SKU登録HTTP500', '本障害に関する初期対応を実施いたしました。運用部の運用 一郎が中心となり、SKU登録APIのエラー内容を確認しました。さらに、定例リリースに関する設定の見直しを行い、単位換算係数が適切に設定されているか再確認しました。これにより、今後同様の障害が発生しないよう、改善策を講じることが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00012', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-29T11:35:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T11:50:36+09:00', '【障害報告】【CLU-10】ヘルスチェック過負荷', '2020年5月1日11時35分36秒に、株式会社ストッククラウドのサービスMercuryにおいて運用者の作業ミスによるアクセス障害が発生しました。症状はヘルスチェック過多でAPサーバー負荷が増加し、全テナントに波及する影響を及ぼしました。この障害は、運用コンソールにおいて発生し、運用部の運用 一郎が発見しました。発生契機はインフラメンテナンス明けであり、推定原因としてLBヘルスチェック間隔の過短設定が考えられます。エラーコードはMON-06-00012です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00012', 'INC-2020-00012', '運用部の運用 一郎によると、インフラメンテナンス明けにLBヘルスチェックの設定が適切でなかったため、ヘルスチェックが過多になりAPサーバーに過負荷がかかる状態が発生しました。ヘルスチェックの間隔が過短に設定されていたことが、この問題の根本原因として特定されました。今回の監視・可用性障害は全テナントに影響を与え、迅速な対応が求められました。', '運用部の運用 一郎によると、インフラメンテナンス明けにLBヘルスチェックの設定が適切でなかったため、ヘルスチェックが過多になりAPサーバーに過負荷がかかる状態が発生しました。ヘルスチェックの間隔が過短に設定されていたことが、この問題の根本原因として特定されました。今回の監視・可用性障害は全テナントに影響を与え、迅速な対応が求められました。', TIMESTAMP WITH TIME ZONE '2020-04-30T11:50:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00018', 'INC-2020-00012', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-29T12:05:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T13:05:36+09:00', '【対応ログ】初期対応', '2020年5月1日11時50分に運用部の運用 一郎が初期対応を実施しました。まずはヘルスチェックの設定を見直し、LBのヘルスチェック間隔を適正に設定し直しました。その後、APサーバーの負荷を監視し、各テナントへの影響を最小限に抑えるための状況把握に努めました。これにより、ヘルスチェックによる過負荷が解消されることを期待しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00015', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-11-13T16:57:18+09:00', TIMESTAMP WITH TIME ZONE '2020-11-13T17:27:18+09:00', '【障害報告】【CLU-08】リフレッシュトークン再利用', '2023-10-01T10:15:00+09:00に株式会社ストッククラウドのMercuryサービスにおいて、リフレッシュトークン再利用が検知され、全端末がログアウトしました。この事象は年末年始の稼働切替時に発生し、同一顧客の全店舗に影響を及ぼしました。推定原因はトークンローテーション実装の不備です。影響を受けたコンポーネントはVenus Azure AP（ゾーンA）およびセッションストアです。リフレッシュトークンの適切な管理が求められる中、このような事態が発生したことは、今後の運用に対する重要な教訓となります。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00015', 'INC-2020-00015', 'リフレッシュトークン再利用の問題について調査を行ったところ、年末年始の稼働切替時にトークンローテーションの実装に不備があったことが判明しました。この不備により、リフレッシュトークンが再利用され、全端末ログアウトが発生しました。運用部門の運用 一郎がこの問題を発見し、迅速に対応を開始しました。今後はトークンローテーションの実装を見直し、再発防止策を講じる必要があります。', 'リフレッシュトークン再利用の問題について調査を行ったところ、年末年始の稼働切替時にトークンローテーションの実装に不備があったことが判明しました。この不備により、リフレッシュトークンが再利用され、全端末ログアウトが発生しました。運用部門の運用 一郎がこの問題を発見し、迅速に対応を開始しました。今後はトークンローテーションの実装を見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-11-14T17:27:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00022', 'INC-2020-00015', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-11-13T17:42:18+09:00', TIMESTAMP WITH TIME ZONE '2020-11-13T18:42:18+09:00', '初期対応', '2023-10-01T10:20:00+09:00に運用 一郎が問題を検知し、直ちに対策を講じました。リフレッシュトークンの再利用が確認されたため、全端末のログアウトを実施し、ユーザーへの影響を最小限に抑えるよう努めました。また、運用チームは状況を把握し、影響範囲を確認するための調査を開始しました。この初期対応により、さらなる影響の拡大を防ぐことができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00020', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-10-14T16:29:31+09:00', TIMESTAMP WITH TIME ZONE '2020-10-14T16:59:31+09:00', '【障害報告】【在庫マスター設定障害】ロット管理初回入庫不可', '2023-10-01T10:00:00+09:00に、株式会社ストッククラウドのサービスMercuryにおいて、顧客の架空食品店Bに対してロット管理初回入庫処理でロット番号採番に失敗しました。発生契機は顧客オンボーディング当日であり、影響範囲は単一店舗のみです。この障害は、ロット管理フラグの誤った有効化が原因と考えられています。エラーコードはMST-08-00020であり、影響コンポーネントはMercury AWS APおよびロット管理サービスです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00020', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00020', 'INC-2020-00020', '発生した障害について、詳細な調査を行いました。顧客オンボーディング当日に発生したロット番号採番の失敗は、ロット管理フラグの誤った有効化によるものであると確認しました。この問題により、初回入庫処理が正常に完了せず、在庫マスター設定に影響を及ぼしました。適切な設定が行われていないため、今後のトラブルを未然に防ぐための対策が必要です。', '発生した障害について、詳細な調査を行いました。顧客オンボーディング当日に発生したロット番号採番の失敗は、ロット管理フラグの誤った有効化によるものであると確認しました。この問題により、初回入庫処理が正常に完了せず、在庫マスター設定に影響を及ぼしました。適切な設定が行われていないため、今後のトラブルを未然に防ぐための対策が必要です。', TIMESTAMP WITH TIME ZONE '2020-10-15T16:59:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00028', 'INC-2020-00020', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-10-14T17:14:31+09:00', TIMESTAMP WITH TIME ZONE '2020-10-14T18:14:31+09:00', '【初期対応】【在庫マスター設定障害】ロット管理初回入庫不可', '初期対応として、問題の影響範囲を確認し、顧客の架空食品店Bへの影響を最小限に抑えるための対応策を講じました。具体的には、ロット管理フラグの設定を見直し、正しい設定に修正しました。この修正により、今後の入庫処理が正常に行われることを確認しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00024', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-16T23:53:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T00:23:19+09:00', '【障害報告】【監視・可用性障害】SLO燃焼率警告', '2020年4月16日23時53分に、株式会社ストッククラウドのMercuryサービスにて、利用者増による応答遅延が発生しました。具体的には、SLO燃焼率が閾値を超過し、エラーバジェット警告が出ました。この問題は全テナントに波及しており、特にVenus Azure AP（ゾーンA）とSLOダッシュボードに影響を与えています。発生は大規模セール開始直前であり、SLO計算ウィンドウの設定誤りが原因と推定されます。検知は2020年4月17日00時24分に行われ、発見者は運用部の運用 一郎です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00024', 'INC-2020-00024', '調査の結果、SLO計算ウィンドウが不適切に設定されていることが確認されました。この設定誤りが原因で、SLO燃焼率が閾値を超過し、エラーバジェット警告が発生しました。大規模セール前の利用者増加により、影響は全テナントに及びました。この問題は監視・可用性障害として分類され、早急な対応が必要です。', '調査の結果、SLO計算ウィンドウが不適切に設定されていることが確認されました。この設定誤りが原因で、SLO燃焼率が閾値を超過し、エラーバジェット警告が発生しました。大規模セール前の利用者増加により、影響は全テナントに及びました。この問題は監視・可用性障害として分類され、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-18T00:23:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00033', 'INC-2020-00024', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T00:38:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T01:38:19+09:00', '【初期対応】【監視・可用性障害】SLO燃焼率警告', '初期対応として、SLO計算ウィンドウの設定を見直し、適正な値に修正しました。また、SLO燃焼率の監視を強化し、エラーバジェットの管理を徹底する方針を決定しました。影響を受けた全テナントへの通知を行い、今後の類似の問題を防ぐための対策を検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
