INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00038', 'INC-2020-00027', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T15:09:26+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T16:09:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00029', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-17T09:14:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T11:14:19+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2020年4月17日09時14分19秒に、株式会社ストッククラウドのサービスMercuryにおいて棚卸突合失敗のインシデントが発生しました。発見者は営業部の花子で、顧客店舗POSにおいてパートナーAPIが429を返し連携が停止しました。この事象は大規模セール開始直前に起こり、呼出頻度の事前調整不足が原因として推定されています。影響範囲はサービス全体の一部機能に及び、エラーコードはEDI-06-00029です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00029', 'INC-2020-00029', 'インシデント発生後、確認を行ったところ、大規模セール開始直前にパートナーAPIが429を返却していたことが判明しました。これにより、顧客店舗POSとの連携が停止し、適切な呼出頻度の調整が行われていなかったことが主な原因と考えられます。今後は、同様の事象を防ぐために、事前に呼出頻度を見直す必要があります。', 'インシデント発生後、確認を行ったところ、大規模セール開始直前にパートナーAPIが429を返却していたことが判明しました。これにより、顧客店舗POSとの連携が停止し、適切な呼出頻度の調整が行われていなかったことが主な原因と考えられます。今後は、同様の事象を防ぐために、事前に呼出頻度を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-18T11:14:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00041', 'INC-2020-00029', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-17T11:29:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T12:29:19+09:00', '【初期対応】【API連携・EDI障害】レート超過429', 'インシデント発生後、営業の花子が状況を把握し、迅速に関係者に通知しました。APIゲートウェイ側での調整を試みましたが、パートナーAPIの429エラーにより連携が続かず、サービスの一部機能が影響を受ける事態となりました。これに対して迅速な対応が求められています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00030', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-27T17:24:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T18:24:57+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2023-10-01T12:00:00+09:00に発生した顧客ネットワーク障害について報告します。この障害は、DNS解決成功後にTLS握手で接続が切断されるという症状が見られました。影響を受けたのは、同一顧客の全店舗です。発生契機は、インフラメンテナンス明けとなっており、推定原因としてプロキシ証明書の期限切れが考えられます。さらに詳しい技術詳細としては、インフラメンテナンス明けにDNS解決成功後にTLS握手で接続が切断され、これにより顧客のサービスに影響が出ました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00030', 'INC-2020-00030', 'インシデントの調査を行い、原因分析を実施しました。DNS解決が成功した後のTLS握手での接続切断現象があったため、プロキシ証明書の状態を確認しました。結果として、やはりプロキシ証明書が期限切れであったことが確認されました。これにより、顧客の全店舗が同時に影響を受けたことが明らかになりました。今後は、証明書の管理を強化し、定期的な点検を行うことが必要です。', 'インシデントの調査を行い、原因分析を実施しました。DNS解決が成功した後のTLS握手での接続切断現象があったため、プロキシ証明書の状態を確認しました。結果として、やはりプロキシ証明書が期限切れであったことが確認されました。これにより、顧客の全店舗が同時に影響を受けたことが明らかになりました。今後は、証明書の管理を強化し、定期的な点検を行うことが必要です。', TIMESTAMP WITH TIME ZONE '2020-04-28T18:24:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00042', 'INC-2020-00030', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-27T18:39:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T19:39:57+09:00', '【初動対応】顧客ネットワーク障害 TLS握手切断', '2023-10-01T12:01:00+09:00に初動対応を開始しました。顧客からの問い合わせを受け、直ちにネットワーク状況を確認しました。DNS解決は成功していますが、TLS握手で接続が切断されていることが判明。プロキシ証明書の期限を確認し、期限切れであることが分かりました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00043', 'INC-2020-00030', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-27T20:09:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T21:09:57+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00032', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-08T15:06:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T17:06:43+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2023-05-12T10:15:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00032', 'INC-2020-00032', '本障害に関して、冪等キーの重複が確認されました。特に、最近の定例リリース後に発生したため、リリースに伴う冪等キー生成ロジックの衝突が原因と考えられます。影響を受けている顧客店舗は全ての店舗で、在庫更新がスキップされている状況です。現在、API連携およびEDIの動作を確認し、適切な対策を講じる必要があります。', '本障害に関して、冪等キーの重複が確認されました。特に、最近の定例リリース後に発生したため、リリースに伴う冪等キー生成ロジックの衝突が原因と考えられます。影響を受けている顧客店舗は全ての店舗で、在庫更新がスキップされている状況です。現在、API連携およびEDIの動作を確認し、適切な対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-09T17:06:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00045', 'INC-2020-00032', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-08T17:21:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T18:21:43+09:00', '【初動対応】【CLU-07】冪等キー重複', '本障害を受けて、初動対応を開始しました。影響を受けている顧客店舗POSの状況を確認し、在庫更新の遅延の原因を特定するための調査を進めています。冪等キーの重複が確認されたため、発生したエラーを解決するためにAPI連携とEDIの設定を見直す必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00046', 'INC-2020-00032', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-08T18:51:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T19:51:43+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00033', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-08T01:58:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T03:58:49+09:00', '【障害報告】【API連携・EDI障害】JSONスキーマ不一致', '2023-10-01T10:00:00+09:00に発生した棚卸突合失敗に関する報告です。この事象は、顧客店舗POSにおける全件拒否の症状を引き起こしました。具体的には、連携JSONのスキーマ不一致が原因であり、スキーマバージョンの同期漏れが推定されています。この障害は、定例リリース直後に発生し、影響範囲はバッチ処理のみで、オンラインには影響がありませんでした。エラーコードはEDI-04-00033です。今後の対策として、スキーマのバージョン管理を徹底する必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00033', 'INC-2020-00033', '調査の結果、連携JSONのスキーマの不一致が発生したことが確認されました。この問題は、定例リリースの際にスキーマバージョンが適切に同期されていなかったことによるものです。今後、スキーマの変更があった際には、必ずバージョン管理を行い、事前に確認するプロセスを導入することが重要です。これにより、再発防止に努める必要があります。', '調査の結果、連携JSONのスキーマの不一致が発生したことが確認されました。この問題は、定例リリースの際にスキーマバージョンが適切に同期されていなかったことによるものです。今後、スキーマの変更があった際には、必ずバージョン管理を行い、事前に確認するプロセスを導入することが重要です。これにより、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-09T03:58:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00047', 'INC-2020-00033', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-08T04:13:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T05:13:49+09:00', '初期対応', '発生直後の対応として、顧客店舗POSの連携設定を確認しました。スキーマの不一致を特定し、修正を行った後、再度バッチ処理を実施しました。処理は正常に完了し、その後の監視体制を強化するための計画を立てています。この初期対応により、影響を最小限に抑えることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00048', 'INC-2020-00033', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-08T05:43:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T06:43:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00034', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-11T00:19:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T00:49:36+09:00', '【障害報告】【性能・負荷障害】CDNエッジミス', '2023-10-15T10:30:00+09:00に発生した事象について報告します。本事象では、CDNエッジで古い静的資産が配信され、サービス全体の一部機能に影響を及ぼしました。推定原因は、CDNキャッシュ無効化の未実施であり、定例リリース直後に発生しています。特に、Venus Azure AP（DRサイト）およびCDNエッジにおいて問題が顕在化しました。運用部の運用 一郎が検知し、影響範囲を把握しました。今後は、リリース前のCDNキャッシュ無効化を徹底することが求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00034', 'INC-2020-00034', 'インシデント発生後の調査において、CDNキャッシュ無効化が実施されていないことが確認されました。定例リリースに伴う障害が生じ、その結果、古い静的資産が配信される事象が発生しました。この障害により、ユーザーへの影響があったことを重く受け止めています。原因の根本的な分析と、再発防止策の策定が急務です。', 'インシデント発生後の調査において、CDNキャッシュ無効化が実施されていないことが確認されました。定例リリースに伴う障害が生じ、その結果、古い静的資産が配信される事象が発生しました。この障害により、ユーザーへの影響があったことを重く受け止めています。原因の根本的な分析と、再発防止策の策定が急務です。', TIMESTAMP WITH TIME ZONE '2020-04-12T00:49:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00049', 'INC-2020-00034', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T01:04:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T02:04:36+09:00', '【初期対応】【性能・負荷障害】CDNエッジミス', '2023-10-15T10:35:00+09:00に運用部の運用 一郎が初期対応を開始しました。CDNキャッシュ無効化の手続きが未実施であったことを確認し、速やかにキャッシュの無効化を実施しました。また、影響を受けたユーザーには情報提供を行い、問題の解決に向けて尽力しました。引き続き、事象の再発防止策を検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00040', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-11T14:07:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T14:37:43+09:00', '【障害報告】【性能・負荷障害】コネクションプール枯渇', '2020年4月11日14:07:43に株式会社ストッククラウドのMercuryサービスにおいて、DBコネクションプール枯渇アラートが発報しました。これは、キャンペーンによるアクセス急増が発生契機であり、全テナントに波及する影響を及ぼしました。影響を受けたコンポーネントはVenus Azure AP（ゾーンA）の接続プールで、コネクションプールサイズ不足が推定される原因です。この状況は、利用者が増加したことによる応答遅延として分類され、重大度はMEDIUMです。エラーコードはPRF-03-00040で、この問題は検知まで27分を要しました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00040', 'INC-2020-00040', '問題発生直後から、DBコネクションプール枯渇の影響を受けた状況を調査しました。調査の結果、キャンペーンによるアクセス急増が原因でコネクションプールサイズ不足が確認されました。この状況を受けて、今後のアクセス急増に対応するための対策を講じる必要があります。', '問題発生直後から、DBコネクションプール枯渇の影響を受けた状況を調査しました。調査の結果、キャンペーンによるアクセス急増が原因でコネクションプールサイズ不足が確認されました。この状況を受けて、今後のアクセス急増に対応するための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-12T14:37:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00057', 'INC-2020-00040', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T14:52:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T15:52:43+09:00', '【初期対応】【性能・負荷障害】コネクションプール枯渇への初期対応', '初期対応として、DBのコネクションプールサイズを一時的に増加させ、状況の回復を図りました。また、該当するキャンペーンの影響範囲を分析し、必要に応じてアクセス制御を行う方針としました。運用チームは、これらの対応を迅速に行い、サービスの安定化を目指しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00041', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-19T18:03:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T18:18:35+09:00', '【障害報告】【運用操作・権限障害】監査ログ出力停止', '・発生日時: 2023-10-01T10:15:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00041', 'INC-2020-00041', '本件について調査を実施した結果、監査ログの外部出力が停止していることが確認された。原因としては、ログシッパーの認証トークンの期限切れが推定される。ログシッパーは、監査ログを外部に出力する役割を担っているため、その機能に影響を与えていると考えられる。今後の対応として、認証トークンの更新が必要である。', '本件について調査を実施した結果、監査ログの外部出力が停止していることが確認された。原因としては、ログシッパーの認証トークンの期限切れが推定される。ログシッパーは、監査ログを外部に出力する役割を担っているため、その機能に影響を与えていると考えられる。今後の対応として、認証トークンの更新が必要である。', TIMESTAMP WITH TIME ZONE '2020-04-20T18:18:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00058', 'INC-2020-00041', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T18:33:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T19:33:35+09:00', '【初期対応】【運用操作・権限障害】監査ログ出力停止', '本件に関して、初期対応として運用部でログシッパーの認証トークンの状態を確認し、必要に応じて更新作業を実施することを決定した。また、監査ログの外部出力が再開されるまでの間、影響範囲についての報告を定期的に行うこととする。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00043', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-30T14:55:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T15:25:58+09:00', '【障害報告】【CLU-06】オートスケール遅延', '2020年4月30日14時55分58秒、株式会社ストッククラウドのMercuryサービスにおいて、オートスケールが間に合わず応答劣化が発生しました。発生契機は大規模セールの開始直前で、影響範囲は全テナントに波及しました。これは、Venus Azure AP上のAPサーバークラスタに影響を与え、応答遅延を招きました。検知は15時32分58秒であり、約37分間この問題が未解決のままでした。推定原因としては、スケールアウト閾値の設定遅延が考えられ、これがオートスケール機能の効果的な利用を妨げました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00043', 'INC-2020-00043', '調査の結果、オートスケール機能が遅延した主な原因は、スケールアウト閾値の設定遅延であることが確認されました。この設定が適切に行われていなかったため、大規模なトラフィックが発生した際にシステムが適切に応答できず、結果として全テナントに影響を及ぼしました。この問題は運用部の運用 一郎によって発見され、即座に対応が必要とされる事象でした。', '調査の結果、オートスケール機能が遅延した主な原因は、スケールアウト閾値の設定遅延であることが確認されました。この設定が適切に行われていなかったため、大規模なトラフィックが発生した際にシステムが適切に応答できず、結果として全テナントに影響を及ぼしました。この問題は運用部の運用 一郎によって発見され、即座に対応が必要とされる事象でした。', TIMESTAMP WITH TIME ZONE '2020-05-01T15:25:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00060', 'INC-2020-00043', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-30T15:40:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T16:40:58+09:00', '【初期対応】【CLU-06】オートスケール遅延', 'オートスケール機能の遅延に対して、運用部は迅速に対応しました。まず、オートスケールの設定を見直し、スケールアウト閾値の調整を行いました。また、APサーバークラスタのパフォーマンスを監視し、必要に応じてリソースを追加しました。これにより、応答性能の回復を図り、顧客への影響を最小限に抑えることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00044', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-22T00:48:01+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T01:18:01+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2020年4月22日00:48に、株式会社ストッククラウドのサービスMercuryにおいて、同一アラートが短時間に数百件発報するアラート疲労が発生しました。この事象は、運用部門において検知され、01:13に運用部 一郎が確認。発生の契機は、大規模セール開始直前であり、原因としてアラート抑制ルールの未設定が疑われます。影響を受けたコンポーネントはVenus Azure AP（ゾーンB）およびアラートマネージャです。アラート疲労により、運用部門の対応が困難となり、正常な監視・可用性に影響を与えました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00044', 'INC-2020-00044', 'アラート疲労の発生に関する調査を行い、発報の原因としてアラート抑制ルールの未設定が確認されました。大規模セール開始直前という特殊な状況により、監視対象の負荷が急増し、同一アラートが数百件連続して発報される事態が発生しました。運用部門はこの影響を受け、適切な対応が難しい状況に陥りました。対策として、アラート抑制ルールの設定が急務です。', 'アラート疲労の発生に関する調査を行い、発報の原因としてアラート抑制ルールの未設定が確認されました。大規模セール開始直前という特殊な状況により、監視対象の負荷が急増し、同一アラートが数百件連続して発報される事態が発生しました。運用部門はこの影響を受け、適切な対応が難しい状況に陥りました。対策として、アラート抑制ルールの設定が急務です。', TIMESTAMP WITH TIME ZONE '2020-04-23T01:18:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00061', 'INC-2020-00044', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T01:33:01+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T02:33:01+09:00', '【初動対応】【監視・可用性障害】アラート疲労', '初動対応として、発報されたアラートの確認を行い、運用部門における負荷を軽減するための対策を検討しました。まず、アラート抑制ルールの設定を急ぎ行う必要があることが明らかとなり、運用部 一郎が中心となって取り組むことを決定しました。また、発報の根本原因を解明し、再発防止策を講じるために、関係者との連携を強化していきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00062', 'INC-2020-00044', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T03:03:01+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T04:03:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00045', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-05-23T08:12:59+09:00', TIMESTAMP WITH TIME ZONE '2020-05-23T10:12:59+09:00', '【障害報告】【棚卸・POS突合障害】移動平均単価異常', '株式会社ストッククラウドのMercuryサービスにおいて、2023-10-01T08:12:59+09:00に架空食品店Aの顧客店舗POSにおいて棚卸突合失敗の事象が発生しました。棚卸後の評価単価が想定外の値になる症状が確認され、重大度はLOWに設定されます。この問題は2023-10-01T10:55:59+09:00に検知され、163分後のことでした。発生契機は定例リリース直後であり、移動平均計算式の適用期間誤りが推定原因とされています。影響範囲はサービス全体の一部機能に及んでいます。エラーコードはINV-07-00045です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00045', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00045', 'INC-2020-00045', '今回の移動平均単価異常の問題に関して、定例リリース直後に棚卸後の評価単価が想定外の値になったことが確認されました。技術詳細として、移動平均計算式の適用期間に誤りがあったことが疑われます。これにより、顧客店舗POSや在庫評価エンジンの機能が影響を受けました。問題の根本的な原因を特定し、今後の再発防止策を講じることが必要です。', '今回の移動平均単価異常の問題に関して、定例リリース直後に棚卸後の評価単価が想定外の値になったことが確認されました。技術詳細として、移動平均計算式の適用期間に誤りがあったことが疑われます。これにより、顧客店舗POSや在庫評価エンジンの機能が影響を受けました。問題の根本的な原因を特定し、今後の再発防止策を講じることが必要です。', TIMESTAMP WITH TIME ZONE '2020-05-24T10:12:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00063', 'INC-2020-00045', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-05-23T10:27:59+09:00', TIMESTAMP WITH TIME ZONE '2020-05-23T11:27:59+09:00', '【初期対応】【棚卸・POS突合障害】移動平均単価異常の初期対応', '初期対応として、該当する顧客店舗POSの評価単価の計算式を見直し、移動平均の適用期間を確認しました。該当顧客には本件についての情報提供を行い、問題の影響を最小限に抑えるための指示を出しました。また、技術チームに対して直ちに調査を依頼し、原因究明に向けての作業を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00049', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-13T08:13:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T10:13:21+09:00', '【障害報告】【CLU-07】冪等キー重複', '2023-10-10T10:00:00+09:00 に発生した棚卸突合失敗について報告します。発生時の症状は冪等キー重複により在庫更新がスキップされました。この問題は株式会社ストッククラウドの顧客店舗POSにおいて確認され、同一顧客の全店舗に影響を及ぼす可能性があります。発見者は営業部の花子であり、発生契機は定例リリース直後です。エラーコードは EDI-08-00049 です。技術的な詳細としては、定例リリース直後に冪等キー重複により在庫更新がスキップされたことが確認され、冪等キー生成ロジックの衝突が原因と推測されます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00049', 'INC-2020-00049', '冪等キー重複に関する調査を行いました。調査の結果、定例リリース直後に発生したことを確認しました。また、冪等キー生成ロジックの衝突が問題の根本的な原因であると考えられます。API連携・EDI障害の観点から、全店舗の在庫更新に影響を及ぼすことが判明しました。今後の対策として、冪等キー生成ロジックの見直しを計画しています。', '冪等キー重複に関する調査を行いました。調査の結果、定例リリース直後に発生したことを確認しました。また、冪等キー生成ロジックの衝突が問題の根本的な原因であると考えられます。API連携・EDI障害の観点から、全店舗の在庫更新に影響を及ぼすことが判明しました。今後の対策として、冪等キー生成ロジックの見直しを計画しています。', TIMESTAMP WITH TIME ZONE '2020-04-14T10:13:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00069', 'INC-2020-00049', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-13T10:28:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T11:28:21+09:00', '【初期対応】【CLU-07】冪等キー重複への初期対応', 'このインシデントに対する初期対応を実施しました。まず、冪等キー重複問題が発生した顧客店舗POSの状況を確認し、影響を受けた店舗に連絡を行いました。次に、API連携・EDIに関するログを収集し、問題の詳細を分析しました。迅速な対応を行うことで、さらなる在庫更新のスキップを防ぐことを目指しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00051', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-17T15:58:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T16:43:15+09:00', '【障害報告】【CLU-10】合成監視失敗', '・発生日時: 2023-09-12T10:05:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00051', 'INC-2020-00051', '調査の結果、合成監視が特定ステップで失敗した原因として、テストデータの期限切れが主な要因であることが判明しました。監視・可用性障害が発生していることにより、サービス全体に影響を及ぼしています。現在、早急にテストデータを更新し、再度合成監視を実施する必要があります。', '調査の結果、合成監視が特定ステップで失敗した原因として、テストデータの期限切れが主な要因であることが判明しました。監視・可用性障害が発生していることにより、サービス全体に影響を及ぼしています。現在、早急にテストデータを更新し、再度合成監視を実施する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-18T16:43:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00072', 'INC-2020-00051', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T16:58:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T17:58:15+09:00', '【初期対応】【CLU-10】合成監視失敗', '初期対応として、運用部の担当者が合成監視の結果を確認しました。合成監視が特定ステップで失敗していることを確認し、テストデータの期限切れが原因であることを記録しました。さらに、定例リリースに関連するエラーコードMON-08-00051を記録し、影響範囲の特定を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00073', 'INC-2020-00051', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T18:28:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T19:28:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00053', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-03T07:47:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T08:47:09+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2020年4月3日07時47分に、株式会社ストッククラウドの顧客拠点NWにおいて、DNS解決成功後にTLS握手で接続切断が発生しました。発見者は営業部の花子で、影響を受けたのは同一顧客の全店舗です。発生契機はインフラメンテナンス明けであり、推定原因としてプロキシ証明書の期限切れが疑われます。エラーコードはNW-03-00053で、検知は09時09分に行われました。技術詳細としては、インフラメンテナンス明けにDNS解決成功後にTLS握手で接続切断が確認され、顧客ネットワークに重大な影響を及ぼしました。このインシデントから、プロキシ証明書の更新管理の重要性を再認識する必要があります。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00053', 'INC-2020-00053', '今回の障害に関する調査では、発生した症状はDNS解決成功後にTLS握手が切断されたことです。この問題は、発生契機がインフラメンテナンス明けであることから、プロキシ証明書の期限切れが直接的な原因と考えられます。技術的な調査を通じて、TLS握手の過程でエラーが発生し、顧客ネットワーク全体に影響を及ぼしたことが確認されました。今後は、証明書の管理と更新に関するプロセスを見直し、再発防止に努めます。', '今回の障害に関する調査では、発生した症状はDNS解決成功後にTLS握手が切断されたことです。この問題は、発生契機がインフラメンテナンス明けであることから、プロキシ証明書の期限切れが直接的な原因と考えられます。技術的な調査を通じて、TLS握手の過程でエラーが発生し、顧客ネットワーク全体に影響を及ぼしたことが確認されました。今後は、証明書の管理と更新に関するプロセスを見直し、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2020-04-04T08:47:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00075', 'INC-2020-00053', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T09:02:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T10:02:09+09:00', '【対応ログ】【顧客ネットワーク障害】TLS握手切断', '2020年4月3日07時47分に発生したTLS握手切断に関する初動対応を行いました。営業部の花子がインシデントを把握し、技術部門と連携の上、即座に調査を開始しました。顧客への影響が大きいため、優先的に対応を進めることとし、プロキシ証明書の期限確認を指示しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00076', 'INC-2020-00053', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T10:32:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T11:32:09+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00055', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-16T21:03:48+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T21:33:48+09:00', '【障害報告】【監視・可用性障害】SLO燃焼率警告', '2023-10-11T14:00:00+09:00に発生した事象について報告します。SLO燃焼率が閾値超過でエラーバジェット警告が出ました。全テナントに影響が及び、特にVenus Azure APにおいて顕著に現れました。原因として、SLO計算ウィンドウの設定誤りが考えられます。大規模セール開始直前のため、利用者の増加により負荷が集中したことも影響していると思われます。今回の障害により、システムの監視・可用性に問題が生じました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00055', 'INC-2020-00055', '障害発生後、運用部の運用 一郎が迅速に調査を開始しました。SLO燃焼率の推移を確認したところ、設定誤りが原因で誤った数値が表示されていたことが確認されました。また、全テナントに対する影響も大きく、特にピーク時の負荷が問題を助長していたことが判明しました。今後、SLO計算ウィンドウの設定見直しと負荷分散の最適化が必要です。', '障害発生後、運用部の運用 一郎が迅速に調査を開始しました。SLO燃焼率の推移を確認したところ、設定誤りが原因で誤った数値が表示されていたことが確認されました。また、全テナントに対する影響も大きく、特にピーク時の負荷が問題を助長していたことが判明しました。今後、SLO計算ウィンドウの設定見直しと負荷分散の最適化が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-17T21:33:48+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00078', 'INC-2020-00055', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T21:48:48+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T22:48:48+09:00', '初期対応', '2023-10-11T14:00:00+09:00に顧客からの問い合わせがあり、運用 一郎が対応を開始しました。SLO燃焼率の異常を確認し、エラーバジェット警告の原因を調査しました。全テナントに影響が出ていることを考慮し、迅速に修正作業を進めました。顧客への情報提供も行い、状況を逐次報告しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00079', 'INC-2020-00055', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T23:18:48+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T00:18:48+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00057', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-21T04:15:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T04:45:12+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2023-10-10T04:15:12+09:00、株式会社ストッククラウドのMercuryにおいて、夜間整合性チェックで不一致アラートが多発しました。発生契機は月末棚卸の開始時であり、整合性チェック基準の変更が未反映であることが推定されます。影響範囲はバッチ処理のみで、オンラインには影響がありません。エラーコードはSYNC-06-00057です。検知は2023-10-10T04:39:12+09:00に行われ、24分後に問題が検知されました。影響コンポーネントにはMercury AWS AP（DRサイト）および整合性チェックジョブが含まれます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00057', 'INC-2020-00057', '調査を進めた結果、月末棚卸の開始時に実施される夜間整合性チェックで不一致アラートが多発していることが確認されました。整合性チェック基準の変更が適切に反映されておらず、これが原因で不一致が発生していると考えられます。追加の検証が必要です。', '調査を進めた結果、月末棚卸の開始時に実施される夜間整合性チェックで不一致アラートが多発していることが確認されました。整合性チェック基準の変更が適切に反映されておらず、これが原因で不一致が発生していると考えられます。追加の検証が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-22T04:45:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00081', 'INC-2020-00057', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T05:00:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T06:00:12+09:00', '初動対応', '運用部の運用 一郎が初動対応にあたり、整合性チェックの設定を確認しました。整合性チェック基準の変更が未反映であることを特定し、速やかに修正作業を開始しました。影響を受けたデータの確認と修正を行い、夜間整合性チェックの再実行を計画しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00061', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-09T18:53:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T19:53:54+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2023-10-01T14:30:00+09:00に、株式会社ストッククラウドのMercuryサービスにおいて顧客側ネットワーク障害が発生しました。本障害はDNS解決成功後にTLS握手で接続切断が発生し、同一顧客の全店舗に影響を及ぼしました。発生契機はインフラメンテナンス明けで、推定原因としてプロキシ証明書の期限切れが考えられます。影響を受けたコンポーネントは顧客拠点NW（ゾーンB）およびTLS終端です。エラーコードはNW-03-00061です。この障害は2023-10-01T15:00:00+09:00に検知され、営業部の花子が問題を発見しました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00061', 'INC-2020-00061', '調査の結果、TLS接続の切断はプロキシ証明書の期限切れが原因であることが確認されました。DNS解決後に接続が行われたものの、証明書が無効であったため、TLS握手が正常に完了せず、接続が切断されました。今後は証明書の管理を徹底し、定期的に更新を行うことで同様の問題を未然に防ぐ必要があります。', '調査の結果、TLS接続の切断はプロキシ証明書の期限切れが原因であることが確認されました。DNS解決後に接続が行われたものの、証明書が無効であったため、TLS握手が正常に完了せず、接続が切断されました。今後は証明書の管理を徹底し、定期的に更新を行うことで同様の問題を未然に防ぐ必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-10T19:53:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00087', 'INC-2020-00061', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-09T20:08:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T21:08:54+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', '初期対応として、問題が発生した際に即座に通信状況を確認し、DNS解決やTLS設定を再確認しました。エラーコードNW-03-00061に基づき、プロキシ証明書の確認を行い、期限切れの証明書が原因であることを特定しました。迅速な対応により、顧客への影響を最小限に抑えることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00071', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-10T22:26:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T22:41:34+09:00', '【障害報告】【CLU-10】トレースサンプリング過少', '2023-10-10T15:00:00+09:00に、株式会社ストッククラウドのサービスMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。発生時刻は2023-10-10T15:00:00+09:00で、運用コンソールにおいて分散トレースのサンプリング率が過少となり、原因特定が困難な状況が発生しました。障害は運用部門に影響を及ぼし、定例リリース直後に発生したことが契機となります。エラーコードはMON-05-00071です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00071', 'INC-2020-00071', 'この障害に関する調査の結果、定例リリース直後に分散トレースのサンプリング率が過少となり、原因特定が困難であることが確認されました。推定原因として、サンプリング率の本番設定誤りが考えられています。運用部門のみが影響を受けたことを考慮すると、リリース時の設定確認が不足していたことが要因である可能性が高いと判断されます。', 'この障害に関する調査の結果、定例リリース直後に分散トレースのサンプリング率が過少となり、原因特定が困難であることが確認されました。推定原因として、サンプリング率の本番設定誤りが考えられています。運用部門のみが影響を受けたことを考慮すると、リリース時の設定確認が不足していたことが要因である可能性が高いと判断されます。', TIMESTAMP WITH TIME ZONE '2020-04-11T22:41:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00101', 'INC-2020-00071', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T22:56:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T23:56:34+09:00', '【初動対応】【CLU-10】トレースサンプリング過少', '運用部の運用 一郎がこの障害に対して初動対応を行い、運用コンソールの設定を確認しました。設定ミスが確認され、修正が実施されました。また、今後の再発防止策として、リリース後の設定確認プロセスを強化することを提案しています。運用部門と連携し、監視・可用性障害の影響を最小限に抑えるための対策を講じていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00102', 'INC-2020-00071', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T00:26:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T01:26:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00076', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-28T21:27:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T21:57:25+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2023-10-10T15:30:00+09:00に発生した、株式会社ストッククラウドのMercuryにおけるマスター設定ミスによる在庫登録失敗の事象について報告いたします。OAuthトークン失効によりPOS連携が中断されました。発生は年末年始の稼働切替時であり、単一店舗に影響を及ぼしました。エラーコードはEDI-05-00076で、Mercury AWS AP（ゾーンA）およびPOS連携ハブが影響を受けています。リフレッシュトークン保存先の障害が原因と考えられています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00076', 'INC-2020-00076', '本事象の調査において、年末年始の稼働切替時にOAuthトークンが失効し、POS連携が中断されたことが確認されました。リフレッシュトークン保存先の障害が推定されており、これが主たる原因と考えられています。今後、リフレッシュトークンの保存先の見直しや、定期的な監視体制の強化が求められます。', '本事象の調査において、年末年始の稼働切替時にOAuthトークンが失効し、POS連携が中断されたことが確認されました。リフレッシュトークン保存先の障害が推定されており、これが主たる原因と考えられています。今後、リフレッシュトークンの保存先の見直しや、定期的な監視体制の強化が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-29T21:57:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00110', 'INC-2020-00076', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T22:12:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T23:12:25+09:00', '【初期対応】【CLU-07】OAuthトークン失効', '本件に関し、初期対応としてMercuryシステムのトークン管理設定を確認し、リフレッシュトークンの保存先に異常がないかを調査いたします。また、該当店舗への影響を最小限に抑えるため、迅速にトークンの再発行を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00087', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-22T06:31:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T07:01:17+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2023-10-01T14:45:00+09:00、株式会社ストッククラウドのMercuryサービスにおいて、ヘルスチェック過多によりAPサーバーへの負荷が増加しました。発見者は運用部の運用 一郎で、発生したのはインフラメンテナンス明けです。全テナントに影響が及び、特にVenus Azure AP（Secondary）とロードバランサに負荷が集中しました。エラーコードはMON-06-00087であり、LBヘルスチェック間隔の過短設定が推定される原因です。今後の対応が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00087', 'INC-2020-00087', '今回のインシデントに関して、運用部の運用 一郎は、ヘルスチェックの過負荷がAPサーバーに影響を与えていると報告しています。インフラメンテナンス明けにLBヘルスチェック間隔が短く設定されていることが原因で、全テナントに波及する過負荷が発生しました。現状の設定を見直し、適切な間隔に調整する必要があります。', '今回のインシデントに関して、運用部の運用 一郎は、ヘルスチェックの過負荷がAPサーバーに影響を与えていると報告しています。インフラメンテナンス明けにLBヘルスチェック間隔が短く設定されていることが原因で、全テナントに波及する過負荷が発生しました。現状の設定を見直し、適切な間隔に調整する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-23T07:01:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00128', 'INC-2020-00087', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T07:16:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T08:16:17+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷確認', '運用 一郎が2023-10-01T14:50:00+09:00に初期対応として、ヘルスチェックの設定を確認しました。設定が過短であることを確認し、運用部として修正を進める方針です。全テナントの監視を強化し、再発防止策を講じる必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00092', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-26T14:55:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T15:55:13+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2020年4月26日14時55分、株式会社ストッククラウドの顧客拠点NWにおいて、DNS解決成功後にTLS握手で接続が切断されるという顧客側ネットワーク障害が発生しました。この問題は、インフラメンテナンス明けに起きたもので、影響範囲は同一顧客の全店舗に及びました。発見者は営業部の花子で、発見がなされてから約50分後の15時45分にこの問題が検知されました。技術的な詳細としては、プロキシ証明書の期限切れが原因であると推定されます。この障害は、顧客ネットワークにおいてTLSの握手段階での接続切断が発生したため、顧客のサービス利用に大きな影響を及ぼしました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00092', 'INC-2020-00092', '調査の結果、顧客拠点NWにおいてTLS握手が切断される原因は、やはりプロキシ証明書の期限切れであることが確認されました。インフラメンテナンス明けにおいて、DNS解決は成功していたものの、TLSの握手段階で切断が発生したため、顧客ネットワークにおける証明書の管理が求められます。この状況を踏まえ、今後は証明書の更新を自動化する仕組みの導入が望まれます。', '調査の結果、顧客拠点NWにおいてTLS握手が切断される原因は、やはりプロキシ証明書の期限切れであることが確認されました。インフラメンテナンス明けにおいて、DNS解決は成功していたものの、TLSの握手段階で切断が発生したため、顧客ネットワークにおける証明書の管理が求められます。この状況を踏まえ、今後は証明書の更新を自動化する仕組みの導入が望まれます。', TIMESTAMP WITH TIME ZONE '2020-04-27T15:55:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00135', 'INC-2020-00092', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T16:10:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T17:10:13+09:00', '初期対応', '初期対応として、発見直後に顧客に連絡を取り、状況を説明しました。また、社内チームで直ちに調査を開始し、プロキシ証明書の状況を確認しました。その結果、証明書の期限切れが原因であることが判明し、迅速に更新手続きを行いました。顧客には影響を最小限に抑えるための解決策を提示し、サービスの再開を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00136', 'INC-2020-00092', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T17:40:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T18:40:13+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00094', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-07-13T07:31:24+09:00', TIMESTAMP WITH TIME ZONE '2020-07-13T08:01:24+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '2020年7月13日07時31分24秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aでの在庫登録に失敗する事象が発生しました。症状として、楽観ロック競合が多発し更新失敗率が上昇しました。この事象は大規模セール開始直前に発生しており、全テナントに波及する影響がありました。原因が疑われるのは、バージョンカラム更新ロジックの不備です。エラーコードはSYNC-10-00094です。この問題は、Mercury AWS AP（Secondary）の在庫登録APIにおいて発生しました。運用部の運用 一郎により発見され、07時56分24秒に検知されました。検知までに25分を要しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00094', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00094', 'INC-2020-00094', 'この事象の調査において、大規模セールの開始直前における楽観ロック競合が多発した理由として、バージョンカラム更新ロジックの不備が考えられます。更新失敗の原因を特定するため、関連するログを分析し、同じ時期にどのようなリクエストが発生していたのかを調査しました。この結果、特定の条件下で更新処理が正しく行われなかったことが明らかになりました。今後、このような問題が再発しないよう、ロジックの見直しとテストを', 'この事象の調査において、大規模セールの開始直前における楽観ロック競合が多発した理由として、バージョンカラム更新ロジックの不備が考えられます。更新失敗の原因を特定するため、関連するログを分析し、同じ時期にどのようなリクエストが発生していたのかを調査しました。この結果、特定の条件下で更新処理が正しく行われなかったことが明らかになりました。今後、このような問題が再発しないよう、ロジックの見直しとテストを実施する必要があります。', TIMESTAMP WITH TIME ZONE '2020-07-14T08:01:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00138', 'INC-2020-00094', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-13T08:16:24+09:00', TIMESTAMP WITH TIME ZONE '2020-07-13T09:16:24+09:00', '【初期対応】【CLU-09】楽観ロック競合多発', '当事象発生後、運用部の運用 一郎が迅速に状況を確認し、エラーの発生源を特定するためにログの精査を開始しました。初期対応として、競合の状況を軽減するための暫定措置を講じ、影響を受けた顧客への通知を行い、必要に応じて手動での在庫登録作業を支援しました。また、技術チームに対して原因分析を依頼し、同時に再発防止策の検討を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00139', 'INC-2020-00094', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-13T09:46:24+09:00', TIMESTAMP WITH TIME ZONE '2020-07-13T10:46:24+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00097', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-09T07:03:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T07:18:15+09:00', '【障害報告】【運用操作・権限障害】夜間バッチ手動停止', '2020年04月09日07時03分、株式会社ストッククラウドの運用部において、運用 一郎が運用コンソールで夜間バッチを手動停止したが、その後の再起動を忘れてしまいました。この事象は2020年04月09日07時22分に検知され、19分間の障害時間が発生しました。影響範囲はバッチ処理のみで、オンラインには影響がありませんでした。年末年始の稼働切替時に運用手順書の再起動ステップが省略されていたことが原因と考えられます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00097', 'INC-2020-00097', '運用 一郎が手動で夜間バッチを停止した後に、再起動を実施しなかったことが問題の発端です。運用手順書に再起動ステップが記載されていないことから、今後同様の事象を防ぐために、手順書の見直しが必要です。また、スケジューラの動作確認も含めた運用マニュアルの整備が求められます。', '運用 一郎が手動で夜間バッチを停止した後に、再起動を実施しなかったことが問題の発端です。運用手順書に再起動ステップが記載されていないことから、今後同様の事象を防ぐために、手順書の見直しが必要です。また、スケジューラの動作確認も含めた運用マニュアルの整備が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-10T07:18:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00143', 'INC-2020-00097', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T07:33:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T08:33:15+09:00', '【初回対応】【運用操作・権限障害】夜間バッチ手動停止', '運用 一郎が実施した夜間バッチの手動停止に関して、再起動の忘れがあったため、ただちに運用コンソールからバッチ処理を再起動しました。手動停止の手順を見直し、次回以降は手順書に従い、必ず再起動を行うよう再確認します。運用部全体への注意喚起も行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00099', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-10T16:04:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T16:19:16+09:00', '【障害報告】【認証・セッション障害】パスワードポリシー衝突', '2020年4月10日16時04分16秒、株式会社ストッククラウドのサービスMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。具体的には、運用コンソールにおいて新パスワードポリシーが適用されたことにより、既存APIの認証が失敗しました。この障害は定例リリース直後に発生し、全テナントに波及する重大な影響を及ぼしました。エラーコードはAUTH-05-00099であり、運用部の運用 一郎が発見しました。発見から13分後の16時17分16秒に障害が検知されました。技術的には、レガシー認証方式の残存が原因として疑われます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00099', 'INC-2020-00099', '本インシデントに関する調査を実施したところ、定例リリース直後に新パスワードポリシーが適用されたことが確認されました。これにより、既存APIの認証が失敗し、全テナントに影響を及ぼす事態となりました。さらに、レガシー認証方式が残存していたことも原因として特定されました。今後の対策として、認証方式の見直しが必要です。', '本インシデントに関する調査を実施したところ、定例リリース直後に新パスワードポリシーが適用されたことが確認されました。これにより、既存APIの認証が失敗し、全テナントに影響を及ぼす事態となりました。さらに、レガシー認証方式が残存していたことも原因として特定されました。今後の対策として、認証方式の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2020-04-11T16:19:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00145', 'INC-2020-00099', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T16:34:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T17:34:16+09:00', '【初期対応】【認証・セッション障害】パスワードポリシー衝突', 'インシデント発生直後に初期対応を行い、運用コンソールに対する一時的なアクセス制限を実施しました。また、影響を受けたテナントに対しては速やかに通知を行い、問題の調査を進めました。エラーコードAUTH-05-00099に関連する問題が確認されたため、迅速に情報共有を行いながら、再発防止策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00101', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-13T01:35:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T02:05:51+09:00', '【障害報告】【認証・セッション障害】SSOリダイレクトループ', '2023年10月15日、株式会社ストッククラウドのMercuryサービスにおいて、SSOログインでリダイレクトループが発生しました。影響範囲は全テナントに波及し、利用者増による応答遅延が確認されました。本事象は、定例リリース直後に発生し、原因としてSAMLメタデータのURL不一致が疑われます。エラーコードはAUTH-01-00101で、影響コンポーネントはVenus Azure AP（Primary）および認証サービスです。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00101', 'INC-2020-00101', '本インシデントは、2023年10月15日に確認されました。調査の結果、リダイレクトループの発生は定例リリースに起因するものであり、具体的にはSAMLメタデータのURL不一致が問題であることが判明しました。SSO機能に影響が出ているため、全テナントのお客様に影響が及んでいる状況です。', '本インシデントは、2023年10月15日に確認されました。調査の結果、リダイレクトループの発生は定例リリースに起因するものであり、具体的にはSAMLメタデータのURL不一致が問題であることが判明しました。SSO機能に影響が出ているため、全テナントのお客様に影響が及んでいる状況です。', TIMESTAMP WITH TIME ZONE '2020-04-14T02:05:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00147', 'INC-2020-00101', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T02:20:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T03:20:51+09:00', '初期対応', 'インシデントの発生を受けて、運用部の運用 一郎が直ちに初期対応を開始しました。まず、リダイレクトループの原因を特定するためにログの分析を実施し、SAMLメタデータのURL不一致に関する情報を収集しました。その後、影響を受けている全テナントに対する連絡を行い、状況を報告しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00102', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-07T11:07:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T11:37:32+09:00', '【障害報告】【在庫マスター設定障害】ロット管理初回入庫不可', '2023-10-15T10:15:00+09:00に発生した、株式会社ストッククラウドのMercuryにおける在庫マスター設定ミスによる在庫登録失敗について報告します。発生直後より、初回入庫処理でロット番号採番に失敗する事象が確認されました。この問題は、顧客オンボーディング当日に発生し、特定の単一店舗に影響を及ぼしました。ロット管理フラグの誤った有効化が推定原因とされており、商材の管理に支障をきたしています。エラーコードはMST-08-00102であり、影響を受けたコンポーネントはMercury AWS AP（ゾーンA）のロット管理サービスです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00102', 'INC-2020-00102', '本件に関しては、初回入庫処理においてロット番号の採番が行われない事象が発生したことを確認しています。調査の結果、ロット管理フラグの誤った有効化が原因と考えられており、これが影響範囲にあたる特定の単一店舗において、正しく在庫が登録されない要因となっています。詳細な技術分析が必要です。', '本件に関しては、初回入庫処理においてロット番号の採番が行われない事象が発生したことを確認しています。調査の結果、ロット管理フラグの誤った有効化が原因と考えられており、これが影響範囲にあたる特定の単一店舗において、正しく在庫が登録されない要因となっています。詳細な技術分析が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-08T11:37:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00148', 'INC-2020-00102', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T11:52:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T12:52:32+09:00', '【対応】【在庫マスター設定障害】ロット管理初回入庫不可', '初回入庫処理でロット番号採番に失敗した件に関し、運用部の運用 一郎が監視を行い、迅速な対応を実施しました。特定の店舗での問題を確認し、ロット管理フラグの設定を見直す必要があると判断しています。お客様には影響を最小限に抑えるため、状況を逐次報告し、問題解決に向けた取り組みを行っていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00149', 'INC-2020-00102', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T13:22:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T14:22:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00103', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-05T17:29:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T19:29:00+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2023-10-15T14:10:00+09:00に、株式会社ストッククラウドの顧客店舗POSにおいて、OAuthトークンの失効によるPOS連携の中断が発生しました。この事象は、2023-10-15T16:00:00+09:00に検知され、顧客名はABC商事、担当者は営業 太郎が対応しました。発生契機は年末年始の稼働切替時であり、影響範囲は単一店舗に限定されました。エラーコードはEDI-05-00103であり、顧客店舗POSとPOS連携ハブに影響しています。技術的に見て、リフレッシュトークンの保存先に障害が発生していることが疑われます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00103', 'INC-2020-00103', '調査の結果、OAuthトークンが失効した原因は、リフレッシュトークンの保存先に障害が発生したことによるものでした。この障害は年末年始の稼働切替時に発生し、POS連携が中断する結果となりました。現在、再発防止策を検討しています。', '調査の結果、OAuthトークンが失効した原因は、リフレッシュトークンの保存先に障害が発生したことによるものでした。この障害は年末年始の稼働切替時に発生し、POS連携が中断する結果となりました。現在、再発防止策を検討しています。', TIMESTAMP WITH TIME ZONE '2020-04-06T19:29:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00150', 'INC-2020-00103', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T19:44:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T20:44:00+09:00', '【初期対応】OAuthトークン失効', '営業 太郎が即座に顧客ABC商事に連絡を取り、状況を説明しました。また、技術チームに問題の調査を依頼し、迅速な復旧を目指しました。初期対応では、リフレッシュトークンの保存状況を確認し、必要に応じて手動でトークンを再発行する準備を進めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00151', 'INC-2020-00103', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T21:14:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T22:14:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00104', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-26T13:01:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T13:31:14+09:00', '【障害報告】【CLU-07】EDI在庫差分遅延', '2023-10-05T10:15:00+09:00 に、株式会社ストッククラウドのMercuryサービスにおいて、在庫登録に関するマスター設定ミスが発生しました。この事象により、EDI在庫差分ファイルの反映が2時間遅延しました。影響範囲は同一顧客の全店舗に及び、エラーコードはEDI-01-00104です。発生契機はデータ移行バッチ実行中であり、EDIキューの優先度設定誤りが推定原因とされています。影響を受けたコンポーネントはMercury AWS APおよびEDIアダプタです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00104', 'INC-2020-00104', '本事象に関する調査を行った結果、データ移行バッチ実行中にEDI在庫差分ファイルが反映される際、2時間の遅延が発生したことを確認しました。EDIキューの優先度設定に問題があり、そのためにファイルの処理が遅れたと考えられます。今後、この問題を解決するための対策が必要です。', '本事象に関する調査を行った結果、データ移行バッチ実行中にEDI在庫差分ファイルが反映される際、2時間の遅延が発生したことを確認しました。EDIキューの優先度設定に問題があり、そのためにファイルの処理が遅れたと考えられます。今後、この問題を解決するための対策が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-27T13:31:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00152', 'INC-2020-00104', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T13:46:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T14:46:14+09:00', '初動対応', '発生したインシデントに対して初動対応を実施しました。具体的には、運用部の運用 一郎が問題を確認し、EDI在庫差分ファイルの遅延を解消するため迅速な対応を行いました。関連する店舗への連絡を行い、影響を最小限に抑えることに努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00106', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-18T20:52:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T21:07:25+09:00', '【障害報告】【CLU-08】APIトークン早期失効', '2020年4月18日、株式会社ストッククラウドのMercuryサービスにおいて、運用者の作業ミスによるアクセス障害が発生しました。症状として、APIトークンが発行直後に失効扱いとなり、サービス全体の一部機能に影響を及ぼしました。発生契機はインフラメンテナンス明けであり、エラーコードはAUTH-04-00106です。運用コンソール（ゾーンB）やAPIゲートウェイに関連する技術詳細として、原因としてサーバー時刻のNTPずれが疑われています。本障害は検知までに12分を要しましたが、迅速な対応が求められる事態でした。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00106', 'INC-2020-00106', '本障害の調査を行った結果、インフラメンテナンス終了後に意図しない形でAPIトークンが発行され、すぐに失効する事象が確認されました。この事象は、サーバー時刻のNTPずれが原因である可能性が高いことが分かりました。NTPサーバーからの時刻取得が正しく行われなかったため、APIトークンが正しく認証されずに失効扱いとなったものと推測されます。', '本障害の調査を行った結果、インフラメンテナンス終了後に意図しない形でAPIトークンが発行され、すぐに失効する事象が確認されました。この事象は、サーバー時刻のNTPずれが原因である可能性が高いことが分かりました。NTPサーバーからの時刻取得が正しく行われなかったため、APIトークンが正しく認証されずに失効扱いとなったものと推測されます。', TIMESTAMP WITH TIME ZONE '2020-04-19T21:07:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00155', 'INC-2020-00106', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T21:22:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T22:22:25+09:00', '初期対応', '障害発生を受けて、直ちに運用チームが対応を開始しました。運用 一郎が中心となり、NTPサーバーの設定の確認と修正を行いました。また、必要な場合に備え、APIトークンの発行プロセスの見直しを行うことを決定しました。これにより、今後同様の障害が発生しないような対策を講じることが求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00108', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-23T06:28:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T08:28:19+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '2020年4月23日6時28分、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSでデータ移行バッチ実行中に同期メッセージがデッドレターに大量蓄積が発生しました。発見者は営業の花子で、検知は同日7時56分に行われ、検知まで88分かかりました。影響範囲はバッチ処理のみで、オンラインへの影響はないものと確認されています。推定原因として、デッドレター再処理ジョブの未設定が疑われています。今回はエラーコードSYNC-08-00108が関連しています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00108', 'INC-2020-00108', '調査の結果、データ移行バッチ実行中にメッセージキューで発生したデッドレターが原因であることが確認されました。具体的には、同期メッセージが大量にデッドレターに蓄積されており、これにより正常なデータ同期が妨げられました。再処理ジョブが未設定であったため、問題の悪化が疑われます。今後、バッチ処理の監視体制を強化する必要があります。', '調査の結果、データ移行バッチ実行中にメッセージキューで発生したデッドレターが原因であることが確認されました。具体的には、同期メッセージが大量にデッドレターに蓄積されており、これにより正常なデータ同期が妨げられました。再処理ジョブが未設定であったため、問題の悪化が疑われます。今後、バッチ処理の監視体制を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T08:28:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00157', 'INC-2020-00108', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T08:43:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T09:43:19+09:00', '【初期対応】【データ同期・整合性障害】デッドレター蓄積', '初期対応として、営業の花子が問題を報告し、エンジニアチームが関連ログを確認しました。データ移行バッチの実行状況とメッセージキューの状態を調査し、デッドレター再処理ジョブの設定を行う必要があると認識しました。さらに、顧客店舗POSの影響範囲を特定するための詳細な分析を行うこととなりました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00117', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-23T18:09:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T18:39:36+09:00', '【障害報告】【性能・負荷障害】コールドスタート連鎖', '2020年4月23日18時09分36秒、株式会社ストッククラウドのMercuryにおいて、サーバーレス関数のコールドスタートが連鎖する現象が発生しました。本事象は、定例リリース直後に発生し、サービス全体の一部機能に影響を及ぼしました。影響を受けたのはVenus Azure APおよびCDNエッジです。運用部の運用 一郎が発見し、18時55分36秒に検知されるまでに46分の時間がかかりました。この間に、コールドスタートの連鎖が引き起こされたと考えられます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00117', 'INC-2020-00117', '本事象の調査を行ったところ、定例リリース直後の処理負荷が急激に増加し、その結果としてサーバーレス関数のコールドスタートが複数回発生していることが判明しました。このコールドスタートの連鎖が、サービス全体の性能に悪影響を及ぼしたと考えられます。今後の対策として、リリース後のトラフィックの監視を強化し、負荷分散を見直す必要があります。', '本事象の調査を行ったところ、定例リリース直後の処理負荷が急激に増加し、その結果としてサーバーレス関数のコールドスタートが複数回発生していることが判明しました。このコールドスタートの連鎖が、サービス全体の性能に悪影響を及ぼしたと考えられます。今後の対策として、リリース後のトラフィックの監視を強化し、負荷分散を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T18:39:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00170', 'INC-2020-00117', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T18:54:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T19:54:36+09:00', '【初期対応】【性能・負荷障害】コールドスタート連鎖', '運用部の運用 一郎より、サーバーレス関数のコールドスタートが連鎖していることが報告されました。現在、定例リリース後の影響を受けていることが確認されており、早急に状況を把握し、必要な対策を講じる予定です。影響を最小限に抑えるため、迅速にトラフィックの調整を行うことを検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00120', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-09T17:44:56+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T18:14:56+09:00', '【障害報告】【CLU-09】読取レプリカ遅延', '2023-10-01T10:30:00+09:00、株式会社ストッククラウドのMercuryサービスにおいて、読取レプリカ遅延により在庫照会が古い値を返す事象が発生しました。特定リージョンのユーザーに影響があり、在庫情報の正確性が損なわれました。レプリケーション遅延の監視閾値を超過することが推定され、影響範囲が確認されています。大規模セール開始直前の時期において、この事象は特に深刻です。さらに、Mercury AWS AP（ゾーンA）での読取専用レプリカの問題が確認されており、早急な対応が求められています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00120', 'INC-2020-00120', '事故発生からの調査を進める中で、読取レプリカ遅延が確認され、在庫照会が古い値を返す原因としてレプリケーション遅延の監視閾値超過が疑われます。影響範囲は特定リージョンのユーザーのみとなっており、大規模セール開始直前の発生契機が影響していると考えられます。', '事故発生からの調査を進める中で、読取レプリカ遅延が確認され、在庫照会が古い値を返す原因としてレプリケーション遅延の監視閾値超過が疑われます。影響範囲は特定リージョンのユーザーのみとなっており、大規模セール開始直前の発生契機が影響していると考えられます。', TIMESTAMP WITH TIME ZONE '2020-04-10T18:14:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00174', 'INC-2020-00120', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T18:29:56+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T19:29:56+09:00', '【初期対応】【CLU-09】読取レプリカ遅延に関する初期対応', '初期対応として、運用部の運用 一郎がレプリケーション遅延の監視システムを確認し、即座に関係者に通知しました。影響を受けたユーザーへの情報提供を行い、在庫情報の正確性向上に向けて最優先で修正を進めています。再発防止策についても検討を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00175', 'INC-2020-00120', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T19:59:56+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T20:59:56+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00121', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-19T00:44:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T01:14:36+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2023-10-01T10:00:00+09:00 に株式会社ストッククラウドのMercuryサービスにおいて、バルクAPIが部分失敗しロールバックが未完了の事象が発生しました。発生時刻は2023-10-01T09:53:00+09:00で、検知が2023-10-01T09:59:00+09:00でした。エラーコードはEDI-10-00121で、データ移行バッチ実行中に発生したため、サービス全体の一部機能に影響を及ぼすこととなりました。発見者は運用部の運用 一郎であり、このバルクAPIの部分失敗に起因する問題により、在庫登録APIが影響を受けました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00121', 'INC-2020-00121', '調査の結果、バルクAPIが部分失敗しロールバックが未完了であったことが確認されました。推定原因として、部分成功時の補償トランザクションが欠如していたことが挙げられます。このため、データ移行バッチ実行中に発生した事象によって、API連携が正常に機能しなくなりました。今後は、補償トランザクションの実装を強化する必要があります。', '調査の結果、バルクAPIが部分失敗しロールバックが未完了であったことが確認されました。推定原因として、部分成功時の補償トランザクションが欠如していたことが挙げられます。このため、データ移行バッチ実行中に発生した事象によって、API連携が正常に機能しなくなりました。今後は、補償トランザクションの実装を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-20T01:14:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00176', 'INC-2020-00121', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T01:29:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T02:29:36+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗の初期対応', '初期対応として、運用 一郎がバルクAPIの部分失敗の事象を確認し、関連するデータを収集しました。すぐにシステムログを調査し、問題の特定に努めました。さらに、チーム内でのコミュニケーションを強化し、影響を受けた機能の復旧に向けた対策を協議しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00177', 'INC-2020-00121', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T02:59:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T03:59:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00125', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-16T15:45:01+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T16:15:01+09:00', '【障害報告】【性能・負荷障害】照会API p99超過', '2020年4月16日15時45分頃、株式会社ストッククラウドのMercuryサービスにおいて、在庫照会APIのp99レイテンシが閾値を超過しました。影響範囲は特定リージョンのユーザーのみで、エラーコードはPRF-02-00125です。本件は大規模セール開始直前の事象であり、N+1クエリの混入が推定原因とされています。運用部の運用 一郎が15時45分に発見し、16時03分に検知しました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00125', 'INC-2020-00125', '本件に関する調査を実施した結果、在庫照会APIのp99レイテンシが異常値を示しており、N+1クエリが混入している可能性が高いことが確認されました。大規模セール開始直前に発生したため、アクセス集中が原因となった可能性があります。今後の再発防止策として、クエリの最適化を検討する必要があります。', '本件に関する調査を実施した結果、在庫照会APIのp99レイテンシが異常値を示しており、N+1クエリが混入している可能性が高いことが確認されました。大規模セール開始直前に発生したため、アクセス集中が原因となった可能性があります。今後の再発防止策として、クエリの最適化を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-17T16:15:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00181', 'INC-2020-00125', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T16:30:01+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T17:30:01+09:00', '【初動対応】照会API p99超過', '初動対応として、運用部の運用 一郎が即座に在庫照会APIのレイテンシを監視し始めました。また、関連するログを収集し、N+1クエリの特定に向けた分析を開始しました。初期調査結果をもとに、エンジニアチームへも共有し、必要な対応策を協議するための会議を設定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00182', 'INC-2020-00125', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T18:00:01+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T19:00:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00127', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-10T09:05:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T09:35:30+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2023-10-15T10:00:00+09:00に発生した障害について報告します。顧客名は株式会社ストッククラウドで、運用担当者は山田 太郎です。大規模セール開始直前にパートナーAPIが429を返し、連携が停止しました。影響範囲はサービス全体の一部機能に及び、エラーコードはEDI-06-00127です。これにより、在庫情報の更新が行えず、取引に影響を及ぼしています。呼出頻度の事前調整不足が推定原因となっています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00127', 'INC-2020-00127', '本障害の調査を実施しました。発生契機として大規模セール開始直前が確認されました。調査の結果、パートナーAPIが429を返す原因は、呼出頻度の事前調整不足であると考えられます。これにより、Mercury AWS AP（ゾーンB）及びAPIゲートウェイにおいて連携が停止しました。今後の対策として、呼出頻度の調整を行う必要があります。', '本障害の調査を実施しました。発生契機として大規模セール開始直前が確認されました。調査の結果、パートナーAPIが429を返す原因は、呼出頻度の事前調整不足であると考えられます。これにより、Mercury AWS AP（ゾーンB）及びAPIゲートウェイにおいて連携が停止しました。今後の対策として、呼出頻度の調整を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T09:35:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00184', 'INC-2020-00127', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T09:50:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T10:50:30+09:00', '【初期対応】【API連携・EDI障害】レート超過429', '山田 太郎が初期対応を行いました。発生した429エラーについて、パートナーAPIとの通信状況を確認し、呼出頻度の調整を提案しました。また、社内関係者に通知し、影響範囲を確認するよう指示しました。今後は、調整が完了次第、再度API連携の状況を確認し、報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00132', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-19T08:24:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T08:54:41+09:00', '【障害報告】【性能・負荷障害】照会API p99超過', '2020年4月19日08時24分41秒、株式会社ストッククラウドのMercuryサービスにおいて、在庫照会APIのp99レイテンシが閾値を超過する障害が発生しました。これは大規模セール開始直前の影響で、特定リージョンのユーザーに対して応答遅延が発生しました。原因としてN+1クエリの混入が考えられ、エラーコードはPRF-02-00132です。運用部の運用一郎がこの事象を発見し、検知は同日08時50分41秒に行われました。今後の対応が求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00132', 'INC-2020-00132', '今回の障害は、大規模セール開始直前に発生しました。調査の結果、在庫照会APIにおいてN+1クエリの混入が確認され、これがp99レイテンシが閾値を超過する原因となっていることがわかりました。影響範囲は特定リージョンのユーザーに限定されており、他の地域への影響は確認されていません。', '今回の障害は、大規模セール開始直前に発生しました。調査の結果、在庫照会APIにおいてN+1クエリの混入が確認され、これがp99レイテンシが閾値を超過する原因となっていることがわかりました。影響範囲は特定リージョンのユーザーに限定されており、他の地域への影響は確認されていません。', TIMESTAMP WITH TIME ZONE '2020-04-20T08:54:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00193', 'INC-2020-00132', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T09:09:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T10:09:41+09:00', '【初期対応】【性能・負荷障害】照会API p99超過', '障害の発生が確認され次第、運用部は迅速に対応を開始しました。まずは、問題の確認を行い、在庫照会APIのp99レイテンシが閾値を超過していることを確認しました。次に、N+1クエリの混入が原因であると考えられるため、クエリの最適化作業を指示しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00133', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-21T10:44:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T11:14:15+09:00', '【障害報告】【性能・負荷障害】ピーク時画面10秒', '2023年10月05日、株式会社ストッククラウドのMercuryサービスにおいて、ピーク時に画面表示が10秒以上かかる障害が発生しました。この影響は全テナントに波及し、顧客から多数の問い合わせが寄せられました。発生契機は大規模セール開始直前であり、キャンペーンによるアクセス急増が推定されます。該当の技術コンポーネントはVenus Azure AP（Secondary）であり、APサーバークラスタが関与しています。エラーコードはPRF-01-00133です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00133', 'INC-2020-00133', '本障害に関する調査を行った結果、大規模セール開始前にアクセスが急増したことが原因であるとの結論に至りました。サーバのリソース状況やトラフィック状況を分析し、特にピーク時における負荷が高まっていることが明らかになりました。これにより、画面遅延が発生し、ユーザー体験が損なわれました。', '本障害に関する調査を行った結果、大規模セール開始前にアクセスが急増したことが原因であるとの結論に至りました。サーバのリソース状況やトラフィック状況を分析し、特にピーク時における負荷が高まっていることが明らかになりました。これにより、画面遅延が発生し、ユーザー体験が損なわれました。', TIMESTAMP WITH TIME ZONE '2020-04-22T11:14:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00194', 'INC-2020-00133', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T11:29:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T12:29:15+09:00', '【初期対応】【性能・負荷障害】ピーク時画面10秒 - 初期対応', '初期対応として、APサーバークラスタのリソースを増強し、負荷分散の最適化を行いました。これにより、アクセス急増に対する耐性を強化し、画面表示速度の改善を図りました。また、ユーザーへの情報提供を強化し、障害の影響を最小限に留めるよう努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00136', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-01T13:15:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T13:45:00+09:00', '【障害報告】【在庫マスター設定障害】マイナス在庫表示', '発生日時: 2023-10-01T10:15:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00136', 'INC-2020-00136', '当該事象の調査を行った結果、月末棚卸の開始時に登録した商品の在庫数量がマイナスで表示される現象が確認された。デフォルト倉庫IDが未設定であることが原因である可能性が高い。今後、設定を見直し、該当する在庫マスターの修正を行う必要がある。', '当該事象の調査を行った結果、月末棚卸の開始時に登録した商品の在庫数量がマイナスで表示される現象が確認された。デフォルト倉庫IDが未設定であることが原因である可能性が高い。今後、設定を見直し、該当する在庫マスターの修正を行う必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-02T13:45:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00198', 'INC-2020-00136', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T14:00:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T15:00:00+09:00', '初期対応', '初期対応として、関係部署に通知し、影響を受ける店舗の情報を収集した。デフォルト倉庫IDの設定状況を確認するための作業を開始し、必要な修正を行う準備を進めた。マイナス在庫表示の解消に向けて、関係者と連携を取りながら対応を進める。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00199', 'INC-2020-00136', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T15:30:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T16:30:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00141', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-28T16:48:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T17:18:15+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2023-10-01T14:30:00+09:00に株式会社ストッククラウドのMercuryにおいて、読取レプリカ遅延が発生しました。これにより在庫照会が古い値を返す事象が確認されました。発生契機は大規模セール開始直前であり、特定リージョンのユーザーに影響を及ぼしました。運用部の運用 一郎が問題を発見し、2023-10-01T15:00:00+09:00には問題の検知を行いました。検知までの時間は30分でした。エラーコードはSYNC-02-00141です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00141', 'INC-2020-00141', '読取レプリカ遅延の原因として、レプリケーション遅延の監視閾値超過が疑われます。具体的には、大規模セール開始直前に発生した影響により、データ同期に遅延が見られたため、在庫照会が古い値を返す結果となりました。影響を受けたのは特定リージョンのユーザーのみで、現在状況を改善するための対策を検討中です。', '読取レプリカ遅延の原因として、レプリケーション遅延の監視閾値超過が疑われます。具体的には、大規模セール開始直前に発生した影響により、データ同期に遅延が見られたため、在庫照会が古い値を返す結果となりました。影響を受けたのは特定リージョンのユーザーのみで、現在状況を改善するための対策を検討中です。', TIMESTAMP WITH TIME ZONE '2020-04-29T17:18:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00206', 'INC-2020-00141', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T17:33:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T18:33:15+09:00', '初期対応', '運用部の運用 一郎が発見したこの障害について、直ちにチームで調査を開始しました。まずは、読取レプリカの状況を確認し、レプリケーション遅延の監視閾値を見直す必要があります。また、関係各所に通知を行い、影響を受けたユーザーへのアナウンスを準備しています。今後の対応については、進捗を随時報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00207', 'INC-2020-00141', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T19:03:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T20:03:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00143', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-18T04:47:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T05:17:16+09:00', '【障害報告】【CLU-09】マスター在庫二重反映', '2023年10月05日 09:30:00に発生した事象について報告いたします。株式会社ストッククラウドのサービスMercuryにおいて、マスター更新と在庫が二重反映される問題が確認されました。今回のインシデントは、定例リリース直後に発生し、同一顧客の全店舗に影響を及ぼしています。推定される原因はイベント順序の逆転配信であり、エラーコードはSYNC-01-00143です。影響を受けたコンポーネントはMercury AWS APとイベントバスです。今後の対応が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00143', 'INC-2020-00143', '本インシデントに関して、調査を行った結果、定例リリース直後にマスター更新と在庫が二重反映される事象が発生しておりました。原因として、イベントの配信順序が逆転していることが確認されました。この問題により、データの整合性が損なわれる可能性があり、詳細な調査と修正が必要です。', '本インシデントに関して、調査を行った結果、定例リリース直後にマスター更新と在庫が二重反映される事象が発生しておりました。原因として、イベントの配信順序が逆転していることが確認されました。この問題により、データの整合性が損なわれる可能性があり、詳細な調査と修正が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-19T05:17:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00209', 'INC-2020-00143', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T05:32:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T06:32:16+09:00', '【対応履歴】【CLU-09】マスター在庫二重反映', '2023年10月05日 09:45:00に初期対応を開始しました。まずは、当該事象に関する詳細なログを確認し、影響範囲を特定します。また、運用チームとの連携を図り、必要な修正対応を迅速に進める体制を整えています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00145', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-07-10T03:55:43+09:00', TIMESTAMP WITH TIME ZONE '2020-07-10T04:25:43+09:00', '【障害報告】【CLU-07】EDI在庫差分遅延', '2020年7月10日03時55分43秒に、株式会社ストッククラウドが提供するMercuryサービスにおいて、在庫登録に関するマスター設定ミスが発生しました。この事象により、EDI在庫差分ファイルの反映が2時間遅延しました。発生した契機はデータ移行バッチの実行中であり、影響を受けたのは架空食品店Aの全店舗です。エラーコードはEDI-01-00145であり、詳細な技術情報によると、EDIキューの優先度設定に誤りがあったと推定されます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00145', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00145', 'INC-2020-00145', '本事象の調査において、データ移行バッチ実行中のEDI在庫差分ファイルの反映遅延が確認されました。初期調査により、EDIキューの優先度設定に誤りがあることが示唆されており、そのために全店舗に影響が及んでいる状況です。現在、詳細な原因分析を進めており、今後の対応策を検討しています。', '本事象の調査において、データ移行バッチ実行中のEDI在庫差分ファイルの反映遅延が確認されました。初期調査により、EDIキューの優先度設定に誤りがあることが示唆されており、そのために全店舗に影響が及んでいる状況です。現在、詳細な原因分析を進めており、今後の対応策を検討しています。', TIMESTAMP WITH TIME ZONE '2020-07-11T04:25:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00211', 'INC-2020-00145', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-10T04:40:43+09:00', TIMESTAMP WITH TIME ZONE '2020-07-10T05:40:43+09:00', '【初期対応】【CLU-07】EDI在庫差分遅延の初期対応', '本事象に対する初期対応として、運用部の運用 一郎が指定された時間内に、EDIキューの優先度設定を見直し、早急に修正作業を実施しました。また、影響を受けた全店舗への通知を行い、在庫差分の反映が正常化するまでの状況を監視する体制を構築しました。今後の改善策として、データ移行バッチ実行時の設定確認手順の見直しを行うことを計画しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00153', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-12-02T03:31:12+09:00', TIMESTAMP WITH TIME ZONE '2020-12-02T05:31:12+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2023-11-01T03:31:12+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00153', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00153', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00153', 'INC-2020-00153', '本障害は、2023-11-01に発生し、冪等キー重複が原因で在庫更新がスキップされたことが確認されました。影響を受けたのは、架空食品店Bおよび架空食品店Aの全店舗です。冪等キー生成ロジックの衝突が原因として考えられ、技術チームによるさらなる分析が必要です。', '本障害は、2023-11-01に発生し、冪等キー重複が原因で在庫更新がスキップされたことが確認されました。影響を受けたのは、架空食品店Bおよび架空食品店Aの全店舗です。冪等キー生成ロジックの衝突が原因として考えられ、技術チームによるさらなる分析が必要です。', TIMESTAMP WITH TIME ZONE '2020-12-03T05:31:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00222', 'INC-2020-00153', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-12-02T05:46:12+09:00', TIMESTAMP WITH TIME ZONE '2020-12-02T06:46:12+09:00', '初期対応', '初期対応として、影響を受けた顧客店舗に連絡を取り、問題を認識している旨を伝えました。また、冪等キーの重複が解消されるまでは在庫更新を一時停止し、顧客への影響を最小限に抑える策を講じました。技術チームには、冪等キー生成ロジックの見直しを依頼しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00154', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-24T21:05:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T21:35:58+09:00', '【障害報告】【在庫マスター設定障害】在庫APIタイムアウト', '2020年4月24日21時05分58秒に、株式会社ストッククラウドのMercuryサービスにおいて、在庫登録APIが30秒を超えてタイムアウトする事象が発生しました。発生状況の確認によれば、特定リージョンのユーザーに影響を及ぼしており、税率テーブルの不整合が原因として疑われます。大規模セール開始直前に発生したため、在庫管理に深刻な影響が及んでいます。検知は21時25分58秒に行われ、検知まで20分の間に多くのユーザーが影響を受けていることが確認されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00154', 'INC-2020-00154', '問題の調査を行った結果、在庫登録APIがタイムアウトする原因として、税率テーブルの不整合が特定されました。この不整合が、特定リージョンにおいて在庫APIの正常な動作を妨げ、結果としてエラーコードMST-05-00154が発生しました。大規模セールの直前というタイミングであったため、影響を受けたユーザーへの迅速な対応が求められました。', '問題の調査を行った結果、在庫登録APIがタイムアウトする原因として、税率テーブルの不整合が特定されました。この不整合が、特定リージョンにおいて在庫APIの正常な動作を妨げ、結果としてエラーコードMST-05-00154が発生しました。大規模セールの直前というタイミングであったため、影響を受けたユーザーへの迅速な対応が求められました。', TIMESTAMP WITH TIME ZONE '2020-04-25T21:35:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00223', 'INC-2020-00154', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T21:50:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T22:50:58+09:00', '初期対応', 'インシデント発生後、運用部の運用一郎が迅速に問題の調査を開始しました。影響を受けたユーザーからのフィードバックを収集し、在庫登録APIのログを確認することで、タイムアウトの原因を特定するための情報を集めました。また、大規模セールに伴う影響を最小限に抑えるため、税率テーブルの修正を検討し、影響範囲を広げないようにするための緊急の対応策を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00224', 'INC-2020-00154', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T23:20:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T00:20:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00157', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-11T22:46:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T23:16:03+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '2020年4月12日、株式会社ストッククラウドのMercuryサービスにおいて、楽観ロック競合が多発し、更新失敗率が上昇しました。これにより、全テナントに影響が及び、一部の在庫登録が正常に行えない状況が発生しました。発生契機は大規模セールの開始直前であり、運用部の運用 一郎が22時46分に問題を確認しました。その後、23時33分に検知されました。推定原因はバージョンカラム更新ロジックの不備であり、これが楽観ロック競合を引き起こしていると考えられます。今後は、リリース前の検証プロセスの強化が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00157', 'INC-2020-00157', '本障害に関する調査の結果、楽観ロック競合が発生した原因として、バージョンカラムの更新ロジックに不備があることが明らかになりました。特に、大規模セール開始直前にサーバー負荷が増加し、データ同期・整合性が確保できなかったことが主要因として挙げられます。全テナントで影響が及ぶため、迅速な対策が必要です。', '本障害に関する調査の結果、楽観ロック競合が発生した原因として、バージョンカラムの更新ロジックに不備があることが明らかになりました。特に、大規模セール開始直前にサーバー負荷が増加し、データ同期・整合性が確保できなかったことが主要因として挙げられます。全テナントで影響が及ぶため、迅速な対策が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-12T23:16:03+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00228', 'INC-2020-00157', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T23:31:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-12T00:31:03+09:00', '初期対応', '運用部の運用 一郎は、問題発生から45分以内に初期対応を開始しました。具体的には、影響を受けた在庫登録APIのログ分析を行い、楽観ロック競合が発生している箇所を特定しました。月次レビューを通じて、バージョンカラム更新ロジックの改善案を検討する必要があると判断されました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00161', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-20T07:05:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T09:05:29+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2023-10-15T10:30:00+09:00に発生したインシデントに関しまして、OAuthトークン失効により顧客店舗POSでの連携が中断いたしました。この障害は、営業部の花子によって発見され、顧客からの報告はありませんでした。発生の契機は年末年始の稼働切替時であり、影響範囲は単一店舗に限定されております。エラーコードは EDI-05-00161 で、技術的な詳細としては、リフレッシュトークン保存先に障害が発生した可能性があると考えられます。今後の対応として、原因の特定と早急な復旧作業が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00161', 'INC-2020-00161', '調査の結果、OAuthトークン失効による顧客店舗POSの連携中断が確認されました。リフレッシュトークン保存先に障害が発生している可能性が高く、詳細なログ解析を進める必要があります。今後の調査では、保存先のシステム状態を確認し、問題の根本原因を明らかにすることが重要です。関係各所との連携を強化し、迅速に復旧作業を行ってまいります。', '調査の結果、OAuthトークン失効による顧客店舗POSの連携中断が確認されました。リフレッシュトークン保存先に障害が発生している可能性が高く、詳細なログ解析を進める必要があります。今後の調査では、保存先のシステム状態を確認し、問題の根本原因を明らかにすることが重要です。関係各所との連携を強化し、迅速に復旧作業を行ってまいります。', TIMESTAMP WITH TIME ZONE '2020-04-21T09:05:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00235', 'INC-2020-00161', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T09:20:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T10:20:29+09:00', '【初動対応】【CLU-07】OAuthトークン失効に対する初動対応', '初動対応として、OAuthトークンの状態を確認し、リフレッシュトークン保存先の正常性を検証する作業を開始しています。店舗のシステム担当者とも連絡を取り、問題の影響範囲を把握するために必要な情報を収集しております。今後、復旧に向けて必要な手続きを速やかに行い、顧客への影響を最小限に抑えることを目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00162', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-07T17:35:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T17:50:00+09:00', '【障害報告】【CLU-10】ログ相関ID欠落', '2023-10-01T14:00:00+09:00に発生した運用者の作業ミスによるアクセス障害について報告いたします。本障害は運用コンソールにおいて、ログに相関IDが欠落し、横断検索が不可となったことに起因しております。推定される原因は、ログフォーマット変更のロールアウト漏れです。影響範囲は運用部門のみであり、定例リリース直後に発生したことが確認されております。エラーコードはMON-09-00162です。今後、このような事象が発生しないよう、作業手順の見直しを検討いたします。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00162', 'INC-2020-00162', '本障害の調査を実施した結果、定例リリース直後にログに相関IDが欠落し横断検索ができない状態が確認されました。原因として、ログフォーマット変更のロールアウト漏れが強く疑われます。運用部門とコミュニケーションを取り、今後のリリース作業における確認手順の強化を図る必要があります。', '本障害の調査を実施した結果、定例リリース直後にログに相関IDが欠落し横断検索ができない状態が確認されました。原因として、ログフォーマット変更のロールアウト漏れが強く疑われます。運用部門とコミュニケーションを取り、今後のリリース作業における確認手順の強化を図る必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-08T17:50:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00236', 'INC-2020-00162', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T18:05:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T19:05:00+09:00', '初期対応', '本障害発生直後に運用部門からの報告を受け、速やかに調査を開始しました。運用コンソールのログを確認したところ、相関IDが欠落していることが判明しました。影響を受ける範囲を特定し、必要な修正措置を講じるための方針を立てました。今後、定例リリースにおける確認作業を徹底し、同様の障害の再発防止に努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00237', 'INC-2020-00162', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T19:35:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T20:35:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00163', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-18T14:21:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T15:06:35+09:00', '【障害報告】【ストレージ・容量障害】DB自動拡張上限', '2021-06-15T10:30:00+09:00、株式会社ストッククラウドにおいて、DB自動拡張が上限に到達し書込停止の事象が発生しました。この問題は大規模セール開始直前に発生し、全テナントに波及したため、影響は広範囲に及びました。エラーコードはSTR-04-00163で、DB自動拡張の上限設定不足が推定原因となっています。この問題により、データベースへの書込が停止し、サービス利用に支障をきたしました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00163', 'INC-2020-00163', '調査の結果、DB自動拡張の設定において上限が適切に設定されていないことが確認されました。これにより、予想以上の負荷がかかった際にDBの拡張が行えず、書込停止に至ったと考えられます。今後は、定期的な設定の見直しと、負荷テストの実施を通じて、同様の事象が発生しないよう対策を講じる必要があります。', '調査の結果、DB自動拡張の設定において上限が適切に設定されていないことが確認されました。これにより、予想以上の負荷がかかった際にDBの拡張が行えず、書込停止に至ったと考えられます。今後は、定期的な設定の見直しと、負荷テストの実施を通じて、同様の事象が発生しないよう対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-19T15:06:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00238', 'INC-2020-00163', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T15:21:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T16:21:35+09:00', '【初期対応】【ストレージ・容量障害】DB自動拡張上限', '初期対応として、運用部の運用 一郎が即座にDB自動拡張の設定を確認し、必要な変更を行いました。また、影響を受けたテナントへの通知も行い、状況の説明と今後の対策について説明しました。さらに、問題解決後はデータの整合性確認を行い、正常なサービス運用を再開しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00164', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-04T09:35:33+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T10:20:33+09:00', '【障害報告】【ストレージ・容量障害】ログローテ停止', '2020年4月4日09時35分頃、株式会社ストッククラウドのMercuryにおいてストレージ溢れの障害が発生。ログローテーションが停止し、容量を圧迫する事象が確認された。発見者は運用部の運用 一郎であり、発生から約26分後の10時01分に検知された。影響範囲はバッチ処理のみで、オンラインサービスへの影響は確認されていない。推定原因として、一時ファイルの削除バッチが停止したことが考えられる。データ移行バッチ実行中にログローテーションが停止し、Mercury AWS Storageと監査ログボリュームの容量が逼迫した。エラーコードはSTR-02-00164。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00164', 'INC-2020-00164', 'インシデント発生後、原因調査を行った結果、データ移行バッチ実行中にログローテーションが停止したことが判明。ログローテーションの停止は容量を圧迫し、一時ファイルの削除バッチが停止していることが根本原因として疑われる。この状況は、Mercury AWS Storageにおけるストレージ・容量問題を引き起こし、バッチ処理のみの影響に留まった。', 'インシデント発生後、原因調査を行った結果、データ移行バッチ実行中にログローテーションが停止したことが判明。ログローテーションの停止は容量を圧迫し、一時ファイルの削除バッチが停止していることが根本原因として疑われる。この状況は、Mercury AWS Storageにおけるストレージ・容量問題を引き起こし、バッチ処理のみの影響に留まった。', TIMESTAMP WITH TIME ZONE '2020-04-05T10:20:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00239', 'INC-2020-00164', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-04T10:35:33+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T11:35:33+09:00', '【初期対応】ログローテーションの復旧', '初期対応として、ログローテーションの復旧作業を実施した。一時ファイルの削除バッチの再起動を行い、容量を確保する対応を図った。また、データ移行バッチの進捗状況を監視し、再発防止策を検討するためのログを確認した。今後は、このようなストレージ・容量障害の再発を防ぐため、定期的な監視体制の強化を図る。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00165', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-17T06:07:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T07:07:59+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023-10-17T09:00:00+09:00、株式会社ストッククラウドの顧客拠点NWにおいて、特定拠点のみAPI呼び出しが失敗する事象が発生しました。この障害は、顧客からの報告によるものではなく、当社営業部の花子が発見しました。発生は2023-10-17T09:00:00+09:00であり、検知は2023-10-17T09:30:00+09:00に行われ、検知までの時間は約30分でした。影響範囲は単一店舗のみであり、推定原因としては店舗LANのスイッチ故障が考えられます。特定拠点のネットワークが正常に機能していないことが確認されています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00165', 'INC-2020-00165', '2023-10-17T09:00:00+09:00に発生した顧客拠点NWのAPI呼び出し失敗について調査を開始しました。調査の結果、新規店舗追加の初日に特定拠点のみAPI呼び出しが失敗する原因として、店舗LANのスイッチの故障が疑われます。ネットワーク機器の状態確認を行い、問題の特定を進める必要があります。', '2023-10-17T09:00:00+09:00に発生した顧客拠点NWのAPI呼び出し失敗について調査を開始しました。調査の結果、新規店舗追加の初日に特定拠点のみAPI呼び出しが失敗する原因として、店舗LANのスイッチの故障が疑われます。ネットワーク機器の状態確認を行い、問題の特定を進める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-18T07:07:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00240', 'INC-2020-00165', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-17T07:22:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T08:22:59+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗への初期対応', '2023-10-17T09:15:00+09:00、顧客拠点NWの状況を確認するため、ネットワーク機器の状態を調査しました。LANスイッチのログに異常が記録されており、故障の可能性が高いことが確認されました。故障が確認された場合、迅速な復旧作業が必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00166', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-10T16:08:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T17:08:31+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '2020年4月10日16時08分31秒に発生した顧客側ネットワーク障害について報告いたします。今回の障害は、単一店舗において、店舗Wi-Fiの認証ページでAPI通信が遮断される事象が発生しました。別途、原因としてキャプティブポータルによるHTTPSインターセプトが疑われます。本件は新規店舗追加の初日に発生し、影響範囲は顧客拠点NW（DRサイト）および顧客側FWに限られています。なお、エラーコードはNW-09-00166です。障害の発見は2020年4月10日16時57分31秒であり、検知までに49分の遅延がありました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00166', 'INC-2020-00166', '調査の結果、新規店舗が追加された初日に、店舗Wi-Fiの認証ページでAPI通信が遮断されたことが判明しました。これはキャプティブポータルによるHTTPSインターセプトが原因と考えられます。影響範囲は単一店舗に限られ、顧客拠点NW（DRサイト）と顧客側FWが影響を受けました。現状ではこの問題に関連する設定や構成に不具合がないかを更に確認する必要があります。', '調査の結果、新規店舗が追加された初日に、店舗Wi-Fiの認証ページでAPI通信が遮断されたことが判明しました。これはキャプティブポータルによるHTTPSインターセプトが原因と考えられます。影響範囲は単一店舗に限られ、顧客拠点NW（DRサイト）と顧客側FWが影響を受けました。現状ではこの問題に関連する設定や構成に不具合がないかを更に確認する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T17:08:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00241', 'INC-2020-00166', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T17:23:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T18:23:31+09:00', '【初動対応】【顧客ネットワーク障害】Wi-Fi captive portal', '初期対応として、店舗Wi-Fiのキャプティブポータルに関する設定を確認し、HTTPS通信のインターセプトを避けるための対策を講じました。また、関連するネットワーク機器のログを収集し、異常がないかを調査しております。顧客には状況をご報告し、現在の進捗状況を随時お伝えすることとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00242', 'INC-2020-00166', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T18:53:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T19:53:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00167', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-01T20:13:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T20:58:00+09:00', '【障害報告】【監視・可用性障害】可用性レポート誤集計', '2023-10-01T15:00:00+09:00に発生したストレージ溢れにより、Mercury AWS Storageにおいて月次可用性レポートが実績より高く表示されるという障害が発生しました。この障害は運用部門にのみ影響を及ぼし、月末棚卸の開始時に確認されました。運用 一郎が発見したこの問題は、メンテナンス除外時間の二重計上が原因と推定されます。エラーコードはMON-10-00167で、影響コンポーネントはMercury AWS Storage（ゾーンB）および可用性レポートです。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00167', 'INC-2020-00167', '本インシデントに関する調査の結果、月末棚卸の開始時に月次可用性レポートが誤って高く表示される事象が確認されました。原因としてはメンテナンス除外時間の二重計上が考えられ、これにより実績が実際の可用性を上回る形で誤集計されていました。この問題は監視システムの設定に起因しており、運用部門の業務に混乱を招く結果となりました。', '本インシデントに関する調査の結果、月末棚卸の開始時に月次可用性レポートが誤って高く表示される事象が確認されました。原因としてはメンテナンス除外時間の二重計上が考えられ、これにより実績が実際の可用性を上回る形で誤集計されていました。この問題は監視システムの設定に起因しており、運用部門の業務に混乱を招く結果となりました。', TIMESTAMP WITH TIME ZONE '2020-04-02T20:58:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00243', 'INC-2020-00167', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T21:13:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T22:13:00+09:00', '【監視・可用性障害】初期対応', '初期対応として、運用 一郎がすぐにこの問題を報告し、チーム内での情報共有が行われました。影響を受けた部門に対しての通知が早急に実施され、指示を徹底することでさらなる混乱を防ぐことができました。また、システムの設定確認を行い、再発防止策を講じるための会議が設けられました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00244', 'INC-2020-00167', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T22:43:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T23:43:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00176', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-13T06:42:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T07:12:21+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2020年4月13日06時42分21秒に、株式会社ストッククラウドのMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。具体的には、マスター更新後も旧設定で在庫登録が拒否され、全テナントに波及する影響が確認されました。この症状は、定例リリース直後に発生し、旧設定による不整合が原因と考えられています。エラーコードはMST-10-00176であり、影響を受けたコンポーネントはMercury AWS AP（Primary）及びキャッシュレイヤです。検知は発生から17分後の06時59分21秒でした。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00176', 'INC-2020-00176', '本インシデントの原因は、定例リリース直後にマスター更新後も旧設定がキャッシュに残っており、在庫登録が拒否される状況が発生したことです。キャッシュレイヤの無効化漏れが疑われ、全テナントに影響を及ぼしました。今後は、リリース後のキャッシュクリア処理の徹底を図る必要があります。', '本インシデントの原因は、定例リリース直後にマスター更新後も旧設定がキャッシュに残っており、在庫登録が拒否される状況が発生したことです。キャッシュレイヤの無効化漏れが疑われ、全テナントに影響を及ぼしました。今後は、リリース後のキャッシュクリア処理の徹底を図る必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-14T07:12:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00259', 'INC-2020-00176', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T07:27:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T08:27:21+09:00', '【初動対応】【在庫マスター設定障害】キャッシュ不整合登録', 'インシデント発生後、運用部の運用 一郎が対応にあたり、キャッシュレイヤの状態を確認しました。旧設定がキャッシュに残っていることを特定し、キャッシュを手動でクリアする措置を講じました。これにより、在庫登録が正常化することが確認されました。再発防止策として、今後のリリース管理にキャッシュクリアを組み込むことを提案します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00180', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-11-04T17:04:36+09:00', TIMESTAMP WITH TIME ZONE '2020-11-04T17:49:36+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2020年11月4日17時04分36秒、株式会社ストッククラウドのMercuryサービスにおいて、主要メトリクス系列が15分間欠損するストレージ溢れが発生しました。この事象は運用部門の運用 一郎によって発見され、検知までに34分を要しました。影響を受けたコンポーネントはMercury AWS Storageで、特にメトリクスコレクタにおいて問題が確認されました。発生契機はインフラメンテナンス明けであり、推定される原因はメトリクスエージェントの再起動失敗です。この問題により、運用部門のみが影響を受ける結果となりました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00180', 'CUST-0002');
