INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00180', 'INC-2020-00180', '今回の監視・可用性障害に関する調査を実施した結果、インフラメンテナンス明けのタイミングで主要メトリクス系列が15分間欠損した原因は、メトリクスエージェントの再起動失敗に起因することが確認されました。今後はエージェントの監視強化や再起動手順の見直しを行い、再発防止に努める必要があります。', '今回の監視・可用性障害に関する調査を実施した結果、インフラメンテナンス明けのタイミングで主要メトリクス系列が15分間欠損した原因は、メトリクスエージェントの再起動失敗に起因することが確認されました。今後はエージェントの監視強化や再起動手順の見直しを行い、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2020-11-05T17:49:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00265', 'INC-2020-00180', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-11-04T18:04:36+09:00', TIMESTAMP WITH TIME ZONE '2020-11-04T19:04:36+09:00', '【初期対応】【監視・可用性障害】メトリクス欠損', '運用部では、メトリクス欠損が発生した際に即座に状況確認を行い、原因としてメトリクスエージェントの再起動失敗の可能性を考え、エージェントの状態を確認しました。必要に応じて再起動手続きを実行し、メトリクスの正常化を図りました。また、情報共有を行い、影響範囲の特定と関係者への連絡を速やかに行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00266', 'INC-2020-00180', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-11-04T19:34:36+09:00', TIMESTAMP WITH TIME ZONE '2020-11-04T20:34:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
