INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00182', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-18T23:25:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T23:55:50+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2020年4月24日、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。発生時刻は2020-04-18T23:25:50+09:00で、検知までに23分を要しました。症状としては、マスター更新後も旧設定で在庫登録が拒否されるというもので、全テナントに波及する影響がありました。エラーコードはMST-10-00182で、定例リリース直後に発生したため、キャッシュレイヤの無効化漏れが推定原因として考えられています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00182', 'INC-2020-00182', '本インシデントの調査において、定例リリース直後にマスター更新後も旧設定で在庫登録が拒否される現象が確認されました。キャッシュレイヤの無効化漏れが主な原因とされており、技術的にはキャッシュの不整合が影響を及ぼしたと考えられます。これにより、全テナントで在庫登録が不能となり、運用への影響が大きかったことが判明しました。', '本インシデントの調査において、定例リリース直後にマスター更新後も旧設定で在庫登録が拒否される現象が確認されました。キャッシュレイヤの無効化漏れが主な原因とされており、技術的にはキャッシュの不整合が影響を及ぼしたと考えられます。これにより、全テナントで在庫登録が不能となり、運用への影響が大きかったことが判明しました。', TIMESTAMP WITH TIME ZONE '2020-04-19T23:55:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00268', 'INC-2020-00182', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T00:10:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T01:10:50+09:00', '【初期対応】【在庫マスター設定障害】キャッシュ不整合登録', '初動対応として、運用部の一郎が問題を確認し、キャッシュレイヤの設定を再点検しました。旧設定に基づく在庫登録拒否の事象を解決するため、急遽キャッシュの強制クリアを実施しました。これにより、直ちに在庫登録が可能となり、不整合の解消が図られました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00269', 'INC-2020-00182', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T01:40:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T02:40:50+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00189', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-14T17:16:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T17:46:34+09:00', '【障害報告】【認証・セッション障害】MFAデバイス不一致', '2023-04-14 17:16:34に、株式会社ストッククラウドのMercuryサービスにおいて、MFAデバイス登録不一致が発生し、ログイン不可の状態が確認されました。発生した場所はVenus Azure APで、影響範囲は単一店舗のみでした。原因としては、MFAシードの再発行未同期が疑われます。この問題は顧客オンボーディング当日に発生しました。影響を受けた顧客はなく、エラーコードはAUTH-03-00189です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00189', 'INC-2020-00189', '運用部の運用 一郎が検知した問題に関して、MFAデバイス登録不一致が原因でログインできない状況を確認しました。技術的な詳細として、顧客オンボーディング当日に発生したことを踏まえ、MFAシードの再発行未同期が主な原因であると推定されます。継続的に調査を行い、問題の根本的な解決に向けた対応を検討します。', '運用部の運用 一郎が検知した問題に関して、MFAデバイス登録不一致が原因でログインできない状況を確認しました。技術的な詳細として、顧客オンボーディング当日に発生したことを踏まえ、MFAシードの再発行未同期が主な原因であると推定されます。継続的に調査を行い、問題の根本的な解決に向けた対応を検討します。', TIMESTAMP WITH TIME ZONE '2020-04-15T17:46:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00279', 'INC-2020-00189', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T18:01:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T19:01:34+09:00', '【初期対応】【認証・セッション障害】MFAデバイス不一致への対応', 'この度はMFAデバイスの不一致により、ログインに問題が発生しましたことをお詫び申し上げます。事象の早期解決に向けて、運用部が状況の把握と調査に入ります。影響を受けた店舗に対しては、問題発生の旨を報告し、必要に応じて代替手段を提案します。MFAシードの再発行についても、速やかに同期作業を行い、早期のサービス復旧を目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00190', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-09T02:25:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T02:40:23+09:00', '【障害報告】【CLU-10】合成監視失敗', '2023-10-15T14:00:00+09:00 に、株式会社ストッククラウドの運用コンソールにおいて合成監視が特定ステップで失敗する事象が発生しました。これは定例リリース直後に起こり、影響範囲はサービス全体の一部機能に及びます。エラーコードは MON-08-00190 で、原因としてテストデータの期限切れが疑われます。運用 一郎(運用部) によって発見され、検知までに11分を要しました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00190', 'INC-2020-00190', '合成監視の失敗は定例リリース直後に確認されました。運用コンソールの合成監視ランナーが特定ステップで失敗し、テストデータの期限切れが推定原因とされています。現在、影響を受けている機能の特定とテストデータの更新作業を急いで行っております。', '合成監視の失敗は定例リリース直後に確認されました。運用コンソールの合成監視ランナーが特定ステップで失敗し、テストデータの期限切れが推定原因とされています。現在、影響を受けている機能の特定とテストデータの更新作業を急いで行っております。', TIMESTAMP WITH TIME ZONE '2020-04-10T02:40:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00280', 'INC-2020-00190', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T02:55:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T03:55:23+09:00', '【初期対応】【CLU-10】合成監視失敗', '初期対応として、運用部はテストデータの確認を実施しました。既存のテストデータが期限切れであることが判明し、直ちに新しいデータを準備中です。また、合成監視のステップ失敗原因に関する分析を進め、影響範囲の拡大を防ぐための対策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00192', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-07-25T14:56:02+09:00', TIMESTAMP WITH TIME ZONE '2020-07-25T16:56:02+09:00', '【障害報告】【CLU-07】配送連携ステータス停滞', '2020年7月25日14時56分に、株式会社ストッククラウドが提供するMercuryサービスにおいて、架空食品店Aで配送連携のステータスが出荷済みで停滞する事象が発生しました。この問題は、顧客店舗POSの特定の単一店舗において観測されました。影響を受けたのは、配送連携アダプタであり、エラーコードはEDI-09-00192です。発生の契機は大規模セール開始直前であり、弊社営業部の花子がこの事象を発見しました。検知は同日16時41分に行われ、発生から105分後のことでした。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00192', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00192', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00192', 'INC-2020-00192', '調査の結果、配送連携のステータスが出荷済みで停滞している原因として、ステータスマッピング表の更新漏れが疑われます。この問題は、特定の顧客店舗POSにおけるAPI連携・EDI障害と関連しています。また、問題の発生は大規模セール前というタイミングであったため、さらなる調査が必要です。', '調査の結果、配送連携のステータスが出荷済みで停滞している原因として、ステータスマッピング表の更新漏れが疑われます。この問題は、特定の顧客店舗POSにおけるAPI連携・EDI障害と関連しています。また、問題の発生は大規模セール前というタイミングであったため、さらなる調査が必要です。', TIMESTAMP WITH TIME ZONE '2020-07-26T16:56:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00283', 'INC-2020-00192', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-07-25T17:11:02+09:00', TIMESTAMP WITH TIME ZONE '2020-07-25T18:11:02+09:00', '【初動対応】【CLU-07】配送連携ステータス停滞', '初動対応として、影響を受けた顧客店舗POSのステータスを確認し、配送連携アダプタのログを収集しました。ステータスマッピング表の更新漏れが原因であることを疑い、専門チームに調査を依頼しました。顧客への影響を最小限に抑えるため、早急に修正作業に着手する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00195', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-28T03:30:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T05:30:43+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '2023年10月15日03時30分43秒に、株式会社ストッククラウドのMercuryサービスにおいて、実地棚卸数とシステム在庫が大幅に乖離する事象が発生いたしました。この問題は顧客店舗POSにて確認されており、影響範囲は同一顧客の全店舗に及びます。発見者は営業部の花子であり、月末棚卸の開始時に発生したことが確認されております。エラーコードはINV-01-00195で、弊社の棚卸突合エンジンに関連する問題が見受けられます。原因として棚卸スナップショット時刻のずれを疑っております。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00195', 'INC-2020-00195', '本件につきましては、月末棚卸の開始時に実地棚卸数とシステム在庫が乖離する原因として、棚卸スナップショット時刻のずれが考えられます。現在、詳しい原因を特定するための調査を進めており、影響を受けている店舗の状況を確認しながら対応を行っております。', '本件につきましては、月末棚卸の開始時に実地棚卸数とシステム在庫が乖離する原因として、棚卸スナップショット時刻のずれが考えられます。現在、詳しい原因を特定するための調査を進めており、影響を受けている店舗の状況を確認しながら対応を行っております。', TIMESTAMP WITH TIME ZONE '2020-04-29T05:30:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00287', 'INC-2020-00195', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-28T05:45:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T06:45:43+09:00', '【初動対応】【棚卸・POS突合障害】棚卸実地差異', '初動対応として、影響を受けた店舗に対し、実地棚卸数とシステム在庫の乖離を報告し、スナップショット時刻の確認を行うよう指示いたしました。また、営業部の花子より、顧客への影響を最小限に抑えるための情報提供を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00197', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-11-12T15:55:30+09:00', TIMESTAMP WITH TIME ZONE '2020-11-12T16:55:30+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2020年11月12日15時55分、株式会社ストッククラウドの顧客である架空食品店Bにて、顧客拠点NWが同時不通となるISP側BGP経路障害が発生しました。16時11分に検知され、その後調査を行いました。影響範囲は同一顧客の全店舗に及び、原因としてISP側のBGP経路障害が推定されます。今回の障害はインフラメンテナンス明けに発生しました。技術的には、DNSリゾルバにも影響が確認されており、顧客ネットワークへの影響が広がりました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00197', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00197', 'INC-2020-00197', '本障害の調査において、複数の顧客店舗が同時に接続が不可能となった原因は、ISP側のBGP経路障害によるものであると確認されました。経路障害は、インフラメンテナンスの直後に発生しており、ISPの対応待ちの段階であることが確認されています。必要に応じて、ISPとの連携を強化し、早急な復旧を目指す方針です。', '本障害の調査において、複数の顧客店舗が同時に接続が不可能となった原因は、ISP側のBGP経路障害によるものであると確認されました。経路障害は、インフラメンテナンスの直後に発生しており、ISPの対応待ちの段階であることが確認されています。必要に応じて、ISPとの連携を強化し、早急な復旧を目指す方針です。', TIMESTAMP WITH TIME ZONE '2020-11-13T16:55:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00290', 'INC-2020-00197', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-11-12T17:10:30+09:00', TIMESTAMP WITH TIME ZONE '2020-11-12T18:10:30+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '顧客からの通報を受け、営業部の花子が迅速に状況を確認しました。顧客拠点NWの障害について確認し、ISPへの連絡を行いました。また、同時に顧客への情報提供を実施し、障害内容と今後の対応について説明を行いました。BGP経路障害の可能性を考慮し、関連情報を収集し続けました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00203', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-11T22:25:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T23:25:47+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '・発生日時: 2023-10-05T22:25:47+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00203', 'INC-2020-00203', '調査を開始し、DNSリゾルバの設定におけるTTL値とキャッシュポリシーに不一致があることを確認しました。店舗のDNSキャッシュは、定例リリース後に古いIPアドレスを返し続けており、これが原因で顧客ネットワークに影響を及ぼしています。DNSの設定とキャッシュ管理を見直し、正しいIPアドレスを返すよう対応を進めています。', '調査を開始し、DNSリゾルバの設定におけるTTL値とキャッシュポリシーに不一致があることを確認しました。店舗のDNSキャッシュは、定例リリース後に古いIPアドレスを返し続けており、これが原因で顧客ネットワークに影響を及ぼしています。DNSの設定とキャッシュ管理を見直し、正しいIPアドレスを返すよう対応を進めています。', TIMESTAMP WITH TIME ZONE '2020-04-12T23:25:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00299', 'INC-2020-00203', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-11T23:40:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-12T00:40:47+09:00', '【対応ログ】【顧客ネットワーク障害】DNSキャッシュ汚染', '初期対応として、店舗のDNSキャッシュ設定を確認し、TTL設定を見直しました。さらに、DNSリゾルバのキャッシュ方針との整合性をチェックし、必要に応じて設定を更新する方針です。顧客への影響を最小限に抑えるため、早急に修正作業を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00300', 'INC-2020-00203', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-12T01:10:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-12T02:10:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00204', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-01T20:00:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T20:30:51+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2020年4月1日20時00分51秒に、株式会社ストッククラウドのサービスMercuryにおいて、パートナーAPIが429を返し連携が停止しました。この事象は、大規模セール開始直前に発生しており、呼出頻度の事前調整不足が推定されます。影響範囲はサービス全体の一部機能であり、エラーコードはEDI-06-00204です。具体的には、Mercury AWS AP（ゾーンA）およびAPIゲートウェイにおいて、429エラーが引き起こされました。運用部の運用 一郎がこの問題を発見し、検知まで43分を要しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00204', 'INC-2020-00204', '調査の結果、大規模セール開始直前にパートナーAPIが429エラーを返し、連携が停止したことが確認されました。呼出頻度の事前調整不足が原因と考えられており、影響を受けたコンポーネントはMercury AWS AP（ゾーンA）およびAPIゲートウェイであることが明らかになりました。この事象により、サービス全体の一部機能が影響を受けました。', '調査の結果、大規模セール開始直前にパートナーAPIが429エラーを返し、連携が停止したことが確認されました。呼出頻度の事前調整不足が原因と考えられており、影響を受けたコンポーネントはMercury AWS AP（ゾーンA）およびAPIゲートウェイであることが明らかになりました。この事象により、サービス全体の一部機能が影響を受けました。', TIMESTAMP WITH TIME ZONE '2020-04-02T20:30:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00301', 'INC-2020-00204', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T20:45:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T21:45:51+09:00', '【初期対応】レート超過429', '運用 一郎が問題を把握し、直ちにパートナーAPIとの連携状況を確認しました。429エラーが返されていることを確認し、原因として呼出頻度の事前調整不足が考慮されました。迅速な対応が求められたため、関係者への連絡を行い、修正に向けての検討を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00208', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-07T16:06:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T16:36:35+09:00', '【障害報告】【CLU-07】EDI在庫差分遅延', '株式会社ストッククラウドのMercuryにおいて、2023年11月01日16時06分に発生した障害について報告いたします。EDI在庫差分ファイルの反映が2時間遅延し、同一顧客の全店舗に影響を及ぼしました。データ移行バッチ実行中におけるEDIキューの優先度設定誤りが推定原因と考えられます。この遅延によって、在庫情報の正確性が損なわれ、業務に支障をきたす恐れがあるため、迅速な対応が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00208', 'INC-2020-00208', '本障害に関する調査を実施いたしました。データ移行バッチが実行中であったことが、EDI在庫差分ファイルの反映遅延の直接的な要因です。調査の結果、EDIキューの優先度設定に誤りがあり、この設定ミスが原因で反映が遅れたことが判明しました。今後の再発防止策として、優先度設定の見直しを行う必要があります。', '本障害に関する調査を実施いたしました。データ移行バッチが実行中であったことが、EDI在庫差分ファイルの反映遅延の直接的な要因です。調査の結果、EDIキューの優先度設定に誤りがあり、この設定ミスが原因で反映が遅れたことが判明しました。今後の再発防止策として、優先度設定の見直しを行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-08T16:36:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00306', 'INC-2020-00208', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T16:51:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T17:51:35+09:00', '【初期対応】【CLU-07】EDI在庫差分遅延についての初期対応', 'お客様からの報告を受け、初期対応を開始しました。まずは、影響を受けた全店舗に対し、現在の状況を通知し、適切な在庫管理が行えるように情報を提供いたしました。また、技術チームが迅速に原因の特定を行い、再発防止策の検討を始めております。現在、問題の継続的な監視を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00307', 'INC-2020-00208', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T18:21:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T19:21:35+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00211', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-20T18:17:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T20:17:11+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2020年4月20日18時17分11秒に、株式会社ストッククラウドのMercuryサービスにおいて棚卸突合失敗が発生しました。この障害は顧客店舗POSにて、分散トランザクションがタイムアウトし、片側のみコミットされる事象を引き起こしました。発見者は営業部の花子で、検知は同日の21時08分11秒に行われ、発生から171分後のことでした。影響範囲は全テナントに波及し、大規模セール開始直前に発生したことが発生契機として考えられます。推定される原因としては、2PCタイムアウト設定の過短が挙げられるため、今後の改善策としてこの設定の見直しが求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00211', 'INC-2020-00211', '調査の結果、大規模セール開始直前に分散トランザクションがタイムアウトし片側のみコミットされる事象が発生しました。顧客店舗POSでのデータ同期・整合性に関する問題が確認され、特に2PCタイムアウト設定の見直しが必要であることが判明しました。今後はこの設定を適切に調整し、再発防止策を講じることが求められます。また、影響範囲が全テナントに広がる可能性を考慮し、迅速な対応が重要です。', '調査の結果、大規模セール開始直前に分散トランザクションがタイムアウトし片側のみコミットされる事象が発生しました。顧客店舗POSでのデータ同期・整合性に関する問題が確認され、特に2PCタイムアウト設定の見直しが必要であることが判明しました。今後はこの設定を適切に調整し、再発防止策を講じることが求められます。また、影響範囲が全テナントに広がる可能性を考慮し、迅速な対応が重要です。', TIMESTAMP WITH TIME ZONE '2020-04-21T20:17:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00311', 'INC-2020-00211', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T20:32:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T21:32:11+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウトへの対応', '初期対応として、発生した分散トランザクションタイムアウトの影響を受けた顧客店舗POSの状態を確認し、片側のみコミットされたデータの整合性を回復するための作業を開始しました。また、2PCタイムアウト設定の過短が原因と考えられるため、該当設定の見直しを行う旨の連絡を内部に行い、担当者に対して早急な対応を依頼しました。これにより、今後のデータ同期・整合性の障害を最小限に抑えることが期待されます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00217', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-02T04:51:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T06:51:47+09:00', '【障害報告】【CLU-07】レート超過429', '2023-10-10T10:30:00+09:00に発生した棚卸突合失敗について報告します。顧客店舗POSにおいて、パートナーAPIが429を返し連携停止しました。これは大規模セール開始直前の状況で、サービス全体の一部機能に影響を及ぼしました。エラーコードはEDI-06-00217です。発見者は営業部の花子で、検知は2023-10-10T10:45:00+09:00に行われました。呼出頻度の事前調整不足が推定される原因です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00217', 'INC-2020-00217', '調査の結果、2023-10-10T10:30:00+09:00に発生した問題は、パートナーAPIによる429エラーが原因であることが確認されました。大規模セール開始直前にこの問題が発生し、呼出頻度の調整が行われていなかったことが推定されます。今後はこの問題を防ぐための対策を講じる必要があります。', '調査の結果、2023-10-10T10:30:00+09:00に発生した問題は、パートナーAPIによる429エラーが原因であることが確認されました。大規模セール開始直前にこの問題が発生し、呼出頻度の調整が行われていなかったことが推定されます。今後はこの問題を防ぐための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-03T06:51:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00318', 'INC-2020-00217', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-02T07:06:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T08:06:47+09:00', '【初期対応】【CLU-07】レート超過429', '営業部の花子が2023-10-10T10:30:00+09:00に発見したレート超過の問題について、初期対応を実施します。まずはパートナーAPIの状態を確認し、リクエストの頻度を調整する必要があります。これによりAPI連携が復旧することを期待しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00319', 'INC-2020-00217', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-02T08:36:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T09:36:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00222', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-02T11:47:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T12:17:37+09:00', '【障害報告】【性能・負荷障害】コールドスタート連鎖', '2023-10-10T09:30:00+09:00 に、株式会社ストッククラウドが提供するサービスMercuryにおいて、サーバーレス関数のコールドスタートが連鎖する事象が発生しました。影響範囲はサービス全体の一部機能に及び、エラーコードはPRF-06-00222です。発生契機は定例リリース直後であり、運用部の運用 一郎が発見しました。検知は2023-10-10T09:54:00+09:00までに行われ、その間に約24分の遅延がありました。このコールドスタートの連鎖が原因で性能・負荷障害が発生したものと考えられます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00222', 'INC-2020-00222', '調査の結果、定例リリース直後にサーバーレス関数のコールドスタートが連鎖して発生したことが確認されました。原因としてはコールドスタートの連鎖が疑われており、影響を受けたコンポーネントはVenus Azure AP（Primary）とCDNエッジです。今後はコールドスタートの管理に関する改善策を検討する必要があります。', '調査の結果、定例リリース直後にサーバーレス関数のコールドスタートが連鎖して発生したことが確認されました。原因としてはコールドスタートの連鎖が疑われており、影響を受けたコンポーネントはVenus Azure AP（Primary）とCDNエッジです。今後はコールドスタートの管理に関する改善策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-03T12:17:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00327', 'INC-2020-00222', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T12:32:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T13:32:37+09:00', '【対応ログ】【性能・負荷障害】初期対応', '運用 一郎より、2023-10-10T09:30:00+09:00 に発生したコールドスタートの連鎖に対する初期対応が行われました。まずは状況を確認し、影響範囲を特定するために迅速な調査を開始しました。サーバーレス機能の状況をモニタリングし、問題の解決に向けた手順を協議し、必要に応じて追加のリソースを検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00328', 'INC-2020-00222', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T14:02:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T15:02:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00224', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-07T09:28:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T11:28:40+09:00', '【障害報告】【CLU-07】文字コード変換事故', '2020年4月7日09時28分40秒、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSで棚卸突合失敗が発生した。原因としてShift_JIS変換で商品名が文字化けする事象が確認された。これはデータ移行バッチ実行中に発生し、文字コード変換テーブルの誤選択が推定される。影響範囲は単一店舗に限定され、エラーコードはEDI-07-00224である。検知は2020年4月7日11時56分40秒に行われ、148分後の発見となった。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00224', 'INC-2020-00224', '調査の結果、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしていることが確認された。文字コード変換テーブルの誤選択が根本原因であると考えられる。影響を受けたコンポーネントは顧客店舗POS（Primary）とEDIアダプタであり、今後の対策として、このプロセスにおけるテーブル選択の見直しが必要である。', '調査の結果、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしていることが確認された。文字コード変換テーブルの誤選択が根本原因であると考えられる。影響を受けたコンポーネントは顧客店舗POS（Primary）とEDIアダプタであり、今後の対策として、このプロセスにおけるテーブル選択の見直しが必要である。', TIMESTAMP WITH TIME ZONE '2020-04-08T11:28:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00330', 'INC-2020-00224', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T11:43:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T12:43:40+09:00', '初期対応', '初期対応として、発生した文字化けの詳細を取得し、影響を受けた商品データを確認した。また、データ移行バッチを一時停止し、文字コード変換テーブルの選択を見直す作業を開始した。これにより、今後の類似事案を防ぐための再発防止策を講じる必要がある。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00331', 'INC-2020-00224', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T13:13:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T14:13:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00228', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-09T08:26:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T09:11:12+09:00', '【障害報告】【ストレージ・容量障害】監査ログ削除未実行', '2023年10月05日、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れが発生しました。古い監査ログ削除ジョブが未実行であることが症状として現れ、容量アラート閾値の未設定が推定される原因です。影響範囲はバッチ処理のみに限られ、オンラインには影響がありませんでした。発生は定例リリース直後であり、Mercury AWS Storageの監査ログボリュームにて問題が確認されました。エラーコードはSTR-05-00228です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00228', 'INC-2020-00228', 'インシデント発生後、運用部の運用 一郎が調査を行いました。定例リリース直後において、古い監査ログ削除ジョブが未実行であることが確認され、容量アラート閾値の未設定が原因の可能性が高いと判断されました。既存の監査ログが削除されずに保持され、ストレージの容量が逼迫を招いている状態です。', 'インシデント発生後、運用部の運用 一郎が調査を行いました。定例リリース直後において、古い監査ログ削除ジョブが未実行であることが確認され、容量アラート閾値の未設定が原因の可能性が高いと判断されました。既存の監査ログが削除されずに保持され、ストレージの容量が逼迫を招いている状態です。', TIMESTAMP WITH TIME ZONE '2020-04-10T09:11:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00336', 'INC-2020-00228', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T09:26:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T10:26:12+09:00', '【初期対応】【ストレージ・容量障害】監査ログ削除未実行の初期対応', '本件に関して、運用 一郎は直ちに古い監査ログ削除ジョブの実行を手配しました。また、容量アラート閾値の設定を見直し、今後の再発防止策として運用フローの整備を行うことを決定しました。さらなる調査と対策を講じ、バッチ処理の安定性を確保することが求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00230', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-09T06:21:26+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T06:51:26+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2023-10-01T14:30:00+09:00に、株式会社ストッククラウドのMercuryにおいて、Webhook再送が嵐状になり、顧客側で拒否される事象が発生しました。エラーコードはEDI-02-00230です。発生契機は定例リリース直後であり、影響範囲は単一店舗に留まりました。技術詳細においては、Webhook再送が過剰に発生したため、先方により受信を拒否されました。推定される原因としては、再送間隔の指数バックオフが未設定であったことが考えられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00230', 'INC-2020-00230', '発生から約30分後に状況を確認したところ、Webhook再送が大量に行われていることが判明しました。原因として再送間隔の指数バックオフ未設定が疑われ、早急な対応が必要とされました。定例リリースに伴う設定ミスが推測され、API連携・EDIに影響を及ぼしていると考えられます。現時点での情報を基に、再設定の方針を検討中です。', '発生から約30分後に状況を確認したところ、Webhook再送が大量に行われていることが判明しました。原因として再送間隔の指数バックオフ未設定が疑われ、早急な対応が必要とされました。定例リリースに伴う設定ミスが推測され、API連携・EDIに影響を及ぼしていると考えられます。現時点での情報を基に、再設定の方針を検討中です。', TIMESTAMP WITH TIME ZONE '2020-04-10T06:51:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00338', 'INC-2020-00230', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T07:06:26+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T08:06:26+09:00', '【初期対応】【CLU-07】Webhook再送嵐', '発生を確認後、運用部の運用 一郎が直ちに調査を開始しました。顧客側に影響が及んでいるため、再送の制限をかける措置を講じると共に、再送間隔に指数バックオフを設定する作業を進めました。顧客への説明も必要と判断し、早急に連絡を取る準備を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00232', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-02T03:33:42+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T03:48:42+09:00', '【障害報告】【CLU-08】MFAデバイス不一致', '2020年4月2日03時33分42秒、株式会社ストッククラウドのMercuryサービスにおいて、運用者の作業ミスによるアクセス障害が発生しました。症状としては、MFAデバイス登録不一致により、ログインが不可となりました。発生契機は顧客オンボーディング当日であり、運用コンソール（ゾーンB）および認証サービスに影響を及ぼしました。エラーコードはAUTH-03-00232です。検知は2020年4月2日03時46分42秒で、発見者は運用部の運用 一郎です。影響範囲は単一店舗のみで、MFAシードの再発行未同期が推定原因と考えられています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00232', 'INC-2020-00232', '障害発生後、MFAデバイスの登録状況を確認しました。運用コンソールにおいて複数のMFAデバイスが登録されていることが確認されましたが、特定のデバイスが同期されていないことが判明しました。MFAシードが再発行される際、同期が行われなかったために、ユーザーはログインができなくなったと推測されます。今後の対策として、MFAデバイスの管理手順を見直し、再発防止策を検討する必要があります。', '障害発生後、MFAデバイスの登録状況を確認しました。運用コンソールにおいて複数のMFAデバイスが登録されていることが確認されましたが、特定のデバイスが同期されていないことが判明しました。MFAシードが再発行される際、同期が行われなかったために、ユーザーはログインができなくなったと推測されます。今後の対策として、MFAデバイスの管理手順を見直し、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-03T03:48:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00341', 'INC-2020-00232', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T04:03:42+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T05:03:42+09:00', '初動対応', 'インシデント発生から13分後に問題を検知したため、迅速に対策を講じました。運用部の運用 一郎が中心となり、影響を受けた顧客に対して状況説明を行い、ログインの復旧に向けて必要な手続きを実施しました。また、MFAデバイスの登録状況を確認し、正しいデバイスへの切り替えを行う手順を整えました。初期対応の結果、問題の影響を最小限に抑えることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00342', 'INC-2020-00232', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T05:33:42+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T06:33:42+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00233', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-25T20:19:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T22:19:12+09:00', '【障害報告】【棚卸・POS突合障害】店舗間転送未反映', '2020年4月25日20時19分12秒に発生した棚卸突合失敗のインシデントに関しまして、顧客店舗POSにおいて、店舗間在庫転送が送信側のみ減算されるという症状が確認されました。この問題の発生契機は新規店舗追加の初日であり、影響範囲は同一顧客の全店舗に及びます。推定原因としては、転送トランザクションの二相コミット失敗が考えられます。エラーコードはINV-08-00233です。検知は2020年4月25日22時11分12秒に行われ、発見者は営業部の花子でございます。今後、お客様への影響を最小限に抑えるため、迅速な対応を行います。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00233', 'INC-2020-00233', '本件につきまして、調査を進めた結果、新規店舗追加の初日における店舗間在庫転送が送信側のみ減算される現象が発生していることが確認されました。これに関連して、転送トランザクションの二相コミット失敗が原因である可能性が高いと推察されます。今後、詳細な原因分析と対応策を講じる必要があります。', '本件につきまして、調査を進めた結果、新規店舗追加の初日における店舗間在庫転送が送信側のみ減算される現象が発生していることが確認されました。これに関連して、転送トランザクションの二相コミット失敗が原因である可能性が高いと推察されます。今後、詳細な原因分析と対応策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-26T22:19:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00343', 'INC-2020-00233', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-25T22:34:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T23:34:12+09:00', '初期対応', 'インシデント発生後、即時に技術チームが対応にあたりました。現象の確認及び影響範囲の特定を行い、関係部門との連携を強化しました。今後、店舗間在庫転送に関するトランザクションの監視を強化し、再発防止策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00344', 'INC-2020-00233', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T00:04:12+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T01:04:12+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00235', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-27T20:09:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T20:39:44+09:00', '【障害報告】【CLU-07】EDI在庫差分遅延', '2023-10-01T14:30:00+09:00に発生したインシデントについて報告いたします。本事象は、株式会社ストッククラウドが提供するMercuryにおいて、マスター設定ミスによる在庫登録失敗を引き起こしました。具体的には、EDI在庫差分ファイルの反映が2時間遅延し、同一顧客の全店舗に影響を及ぼしました。発生契機としては、データ移行バッチ実行中にEDIキューの優先度設定誤りが疑われます。この問題は、2023-10-01T14:55:00+09:00に検知されました。影響を受けたエラーコードはEDI-01-00235です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00235', 'INC-2020-00235', 'インシデントの調査において、データ移行バッチ実行中のEDI在庫差分ファイルの反映遅延が確認されました。原因として、EDIキューの優先度設定誤りが特定されました。この誤りにより、在庫差分情報の処理が遅延し、影響範囲は同一顧客の全店舗に及びました。今後、同様の問題が発生しないよう、優先度設定の見直しと監視体制の強化が必要です。', 'インシデントの調査において、データ移行バッチ実行中のEDI在庫差分ファイルの反映遅延が確認されました。原因として、EDIキューの優先度設定誤りが特定されました。この誤りにより、在庫差分情報の処理が遅延し、影響範囲は同一顧客の全店舗に及びました。今後、同様の問題が発生しないよう、優先度設定の見直しと監視体制の強化が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-28T20:39:44+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00347', 'INC-2020-00235', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T20:54:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T21:54:44+09:00', '初期対応', '2023-10-01T14:40:00+09:00に初期対応を実施しました。問題の検知後、迅速にエンジニアチームが集まり、EDIキューの設定を確認しました。設定に誤りがあることを確認し、修正作業に着手しました。影響を受けた顧客への説明や補償についても検討を始めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00348', 'INC-2020-00235', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T22:24:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T23:24:44+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00237', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-01T14:17:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T16:17:55+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2020年4月1日14時17分55秒、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSにてShift_JIS変換による商品名の文字化けが発生しました。発見者は営業部の花子であり、データ移行バッチ実行中にこの事象が確認されました。発生契機はデータ移行バッチの実行であり、影響は単一店舗に限定されています。確認されたエラーコードはEDI-07-00237であり、原因として文字コード変換テーブルの誤選択が推定されています。この事象は、顧客に対して影響を及ぼさない可能性が高いですが、今後の対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00237', 'INC-2020-00237', '発生した文字化けの原因調査を行ったところ、データ移行バッチ実行中にShift_JIS変換処理が誤って選択されたため、商品名が正しく変換されず文字化けが発生したことが確認されました。具体的な原因としては、文字コード変換テーブルの誤選択が挙げられます。今後は、変換処理の見直し及びテーブル選択のプロセスを改善する必要があります。', '発生した文字化けの原因調査を行ったところ、データ移行バッチ実行中にShift_JIS変換処理が誤って選択されたため、商品名が正しく変換されず文字化けが発生したことが確認されました。具体的な原因としては、文字コード変換テーブルの誤選択が挙げられます。今後は、変換処理の見直し及びテーブル選択のプロセスを改善する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-02T16:17:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00351', 'INC-2020-00237', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-01T16:32:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T17:32:55+09:00', '【初期対応】文字コード変換事故', '初期対応として、影響を受けた店舗の関係者に対し、事象の発生を通知しました。また、データ移行バッチの実行を一時停止し、原因分析を行うためのチームを編成しました。次に、変換処理におけるテーブル選択の見直しを進め、再発防止策を検討することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00352', 'INC-2020-00237', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-01T18:02:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T19:02:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00239', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-22T13:41:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T15:41:20+09:00', '【障害報告】【データ同期・整合性障害】クロスリージョンレプリケーション', '2023-10-05に発生したインシデントでは、顧客店舗POSにおけるデータ同期に関する問題が報告されました。特定リージョンのユーザーに対してクロスリージョン複製が片系のみ更新される現象が確認されました。エラーコードはSYNC-07-00239で、インフラメンテナンス明けに発生。発見者は営業部の花子で、検知には153分を要しました。データの整合性に影響を与え、業務に支障をきたす可能性があるため、早急な対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00239', 'INC-2020-00239', 'インフラメンテナンス後に発生したクロスリージョン複製の問題について調査を実施しました。リージョンルーティングの誤設定が原因として疑われ、特定のリージョンにおいてデータの同期に失敗しました。影響範囲は特定のユーザーのみに限定されましたが、迅速な解決が必要です。', 'インフラメンテナンス後に発生したクロスリージョン複製の問題について調査を実施しました。リージョンルーティングの誤設定が原因として疑われ、特定のリージョンにおいてデータの同期に失敗しました。影響範囲は特定のユーザーのみに限定されましたが、迅速な解決が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-23T15:41:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00354', 'INC-2020-00239', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-22T15:56:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T16:56:20+09:00', '初期対応', '本事象に対する初期対応として、リージョンルーティングの設定を確認し、誤設定がないか精査を行います。また、影響を受けたユーザーへの情報提供を行い、今後の対応について周知します。データ同期の整合性を確保し、再発防止策を講じることが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00240', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-06T18:41:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T19:11:53+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2020年04月06日18時41分53秒に、株式会社ストッククラウドのMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生。データ移行バッチ実行中にShift_JIS変換を行った際、商品名が文字化けする事象が確認された。原因として文字コード変換テーブルの誤選択が考えられる。影響範囲は単一店舗に限られ、エラーコードはEDI-07-00240である。2020年04月06日19時18分53秒に検知され、検知まで37分の時間を要した。この問題はMercury AWS APのゾーンAに影響を与え、EDIアダプタも関与している。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00240', 'INC-2020-00240', '本インシデントは、データ移行バッチ実行中に発生した。Shift_JIS変換で商品名が文字化けし、影響範囲は単一店舗にとどまった。現在、文字コード変換テーブルの誤選択が原因として挙げられているが、詳細な確認が必要である。今後、変換処理の見直しを行い、再発防止策を講じる必要がある。', '本インシデントは、データ移行バッチ実行中に発生した。Shift_JIS変換で商品名が文字化けし、影響範囲は単一店舗にとどまった。現在、文字コード変換テーブルの誤選択が原因として挙げられているが、詳細な確認が必要である。今後、変換処理の見直しを行い、再発防止策を講じる必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-07T19:11:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00355', 'INC-2020-00240', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T19:26:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T20:26:53+09:00', '【初期対応】【API連携・EDI障害】文字コード変換事故への初動対応', '初期対応として、運用部の運用 一郎がこの問題に対処。まず、影響を受けたデータを特定し、速やかにバックアップとリカバリーの手続きを実施。次に、文字コード変換テーブルの設定を確認し、誤選択がないかを検証した。影響を受けた店舗に対しては、状況を説明し、適切な対応策を提示した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00241', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-13T02:00:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T03:00:59+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2020年4月13日02時00分59秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客拠点NWにおけるネットワーク障害が発生しました。本障害により、店舗VPN経由でSaaSに到達できず、影響範囲は単一店舗のみとなっております。発生契機として、顧客オンボーディング当日に問題が顕在化しました。エラーコードはNW-01-00241であり、拠点FWのルール変更が推定される原因です。検知は03時23分59秒に行われ、約83分後の確認となりました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00241', 'INC-2020-00241', '調査の結果、店舗VPN経由でSaaSに到達できない原因として、拠点FWのルール変更が疑われます。この問題が顧客オンボーディング当日に発生したことから、設定の見直しが必要と考えられます。今後は、顧客のネットワーク環境をより慎重に確認し、問題の未然防止に努めます。', '調査の結果、店舗VPN経由でSaaSに到達できない原因として、拠点FWのルール変更が疑われます。この問題が顧客オンボーディング当日に発生したことから、設定の見直しが必要と考えられます。今後は、顧客のネットワーク環境をより慎重に確認し、問題の未然防止に努めます。', TIMESTAMP WITH TIME ZONE '2020-04-14T03:00:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00356', 'INC-2020-00241', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-13T03:15:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T04:15:59+09:00', '【初期対応】店舗VPN到達不可', '初期対応として、顧客の拠点NWの状態を確認し、拠点VPNゲートウェイの設定を見直しました。問題の特定に向けて、拠点FWのルールについても調査を行い、必要に応じて設定を更新する準備を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00357', 'INC-2020-00241', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-13T04:45:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T05:45:59+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00242', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-21T23:04:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T23:19:53+09:00', '【障害報告】【運用操作・権限障害】手動設定編集事故', '2020年4月21日23時04分53秒、株式会社ストッククラウドの運用コンソールにおいて、設定ファイルの手動編集が原因で必須キーが欠落しました。この事象はインフラメンテナンス明けに発生し、サービス全体の一部機能に影響を及ぼしました。23時15分53秒に検知され、運用部の運用 一郎が発見しました。エラーコードはOPS-07-00242です。手動編集による設定ファイルの不整合が疑われ、運用操作・権限障害が発生しました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00242', 'INC-2020-00242', '調査の結果、インフラメンテナンス明けに行われた設定ファイルの手動編集が原因で必須キーが欠落したことが確認されました。設定ファイルの手動編集ミスが疑われ、影響範囲はサービス全体の一部機能に及びました。運用コンソール（ゾーンA）及び設定管理DBに影響を与えました。', '調査の結果、インフラメンテナンス明けに行われた設定ファイルの手動編集が原因で必須キーが欠落したことが確認されました。設定ファイルの手動編集ミスが疑われ、影響範囲はサービス全体の一部機能に及びました。運用コンソール（ゾーンA）及び設定管理DBに影響を与えました。', TIMESTAMP WITH TIME ZONE '2020-04-22T23:19:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00358', 'INC-2020-00242', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T23:34:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T00:34:53+09:00', '【初期対応】【運用操作・権限障害】手動設定編集事故', '初期対応として、運用部は設定ファイルのバックアップから正しい状態に戻す作業を行いました。また、運用コンソールの監視を強化し、手動編集に関する運用手順の見直しを実施しました。今後、手動編集時には必須キーの確認を義務化し、作業ミスを防止するための教育も行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00244', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-08T05:35:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T06:05:25+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2023-10-01T10:00:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00244', 'INC-2020-00244', '現在、冪等キーが重複している状況を確認。冪等キー生成ロジックに問題がある可能性が高い。定例リリースによって新しい変更が導入されたため、これが原因で冪等キーが適切に生成されていないか、既存のキーと衝突していることが考えられる。詳細なログ解析を進める必要がある。', '現在、冪等キーが重複している状況を確認。冪等キー生成ロジックに問題がある可能性が高い。定例リリースによって新しい変更が導入されたため、これが原因で冪等キーが適切に生成されていないか、既存のキーと衝突していることが考えられる。詳細なログ解析を進める必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-09T06:05:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00361', 'INC-2020-00244', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T06:20:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T07:20:25+09:00', '初動対応', '発生直後に運用部が対応を開始し、冪等キー重複の影響を受けている店舗を特定。影響を受けた店舗には速やかに在庫登録の手動対応を実施した。さらに、冪等キーが重複している原因を特定するため、開発部門との連携を強化し、調査を開始した。今後の対応については、問題解決後に再発防止策を検討する。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00362', 'INC-2020-00244', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T07:50:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T08:50:25+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00245', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-14T20:27:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T20:42:52+09:00', '【障害報告】【CLU-10】トレースサンプリング過少', '株式会社ストッククラウドのサービスMercuryにおいて、2023-10-01T14:30:00+09:00に運用者の作業ミスによるアクセス障害が発生いたしました。症状として、分散トレースのサンプリング率が過少となり、原因特定が困難な状況に陥っています。影響範囲は主に運用部門に及んでおり、運用コンソール（ゾーンA）およびトレーシング基盤に関連する機能に制約が生じています。発生の契機としては、定例リリース直後に起因するものと考えられます。このままでは監視・可用性障害が懸念されるため、早急な対処が求められています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00245', 'INC-2020-00245', '本インシデントに関する調査を行った結果、分散トレースのサンプリング率が過少であることが確認されました。この原因として、サンプリング率の本番設定誤りを疑っています。運用者による設定のミスが影響を及ぼしており、迅速な修正が必要です。関係者にはこの問題の重大性を周知し、再発防止策を講じる必要があります。', '本インシデントに関する調査を行った結果、分散トレースのサンプリング率が過少であることが確認されました。この原因として、サンプリング率の本番設定誤りを疑っています。運用者による設定のミスが影響を及ぼしており、迅速な修正が必要です。関係者にはこの問題の重大性を周知し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-15T20:42:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00363', 'INC-2020-00245', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T20:57:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T21:57:52+09:00', '【初期対応】【CLU-10】トレースサンプリング過少', '発生直後より、運用部門の運用 一郎が状況の把握と対応を開始しました。エラーコードMON-05-00245を記録し、原因としてサンプリング率の本番設定誤りが疑われるため、設定内容の確認と修正作業に着手します。また、関係者への連絡を行い、問題の共有を図ります。早急に行動を起こし、監視・可用性障害の影響を最小限に抑えるよう努めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00364', 'INC-2020-00245', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T22:27:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T23:27:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00247', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-13T22:52:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T23:37:17+09:00', '【障害報告】【ストレージ・容量障害】ログローテ停止', '2020年04月13日22時52分17秒、株式会社ストッククラウドのMercury AWS Storageにおいて、ストレージ溢れの事象が発生した。ログローテーションが停止し、容量を圧迫していることが確認された。発生契機はデータ移行バッチ実行中であった。運用部の運用 一郎がこの問題を発見し、影響範囲はバッチ処理のみでオンラインには影響がなかった。エラーコードはSTR-02-00247であり、推定原因として一時ファイルの削除バッチ停止が考えられる。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00247', 'INC-2020-00247', '発生から59分後の2020年04月13日23時51分17秒に問題が検知された。調査の結果、データ移行バッチ実行中にログローテーションが停止したことが容量を圧迫している原因であると確認された。一時ファイルの削除バッチが停止している可能性が高く、これが根本原因と推測される。今後、バッチ処理の監視体制を強化し、同様の障害を防止する必要がある。', '発生から59分後の2020年04月13日23時51分17秒に問題が検知された。調査の結果、データ移行バッチ実行中にログローテーションが停止したことが容量を圧迫している原因であると確認された。一時ファイルの削除バッチが停止している可能性が高く、これが根本原因と推測される。今後、バッチ処理の監視体制を強化し、同様の障害を防止する必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-14T23:37:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00366', 'INC-2020-00247', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T23:52:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T00:52:17+09:00', '【初期対応】【ストレージ・容量障害】ログローテ停止への初期対応', '発生した問題に対し、運用部は直ちにログローテーションの再起動を試み、バッチ処理が正常に行われるように手配した。また、一時ファイルの削除バッチを再度起動し、ストレージの容量を回復させる作業を行った。この対応により、ストレージ容量は正常化し、以降のオンラインサービスに影響を及ぼさない状態に戻すことができた。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00250', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-21T03:55:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T04:25:49+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2020年4月21日03時55分49分頃、株式会社ストッククラウドのMercuryにおいて、利用者増による応答遅延が発生いたしました。この障害は、運用部門の死活監視システムにおいて、正常に稼働しているサーバーをDOWNと誤検知する事象が発生したことに端を発します。定例リリース直後に発生したことから、監視プローブのUser-Agentブロックが原因であると推定されます。影響範囲は運用部門のみであり、エラーコードはMON-01-00250となります。死活監視の誤検知により、運用部門の業務に支障をきたす恐れがありました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00250', 'INC-2020-00250', '発生契機として、定例リリース直後に死活監視が正常系をDOWNと誤検知したことを確認いたしました。監視プローブのUser-Agentブロックが影響を及ぼした可能性が高く、迅速な調査が必要です。特に、誤検知の原因を突き止めるためには、監視設定やプローブの動作確認を行う必要があります。今後の再発防止策を検討するため、詳細な調査を進めます。', '発生契機として、定例リリース直後に死活監視が正常系をDOWNと誤検知したことを確認いたしました。監視プローブのUser-Agentブロックが影響を及ぼした可能性が高く、迅速な調査が必要です。特に、誤検知の原因を突き止めるためには、監視設定やプローブの動作確認を行う必要があります。今後の再発防止策を検討するため、詳細な調査を進めます。', TIMESTAMP WITH TIME ZONE '2020-04-22T04:25:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00371', 'INC-2020-00250', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T04:40:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T05:40:49+09:00', '【初動対応】【監視・可用性障害】死活監視誤検知に対する初動対応', '初動対応として、運用部の一郎が直ちに死活監視の設定を確認し、正常系のサーバーの稼働状況を再確認いたしました。監視プローブの設定を見直し、User-Agentのブロック設定が誤っているかどうかを確認する作業を行いました。また、影響範囲についても運用部内で共有し、関連メンバーに対して注意喚起を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00254', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-05T13:23:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T14:23:22+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2023-10-10T10:00:00+09:00に発生した顧客側ネットワーク障害について調査を行った。発生日時は2023-10-10T10:00:00+09:00であり、検知は2023-10-10T10:36:00+09:00（検知まで36分）であった。症状としてはISP側BGP経路障害で複数拠点が同時不通となり、同一顧客の全店舗に影響が及んでいる。エラーコードNW-06-00254が発生している。発生契機はインフラメンテナンス明けであり、技術詳細としてはインフラメンテナンス明けにISP側BGP経路障害が確認され、複数拠点が同時不通となった。原因としてはISP側のBGP経路障害を疑っている。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00254', 'INC-2020-00254', 'この障害についての調査を行った結果、ISP側のBGP経路障害が原因で顧客の複数拠点が同時に不通となっていることが確認された。BGP経路障害により、顧客ネットワークへのアクセスが完全に遮断され、影響範囲は同一顧客の全店舗に及んでいる。ISPからの公式な回答を待っているところであり、早急な対応を進める必要がある。', 'この障害についての調査を行った結果、ISP側のBGP経路障害が原因で顧客の複数拠点が同時に不通となっていることが確認された。BGP経路障害により、顧客ネットワークへのアクセスが完全に遮断され、影響範囲は同一顧客の全店舗に及んでいる。ISPからの公式な回答を待っているところであり、早急な対応を進める必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-06T14:23:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00376', 'INC-2020-00254', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T14:38:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T15:38:22+09:00', '初期対応', 'インシデント発生後、営業部の花子が顧客に連絡を取り、状況の確認を行った。顧客からはネットワークが全く利用できないとの報告があり、障害の深刻さが確認された。ISP側に対しても早急に連絡を行い、BGP経路障害の修正状況を確認するよう指示を出した。顧客への情報提供を行い、状況が改善され次第、再度の連絡を約束した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00255', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-01T14:39:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T16:39:09+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2020-04-01 14:39:09 に発生した棚卸突合失敗に関するインシデントです。この問題により、顧客店舗POS の読取レプリカ遅延が発生し、在庫照会が古い値を表示していました。発見者は営業部の花子であり、15:22:09 に検知されました。大規模セール開始直前に発生したため、特定リージョンのユーザーに影響が及びました。エラーコードは SYNC-02-00255 です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00255', 'INC-2020-00255', 'インシデントの調査では、レプリケーション遅延の監視閾値を超過していたことが確認されました。古い値の在庫照会が特定の顧客店舗POS に影響を与え、データ同期・整合性の障害が発生していました。発生した原因を特定するために、システムのログを分析し、レプリカ遅延の影響範囲を確認しました。', 'インシデントの調査では、レプリケーション遅延の監視閾値を超過していたことが確認されました。古い値の在庫照会が特定の顧客店舗POS に影響を与え、データ同期・整合性の障害が発生していました。発生した原因を特定するために、システムのログを分析し、レプリカ遅延の影響範囲を確認しました。', TIMESTAMP WITH TIME ZONE '2020-04-02T16:39:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00377', 'INC-2020-00255', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-01T16:54:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T17:54:09+09:00', '初期対応の実施', '初期対応として、営業部の花子が状況を把握し、影響を受けた顧客店舗に対して通知を行いました。また、レプリケーション遅延の原因を調査するために、技術チームにエスカレーションし、システムのモニタリングを強化しました。問題の解決に向けて、迅速に対応を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00259', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-25T20:24:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T20:54:14+09:00', '【障害報告】【認証・セッション障害】Cookie SameSite拒否', '2020年5月1日、株式会社ストッククラウドが提供するMercuryにおいて、Cookie SameSite設定の影響により埋込画面が認証不可となる事象が発生しました。この問題は、運用部の運用 一郎によって発見され、影響範囲は単一店舗のVenus Azure APに限定されています。発生の契機は定例リリース直後であり、エラーコードはAUTH-06-00259です。技術的には、SameSite属性変更の影響であると推測されます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00259', 'INC-2020-00259', '運用 一郎が発見したこの障害は、定例リリース直後に発生しました。CookieのSameSite設定が原因となり、埋込画面での認証ができなくなっている状況です。影響を受けているコンポーネントはVenus Azure AP（ゾーンA）およびセッションストアであり、迅速な原因特定と対応が求められています。', '運用 一郎が発見したこの障害は、定例リリース直後に発生しました。CookieのSameSite設定が原因となり、埋込画面での認証ができなくなっている状況です。影響を受けているコンポーネントはVenus Azure AP（ゾーンA）およびセッションストアであり、迅速な原因特定と対応が求められています。', TIMESTAMP WITH TIME ZONE '2020-04-26T20:54:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00383', 'INC-2020-00259', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T21:09:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T22:09:14+09:00', '【初期対応】【認証・セッション障害】Cookie SameSite拒否', '運用 一郎からの報告を受け、直ちに調査を開始しました。CookieのSameSite設定に関する技術的な確認を行い、定例リリース後に実施された変更が影響していることを確認しました。迅速に修正対応を行い、再発防止のための対策を検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00384', 'INC-2020-00259', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T22:39:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T23:39:14+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00260', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-04T16:19:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T16:49:21+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2020年4月5日、株式会社ストッククラウドのMercuryサービスにおいて、分散トランザクションがタイムアウトし片側のみコミットされる事象が発生しました。本障害は、全テナントに波及する影響を及ぼしました。発生の契機は、大規模セール開始直前であり、通常以上のトランザクション量が予測される中での事象でした。推定原因として2PCタイムアウト設定の過短が考えられ、今後の対策が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00260', 'INC-2020-00260', '本障害の調査においては、分散トランザクションがタイムアウトした際のログを確認しました。具体的には、Mercury AWS APでのトランザクション処理が正常に完了せず、片側がコミットされたが他方はロールバックされたことが確認されました。この原因として、2PCタイムアウト設定が短すぎたことが明らかになりました。今後は、この設定の見直しを行う必要があります。', '本障害の調査においては、分散トランザクションがタイムアウトした際のログを確認しました。具体的には、Mercury AWS APでのトランザクション処理が正常に完了せず、片側がコミットされたが他方はロールバックされたことが確認されました。この原因として、2PCタイムアウト設定が短すぎたことが明らかになりました。今後は、この設定の見直しを行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-05T16:49:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00385', 'INC-2020-00260', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-04T17:04:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T18:04:21+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウトへの初期対応', '障害発生後、運用部の運用 一郎は即座に関係者へ通知し、初期対応を開始しました。ログ分析を行い、タイムアウト発生の原因を特定するための調査を実施しました。また、全テナントへの影響を最小限に抑えるため、必要な対策を迅速に講じるよう指示を出しました。今後の再発防止策として、2PCタイムアウトの設定見直しと、トランザクション処理能力の向上を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00261', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-06T16:17:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T16:47:51+09:00', '【障害報告】【認証・セッション障害】ブルートフォース誤検知', '発生日時: 2020-04-08T16:17:51+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00261', 'INC-2020-00261', '調査の結果、ブルートフォース検知による正常IPの遮断が確認されました。特に、WAFに設定された検知閾値が過敏であることが、過剰な遮断を引き起こしている原因として考えられます。大規模セールを前にした特異なトラフィックが、さらにこの問題を悪化させた可能性があります。', '調査の結果、ブルートフォース検知による正常IPの遮断が確認されました。特に、WAFに設定された検知閾値が過敏であることが、過剰な遮断を引き起こしている原因として考えられます。大規模セールを前にした特異なトラフィックが、さらにこの問題を悪化させた可能性があります。', TIMESTAMP WITH TIME ZONE '2020-04-07T16:47:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00386', 'INC-2020-00261', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T17:02:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T18:02:51+09:00', '初期対応', '初期対応として、WAFの設定を見直し、検知閾値を適切なレベルに調整しました。正常IPの遮断を解除し、影響を受けたユーザーへの連絡を行いました。さらに、再発防止策として、ブルートフォース検知の設定改善を進める方針です。また、問題発生時の影響を最小限に抑えるための監視体制を強化することを検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00387', 'INC-2020-00261', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T18:32:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T19:32:51+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00263', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-04T17:43:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T18:13:51+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '2020年4月4日17時43分51秒に、株式会社ストッククラウドのMercuryサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。楽観ロック競合が多発し、更新失敗率が上昇しました。影響範囲は全テナントに波及し、大規模セール開始直前のタイミングで発生したため、顧客に大きな影響を与える可能性がありました。特に、Mercury AWS APにおける在庫登録APIに関しては、バージョンカラム更新ロジックの不備が原因として疑われます。検知は2020年4月4日18時14分51秒に行われ、31分後に問題が確認されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00263', 'INC-2020-00263', '調査の結果、楽観ロック競合が多発する原因として、バージョンカラム更新ロジックの不備が確認されました。この不備が原因で、同時に複数の更新が行われた際に競合が発生し、更新失敗が多発しました。全テナントに影響が及んだことから、早急な修正が必要となる事態です。今後の対策として、ロジックの見直しとテストを強化することが求められます。', '調査の結果、楽観ロック競合が多発する原因として、バージョンカラム更新ロジックの不備が確認されました。この不備が原因で、同時に複数の更新が行われた際に競合が発生し、更新失敗が多発しました。全テナントに影響が及んだことから、早急な修正が必要となる事態です。今後の対策として、ロジックの見直しとテストを強化することが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-05T18:13:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00389', 'INC-2020-00263', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-04T18:28:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T19:28:51+09:00', '初期対応', '初期対応として、運用部の運用 一郎が中心となり、影響を受けたシステムの調査を開始しました。状況を把握するために、関連するログを収集し、優先的に問題を特定するためのアプローチを取ることにしました。また、顧客への通知を行い、影響範囲を正確に伝えるための準備を進めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00264', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-06T23:07:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T00:07:11+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2023年10月10日、株式会社ストッククラウドのお客様において、店舗VPN経由でSaaSに到達できない事象が報告されました。発生時刻は23時07分であり、その後69分後に検知されました。この問題は単一店舗に影響を及ぼしており、特定の顧客拠点NWにおいて、拠点FWのルール変更が原因と考えられています。顧客オンボーディング当日に発生したため、迅速な対応が求められます。エラーコードはNW-01-00264です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00264', 'INC-2020-00264', '本事象について調査したところ、顧客オンボーディング当日に店舗VPN経由でSaaSに到達できない状態が確認されました。拠点FWのルール変更が影響している可能性が高く、これにより店舗側のVPN接続が妨げられていることが推測されます。', '本事象について調査したところ、顧客オンボーディング当日に店舗VPN経由でSaaSに到達できない状態が確認されました。拠点FWのルール変更が影響している可能性が高く、これにより店舗側のVPN接続が妨げられていることが推測されます。', TIMESTAMP WITH TIME ZONE '2020-04-08T00:07:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00390', 'INC-2020-00264', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T00:22:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T01:22:11+09:00', '【初動対応】【顧客ネットワーク障害】店舗VPN到達不可', '初動対応として、該当店舗のネットワーク接続を確認し、拠点FWの設定を見直しました。設定変更が行われた場合は、元の設定に戻す手続きを実施し、店舗VPN経由の接続が正常に行えることを確認する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00265', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-09T20:59:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T21:44:47+09:00', '【障害報告】【ストレージ・容量障害】開発ダンプ誤配置', '2023-10-05 15:30:00 に、株式会社ストッククラウド の Mercury サービスにおいて、開発環境ダンプが本番ボリュームを占有するというストレージ・容量障害が発生しました。障害の発生は 2023-10-05 15:30:00 で、約41分後の 2023-10-05 16:11:00 に検知されました。今回の障害は、データ移行バッチ実行中に開発環境ダンプの誤配置が原因と考えられます。この影響により、サービス全体の一部機能に障害が発生し、ユーザーの業務に支障をきたす事態となりました。エラーコードは STR-06-00265 です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00265', 'INC-2020-00265', '本障害は、2023-10-05 に発生したもので、運用部の運用 一郎が発見しました。調査の結果、データ移行バッチ実行中に開発環境ダンプが本番ボリュームを占有したことが確認されました。原因として開発環境ダンプの誤配置が疑われ、今後の対策として手順の見直しや環境の分離を検討しています。', '本障害は、2023-10-05 に発生したもので、運用部の運用 一郎が発見しました。調査の結果、データ移行バッチ実行中に開発環境ダンプが本番ボリュームを占有したことが確認されました。原因として開発環境ダンプの誤配置が疑われ、今後の対策として手順の見直しや環境の分離を検討しています。', TIMESTAMP WITH TIME ZONE '2020-04-10T21:44:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00391', 'INC-2020-00265', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T21:59:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T22:59:47+09:00', '【初期対応】【ストレージ・容量障害】開発ダンプ誤配置対応開始', '運用部の運用 一郎です。2023-10-05 16:15:00 に本障害の初期対応を開始しました。現在、開発環境ダンプの配置を確認し、必要なデータの移動を行っています。また、影響を受けたサービス全体の機能を復旧するための作業も進めています。対応が完了次第、再度連絡いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00392', 'INC-2020-00265', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T23:29:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T00:29:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
