INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00287', 'INC-2020-00287', '・調査開始日時: 2020-04-18T17:04:00+09:00
