INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00424', 'INC-2020-00287', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-18T18:52:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T19:52:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00292', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-13T19:16:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T19:46:58+09:00', '【障害報告】【在庫マスター設定障害】バーコード照合エラー', '2020年4月13日19時16分58秒に、株式会社ストッククラウドのMercuryにおいて、バーコードスキャン後に照合エラーで登録不可の事象が発生しました。この問題は新規店舗追加の初日に起きており、影響範囲は単一店舗のみで、エラーコードはMST-06-00292です。運用部の運用 一郎が発見し、検知まで38分を要しました。技術的には、Mercury AWS AP（ゾーンB）でのPOS連携アダプタに影響が及んでいると考えられます。原因としてはチェックディジット検証ロジックの誤設定が疑われます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00292', 'INC-2020-00292', '運用部の運用 一郎が発見したこの事象に関する調査を行いました。新規店舗追加の初日において、バーコードスキャン後に照合エラーが発生し、在庫の登録ができない状況となっています。影響を受けているのはMercury AWS AP（ゾーンB）であり、POS連携アダプタが関与しています。チェックディジット検証ロジックの設定ミスが原因である可能性が高く、詳細な調査が必要です。', '運用部の運用 一郎が発見したこの事象に関する調査を行いました。新規店舗追加の初日において、バーコードスキャン後に照合エラーが発生し、在庫の登録ができない状況となっています。影響を受けているのはMercury AWS AP（ゾーンB）であり、POS連携アダプタが関与しています。チェックディジット検証ロジックの設定ミスが原因である可能性が高く、詳細な調査が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-14T19:46:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00429', 'INC-2020-00292', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T20:01:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T21:01:58+09:00', '【初期対応】【在庫マスター設定障害】バーコード照合エラー', '運用部の運用 一郎が2020年4月13日19時54分58秒にこの事象を確認した時点で、即座に初期対応を開始しました。まずは、問題が発生したバーコードスキャンの環境を確認し、POS連携アダプタの設定を再確認しました。また、チェックディジット検証ロジックの設定ミスが原因であることを前提に対策を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00293', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-01T15:07:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T15:37:22+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2023-10-10T10:00:00+09:00 に、株式会社ストッククラウドのサービスMercuryにおいて、バルクAPIが部分失敗しロールバックが未完了となる事象が発生しました。発生契機はデータ移行バッチの実行中であり、影響範囲はサービス全体の一部機能に及びました。エラーコードはEDI-10-00293で、影響コンポーネントはMercury AWS AP（ゾーンA）にある在庫登録APIです。検知は2023-10-10T10:12:00+09:00で、検知までに12分の遅延が発生しました。技術詳細としては、データ移行バッチ実行中にバルクAPIが部分失敗し、ロールバックが未完了であることが確認されました。原因として部分成功時の補償トランザクション欠如が疑われます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00293', 'INC-2020-00293', '現在、事象の詳細な調査を行っています。バルクAPIの部分失敗が発生した原因を究明するために、データ移行プロセスのログを精査しています。特に部分成功時に補償トランザクションが実行されていない箇所があるかを確認し、再発防止策を検討しています。また、他のシステムとの連携状況も確認し、API連携・EDI障害の影響が及んでいる可能性について調査を進めています。', '現在、事象の詳細な調査を行っています。バルクAPIの部分失敗が発生した原因を究明するために、データ移行プロセスのログを精査しています。特に部分成功時に補償トランザクションが実行されていない箇所があるかを確認し、再発防止策を検討しています。また、他のシステムとの連携状況も確認し、API連携・EDI障害の影響が及んでいる可能性について調査を進めています。', TIMESTAMP WITH TIME ZONE '2020-04-02T15:37:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00430', 'INC-2020-00293', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T15:52:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T16:52:22+09:00', '初期対応', '発生事象を受けて、運用部の運用 一郎が即時対応を行い、バルクAPIの状態を確認しました。影響が出ているサービスについては、暫定的なロールバックを試みましたが、完全な回復には至りませんでした。なお、関係者への情報共有を行い、問題解決に向けたチームでの協議を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00295', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-09T22:37:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T00:37:27+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2020年4月9日22時37分27秒、株式会社ストッククラウドにおいて、顧客店舗POSでEDI経由の棚卸ファイル取込時に件数不一致が発生しました。この問題は2020年4月10日00時45分27秒に検知され、検知までに128分を要しました。発生契機はデータ移行バッチ実行中であり、影響範囲はバッチ処理のみでオンラインには影響がありませんでした。影響を受けたコンポーネントは顧客店舗POS（ゾーンB）とEDIアダプタです。原因としてEDI連携ファイルの文字コード不一致が考えられ、今後の対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00295', 'INC-2020-00295', '本インシデントについての調査を行いました。EDI経由の棚卸ファイル取込中に件数不一致が発生した原因として、EDI連携ファイルの文字コード不一致が指摘されています。影響はバッチ処理のみに留まり、オンラインサービスには影響を与えていません。引き続き、問題の根本原因を明らかにし、再発防止策を検討する必要があります。', '本インシデントについての調査を行いました。EDI経由の棚卸ファイル取込中に件数不一致が発生した原因として、EDI連携ファイルの文字コード不一致が指摘されています。影響はバッチ処理のみに留まり、オンラインサービスには影響を与えていません。引き続き、問題の根本原因を明らかにし、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T00:37:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00432', 'INC-2020-00295', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T00:52:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T01:52:27+09:00', '【初期対応】【棚卸・POS突合障害】EDI棚卸ファイル異常への初期対応', '初期対応として、影響を受けたEDI連携ファイルの確認を行い、文字コードの不一致が発生している可能性について調査を開始しました。また、データ移行バッチの実行状況を監視し、再発防止のための設定見直しも行うことを決定しました。関係各所への通知とともに、必要に応じてテスト環境での検証を行い、問題解決に向けたアプローチを進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00433', 'INC-2020-00295', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T02:22:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T03:22:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00296', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-20T03:52:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T05:52:28+09:00', '【障害報告】【CLU-07】APIキー期限切れ', '・発生日時: 2023-10-10T04:00:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00296', 'INC-2020-00296', '外部WMS APIキーの期限切れにより、API連携が停止しています。メンテナンスの結果、APIキーのローテーション手順が実施されていないことが原因である可能性があります。これにより、同一顧客の全店舗に影響が及んでいます。API連携・EDI関係の再確認が必要です。', '外部WMS APIキーの期限切れにより、API連携が停止しています。メンテナンスの結果、APIキーのローテーション手順が実施されていないことが原因である可能性があります。これにより、同一顧客の全店舗に影響が及んでいます。API連携・EDI関係の再確認が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-21T05:52:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00434', 'INC-2020-00296', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T06:07:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T07:07:28+09:00', '初期対応', 'APIキーの期限切れが確認され、速やかに再発行手続きに入ります。関係者には情報共有を行い、今後のメンテナンス時にAPIキーローテーション手順の実施を徹底するよう指示します。影響を受けた店舗への連絡も行い、API連携の復旧を急ぎます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00297', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-28T01:05:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T02:05:13+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2023-10-05 14:00:00に、株式会社ストッククラウドのお客様において顧客拠点NWで発生したネットワーク障害について報告いたします。症状としては、DNS解決成功後にTLS握手で接続が切断される現象が確認されました。エラーコードはNW-03-00297であり、同一顧客の全店舗に影響が及んでおります。発生契機はインフラメンテナンス明けであり、推定原因としてプロキシ証明書の期限切れが考えられます。この障害は2023-10-05 15:15:00に検知され、復旧作業が開始されました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00297', 'INC-2020-00297', '株式会社ストッククラウドの顧客ネットワークにおいて発生した障害の調査結果について報告いたします。技術詳細としては、インフラメンテナンス明けにDNS解決成功後にTLS握手で接続が切断されたことが確認されました。この原因を調査した結果、プロキシ証明書の期限切れが主な原因であると推測されます。今後は定期的な証明書の更新を行い、再発防止に努める必要があります。', '株式会社ストッククラウドの顧客ネットワークにおいて発生した障害の調査結果について報告いたします。技術詳細としては、インフラメンテナンス明けにDNS解決成功後にTLS握手で接続が切断されたことが確認されました。この原因を調査した結果、プロキシ証明書の期限切れが主な原因であると推測されます。今後は定期的な証明書の更新を行い、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-29T02:05:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00435', 'INC-2020-00297', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-28T02:20:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T03:20:13+09:00', '【初動対応】【顧客ネットワーク障害】TLS握手切断', '2023-10-05 14:05:00に障害の初動対応を開始しました。影響を受けた顧客に対して状況の説明と謝罪を行い、復旧作業を進める旨を通知しました。技術チームが直ちに原因調査に着手し、プロキシ証明書の期限切れについて確認を行いました。障害発生から検知までの時間を短縮するための監視体制の強化が求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00300', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-06T06:42:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T06:57:11+09:00', '【障害報告】【運用操作・権限障害】手動設定編集事故', '2020年4月6日06:42:11、株式会社ストッククラウドの運用コンソールにて、設定ファイル手動編集で必須キーが欠落し、サービス全体の一部機能に影響が生じた。この事象は、インフラメンテナンス明けに発生したものであり、運用 一郎が発見した。06:50:11に検知され、検知までに8分を要した。運用操作・権限障害の影響範囲には、運用コンソール（ゾーンA）および設定管理DBが含まれる。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00300', 'INC-2020-00300', 'このインシデントは、インフラメンテナンス明けに実施された設定ファイルの手動編集によって引き起こされた可能性がある。手動編集の際に必須キーが欠落した結果、運用コンソールにおけるサービスの一部機能が停止したと考えられる。原因究明のために、関係者へのヒアリングを実施し、手動編集のプロセスの見直しを行う必要がある。', 'このインシデントは、インフラメンテナンス明けに実施された設定ファイルの手動編集によって引き起こされた可能性がある。手動編集の際に必須キーが欠落した結果、運用コンソールにおけるサービスの一部機能が停止したと考えられる。原因究明のために、関係者へのヒアリングを実施し、手動編集のプロセスの見直しを行う必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-07T06:57:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00440', 'INC-2020-00300', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T07:12:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T08:12:11+09:00', '【初期対応】【運用操作・権限障害】手動設定編集事故', 'このインシデントに対して、運用チームは直ちに影響を受けた設定ファイルの復旧作業を開始した。手動編集ミスの解消のために、バックアップから設定ファイルを復元し、必要な必須キーを再設定した。また、運用 一郎が事象の発生状況を確認し、関係者に通知した。今後の再発防止策として、手動編集プロセスの標準化を検討する予定である。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00301', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-18T21:08:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T21:38:08+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2020年4月18日21時08分、株式会社ストッククラウドの運用部において、Venus Azure APからの同一アラートが短時間に数百件発報する事象が発生しました。この現象は、21時50分に検知され、運用部門のみが影響を受けました。発生契機は大規模セール開始直前であり、アラート抑制ルールが未設定であることが推定されます。アラート疲労により運用担当者の負担が増し、迅速な対応が困難となりました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00301', 'INC-2020-00301', '運用部門において発報された同一アラートが数百件に達した事象について調査を行いました。アラート抑制ルールの未設定が原因として考えられ、特に大規模セール開始前にこの問題が顕在化しました。対応策としては、抑制ルールの設定が急務であると結論付けられました。', '運用部門において発報された同一アラートが数百件に達した事象について調査を行いました。アラート抑制ルールの未設定が原因として考えられ、特に大規模セール開始前にこの問題が顕在化しました。対応策としては、抑制ルールの設定が急務であると結論付けられました。', TIMESTAMP WITH TIME ZONE '2020-04-19T21:38:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00441', 'INC-2020-00301', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T21:53:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T22:53:08+09:00', '【初期対応】【監視・可用性障害】アラート疲労の初期対応', '初期対応として、運用部は即座にアラート抑制ルールの未設定を確認しました。次に、発報されたアラートのログを収集し、影響範囲を特定しました。その後、システムの一時的な監視を強化し、必要に応じて手動での対応を行う体制を整えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00306', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-05T18:10:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T19:10:36+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2020年4月5日18時10分36秒に、株式会社ストッククラウドのネットワークサービスMercuryにおいて顧客側ネットワーク障害が発生しました。発生した症状は、SD-WANが劣化回線を選択し、遅延が増大するものでした。影響範囲は同一顧客の全店舗に及びました。具体的には、SD-WANポリシーの閾値設定誤りが推定原因とされています。大規模セール開始直前に発生したため、通常の業務に深刻な影響を及ぼしました。顧客拠点NW及び拠点VPNゲートウェイが影響を受け、顧客のビジネス運営に支障を来す事態となりました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00306', 'INC-2020-00306', '本障害の調査において、大規模セール開始直前の状況下でSD-WANが劣化回線を選択したことが判明しました。SD-WANポリシーの閾値設定に誤りがあり、正常な経路選択が行われなかったことが原因と考えられます。遅延の発生により、顧客に対して大きな影響を及ぼしました。この問題を解決するためには、SD-WANのポリシー設定の見直しと試験が急務です。', '本障害の調査において、大規模セール開始直前の状況下でSD-WANが劣化回線を選択したことが判明しました。SD-WANポリシーの閾値設定に誤りがあり、正常な経路選択が行われなかったことが原因と考えられます。遅延の発生により、顧客に対して大きな影響を及ぼしました。この問題を解決するためには、SD-WANのポリシー設定の見直しと試験が急務です。', TIMESTAMP WITH TIME ZONE '2020-04-06T19:10:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00448', 'INC-2020-00306', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T19:25:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T20:25:36+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '障害発生を受けて、営業部の花子が直ちに対応を開始しました。SD-WANの経路設定を確認し、劣化回線選択の原因となる設定を特定しました。迅速に対応することで、遅延を軽減し、顧客への影響を最小限に抑えることができました。今後はこのような問題が再発しないよう、定期的なシステムレビューを行い、設定の精度を高める必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00449', 'INC-2020-00306', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T20:55:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T21:55:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00307', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-16T08:17:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T08:47:54+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2023-10-10T08:17:54+09:00に、株式会社ストッククラウドのサービスMercuryにおいて、読取レプリカ遅延が発生し、在庫照会が古い値を表示する事象が確認されました。影響範囲は特定リージョンのユーザーのみで、エラーコードはSYNC-02-00307です。発生契機は大規模セール開始直前であり、レプリケーション遅延の監視閾値超過が推定原因として挙げられます。運用部の運用 一郎が発見し、08:46:54に検知しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00307', 'INC-2020-00307', '読取レプリカ遅延による在庫照会の古い値の表示が確認されました。この事象は、Mercury AWS AP（DRサイト）における読取専用レプリカのレプリケーション遅延が原因と考えられます。状況を詳しく確認した結果、レプリケーション遅延の監視閾値が超過していることが判明しました。早急に対応が必要です。', '読取レプリカ遅延による在庫照会の古い値の表示が確認されました。この事象は、Mercury AWS AP（DRサイト）における読取専用レプリカのレプリケーション遅延が原因と考えられます。状況を詳しく確認した結果、レプリケーション遅延の監視閾値が超過していることが判明しました。早急に対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-17T08:47:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00450', 'INC-2020-00307', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T09:02:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T10:02:54+09:00', '初期対応', '本事象を受けて、運用部は即座に状況を確認し、読取レプリカの監視を強化する措置を講じました。また、レプリケーション遅延が解消されるまで、在庫照会サービスの利用を制限する方針を検討しました。顧客への影響を最小限に抑えるため、適切な情報提供を実施することを優先します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00451', 'INC-2020-00307', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T10:32:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T11:32:54+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00308', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-23T16:55:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T17:25:02+09:00', '【障害報告】【在庫マスター設定障害】在庫APIタイムアウト', '2020年4月23日16時55分に発生した在庫登録APIのタイムアウトに関するインシデントを報告いたします。本インシデントは、在庫登録APIが30秒を超えてタイムアウトするという症状が発生し、特定のリージョンのユーザーに影響を及ぼしました。特に大規模セールの開始直前にこの問題が発生したことから、税率テーブルの不整合が推定原因として考えられます。運用部の運用 一郎がこの問題を発見し、検知までに44分を要しました。エラーコードはMST-05-00308であり、影響を受けたコンポーネントはMercury AWS AP（ゾーンA）の在庫登録APIです。今後の再発防止に向けた対策を講じる必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00308', 'INC-2020-00308', '本インシデントの調査において、在庫登録APIが30秒超でタイムアウトした原因として、税率テーブルの不整合が疑われています。特に大規模セール開始直前のタイミングで発生したため、急激なリクエスト増加が影響した可能性も考慮されます。これにより、特定リージョンのユーザーが影響を受け、円滑な在庫管理が阻害されたことがわかりました。詳細な原因分析と影響範囲の特定を継続的に行う必要があります。', '本インシデントの調査において、在庫登録APIが30秒超でタイムアウトした原因として、税率テーブルの不整合が疑われています。特に大規模セール開始直前のタイミングで発生したため、急激なリクエスト増加が影響した可能性も考慮されます。これにより、特定リージョンのユーザーが影響を受け、円滑な在庫管理が阻害されたことがわかりました。詳細な原因分析と影響範囲の特定を継続的に行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T17:25:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00452', 'INC-2020-00308', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T17:40:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T18:40:02+09:00', '【初期対応】【在庫マスター設定障害】', '初期対応として、運用部の運用 一郎が速やかに在庫登録APIの動作状況を確認し、問題を特定しました。エラーコードMST-05-00308が発生していることを確認し、直ちに税率テーブルの整合性をチェックする作業に着手しました。これにより、影響範囲の特定と再発防止策を早急に検討することができました。今後の対応策としては、税率テーブルの整合性を自動でチェックする仕組みの構築が必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00453', 'INC-2020-00308', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T19:10:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T20:10:02+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00309', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-21T14:46:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T16:46:40+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2020年4月21日14時46分40秒に、株式会社ストッククラウドのサービスMercuryにおいて、棚卸突合の失敗が発生しました。症状として、マスター更新と在庫が二重反映される事象が報告されています。定例リリース直後の発生で、影響範囲は同一顧客の全店舗に及びます。エラーコードはSYNC-01-00309です。検知は2020年4月21日17時09分40秒で、143分の遅延がありました。影響を受けたコンポーネントには、顧客店舗POS（Secondary）およびイベントバスが含まれています。この事象は、イベント順序の逆転配信が原因と推定されています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00309', 'INC-2020-00309', '本事象の調査を行った結果、定例リリース直後にマスター更新と在庫が二重反映されることが確認されました。特に、イベント順序の逆転配信が主な原因であると考えられます。この問題により、全店舗の在庫データの整合性が損なわれ、顧客に対する影響が懸念されます。現在、関連するイベント処理のフローを再確認し、根本原因を特定するための追加調査を進めています。', '本事象の調査を行った結果、定例リリース直後にマスター更新と在庫が二重反映されることが確認されました。特に、イベント順序の逆転配信が主な原因であると考えられます。この問題により、全店舗の在庫データの整合性が損なわれ、顧客に対する影響が懸念されます。現在、関連するイベント処理のフローを再確認し、根本原因を特定するための追加調査を進めています。', TIMESTAMP WITH TIME ZONE '2020-04-22T16:46:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00454', 'INC-2020-00309', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T17:01:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T18:01:40+09:00', '【初動対応】【データ同期・整合性障害】マスター在庫二重反映', '初動対応として、直ちに関連するシステムのログを取得し、イベント処理の流れを分析しました。二重反映の原因となるイベント順序の逆転について検討を行い、今後の対策を策定するための会議を設定しました。また、影響を受けた店舗に対しては、状況説明を行い、顧客対応の指示を出しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00310', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-28T09:30:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T11:30:47+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2023-10-01T10:15:00+09:00に、株式会社ストッククラウドのMercuryサービスにおいて棚卸突合失敗が発生しました。問題は顧客店舗POSに関連しており、発見者は営業部の花子です。この症状は読取レプリカ遅延で在庫照会が古い値を示すもので、特定リージョンのユーザーのみが影響を受けています。大規模セール開始直前に発生したため、レプリケーション遅延の監視閾値超過が原因である可能性があります。エラーコードはSYNC-02-00310です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00310', 'INC-2020-00310', '発生から検知までの時間は161分で、在庫照会に古い値が表示されていることが確認されました。調査の結果、レプリケーション遅延の監視閾値が超過していることが疑われました。特定リージョンのユーザーにのみ影響が及んでおり、読取専用レプリカが問題の原因と考えられます。この遅延がサービス全体にどのような影響を与えるかを調査中です。', '発生から検知までの時間は161分で、在庫照会に古い値が表示されていることが確認されました。調査の結果、レプリケーション遅延の監視閾値が超過していることが疑われました。特定リージョンのユーザーにのみ影響が及んでおり、読取専用レプリカが問題の原因と考えられます。この遅延がサービス全体にどのような影響を与えるかを調査中です。', TIMESTAMP WITH TIME ZONE '2020-04-29T11:30:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00455', 'INC-2020-00310', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-28T11:45:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T12:45:47+09:00', '初期対応', '問題が確認されたため、営業部の花子が即座にレプリケーションの状態を監視し、遅延の原因を特定する作業を開始しました。初期対応として、レプリケーションのリセットや監視閾値の見直しを行う予定です。また、影響を受けたユーザーに対して情報提供を行い、必要に応じて代替手段を案内する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00456', 'INC-2020-00310', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-28T13:15:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T14:15:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00312', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-07T03:16:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T05:16:41+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '株式会社ストッククラウドのサービスMercuryにおいて、2023-10-01T03:16:41+09:00に発生した棚卸突合失敗について報告いたします。顧客店舗POSにおいて発生した症状は、アウトボックステーブル滞留による通知遅延です。エラーコードはSYNC-05-00312であり、定例リリース直後に影響が出ております。この事象は2023-10-01T05:56:41+09:00に検知されました。現時点では、アウトボックスポーラーの停止が推定原因として考えられ、サービス全体の一部機能に影響を及ぼしております。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00312', 'INC-2020-00312', '本インシデントに関する調査を行った結果、アウトボックステーブルの滞留が確認されました。定例リリース直後の影響を受けており、アウトボックスポーラーが停止していることが通知遅延の原因と推定されます。この状態が続く限り、顧客店舗POSの正常な機能に支障を来す可能性があります。', '本インシデントに関する調査を行った結果、アウトボックステーブルの滞留が確認されました。定例リリース直後の影響を受けており、アウトボックスポーラーが停止していることが通知遅延の原因と推定されます。この状態が続く限り、顧客店舗POSの正常な機能に支障を来す可能性があります。', TIMESTAMP WITH TIME ZONE '2020-04-08T05:16:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00458', 'INC-2020-00312', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T05:31:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T06:31:41+09:00', '【初期対応】データ同期・整合性障害', '初期対応としまして、アウトボックスポーラーの状態を確認し、必要に応じて再起動を行います。また、影響を受けている顧客店舗POSへの通知を迅速に行うため、アウトボックスの状態をリアルタイムで監視する体制を構築します。今後の事象発生を防ぐため、追加調査と対策を速やかに進めてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00459', 'INC-2020-00312', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T07:01:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T08:01:41+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00316', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-14T08:52:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T09:22:16+09:00', '【障害報告】【性能・負荷障害】コネクションプール枯渇', '2020年4月14日08時52分、株式会社ストッククラウドのMercuryサービスにおいて、DBコネクションプール枯渇アラートが発報しました。この症状は、全テナントに波及する影響を及ぼしました。発生契機はキャンペーンによるアクセス急増であり、推定原因としてコネクションプールサイズ不足が考えられます。影響を受けたコンポーネントはVenus Azure AP（DRサイト）であり、接続プールに問題が発生しました。このインシデントは2020年4月14日09時18分に検知され、検知までに26分を要しました。エラーコードはPRF-03-00316です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00316', 'INC-2020-00316', '調査の結果、キャンペーンによるアクセス急増がDBコネクションプール枯渇の直接的な原因であることが確認されました。特に、コネクションプールサイズが不十分であったため、リクエスト処理が遅延し、結果として全テナントに影響を及ぼしました。今後の対策として、コネクションプールのサイズを見直す必要があります。', '調査の結果、キャンペーンによるアクセス急増がDBコネクションプール枯渇の直接的な原因であることが確認されました。特に、コネクションプールサイズが不十分であったため、リクエスト処理が遅延し、結果として全テナントに影響を及ぼしました。今後の対策として、コネクションプールのサイズを見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-15T09:22:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00465', 'INC-2020-00316', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T09:37:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T10:37:16+09:00', '初期対応', 'インシデント発生後、運用部の運用 一郎が迅速に対応しました。具体的には、DBコネクションプールのサイズを一時的に増加させ、処理能力を向上させるための作業を行いました。また、関連するログを収集し、アクセスのピーク時におけるトラフィックの動向を分析しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00319', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-23T23:49:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T01:49:51+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '・発生日時: 2023-10-15T10:00:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00319', 'INC-2020-00319', '本インシデントは、2023年10月15日に発生したCDCイベントの欠損により、下流倉庫が未更新となったことが原因です。特に、データ移行バッチ実行中にこの問題が発生しました。調査においては、CDCコネクタのオフセットが巻き戻されている可能性があることが判明しました。今後の対策として、CDCイベントの監視とデータ同期の整合性チェックを強化する必要があります。', '本インシデントは、2023年10月15日に発生したCDCイベントの欠損により、下流倉庫が未更新となったことが原因です。特に、データ移行バッチ実行中にこの問題が発生しました。調査においては、CDCコネクタのオフセットが巻き戻されている可能性があることが判明しました。今後の対策として、CDCイベントの監視とデータ同期の整合性チェックを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-25T01:49:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00468', 'INC-2020-00319', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-24T02:04:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T03:04:51+09:00', '初期対応', '本インシデントに対する初期対応を行いました。まず、発生したCDCイベントの欠損についてログを確認し、影響を受けたバッチ処理を停止しました。次に、データ移行バッチのオフセット設定を確認し、正常な状態に戻すための修正作業を開始しました。影響を受けた顧客店舗POSについても、必要なデータを手動で更新する手順を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00320', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-10T20:05:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T21:05:23+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '・発生日時: 2023-10-01T14:30:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00320', 'INC-2020-00320', '調査を開始したところ、DNSリゾルバの設定に問題があり、TTLの値が期待されるものと異なっていることが判明しました。これにより、古いIPアドレスがキャッシュされ続け、最新のIP情報が反映されない状況が発生しています。各ネットワークコンポーネントを詳細に確認し、設定の見直しを行う必要があります。', '調査を開始したところ、DNSリゾルバの設定に問題があり、TTLの値が期待されるものと異なっていることが判明しました。これにより、古いIPアドレスがキャッシュされ続け、最新のIP情報が反映されない状況が発生しています。各ネットワークコンポーネントを詳細に確認し、設定の見直しを行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T21:05:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00469', 'INC-2020-00320', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T21:20:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T22:20:23+09:00', '【初期対応】【顧客ネットワーク障害】DNSキャッシュ汚染', '初期対応として、DNSリゾルバのTTL設定を確認し、適切な値に修正する作業を実施しました。また、DNSキャッシュのクリアを行い、正しいIP情報が返却されることを確認しました。影響を受けた店舗においては、問題が解決した旨を報告しました。引き続き、他の関連するネットワークコンポーネントも監視し、必要に応じて追加対応を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00325', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-04T06:27:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T06:57:21+09:00', '【障害報告】【在庫マスター設定障害】商品同期全件失敗', '2023年10月01日、株式会社ストッククラウドのサービスMercuryにおいて、商品マスター同期後に在庫登録が全件失敗する事象が発生いたしました。発生時刻は06:27:21であり、検知までに39分を要しました。発見者は運用部の運用 一郎でございます。影響範囲はサービス全体の一部機能に及び、エラーコードはMST-04-00325となります。発生契機は顧客オンボーディング当日であり、影響コンポーネントはMercury AWS AP（ゾーンB）および商品マスターDBであります。技術的な詳細としては、顧客オンボーディング当日に商品マスター同期後に在庫登録が全件失敗する現象が確認され、原因としてカテゴリ階層の循環参照が疑われております。今後の対応が必要であると考えております。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00325', 'INC-2020-00325', '今回の障害に関する調査を実施いたしましたところ、商品マスター同期後に在庫登録が全件失敗する現象が発生した原因として、カテゴリ階層の循環参照が特定されました。この循環参照が原因で、在庫情報が正しく処理されず、全ての登録が失敗する事態となったものと考えられます。影響を受けたサービス機能は、最も重要な在庫管理機能であり、迅速な対応が求められます。再発防止策として、カテゴリ階層の設定精査及びシステムの見直', '今回の障害に関する調査を実施いたしましたところ、商品マスター同期後に在庫登録が全件失敗する現象が発生した原因として、カテゴリ階層の循環参照が特定されました。この循環参照が原因で、在庫情報が正しく処理されず、全ての登録が失敗する事態となったものと考えられます。影響を受けたサービス機能は、最も重要な在庫管理機能であり、迅速な対応が求められます。再発防止策として、カテゴリ階層の設定精査及びシステムの見直しを提案いたします。', TIMESTAMP WITH TIME ZONE '2020-04-05T06:57:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00476', 'INC-2020-00325', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-04T07:12:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T08:12:21+09:00', '【対応ログ】【在庫マスター設定障害】商品同期全件失敗', '2023年10月01日、運用部の運用 一郎が障害の発生を確認し、関連するログの解析を開始しました。初期調査において、商品マスター同期後の在庫登録失敗の原因を特定するため、システム構成および設定内容の確認を行いました。調査の結果、カテゴリ階層における循環参照が影響していることが明らかとなり、迅速に開発チームへ情報共有を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00477', 'INC-2020-00325', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-04T08:42:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T09:42:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00328', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-01T15:44:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T16:29:08+09:00', '【障害報告】【ストレージ・容量障害】オブジェクトライフサイクル誤り', '2020年4月1日15時44分、株式会社ストッククラウドのMercuryサービスにおいてストレージ溢れが発生しました。発生場所はMercury AWS Storageで、不要オブジェクトが削除されず容量が増加しています。推定原因はライフサイクルポリシーの適用漏れであり、定例リリース直後に発生したため、サービス全体の一部機能に影響を及ぼしています。エラーコードはSTR-09-00328で、運用部の運用 一郎が発見者です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00328', 'INC-2020-00328', '本事象の調査を実施した結果、定例リリース直後に不要オブジェクトが削除されなかったことが確認されました。ライフサイクルポリシーの適用漏れが疑われ、当該ポリシーの設定や適用状況を詳細に確認する必要があります。今後の対策としては、ライフサイクルポリシーの再確認と運用手順の見直しを行う予定です。', '本事象の調査を実施した結果、定例リリース直後に不要オブジェクトが削除されなかったことが確認されました。ライフサイクルポリシーの適用漏れが疑われ、当該ポリシーの設定や適用状況を詳細に確認する必要があります。今後の対策としては、ライフサイクルポリシーの再確認と運用手順の見直しを行う予定です。', TIMESTAMP WITH TIME ZONE '2020-04-02T16:29:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00480', 'INC-2020-00328', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T16:44:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T17:44:08+09:00', '【初動対応】【ストレージ・容量障害】オブジェクトライフサイクル誤り', '初動対応として、運用部は被害を最小限に抑えるため、不要オブジェクトの手動削除作業を開始しました。また、ライフサイクルポリシーの設定を確認し、適用漏れの原因を特定するための調査を並行して実施しています。この作業により、ストレージの容量回復を目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00481', 'INC-2020-00328', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T18:14:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T19:14:08+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00332', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-17T23:28:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T23:58:37+09:00', '【障害報告】【性能・負荷障害】下流APIレート制限', '2020年4月17日23時28分37秒、株式会社ストッククラウドのMercuryにおいて下流APIのレート制限が発生し、処理待ちが増大した。この事象は大規模セール開始直前に発生したため、影響範囲はサービス全体の一部機能に及んでいる。顧客からの報告はなく、運用部の運用 一郎が事象を発見した。検知までに34分を要し、2020年4月18日00時02分37秒に問題が検知された。エラーコードはPRF-07-00332であり、影響コンポーネントはVenus Azure AP（ゾーンB）およびAPIゲートウェイである。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00332', 'INC-2020-00332', '調査の結果、大規模セール開始直前に下流APIのレート制限が原因で、待ち行列が増えたことが確認された。下流APIのレート制限に起因する性能・負荷障害のため、多数のリクエストが処理されず、ユーザーに影響を及ぼした。今後の対策としては、レート制限の緩和や、トラフィックの分散が必要と考えられる。', '調査の結果、大規模セール開始直前に下流APIのレート制限が原因で、待ち行列が増えたことが確認された。下流APIのレート制限に起因する性能・負荷障害のため、多数のリクエストが処理されず、ユーザーに影響を及ぼした。今後の対策としては、レート制限の緩和や、トラフィックの分散が必要と考えられる。', TIMESTAMP WITH TIME ZONE '2020-04-18T23:58:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00486', 'INC-2020-00332', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T00:13:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T01:13:37+09:00', '【初期対応】【性能・負荷障害】下流APIレート制限', '初期対応として、運用部より下流APIのレート制限を一時的に緩和し、待ち行列の解消を試みた。その後、システムのモニタリングを強化し、パフォーマンスを観察した。影響を受けた顧客への通知も検討し、必要に応じて情報提供を行う方針とした。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00487', 'INC-2020-00332', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T01:43:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T02:43:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00335', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-10T09:38:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T11:38:10+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2023-10-05 14:22:00 に発生した棚卸突合失敗について報告いたします。顧客店舗POSにて棚卸確定ボタンがグレーアウトしたまま操作できない事象が確認されました。この問題は月末棚卸の開始時に発生し、影響範囲は単一店舗のみとなっています。また、発見者は営業部の花子で、影響コンポーネントは顧客店舗POS（DRサイト）および店舗在庫ビューです。検知は発生から132分後の2023-10-05 14:54:00 に行われました。推定原因として、未処理の差異調整レコード残留が考えられます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00335', 'INC-2020-00335', '本事象について調査を行った結果、月末棚卸の開始時に棚卸確定ボタンがグレーアウトした原因として、システム内に未処理の差異調整レコードが残留している可能性が高いことが判明しました。これにより、顧客店舗POSにおける棚卸プロセスが正常に進行できなくなっていました。今後は、差異調整レコードの管理を強化し、再発防止に努める必要があります。', '本事象について調査を行った結果、月末棚卸の開始時に棚卸確定ボタンがグレーアウトした原因として、システム内に未処理の差異調整レコードが残留している可能性が高いことが判明しました。これにより、顧客店舗POSにおける棚卸プロセスが正常に進行できなくなっていました。今後は、差異調整レコードの管理を強化し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T11:38:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00490', 'INC-2020-00335', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T11:53:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T12:53:10+09:00', '【初期対応】【棚卸・POS突合障害】棚卸確定不可の初期対応', '2023-10-05 14:22:00 に発生した棚卸確定不可の件について、ただちに調査を開始しました。営業部の花子が顧客店舗POSの状況を確認し、エラーコード INV-03-00335 に基づく原因分析を実施中です。現在は未処理の差異調整レコードについて詳細を調査し、早急に対応策を検討しております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00491', 'INC-2020-00335', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T13:23:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T14:23:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00336', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-22T13:47:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T14:17:55+09:00', '【障害報告】【CLU-07】EDI在庫差分遅延', '2023-10-15T09:30:00+09:00に発生した、株式会社ストッククラウドのMercuryに関する障害についてご報告いたします。本件はEDI在庫差分ファイルの反映が2時間遅延し、影響範囲は同一顧客の全店舗に及びました。発生契機はデータ移行バッチ実行中であり、推定原因としてEDIキューの優先度設定誤りが考えられます。この問題は検知までに17分を要し、2023-10-15T09:47:00+09:00に確認されました。エラーコードはEDI-01-00336です。技術的な詳細としては、データ移行バッチ実行中にEDI在庫差分ファイルの反映が遅延しており、迅速な対応が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00336', 'INC-2020-00336', '本障害の調査を行った結果、EDI在庫差分ファイルの反映遅延がEDIキューの優先度設定に起因していることが確認されました。現在、問題の根本的な原因を特定し、再発防止策を講じる必要があります。また、影響を受けた全店舗の在庫情報が正確であるかどうかの確認も進めております。今後の対応として、優先度設定の見直しを早急に行うことが求められます。', '本障害の調査を行った結果、EDI在庫差分ファイルの反映遅延がEDIキューの優先度設定に起因していることが確認されました。現在、問題の根本的な原因を特定し、再発防止策を講じる必要があります。また、影響を受けた全店舗の在庫情報が正確であるかどうかの確認も進めております。今後の対応として、優先度設定の見直しを早急に行うことが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-23T14:17:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00492', 'INC-2020-00336', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T14:32:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T15:32:55+09:00', '初期対応', '2023-10-15T09:31:00+09:00に初期対応を開始しました。運用部の運用 一郎が担当し、影響を受けた全店舗への連絡を行い、状況把握を進めております。また、データ移行バッチの確認とEDIキューの設定を見直し、即時対応を行っております。さらに、問題発生の根本原因の特定に向けて、技術チームと連携を図っております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00493', 'INC-2020-00336', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T16:02:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T17:02:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00342', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-13T07:20:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T08:05:22+09:00', '【障害報告】【ストレージ・容量障害】オブジェクトライフサイクル誤り', '発生日時: 2020-05-15T09:30:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00342', 'INC-2020-00342', '今回の障害は、2020-05-15T09:30:00+09:00に発生し、59分後に検知されました。対象はMercury AWS Storageで、不要オブジェクトが削除されずストレージが圧迫される事象が確認されました。調査の結果、ライフサイクルポリシーの適用漏れが原因であると考えられています。今後、定例リリース後のポリシー適用状況を確認する体制を強化します。', '今回の障害は、2020-05-15T09:30:00+09:00に発生し、59分後に検知されました。対象はMercury AWS Storageで、不要オブジェクトが削除されずストレージが圧迫される事象が確認されました。調査の結果、ライフサイクルポリシーの適用漏れが原因であると考えられています。今後、定例リリース後のポリシー適用状況を確認する体制を強化します。', TIMESTAMP WITH TIME ZONE '2020-04-14T08:05:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00503', 'INC-2020-00342', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T08:20:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T09:20:22+09:00', '【初期対応】【ストレージ・容量障害】オブジェクトライフサイクル誤り', '初期対応として、運用部の運用 一郎が障害の内容を把握し、関係部署に報告を行いました。不要オブジェクトの immediate deletion を試みましたが、ライフサイクルポリシーの適用漏れが明らかであるため、さらなる調査と報告が必要であることが判明しました。ストレージの監視強化を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00504', 'INC-2020-00342', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T09:50:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T10:50:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00345', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-01T20:01:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T20:16:18+09:00', '【障害報告】【CLU-08】APIトークン早期失効', '2020年4月1日20時01分18秒、株式会社ストッククラウドのサービスMercuryにおいて、運用者による作業ミスが原因で、APIトークンが発行直後に失効扱いとなる事象が発生しました。影響範囲はサービス全体の一部機能に及び、運用コンソール（ゾーンA）及びAPIゲートウェイにおいて顕著に現れました。発生契機はインフラメンテナンス明けであり、約15分後の20時16分18秒にこの障害が検知されました。原因としては、サーバー時刻のNTPずれが推定されています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00345', 'INC-2020-00345', '本インシデントに関する調査を行った結果、APIトークンが発行直後に失効扱いとなった原因は、インフラメンテナンス後のサーバー時刻のNTPずれであることが確認されました。特に、運用コンソールにおいてこの問題が顕著に現れました。この問題により、ユーザーはAPIを利用できず、サービス提供に支障をきたしました。今後の再発防止策として、NTP設定の定期的な確認を行う必要があります。', '本インシデントに関する調査を行った結果、APIトークンが発行直後に失効扱いとなった原因は、インフラメンテナンス後のサーバー時刻のNTPずれであることが確認されました。特に、運用コンソールにおいてこの問題が顕著に現れました。この問題により、ユーザーはAPIを利用できず、サービス提供に支障をきたしました。今後の再発防止策として、NTP設定の定期的な確認を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-02T20:16:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00508', 'INC-2020-00345', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T20:31:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T21:31:18+09:00', '【初期対応】【CLU-08】APIトークン早期失効の初期対応', '2020年4月1日20時01分、運用部の運用 一郎がAPIトークン早期失効の事象を確認し、直ちに対策を講じました。具体的には、運用コンソールの設定確認及びサーバー時刻のNTP設定を見直すとともに、ユーザーへのお知らせを準備しました。また、障害が発生した原因を突き止めるための調査チームを編成し、詳細な調査を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00346', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-23T16:53:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T17:53:35+09:00', '【障害報告】【顧客ネットワーク障害】回線断後セッション未復旧', '2023年10月12日、株式会社ストッククラウドの顧客拠点において、拠点回線断復旧後もセッションが復旧しない事象が発生いたしました。本事象は、顧客ネットワークにおける接続性に重大な影響を及ぼしており、該当拠点の業務に支障をきたす恐れがございます。エラーコードはNW-05-00346です。本障害は、年末年始の稼働切替時に発生しており、内部調査の結果、VPNクライアントのバージョン不整合が推定されております。本件に関しましては、迅速な対応を行う必要があり、現在対応を進めている状況でございます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00346', 'INC-2020-00346', '本障害について、詳細な調査を実施いたしました。調査の結果、拠点回線断復旧後にセッションが復旧しない原因として、VPNクライアントのバージョン不整合が確認されました。特に、年末年始の稼働切替時に発生したことが影響している可能性が高いと考えられます。今後、顧客と連携し、問題解決のための具体策を講じる必要がございます。', '本障害について、詳細な調査を実施いたしました。調査の結果、拠点回線断復旧後にセッションが復旧しない原因として、VPNクライアントのバージョン不整合が確認されました。特に、年末年始の稼働切替時に発生したことが影響している可能性が高いと考えられます。今後、顧客と連携し、問題解決のための具体策を講じる必要がございます。', TIMESTAMP WITH TIME ZONE '2020-04-24T17:53:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00509', 'INC-2020-00346', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T18:08:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T19:08:35+09:00', '【初期対応】【顧客ネットワーク障害】回線断後セッション未復旧', '本日、10月12日に発生した回線断後セッション未復旧の件について、初期対応を実施いたしました。該当の顧客拠点において、回線復旧が確認されましたが、セッションが未だ復旧していない状況です。具体的な原因として、VPNクライアントのバージョン不整合が疑われております。顧客への報告と今後の対応について、早急に方針を確定し、実行に移す所存です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00349', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-23T17:10:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T19:10:34+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '2020年4月23日17時10分34秒に、株式会社ストッククラウドが提供するMercuryサービスにおいて、顧客店舗POSにて棚卸突合失敗が発生しました。症状としては、アウトボックステーブルに滞留が見られ、通知遅延が発生しています。発見者は営業部の花子であり、定例リリース直後にこの事象が確認されました。影響範囲としてはサービス全体の一部機能に及んでおり、エラーコードはSYNC-05-00349です。推定原因としては、アウトボックスポーラーの停止が疑われます。この問題に関しては、直ちに対応が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00349', 'INC-2020-00349', '調査の結果、定例リリース直後に発生したアウトボックステーブルの滞留が確認されました。これにより通知遅延が発生しており、アウトボックスポーラーが停止している可能性が高いです。影響を受けるコンポーネントは顧客店舗POSとイベントバスです。原因の特定および早期復旧に向けた対応を進める必要があります。', '調査の結果、定例リリース直後に発生したアウトボックステーブルの滞留が確認されました。これにより通知遅延が発生しており、アウトボックスポーラーが停止している可能性が高いです。影響を受けるコンポーネントは顧客店舗POSとイベントバスです。原因の特定および早期復旧に向けた対応を進める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T19:10:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00513', 'INC-2020-00349', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T19:25:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T20:25:34+09:00', '初期対応', '初期対応として、アウトボックスポーラーの状態を確認し、必要に応じて再起動を行います。また、アウトボックステーブルの状況を監視し、滞留が解消されるかどうかを確認します。関係者には事象について周知し、進捗情報を随時共有します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00350', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-18T16:21:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T17:06:41+09:00', '【障害報告】【ストレージ・容量障害】レプリカ遅延肥大', '2020年4月18日16時21分41秒に発生したストレージ溢れのインシデントに関する報告です。本事象は、レプリカ遅延により差分ログが肥大化し、読取専用レプリカ利用者に影響を及ぼしました。発生の契機は、大規模セール開始直前に設定されたレプリカ帯域制限の過小によるものであると推定されます。具体的には、Mercury AWS Storage（ゾーンA）において、DBデータファイルの更新が遅延し、その結果として差分ログが蓄積されました。また、インシデントは17時34分41秒に検知されました。この遅延により、顧客へのサービス提供に影響を与えることとなり、重大度はHIGHに分類されます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00350', 'INC-2020-00350', 'インシデントの調査を行った結果、レプリカ遅延の発生原因は、レプリカ帯域制限設定の過小であったことが確認されました。大規模セール開始直前に、この設定が適切に行われていなかったため、データの複製遅延が発生し、差分ログが膨大化しました。今後は、帯域制限の見直しを行い、同様の問題が発生しないように対策を講じる必要があります。また、定期的な監視体制の強化も不可欠です。', 'インシデントの調査を行った結果、レプリカ遅延の発生原因は、レプリカ帯域制限設定の過小であったことが確認されました。大規模セール開始直前に、この設定が適切に行われていなかったため、データの複製遅延が発生し、差分ログが膨大化しました。今後は、帯域制限の見直しを行い、同様の問題が発生しないように対策を講じる必要があります。また、定期的な監視体制の強化も不可欠です。', TIMESTAMP WITH TIME ZONE '2020-04-19T17:06:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00514', 'INC-2020-00350', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T17:21:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T18:21:41+09:00', '【初動対応】【ストレージ・容量障害】初期対応の実施', 'インシデント発生直後、運用部の運用 一郎が迅速に対応を開始しました。具体的には、レプリカ遅延の状況を確認し、まずは影響を受けている顧客への通知を行いました。また、遅延の原因と考えられる帯域制限設定を見直すため、関連する設定の確認を行いました。さらに、迅速な解消策として、帯域制限の一時的な引き上げを実施し、差分ログの肥大化を抑制するための処置を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00515', 'INC-2020-00350', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T18:51:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T19:51:41+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00351', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-15T23:30:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T00:30:57+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2020年4月15日23時30分57秒に発生した顧客側ネットワーク障害に関する報告です。顧客拠点NWにおいて、店舗VPN経由でSaaSに到達できない事象が発生しました。この問題は、2020年4月16日00時56分57秒に検知され、検知まで86分を要しました。影響範囲は単一店舗に限定されており、顧客オンボーディング当日に発生したことが確認されています。推定原因として、拠点FWのルール変更が疑われます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00351', 'INC-2020-00351', '本障害についての調査を行った結果、顧客拠点NWの拠点VPNゲートウェイに障害が発生し、店舗VPN経由でSaaSに到達できない状況が確認されました。顧客オンボーディング当日における拠点FWのルール変更が原因である可能性が高いと考えられます。今後、FWの設定やルール確認を行い、再発防止策を講じる必要があります。', '本障害についての調査を行った結果、顧客拠点NWの拠点VPNゲートウェイに障害が発生し、店舗VPN経由でSaaSに到達できない状況が確認されました。顧客オンボーディング当日における拠点FWのルール変更が原因である可能性が高いと考えられます。今後、FWの設定やルール確認を行い、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-17T00:30:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00516', 'INC-2020-00351', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T00:45:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T01:45:57+09:00', '【初期対応】【顧客ネットワーク障害】店舗VPN到達不可', '事象発生後、速やかに初期対応を実施し、顧客拠点NWの状況を確認しました。店舗VPNに関する設定を見直すとともに、拠点FWのルール変更についての検討を行いました。また、影響を受けた顧客に対して適切な情報を提供し、現在の進捗状況について随時報告する体制を整えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00353', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-08T19:38:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T19:53:32+09:00', '【障害報告】【運用操作・権限障害】ロールバック途中停止', '2023-10-12T15:00:00+09:00に発生した、株式会社ストッククラウドのMercuryにおける運用者の作業ミスによるアクセス障害について報告します。運用コンソールにてロールバック操作が途中で停止し、不整合が生じました。この障害は定例リリース直後に発生し、サービス全体の一部機能に影響を及ぼしました。推定される原因はリリース手順のスキップであり、エラーコードはOPS-05-00353です。今後は、リリース時の手順を厳守することが求められます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00353', 'INC-2020-00353', '本インシデントに関する調査を行った結果、定例リリース直後にロールバック操作が途中で停止し、不整合が発生したことが確認されました。運用者がリリース手順をスキップしたことが原因と考えられ、適切な手順を遵守することが重要であることが示されています。今後は、運用操作の教育と手順の確認を徹底する必要があります。', '本インシデントに関する調査を行った結果、定例リリース直後にロールバック操作が途中で停止し、不整合が発生したことが確認されました。運用者がリリース手順をスキップしたことが原因と考えられ、適切な手順を遵守することが重要であることが示されています。今後は、運用操作の教育と手順の確認を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-09T19:53:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00518', 'INC-2020-00353', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T20:08:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T21:08:32+09:00', '【初期対応】【運用操作・権限障害】ロールバック途中停止', '2023-10-12T15:01:00+09:00に、運用 一郎が運用コンソールにてロールバック操作が途中で停止したことを確認しました。直ちに運用部のメンバーと連携し、状況を把握し、不整合を解消するための対応を開始しました。影響範囲を明確化し、迅速な復旧を目指しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00354', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-19T11:19:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T13:19:28+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2020年4月19日11時19分28秒、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSに関連する棚卸突合失敗の事象が発生しました。この障害は、大規模セール開始直前に分散トランザクションがタイムアウトし、片側のみがコミットされる形で発生しました。これにより、全テナントに影響を及ぼし、在庫の整合性に問題が生じました。発見者は営業部の花子で、検知は12時51分28秒に行われました。推定される原因は2PCタイムアウト設定の過短であり、今後の対策が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00354', 'INC-2020-00354', '本インシデントの原因調査を行った結果、大規模セール開始直前という特殊な条件下で、分散トランザクションがタイムアウトしたことが判明しました。特に、2PCのタイムアウト設定が適切でなかったことがこの事象の原因として指摘されています。今後は、2PCタイムアウト設定を見直し、同様の事象が再発しないように対策を講じる必要があります。', '本インシデントの原因調査を行った結果、大規模セール開始直前という特殊な条件下で、分散トランザクションがタイムアウトしたことが判明しました。特に、2PCのタイムアウト設定が適切でなかったことがこの事象の原因として指摘されています。今後は、2PCタイムアウト設定を見直し、同様の事象が再発しないように対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-20T13:19:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00519', 'INC-2020-00354', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T13:34:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T14:34:28+09:00', '【初期対応】障害発生時の対応', '障害発生時、直ちに営業部の花子が調査を開始し、影響範囲を確認しました。その後、技術チームにも報告し、速やかに問題の特定に向けた作業を行いました。顧客への影響を最小限に抑えるため、初期対応として、在庫計算エンジンの再起動を実施しました。さらに、2PCタイムアウト設定の確認を行い、必要な修正を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00355', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-05-17T13:46:57+09:00', TIMESTAMP WITH TIME ZONE '2020-05-17T14:31:57+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2020年5月17日13時46分に、株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れが発生しました。発見者の運用 一郎(運用部)が14時08分に検知したところ、ヘルスチェック過多でAPサーバーの負荷が増加していることが判明しました。発生契機はインフラメンテナンス明けであり、全テナントに影響が及ぶ可能性があります。エラーコードはMON-06-00355です。LBのヘルスチェック間隔設定が過短であったことが推定原因として挙げられます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00355', 'INC-2020-00355', '調査の結果、インフラメンテナンス明けにヘルスチェックが過多となり、APサーバーに負荷がかかっていることが確認されました。LBのヘルスチェック間隔設定が過短であることが原因と見られ、全テナントに影響を及ぼす事態が発生しています。今後の対応として、ヘルスチェックの間隔見直しを検討する必要があります。', '調査の結果、インフラメンテナンス明けにヘルスチェックが過多となり、APサーバーに負荷がかかっていることが確認されました。LBのヘルスチェック間隔設定が過短であることが原因と見られ、全テナントに影響を及ぼす事態が発生しています。今後の対応として、ヘルスチェックの間隔見直しを検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-05-18T14:31:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00520', 'INC-2020-00355', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-05-17T14:46:57+09:00', TIMESTAMP WITH TIME ZONE '2020-05-17T15:46:57+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎(運用部)より、ヘルスチェック過多によるAPサーバーの負荷増加が報告されました。迅速にLBのヘルスチェック設定を確認し、間隔を適切な値に修正しました。また、現在の負荷状況を監視し続け、全テナントへの影響を最小限に抑えるよう努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00357', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-08-15T23:29:14+09:00', TIMESTAMP WITH TIME ZONE '2020-08-15T23:44:14+09:00', '【障害報告】【運用操作・権限障害】本番DB誤接続', '2020年8月15日23時29分に、株式会社ストッククラウドが提供するMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。顧客である架空食品店Aおよび架空食品店Bに対し、運用コンソールが本番DB以外に接続している事象が確認されました。システムの定例リリース直後に発生したもので、影響範囲は全テナントに及びます。エラーコードはOPS-06-00357であり、運用ツールの設定が誤っていたことが推定原因となります。このため、迅速な対応が求められました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00357', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00357', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00357', 'INC-2020-00357', '本障害に関する調査を実施した結果、運用ツールが誤って本番DB以外のデータベースに接続していたことが判明しました。この問題は、定例リリース直後に発生したことから、リリース後の設定ミスが原因であると考えられます。運用部の運用 一郎が確認したところ、設定管理DBにおける接続設定内容が誤っていたため、このような事象が発生したものと推測されます。早急な対策が必要です。', '本障害に関する調査を実施した結果、運用ツールが誤って本番DB以外のデータベースに接続していたことが判明しました。この問題は、定例リリース直後に発生したことから、リリース後の設定ミスが原因であると考えられます。運用部の運用 一郎が確認したところ、設定管理DBにおける接続設定内容が誤っていたため、このような事象が発生したものと推測されます。早急な対策が必要です。', TIMESTAMP WITH TIME ZONE '2020-08-16T23:44:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00523', 'INC-2020-00357', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-08-15T23:59:14+09:00', TIMESTAMP WITH TIME ZONE '2020-08-16T00:59:14+09:00', '【障害対応】【運用操作・権限障害】本番DB誤接続', '障害発生後、運用部の運用 一郎が迅速に対応を開始しました。初期対応として、運用コンソールの接続設定を確認し、誤接続を解除しました。また、全テナントに対して影響状況を確認し、適切な案内を行いました。この際、設定見直しを行い、再発防止策として運用体制の強化が求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00362', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-20T02:07:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T02:22:52+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2023-10-03T14:00:00+09:00に発生した障害について報告します。株式会社ストッククラウドの運用コンソールにおいて、Cookie SameSite設定の影響で埋込画面が認証不可となりました。発見者は運用 一郎さんで、発生契機は定例リリース直後でした。これにより、単一店舗のみが影響を受け、エラーコードはAUTH-06-00362です。業務に支障が出るため、早急な対応が求められます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00362', 'INC-2020-00362', '運用 一郎です。現在、同障害の原因を調査しています。CookieのSameSite属性変更により、埋込画面が認証不可となっていると推測しています。この影響により、特定の店舗でのログインができない状況です。今後の調査を進め、詳細な原因を特定し、早急に対応策を講じます。', '運用 一郎です。現在、同障害の原因を調査しています。CookieのSameSite属性変更により、埋込画面が認証不可となっていると推測しています。この影響により、特定の店舗でのログインができない状況です。今後の調査を進め、詳細な原因を特定し、早急に対応策を講じます。', TIMESTAMP WITH TIME ZONE '2020-04-21T02:22:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00529', 'INC-2020-00362', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-20T02:37:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T03:37:52+09:00', '【対応】初期対応', '運用 一郎です。障害発生後、直ちに確認作業を行いました。Cookie SameSite設定に関連する問題が疑われ、定例リリース直後の変更が影響している可能性が高いと考えています。このため、関連する設定を元に戻す作業を指示しました。今後の進展に注意しつつ、早急な復旧を目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00530', 'INC-2020-00362', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-20T04:07:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T05:07:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00365', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-15T03:50:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T04:50:07+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2023-10-01T10:30:00+09:00に、株式会社ストッククラウドの顧客ネットワークでISP側BGP経路障害が発生。これにより同時に複数拠点が不通となる障害が確認された。特に影響を受けたのは、同一顧客の全店舗である。発生契機はインフラメンテナンス明けであり、このタイミングで障害が発生した。エラーコードはNW-06-00365である。障害検知は2023-10-01T11:40:00+09:00に行われ、約70分のタイムラグがあった。営業部の花子が発見者となり、事象を報告した。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00365', 'INC-2020-00365', '調査の結果、ISP側のBGP経路障害が原因で複数拠点が同時に不通となっていることが確認された。インフラメンテナンス明けに発生したこの障害は、顧客拠点NWとDNSリゾルバに影響を与えた。今後の対策としては、ISPとの連携を強化し、障害発生時の迅速な情報共有を図る必要がある。', '調査の結果、ISP側のBGP経路障害が原因で複数拠点が同時に不通となっていることが確認された。インフラメンテナンス明けに発生したこの障害は、顧客拠点NWとDNSリゾルバに影響を与えた。今後の対策としては、ISPとの連携を強化し、障害発生時の迅速な情報共有を図る必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-16T04:50:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00533', 'INC-2020-00365', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-15T05:05:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T06:05:07+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '初期対応として、顧客へ障害の発生を通知し、現在の状況を説明した。ISPに対しても障害の詳細を確認し、原因究明に向けた協力を要請した。顧客への影響を最小限に抑えるため、DNS設定の見直し及び代替経路の検討を行うことを提案した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00366', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-04T23:39:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T00:09:15+09:00', '【障害報告】【監視・可用性障害】PagerDuty連携失敗', '2023-10-01T10:15:00+09:00に、株式会社ストッククラウドのMercuryにおいて、PagerDuty連携が失敗し、オンコール通知が未達となる事象が発生しました。運用部門で確認したところ、発生契機は年末年始の稼働切替時でした。運用部の運用 一郎がこの問題を発見し、影響範囲は運用部門のみに限られています。エラーコードはMON-07-00366であり、影響を受けたコンポーネントはVenus Azure AP（ゾーンA）です。技術詳細として、連携APIキーの権限不足が推定原因として挙げられます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00366', 'INC-2020-00366', '本件に関する調査を開始しました。最初に、連携APIキーの権限不足が疑われるため、設定内容を確認しました。また、PagerDutyサービスとの接続状況も検証します。これにより、再発防止策を講じるための具体的な対応が可能になると考えています。この調査は、運用部門が中心となって進めています。', '本件に関する調査を開始しました。最初に、連携APIキーの権限不足が疑われるため、設定内容を確認しました。また、PagerDutyサービスとの接続状況も検証します。これにより、再発防止策を講じるための具体的な対応が可能になると考えています。この調査は、運用部門が中心となって進めています。', TIMESTAMP WITH TIME ZONE '2020-04-06T00:09:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00534', 'INC-2020-00366', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-05T00:24:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T01:24:15+09:00', '【初期対応】【監視・可用性障害】PagerDuty連携失敗への初期対応', '初期対応として、運用部門でPagerDutyの連携設定を確認し、APIキーの権限を見直しました。また、既存の通知設定をテンポラリーで変更し、他の通知方法を検討しました。加えて、オンコールメンバーへの手動通知を実施し、影響を最小限に抑えるよう努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00535', 'INC-2020-00366', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-05T01:54:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T02:54:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00367', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-17T17:00:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T17:30:46+09:00', '【障害報告】【監視・可用性障害】SLO燃焼率警告', '2020年4月17日17時00分46秒に、株式会社ストッククラウドのMercuryサービスにおいて、SLO燃焼率が閾値超過でエラーバジェット警告が発生。発生の契機は、大規模セール開始直前であり、全テナントに波及する影響が確認されました。影響を受けたコンポーネントはVenus Azure AP（ゾーンA）及びSLOダッシュボードで、エラーコードはMON-03-00367です。運用部の運用 一郎の発見により、17時35分46秒に検知されました。事象の原因としては、SLO計算ウィンドウの設定誤りが疑われています。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00367', 'INC-2020-00367', '監視システムからのデータを分析した結果、SLO計算ウィンドウの設定誤りが原因でSLO燃焼率が閾値を超えたことが明らかとなりました。この誤設定により、エラーバジェットの警告が出力され、全てのテナントに影響が及びました。さらに、今後の大規模セールに向けて、設定の見直しが必要であることが確認されました。', '監視システムからのデータを分析した結果、SLO計算ウィンドウの設定誤りが原因でSLO燃焼率が閾値を超えたことが明らかとなりました。この誤設定により、エラーバジェットの警告が出力され、全てのテナントに影響が及びました。さらに、今後の大規模セールに向けて、設定の見直しが必要であることが確認されました。', TIMESTAMP WITH TIME ZONE '2020-04-18T17:30:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00536', 'INC-2020-00367', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T17:45:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T18:45:46+09:00', '【初期対応】【監視・可用性障害】SLO燃焼率警告', '初期の対応として、SLO計算ウィンドウの設定を確認し、必要に応じて修正を行いました。運用部は警告が発生した原因を特定し、その影響範囲を明確にするため、全テナントへの連絡を開始しました。また、システムの監視体制を強化し、再発防止策を講じる方針を決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00537', 'INC-2020-00367', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T19:15:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T20:15:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00368', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-16T13:07:48+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T13:22:48+09:00', '【障害報告】【CLU-08】パスワードポリシー衝突', '2020年4月16日13時07分に、株式会社ストッククラウドのサービスMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。具体的には、新パスワードポリシーの導入によって、既存API認証が失敗し、全テナントに波及する事象が確認されました。発見者は運用部の運用 一郎であり、障害は定例リリース直後に発生しました。検知は同日13時23分に行われ、発見から16分後に問題が確認されました。現時点での推定原因は、レガシー認証方式の残存が影響していると考えられます。影響を受けたコンポーネントは運用コンソール及び認証サービスです。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00368', 'INC-2020-00368', '本障害について調査を進めた結果、定例リリース直後に新パスワードポリシーが適用されたことが確認されました。これにより、既存のレガシー認証方式が残存していたため、認証失敗が引き起こされたものと推測されます。現在、影響範囲は全テナントに及んでおり、早急な対応が求められています。', '本障害について調査を進めた結果、定例リリース直後に新パスワードポリシーが適用されたことが確認されました。これにより、既存のレガシー認証方式が残存していたため、認証失敗が引き起こされたものと推測されます。現在、影響範囲は全テナントに及んでおり、早急な対応が求められています。', TIMESTAMP WITH TIME ZONE '2020-04-17T13:22:48+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00538', 'INC-2020-00368', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T13:37:48+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T14:37:48+09:00', '初動対応', '本障害発生の初動対応として、運用部は直ちに影響を受けるテナントへの案内を行い、認証サービスを一時的に停止し、問題の調査を開始しました。また、エラーコードAUTH-05-00368が記録されていることを確認し、関連情報を収集して原因分析を進めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00539', 'INC-2020-00368', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T15:07:48+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T16:07:48+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00374', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-18T03:24:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T03:54:28+09:00', '【障害報告】【認証・セッション障害】パスワードポリシー衝突', '2023年10月01日 10:00に発生したインシデントについて報告いたします。本障害は、株式会社ストッククラウドのMercuryサービスにおいて、新パスワードポリシーが適用されたことで既存API認証が失敗する事象が発生しました。影響範囲は全テナントに波及し、顧客への影響が懸念されました。発生契機は定例リリース直後であり、技術的な詳細としてはレガシー認証方式の残存が予想されます。このため、認証サービスにおいては即座の対応が求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00374', 'INC-2020-00374', '本障害に関する調査を実施いたしました。定例リリース直後に適用された新パスワードポリシーにより、既存API認証が失敗する問題が確認されました。レガシー認証方式が残存していることが推定原因として挙げられ、全テナントに影響を与えたことが明らかとなりました。これにより、今後のリリースに向けた対策が必要であると考えられます。', '本障害に関する調査を実施いたしました。定例リリース直後に適用された新パスワードポリシーにより、既存API認証が失敗する問題が確認されました。レガシー認証方式が残存していることが推定原因として挙げられ、全テナントに影響を与えたことが明らかとなりました。これにより、今後のリリースに向けた対策が必要であると考えられます。', TIMESTAMP WITH TIME ZONE '2020-04-19T03:54:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00549', 'INC-2020-00374', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T04:09:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T05:09:28+09:00', '【初動対応】【認証・セッション障害】パスワードポリシー衝突', '本事象に対して初動対応を行いました。影響を受けた全テナントへの通知を開始し、顧客への影響を最小限に留めるための措置を講じました。また、技術チームに対してレガシー認証方式の排除を急ぎ進めるよう指示を行いました。この問題に対する継続的なモニタリングを実施し、適切な解決策を実装するための準備を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00550', 'INC-2020-00374', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T05:39:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T06:39:28+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00375', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-01T09:45:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T10:00:24+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2023-10-05 14:00:00に、株式会社ストッククラウドのMercuryサービスにおいて、運用者の作業ミスによるアクセス障害が発生しました。症状はCookie SameSite設定により、埋込画面が認証不可となり、ユーザーへの影響が出ました。発生は定例リリース直後であり、影響範囲は単一店舗のみとなっています。エラーコードはAUTH-06-00375で、運用コンソールのゾーンAおよびセッションストアに関連しています。運用 一郎が発見者となり、09:57:24に検知されました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00375', 'INC-2020-00375', '調査を行った結果、定例リリース直後にCookieのSameSite設定が変更されたことが原因で、埋込画面が認証不可となったことが分かりました。これにより、運用コンソールにアクセスできない状況が確認されました。この影響により、特定の店舗で認証が行えず、ユーザーからの問い合わせが増加しました。', '調査を行った結果、定例リリース直後にCookieのSameSite設定が変更されたことが原因で、埋込画面が認証不可となったことが分かりました。これにより、運用コンソールにアクセスできない状況が確認されました。この影響により、特定の店舗で認証が行えず、ユーザーからの問い合わせが増加しました。', TIMESTAMP WITH TIME ZONE '2020-04-02T10:00:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00551', 'INC-2020-00375', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T10:15:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T11:15:24+09:00', '【初期対応】【CLU-08】Cookie SameSite拒否', '発見後、運用 一郎が迅速に該当部分の設定を確認し、CookieのSameSite設定を元に戻す作業を開始しました。影響を受けたユーザーには、現在作業を行っていることを通知し、少々お待ちいただく旨をお伝えしました。今後の対応として、再発防止策を検討し、設定変更の影響範囲を明確化する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00376', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-20T12:39:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T12:54:43+09:00', '【障害報告】【CLU-08】SSOリダイレクトループ', '株式会社ストッククラウドのMercuryにおいて、2023-10-05T14:30:00+09:00にアクセス障害が発生いたしました。発生時、SSOログインでリダイレクトループが発生し、全テナントに影響を及ぼしました。本障害は、定例リリース直後に発生し、運用コンソール及び認証サービスにおいて確認されました。検知時刻は2023-10-05T14:45:00+09:00であり、運用 一郎（運用部）が発見いたしました。原因としては、SAMLメタデータのURL不一致が考えられます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00376', 'INC-2020-00376', '発生したSSOリダイレクトループに関する調査を行いました。定例リリース直後に発生した本障害は、SSOログイン時にリダイレクトループが生じることから、SAMLメタデータのURL不一致が推定されます。確認作業を進め、詳細な原因を特定する必要があります。影響範囲が広いため、対応を急ぎ、全テナントのサービス復旧を目指します。', '発生したSSOリダイレクトループに関する調査を行いました。定例リリース直後に発生した本障害は、SSOログイン時にリダイレクトループが生じることから、SAMLメタデータのURL不一致が推定されます。確認作業を進め、詳細な原因を特定する必要があります。影響範囲が広いため、対応を急ぎ、全テナントのサービス復旧を目指します。', TIMESTAMP WITH TIME ZONE '2020-04-21T12:54:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00552', 'INC-2020-00376', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-20T13:09:43+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T14:09:43+09:00', '【初期対応】【CLU-08】SSOリダイレクトループ', '本障害発生後、運用チームは速やかに初期対応を開始しました。具体的には、SSOログインに関連する設定を確認し、SAMLメタデータのURLを再設定する作業を行いました。全テナントに影響が及んでいるため、障害情報を共有し、顧客への迅速な報告を行うことが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00377', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-18T00:48:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T01:33:57+09:00', '【障害報告】【CLU-10】アラート疲労', '2020年4月18日0時48分57秒、株式会社ストッククラウドのMercuryサービスにおいて、運用部門が監視していたMercury AWS Storageでストレージ溢れが発生。検知は2020年4月18日1時23分57秒で、検知までに35分の遅延があった。同一アラートが短時間に数百件発報され、運用部門にアラート疲労を引き起こしたと考えられる。発生契機は大規模セール開始直前であり、アラート抑制ルールが未設定であったことが推定原因として挙げられる。影響範囲は運用部門のみであり、影響コンポーネントはMercury AWS Storage（DRサイト）及びアラートマネージャであった。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00377', 'INC-2020-00377', '調査の結果、大規模セール開始直前に同一アラートが短時間に数百件発報したことが確認された。原因としてアラート抑制ルールが未設定であったことが主な要因と考えられる。運用部門の業務に大きな影響を及ぼす結果となり、適切な抑制ルールの設定が急務であることが明らかになった。今後はアラート設定の見直し及び改善策を検討する必要がある。', '調査の結果、大規模セール開始直前に同一アラートが短時間に数百件発報したことが確認された。原因としてアラート抑制ルールが未設定であったことが主な要因と考えられる。運用部門の業務に大きな影響を及ぼす結果となり、適切な抑制ルールの設定が急務であることが明らかになった。今後はアラート設定の見直し及び改善策を検討する必要がある。', TIMESTAMP WITH TIME ZONE '2020-04-19T01:33:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00553', 'INC-2020-00377', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T01:48:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T02:48:57+09:00', '【対応ログ】【CLU-10】アラート疲労への初期対応', '運用部門では発報されたアラートについて、即座に対策を講じるため、アラート抑制ルールの設定を検討した。また、影響範囲を把握し、必要な情報を関係者と共有することで、迅速な対応を図った。アラートの発報が続く中、正常な運用の早期復旧を目指し、全社で連携を強化した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00380', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-08T09:23:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T09:53:27+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023年09月15日、株式会社ストッククラウドのMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。発生した問題は、マスター更新と在庫が二重反映されるというもので、全店舗に影響を及ぼしました。問題は定例リリース直後に発生し、イベント順序の逆転配信が原因と考えられます。エラーコードはSYNC-01-00380で、影響コンポーネントはMercury AWS AP及びイベントバスです。検知は発生から31分後に行われました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00380', 'INC-2020-00380', '調査の結果、定例リリース直後において、マスター更新と在庫の二重反映が確認されました。原因としては、イベント順序が逆転して配信された可能性が高く、これによりデータ同期に問題が生じたと考えられます。さらに、全店舗の在庫状況に影響を及ぼす事象であり、早急な対策が求められます。', '調査の結果、定例リリース直後において、マスター更新と在庫の二重反映が確認されました。原因としては、イベント順序が逆転して配信された可能性が高く、これによりデータ同期に問題が生じたと考えられます。さらに、全店舗の在庫状況に影響を及ぼす事象であり、早急な対策が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-09T09:53:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00558', 'INC-2020-00380', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T10:08:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T11:08:27+09:00', '【応答】【データ同期・整合性障害】初期対応', '初期対応として、問題の再現確認及びエラーログの収集を行いました。二重反映の原因究明に向けて、関連するシステムの検証を順次進めており、イベントの配信順序を見直す必要があります。また、顧客への影響を最小限に抑えるため、在庫データの整合性を確保する措置を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00382', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-10T20:52:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T21:37:19+09:00', '【障害報告】【CLU-10】合成監視失敗', '2020年4月10日20時52分、株式会社ストッククラウドのMercuryにおいて、合成監視が特定ステップで失敗しました。発生は定例リリース直後であり、エラーコードはMON-08-00382です。この障害により、サービス全体の一部機能に影響が出ています。影響コンポーネントはMercury AWS Storage（Secondary）および合成監視ランナーです。推定原因として、テストデータの期限切れが考えられます。問題の詳細を記録し、再発防止策を検討する必要があります。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00382', 'INC-2020-00382', '初期調査の結果、合成監視が特定ステップで失敗していることが確認されました。発生タイミングは定例リリース直後で、テストデータの期限切れが原因として推定されます。今後、失敗したステップの詳細な分析を行い、必要な修正を実施する予定です。また、合成監視の信頼性を向上させるための対策も併せて検討します。', '初期調査の結果、合成監視が特定ステップで失敗していることが確認されました。発生タイミングは定例リリース直後で、テストデータの期限切れが原因として推定されます。今後、失敗したステップの詳細な分析を行い、必要な修正を実施する予定です。また、合成監視の信頼性を向上させるための対策も併せて検討します。', TIMESTAMP WITH TIME ZONE '2020-04-11T21:37:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00560', 'INC-2020-00382', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T21:52:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T22:52:19+09:00', '【対応ログ】【CLU-10】合成監視失敗', '2020年4月10日21時58分、運用部の運用 一郎が合成監視の失敗を検知しました。テストデータの期限切れが原因として疑われるため、この問題に対して直ちに対応を開始しました。まずは、監視システムの設定を確認し、失敗したステップの原因を特定するための調査を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00561', 'INC-2020-00382', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T23:22:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T00:22:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00384', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-21T09:54:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T10:54:27+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023-10-15T09:30:00+09:00 顧客からの連絡により、特定拠点のみAPI呼び出しが失敗する事象が発生。失敗発生の背景には、新規店舗追加の初日であることがある。担当の営業 花子が事象を確認し、原因として店舗LANのスイッチ故障が疑われる。影響範囲は単一店舗に限定されており、顧客拠点NW（ゾーンB）および顧客側FWに影響が出ている。エラーコードはNW-02-00384であり、API失敗により顧客サービスに影響を与えている。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00384', 'INC-2020-00384', '新規店舗追加の初日に発生した特定拠点のみAPI呼び出しが失敗する事象について調査を開始。店舗LANのスイッチに異常がないか確認するため、ネットワークのトラフィックをモニタリング。スイッチの管理ログを確認し、エラーや異常が記録されていないか確認する。また、顧客のLAN環境に他の問題がないかも併せて確認する。', '新規店舗追加の初日に発生した特定拠点のみAPI呼び出しが失敗する事象について調査を開始。店舗LANのスイッチに異常がないか確認するため、ネットワークのトラフィックをモニタリング。スイッチの管理ログを確認し、エラーや異常が記録されていないか確認する。また、顧客のLAN環境に他の問題がないかも併せて確認する。', TIMESTAMP WITH TIME ZONE '2020-04-22T10:54:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00563', 'INC-2020-00384', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T11:09:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T12:09:27+09:00', '【応答】調査結果', '調査を実施した結果、店舗LANのスイッチに故障の兆候が確認され、交換が必要であることが判明。顧客に対して、スイッチの交換を提案し、作業を実施することになった。交換作業後、API呼び出しについて再度テストを実施し、正常な動作を確認した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00564', 'INC-2020-00384', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T12:39:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T13:39:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00387', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-26T09:55:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T11:55:04+09:00', '【障害報告】【CLU-07】APIキー期限切れ', '2020年4月26日09時55分に、株式会社ストッククラウドの顧客店舗POSにおいて外部WMS APIキー期限切れが発生しました。この事象により、API連携が停止し、影響範囲は同一顧客の全店舗に及びました。発生契機はインフラメンテナンス明けであり、推定原因はAPIキーローテーション手順の未実施です。エラーコードはEDI-03-00387です。検知は2020年4月26日12時24分で、149分後に状況が把握されました。技術詳細として、APIゲートウェイも影響を受けていることが報告されています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00387', 'INC-2020-00387', 'APIキーの期限切れに起因する連携停止の問題は、インフラメンテナンス明けに発生しました。確認された症状は、外部WMSとのAPI連携が機能しない状態です。この問題を解決するためには、APIキーローテーション手順の実施が不可欠です。今後、同様の事象を防ぐための対策として、定期的な確認と手順の見直しが必要です。', 'APIキーの期限切れに起因する連携停止の問題は、インフラメンテナンス明けに発生しました。確認された症状は、外部WMSとのAPI連携が機能しない状態です。この問題を解決するためには、APIキーローテーション手順の実施が不可欠です。今後、同様の事象を防ぐための対策として、定期的な確認と手順の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2020-04-27T11:55:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00568', 'INC-2020-00387', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T12:10:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T13:10:04+09:00', '初期対応', 'インシデント発生直後、営業部の花子が状況を確認しました。APIの状態を調査し、期限切れが原因であることを特定しました。その後、関連部署と連携して迅速にAPIキーの更新手続きを進めるよう指示を出しました。さらに、顧客への影響を最小限に抑えるため、状況説明を行い、信頼回復に努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00569', 'INC-2020-00387', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T13:40:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T14:40:04+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00388', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-24T18:49:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T19:04:59+09:00', '【障害報告】【CLU-10】ログ相関ID欠落', '2023-10-05T10:30:00+09:00に発生した運用者の作業ミスによるアクセス障害について報告いたします。この障害は、運用コンソールにて発生し、ログに相関IDが欠落したため、横断検索が不可能な状態となりました。発見者は運用部の運用 一郎であり、発生契機は定例リリース直後です。この問題により、運用部門のみが影響を受け、業務の継続に支障をきたしました。推定原因はログフォーマット変更のロールアウト漏れと考えられます。技術的には、定例リリース直後にログに相関IDが欠落し横断検索が不可となる状況が発生しました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00388', 'INC-2020-00388', '本障害について調査を行った結果、運用コンソールでのログに相関IDが欠落していることが確認されました。このため、横断検索が実施できない状態が継続しており、原因はログフォーマット変更のロールアウト漏れと推定されます。運用部門にのみ影響が及んでいるため、迅速な対応が求められています。', '本障害について調査を行った結果、運用コンソールでのログに相関IDが欠落していることが確認されました。このため、横断検索が実施できない状態が継続しており、原因はログフォーマット変更のロールアウト漏れと推定されます。運用部門にのみ影響が及んでいるため、迅速な対応が求められています。', TIMESTAMP WITH TIME ZONE '2020-04-25T19:04:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00570', 'INC-2020-00388', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T19:19:59+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T20:19:59+09:00', '【初期対応】【CLU-10】ログ相関ID欠落', '運用部門に対して、本障害に関する初期対応を実施いたしました。まず、ログフォーマット変更に関する検証を行い、相関ID欠落の原因を特定するための調査を開始しました。運用 一郎が主導し、関係者と連携しながら問題解決に向けての作業を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00391', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-15T19:02:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T19:32:53+09:00', '【障害報告】【性能・負荷障害】キャッシュヒット率低下', '2020年4月15日19時02分53秒、株式会社ストッククラウドのMercuryサービスにおいて、キャッシュヒット率低下によるDB負荷増の事象が発生しました。影響範囲は全テナントに及び、特にVenus Azure APでのキャッシュレイヤにおいて顕著でした。定例リリース直後に発生し、検知は同日の19時30分53秒であり、検知までの時間は28分でした。推定原因として、インデックス未適用の新機能が考えられます。エラーコードはPRF-09-00391です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00391', 'INC-2020-00391', '本事象に関する調査を行ったところ、定例リリース直後にキャッシュヒット率が低下し、それに伴いDB負荷が増加する現象が確認されました。調査の結果、新機能にインデックスが未適用であることが問題の根本原因として特定されました。今後の対応として、該当機能に対するインデックス適用を優先的に行う必要があります。', '本事象に関する調査を行ったところ、定例リリース直後にキャッシュヒット率が低下し、それに伴いDB負荷が増加する現象が確認されました。調査の結果、新機能にインデックスが未適用であることが問題の根本原因として特定されました。今後の対応として、該当機能に対するインデックス適用を優先的に行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-16T19:32:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00573', 'INC-2020-00391', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-15T19:47:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T20:47:53+09:00', '【初期対応】【性能・負荷障害】キャッシュヒット率低下に対する初期対応', 'インシデント発生後、運用部の運用 一郎が初期対応として状況を確認しました。キャッシュヒット率の低下が全テナントに影響を与えていることが確認され、DB負荷の状況をモニタリングしました。新機能に対するインデックス適用を早急に行う方針を決定し、必要な手順を準備しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00574', 'INC-2020-00391', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-15T21:17:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T22:17:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00395', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-28T09:20:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T09:50:36+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2020年5月10日、顧客のリテール株式会社において、夜間整合性チェックで不一致アラートが多発しました。発生契機は月末棚卸の開始時であり、整合性チェック基準の変更が未反映であることが推定されます。この問題により、バッチ処理に限り影響が出ており、オンラインには影響がありませんでした。エラーコードはSYNC-06-00395で、Mercury AWS APの整合性チェックジョブに関連しています。また、運用部の運用 一郎がこの問題を発見しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00395', 'INC-2020-00395', '本インシデントについて調査を行った結果、夜間整合性チェックの実行時に不一致アラートが多発したことが確認されました。この原因として、整合性チェック基準の変更が未反映であったことが浮かび上がりました。月末棚卸の開始に伴い、カバレッジが不十分であったことが不一致の要因と考えられます。さらに、影響を受けたのはバッチ処理であり、オンライン業務には影響がないことも確認されています。', '本インシデントについて調査を行った結果、夜間整合性チェックの実行時に不一致アラートが多発したことが確認されました。この原因として、整合性チェック基準の変更が未反映であったことが浮かび上がりました。月末棚卸の開始に伴い、カバレッジが不十分であったことが不一致の要因と考えられます。さらに、影響を受けたのはバッチ処理であり、オンライン業務には影響がないことも確認されています。', TIMESTAMP WITH TIME ZONE '2020-04-29T09:50:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00579', 'INC-2020-00395', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T10:05:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T11:05:36+09:00', '初期対応', '2020年5月10日、発生が確認された直後に、運用部の運用 一郎が初期対応を実施しました。整合性チェックの基準変更を適用するために、関連データの確認と修正作業を開始しました。これにより、夜間整合性チェックの異常な挙動を解決するための準備が整えられました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00396', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-23T10:51:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T11:51:18+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2020年4月23日10時51分、株式会社ストッククラウドの顧客拠点NWにおいて、顧客固定IP変更が許可リストに未反映の事象が発生しました。この障害は、顧客オンボーディング当日に発生しており、影響範囲は単一店舗に限られています。発見者は営業部の花子で、問題が確認されたのは11時56分です。エラーコードはNW-07-00396で、推定される原因はIP許可リスト更新漏れです。現在、システムの影響が確認されており、適切な対策が必要です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00396', 'INC-2020-00396', '本事象についての調査を行ったところ、顧客オンボーディング当日に顧客固定IP変更が許可リストに未反映であることが確認されました。これにより、顧客ネットワークの接続に影響を及ぼしました。原因としては、IP許可リストの更新漏れが挙げられます。今後、こうした事象が発生しないように、許可リストの管理プロセスを強化する必要があります。', '本事象についての調査を行ったところ、顧客オンボーディング当日に顧客固定IP変更が許可リストに未反映であることが確認されました。これにより、顧客ネットワークの接続に影響を及ぼしました。原因としては、IP許可リストの更新漏れが挙げられます。今後、こうした事象が発生しないように、許可リストの管理プロセスを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T11:51:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00580', 'INC-2020-00396', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T12:06:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T13:06:18+09:00', '【初期対応】固定IP変更未連絡', '営業部の花子からの報告を受け、直ちにIP許可リストを確認しました。顧客の固定IP変更が反映されていないことが確認されたため、速やかに許可リストの更新作業を開始しました。また、顧客への連絡を行い、状況を説明するとともに、今後の対応について合意を得ました。引き続き、進捗を確認し、適切な対策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00397', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-26T17:41:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T18:11:39+09:00', '【障害報告】【性能・負荷障害】キャッシュヒット率低下', '2020年04月26日17時41分39秒に、株式会社ストッククラウドのサービスMercuryにおいて、キャッシュヒット率低下によるDB負荷増が発生いたしました。発生個所はVenus Azure APであり、影響は全テナントに及びました。定例リリース直後に発生したことから、新機能にインデックスが未適用であったことが推定原因と考えられます。この障害は2020年04月26日17時57分39秒に検知され、検知までに16分を要しました。エラーコードはPRF-09-00397です。今後の対応が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00397', 'INC-2020-00397', '障害発生後、迅速に調査を行いました。定例リリース直後に発生したため、リリースに関連する新機能に着目し、キャッシュヒット率低下がDB負荷増に繋がったことを確認しました。インデックス未適用の状態が問題であると特定され、このままでは全テナントに影響を及ぼすことが懸念されます。さらなる調査を継続し、詳細な原因分析を実施する必要があります。', '障害発生後、迅速に調査を行いました。定例リリース直後に発生したため、リリースに関連する新機能に着目し、キャッシュヒット率低下がDB負荷増に繋がったことを確認しました。インデックス未適用の状態が問題であると特定され、このままでは全テナントに影響を及ぼすことが懸念されます。さらなる調査を継続し、詳細な原因分析を実施する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-27T18:11:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00581', 'INC-2020-00397', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T18:26:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T19:26:39+09:00', '【初動対応】【性能・負荷障害】キャッシュヒット率低下の初期対応', '初動対応として、運用部の運用 一郎が主導となり、該当システムの確認を行いました。キャッシュレイヤの状態を監視し、DB負荷を軽減するための暫定措置を講じました。具体的には、影響を受ける新機能の一時的な無効化を行い、DB負荷を抑える対策を実施いたしました。引き続き、システムの状況を注視し、問題の根本的な解決策を検討して参ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00582', 'INC-2020-00397', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T19:56:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T20:56:39+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00399', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-19T08:18:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T08:48:47+09:00', '【障害報告】【CLU-09】クロスリージョンレプリケーション', '2023-10-01T10:00:00+09:00、株式会社ストッククラウドのMercuryにて、クロスリージョン複製が片系のみ更新される事象が発生しました。発生契機はインフラメンテナンス明けであり、特定リージョンのユーザーに影響が及んでいます。エラーコードはSYNC-07-00399です。影響を受けたコンポーネントはMercury AWS AP（Secondary）およびレプリケーションゲートウェイです。インフラメンテナンス後にデータの同期・整合性に問題が確認されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00399', 'INC-2020-00399', 'インフラメンテナンス明けに、対象リージョンにおいてクロスリージョン複製のルーティング設定に異常が見受けられました。原因として、リージョンルーティングの誤設定が疑われます。このため、特定ユーザーに対してデータ同期が正しく行われず、片系のみが更新される事象が確認されました。引き続き詳細な分析を進めます。', 'インフラメンテナンス明けに、対象リージョンにおいてクロスリージョン複製のルーティング設定に異常が見受けられました。原因として、リージョンルーティングの誤設定が疑われます。このため、特定ユーザーに対してデータ同期が正しく行われず、片系のみが更新される事象が確認されました。引き続き詳細な分析を進めます。', TIMESTAMP WITH TIME ZONE '2020-04-20T08:48:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00584', 'INC-2020-00399', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T09:03:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T10:03:47+09:00', '初期対応', '運用部の運用 一郎が、発生したクロスリージョン複製の問題に対し初期対応を実施しました。特定のリージョンにおけるデータ同期・整合性の確認を行い、即座にリージョンルーティングの設定を見直しました。今後、影響を受けるユーザーへの周知を図り、必要な対策を講じる予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00405', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-11T15:02:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T15:32:28+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2023-10-11T10:15:00+09:00に発生したインシデントについて報告します。株式会社ストッククラウドのサービスMercuryにおいて、Cookie SameSite設定の影響で埋込画面が認証不可となりました。発生は定例リリース直後であり、影響範囲は単一店舗のみとなります。エラーコードはAUTH-06-00405です。運用部の運用 一郎が発見し、検知まで21分を要しました。技術的には、SameSite属性変更の影響が疑われます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00405', 'INC-2020-00405', '本インシデントについての調査を行いました。運用 一郎は、定例リリース直後に発生したことを確認しました。技術詳細として、Cookie SameSite設定が原因で埋込画面が認証不可となっていることが話題に上りました。影響を受けたのはVenus Azure APおよびセッションストアです。引き続き、SameSite属性変更の影響を精査し、さらなる再発防止策を検討します。', '本インシデントについての調査を行いました。運用 一郎は、定例リリース直後に発生したことを確認しました。技術詳細として、Cookie SameSite設定が原因で埋込画面が認証不可となっていることが話題に上りました。影響を受けたのはVenus Azure APおよびセッションストアです。引き続き、SameSite属性変更の影響を精査し、さらなる再発防止策を検討します。', TIMESTAMP WITH TIME ZONE '2020-04-12T15:32:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00594', 'INC-2020-00405', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T15:47:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T16:47:28+09:00', '対応開始', '運用 一郎からの報告を受け、迅速に対応を開始しました。CookieのSameSite設定に関連する問題が確認されたため、即座に技術チームと連携し、該当箇所の調査を行っています。現在、問題の特定と解決に向けて全力で取り組んでいます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00406', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-02T09:11:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T09:41:53+09:00', '【障害報告】【CLU-07】配送連携ステータス停滞', '2020年4月2日09時11分53秒に、株式会社ストッククラウドのサービスMercuryにおいて、配送連携のステータスが出荷済みで停滞する事象が発生しました。重大度はMEDIUMで、影響範囲は単一店舗のみです。この問題は、2020年4月2日09時52分53秒に検知されました。発生契機は大規模セール開始直前であり、主な原因としてステータスマッピング表の更新漏れが疑われます。影響を受けたコンポーネントはMercury AWS AP（ゾーンB）および配送連携アダプタです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00406', 'INC-2020-00406', '本事象の調査を行ったところ、配送連携のステータスが出荷済みで停滞していることが確認されました。原因としては、ステータスマッピング表の更新漏れが影響を及ぼしていると考えられます。早急にステータスマッピング表の見直しを行い、問題の解決に向けた対策を実施する必要があります。', '本事象の調査を行ったところ、配送連携のステータスが出荷済みで停滞していることが確認されました。原因としては、ステータスマッピング表の更新漏れが影響を及ぼしていると考えられます。早急にステータスマッピング表の見直しを行い、問題の解決に向けた対策を実施する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-03T09:41:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00595', 'INC-2020-00406', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T09:56:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T10:56:53+09:00', '【初期対応】【CLU-07】配送連携ステータス停滞への初期対応', '初期対応として、運用部の運用 一郎が配送連携の状況を確認し、ステータスマッピング表の状態を調査しました。さらに、影響を受けた店舗に対して状況説明を行い、安否確認を実施しました。原因がステータスマッピング表の更新漏れであることを特定し、迅速な修正作業を進めるための指示を出しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00596', 'INC-2020-00406', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T11:26:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T12:26:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00408', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-06T22:42:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T23:12:30+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2020年04月06日22時42分30秒、株式会社ストッククラウドのサービスMercuryにおいて、在庫登録APIに関連するバルクAPIが部分失敗しました。この事象はデータ移行バッチ実行中に発生し、ロールバックが未完了な状態となりました。推定される原因は、部分成功時の補償トランザクションの欠如です。この影響により、サービス全体の一部機能に不具合が生じました。特にMercury AWS AP（ゾーンB）において、在庫登録APIが正常に機能しないケースが発生しており、顧客に対する影響が懸念されます。今後の対策として、補償トランザクションの実装を検討し、再発防止に向けた対応を進める必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00408', 'INC-2020-00408', '本インシデントの調査により、発生契機であるデータ移行バッチ実行中に、バルクAPIが部分失敗を引き起こしたことが確認されました。また、ロールバックが適切に行われなかったため、システムに不整合が生じました。原因としては、部分成功時に補償トランザクションが実施されなかったことが根本的な要因であると考えられます。これにより、今後は補償処理に関する設計を見直す必要があります。', '本インシデントの調査により、発生契機であるデータ移行バッチ実行中に、バルクAPIが部分失敗を引き起こしたことが確認されました。また、ロールバックが適切に行われなかったため、システムに不整合が生じました。原因としては、部分成功時に補償トランザクションが実施されなかったことが根本的な要因であると考えられます。これにより、今後は補償処理に関する設計を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-07T23:12:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00598', 'INC-2020-00408', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T23:27:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T00:27:30+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗', 'インシデント発生後、運用部の運用 一郎が直ちに対応にあたり、部分失敗したバルクAPIの状況を確認しました。ロールバック未完了の状態であることを把握し、運用チームと連携して影響範囲を特定しました。また、関係者への情報共有を行いながら、補償トランザクションの実施を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00409', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-15T23:58:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T00:43:51+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2020年4月16日23時58分51秒、株式会社ストッククラウドのMercuryにおいて、ストレージ溢れの障害が発生しました。死活監視が正常系をDOWNと誤検知し、運用部門に影響を与えました。検知は36分後の00時34分51秒に行われました。この障害は、定例リリース直後に発生したものであり、監視プローブのUser-Agentがブロックされたことが推定原因と考えられます。エラーコードはMON-01-00409です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00409', 'INC-2020-00409', '本件の調査では、定例リリース後に死活監視が正常系をDOWNと誤検知した原因として、監視プローブのUser-Agentがブロックされている可能性が確認されました。この影響により、運用部門は誤った情報に基づいて対応を行う必要が生じました。今後は、監視プローブの設定を見直し、再発防止に努める必要があります。', '本件の調査では、定例リリース後に死活監視が正常系をDOWNと誤検知した原因として、監視プローブのUser-Agentがブロックされている可能性が確認されました。この影響により、運用部門は誤った情報に基づいて対応を行う必要が生じました。今後は、監視プローブの設定を見直し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-17T00:43:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00599', 'INC-2020-00409', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T00:58:51+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T01:58:51+09:00', '【初期対応】【監視・可用性障害】死活監視誤検知', '運用部門において、死活監視が正常系をDOWNと誤検知していることが確認され次第、直ちに確認作業を実施しました。監視ログを調査したところ、定例リリース直後に監視プローブのUser-Agentがブロックされていることが判明しました。このため、誤った監視結果が出力されていたことが原因です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00410', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-15T07:49:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T09:49:55+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '2023-10-01T08:00:00+09:00に発生した棚卸突合失敗について報告いたします。本事象では、実地棚卸数とシステム在庫に大幅な乖離が見られました。この問題により、同一顧客の全店舗において棚卸数の正確な把握が困難となっております。発生契機は月末棚卸の開始時であり、検知は2023-10-01T09:30:00+09:00に行われました。影響コンポーネントは顧客店舗POS及び棚卸突合エンジンです。原因として棚卸スナップショット時刻のずれが疑われており、現在調査を進めております。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00410', 'INC-2020-00410', '本事象の調査を開始いたしました。現時点では、棚卸スナップショット時刻のずれが原因である可能性が高いことが確認されております。さらに、棚卸データの取得時刻とシステム在庫が一致していないことが問題を引き起こした要因と考えられます。調査を進めることで、詳細な原因究明と再発防止策を講じる所存です。', '本事象の調査を開始いたしました。現時点では、棚卸スナップショット時刻のずれが原因である可能性が高いことが確認されております。さらに、棚卸データの取得時刻とシステム在庫が一致していないことが問題を引き起こした要因と考えられます。調査を進めることで、詳細な原因究明と再発防止策を講じる所存です。', TIMESTAMP WITH TIME ZONE '2020-04-16T09:49:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00600', 'INC-2020-00410', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-15T10:04:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T11:04:55+09:00', '【初期対応】【棚卸・POS突合障害】棚卸実地差異への初期対応', '今回の棚卸突合失敗に対して、初期対応を実施しました。担当者が顧客店舗POSのデータを確認し、棚卸スナップショットの時刻を再確認しています。また、全店舗に対して実地棚卸の状況を確認するための連絡を行いました。データの整合性を確保するため、棚卸突合エンジンの設定も見直す予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00412', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-17T15:17:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T15:47:36+09:00', '【障害報告】【監視・可用性障害】トレースサンプリング過少', '2020年4月17日15時17分36秒に、株式会社ストッククラウドのサービスMercuryにおいて、利用者増による応答遅延が発生いたしました。この障害は分散トレースのサンプリング率が過少であったため、原因特定が困難な状態となっております。影響範囲は運用部門のみであり、原因としてはサンプリング率の本番設定誤りが疑われています。特に、定例リリース直後にトレーシング基盤においてこの問題が顕在化したことが確認されています。エラーコードはMON-05-00412で、影響を受けたコンポーネントはVenus Azure AP（DRサイト）です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00412', 'INC-2020-00412', '障害発生後に行った調査により、分散トレースのサンプリング率が過少であったことが判明しました。このことにより、原因特定が困難な状況が続いています。定例リリース直後のタイミングで問題が顕在化したため、サンプリング率の設定に関する確認を実施し、設定誤りの確認を急ぎます。今後の対応策を検討し、早急な解決を目指します。', '障害発生後に行った調査により、分散トレースのサンプリング率が過少であったことが判明しました。このことにより、原因特定が困難な状況が続いています。定例リリース直後のタイミングで問題が顕在化したため、サンプリング率の設定に関する確認を実施し、設定誤りの確認を急ぎます。今後の対応策を検討し、早急な解決を目指します。', TIMESTAMP WITH TIME ZONE '2020-04-18T15:47:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00602', 'INC-2020-00412', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T16:02:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T17:02:36+09:00', '初期対応報告', '本件について、運用部門より初期対応を実施しております。現時点で分散トレースのサンプリング率についての設定を見直し、原因特定に向けた作業を進めております。今後は、影響を受けたコンポーネントの健全性を確認し、監視体制の強化を図る予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00414', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-07T09:53:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T10:23:15+09:00', '【障害報告】【CLU-07】配送連携ステータス停滞', '2023-10-10T12:00:00+09:00 に、株式会社ストッククラウドのサービスMercuryにおいて、配送連携のステータスが出荷済みで停滞する事象が発生しました。発見者は運用部の運用 一郎であり、影響範囲は単一店舗に限定されています。発生契機は大規模セール開始直前であり、エラーコードはEDI-09-00414です。ステータスマッピング表の更新漏れが推定原因と考えられ、この問題は特に配送連携アダプタとMercury AWS APに影響を及ぼしております。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00414', 'INC-2020-00414', '本件についての調査を行った結果、配送連携のステータスが出荷済みで停滞する原因として、ステータスマッピング表の更新漏れが確認されました。このため、API連携・EDIにおいて正しいステータスが反映されず、顧客への影響が懸念されます。早急な対応が必要です。', '本件についての調査を行った結果、配送連携のステータスが出荷済みで停滞する原因として、ステータスマッピング表の更新漏れが確認されました。このため、API連携・EDIにおいて正しいステータスが反映されず、顧客への影響が懸念されます。早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-08T10:23:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00604', 'INC-2020-00414', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T10:38:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T11:38:15+09:00', '初期対応', '本障害に対しては、運用部によりステータスマッピング表の確認と更新作業を実施しました。これにより、配送連携のステータスが正常に反映されるよう対応しました。今後同様の事象が発生しないよう、定期的な監査を行う方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
