INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00609', 'INC-2020-00417', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T21:31:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T22:31:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00418', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-25T19:23:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T21:23:44+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2023年10月15日、株式会社ストッククラウドの顧客において、棚卸確定ボタンがグレーアウトしたまま操作できない事象が発生しました。この問題は、顧客店舗POSにおいて確認でき、影響範囲は単一店舗に限定されています。発生契機は月末棚卸の開始時で、エラーコードはINV-03-00418です。発見者は営業部の花子で、検知は85分後の20時48分に行われました。技術的には、未処理の差異調整レコード残留が原因である可能性が疑われます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00418', 'INC-2020-00418', '今回の棚卸確定不可の事象について調査を行いました。まず、影響を受けた店舗のPOSシステムのログを確認したところ、月末棚卸の開始時に未処理の差異調整レコードが残留していることが確認されました。このため、棚卸確定ボタンが正常に操作できない状態が発生しました。今後は、差異調整レコードの管理方法を見直す必要があります。', '今回の棚卸確定不可の事象について調査を行いました。まず、影響を受けた店舗のPOSシステムのログを確認したところ、月末棚卸の開始時に未処理の差異調整レコードが残留していることが確認されました。このため、棚卸確定ボタンが正常に操作できない状態が発生しました。今後は、差異調整レコードの管理方法を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-26T21:23:44+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00610', 'INC-2020-00418', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-25T21:38:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T22:38:44+09:00', '【初期対応】【棚卸・POS突合障害】', '初期対応として、影響を受けている店舗のPOSシステムを再起動し、未処理の差異調整レコードを確認することを指示しました。また、店舗担当者には、棚卸確定ボタンの操作方法を再度周知し、影響の範囲を把握するよう指示しました。これにより、問題の早期解決を目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00611', 'INC-2020-00418', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-25T23:08:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T00:08:44+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00420', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-25T15:01:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T15:31:55+09:00', '【障害報告】【性能・負荷障害】下流APIレート制限', '2020年4月25日15時01分55秒、株式会社ストッククラウドのMercuryにおいて、下流APIのレート制限により処理待ちが増大する障害が発生しました。影響の範囲はサービス全体の一部機能に及び、エラーコードはPRF-07-00420です。発生契機は大規模セール開始直前であり、15時48分55秒にこの問題が検知されました。下流APIのレート制限が原因とされ、特にVenus Azure APとAPIゲートウェイが影響を受けています。待ち行列が発生し、性能・負荷障害が懸念されます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00420', 'INC-2020-00420', '障害発生後、運用部の運用 一郎が調査を開始しました。調査の結果、下流APIのレート制限が原因であることが明らかになりました。大規模セール開始直前にこの制限が適用され、待ち行列が発生したと考えられます。システムの状況を確認し、対策を講じる必要があります。', '障害発生後、運用部の運用 一郎が調査を開始しました。調査の結果、下流APIのレート制限が原因であることが明らかになりました。大規模セール開始直前にこの制限が適用され、待ち行列が発生したと考えられます。システムの状況を確認し、対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-26T15:31:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00614', 'INC-2020-00420', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T15:46:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T16:46:55+09:00', '【初期対応】【性能・負荷障害】下流APIレート制限', '初期対応として、運用 一郎は下流APIのレート制限を見直すよう運用部に指示しました。また、影響を受けた機能の利用状況を監視し、必要に応じて速やかに対応できるよう準備を進めています。引き続き状況を確認し、顧客への影響を最小限に抑えるための措置を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00421', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-19T20:54:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T21:24:45+09:00', '【障害報告】【在庫マスター設定障害】マイナス在庫表示', '・発生日時: 2023-10-05T14:30:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00421', 'INC-2020-00421', '本障害に関して調査を行った結果、顧客である株式会社ストッククラウドの在庫登録にて、登録後に在庫数量がマイナス表示される事象が確認されました。原因はデフォルト倉庫IDの未設定である可能性が高く、これにより月末棚卸の開始時に影響が出たと考えられます。影響を受けた店舗を特定し、迅速な対応が求められます。', '本障害に関して調査を行った結果、顧客である株式会社ストッククラウドの在庫登録にて、登録後に在庫数量がマイナス表示される事象が確認されました。原因はデフォルト倉庫IDの未設定である可能性が高く、これにより月末棚卸の開始時に影響が出たと考えられます。影響を受けた店舗を特定し、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-20T21:24:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00615', 'INC-2020-00421', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T21:39:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T22:39:45+09:00', '【初期対応】【在庫マスター設定障害】マイナス在庫表示', '本事象に対する初期対応として、まずはデフォルト倉庫IDの設定状況を確認しました。また、影響を受けた店舗への通知を行い、在庫状況の確認を依頼しました。社員への情報共有も行い、今後同様の事象が発生しないよう注意喚起を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00423', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-01T16:28:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T18:28:00+09:00', '【障害報告】【棚卸・POS突合障害】月次突合不一致', '2020年4月1日16時28分に発生した棚卸突合失敗に関する障害報告です。本障害は、月次突合レポートの合計が帳票と不一致であることが症状として現れました。発生は、月末棚卸の開始時に確認されました。原因としては、返品データの符号反転漏れが疑われており、同一顧客の全店舗に影響を与えています。エラーコードはINV-05-00423で、影響を受けたコンポーネントは顧客店舗POS（Secondary）および月次集計ジョブです。なお、本障害は2020年4月1日18時30分に検知され、検知までに122分を要しました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00423', 'INC-2020-00423', '本インシデントに関する調査を行いました。調査の結果、月次突合レポートの合計が帳票と不一致であることが確認されました。返品データの符号反転漏れが主な原因として特定され、これによって全店舗の月次突合に問題が発生しました。今後、このような事象を防ぐための対策を検討いたします。', '本インシデントに関する調査を行いました。調査の結果、月次突合レポートの合計が帳票と不一致であることが確認されました。返品データの符号反転漏れが主な原因として特定され、これによって全店舗の月次突合に問題が発生しました。今後、このような事象を防ぐための対策を検討いたします。', TIMESTAMP WITH TIME ZONE '2020-04-02T18:28:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00618', 'INC-2020-00423', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-01T18:43:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T19:43:00+09:00', '【初動対応】【棚卸・POS突合障害】初動対応', 'インシデント発生直後、担当の営業部 花子が状況を確認し、関連するデータの再確認を行いました。問題の範囲を特定するために、各店舗のPOSデータを集約し、月次突合レポートとの整合性をチェックしました。また、影響を受けている店舗への連絡を行い、状況の把握に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00619', 'INC-2020-00423', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-01T20:13:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T21:13:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00424', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-22T05:39:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T06:24:13+09:00', '[障害報告][CLU-10]ヘルスチェック過負荷', '2020年4月22日05時39分13秒に発生したインシデントについて報告します。今回の問題は、ヘルスチェック過多によるAPサーバーの負荷増が主な症状で、全テナントに波及しました。発生契機はインフラメンテナンス明けで、エラーコードはMON-06-00424です。この問題はMercury AWS Storage（Primary）およびロードバランサに影響を及ぼしています。運用部の運用 一郎が問題を発見し、06時33分13秒に検知しました。技術的には、LBヘルスチェック間隔の過短設定が原因と考えられます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00424', 'INC-2020-00424', '運用部の運用 一郎によると、インフラメンテナンス明けにヘルスチェックが過多に実施され、APサーバーに負荷がかかっています。LBのヘルスチェック間隔が短すぎることが原因と推測されます。全テナントに影響が及んでいるため、迅速な対応が求められます。', '運用部の運用 一郎によると、インフラメンテナンス明けにヘルスチェックが過多に実施され、APサーバーに負荷がかかっています。LBのヘルスチェック間隔が短すぎることが原因と推測されます。全テナントに影響が及んでいるため、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-23T06:24:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00620', 'INC-2020-00424', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T06:39:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T07:39:13+09:00', '[対応履歴][CLU-10]ヘルスチェック過負荷初期対応', '運用 一郎が2020年4月22日06時33分13秒にインシデントを検知し、初動としてLBのヘルスチェック設定を確認しました。設定が過短であることが判明し、即座に設定の見直しを依頼しました。今後、監視・可用性障害を防ぐために、設定を調整する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00425', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-27T15:19:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T15:34:15+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2020年4月27日15時19分15秒、株式会社ストッククラウドのMercuryにおいて、運用者の作業ミスによるアクセス障害が発生いたしました。発生時にはログに相関IDが欠落し、横断検索が不可となっておりました。この障害は運用部門に影響を及ぼし、発見者は運用一郎（運用部）でございます。検知は15分後の15時34分15秒に行われ、定例リリース直後の影響と考えられます。エラーコードはMON-09-00425であり、原因としてログフォーマット変更のロールアウト漏れが疑われております。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00425', 'INC-2020-00425', '障害発生後の調査において、定例リリース直後にログに相関IDが欠落したことが確認されました。この影響により、横断検索が不可となり、運用部門の業務に支障を来しました。原因として、ログフォーマット変更のロールアウト漏れが考えられ、この点について詳細な状況を確認する必要があります。ログフォーマットの変更履歴及びリリース手順に関する調査を進めております。', '障害発生後の調査において、定例リリース直後にログに相関IDが欠落したことが確認されました。この影響により、横断検索が不可となり、運用部門の業務に支障を来しました。原因として、ログフォーマット変更のロールアウト漏れが考えられ、この点について詳細な状況を確認する必要があります。ログフォーマットの変更履歴及びリリース手順に関する調査を進めております。', TIMESTAMP WITH TIME ZONE '2020-04-28T15:34:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00621', 'INC-2020-00425', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T15:49:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T16:49:15+09:00', '【初期対応】【監視・可用性障害】ログ相関ID欠落に対する初期対応', '初期対応として、運用部門にて該当のログフォーマットについて確認を行いました。相関ID欠落の原因を特定するために、運用コンソールの設定を見直し、必要な修正を迅速に行う方針です。また、影響を受けた運用部門には障害の状況を共有し、業務継続に関する対策を講じております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00622', 'INC-2020-00425', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T17:19:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T18:19:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00426', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-08T10:27:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T11:12:07+09:00', '【障害報告】【CLU-10】合成監視失敗', '・発生日時: 2023-10-10T09:30:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00426', 'INC-2020-00426', '調査の結果、合成監視が特定ステップで失敗した原因として、テストデータの期限切れが疑われます。これにより、合成監視が正常に機能せず、サービス全体の一部機能が影響を受けている状況です。運用チームはこの問題を早急に解決する必要があります。具体的には、テストデータの更新と監視システムの再設定が求められます。', '調査の結果、合成監視が特定ステップで失敗した原因として、テストデータの期限切れが疑われます。これにより、合成監視が正常に機能せず、サービス全体の一部機能が影響を受けている状況です。運用チームはこの問題を早急に解決する必要があります。具体的には、テストデータの更新と監視システムの再設定が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-09T11:12:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00623', 'INC-2020-00426', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T11:27:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T12:27:07+09:00', '初期対応', '初期対応として、運用チームはただちにテストデータの更新作業を開始しました。また、合成監視ランナーの設定を確認し、必要に応じて修正を行う方針です。さらに、影響を受けたサービス機能の代替手段を検討し、顧客への対応を進めます。今後の進展については随時報告を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00624', 'INC-2020-00426', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T12:57:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T13:57:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00427', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-16T22:55:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T23:25:32+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2020年4月17日、顧客からの問い合わせにより、Mercuryサービスにおいてヘルスチェック過多でAPサーバー負荷増の事象が発生しました。影響は全テナントに波及しており、特にVenus Azure APにおいて顕著です。運用 一郎が運用部から発見し、問題の詳細を調査したところ、インフラメンテナンス明けにLBヘルスチェック間隔の過短設定が原因であると考えられます。検知は2020年4月17日23時21分に行われ、発生から26分後のことでした。エラーコードはMON-06-00427です。この状況を受けて、迅速な対応が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00427', 'INC-2020-00427', '運用 一郎がこの問題を調査したところ、ヘルスチェックの過負荷がAPサーバーに影響を及ぼしているため、即座に原因を特定する必要があります。特に、LBヘルスチェック間隔の設定が短すぎることが問題であり、これによりサーバー負荷が増加しました。今後の対策として、LBの設定変更が求められます。状況を注視し、必要に応じて追加の調査を行っていきます。', '運用 一郎がこの問題を調査したところ、ヘルスチェックの過負荷がAPサーバーに影響を及ぼしているため、即座に原因を特定する必要があります。特に、LBヘルスチェック間隔の設定が短すぎることが問題であり、これによりサーバー負荷が増加しました。今後の対策として、LBの設定変更が求められます。状況を注視し、必要に応じて追加の調査を行っていきます。', TIMESTAMP WITH TIME ZONE '2020-04-17T23:25:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00625', 'INC-2020-00427', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T23:40:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T00:40:32+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎が本事象に対し、即時に対応にあたりました。まずは、ヘルスチェックの設定を見直し、LBのヘルスチェック間隔を延長することを検討中です。また、問題の影響を受けている全テナントへの通知を行いました。今後、追加の調査を通じて、根本的な解決策を見つける必要があります。状況が改善されるまで、監視を強化し、定期的に進捗を報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00626', 'INC-2020-00427', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T01:10:32+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T02:10:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00429', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-05T11:21:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T11:51:52+09:00', '【障害報告】【CLU-09】アウトボックス滞留', '2023年10月10日11時21分に、株式会社ストッククラウドのMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。発生契機は定例リリース直後であり、アウトボックステーブルに滞留が生じ、結果として通知遅延が確認されました。実施された検知は2023年10月10日12時02分で、発生から41分後のことでした。この障害はMercury AWS APおよびイベントバスに関わるサービス全体の一部機能に影響を及ぼしました。エラーコードはSYNC-05-00429で、推定原因としてはアウトボックスポーラーの停止が考えられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00429', 'INC-2020-00429', 'インシデントの調査において、アウトボックステーブルの滞留が確認されました。この滞留は定例リリース直後に発生し、通知遅延の原因としてアウトボックスポーラーの停止が疑われます。現在、具体的な原因を特定するための詳細な分析を進めています。', 'インシデントの調査において、アウトボックステーブルの滞留が確認されました。この滞留は定例リリース直後に発生し、通知遅延の原因としてアウトボックスポーラーの停止が疑われます。現在、具体的な原因を特定するための詳細な分析を進めています。', TIMESTAMP WITH TIME ZONE '2020-04-06T11:51:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00629', 'INC-2020-00429', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-05T12:06:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T13:06:52+09:00', '【対応】【CLU-09】初期対応', '初期対応として、アウトボックステーブルの状態を確認し、アウトボックスポーラーの再起動を試みました。また、関連ログを収集し、問題の根本原因を特定するための分析を行っています。影響を受けた顧客への通知も準備中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00433', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-28T19:50:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T20:20:39+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2020年5月5日15時30分、株式会社ストッククラウドのMercuryサービスにおいて、運用部門が横断検索機能において問題を確認いたしました。具体的には、ログに相関IDが欠落しており、横断検索が不可能な状態となっております。この事象は定例リリース直後に発生し、運用部門に影響を及ぼしています。エラーコードはMON-09-00433であり、ログフォーマット変更のロールアウト漏れが推定原因と考えられます。影響を受けるコンポーネントはVenus Azure AP（Secondary）およびログパイプラインです。今後の調査を進め、早急に解決策を講じてまいります。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00433', 'INC-2020-00433', '運用部門において、特定の時間に発生した相関ID欠落の問題について調査を開始いたしました。定例リリース直後に発生したことから、リリース内容とログフォーマットの変更について確認を行います。原因として考えられるログフォーマット変更のロールアウト漏れに関しても詳細な検証を行い、障害の全容を明らかにする予定です。', '運用部門において、特定の時間に発生した相関ID欠落の問題について調査を開始いたしました。定例リリース直後に発生したことから、リリース内容とログフォーマットの変更について確認を行います。原因として考えられるログフォーマット変更のロールアウト漏れに関しても詳細な検証を行い、障害の全容を明らかにする予定です。', TIMESTAMP WITH TIME ZONE '2020-04-29T20:20:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00636', 'INC-2020-00433', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T20:35:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T21:35:39+09:00', '初期対応', '本事象に関し、運用部門は即座に初期対応を開始しました。ログフォーマットの変更について確認し、相関IDの欠落が発生しているログを特定するための作業を進めています。今後、必要な修正を施した後、正常な状態に戻すための対策を講じる所存です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00637', 'INC-2020-00433', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T22:05:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T23:05:39+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00434', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-21T16:35:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T17:05:19+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2020年4月21日16時35分に株式会社ストッククラウドのMercuryにおいて、SKU登録APIがHTTP 500を返し在庫反映に失敗する事象が発生しました。この障害は、定例リリース直後に確認され、単位換算係数の設定漏れが推定されます。影響範囲としては単一店舗の登録機能のみに及び、他の機能には影響を与えていないことが確認されています。エラーコードはMST-01-00434であり、原因特定に向けた調査が必要です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00434', 'INC-2020-00434', 'インシデント発生日から約18分後の2020年4月21日16時53分に、影響を受けたSKU登録APIの調査を開始しました。調査の結果、定例リリース直後に実施された設定変更において、単位換算係数が未設定であることが判明しました。これにより、HTTP 500エラーが発生したものと考えられます。今後、再発防止策を講じる必要があります。', 'インシデント発生日から約18分後の2020年4月21日16時53分に、影響を受けたSKU登録APIの調査を開始しました。調査の結果、定例リリース直後に実施された設定変更において、単位換算係数が未設定であることが判明しました。これにより、HTTP 500エラーが発生したものと考えられます。今後、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-22T17:05:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00638', 'INC-2020-00434', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T17:20:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T18:20:19+09:00', '【対応報告】【在庫マスター設定障害】初期対応', '最初の対応として、SKU登録APIに対するリクエストを確認し、HTTP 500エラーが発生した原因を特定するための調査を開始しました。その結果、単位換算係数の設定漏れが原因であることが明らかとなりました。必要な設定を速やかに行い、再度APIの検証を実施して正常に動作することを確認しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00438', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-26T22:59:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T23:29:31+09:00', '【障害報告】【CLU-06】特定顧客のみ劣化', '2023年10月01日22時30分、株式会社ストッククラウドのMercuryサービスにおいて、特定顧客テナントのみレスポンスが劣化する事象が発生しました。本事象は、顧客オンボーディング当日に発生しており、影響範囲は単一店舗に限られます。テナント別リソース制限の誤設定が推定原因として考えられており、影響コンポーネントはVenus Azure AP（ゾーンA）のAPサーバークラスタです。ユーザーがサービスを利用する際に影響が発生し、快適な利用が損なわれました。エラーコードはPRF-05-00438です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00438', 'INC-2020-00438', '本事象に関する調査を実施した結果、顧客オンボーディング当日に特定顧客テナントのみレスポンスが劣化したことが確認されました。テナント別リソース制限の誤設定が原因として疑われており、具体的には、リソースが適切に割り当てられていなかったことが考えられます。今後は、リソース制限の設定を見直し、適切な管理を行う必要があります。', '本事象に関する調査を実施した結果、顧客オンボーディング当日に特定顧客テナントのみレスポンスが劣化したことが確認されました。テナント別リソース制限の誤設定が原因として疑われており、具体的には、リソースが適切に割り当てられていなかったことが考えられます。今後は、リソース制限の設定を見直し、適切な管理を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-27T23:29:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00643', 'INC-2020-00438', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T23:44:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T00:44:31+09:00', '【初期対応】【CLU-06】特定顧客のみ劣化', '2023年10月01日22時45分、運用部の運用 一郎が本事象の初期対応を実施しました。テナント別リソース制限の設定状況を確認し、誤設定を修正する作業を開始しました。また、影響を受けた顧客への連絡を行い、状況の説明とお詫びを行いました。今後、同様の事象を防ぐために再発防止策を検討していきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00644', 'INC-2020-00438', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T01:14:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T02:14:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00440', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-19T11:19:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T13:19:18+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2020年4月19日11時19分18秒に、株式会社ストッククラウドの顧客店舗POSにおいて、夜間整合性チェックで不一致アラートが多発しました。発生契機は月末棚卸の開始時であり、整合性チェック基準の変更未反映が推定原因とされています。検知は2020年4月19日13時07分18秒に行われ、検知まで108分の遅延が発生しました。影響範囲はバッチ処理のみで、オンラインサービスには影響がありません。エラーコードはSYNC-06-00440です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00440', 'INC-2020-00440', '整合性チェックにおいて不一致が発生したため、詳細な調査を開始しました。月末棚卸の開始時に整合性チェック基準の変更が未反映であった可能性が高く、これが不一致アラート多発の原因とみられています。現在、整合性チェックジョブのログと設定を確認中です。', '整合性チェックにおいて不一致が発生したため、詳細な調査を開始しました。月末棚卸の開始時に整合性チェック基準の変更が未反映であった可能性が高く、これが不一致アラート多発の原因とみられています。現在、整合性チェックジョブのログと設定を確認中です。', TIMESTAMP WITH TIME ZONE '2020-04-20T13:19:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00647', 'INC-2020-00440', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T13:34:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T14:34:18+09:00', '【初期対応】【データ同期・整合性障害】整合性チェックアラート', '2020年4月19日11時30分に、まずは整合性チェックジョブの設定を確認しました。整合性チェック基準の変更が正しく反映されていないことが確認されました。月末棚卸に影響が及ぶ可能性を考慮し、早急に設定修正を行う必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00648', 'INC-2020-00440', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T15:04:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T16:04:18+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00443', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-08T14:47:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T15:17:17+09:00', '【障害報告】【認証・セッション障害】ブルートフォース誤検知', '2020年4月9日14時47分に、株式会社ストッククラウドのMercuryサービスにおいて、ブルートフォース検知による正常IPの遮断が発生しました。影響を受けたのはVenus Azure APのゾーンBで、単一店舗の認証・セッションに影響を及ぼしました。発生は大規模セール開始直前に起き、検知まで19分を要しました。エラーコードはAUTH-08-00443で、検知閾値の過敏設定が原因と考えられています。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00443', 'INC-2020-00443', '発生したブルートフォース誤検知に関して、検知システムの設定を見直したところ、過敏すぎる検知閾値が設定されていたことが確認されました。正常なアクセスも遮断されてしまうリスクがあるため、設定の調整が必要です。WAFのログを分析し、今後の対策についても議論を行う予定です。', '発生したブルートフォース誤検知に関して、検知システムの設定を見直したところ、過敏すぎる検知閾値が設定されていたことが確認されました。正常なアクセスも遮断されてしまうリスクがあるため、設定の調整が必要です。WAFのログを分析し、今後の対策についても議論を行う予定です。', TIMESTAMP WITH TIME ZONE '2020-04-09T15:17:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00653', 'INC-2020-00443', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T15:32:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T16:32:17+09:00', '【初動対応】【認証・セッション障害】', '障害発生後、運用部の運用 一郎が迅速に対応にあたり、遮断されていた正常IPの復旧作業を開始しました。WAFの設定を一時的に見直し、異常検知の範囲を再確認することで、影響を受けた顧客への対応を強化しました。エラーコードAUTH-08-00443は記録し、今後の再発防止策に活かす方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00654', 'INC-2020-00443', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T17:02:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T18:02:17+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00446', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-11-21T05:16:49+09:00', TIMESTAMP WITH TIME ZONE '2020-11-21T07:16:49+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2020年11月21日05時16分49秒、株式会社ストッククラウドの顧客である架空食品店A及び架空食品店Bにおいて、EDI経由の棚卸ファイル取込で件数不一致が発生しました。影響範囲はバッチ処理のみであり、オンラインには影響がありません。この問題はデータ移行バッチ実行中に発生し、エラーコードはINV-06-00446です。発見者は営業部の花子で、06時53分49秒に検知されました。技術的には、EDI連携ファイルの文字コード不一致が原因と考えられます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00446', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00446', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00446', 'INC-2020-00446', '調査の結果、データ移行バッチが実行されている最中にEDI経由の棚卸ファイル取込で件数不一致が報告されました。EDI連携ファイルの文字コードが原因である可能性が高いと見られています。この問題により、顧客店舗POSおよびEDIアダプタに影響が及んでいます。今後、文字コードの整合性を確認する必要があります。', '調査の結果、データ移行バッチが実行されている最中にEDI経由の棚卸ファイル取込で件数不一致が報告されました。EDI連携ファイルの文字コードが原因である可能性が高いと見られています。この問題により、顧客店舗POSおよびEDIアダプタに影響が及んでいます。今後、文字コードの整合性を確認する必要があります。', TIMESTAMP WITH TIME ZONE '2020-11-22T07:16:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00658', 'INC-2020-00446', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-11-21T07:31:49+09:00', TIMESTAMP WITH TIME ZONE '2020-11-21T08:31:49+09:00', '【初動対応】【棚卸・POS突合障害】EDI棚卸ファイル異常への初動対応', '初動対応として、エラーコードINV-06-00446に基づき、EDI経由の棚卸ファイル取込処理を一時停止しました。具体的には、文字コードの確認作業を始め、異常値がないかを調査しています。また、営業部の花子が顧客に対して問題発生の連絡を行い、状況を説明しました。影響を最小限に抑えるため、早急な対応を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00451', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-16T03:53:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T05:53:08+09:00', '【障害報告】【API連携・EDI障害】バルクAPI部分失敗', '2020年4月16日03時53分08秒、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSでバルクAPIが部分失敗し、ロールバックが未完了となる事象が発生しました。発生契機はデータ移行バッチ実行中であり、サービス全体の一部機能に影響を及ぼしました。具体的には、在庫登録APIが正常に機能せず、顧客に対するサービス提供に遅れが生じました。エラーコードはEDI-10-00451で、部分成功時の補償トランザクション欠如が推定原因とされています。この事象の影響は、店舗業務に支障をきたすものであり、早急な対応が求められました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00451', 'INC-2020-00451', '本事象に関する調査の結果、データ移行バッチ実行中に発生したバルクAPIの部分失敗が確認されました。ロールバックが未完了であることから、原因として部分成功時の補償トランザクション欠如が考えられます。このため、データ整合性が保たれず、顧客店舗POSの機能に影響を及ぼしました。調査を通じて、今後の再発防止策として、API連携の強化やトランザクション管理の見直しが必要であることが示唆されました。', '本事象に関する調査の結果、データ移行バッチ実行中に発生したバルクAPIの部分失敗が確認されました。ロールバックが未完了であることから、原因として部分成功時の補償トランザクション欠如が考えられます。このため、データ整合性が保たれず、顧客店舗POSの機能に影響を及ぼしました。調査を通じて、今後の再発防止策として、API連携の強化やトランザクション管理の見直しが必要であることが示唆されました。', TIMESTAMP WITH TIME ZONE '2020-04-17T05:53:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00665', 'INC-2020-00451', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T06:08:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T07:08:08+09:00', '初期対応', 'インシデント発生直後、営業部の花子が障害を報告し、技術チームが即座に対応を開始しました。影響範囲を特定し、迅速に原因調査を行うとともに、顧客に対して状況を説明しました。バルクAPIの状態をモニタリングし、課題解決に向けた対応を進めました。今後の対応策として、補償トランザクションの実装やテストケースの充実を図る必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00666', 'INC-2020-00451', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T07:38:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T08:38:08+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00452', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-16T21:20:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T23:20:21+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2020年4月16日21:20に、株式会社ストッククラウドのサービスMercuryにおいて、バルクAPIが部分失敗しロールバック未完了の事象が発生しました。これは顧客店舗POSでのデータ移行バッチ実行中に発生し、影響範囲はサービス全体の一部機能に及びました。発生したエラーコードはEDI-10-00452です。この件は営業部の花子が検知し、顧客名はなしです。推定原因としては部分成功時の補償トランザクションの欠如が挙げられます。今後の再発防止策を講じるための詳細な調査が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00452', 'INC-2020-00452', '本件の調査を進めた結果、データ移行バッチ実行中にバルクAPIが部分失敗したことが確認されました。ロールバックが未完了であったことが影響を及ぼし、サービス全体の一部機能に障害が発生しました。部分成功時の補償トランザクションが欠如していたことが考えられ、この点についての技術的な改善が求められます。今後は、適切なエラーハンドリングを実施し、類似の事象を未然に防ぐ措置を講じる必要があります。', '本件の調査を進めた結果、データ移行バッチ実行中にバルクAPIが部分失敗したことが確認されました。ロールバックが未完了であったことが影響を及ぼし、サービス全体の一部機能に障害が発生しました。部分成功時の補償トランザクションが欠如していたことが考えられ、この点についての技術的な改善が求められます。今後は、適切なエラーハンドリングを実施し、類似の事象を未然に防ぐ措置を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-17T23:20:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00667', 'INC-2020-00452', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T23:35:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T00:35:21+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗', '初期対応として、バルクAPIの状況を詳細に確認しました。部分失敗に伴い、ロールバック処理が完了していないことを確認し、その影響を最小限に抑えるための対策を検討しています。すぐに技術チームに連絡し、原因の特定と修正作業を進めています。また、影響を受けた顧客店舗POSについても、必要な情報を提供し、状況を報告しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00668', 'INC-2020-00452', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-17T01:05:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T02:05:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00453', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-22T13:35:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T14:35:57+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023-10-05T10:00:00+09:00に、株式会社ストッククラウドの顧客拠点において特定拠点のみAPI呼び出しが失敗する事象が発生しました。発生は新規店舗追加の初日であり、影響範囲は単一店舗に限定されています。エラーコードはNW-02-00453です。この問題は、顧客側FWおよび顧客拠点NW（ゾーンA）に関連しており、店舗LANのスイッチ故障が推定原因とされています。検知が行われたのは発生から53分後の2023-10-05T10:53:00+09:00です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00453', 'INC-2020-00453', '調査の結果、特定の拠点でのみAPI呼び出しが失敗していることが確認されました。この問題の原因として、店舗LANのスイッチ故障が疑われています。関連する機器の確認を行い、問題の切り分けを進める必要があります。顧客からの連絡も受けており、早急な対応が求められます。', '調査の結果、特定の拠点でのみAPI呼び出しが失敗していることが確認されました。この問題の原因として、店舗LANのスイッチ故障が疑われています。関連する機器の確認を行い、問題の切り分けを進める必要があります。顧客からの連絡も受けており、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-23T14:35:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00669', 'INC-2020-00453', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-22T14:50:57+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T15:50:57+09:00', '【対応ログ】【顧客ネットワーク障害】拠点限定API失敗', '2023-10-05T10:10:00+09:00に顧客からの報告を受け、担当の営業 花子が初動対応を開始しました。特定拠点でのAPI呼び出し失敗について、詳細な情報収集を行い、故障原因を店舗LANのスイッチに絞り込む調査を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00454', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-08T19:22:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T20:07:24+09:00', '【障害報告】【ストレージ・容量障害】DB自動拡張上限', '2020年4月8日19時22分に発生したインシデントにより、DB自動拡張が上限に到達し、書込が停止しました。本件は全テナントに波及し、影響範囲が広がりました。発生契機としては、大規模セール開始直前という状況が考えられます。エラーコードはSTR-04-00454であり、原因としてDB自動拡張の上限設定不足が疑われます。Mercury AWS StorageにおけるDBデータファイルに影響が出ており、早急な対応が求められます。ストレージ・容量の障害確認と対策を進める必要があります。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00454', 'INC-2020-00454', '本インシデントに関する調査を行った結果、DB自動拡張が上限に到達したことが原因で書込が停止していることが確認されました。大規模セール開始直前にこの問題が発生した為、影響は全テナントに及びました。DBの上限設定に関する見直しが必要であると考えます。今後は、DB拡張の上限設定を適切に行い、同様の障害を未然に防ぐための対策を講じることが重要です。', '本インシデントに関する調査を行った結果、DB自動拡張が上限に到達したことが原因で書込が停止していることが確認されました。大規模セール開始直前にこの問題が発生した為、影響は全テナントに及びました。DBの上限設定に関する見直しが必要であると考えます。今後は、DB拡張の上限設定を適切に行い、同様の障害を未然に防ぐための対策を講じることが重要です。', TIMESTAMP WITH TIME ZONE '2020-04-09T20:07:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00670', 'INC-2020-00454', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T20:22:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T21:22:24+09:00', '【初動対応】【ストレージ・容量障害】DB自動拡張上限', '2020年4月8日19時52分に本インシデントを検知しました。初動対応として、運用 一郎が直ちにDB自動拡張の設定を確認し、書込停止の原因を特定するための作業を開始しました。ストレージ・容量に関する問題に対して、迅速な解決を図るために関係者と連携し、影響の最小化を目指しました。エラーコードSTR-04-00454に基づき、必要な対策を実施する方針を立てました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00455', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-27T08:43:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T09:28:58+09:00', '【障害報告】【ストレージ・容量障害】WALアーカイブ滞留', '2020年4月27日08時43分58秒に発生したストレージ溢れに関する障害についてご報告いたします。本障害は、WALアーカイブが滞留し、ディスクを圧迫する事象でございます。発見者は運用部の運用 一郎であり、本障害は定例リリース直後に発生いたしました。本障害の影響範囲は全テナントに波及しており、特にMercury AWS Storage（DRサイト）およびバックアップ領域に影響を与えております。推定原因として、アーカイブ先のマウントポイント枯渇が考えられます。本事象によりシステムの運用に支障をきたし、多大な影響が懸念されます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00455', 'INC-2020-00455', '本障害に関する詳細な調査を行った結果、定例リリース直後にWALアーカイブが滞留し、ディスクを圧迫する状況が確認されました。調査において、アーカイブ先のマウントポイントが枯渇していることが主な原因と考えられます。このため、ストレージの容量が不足し、全テナントに影響を及ぼす事態となりました。今後の対応策を検討し、再発防止に努める所存です。', '本障害に関する詳細な調査を行った結果、定例リリース直後にWALアーカイブが滞留し、ディスクを圧迫する状況が確認されました。調査において、アーカイブ先のマウントポイントが枯渇していることが主な原因と考えられます。このため、ストレージの容量が不足し、全テナントに影響を及ぼす事態となりました。今後の対応策を検討し、再発防止に努める所存です。', TIMESTAMP WITH TIME ZONE '2020-04-28T09:28:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00671', 'INC-2020-00455', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T09:43:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T10:43:58+09:00', '【初期対応】【ストレージ・容量障害】WALアーカイブ滞留', '本障害について、初期対応を開始いたしました。運用部の運用 一郎が中心となり、WALアーカイブの状況を確認するとともに、アーカイブ先のマウントポイントの状況を調査中です。必要に応じて追加のストレージを確保し、WALアーカイブの滞留を解消する作業に取り組んでおります。全テナントへの影響を最小限に抑えるために、迅速な対応を心掛けてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00458', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-19T10:27:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T10:57:54+09:00', '【障害報告】【性能・負荷障害】オートスケール遅延', '2020年4月19日10時27分54秒、株式会社ストッククラウドのサービスMercuryにおいて、オートスケールが間に合わず応答劣化が発生しました。発生契機は大規模セール開始直前であり、全テナントに波及する影響が確認されました。エラーコードはPRF-04-00458です。運用部の運用 一郎によって11時12分54秒に検知され、検知までに45分の遅延がありました。技術詳細調査の結果、スケールアウト閾値の設定遅延が原因と推測され、今後の対策としてオートスケールの設定見直しが必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00458', 'INC-2020-00458', '本インシデントに関する調査を行った結果、大規模セール開始直前にオートスケールが間に合わず、応答劣化が発生したことが確認されました。具体的には、スケールアウトの閾値設定に遅延が生じたことが原因と考えられます。この遅延により、全テナントへの影響が発生し、迅速な対応が求められました。今後は、スケールアウトの閾値設定プロセスの見直しと、事前の検証を強化することが重要です。', '本インシデントに関する調査を行った結果、大規模セール開始直前にオートスケールが間に合わず、応答劣化が発生したことが確認されました。具体的には、スケールアウトの閾値設定に遅延が生じたことが原因と考えられます。この遅延により、全テナントへの影響が発生し、迅速な対応が求められました。今後は、スケールアウトの閾値設定プロセスの見直しと、事前の検証を強化することが重要です。', TIMESTAMP WITH TIME ZONE '2020-04-20T10:57:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00676', 'INC-2020-00458', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T11:12:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T12:12:54+09:00', '初期対応', 'インシデント発生後、運用部は直ちに対応チームを編成し、状況の把握に努めました。応答劣化の影響を受けたテナントへの通知を行い、ユーザーからの問い合わせに対応しました。スケールアウト閾値の設定遅延に関しては、運用部内での確認を行い、必要な修正を実施しました。さらに、システムのパフォーマンスを監視し、問題の再発防止策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00677', 'INC-2020-00458', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T12:42:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T13:42:54+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00459', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-02T13:34:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T14:04:28+09:00', '【障害報告】【CLU-09】スナップショット復元不整合', '2023年10月15日13時34分28秒に株式会社ストッククラウドのMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。具体的には、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れ、全テナントに波及する事態となりました。影響を受けたコンポーネントはMercury AWS AP（ゾーンA）であり、バックアップ管理が関与しています。この問題は、復元ポイントのトランザクションログ欠落が原因と考えられています。障害検知は2023年10月15日14時00分28秒に行われ、発見者は運用部の運用 一郎です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00459', 'INC-2020-00459', '本インシデントは、データ移行バッチ実行中に発生したスナップショット復元後の在庫整合崩れに起因します。調査の結果、復元ポイントに必要なトランザクションログが欠落していることが確認されました。このことが全テナントに影響を及ぼしたと考えられます。現在、原因の特定と対応策の策定を進めております。', '本インシデントは、データ移行バッチ実行中に発生したスナップショット復元後の在庫整合崩れに起因します。調査の結果、復元ポイントに必要なトランザクションログが欠落していることが確認されました。このことが全テナントに影響を及ぼしたと考えられます。現在、原因の特定と対応策の策定を進めております。', TIMESTAMP WITH TIME ZONE '2020-04-03T14:04:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00678', 'INC-2020-00459', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T14:19:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T15:19:28+09:00', '初動対応', 'インシデント発生直後、運用部では直ちに対応を開始しました。スナップショット復元の影響を受けたテナントの状況を把握するため、関連データの確認を行い、在庫整合の復旧作業を実施しました。また、復元ポイントに関連するトランザクションログの確認も行い、再発防止策の検討を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00679', 'INC-2020-00459', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T15:49:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T16:49:28+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00461', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-26T10:53:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T11:08:03+09:00', '【障害報告】【監視・可用性障害】トレースサンプリング過少', '2023年10月12日、株式会社ストッククラウドのMercuryサービスにおいて、運用者の作業ミスによるアクセス障害が発生しました。具体的には、運用コンソールにおいて分散トレースのサンプリング率が過少となり、原因特定が困難な状況に陥っています。サンプリング率の本番設定誤りが疑われ、運用部門に影響を及ぼしました。この問題は定例リリース直後に発生し、検知までに17分の時間を要しました。エラーコードはMON-05-00461です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00461', 'INC-2020-00461', '本インシデントに関する調査が行われました。運用者の作業ミスにより分散トレースのサンプリング率が過少となり、原因特定が困難な状況が確認されました。定例リリース直後に発生したことから、サンプリング率の本番設定誤りが主な原因と考えられます。運用部門のみが影響を受け、早急な対応が必要です。', '本インシデントに関する調査が行われました。運用者の作業ミスにより分散トレースのサンプリング率が過少となり、原因特定が困難な状況が確認されました。定例リリース直後に発生したことから、サンプリング率の本番設定誤りが主な原因と考えられます。運用部門のみが影響を受け、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-27T11:08:03+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00682', 'INC-2020-00461', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T11:23:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T12:23:03+09:00', '【初期対応】【監視・可用性障害】トレースサンプリング過少の初期対応', '初期対応として、運用部門がプラットフォームのサンプリング設定を確認し、速やかに修正作業に取り掛かることとしました。加えて、定例リリースの影響範囲を再評価し、運用コンソールの監視体制を強化する方針です。分散トレースの状況も継続的に監視し、再発防止策を講じる所存です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00683', 'INC-2020-00461', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T12:53:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T13:53:03+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00462', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-25T01:58:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T02:28:02+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2023年10月12日 14時30分に、株式会社ストッククラウドのMercuryにおいて、スナップショット復元後に在庫整合が崩れる事象が発生しました。本事象は、データ移行バッチ実行中に検知され、全テナントに波及する影響を及ぼしました。復元ポイントのトランザクションログが欠落していることが推定原因と考えられ、これにより在庫情報の整合性が失われました。エラーコードはSYNC-09-00462で、影響を受けたコンポーネントはMercury AWS AP（ゾーンB）およびバックアップ管理です。本事象は、全てのテナントに影響を与え、迅速な対応が必要です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00462', 'INC-2020-00462', '本事象について調査した結果、データ移行バッチ実行中にスナップショット復元を行った際、復元ポイントのトランザクションログが欠落していたことが確認されました。そのため、在庫整合が崩れ、全テナントに影響が及ぶ結果となりました。現在、原因の詳細をさらに掘り下げ、再発防止策を検討しております。', '本事象について調査した結果、データ移行バッチ実行中にスナップショット復元を行った際、復元ポイントのトランザクションログが欠落していたことが確認されました。そのため、在庫整合が崩れ、全テナントに影響が及ぶ結果となりました。現在、原因の詳細をさらに掘り下げ、再発防止策を検討しております。', TIMESTAMP WITH TIME ZONE '2020-04-26T02:28:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00684', 'INC-2020-00462', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T02:43:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T03:43:02+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合', '事象発生後、運用部の運用 一郎が迅速に対応を開始しました。エラーコードSYNC-09-00462に基づき、全テナントの在庫整合性を確認し、影響範囲を特定しました。直ちにデータ移行バッチの停止を行い、バックアップからの復元作業を実施しております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00463', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-30T13:04:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T14:04:06+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2023-10-05T10:00:00+09:00に、株式会社ストッククラウドの顧客からの報告により、顧客固定IP変更が許可リストに未反映であることが確認されました。具体的には、顧客オンボーディング当日に発生した障害で、IP許可リストの更新漏れが影響と考えられています。このため、顧客拠点NWおよび顧客側FWにてネットワーク接続が不安定な状態が続いています。影響範囲は単一店舗のみで、エラーコードはNW-07-00463です。検知まで49分を要しましたが、早急な対応が求められています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00463', 'INC-2020-00463', '調査の結果、2023-10-05に顧客オンボーディング当日に固定IP変更が許可リストに未反映となっていることが判明しました。IP許可リストの更新漏れが原因であると推定され、これにより顧客側のネットワーク接続に影響が出ています。現在、影響を受けている店舗のヒアリングも行い、具体的な状況を把握しています。', '調査の結果、2023-10-05に顧客オンボーディング当日に固定IP変更が許可リストに未反映となっていることが判明しました。IP許可リストの更新漏れが原因であると推定され、これにより顧客側のネットワーク接続に影響が出ています。現在、影響を受けている店舗のヒアリングも行い、具体的な状況を把握しています。', TIMESTAMP WITH TIME ZONE '2020-05-01T14:04:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00685', 'INC-2020-00463', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-30T14:19:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T15:19:06+09:00', '【対応ログ】【顧客ネットワーク障害】固定IP変更未連絡', '営業部の花子です。顧客からの報告に基づき、固定IP変更が許可リストに未反映である件について、早急に対応を開始しました。現在、技術部と連携し、IP許可リストの更新を進めています。影響範囲を確認し、顧客に対しても状況を説明します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00686', 'INC-2020-00463', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-30T15:49:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T16:49:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00466', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-24T01:08:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T01:53:19+09:00', '【障害報告】【ストレージ・容量障害】レプリカ遅延肥大', '2023-10-15T15:45:00+09:00に発生したストレージ溢れのインシデントについて報告します。瞬時にレプリカ遅延が発生し、差分ログが肥大化しました。この問題は、Mercury AWS Storageにおいて影響を及ぼし、読取専用レプリカ利用者に深刻な影響を与えました。発生契機は大規模セールの開始直前で、予期せぬトラフィック増加が考えられます。エラーコードはSTR-10-00466であり、検知までに27分を要しました。運用 一郎が最初に問題を検知しました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00466', 'INC-2020-00466', 'このインシデントの調査において、レプリカ遅延の原因として帯域制限設定の過小が疑われます。大規模セール開始直前に高負荷がかかり、帯域制限が適切に設定されていなかったことにより、差分ログが肥大化しました。今後の対策として、帯域制限の見直しとモニタリング体制の強化が必要です。また、発生時のトラフィック予測をより精密に行うことが求められます。', 'このインシデントの調査において、レプリカ遅延の原因として帯域制限設定の過小が疑われます。大規模セール開始直前に高負荷がかかり、帯域制限が適切に設定されていなかったことにより、差分ログが肥大化しました。今後の対策として、帯域制限の見直しとモニタリング体制の強化が必要です。また、発生時のトラフィック予測をより精密に行うことが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-25T01:53:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00689', 'INC-2020-00466', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T02:08:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T03:08:19+09:00', '【初期対応】【ストレージ・容量障害】レプリカ遅延肥大', '初期対応として、運用チームは直ちに帯域制限設定を確認し、必要に応じて調整を行いました。加えて、影響を受けたユーザーへの通知を実施し、状況の説明を行いました。差分ログの削除および最適化処理を行い、システムの安定化を図りました。今後の方針として、再発防止策を講じるため、システム全体の見直しを行う必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00467', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-13T10:18:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T12:18:23+09:00', '【障害報告】【棚卸・POS突合障害】店舗間転送未反映', '2020年4月13日10時18分23秒に、株式会社ストッククラウドのサービスMercuryにおいて、棚卸突合に関連する重大なインシデントが発生しました。このインシデントは、顧客店舗POSにおける店舗間在庫転送が送信側のみ減算される症状が見られました。影響範囲は同一顧客の全店舗に及び、エラーコードはINV-08-00467が記録されています。発生契機として新規店舗追加の初日が考えられ、これに伴い転送トランザクションの二相コミット失敗が推定されます。今後の調査と対応が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00467', 'INC-2020-00467', '本件につきまして、調査を行った結果、新規店舗追加の初日において店舗間在庫転送が送信側のみ減算される問題が確認されました。このトランザクションに関して、二相コミットの失敗が原因である可能性が高いと考えられます。引き続き詳細な分析を進め、再発防止策を検討してまいります。', '本件につきまして、調査を行った結果、新規店舗追加の初日において店舗間在庫転送が送信側のみ減算される問題が確認されました。このトランザクションに関して、二相コミットの失敗が原因である可能性が高いと考えられます。引き続き詳細な分析を進め、再発防止策を検討してまいります。', TIMESTAMP WITH TIME ZONE '2020-04-14T12:18:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00690', 'INC-2020-00467', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-13T12:33:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T13:33:23+09:00', '【対応ログ】【棚卸・POS突合障害】初期対応', 'インシデント発生を受けて、営業部の花子が最初の対応を行いました。状況を確認したところ、店舗間の在庫転送が正常に行われていないことが判明しました。詳細な技術調査を行うため、システムエンジニアと連携し、転送トランザクションのログを収集・分析することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00470', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-10T15:47:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T16:17:49+09:00', '【障害報告】【在庫マスター設定障害】セット商品分解失敗', '2023-10-01T14:30:00+09:00 に発生した事象について報告いたします。今回は、株式会社ストッククラウドのサービスMercuryにおいて、セット商品の在庫分解時に構成エラーが発生しました。発見者は運用部の運用 一郎であり、エラーコードはMST-07-00470です。この障害は定例リリース直後に発生しており、同一顧客の全店舗に影響を与えました。発生契機としては、BOM構成テーブルの親子関係不整合が疑われています。従いまして、在庫計算エンジン及びMercury AWS AP（DRサイト）において、在庫マスター設定に関連する問題が考えられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00470', 'INC-2020-00470', '本障害の調査を行った結果、定例リリース直後にセット商品の在庫分解時に構成エラーが発生したことが確認されました。原因として、BOM構成テーブルにおける親子関係の不整合が主な要因と考えられます。この不整合が在庫計算エンジンに影響を及ぼし、全店舗の在庫分解に支障をきたしました。さらなる調査が必要ですが、現時点ではこの構成の不整合が直接の原因であると結論付けられます。', '本障害の調査を行った結果、定例リリース直後にセット商品の在庫分解時に構成エラーが発生したことが確認されました。原因として、BOM構成テーブルにおける親子関係の不整合が主な要因と考えられます。この不整合が在庫計算エンジンに影響を及ぼし、全店舗の在庫分解に支障をきたしました。さらなる調査が必要ですが、現時点ではこの構成の不整合が直接の原因であると結論付けられます。', TIMESTAMP WITH TIME ZONE '2020-04-11T16:17:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00694', 'INC-2020-00470', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T16:32:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T17:32:49+09:00', '【初期対応】【在庫マスター設定障害】セット商品分解失敗', '本障害を受けて、初期対応として運用部が直ちにBOM構成テーブルの確認を行いました。親子関係の不整合が確認され、即時修正が必要と判断されました。エラーコードMST-07-00470に基づき、在庫計算エンジンの挙動もチェックし、影響を受けた店舗への連絡を迅速に進める必要があります。今後の対応策としまして、再発防止策を講じるとともに、関係者との情報共有を徹底してまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00472', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-22T00:11:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T00:41:53+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2023年10月15日、株式会社ストッククラウドのMercuryサービスにおいて、SKU登録APIがHTTP 500を返し在庫反映に失敗する事象が発生しました。発生時刻は00:11:53であり、この影響により単一店舗の登録機能のみが影響を受けました。今回の事象は定例リリース直後に発生し、推定される原因として単位換算係数の設定漏れが考えられます。このため、SKU情報の正確な登録が行えず、在庫情報の反映が滞りました。影響を受けたエラーコードはMST-01-00472で、状況を速やかに解決する必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00472', 'INC-2020-00472', 'ルールに従い、SKU登録APIがHTTP 500を返した原因について調査を行いました。定例リリース直後の影響ということもあり、単位換算係数の設定漏れが原因と推測されます。現在、当該設定の確認作業を進めており、適切な設定が行われているかを検証しています。今後、必要に応じて修正を行い、問題の再発防止に努めます。', 'ルールに従い、SKU登録APIがHTTP 500を返した原因について調査を行いました。定例リリース直後の影響ということもあり、単位換算係数の設定漏れが原因と推測されます。現在、当該設定の確認作業を進めており、適切な設定が行われているかを検証しています。今後、必要に応じて修正を行い、問題の再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2020-04-23T00:41:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00697', 'INC-2020-00472', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T00:56:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T01:56:53+09:00', '初期対応', '2023年10月15日、事象発生の報告を受けて、運用部の担当者である運用 一郎が対応にあたりました。事象の影響範囲と原因の特定を進め、直ちに定例リリースに関する設定内容の確認を開始しました。なお、影響を受けたユーザーへの通知も検討し、必要な情報を提供する準備を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00473', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-23T11:42:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T13:42:10+09:00', '【障害報告】【棚卸・POS突合障害】差異リスト空表示', '2023-09-15に株式会社ストッククラウドの顧客店舗POSにおいて、棚卸差異リストが空表示になる事象が発生しました。発生時刻は11:42で、データ移行バッチ実行中に問題が検知されました。検知は15:14に行われ、212分の時間差がありました。この障害は同一顧客の全店舗に影響を及ぼしました。推定原因として、店舗別在庫の集計粒度不一致が考えられます。技術詳細として、データ移行バッチ実行中に店舗端末で棚卸差異リストが空表示になる状況が確認されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00473', 'INC-2020-00473', '調査を行った結果、店舗端末にて棚卸差異リストが空表示となった原因は、店舗別在庫の集計粒度不一致であることが判明しました。この問題は、データ移行バッチが実行されている最中に発生しました。影響を受けたのは同一顧客の全店舗であり、全ての店舗で同様の症状が見られました。', '調査を行った結果、店舗端末にて棚卸差異リストが空表示となった原因は、店舗別在庫の集計粒度不一致であることが判明しました。この問題は、データ移行バッチが実行されている最中に発生しました。影響を受けたのは同一顧客の全店舗であり、全ての店舗で同様の症状が見られました。', TIMESTAMP WITH TIME ZONE '2020-04-24T13:42:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00698', 'INC-2020-00473', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T13:57:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T14:57:10+09:00', '【対応報告】【棚卸・POS突合障害】差異リスト空表示', '初期対応として、データ移行バッチの実行を一時停止し、店舗別在庫の集計粒度を見直しています。また、影響を受けた店舗に対し、状況を共有し、適切な対策を講じています。今後、より詳細な調査を進め、再発防止策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00474', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-26T11:20:38+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T13:20:38+09:00', '【障害報告】【データ同期・整合性障害】楽観ロック競合多発', '2023-10-16T10:15:00+09:00に発生した棚卸突合失敗について報告します。このインシデントは、顧客店舗POSにおいて、楽観ロック競合が多発し、更新失敗率が上昇しました。発見者は営業部の花子で、発生は大規模セール開始直前に発生しました。影響範囲は全テナントに波及し、顧客の在庫登録においても問題が発生しました。また、エラーコードSYNC-10-00474が記録されています。今回の問題は、バージョンカラム更新ロジックの不備が推定されており、技術詳細としては楽観ロック競合が多発したことが確認されています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00474', 'INC-2020-00474', '本インシデントの調査の結果、楽観ロック競合が多発した原因として、バージョンカラム更新ロジックの不備が確認されました。これは、大規模セール開始直前にシステムに負荷がかかることが影響したと考えられます。さらに、全テナントに影響が及んでいるため、より広範な影響が懸念される状況でした。', '本インシデントの調査の結果、楽観ロック競合が多発した原因として、バージョンカラム更新ロジックの不備が確認されました。これは、大規模セール開始直前にシステムに負荷がかかることが影響したと考えられます。さらに、全テナントに影響が及んでいるため、より広範な影響が懸念される状況でした。', TIMESTAMP WITH TIME ZONE '2020-04-27T13:20:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00699', 'INC-2020-00474', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T13:35:38+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T14:35:38+09:00', '初期対応', 'インシデント発生後、直ちに技術チームを招集し、原因の特定と影響の範囲確認を行いました。また、エラーコードSYNC-10-00474に関連するログを解析し、楽観ロック競合が発生していることを確認しました。初期対策として、バージョンカラム更新ロジックの見直しを行い、問題の解消に向けた対応を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00700', 'INC-2020-00474', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T15:05:38+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T16:05:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00477', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-13T12:40:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T14:40:58+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2023年10月11日、株式会社ストッククラウドのサービスMercuryにおいて、スナップショット復元後に在庫整合が崩れる事象が発生いたしました。本事象は顧客店舗POSにおいて確認されており、復元ポイントのトランザクションログ欠落が推定原因とされています。全テナントに影響が及ぶ可能性があるため、迅速な対応が求められます。発生契機はデータ移行バッチの実行中であり、影響コンポーネントは顧客店舗POS（Primary）及びバックアップ管理です。技術詳細としては、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れた事象が報告されております。エラーコードはSYNC-09-00477です。本件については、早急な対応を行い、必要な措置を講じる所存です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00477', 'INC-2020-00477', '本事象に関しまして、調査を進めた結果、スナップショット復元に際してのトランザクションログが欠落していたことが判明いたしました。このことが在庫整合の崩れを引き起こし、全テナントに影響が及ぶ結果となりました。なお、データ移行バッチの実行中に発生したため、当該バッチの影響を再評価し、必要な修正を検討する必要があると考えております。', '本事象に関しまして、調査を進めた結果、スナップショット復元に際してのトランザクションログが欠落していたことが判明いたしました。このことが在庫整合の崩れを引き起こし、全テナントに影響が及ぶ結果となりました。なお、データ移行バッチの実行中に発生したため、当該バッチの影響を再評価し、必要な修正を検討する必要があると考えております。', TIMESTAMP WITH TIME ZONE '2020-04-14T14:40:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00704', 'INC-2020-00477', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-13T14:55:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T15:55:58+09:00', '【対応履歴】【データ同期・整合性障害】スナップショット復元不整合', '2023年10月11日に発生したスナップショット復元不整合の事象に対して、初期対応を行いました。顧客店舗POSの復旧作業を開始し、状況の詳細確認を行っております。関係者には本事象の影響範囲について周知し、適切な対応を進めています。今後の経過については随時ご報告させていただきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00478', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-06T12:36:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T12:51:10+09:00', '【障害報告】【CLU-08】ブルートフォース誤検知', '発生日時: 2023-10-15T14:00:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00478', 'INC-2020-00478', '調査を進めた結果、ブルートフォース検知が正常IPを誤って遮断したことが確認されました。原因として、検知閾値が過敏に設定されていたことが浮き彫りになりました。このため、正常なユーザーのアクセスが妨げられたことが判明しました。今後は設定の見直しを行い、同様の事象が再発しないよう対策を講じていきます。', '調査を進めた結果、ブルートフォース検知が正常IPを誤って遮断したことが確認されました。原因として、検知閾値が過敏に設定されていたことが浮き彫りになりました。このため、正常なユーザーのアクセスが妨げられたことが判明しました。今後は設定の見直しを行い、同様の事象が再発しないよう対策を講じていきます。', TIMESTAMP WITH TIME ZONE '2020-04-07T12:51:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00705', 'INC-2020-00478', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T13:06:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T14:06:10+09:00', '【初期対応】【CLU-08】ブルートフォース誤検知に対する初期対応', '運用 一郎が発見後、迅速に対応を開始しました。最初に問題の特定を行い、正常IPの遮断を解除する手続きを実施しました。WAFの検知設定を確認し、過敏になっているポイントを見直すことを決定しました。顧客への影響を最小限に抑えるため、速やかに作業を進める必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00706', 'INC-2020-00478', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T14:36:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T15:36:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00481', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-09T08:19:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T09:19:47+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2020年4月9日08時19分47秒に発生した顧客側ネットワーク障害について報告いたします。本事象はSD-WANが劣化回線を選択し、遅延が増大するという症状が見られました。この影響により、同一顧客の全店舗でネットワークの利用に支障が生じました。発生契機は大規模セール開始直前であり、SD-WANポリシーの閾値設定誤りが原因として考えられます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00481', 'INC-2020-00481', '本障害の調査において、SD-WANの経路選択が原因であることが確認されました。特に、大規模セール開始直前に設定されたポリシーに問題があることが分かりました。これにより、劣化回線を選択した結果、顧客ネットワークに遅延が生じました。今後はポリシーの見直しと閾値設定の適正化が必要です。', '本障害の調査において、SD-WANの経路選択が原因であることが確認されました。特に、大規模セール開始直前に設定されたポリシーに問題があることが分かりました。これにより、劣化回線を選択した結果、顧客ネットワークに遅延が生じました。今後はポリシーの見直しと閾値設定の適正化が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-10T09:19:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00710', 'INC-2020-00481', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-09T09:34:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T10:34:47+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '初期対応として、SD-WANのポリシー設定を確認し、迅速に適切な閾値に修正する作業を行いました。また、影響を受けた全店舗に連絡を取り、障害内容を周知しました。障害の発生から約70分後に検知し、対応を開始した結果、問題の解決に向けた措置が進められています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00711', 'INC-2020-00481', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-09T11:04:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T12:04:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
