INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00494', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-19T15:29:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T16:14:04+09:00', '【障害報告】【CLU-10】トレースサンプリング過少', '2020年4月20日、株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れが発生しました。本障害は、分散トレースのサンプリング率過少により、原因特定が困難となったことが特徴です。影響範囲は運用部門のみに限定されており、エラーコードはMON-05-00494です。本障害は、定例リリース直後に発生しました。技術的には、分散トレースのサンプリング率が誤って設定されている可能性があります。このため、原因特定が難航し、迅速な対応が求められました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00494', 'INC-2020-00494', '本インシデントに関する調査を行った結果、分散トレースのサンプリング率が想定よりも過少であることが確認されました。この問題は、サンプリング率の本番設定に誤りがあったために引き起こされました。原因の特定が困難な状態が続いた背景には、通常の監視体制では察知できない事象であったことが挙げられます。今後、監視・可用性障害の対策を強化し、再発防止に努める所存です。', '本インシデントに関する調査を行った結果、分散トレースのサンプリング率が想定よりも過少であることが確認されました。この問題は、サンプリング率の本番設定に誤りがあったために引き起こされました。原因の特定が困難な状態が続いた背景には、通常の監視体制では察知できない事象であったことが挙げられます。今後、監視・可用性障害の対策を強化し、再発防止に努める所存です。', TIMESTAMP WITH TIME ZONE '2020-04-20T16:14:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00728', 'INC-2020-00494', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T16:29:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T17:29:04+09:00', '【初動対応】【CLU-10】トレースサンプリング過少の初動対応', 'インシデント発生後、運用部の運用 一郎が速やかに初動対応を開始しました。まずは、分散トレースのサンプリング率設定を確認し、誤りを修正する作業に着手しました。また、関連する監視ツールの設定も見直し、同様の問題が発生しないよう対策を講じました。運用部門は、影響を受けるコンポーネントを特定し、詳細な調査を進めることとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00495', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-06T03:11:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T03:41:18+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2023-10-01T10:15:00+09:00、株式会社ストッククラウドのMercuryにおいて在庫登録に失敗する事象が発生しました。症状としては、読取レプリカ遅延により在庫照会が古い値を返す事態が確認されています。この障害は大規模セール開始直前に発生し、特定リージョンのユーザーに影響を及ぼします。エラーコードはSYNC-02-00495です。運用部の運用 一郎が発見し、検知に至るまで40分かかりました。技術的には、レプリケーション遅延の監視閾値を超過していることが疑われます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00495', 'INC-2020-00495', '事象発生後、読取レプリカ遅延の監視データを確認しました。レプリカ遅延が発生し、在庫照会が古い値を取得する原因として、レプリケーションの監視閾値超過が特定されました。大規模セール開始直前のトラフィック増加が影響を及ぼした可能性があります。影響範囲は特定リージョンのユーザーのみに限られています。これにより、今後の同様の事象を防止するための対策が必要です。', '事象発生後、読取レプリカ遅延の監視データを確認しました。レプリカ遅延が発生し、在庫照会が古い値を取得する原因として、レプリケーションの監視閾値超過が特定されました。大規模セール開始直前のトラフィック増加が影響を及ぼした可能性があります。影響範囲は特定リージョンのユーザーのみに限られています。これにより、今後の同様の事象を防止するための対策が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-07T03:41:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00729', 'INC-2020-00495', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T03:56:18+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T04:56:18+09:00', '初期対応', '運用部の運用 一郎がこの障害を確認後、即座に円滑な在庫照会を復旧するための初期対応を開始しました。具体的には、レプリカ遅延の状況をリアルタイムで監視し、必要に応じてリソースの再配置を行いました。また、データ同期・整合性の問題を早急に解決するために、他の障害対応チームとの連携を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00497', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-09T06:59:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T08:59:15+09:00', '【障害報告】【CLU-07】JSONスキーマ不一致', '2023-10-05T09:30:00+09:00に発生した事象について報告いたします。今回のインシデントは、顧客店舗POSにおいて、連携JSONのスキーマ不一致が発生し、全件拒否となりました。この問題は、スキーマバージョンの同期漏れが原因と考えられ、定例リリース直後に発生したため、バッチ処理に対してのみ影響があり、オンラインには影響を及ぼしませんでした。エラーコードはEDI-04-00497です。問題の解決に向け、関係部署と協力し、再発防止策を検討する必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00497', 'INC-2020-00497', '本インシデントの調査を行った結果、連携JSONのスキーマ不一致が確認されました。定例リリース直後に発生したため、スキーマバージョンの同期漏れが推定原因とされます。影響範囲は顧客店舗POSに限定されており、他のシステムへの影響はありませんでした。今後、このような事態を未然に防ぐためには、リリース前のスキーマバージョンの適切なチェックが重要です。', '本インシデントの調査を行った結果、連携JSONのスキーマ不一致が確認されました。定例リリース直後に発生したため、スキーマバージョンの同期漏れが推定原因とされます。影響範囲は顧客店舗POSに限定されており、他のシステムへの影響はありませんでした。今後、このような事態を未然に防ぐためには、リリース前のスキーマバージョンの適切なチェックが重要です。', TIMESTAMP WITH TIME ZONE '2020-04-10T08:59:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00731', 'INC-2020-00497', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-09T09:14:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T10:14:15+09:00', '初期対応', 'この問題が確認された際に、初期対応として関連するシステムの状態を確認し、影響範囲を特定しました。顧客店舗POSにおけるバッチ処理が全件拒否されたため、速やかにエンジニアチームを招集し、スキーマの問題点を明らかにしました。定例リリースによる影響だと確認できたため、早急に修正作業を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00732', 'INC-2020-00497', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-09T10:44:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T11:44:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00500', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-14T20:39:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T21:24:23+09:00', '【障害報告】【ストレージ・容量障害】インデックス再構築膨張', '2023-10-01T10:00:00+09:00 に、株式会社ストッククラウドのサービスMercuryにおいて、インフラメンテナンス明けにインデックス再構築中に一時領域が枯渇した。これにより、特定リージョンのユーザーが影響を受けている。エラーコードはSTR-07-00500である。運用部の運用 一郎が事象を発見し、検知は2023-10-01T10:52:00+09:00に行われた。発生までの時間は52分である。これから、原因の特定と対策を進めていく。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00500', 'INC-2020-00500', '今回のインシデントはインフラメンテナンス明けに発生したため、再構築用一時領域のサイズ見積不足が推定原因である。影響範囲は特定リージョンのユーザーのみで、Mercury AWS StorageのDBデータファイルに関連している。技術的には、一時領域が枯渇したため、インデックス再構築プロセスが正常に完了しなかった。今後の対策としては、一時領域のサイズの見直しが必要だ。', '今回のインシデントはインフラメンテナンス明けに発生したため、再構築用一時領域のサイズ見積不足が推定原因である。影響範囲は特定リージョンのユーザーのみで、Mercury AWS StorageのDBデータファイルに関連している。技術的には、一時領域が枯渇したため、インデックス再構築プロセスが正常に完了しなかった。今後の対策としては、一時領域のサイズの見直しが必要だ。', TIMESTAMP WITH TIME ZONE '2020-04-15T21:24:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00736', 'INC-2020-00500', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T21:39:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T22:39:23+09:00', '【初期対応】【ストレージ・容量障害】インデックス再構築膨張', '初期対応として、運用 一郎はまず、インデックス再構築中の一時領域の使用状況を確認した。次に、再構築用一時領域のサイズを見直し、必要に応じて増加させる手続きを開始した。さらに、影響を受けたユーザーへは状況を説明し、情報提供を行った。明確な改善策を講じるために、さらなる調査を続ける必要がある。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00737', 'INC-2020-00500', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T23:09:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T00:09:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00503', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-24T09:12:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T11:12:09+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2020年4月24日09時12分09秒に、株式会社ストッククラウドのMercuryサービスにおいて、顧客店舗POSに関連する棚卸突合が失敗しました。このインシデントは、分散トランザクションがタイムアウトし片側のみがコミットされるという症状を伴いました。問題は、大規模セール開始直前に発生し、全テナントに波及する影響を及ぼしました。推定原因としては、2PCタイムアウト設定の過短が考えられます。2020年4月24日10時35分09秒にこの問題が検知され、83分の遅延が発生しました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00503', 'INC-2020-00503', '調査の結果、大規模セール開始直前において分散トランザクションがタイムアウトしたことが明らかになりました。この結果、片側のみコミットされる事象が発生し、全テナントに影響を及ぼしました。根本的な原因として、2PCタイムアウト設定の過短が指摘され、今後の改善施策としてタイムアウト設定の見直しが求められます。', '調査の結果、大規模セール開始直前において分散トランザクションがタイムアウトしたことが明らかになりました。この結果、片側のみコミットされる事象が発生し、全テナントに影響を及ぼしました。根本的な原因として、2PCタイムアウト設定の過短が指摘され、今後の改善施策としてタイムアウト設定の見直しが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-25T11:12:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00741', 'INC-2020-00503', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-24T11:27:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T12:27:09+09:00', '【初期対応】分散トランザクションの状況確認', 'インシデント発生後、すぐに影響を受けた顧客店舗POSの状況を確認しました。分散トランザクションがタイムアウトした原因を調査し、エラーコードSYNC-04-00503が記録されていることを確認しました。営業部の花子が中心となり、顧客への情報提供と、問題解決に向けた初期対応を迅速に行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00742', 'INC-2020-00503', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-24T12:57:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T13:57:09+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00506', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-22T09:10:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T10:10:46+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2023年10月15日09時30分頃、株式会社ストッククラウドのMercuryサービスにおいて、顧客固定IPが許可リストに未反映であるという事象が発生しました。発生時刻は2023年10月15日09時30分で、検知時刻は2023年10月15日10時35分でした。この問題は顧客拠点NWにて確認され、影響を受けたのは単一店舗のみです。発見者は営業部の花子であり、顧客のオンボーディング当日に該当する固定IPの変更が許可リストに反映されていないことが明らかとなりました。技術的には、IP許可リストの更新漏れが原因と推定されており、早急な対応が求められます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00506', 'INC-2020-00506', '調査の結果、顧客固定IP変更が許可リストに未反映であることが確認されました。これにより、顧客はネットワークにアクセスできない状況となっていました。発生の契機として、顧客のオンボーディング当日にIP許可リストの更新が漏れていたことが原因として挙げられます。今後は、このような事象が再発しないよう、チェックリストとプロセスの見直しを行います。', '調査の結果、顧客固定IP変更が許可リストに未反映であることが確認されました。これにより、顧客はネットワークにアクセスできない状況となっていました。発生の契機として、顧客のオンボーディング当日にIP許可リストの更新が漏れていたことが原因として挙げられます。今後は、このような事象が再発しないよう、チェックリストとプロセスの見直しを行います。', TIMESTAMP WITH TIME ZONE '2020-04-23T10:10:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00745', 'INC-2020-00506', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-22T10:25:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T11:25:46+09:00', '【初期対応】【顧客ネットワーク障害】固定IP変更未連絡', '初期対応として、営業の花子が顧客に連絡を取り、許可リストの変更を直ちに行う手続きを進めました。顧客に対しては、発生した問題の詳細を説明し、影響を受けた店舗が円滑にネットワークを利用できるよう、迅速な解決を約束しました。今後は、類似の問題を防ぐための対策も考慮し、改善策を講じる必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00746', 'INC-2020-00506', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-22T11:55:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T12:55:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00510', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-11T08:49:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T09:34:58+09:00', '【障害報告】【CLU-10】アラート疲労', '2020年4月11日08:49に、株式会社ストッククラウドのMercuryサービスにおいてストレージ溢れが発生しました。発生当初は特に顧客への影響はありませんでしたが、09:45に運用部の運用 一郎が発見した時点で、同一アラートが短時間に数百件発報される状態が続いていました。この状況は「アラート疲労」とも呼ばれるもので、運用部門にとって注意を要する状況でした。大規模セール開始直前という発生契機が影響しているものと考えられます。アラート抑制ルールが未設定であったことが、今回の事象の原因と推定されます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00510', 'INC-2020-00510', '発生したストレージ溢れに関して調査を行った結果、運用部門でのアラート疲労が確認されました。具体的には、同一アラートが短時間に数百件発報され、運用 一郎がその状況を把握したのは発生から56分後でした。この状況は、大規模セール開始直前に発生したため、アラートの抑制が行われていなかったことが原因として特定されました。アラートマネージャの設定が適切でなかったことが問題とされています。', '発生したストレージ溢れに関して調査を行った結果、運用部門でのアラート疲労が確認されました。具体的には、同一アラートが短時間に数百件発報され、運用 一郎がその状況を把握したのは発生から56分後でした。この状況は、大規模セール開始直前に発生したため、アラートの抑制が行われていなかったことが原因として特定されました。アラートマネージャの設定が適切でなかったことが問題とされています。', TIMESTAMP WITH TIME ZONE '2020-04-12T09:34:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00753', 'INC-2020-00510', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T09:49:58+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T10:49:58+09:00', '【初期対応】【CLU-10】アラート疲労', '運用部門では、発生したストレージ溢れに対して初期対応を行いました。具体的には、発報されているアラートの確認を行い、必要な対応を迅速に実施しました。また、アラート抑制ルールを設定し、同様の事象が再発しないように対策を講じました。運用 一郎が中心となり、影響を受けたコンポーネントの確認を行い、今後の運用に支障が出ないように注意を払っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00512', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-18T21:53:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T22:53:10+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023-10-01T10:00:00+09:00に、株式会社ストッククラウドの顧客拠点NWにおいて、特定拠点のみAPI呼び出しが失敗する事象が発生しました。発生契機は新規店舗追加の初日です。顧客名なしでの確認となりましたが、影響範囲は単一店舗のみであり、エラーコードはNW-02-00512です。営業部の花子が21:53:10に障害を発見しました。検知は22:28:10に行われ、検知までに35分を要しました。技術詳細として、店舗LANのスイッチ故障が推定原因とされています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00512', 'INC-2020-00512', '特定拠点でのAPI呼び出し失敗に関して、調査を行いました。新規店舗追加の初日に発生したため、店舗LANのスイッチの状態を確認しました。故障や不具合がないか、接続状況を詳細に確認した結果、スイッチの異常が確認されました。そのため、スイッチのリプレースを提案し、早急な対応を進める必要があります。', '特定拠点でのAPI呼び出し失敗に関して、調査を行いました。新規店舗追加の初日に発生したため、店舗LANのスイッチの状態を確認しました。故障や不具合がないか、接続状況を詳細に確認した結果、スイッチの異常が確認されました。そのため、スイッチのリプレースを提案し、早急な対応を進める必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-19T22:53:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00755', 'INC-2020-00512', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-18T23:08:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T00:08:10+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗への初期対応', '障害発生から30分以内に初期対応を実施しました。特定拠点のAPI失敗に関する情報を収集し、影響を受けている店舗との連絡を開始しました。営業部の花子が中心となり、問題解決のための情報を整理し、社内システムへのエラーログの記録を行いました。今後の調査と対応策を検討するための会議を設定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00756', 'INC-2020-00512', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T00:38:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T01:38:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00513', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-12-01T05:53:27+09:00', TIMESTAMP WITH TIME ZONE '2020-12-01T06:23:27+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2020年12月1日05時53分27秒に株式会社ストッククラウドのMercuryにおいて、年末年始の稼働切替時にPagerDuty連携が失敗しました。このため、運用部門に対するオンコール通知が未達となってしまいました。06時22分27秒にこの問題が検知されるまで約29分間、影響が続きました。影響を受けたコンポーネントはVenus Azure AP（Primary）とインシデント通知です。この問題の推定原因は、連携APIキーの権限不足と考えられます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00513', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00513', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00513', 'INC-2020-00513', 'PagerDuty連携失敗の調査を実施しました。運用部 一郎が連携APIキーの設定を確認したところ、権限に不足が見つかりました。年末年始の稼働切替時のことを踏まえ、APIの権限設定が適切でない理由を検証しました。また、同様の障害が再発しないよう、監視・可用性障害が発生しないための対策を講じる必要があります。', 'PagerDuty連携失敗の調査を実施しました。運用部 一郎が連携APIキーの設定を確認したところ、権限に不足が見つかりました。年末年始の稼働切替時のことを踏まえ、APIの権限設定が適切でない理由を検証しました。また、同様の障害が再発しないよう、監視・可用性障害が発生しないための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-12-02T06:23:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00757', 'INC-2020-00513', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-12-01T06:38:27+09:00', TIMESTAMP WITH TIME ZONE '2020-12-01T07:38:27+09:00', '【初期対応】【CLU-10】PagerDuty連携失敗への初期対応', '初期対応として、運用部 一郎が直ちにPagerDuty連携の設定を確認しました。連携APIキーの権限不足が原因であることが判明したため、急遽権限を変更し、再度連携を行いました。これにより、以後のオンコール通知が正常に機能するようになりました。今後は権限設定の見直しと定期的な確認を行うことが求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00758', 'INC-2020-00513', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-12-01T08:08:27+09:00', TIMESTAMP WITH TIME ZONE '2020-12-01T09:08:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00516', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-03T12:07:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T14:07:17+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '2020年4月3日12時07分に、株式会社ストッククラウドのサービスMercuryにおいて、棚卸突合失敗が発生しました。発生場所は顧客店舗POSであり、症状として実地棚卸数とシステム在庫が大幅に乖離していることが確認されました。これは月末棚卸の開始時に発生したものであり、推定原因として棚卸スナップショット時刻のずれが考えられます。影響範囲は同一顧客の全店舗に及び、エラーコードはINV-01-00516です。クライアントに与える影響を考慮し、早急に対応策を講じる必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00516', 'INC-2020-00516', '問題の発生を検知したのは2020年4月3日14時30分であり、発見者は営業部の花子でした。調査の結果、月末棚卸の開始時に実地棚卸数とシステム在庫が乖離した原因として、棚卸スナップショット時刻のずれが疑われます。影響を受けた顧客の全店舗において、この問題が発生しているため、徹底的な検証が必要です。', '問題の発生を検知したのは2020年4月3日14時30分であり、発見者は営業部の花子でした。調査の結果、月末棚卸の開始時に実地棚卸数とシステム在庫が乖離した原因として、棚卸スナップショット時刻のずれが疑われます。影響を受けた顧客の全店舗において、この問題が発生しているため、徹底的な検証が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-04T14:07:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00762', 'INC-2020-00516', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T14:22:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T15:22:17+09:00', '【初期対応】【棚卸・POS突合障害】棚卸実地差異への初期対応', '初期対応として、影響を受けた顧客全店舗に対し、実地棚卸数とシステム在庫の乖離についての詳細な情報収集を行うこととしました。さらに、棚卸スナップショット時刻の確認及び調整を実施し、問題の早期解決を目指します。今後の進捗については、定期的に報告を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00520', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-07T07:38:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T08:38:31+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2023-10-07 14:30:00に株式会社ストッククラウドの顧客拠点NWにおいて、ISP側BGP経路障害が発生し、複数拠点が同時不通となった。この事故は、インフラメンテナンス明けに発生し、同一顧客の全店舗に影響を及ぼしている。現時点で確認されている症状は、全ての拠点での接続障害であり、顧客からの報告も相次いでいる。推定される原因は、ISP側のBGP経路障害である。発見者は営業部の花子であり、障害の検知は約87分後の15:57:00に行われた。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00520', 'INC-2020-00520', '発生したBGP経路障害について調査を開始。ISP側からの情報によると、メンテナンス作業が行われた後にBGP経路に異常が発生したとのこと。特に、顧客ネットワークに接続している全店舗が影響を受けており、DNSリゾルバにも問題が生じていることが確認された。引き続き、ISPとの連携を強化し、早急な解決に向けた対応を進める。', '発生したBGP経路障害について調査を開始。ISP側からの情報によると、メンテナンス作業が行われた後にBGP経路に異常が発生したとのこと。特に、顧客ネットワークに接続している全店舗が影響を受けており、DNSリゾルバにも問題が生じていることが確認された。引き続き、ISPとの連携を強化し、早急な解決に向けた対応を進める。', TIMESTAMP WITH TIME ZONE '2020-04-08T08:38:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00768', 'INC-2020-00520', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T08:53:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T09:53:31+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', 'インシデント発生の報告を受けて、直ちにISPに対して障害内容を伝達し、状況確認を依頼した。また、影響を受けている顧客へは、事前に状況報告を行い、今後の対応方針についても説明を行った。障害解消までの間、定期的に状況を更新し、顧客への情報提供を徹底することで信頼回復を図る。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00769', 'INC-2020-00520', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T10:23:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T11:23:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00521', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-03T16:56:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T17:56:36+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '2020年4月3日16時56分36秒に発生した顧客側ネットワーク障害について報告します。発生時、株式会社ストッククラウドの顧客拠点NWにおいて、店舗DNSキャッシュが旧IPを返し続ける状況が確認されました。この問題により、単一店舗でのDNS関連のサービスに影響が出ています。推定原因として、DNS TTL設定とキャッシュ方針の不一致が挙げられます。特に、定例リリース直後にこの障害が発生したため、リリースに伴う設定変更が影響している可能性があります。エラーコードはNW-08-00521です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00521', 'INC-2020-00521', '本件の調査において、まず定例リリースの内容を確認しました。リリース後、DNS TTL設定が正しく適用されていない可能性があり、これが店舗DNSキャッシュが旧IPを返す原因と考えられます。さらに、DNSリゾルバのキャッシュ方針がリリース前後で変更されたかどうかも検討しています。今後は、DNSの設定を見直し、キャッシュクリアの手順を取る必要があります。', '本件の調査において、まず定例リリースの内容を確認しました。リリース後、DNS TTL設定が正しく適用されていない可能性があり、これが店舗DNSキャッシュが旧IPを返す原因と考えられます。さらに、DNSリゾルバのキャッシュ方針がリリース前後で変更されたかどうかも検討しています。今後は、DNSの設定を見直し、キャッシュクリアの手順を取る必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-04T17:56:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00770', 'INC-2020-00521', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T18:11:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T19:11:36+09:00', '【初動対応】【顧客ネットワーク障害】DNSキャッシュ汚染の初動対応', '初動対応として、影響を受けている店舗のネットワーク設定を確認し、DNSリゾルバのキャッシュをクリアしました。同時に、顧客に対して現在の状況を説明し、DNS設定の見直しを行う旨を通知しました。問題が解決するまで、顧客からのフィードバックを待ちながら状況を監視しています。今後は再発防止策として、DNS設定の定期的な確認を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00771', 'INC-2020-00521', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T19:41:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T20:41:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00522', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-10-04T03:30:42+09:00', TIMESTAMP WITH TIME ZONE '2020-10-04T04:00:42+09:00', '【障害報告】【認証・セッション障害】APIトークン早期失効', '2023年10月01日 12時45分に、株式会社ストッククラウドのサービスMercuryにおいて、APIトークンが発行直後に失効扱いとなる事象が発生しました。影響を受けた顧客は架空食品店Aで、インフラメンテナンス明けに発生したため、サービス全体の一部機能が利用できなくなりました。問題はVenus Azure AP（ゾーンB）およびAPIゲートウェイに関連していると考えられています。この事象は、サーバー時刻のNTPずれが原因である可能性が高いと見ています。エラーコードはAUTH-04-00522で、検知は発生から16分後の2023年10月01日 13時01分に行われました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00522', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00522', 'INC-2020-00522', '調査の結果、APIトークンが発行直後に失効扱いとなった原因は、サーバー時刻のNTPずれであることが確認されました。この問題はインフラメンテナンス後に発生し、実際の時刻とのズレが原因で、正しくトークンが認証されない状態となりました。今後はNTP設定の見直しを行い、定期的な確認を実施することで再発防止を図ります。', '調査の結果、APIトークンが発行直後に失効扱いとなった原因は、サーバー時刻のNTPずれであることが確認されました。この問題はインフラメンテナンス後に発生し、実際の時刻とのズレが原因で、正しくトークンが認証されない状態となりました。今後はNTP設定の見直しを行い、定期的な確認を実施することで再発防止を図ります。', TIMESTAMP WITH TIME ZONE '2020-10-05T04:00:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00772', 'INC-2020-00522', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-10-04T04:15:42+09:00', TIMESTAMP WITH TIME ZONE '2020-10-04T05:15:42+09:00', '【初動対応】【認証・セッション障害】APIトークン早期失効', '初動対応として、インフラメンテナンス後に発行されたAPIトークンの状況を確認し、影響を受けた顧客への連絡を行いました。また、サーバー時刻のNTP設定を確認し、修正を行った後、トークンの再発行を行いました。影響を受けた顧客には謝罪を行い、今後の対策についても説明しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00524', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-21T12:58:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T13:58:45+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '・発生日時: 2020-04-21T12:58:45+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00524', 'INC-2020-00524', '本障害について調査を実施しました。代理サーバー経由で502エラーが発生しており、顧客ネットワークの利用状況やプロキシ設定に関する確認を行いました。特に、タイムアウト設定に関して過短であることが原因である可能性が高いと考えられます。今後、設定の見直しを進め、再発防止に向けた対応を行います。', '本障害について調査を実施しました。代理サーバー経由で502エラーが発生しており、顧客ネットワークの利用状況やプロキシ設定に関する確認を行いました。特に、タイムアウト設定に関して過短であることが原因である可能性が高いと考えられます。今後、設定の見直しを進め、再発防止に向けた対応を行います。', TIMESTAMP WITH TIME ZONE '2020-04-22T13:58:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00775', 'INC-2020-00524', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T14:13:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T15:13:45+09:00', '【初動対応】【顧客ネットワーク障害】代理サーバー502', '初動対応として、発生した502エラーの詳細を確認し、影響を受けた顧客に対して連絡を行いました。また、プロキシの設定を見直し、タイムアウトの設定を確認するための作業を開始しました。顧客への影響を最小限に抑えるため、速やかな対応を心がけました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00526', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-19T06:54:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T07:54:24+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2020年5月5日 14:30、株式会社ストッククラウドの顧客拠点NWにてISP側BGP経路障害が発生しました。これにより、複数拠点が同時不通となっています。この障害は、インフラメンテナンス明けに発生したもので、影響範囲は同一顧客の全店舗に及んでいます。具体的には、顧客拠点NW（ゾーンB）およびDNSリゾルバが影響を受けています。発見者は営業部の花子で、障害は2020年5月5日 14:30に発生し、2020年5月5日 15:21に検知されました。エラーコードはNW-06-00526です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00526', 'INC-2020-00526', '障害の検出後、営業部の花子がISPに連絡を取り、状況を確認しました。ISP側はBGP経路障害を認め、対応中であるとの報告がありました。今後は、具体的な復旧見込みや進捗状況をISPからの通信を通じて確認し、顧客への情報提供を行う必要があります。影響範囲が広いため、顧客には障害の概要と対応状況を迅速に共有することが求められます。', '障害の検出後、営業部の花子がISPに連絡を取り、状況を確認しました。ISP側はBGP経路障害を認め、対応中であるとの報告がありました。今後は、具体的な復旧見込みや進捗状況をISPからの通信を通じて確認し、顧客への情報提供を行う必要があります。影響範囲が広いため、顧客には障害の概要と対応状況を迅速に共有することが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-20T07:54:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00777', 'INC-2020-00526', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T08:09:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T09:09:24+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '初期対応として、営業部の花子が障害通知を行い、顧客に対して状況を説明しました。また、ISPと連携し、BGP経路障害の原因を特定するための調査を依頼しました。顧客からの問い合わせに対しては、障害の影響範囲や復旧の目処について情報を提供しました。今後の対応についても、進捗があれば随時顧客に報告する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00778', 'INC-2020-00526', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T09:39:24+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T10:39:24+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00529', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-06T06:54:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T07:39:46+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2023-10-01T10:30:00+09:00に株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れのインシデントが発生した。具体的には、ヘルスチェック過多によりAPサーバーの負荷が増大していることが確認された。今回の事象は、インフラメンテナンス明けにおけるLBヘルスチェック間隔の過短設定が推定原因であり、その影響は全テナントに波及している。エラーコードはMON-06-00529で、運用部の運用 一郎が発見した。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00529', 'INC-2020-00529', '詳細な調査の結果、インフラメンテナンス明けにおけるヘルスチェックが過多であり、そのためAPサーバーに過負荷がかかっていることが判明した。特に、LBのヘルスチェック間隔が短すぎることが主な要因として疑われている。このままでは全テナントに影響を及ぼし続ける可能性があるため、早急な対策が必要である。', '詳細な調査の結果、インフラメンテナンス明けにおけるヘルスチェックが過多であり、そのためAPサーバーに過負荷がかかっていることが判明した。特に、LBのヘルスチェック間隔が短すぎることが主な要因として疑われている。このままでは全テナントに影響を及ぼし続ける可能性があるため、早急な対策が必要である。', TIMESTAMP WITH TIME ZONE '2020-04-07T07:39:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00782', 'INC-2020-00529', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T07:54:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T08:54:46+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎が報告した警告に基づき、ヘルスチェックの設定を見直し、LBのヘルスチェック間隔を適切な値に変更する。サーバーの負荷状況を監視し、改善が見られるかを確認する。また、全テナントへの影響を考慮し、迅速な対応を進める。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00783', 'INC-2020-00529', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T09:24:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T10:24:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00531', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-07T10:48:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T11:18:50+09:00', '【障害報告】【CLU-09】マスター在庫二重反映', '株式会社ストッククラウドのMercuryにおいて、2020年4月7日10時48分50秒にマスター設定ミスによる在庫登録失敗が発生しました。症状として、マスター更新と在庫が二重反映される事象が確認されました。発生契機は定例リリース直後であり、影響範囲は同一顧客の全店舗に及びました。推定原因はイベント順序の逆転配信であり、エラーコードはSYNC-01-00531となります。影響コンポーネントはMercury AWS AP（Primary）およびイベントバスです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00531', 'INC-2020-00531', '本事象についての調査を行った結果、定例リリース直後にマスター更新と在庫が二重反映されることが確認されました。この現象は、イベント順序の逆転配信によって引き起こされていると考えられます。データ同期・整合性に関わる問題であり、迅速な対応が求められます。全店舗への影響を考慮し、今後の再発防止策を講じる必要があります。', '本事象についての調査を行った結果、定例リリース直後にマスター更新と在庫が二重反映されることが確認されました。この現象は、イベント順序の逆転配信によって引き起こされていると考えられます。データ同期・整合性に関わる問題であり、迅速な対応が求められます。全店舗への影響を考慮し、今後の再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-08T11:18:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00786', 'INC-2020-00531', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T11:33:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T12:33:50+09:00', '【初期対応】マスター在庫二重反映', '発生直後、運用部の運用 一郎が事象を確認し、速やかに対応に着手しました。最初の対応として、マスター更新の状況を確認し、二重反映の原因となるべきイベント順序の確認を行いました。影響を受けた店舗に対しては、在庫状況を手動で修正する措置を講じ、顧客への影響を最小限に抑えるよう努力しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00532', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-23T06:51:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T07:21:47+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2023-10-10T10:12:47+09:00に発生したマスター設定ミスによる在庫登録失敗の事象について報告します。Webhook再送が嵐状になり先方で拒否されました。発生契機は定例リリース直後で、影響範囲は単一店舗のみです。エラーコードはEDI-02-00532で、影響コンポーネントはMercury AWS AP（ゾーンB）およびWebhookディスパッチャです。技術詳細としては、定例リリース直後にWebhook再送が嵐状になり、先方で拒否された状況が確認されています。推定原因として再送間隔の指数バックオフ未設定が疑われます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00532', 'INC-2020-00532', '本事象の調査を行いました。発生は2023-10-10T10:12:47+09:00であり、Webhook再送が嵐状になる原因として再送間隔の指数バックオフが未設定であることが判明しました。定例リリース後の状況を確認したところ、再送の設定に不具合があり、結果として先方に拒否される事態となりました。これにより、API連携・EDIに支障をきたしています。', '本事象の調査を行いました。発生は2023-10-10T10:12:47+09:00であり、Webhook再送が嵐状になる原因として再送間隔の指数バックオフが未設定であることが判明しました。定例リリース後の状況を確認したところ、再送の設定に不具合があり、結果として先方に拒否される事態となりました。これにより、API連携・EDIに支障をきたしています。', TIMESTAMP WITH TIME ZONE '2020-04-24T07:21:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00787', 'INC-2020-00532', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T07:36:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T08:36:47+09:00', '【初動対応】【CLU-07】Webhook再送嵐', '2023-10-10T10:15:00+09:00に初動対応を開始しました。再送の設定を確認し、指数バックオフの未設定を特定しました。直ちに設定変更を行い、再送の制御を行うことで、先方への影響を最小限に抑える措置を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00534', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-23T12:31:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T13:01:19+09:00', '【障害報告】【CLU-09】アウトボックス滞留', '2023年10月15日12時00分、株式会社ストッククラウドのサービスMercuryにおいて、定例リリース直後にアウトボックステーブル滞留が発生し、通知遅延が確認されました。発見者は運用 一郎(運用部)です。この障害は、アウトボックスポーラーの停止が推定される原因であり、サービス全体の一部機能に影響を及ぼしました。エラーコードはSYNC-05-00534です。影響を受けたコンポーネントはMercury AWS AP（ゾーンB）及びイベントバスです。これにより、業務に支障が出ている状況です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00534', 'INC-2020-00534', '調査の結果、定例リリース直後に発生したアウトボックステーブル滞留は、アウトボックスポーラーが停止していたことが直接的な原因であることが確認されました。今後の対応として、アウトボックスポーラーの稼働状況を監視し、再発防止策を講じる必要があります。', '調査の結果、定例リリース直後に発生したアウトボックステーブル滞留は、アウトボックスポーラーが停止していたことが直接的な原因であることが確認されました。今後の対応として、アウトボックスポーラーの稼働状況を監視し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T13:01:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00789', 'INC-2020-00534', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T13:16:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T14:16:19+09:00', '【初期対応】【CLU-09】アウトボックス滞留', '初期対応として、運用チームはアウトボックスポーラーの再起動を実施し、アウトボックステーブルの滞留状態を解消しました。また、通知遅延の影響を受けた顧客への情報提供を行い、誠意ある対応を心掛けました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00790', 'INC-2020-00534', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T14:46:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T15:46:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00535', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-22T20:28:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T22:28:23+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023-10-05T15:00:00+09:00 に、株式会社ストッククラウドのサービスMercuryにおいて、棚卸突合失敗の事象が発生いたしました。発生時刻は2023-10-05T15:00:00+09:00で、検知時刻は2023-10-05T17:17:00+09:00であり、検知までの時間は137分でした。症状として、マスター更新と在庫が二重反映される事象が報告されております。影響範囲は同一顧客の全店舗に及び、エラーコードはSYNC-01-00535です。発生契機は定例リリース直後であり、影響コンポーネントは顧客店舗POS（ゾーンB）とイベントバスです。技術詳細として、定例リリース直後にマスター更新と在庫が二重反映されることが確認されており、原因としてイベント順序の逆転配信が疑われます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00535', 'INC-2020-00535', '本事象に関する調査を行った結果、マスター更新と在庫が二重反映される問題が確認されました。詳細な分析を実施したところ、イベント順序の逆転配信が主な原因と考えられます。この問題は定例リリース直後に発生しており、全店舗で同様の症状が見られました。今後、再発防止策として、イベントの配信順序を見直す必要があります。', '本事象に関する調査を行った結果、マスター更新と在庫が二重反映される問題が確認されました。詳細な分析を実施したところ、イベント順序の逆転配信が主な原因と考えられます。この問題は定例リリース直後に発生しており、全店舗で同様の症状が見られました。今後、再発防止策として、イベントの配信順序を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-23T22:28:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00791', 'INC-2020-00535', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-22T22:43:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T23:43:23+09:00', '初期対応ログ', '2023-10-05T15:05:00+09:00 に初期調査を開始し、システムログを確認しました。今後の対応として、関連するシステムの監視を強化し、問題の根本原因を特定するための追加調査を実施する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00792', 'INC-2020-00535', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T00:13:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T01:13:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00538', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-23T01:08:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T03:08:36+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2023-10-05T10:15:00+09:00に、株式会社ストッククラウドの顧客店舗POSにおいて棚卸確定ボタンがグレーアウトしたまま操作できないという事象が発生しました。営業部の花子が発見し、影響範囲は単一店舗のみです。この問題は月末棚卸の開始時に発生したため、未処理の差異調整レコードが残留している可能性があります。これにより、棚卸確定が行えず、業務に支障をきたしています。エラーコードはINV-03-00538で、現在調査を進めています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00538', 'INC-2020-00538', '調査を開始したところ、2023-10-05T10:15:00+09:00に発生した棚卸確定不可の原因として、未処理の差異調整レコードが残留していることが疑われます。これにより、顧客店舗POSの棚卸確定ボタンがグレーアウトし、操作できない状況が続いています。技術チームは現在、差異調整レコードの確認と対応を行っています。', '調査を開始したところ、2023-10-05T10:15:00+09:00に発生した棚卸確定不可の原因として、未処理の差異調整レコードが残留していることが疑われます。これにより、顧客店舗POSの棚卸確定ボタンがグレーアウトし、操作できない状況が続いています。技術チームは現在、差異調整レコードの確認と対応を行っています。', TIMESTAMP WITH TIME ZONE '2020-04-24T03:08:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00795', 'INC-2020-00538', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T03:23:36+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T04:23:36+09:00', '【初期対応】【棚卸・POS突合障害】棚卸確定不可', '営業部の花子より2023-10-05T10:15:00+09:00に棚卸確定ボタンが操作できないとの報告がありました。これを受けて、迅速に調査を行い、未処理の差異調整レコードが原因として特定されました。まずは影響を受けた店舗での確認作業を行い、必要な対応を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00541', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-25T06:08:38+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T08:08:38+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2020年4月25日06時08分38秒に、株式会社ストッククラウドが提供するMercuryにおいて、顧客店舗POSで分散トランザクションがタイムアウトし、片側のみコミットされる事象が発生しました。この事象は大規模セール開始直前に発生し、全テナントに波及する可能性があることが確認されています。原因として、2PCタイムアウト設定の過短が考えられ、影響を受けたコンポーネントは顧客店舗POS（ゾーンA）および在庫計算エンジンです。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00541', 'INC-2020-00541', '本事象の調査を行った結果、分散トランザクションがタイムアウトした原因は2PCタイムアウト設定が過短であったことに起因することが確認されました。特に、大規模セールが開始される直前にこの障害が発生したため、システム全体に影響が及ぶリスクが高まっていました。今後は、2PCタイムアウト設定を見直し、必要に応じて適正化することが求められます。', '本事象の調査を行った結果、分散トランザクションがタイムアウトした原因は2PCタイムアウト設定が過短であったことに起因することが確認されました。特に、大規模セールが開始される直前にこの障害が発生したため、システム全体に影響が及ぶリスクが高まっていました。今後は、2PCタイムアウト設定を見直し、必要に応じて適正化することが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-26T08:08:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00799', 'INC-2020-00541', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-25T08:23:38+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T09:23:38+09:00', '初期対応', '発生した事象を受け、営業部の花子が迅速に対応にあたり、分散トランザクションの設定を確認しました。設定の見直しを行い、タイムアウト値の適正化を進めました。影響範囲の確認も行い、全テナントへの波及を防ぐための対策を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00546', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-08-05T17:35:38+09:00', TIMESTAMP WITH TIME ZONE '2020-08-05T18:20:38+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2023-10-10T12:00:00+09:00に、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れの問題が発生しました。具体的には、Mercury AWS StorageにおいてPagerDuty連携が失敗し、運用部門のオンコール通知が未達となりました。発見者は運用部の運用 一郎で、検知は2023-10-10T12:39:00+09:00に行われました。発生契機は年末年始の稼働切替時であり、推定原因は連携APIキーの権限不足と考えられます。影響範囲は運用部門のみです。エラーコードはMON-07-00546です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00546', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00546', 'INC-2020-00546', '調査を実施した結果、年末年始の稼働切替時において、PagerDuty連携が失敗したことが確認されました。連携APIキーの権限不足が原因で、オンコール通知が運用部門に届いていない状態でした。これにより、重要なインシデントに対応するべき運用担当者が通知を受けられず、迅速な対応ができない状況に陥りました。この問題の解決には、APIキーの権限を見直し、適切な設定を行う必要があります。', '調査を実施した結果、年末年始の稼働切替時において、PagerDuty連携が失敗したことが確認されました。連携APIキーの権限不足が原因で、オンコール通知が運用部門に届いていない状態でした。これにより、重要なインシデントに対応するべき運用担当者が通知を受けられず、迅速な対応ができない状況に陥りました。この問題の解決には、APIキーの権限を見直し、適切な設定を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-08-06T18:20:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00807', 'INC-2020-00546', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-08-05T18:35:38+09:00', TIMESTAMP WITH TIME ZONE '2020-08-05T19:35:38+09:00', '【初期対応】【CLU-10】PagerDuty連携失敗', 'インシデント発生後、運用部の運用 一郎が速やかに状況を確認しました。まず、PagerDutyとの連携設定を確認し、権限に関する問題を特定しました。その後、迅速にAPIキーの権限を修正し、再度連携を試みました。結果として、オンコール通知が運用部門のメンバーに届くようになり、正常な監視・可用性の確保が図られました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00808', 'INC-2020-00546', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-08-05T20:05:38+09:00', TIMESTAMP WITH TIME ZONE '2020-08-05T21:05:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00548', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-19T02:19:26+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T04:19:26+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023年10月10日、株式会社ストッククラウドにおいて、サービスMercuryに関連する棚卸突合失敗が発生しました。症状として、マスター更新と在庫が二重反映される事象が確認されました。本事象は顧客店舗POSにて発生し、影響範囲は同一顧客の全店舗に及んでいます。発生契機は定例リリース直後であり、エラーコードはSYNC-01-00548となります。技術的な詳細としては、定例リリース直後にマスター更新と在庫が二重反映されることが確認され、原因としてイベント順序の逆転配信が疑われております。この障害により、顧客への影響が懸念されており、早急な対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00548', 'INC-2020-00548', '本事象に関する調査を行った結果、マスター更新と在庫が二重反映される原因は、イベント順序の逆転配信にあると考えられます。この問題は、定期的なシステムのメンテナンスおよびリリースに関連して発生する可能性があります。現在、影響を受けた全店舗において在庫データの確認および修正作業を進めており、再発防止策の検討も行っております。', '本事象に関する調査を行った結果、マスター更新と在庫が二重反映される原因は、イベント順序の逆転配信にあると考えられます。この問題は、定期的なシステムのメンテナンスおよびリリースに関連して発生する可能性があります。現在、影響を受けた全店舗において在庫データの確認および修正作業を進めており、再発防止策の検討も行っております。', TIMESTAMP WITH TIME ZONE '2020-04-20T04:19:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00811', 'INC-2020-00548', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T04:34:26+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T05:34:26+09:00', '初期対応', '障害発生後、早急に技術チームを招集し、影響範囲の特定および初期調査を実施いたしました。全店舗の在庫データを確認し、二重反映の事例を特定しました。また、イベントの配信順序についても再確認を行い、改善策を講じる必要があることを認識いたしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00812', 'INC-2020-00548', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T06:04:26+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T07:04:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
