INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00814', 'INC-2020-00549', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-22T18:36:55+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T19:36:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00551', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-21T04:32:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T06:32:22+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2023-10-10T10:00:00+09:00に、株式会社ストッククラウドの顧客店舗POSにおいてWebhook再送が嵐状になり、先方で拒否される事象が発生しました。発見者は営業部の花子で、定例リリース直後のため影響範囲は単一店舗に限定されます。エラーコードはEDI-02-00551です。再送間隔の指数バックオフ未設定が推定原因と考えられます。事象発生から検知まで156分のタイムラグがありました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00551', 'INC-2020-00551', '調査の結果、定例リリース直後にWebhook再送が嵐状となり、先方で拒否された事象が確認されました。再送間隔の指数バックオフが未設定であったことが推定原因であると考えられます。影響を受けたのは単一店舗のみで、事象が発生した具体的な時間は2023-10-10T10:00:00+09:00でした。エラーコードはEDI-02-00551です。', '調査の結果、定例リリース直後にWebhook再送が嵐状となり、先方で拒否された事象が確認されました。再送間隔の指数バックオフが未設定であったことが推定原因であると考えられます。影響を受けたのは単一店舗のみで、事象が発生した具体的な時間は2023-10-10T10:00:00+09:00でした。エラーコードはEDI-02-00551です。', TIMESTAMP WITH TIME ZONE '2020-04-22T06:32:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00817', 'INC-2020-00551', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T06:47:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T07:47:22+09:00', '【初動対応】【CLU-07】Webhook再送嵐', '初動対応として、Webhook再送に関する設定の見直しを行いました。特に再送間隔の指数バックオフを適切に設定することを優先しました。また、顧客店舗POSに影響を与えた事象について、報告書を作成し関係者に配布しました。今後は同様の事象が発生しないように、定例リリースの前に事前に検証を行う体制を確立することが求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00818', 'INC-2020-00551', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T08:17:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T09:17:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00553', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-10T19:29:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T21:29:21+09:00', '【障害報告】【CLU-07】APIキー期限切れ', '発生日時: 2020-04-10T19:29:21+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00553', 'INC-2020-00553', '本案件は外部WMS APIキーの期限が切れたことによるAPI連携の停止が原因と考えられます。APIキーのローテーション手順が実施されなかったことが主な要因です。現状、同一顧客のすべての店舗に影響が及んでおり、早急な対応が求められています。今後の対策として、定期的なAPIキーの確認およびローテーション手順の遵守が必要です。', '本案件は外部WMS APIキーの期限が切れたことによるAPI連携の停止が原因と考えられます。APIキーのローテーション手順が実施されなかったことが主な要因です。現状、同一顧客のすべての店舗に影響が及んでおり、早急な対応が求められています。今後の対策として、定期的なAPIキーの確認およびローテーション手順の遵守が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-11T21:29:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00821', 'INC-2020-00553', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-10T21:44:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T22:44:21+09:00', '初期対応', 'このインシデントに関しては、即座にAPIキーのローテーションを実施しました。また、影響を受けた店舗には連絡を行い、状況を説明しました。今後は、APIキーの管理を徹底し、再発防止策を講じる必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00554', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-08T04:26:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T04:41:07+09:00', '【障害報告】【運用操作・権限障害】ロールバック途中停止', '2023-10-10T10:15:00+09:00に、株式会社ストッククラウドのMercuryにおいて、運用コンソールでのロールバック操作が途中で停止し、不整合が発生しました。この障害は定例リリース直後に起こり、サービス全体の一部機能に影響を及ぼしました。発生契機は、リリース手順のスキップが疑われており、運用部の運用 一郎が発見しました。この事象は、リリース手順を再確認し厳守する必要性を示しています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00554', 'INC-2020-00554', '調査の結果、2023-10-10T10:15:00+09:00に発生したロールバック操作が途中で停止した原因は、リリース手順のスキップに起因することが確認されました。デプロイパイプラインにおける手順不遵守がこの不整合を引き起こしました。このような事象を防ぐため、運用チームには手順遵守の徹底が求められます。', '調査の結果、2023-10-10T10:15:00+09:00に発生したロールバック操作が途中で停止した原因は、リリース手順のスキップに起因することが確認されました。デプロイパイプラインにおける手順不遵守がこの不整合を引き起こしました。このような事象を防ぐため、運用チームには手順遵守の徹底が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-09T04:41:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00822', 'INC-2020-00554', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T04:56:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T05:56:07+09:00', '【初期対応】運用操作・権限障害の迅速対応', 'インシデント発生後、即座に運用部門が対応に当たり、影響を受けたサービス機能の復旧作業を開始しました。運用 一郎を中心に関連チームが連携し、速やかにロールバック操作の再実施を行い、不整合の回復を図りました。さらに、今後の再発防止のため、運用手順の見直しを実施しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00558', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-08T21:15:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T21:45:03+09:00', '【障害報告】【API連携・EDI障害】バルクAPI部分失敗', '2022-05-15T14:20:00+09:00に発生した問題について報告いたします。このインシデントは、バルクAPIが部分失敗しロールバックが未完了だったことが原因です。影響を受けたのは、株式会社ストッククラウドのMercuryサービス全体の一部機能です。エラーコードはEDI-10-00558で、発生契機はデータ移行バッチ実行中でした。状況を確認したところ、バルクAPIが部分失敗し、その結果としてサービスの在庫登録機能に影響が出ました。この問題は、部分成功時の補償トランザクションが欠如していることから生じたと考えられます。運用部の運用 一郎がこの問題を発見し、迅速に対応を行いました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00558', 'INC-2020-00558', 'インシデントの調査を行った結果、データ移行バッチの実行中にバルクAPIが部分失敗したことが確認されました。ロールバック処理が未完了であったため、一部の在庫登録が正常に行われていませんでした。原因として、部分成功時に必要な補償トランザクションが存在しなかったことが特定されました。今後はこのような問題を防ぐために、補償トランザクションの実装を強化し、バッチ処理の監視を徹底します。', 'インシデントの調査を行った結果、データ移行バッチの実行中にバルクAPIが部分失敗したことが確認されました。ロールバック処理が未完了であったため、一部の在庫登録が正常に行われていませんでした。原因として、部分成功時に必要な補償トランザクションが存在しなかったことが特定されました。今後はこのような問題を防ぐために、補償トランザクションの実装を強化し、バッチ処理の監視を徹底します。', TIMESTAMP WITH TIME ZONE '2020-04-09T21:45:03+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00826', 'INC-2020-00558', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T22:00:03+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T23:00:03+09:00', '初期対応', '運用部の運用 一郎は、2022-05-15T14:25:00+09:00に問題を確認し、速やかに対応を開始しました。影響を受けたユーザーへの連絡を行い、状況の把握を進めました。また、バルクAPIのログを確認し、部分失敗の原因を調査しました。この段階で、緊急の修正措置として、補償トランザクションの追加を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00560', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-17T04:25:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T06:25:02+09:00', '【障害報告】【データ同期・整合性障害】楽観ロック競合多発', '2023-10-10T10:00:00+09:00に発生した棚卸突合失敗に関するインシデントです。楽観ロック競合が多発し、更新失敗率が上昇しました。この問題の発生は、大規模セール開始直前のタイミングであり、全テナントに波及する影響が確認されています。エラーコードはSYNC-10-00560です。問題の根本的な原因には、バージョンカラム更新ロジックの不備が疑われ、顧客店舗POSおよび在庫登録APIが影響を受けました。今回のインシデントは、効率的なデータ同期を妨げ、顧客の業務に支障をきたす結果となりました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00560', 'INC-2020-00560', 'このインシデントに関する調査の結果、大規模セール開始直前に発生した楽観ロック競合が原因で更新失敗率が上昇しました。調査においては、バージョンカラム更新ロジックの不備が確認され、これがデータ同期・整合性の問題を引き起こしたことが示唆されました。全テナントに影響を与える事象であったため、迅速な対応が求められました。今後は、ロジックの見直し及びテストを強化する必要があります。', 'このインシデントに関する調査の結果、大規模セール開始直前に発生した楽観ロック競合が原因で更新失敗率が上昇しました。調査においては、バージョンカラム更新ロジックの不備が確認され、これがデータ同期・整合性の問題を引き起こしたことが示唆されました。全テナントに影響を与える事象であったため、迅速な対応が求められました。今後は、ロジックの見直し及びテストを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-18T06:25:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00829', 'INC-2020-00560', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-17T06:40:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T07:40:02+09:00', '【初期対応】【データ同期・整合性障害】楽観ロック競合多発', '本インシデントの発生を受けて、初期対応を実施しました。楽観ロック競合が多発していることを受け、技術チームが迅速に調査を開始し、原因に関する分析を進めました。特に、バージョンカラム更新ロジックの不備に焦点を当て、問題の特定を行いました。また、顧客に対する影響を最小限に抑えるため、当該サービスの一時的な停止やロールバック操作を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00561', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-22T13:33:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T14:03:19+09:00', '【障害報告】【CLU-07】JSONスキーマ不一致', '2020年4月22日13時33分19秒に、株式会社ストッククラウドのMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。当該事象は連携JSONのスキーマ不一致が原因で全件拒否される事態となり、重大度はHIGHと判断されました。検知は13時55分19秒に行われ、検知までの時間は22分間でした。影響はバッチ処理のみに限定されており、オンラインへの影響は確認されていません。発生契機としては定例リリース直後であり、スキーマバージョンの同期漏れが推定原因として考えられます。技術的には、Mercury AWS AP（DRサイト）及びEDIアダプタに関連する問題であり、今後の改善に向けた教訓が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00561', 'INC-2020-00561', '本事象の調査を行った結果、連携されたJSONのスキーマが定例リリース直後に不一致であったことが確認されました。この不一致が発生した原因としては、スキーマバージョンの同期が適切に行われていなかったことが主な要因とされます。調査では、最新のスキーマと実際に使用されたスキーマとの比較が行われ、明確な差異が存在することが判明しました。今後の対策として、リリース前のスキーマ確認プロセスを強化する必要がありま', '本事象の調査を行った結果、連携されたJSONのスキーマが定例リリース直後に不一致であったことが確認されました。この不一致が発生した原因としては、スキーマバージョンの同期が適切に行われていなかったことが主な要因とされます。調査では、最新のスキーマと実際に使用されたスキーマとの比較が行われ、明確な差異が存在することが判明しました。今後の対策として、リリース前のスキーマ確認プロセスを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-23T14:03:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00830', 'INC-2020-00561', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T14:18:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T15:18:19+09:00', '【初期対応】【CLU-07】JSONスキーマの修正', 'インシデント発生後、初期対応として連携JSONのスキーマを修正し、再度バッチ処理を実施しました。修正後のスキーマは、最新のバージョンに基づくものであり、全件正常に処理されることを確認しました。これにより、影響を受けた顧客への迅速な対応が可能となりました。また、今後のインシデント防止に向けて、スキーマの変更管理プロセスを見直し、リリース時のバージョン確認を徹底することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00562', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-23T08:22:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T10:22:45+09:00', '【障害報告】【API連携・EDI障害】EDI在庫差分遅延', '2020年4月23日08時22分45秒に、株式会社ストッククラウドのMercuryサービスにおいて、EDI在庫差分ファイルの反映が2時間遅延する事象が発生しました。発生契機はデータ移行バッチ実行中であり、影響範囲は同一顧客の全店舗に及んでいます。この問題は2020年4月23日08時46分45秒に検知され、検知まで24分を要しました。推定原因として、EDIキューの優先度設定誤りが考えられています。影響を受けたコンポーネントは顧客店舗POSおよびEDIアダプタです。適切な対策を講じる必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00562', 'INC-2020-00562', '本事象の調査を実施した結果、EDI在庫差分ファイルの反映が遅延していた原因として、EDIキューの優先度設定誤りが疑われます。データ移行バッチ実行中において、予期せぬ優先度の競合が発生し、在庫差分データの処理が遅延したものと考えられます。今後は、優先度設定の見直しや監視体制の強化が求められます。さらなる影響を防ぐために、早急な改善策が必要です。', '本事象の調査を実施した結果、EDI在庫差分ファイルの反映が遅延していた原因として、EDIキューの優先度設定誤りが疑われます。データ移行バッチ実行中において、予期せぬ優先度の競合が発生し、在庫差分データの処理が遅延したものと考えられます。今後は、優先度設定の見直しや監視体制の強化が求められます。さらなる影響を防ぐために、早急な改善策が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-24T10:22:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00831', 'INC-2020-00562', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T10:37:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T11:37:45+09:00', '【初動対応】【API連携・EDI障害】EDI在庫差分遅延に対する初動対応', 'この度のEDI在庫差分遅延に関して、初動対応を実施しました。影響を受けた全店舗に対して、状況を周知し、必要な情報提供を行いました。さらに、迅速に原因の特定を行い、対応策を検討するためのチームを編成しました。今後も進捗状況や対応策について、定期的に報告を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00568', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-20T05:00:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T07:00:10+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2023-10-15T10:00:00+09:00に、株式会社ストッククラウドのサービスMercuryにおいて、棚卸突合失敗が発生しました。症状としては、スナップショット復元後に在庫整合が崩れるという事象が確認されました。発生はデータ移行バッチ実行中で、影響範囲は全テナントに波及することが考えられます。エラーコードはSYNC-09-00568であり、発見者は営業部の花子です。検知は2023-10-15T11:00:00+09:00で、116分後に確認されました。バックアップ管理に関連する顧客店舗POS（ゾーンA）で問題が発生しました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00568', 'INC-2020-00568', '調査を進めた結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れた原因として、復元ポイントのトランザクションログ欠落が疑われました。整合性の崩れは、データの不整合を引き起こし、顧客店舗POSに影響を与えていることが確認されています。今後はトランザクションログの管理を見直し、再発防止策を講じる必要があります。', '調査を進めた結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れた原因として、復元ポイントのトランザクションログ欠落が疑われました。整合性の崩れは、データの不整合を引き起こし、顧客店舗POSに影響を与えていることが確認されています。今後はトランザクションログの管理を見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-21T07:00:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00841', 'INC-2020-00568', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T07:15:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T08:15:10+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合', '初期対応として、関連するトランザクションログの確認を行い、復元ポイントに欠落がないかを検証しました。問題が確認された場合、復元プロセスの見直しと、影響を受けたデータの修正を行う方針です。また、顧客への連絡も早急に行い、現状を共有します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00569', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-22T09:45:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T10:15:17+09:00', '【障害報告】【CLU-06】CDNエッジミス', '2023年10月15日、株式会社ストッククラウドのMercuryサービスにおいて、CDNエッジで古い静的資産が配信されるという障害が発生しました。本事象は、定例リリース直後に発生し、サービス全体の一部機能に影響を及ぼしました。検知までに24分を要し、運用部の運用 一郎がこの問題を発見しました。推定される原因はCDNキャッシュ無効化の未実施です。その結果、CDNエッジからの不適切な資産配信が続き、ユーザーに混乱を招きました。今後は定例リリース後のキャッシュ無効化を徹底する必要があります。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00569', 'INC-2020-00569', '私たちは、2023年10月15日に発生したCDNエッジでの古い静的資産配信問題の調査を行いました。調査の結果、定例リリース直後にCDNキャッシュの無効化が行われなかったことが原因と考えられます。この問題は、サービス全体の一部機能に影響を与え、多くのユーザーが不適切な情報を受け取る結果となりました。今後は、リリース後のキャッシュ管理プロセスを見直し、再発を防ぐための対策を講じる必要があります。', '私たちは、2023年10月15日に発生したCDNエッジでの古い静的資産配信問題の調査を行いました。調査の結果、定例リリース直後にCDNキャッシュの無効化が行われなかったことが原因と考えられます。この問題は、サービス全体の一部機能に影響を与え、多くのユーザーが不適切な情報を受け取る結果となりました。今後は、リリース後のキャッシュ管理プロセスを見直し、再発を防ぐための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-23T10:15:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00842', 'INC-2020-00569', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T10:30:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T11:30:17+09:00', '【初期対応】【CLU-06】CDNエッジミス', '2023年10月15日、CDNエッジで古い静的資産が配信されていることが確認されました。運用部の運用 一郎がこの事象を発見し、即座にチームを招集しました。初期対応として、CDNキャッシュの手動無効化を実施しました。さらに、経過観察を行い、ユーザーからのフィードバックを受けて改善策を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00571', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-25T01:40:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T03:40:52+09:00', '【障害報告】【棚卸・POS突合障害】棚卸ラベル印刷失敗', '発生日時: 2023-10-10T01:40:52+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00571', 'INC-2020-00571', '顧客: 株式会社ストッククラウド
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00845', 'INC-2020-00571', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-25T03:55:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T04:55:52+09:00', '【初期対応】【棚卸・POS突合障害】ラベル印刷の初期対応', '2023-10-10T04:15:00+09:00に、顧客店舗のプリンタ設定を見直し、テンプレートIDを正しいものに修正。再度、棚卸用ラベル印刷APIを実行し、404エラーが解消されたことを確認。影響を受けた店舗の担当者に状況を報告し、再発防止のためプリンタ設定の確認を徹底することを周知。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00572', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-19T12:41:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T13:26:16+09:00', '【障害報告】【ストレージ・容量障害】WALアーカイブ滞留', '2023年10月10日12時41分に、株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れのインシデントが発生しました。WALアーカイブが滞留し、ディスクを圧迫する事象が確認されました。この問題は定例リリース直後に発生しており、影響範囲は全テナントに波及しています。発見は運用部の運用 一郎によるもので、2023年10月10日13時26分に検知されました。エラーコードはSTR-08-00572です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00572', 'INC-2020-00572', '調査の結果、WALアーカイブが滞留している原因は、アーカイブ先のマウントポイントが枯渇していたことが疑われます。これにより、ストレージが満杯となり、正常な動作が阻害されたと考えられます。今後、マウントポイントの監視と管理を強化する必要があると判断しました。', '調査の結果、WALアーカイブが滞留している原因は、アーカイブ先のマウントポイントが枯渇していたことが疑われます。これにより、ストレージが満杯となり、正常な動作が阻害されたと考えられます。今後、マウントポイントの監視と管理を強化する必要があると判断しました。', TIMESTAMP WITH TIME ZONE '2020-04-20T13:26:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00846', 'INC-2020-00572', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T13:41:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T14:41:16+09:00', '【初期対応】【ストレージ・容量障害】WALアーカイブ滞留', '初期対応として、運用部は直ちにWALアーカイブの処理を開始しました。また、該当のマウントポイントの状態を確認し、必要に応じてマウントポイントの拡張を行いました。全テナントへの影響を最小限に抑えるため、迅速な対応が求められました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00573', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-18T23:27:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T01:27:23+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2023年10月24日、株式会社ストッククラウドにおいて、顧客店舗POSにおけるOAuthトークン失効が発生し、POS連携が中断しました。発生日時は2023年10月24日23:27で、検知は同日01:51に行われました。影響を受けたのは単一店舗のみであり、エラーコードはEDI-05-00573です。本事象は年末年始の稼働切替時に起こり、リフレッシュトークン保存先に障害があると推定しています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00573', 'INC-2020-00573', '発見者は営業部の花子であり、顧客店舗POSのOAuthトークンが失効したために、POS連携が中断しました。調査の結果、リフレッシュトークンの保存先に障害があったことが示唆されています。現在、障害の詳細な分析と解決策の検討を進めており、迅速な復旧を目指しています。', '発見者は営業部の花子であり、顧客店舗POSのOAuthトークンが失効したために、POS連携が中断しました。調査の結果、リフレッシュトークンの保存先に障害があったことが示唆されています。現在、障害の詳細な分析と解決策の検討を進めており、迅速な復旧を目指しています。', TIMESTAMP WITH TIME ZONE '2020-04-20T01:27:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00847', 'INC-2020-00573', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T01:42:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T02:42:23+09:00', '初期対応ログ', '2023年10月24日23:30に、障害の初期対応を開始しました。営業部の花子が状況を確認し、担当エンジニアと連携して原因の特定を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00848', 'INC-2020-00573', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T03:12:23+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T04:12:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00578', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-27T00:14:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T00:44:27+09:00', '【障害報告】【認証・セッション障害】セッション突然切断', '2020年04月27日00時14分27秒に、株式会社ストッククラウドが提供するMercuryにおいて、特定リージョンのユーザーに対して操作中にセッションが突然切断される事象が発生しました。この事象は、インフラメンテナンス明けに発生し、セッションTTL設定の短縮が原因と考えられています。影響を受けたのはVenus Azure AP（ゾーンB）内のセッションストアであり、エラーコードはAUTH-02-00578です。運用部の運用 一郎が発見し、検知までに18分を要しました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00578', 'INC-2020-00578', '今回のセッション突然切断について、インフラメンテナンス明けのタイミングで発生したことが確認されました。セッションTTL設定の短縮が反映されている可能性が高いと考えられ、特定リージョンのユーザーにのみ影響が出ていることも確認されました。システムログを確認したところ、切断の発生時刻とメンテナンス終了時刻が重なっており、原因の特定が進んでいます。', '今回のセッション突然切断について、インフラメンテナンス明けのタイミングで発生したことが確認されました。セッションTTL設定の短縮が反映されている可能性が高いと考えられ、特定リージョンのユーザーにのみ影響が出ていることも確認されました。システムログを確認したところ、切断の発生時刻とメンテナンス終了時刻が重なっており、原因の特定が進んでいます。', TIMESTAMP WITH TIME ZONE '2020-04-28T00:44:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00853', 'INC-2020-00578', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T00:59:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T01:59:27+09:00', '【初期対応】【認証・セッション障害】セッション切断の初期対応', 'セッション突然切断の事象が確認されたため、直ちに運用部にて調査を開始しました。影響範囲を特定し、該当するユーザーへの通知を行いました。また、セッションTTL設定の確認を行い、必要な修正を検討するためのヒアリングを実施しました。今後の対応として、設定変更の影響を最小限に抑えるための対策を講じる予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00854', 'INC-2020-00578', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T02:29:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T03:29:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00579', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-18T03:14:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T03:29:06+09:00', '【障害報告】【運用操作・権限障害】監視画面真っ白', '2023-10-01T10:00:00+09:00に株式会社ストッククラウドの運用コンソールにおいて、監視ダッシュボードが真っ白でメトリクス非表示の事象が発生しました。影響範囲は運用部門のみであり、エラーコードはOPS-04-00579です。この障害は定例リリース直後に発生し、運用 一郎が発見しました。グラフクエリの時間範囲パラメータの誤設定が推定原因と考えられます。検知には18分を要しました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00579', 'INC-2020-00579', '監視ダッシュボードが真っ白でメトリクス非表示となった事象について調査を行いました。定例リリース直後に発生したため、リリース内容を確認したところ、グラフクエリの時間範囲パラメータが誤設定であったことが判明しました。この設定ミスにより、運用部門では必要な情報を得ることができず、監視業務に支障をきたしました。', '監視ダッシュボードが真っ白でメトリクス非表示となった事象について調査を行いました。定例リリース直後に発生したため、リリース内容を確認したところ、グラフクエリの時間範囲パラメータが誤設定であったことが判明しました。この設定ミスにより、運用部門では必要な情報を得ることができず、監視業務に支障をきたしました。', TIMESTAMP WITH TIME ZONE '2020-04-19T03:29:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00855', 'INC-2020-00579', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T03:44:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T04:44:06+09:00', '【初期対応】【運用操作・権限障害】監視画面真っ白', '初期対応として、運用 一郎が当該ダッシュボードの設定を確認し、グラフクエリの時間範囲パラメータの誤設定を修正しました。その後、監視ダッシュボードが正常に表示されることを確認し、運用部門に状況を報告しました。この対応により、運用部門は必要なメトリクスを再度確認できるようになりました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00856', 'INC-2020-00579', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T05:14:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T06:14:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00590', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-16T17:06:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T19:06:04+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '2020年4月16日17時06分04秒に発生した棚卸突合失敗に関する障害報告です。現象として、顧客店舗POSにおいてアウトボックステーブルの滞留が確認され、通知遅延が発生しました。本件は定例リリース直後に起こったもので、サービス全体の一部機能に影響を及ぼしています。推定される原因としては、アウトボックスポーラーの停止が考えられます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00590', 'INC-2020-00590', '調査の結果、定例リリース直後に発生したアウトボックステーブル滞留による通知遅延が確認されました。主要な要因として、アウトボックスポーラーの停止が挙げられます。この問題は、サービスの一部機能に影響を及ぼしているため、早急な対応が必要です。', '調査の結果、定例リリース直後に発生したアウトボックステーブル滞留による通知遅延が確認されました。主要な要因として、アウトボックスポーラーの停止が挙げられます。この問題は、サービスの一部機能に影響を及ぼしているため、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-17T19:06:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00874', 'INC-2020-00590', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T19:21:04+09:00', NULL, '【初期対応】【データ同期・整合性障害】アウトボックス滞留', '初期対応として、アウトボックスポーラーの状態を確認し、必要な再起動を行いました。また、関連するシステムコンポーネントのログを分析し、さらなる問題の有無を確認しました。これにより、通知遅延の解消を図るとともに、問題の再発防止策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00596', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-03T14:16:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T14:46:30+09:00', '【障害報告】【CLU-09】マスター在庫二重反映', '2023年10月25日、株式会社ストッククラウドのMercuryサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。症状としては、マスター更新と在庫が二重反映されることが確認されました。この現象は、定例リリース直後に発生し、全店舗に影響を及ぼしました。推定原因としては、イベント順序の逆転配信が考えられます。本件におけるエラーコードはSYNC-01-00596です。影響コンポーネントはMercury AWS AP（Primary）およびイベントバスです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00596', 'INC-2020-00596', '本障害の調査を行った結果、定例リリース直後に発生したことが確認されました。マスター更新と在庫の二重反映は、イベント順序が逆転して配信されたことが原因と考えられます。この問題により、同一顧客の全店舗に影響が及び、通常のデータ同期・整合性が著しく損なわれました。', '本障害の調査を行った結果、定例リリース直後に発生したことが確認されました。マスター更新と在庫の二重反映は、イベント順序が逆転して配信されたことが原因と考えられます。この問題により、同一顧客の全店舗に影響が及び、通常のデータ同期・整合性が著しく損なわれました。', TIMESTAMP WITH TIME ZONE '2020-04-04T14:46:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00883', 'INC-2020-00596', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-03T15:01:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T16:01:30+09:00', '【初期対応】【CLU-09】マスター在庫二重反映', '初期対応として、運用部の運用 一郎がこの問題を検知し、直ちに対応を開始しました。対象となるマスター更新の履歴を確認し、二重反映の原因を特定するための調査を実施しました。さらに、アラートシステムを用いて同様の事象が発生しないよう監視体制を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00610', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-03T22:50:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T23:35:47+09:00', '【障害報告】【CLU-10】アラート疲労', '2023-10-10T14:30:00+09:00に、株式会社ストッククラウドのMercuryにおいて、ストレージ溢れのインシデントが発生しました。運用部の運用 一郎が同日14:50頃に問題を検知し、同一アラートが短時間に数百件発報される事象が確認されました。検知までの時間は約20分でした。大規模セール開始直前という発生契機があり、この状況により運用部門に影響を及ぼしました。アラート抑制ルールが未設定であったことが推定原因として挙げられています。これらの理由から、監視・可用性障害が発生したと考えられます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00610', 'INC-2020-00610', '本インシデントの調査の結果、同一アラートが短時間に数百件発報された原因として、アラート抑制ルールの未設定が推定されます。大規模セール開始直前の状況において、運用部門のみが影響を受け、他部門には波及しませんでした。このアラート疲労の問題を解決するためには、適切なアラート抑制ルールを設定し、再発を防ぐ必要があります。', '本インシデントの調査の結果、同一アラートが短時間に数百件発報された原因として、アラート抑制ルールの未設定が推定されます。大規模セール開始直前の状況において、運用部門のみが影響を受け、他部門には波及しませんでした。このアラート疲労の問題を解決するためには、適切なアラート抑制ルールを設定し、再発を防ぐ必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-04T23:35:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00903', 'INC-2020-00610', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-03T23:50:47+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T00:50:47+09:00', '【初期対応】【CLU-10】アラート疲労', 'インシデント発生後、運用部門では直ちに対応を開始しました。発報されたアラートの内容を精査し、不要なアラートの抑制を行うためのルール作成に着手しました。運用 一郎が主導となり、関係者と連携を取りながら、アラート管理システムの設定を見直し、問題の特定と修正に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00611', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-18T13:43:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T14:13:15+09:00', '【障害報告】【性能・負荷障害】ピーク時画面10秒', '2023年10月01日 13:43:15 に株式会社ストッククラウドのサービスMercuryにおいて、利用者増による応答遅延が発生しました。具体的には、ピーク時に画面表示が10秒以上かかる現象が確認され、全テナントに波及する影響が及びました。発生契機は大規模セール開始直前であり、推定原因としてキャンペーンによるアクセス急増が考えられます。検知は2023年10月01日 14:32:15 に行われ、発見者は運用部の運用 一郎です。影響を受けたコンポーネントはVenus Azure AP（Primary）であり、APサーバークラスタが問題の中心となっています。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00611', 'INC-2020-00611', '障害発生後の調査において、ピーク時に画面遅延が発生していることが確認されました。調査チームは、利用者のアクセス急増が原因であると特定し、キャンペーンによる突然のトラフィック増加が影響を及ぼしたことがわかりました。今後の対応策として、サーバーリソースの拡張や負荷分散の最適化を検討する必要があります。', '障害発生後の調査において、ピーク時に画面遅延が発生していることが確認されました。調査チームは、利用者のアクセス急増が原因であると特定し、キャンペーンによる突然のトラフィック増加が影響を及ぼしたことがわかりました。今後の対応策として、サーバーリソースの拡張や負荷分散の最適化を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-19T14:13:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00904', 'INC-2020-00611', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T14:28:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T15:28:15+09:00', '【初動対応】【性能・負荷障害】ピーク時画面10秒', '初動対応として、障害発生の確認後にAPサーバークラスタの状態を迅速にチェックし、リソースの使用状況を監視しました。また、異常なトラフィックパターンを確認し、急増したアクセスを軽減するための暫定的な措置を講じました。顧客への情報提供も早急に行い、今後の影響を最小限に抑える努力を続けています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00905', 'INC-2020-00611', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T15:58:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T16:58:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00613', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-09T05:27:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T07:27:14+09:00', '【障害報告】【データ同期・整合性障害】クロスリージョンレプリケーション', '2020年4月9日05時27分に発生した棚卸突合失敗に関するインシデントです。発生した症状は、クロスリージョン複製が片系のみ更新されている状況です。発見者は営業部の花子です。インフラメンテナンス明けにこの問題が検知され、特定リージョンのユーザーに影響を及ぼしています。エラーコードはSYNC-07-00613です。影響を受けているコンポーネントは顧客店舗POS（ゾーンB）およびレプリケーションゲートウェイです。検知には172分かかり、ユーザーへの影響を最小限に抑えられるよう迅速に対応する必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00613', 'INC-2020-00613', '調査の結果、リージョンルーティングの誤設定が原因と考えられます。インフラメンテナンス後の変更により、クロスリージョン複製が片系のみの更新となり、データの不整合が発生しました。システム全体での影響範囲を確認し、特定リージョンのユーザーに対する影響を評価しました。今後の改善策として、リージョンルーティング設定の見直しが必要です。', '調査の結果、リージョンルーティングの誤設定が原因と考えられます。インフラメンテナンス後の変更により、クロスリージョン複製が片系のみの更新となり、データの不整合が発生しました。システム全体での影響範囲を確認し、特定リージョンのユーザーに対する影響を評価しました。今後の改善策として、リージョンルーティング設定の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2020-04-10T07:27:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00907', 'INC-2020-00613', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-09T07:42:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T08:42:14+09:00', '初期対応', '初期対応として、影響を受けている顧客店舗POSの状況を確認し、迅速にリージョンルーティング設定の修正を行います。データの整合性を保つため、レプリケーションゲートウェイの状態も確認し、必要に応じて再設定を行う予定です。また、ユーザーへの影響を最小限に抑えるため、通知を行い、状況の進捗を随時報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00615', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-13T04:29:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T05:14:40+09:00', '【障害報告】【ストレージ・容量障害】レプリカ遅延肥大', '2023-10-01T10:15:00+09:00に発生した事象について報告いたします。レプリカ遅延により差分ログが肥大化し、Mercury AWS Storageにおけるストレージ容量に影響を及ぼしました。影響範囲は読取専用レプリカ利用者であり、大規模セール開始直前のタイミングで発生したことから、販売活動に支障をきたす恐れがありました。エラーコードはSTR-10-00615で、運用 一郎が本事象を発見しました。レプリカ帯域制限設定が過小であったことが推定原因です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00615', 'INC-2020-00615', '本事象の調査を行った結果、レプリカ遅延により差分ログが肥大化したことが確認されました。これによりMercury AWS Storageのストレージ容量が逼迫し、サービス品質が低下する事態となりました。特に、大規模セール開始直前にこの問題が発生したため、顧客への影響が懸念されました。今後はレプリカ帯域制限設定の見直しを行い、このような事象の再発を防ぐ必要があります。', '本事象の調査を行った結果、レプリカ遅延により差分ログが肥大化したことが確認されました。これによりMercury AWS Storageのストレージ容量が逼迫し、サービス品質が低下する事態となりました。特に、大規模セール開始直前にこの問題が発生したため、顧客への影響が懸念されました。今後はレプリカ帯域制限設定の見直しを行い、このような事象の再発を防ぐ必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-14T05:14:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00909', 'INC-2020-00615', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T05:29:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T06:29:40+09:00', '【初動対応】【ストレージ・容量障害】レプリカ遅延肥大', 'インシデント発生後、直ちに運用部より対応を開始しました。原因として考えられるレプリカ帯域制限の調整を試み、差分ログの肥大化を抑制する施策を講じました。また、影響を受けた読取専用レプリカ利用者への情報提供を行い、サービス品質の維持に努めました。この初動対応により、顧客への影響を最小限に留めることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00910', 'INC-2020-00615', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T06:59:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T07:59:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00617', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-26T06:25:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T06:55:06+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '株式会社ストッククラウドのサービス、Mercuryにおいて、2020年5月1日 06:25:06に死活監視が正常系をDOWNと誤検知する事象が発生しました。本事象は監視プローブのUser-Agentブロックが推定原因であり、運用部門にのみ影響を及ぼしました。定例リリース直後に発生しており、関連するエラーコードはMON-01-00617です。死活監視の誤検知により、正常な状態がDOWNと認識されてしまったため、運用部門において作業に影響が出ました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00617', 'INC-2020-00617', '本事象の調査では、死活監視が正常系をDOWNと誤検知した原因を探るため、監視プローブの設定を確認しました。定例リリースの内容にも着目し、リリースによって新たに導入された設定が影響を与えた可能性があると考えられます。特にUser-Agentのブロックが原因であることが示唆されており、これにより監視プローブが正常な応答を適切に処理できなかったものと推測されます。', '本事象の調査では、死活監視が正常系をDOWNと誤検知した原因を探るため、監視プローブの設定を確認しました。定例リリースの内容にも着目し、リリースによって新たに導入された設定が影響を与えた可能性があると考えられます。特にUser-Agentのブロックが原因であることが示唆されており、これにより監視プローブが正常な応答を適切に処理できなかったものと推測されます。', TIMESTAMP WITH TIME ZONE '2020-04-27T06:55:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00912', 'INC-2020-00617', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T07:10:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T08:10:06+09:00', '初期対応', '運用部門は本事象の発生を受け、まず死活監視のログを確認し、誤検知の詳細を把握しました。監視プローブの設定を見直し、User-Agentのブロックが影響を及ぼしている可能性を特定しました。その後、設定の修正を行い、死活監視が正常に機能することを確認しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00913', 'INC-2020-00617', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T08:40:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T09:40:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00622', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-23T16:16:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T16:46:37+09:00', '【障害報告】【認証・セッション障害】リフレッシュトークン再利用', '2023年10月01日16時16分37秒に、株式会社ストッククラウドのMercuryサービスにおいて、リフレッシュトークン再利用検知による全端末のログアウトが発生しました。本事象は、年末年始の稼働切替時に発生したもので、同一顧客の全店舗に影響を及ぼしました。原因としては、トークンローテーション実装の不備が疑われています。この影響により、利用者は一時的にサービスへのアクセスを失うこととなりました。エラーコードはAUTH-10-00622です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00622', 'INC-2020-00622', '本インシデントに関する調査を行った結果、年末年始の稼働切替時にリフレッシュトークンの再利用が検知され、全端末がログアウトされたことがわかりました。トークンローテーションの実装に不備があったため、リフレッシュトークンの管理に問題が生じました。今後は、同様の事象を未然に防ぐため、ローテーションシステムの見直しとテストを強化する必要があります。', '本インシデントに関する調査を行った結果、年末年始の稼働切替時にリフレッシュトークンの再利用が検知され、全端末がログアウトされたことがわかりました。トークンローテーションの実装に不備があったため、リフレッシュトークンの管理に問題が生じました。今後は、同様の事象を未然に防ぐため、ローテーションシステムの見直しとテストを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T16:46:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00920', 'INC-2020-00622', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T17:01:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T18:01:37+09:00', '【対応ログ】INITIAL対応', '2023年10月01日16時49分37秒に本事象を検知し、迅速に初期対応を開始しました。リフレッシュトークンの管理システムの確認と、影響を受けた顧客への通知を行いました。サービスの復旧を図るため、トークンローテーションの実装状況を確認し、必要な修正を行うためのチームを編成しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00623', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-28T10:27:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T10:57:50+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2023-10-01T14:15:30+09:00に発生したWebhook再送が嵐状となり、先方で拒否された。発生契機は定例リリース直後であり、影響範囲は単一店舗に限定されている。エラーコードはEDI-02-00623で、Mercury AWS APのWebhookディスパッチャに影響を及ぼした。再送間隔の指数バックオフが未設定であったため、短時間に多くの再送が行われたことが原因と考えられる。検知は2023-10-01T14:47:30+09:00で、約32分後に問題が認識された。即座に対応を開始し、状況の把握を進めている。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00623', 'INC-2020-00623', 'Webhookの再送が異常に頻発した原因を調査された。定例リリース直後にGalileoの設定が変更された結果、再送間隔の指数バックオフが適用されていなかったことが判明した。これにより、APIとの連携において過剰なリクエストが生じ、先方システムからの拒否が引き起こされた。再発防止策として、Webhook再送の設定を見直し、関連チームとの協議を実施する予定である。', 'Webhookの再送が異常に頻発した原因を調査された。定例リリース直後にGalileoの設定が変更された結果、再送間隔の指数バックオフが適用されていなかったことが判明した。これにより、APIとの連携において過剰なリクエストが生じ、先方システムからの拒否が引き起こされた。再発防止策として、Webhook再送の設定を見直し、関連チームとの協議を実施する予定である。', TIMESTAMP WITH TIME ZONE '2020-04-29T10:57:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00921', 'INC-2020-00623', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T11:12:50+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T12:12:50+09:00', '初期対応', 'Webhooksの再送が激増していることに気づき、直ちに担当チームが調査を開始した。問題の特定のために各種ログを確認し、定例リリースに伴う設定変更が原因であることが明らかになった。関連チームへの連絡を行い、早急に修正作業に着手する手配を行った。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00624', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-29T10:13:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T10:43:29+09:00', '【障害報告】【CLU-07】冪等キー重複', '2023-10-01T14:00:00+09:00に発生したインシデントです。株式会社ストッククラウドのMercuryサービスにおいて、冪等キー重複により在庫更新がスキップされました。
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00624', 'INC-2020-00624', '2023-10-01T14:00:00+09:00に発見された冪等キー重複の事象について調査を行いました。まず、発生のトリガーとなった定例リリースを確認しました。リリース後の冪等キー生成ロジックに関連するコードを精査し、衝突が発生している可能性を特定しました。今後、冪等キー生成ロジックの見直しが必要です。', '2023-10-01T14:00:00+09:00に発見された冪等キー重複の事象について調査を行いました。まず、発生のトリガーとなった定例リリースを確認しました。リリース後の冪等キー生成ロジックに関連するコードを精査し、衝突が発生している可能性を特定しました。今後、冪等キー生成ロジックの見直しが必要です。', TIMESTAMP WITH TIME ZONE '2020-04-30T10:43:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00922', 'INC-2020-00624', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-29T10:58:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T11:58:29+09:00', '初期対応', '発生した冪等キー重複に対して、運用部の運用 一郎が初期対応を行いました。影響を受けている全店舗の在庫更新状態を確認し、必要に応じて手動で更新を実施しました。また、関連するチームに通知を行い、問題の早急な解決を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00923', 'INC-2020-00624', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-29T12:28:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T13:28:29+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00628', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-15T10:31:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T11:31:39+09:00', '【障害報告】【顧客ネットワーク障害】回線断後セッション未復旧', '2023年10月01日10時31分39秒に、株式会社ストッククラウドの顧客ネットワークにおいて、拠点回線が断された後、セッションが復旧しない事象が発生いたしました。検知時間は2023年10月01日11時25分39秒で、発見者は営業部の花子でございます。本事象は単一店舗に影響を及ぼし、具体的には顧客拠点NW（ゾーンB）および拠点VPNゲートウェイに関連しております。推定原因としては、VPNクライアントのバージョン不整合が考えられます。回線断後のセッション復旧が行われず、顧客ネットワークの正常な運用が阻害されています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00628', 'INC-2020-00628', '本障害は、年末年始の稼働切替時に発生いたしました。拠点回線断復旧後、セッションが復旧しないという症状が確認されております。調査の結果、VPNクライアントのバージョン不整合が原因として疑われており、これが影響範囲を狭めている可能性があります。必要な対応策を速やかに講じることが求められます。', '本障害は、年末年始の稼働切替時に発生いたしました。拠点回線断復旧後、セッションが復旧しないという症状が確認されております。調査の結果、VPNクライアントのバージョン不整合が原因として疑われており、これが影響範囲を狭めている可能性があります。必要な対応策を速やかに講じることが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-16T11:31:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00927', 'INC-2020-00628', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-15T11:46:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T12:46:39+09:00', '初期対応', '本事象に関し、直ちに顧客へ状況を説明し、回線断による影響を最小限に抑えるための初期対応を行いました。VPNクライアントのバージョン確認と、必要に応じたアップデート作業を実施する準備を進めています。引き続き、状況を注視し、顧客に対して最新の情報を提供してまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00928', 'INC-2020-00628', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-15T13:16:39+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T14:16:39+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00629', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-01T11:22:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T11:52:00+09:00', '【障害報告】【CLU-01】バーコード照合エラー', '2023-10-01 09:00に、株式会社ストッククラウドのMercuryサービスにおいて、バーコードスキャン後に照合エラーが発生し、在庫登録ができない事象が発生しました。本事象は新規店舗追加の初日に発生しており、影響範囲は単一店舗のみです。また、エラーコードはMST-06-00629で、原因としてチェックディジット検証ロジックの誤設定が考えられます。運用部の運用 一郎が発見し、検知までに36分が経過しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00629', 'INC-2020-00629', '運用 一郎が発見したバーコード照合エラーの原因を調査しました。新規店舗追加の初日にPOS連携アダプタのチェックディジット検証ロジックが誤設定されており、結果としてバーコードスキャン後に照合エラーが発生し、在庫登録ができない状況が確認されました。今後、この問題を防ぐための対策が必要です。', '運用 一郎が発見したバーコード照合エラーの原因を調査しました。新規店舗追加の初日にPOS連携アダプタのチェックディジット検証ロジックが誤設定されており、結果としてバーコードスキャン後に照合エラーが発生し、在庫登録ができない状況が確認されました。今後、この問題を防ぐための対策が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-02T11:52:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00929', 'INC-2020-00629', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T12:07:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T13:07:00+09:00', '【初動対応】【CLU-01】バーコード照合エラー', '運用 一郎は、バーコード照合エラーの問題を受けて、まずは該当店舗の設定を確認しました。チェックディジット検証ロジックの修正を行う前に、既存の設定をバックアップし、エラーの再現テストを実施しました。これにより、問題の根本原因を特定し、早期の解決に向けた対応を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00930', 'INC-2020-00629', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T13:37:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T14:37:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00631', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-28T04:37:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T05:07:29+09:00', '【障害報告】【CLU-09】マスター在庫二重反映', '2020年4月28日04時37分29秒に、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録が失敗しました。本事象では、マスター更新と在庫が二重反映される症状が発生しました。これは、定例リリース直後に起こったもので、同一顧客の全店舗に影響を及ぼします。エラーコードはSYNC-01-00631です。技術的には、イベント順序の逆転配信が原因として疑われ、Mercury AWS AP（DRサイト）およびイベントバスにおいて問題が確認されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00631', 'INC-2020-00631', '本件についての調査を実施しました。発生契機は定例リリース直後であり、原因としてイベント順序の逆転配信が指摘されています。データ同期・整合性の観点から、すべての関連データの流れを確認し、二重反映の根本的な要因を特定する必要があります。今後、再発防止策を講じることが求められます。', '本件についての調査を実施しました。発生契機は定例リリース直後であり、原因としてイベント順序の逆転配信が指摘されています。データ同期・整合性の観点から、すべての関連データの流れを確認し、二重反映の根本的な要因を特定する必要があります。今後、再発防止策を講じることが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-29T05:07:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00932', 'INC-2020-00631', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T05:22:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T06:22:29+09:00', '【初動対応】マスター在庫二重反映', '初動対応として、まずは影響を受けた全店舗の在庫状況を確認し、二重反映の影響を受けたデータを修正しました。また、システムログを精査し、イベント順序に関する問題を特定し、解決に向けた措置を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00632', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-12T15:17:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-12T15:32:20+09:00', '【障害報告】【運用操作・権限障害】メンテ解除失敗', '2023-10-10T10:00:00+09:00に発生した運用者の作業ミスによるアクセス障害についてご報告いたします。この障害は、運用コンソールにおいてメンテナンスモード解除操作が失敗するという症状を引き起こしました。具体的には、インフラメンテナンス明けにメンテナンスモード解除が行われたが、メンテナンスフラグが残留していたために解除が失敗しました。サービス全体の一部機能に影響が出ており、早急な対応が求められます。顧客への影響は現在確認中です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00632', 'INC-2020-00632', '運用部の運用 一郎が障害の調査を行いました。メンテナンスモード解除操作が失敗した原因は、メンテナンスフラグの残留にあると推定されます。この状態では運用コンソールが正しく動作せず、サービスの一部機能が影響を受けることが確認されました。今後、再発防止策を検討し、早急に対応が必要です。', '運用部の運用 一郎が障害の調査を行いました。メンテナンスモード解除操作が失敗した原因は、メンテナンスフラグの残留にあると推定されます。この状態では運用コンソールが正しく動作せず、サービスの一部機能が影響を受けることが確認されました。今後、再発防止策を検討し、早急に対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-13T15:32:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00933', 'INC-2020-00632', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-12T15:47:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-12T16:47:20+09:00', '【初期対応】【運用操作・権限障害】メンテ解除失敗', '2023-10-10T10:05:00+09:00に運用 一郎が初期対応を開始しました。状況を確認し、メンテナンスフラグの確認を行いました。フラグが残留していることが確認されたため、即座に解除作業を実施しました。対応の結果、運用コンソールの機能が復旧し、サービスの正常化が図られました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00633', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-02T07:42:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T08:27:41+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2020年4月2日07時42分41秒に、株式会社ストッククラウドのMercuryサービスにおいて、ヘルスチェック過多によるAPサーバーの負荷増加が発生しました。発見時刻は08時26分41秒で、検知までに44分を要しました。発生の契機はインフラメンテナンス明けであり、全テナントに影響を及ぼしています。エラーコードはMON-06-00633で、影響コンポーネントはMercury AWS Storageおよびロードバランサです。この状況では、LBヘルスチェック間隔の過短設定が推定原因とされています。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00633', 'INC-2020-00633', 'インフラメンテナンス明けに発生したヘルスチェック過多が、APサーバーの過負荷を引き起こしていることが確認されました。LBのヘルスチェック間隔が過短に設定されていることが原因と考えられ、全テナントに影響を及ぼす可能性があります。さらなる調査を進め、具体的な設定値を確認する必要があります。', 'インフラメンテナンス明けに発生したヘルスチェック過多が、APサーバーの過負荷を引き起こしていることが確認されました。LBのヘルスチェック間隔が過短に設定されていることが原因と考えられ、全テナントに影響を及ぼす可能性があります。さらなる調査を進め、具体的な設定値を確認する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-03T08:27:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00934', 'INC-2020-00633', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-02T08:42:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-02T09:42:41+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎が初期調査を実施し、ヘルスチェック過多がAPサーバーに負荷をかけていることを確認。迅速にLBのヘルスチェック間隔の設定を見直し、適切な値に修正することを提案します。全テナントに影響が出る前に対応する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00634', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-07T15:06:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T17:06:21+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '2023年10月01日12時30分に発生した棚卸突合失敗について報告いたします。本事象は、顧客店舗POSにおいて、アウトボックステーブルが滞留し、通知の遅延が生じました。推定される原因としては、アウトボックスポーラーの停止が挙げられ、影響範囲はサービス全体の一部機能に及びます。この障害は、定例リリース直後に発生し、発見者は営業部の花子でございます。発生時刻は2023年10月01日12時30分、検知は2023年10月01日14時05分に行われ、95分後に問題が確認されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00634', 'INC-2020-00634', '本件に関する調査の結果、アウトボックステーブルの滞留が確認されました。資料から、定例リリース直後にアウトボックスポーラーが停止したことが原因であると考えられます。このため、顧客店舗POSでの通知が遅延し、影響が生じました。現在、問題の再発防止に向けての対策を検討中です。', '本件に関する調査の結果、アウトボックステーブルの滞留が確認されました。資料から、定例リリース直後にアウトボックスポーラーが停止したことが原因であると考えられます。このため、顧客店舗POSでの通知が遅延し、影響が生じました。現在、問題の再発防止に向けての対策を検討中です。', TIMESTAMP WITH TIME ZONE '2020-04-08T17:06:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00935', 'INC-2020-00634', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T17:21:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T18:21:21+09:00', '【初動対応】【データ同期・整合性障害】アウトボックス滞留', '本障害に対し、初動対応を実施しました。まず、アウトボックスポーラーの状態を確認し、停止の原因を特定するための調査を開始しました。また、影響を受けた顧客店舗POSに対しては、早急な情報提供を行い、状況を把握していただけるよう努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00936', 'INC-2020-00634', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-07T18:51:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T19:51:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00641', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-07T21:04:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T21:34:10+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2020年4月7日21時04分に、株式会社ストッククラウドのサービスMercuryにおいて、在庫登録失敗が発生しました。本障害は、読取レプリカ遅延により在庫照会が古い値となり、特定リージョンのユーザーに影響を及ぼしました。発生契機は大規模セール開始直前であり、影響を受けたコンポーネントはMercury AWS AP（DRサイト）及び読取専用レプリカです。エラーコードはSYNC-02-00641です。この問題は21時41分に検知され、検知までの時間は37分でした。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00641', 'INC-2020-00641', '調査の結果、大規模セール開始直前にレプリケーション遅延の監視閾値を超過したことが原因であると考えられます。システムのログを確認したところ、レプリカ遅延が発生しており、在庫照会に影響を与えたことが確認できました。これは、特定リージョンのユーザーに古い値を返す結果となり、影響範囲を特定する必要があります。今後の対応策として、監視体制の強化が求められます。', '調査の結果、大規模セール開始直前にレプリケーション遅延の監視閾値を超過したことが原因であると考えられます。システムのログを確認したところ、レプリカ遅延が発生しており、在庫照会に影響を与えたことが確認できました。これは、特定リージョンのユーザーに古い値を返す結果となり、影響範囲を特定する必要があります。今後の対応策として、監視体制の強化が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-08T21:34:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00946', 'INC-2020-00641', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T21:49:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T22:49:10+09:00', '【対応記録】【データ同期・整合性障害】初期対応', '初期対応として、レプリケーション遅延の原因調査を開始しました。システムのパフォーマンスを監視し、各コンポーネントの状態を確認しました。また、影響を受けたユーザーへの情報提供を行い、状況を説明しました。今後の方針として、再発防止策を検討するため、詳細な分析を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00947', 'INC-2020-00641', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-07T23:19:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T00:19:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00642', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-16T00:38:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T01:38:22+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '2023-10-10T14:00:00+09:00 に発生した顧客側ネットワーク障害について報告します。発生場所は顧客拠点NWで、店舗DNSキャッシュが旧IPを返し続ける症状が確認されました。問題の推定原因は、DNS TTL設定とキャッシュ方針の不一致です。この影響により、単一店舗のみでの影響が確認されています。エラーコードは NW-08-00642 です。発生契機は定例リリース直後であり、その後95分後に検知されました。技術的には、定例リリース直後に店舗DNSキャッシュが旧IPを返し続ける状況が見受けられます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00642', 'INC-2020-00642', '本インシデントの調査を実施しました。定例リリースの影響でDNSキャッシュが旧IPを返していることが判明しました。DNS TTL設定とキャッシュ方針の不一致が原因と考えられます。この問題は顧客ネットワークにおいて顕著に現れ、単一店舗に限定されました。今後の対策として、TTL設定の見直しを行います。', '本インシデントの調査を実施しました。定例リリースの影響でDNSキャッシュが旧IPを返していることが判明しました。DNS TTL設定とキャッシュ方針の不一致が原因と考えられます。この問題は顧客ネットワークにおいて顕著に現れ、単一店舗に限定されました。今後の対策として、TTL設定の見直しを行います。', TIMESTAMP WITH TIME ZONE '2020-04-17T01:38:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00948', 'INC-2020-00642', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T01:53:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T02:53:22+09:00', '【対応】【顧客ネットワーク障害】DNSキャッシュ汚染', '初期対応として、DNSキャッシュのクリアを実施しました。また、TTL設定を確認し、キャッシュ方針の整合性を取る作業を行いました。問題の再発防止に向け、関係者と連携し、設定の見直しを進めています。今後の改善策については、監視体制の強化も検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00949', 'INC-2020-00642', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-16T03:23:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T04:23:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00649', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-03T11:42:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T12:12:53+09:00', '【障害報告】【CLU-09】整合性チェックアラート', '2020年4月3日11時42分53秒、株式会社ストッククラウドのサービスMercuryにおいて、整合性チェックで不一致アラートが多発しました。発生した契機は月末棚卸の開始時です。夜間の整合性チェックにおいて不一致が確認され、影響範囲はバッチ処理のみであり、オンラインには影響はありませんでした。発見者は運用部の運用 一郎です。エラーコードはSYNC-06-00649です。技術詳細として、整合性チェック基準の変更が未反映であることが推定されます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00649', 'INC-2020-00649', '調査の結果、整合性チェック基準の変更が未反映であることが確認されました。月末棚卸の開始時において、整合性チェックジョブが正常に動作せず、不一致アラートが多発しました。今後、整合性チェック基準の反映状況を確認し、再発防止策を講じる必要があります。', '調査の結果、整合性チェック基準の変更が未反映であることが確認されました。月末棚卸の開始時において、整合性チェックジョブが正常に動作せず、不一致アラートが多発しました。今後、整合性チェック基準の反映状況を確認し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-04T12:12:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00959', 'INC-2020-00649', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-03T12:27:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T13:27:53+09:00', '【初期対応】【CLU-09】整合性チェックアラート', '初期対応として、整合性チェック基準の変更点を確認し、必要な修正を行いました。また、影響を受けたバッチ処理の再実行を行い、整合性の確保を図りました。今後の対策として、整合性チェック基準の変更を定期的に確認し、影響を受ける可能性のある処理に対して事前に周知徹底を行う方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00650', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-13T08:09:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T08:39:46+09:00', '【障害報告】【CLU-07】配送連携ステータス停滞', '2023年10月01日、株式会社ストッククラウド様において、Mercuryのマスター設定ミスによる在庫登録失敗の障害が発生いたしました。症状としては、配送連携のステータスが出荷済みで停滞しており、影響範囲は単一店舗のみとされております。発生は大規模セール開始直前であり、エラーコードはEDI-09-00650です。技術的な詳細に関しては、配送連携アダプタにおいてステータスマッピング表の更新漏れが原因として疑われております。検知が行われたのは発生から30分後の2023年10月01日08時39分であり、現在、緊急の対応が求められております。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00650', 'INC-2020-00650', '本障害の調査を進めた結果、配送連携のステータスが出荷済みで停滞している状況が確認されました。この事象は、大規模セール開始直前に発生し、原因としてステータスマッピング表の更新漏れが考えられます。影響は単一店舗に限定されており、迅速な修正作業が必要です。今後、このような事象を防ぐための対策が求められます。', '本障害の調査を進めた結果、配送連携のステータスが出荷済みで停滞している状況が確認されました。この事象は、大規模セール開始直前に発生し、原因としてステータスマッピング表の更新漏れが考えられます。影響は単一店舗に限定されており、迅速な修正作業が必要です。今後、このような事象を防ぐための対策が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-14T08:39:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00960', 'INC-2020-00650', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T08:54:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T09:54:46+09:00', '【初期対応】【CLU-07】配送連携ステータス停滞', '本障害に対する初期対応として、運用部の運用 一郎が中心となり、ステータスマッピング表の内容を確認し、必要な修正を行うことを決定いたしました。また、ステータスが出荷済みで停滞した原因を究明し、再発防止策を講じることが求められます。初動として、関連するチームへの情報共有も行い、今後の対応を明確にして参ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00961', 'INC-2020-00650', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-13T10:24:46+09:00', TIMESTAMP WITH TIME ZONE '2020-04-13T11:24:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00651', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-18T03:57:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T04:12:16+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2020年4月18日03時57分、株式会社ストッククラウドにおいて、運用コンソールにて同一アラートが短時間に数百件発報する事象が発生しました。これは大規模セール開始直前のタイミングで発生したため、運用部門において監視・可用性障害が発生したと考えられます。問題の発生は運用 一郎（運用部）によって確認され、04時17分に検知されました。発報されたアラートは運用コンソールのアラートマネージャに関連しており、抑制ルールの未設定が原因として疑われています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00651', 'INC-2020-00651', '本事象の調査結果として、アラート抑制ルールの未設定が根本原因であることが確認されました。大規模セール開始に伴い、過剰なアラートが発報され、運用部門はその影響でアラート疲労に陥りました。今後はこのような事態を防ぐために、事前に適切なアラート設定を行う必要があります。また、運用コンソールの監視体制を見直すことが求められます。', '本事象の調査結果として、アラート抑制ルールの未設定が根本原因であることが確認されました。大規模セール開始に伴い、過剰なアラートが発報され、運用部門はその影響でアラート疲労に陥りました。今後はこのような事態を防ぐために、事前に適切なアラート設定を行う必要があります。また、運用コンソールの監視体制を見直すことが求められます。', TIMESTAMP WITH TIME ZONE '2020-04-19T04:12:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00962', 'INC-2020-00651', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T04:27:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T05:27:16+09:00', '【対応ログ】【監視・可用性障害】アラート疲労に関する初期対応', '初期対応として、運用部門は直ちにアラート抑制ルールの設定を行い、発報の監視を強化しました。運用 一郎が中心となり、問題の収束を図るための会議を開催し、関係者への周知徹底を行いました。また、同様の事象が再発しないよう、運用コンソールの設定を見直す計画を立てています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00653', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-07-11T13:29:26+09:00', TIMESTAMP WITH TIME ZONE '2020-07-11T13:44:26+09:00', '【障害報告】【CLU-10】ヘルスチェック過負荷', '2023-10-01T10:15:00+09:00に、株式会社ストッククラウドの運用コンソールにおいて、ヘルスチェック過多でAPサーバー負荷増の事象が発生しました。顧客には架空食品店Aと架空食品店Bが含まれ、全テナントに波及する可能性があります。発見者は運用 一郎（運用部）で、発生の原因としてLBヘルスチェック間隔の過短設定が考えられています。この問題は、インフラメンテナンス明けに発生しました。エラーコードはMON-06-00653です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00653', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00653', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00653', 'INC-2020-00653', '運用 一郎（運用部）によると、インフラメンテナンス明けにヘルスチェックが過多になり、APサーバーに負荷がかかる事象が確認されました。特にLBヘルスチェック間隔が短すぎる設定になっていることが原因として疑われています。今後、設定の見直しと、ヘルスチェックの監視を強化することが必要です。', '運用 一郎（運用部）によると、インフラメンテナンス明けにヘルスチェックが過多になり、APサーバーに負荷がかかる事象が確認されました。特にLBヘルスチェック間隔が短すぎる設定になっていることが原因として疑われています。今後、設定の見直しと、ヘルスチェックの監視を強化することが必要です。', TIMESTAMP WITH TIME ZONE '2020-07-12T13:44:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00965', 'INC-2020-00653', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-11T13:59:26+09:00', TIMESTAMP WITH TIME ZONE '2020-07-11T14:59:26+09:00', '【初動対応】【CLU-10】ヘルスチェック過負荷の初動対応', '運用 一郎（運用部）より、現在の状況を把握し次第、LBヘルスチェックの設定を見直し、過負荷の状況を改善するための対策を講じます。また、全テナントへの影響を考慮し、早急に通知を行い、顧客への説明を準備します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00966', 'INC-2020-00653', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-11T15:29:26+09:00', TIMESTAMP WITH TIME ZONE '2020-07-11T16:29:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00654', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-24T12:08:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T12:38:25+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2023-10-08T14:15:00+09:00、株式会社ストッククラウドのMercuryサービスにおいて、整合性チェックで不一致アラートが多発しました。夜間に実施された整合性チェックにおいて、データの不一致が検出されました。この問題は月末棚卸の開始時に発生しており、特にバッチ処理に影響を与えています。オンラインサービスには影響がありませんが、内部のデータ同期において重大な問題となっています。エラーコードはSYNC-06-00654です。今後、整合性チェック基準の見直しを速やかに行う必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00654', 'INC-2020-00654', '調査の結果、月末棚卸の開始時に夜間整合性チェックで不一致アラートが多発していることが確認されました。原因として、整合性チェック基準の変更が未反映であることが推定されます。この問題が発生した背景には、基準変更の手続きが不十分だった可能性があります。今後、基準変更の即時反映を行う体制を整える必要があります。', '調査の結果、月末棚卸の開始時に夜間整合性チェックで不一致アラートが多発していることが確認されました。原因として、整合性チェック基準の変更が未反映であることが推定されます。この問題が発生した背景には、基準変更の手続きが不十分だった可能性があります。今後、基準変更の即時反映を行う体制を整える必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-25T12:38:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00967', 'INC-2020-00654', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T12:53:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T13:53:25+09:00', '【初期対応】【データ同期・整合性障害】整合性チェックアラート初期対応', '初期対応として、整合性チェック基準の見直しを行い、未反映の内容を速やかに反映することが求められます。また、不一致の原因を特定するために関係者とのヒアリングを行い、影響範囲を確認することが必要です。さらに、今後の再発防止策として、整合性チェックの定期的な見直しが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00655', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-30T20:06:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T20:51:21+09:00', '【障害報告】【ストレージ・容量障害】ログローテ停止', '2020年5月1日 10時00分、株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れの問題が発生した。発生日時は2020年4月30日20時06分で、20時30分にはこの異常が検知された。ログローテーションが停止し、容量を圧迫する状況となった。この影響はバッチ処理のみに及び、オンラインサービスには影響がなかった。発見者は運用部の運用 一郎で、発生契機はデータ移行バッチの実行中であった。エラーコードはSTR-02-00655である。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00655', 'INC-2020-00655', '調査の結果、データ移行バッチ実行中にログローテーションが停止したことが確認された。原因として、一時ファイルの削除バッチが停止している可能性が高いと考えられる。このため、容量が圧迫され、ログローテーションが正常に機能しなかった。引き続き、関連するプロセスの監視を強化し、再発防止策を検討する必要がある。', '調査の結果、データ移行バッチ実行中にログローテーションが停止したことが確認された。原因として、一時ファイルの削除バッチが停止している可能性が高いと考えられる。このため、容量が圧迫され、ログローテーションが正常に機能しなかった。引き続き、関連するプロセスの監視を強化し、再発防止策を検討する必要がある。', TIMESTAMP WITH TIME ZONE '2020-05-01T20:51:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00968', 'INC-2020-00655', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-30T21:06:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T22:06:21+09:00', '【初期対応】【ストレージ・容量障害】ログローテ停止への初期対応', '初期対応として、運用部の運用 一郎が迅速に問題を確認し、データ移行バッチを一時停止した。さらに、一時ファイルの削除バッチを手動で再起動し、ログローテーションの再開を試みた。これにより、一時的なストレージの圧迫を軽減することができた。状況の把握とともに、長期的な解決策として、バッチ処理の改善を検討する必要がある。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00969', 'INC-2020-00655', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-30T22:36:21+09:00', TIMESTAMP WITH TIME ZONE '2020-04-30T23:36:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00656', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-09T17:47:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T18:02:31+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2023年10月5日17時30分に発生した運用者の作業ミスによるアクセス障害について報告いたします。発生時刻に運用コンソールにアクセスした際、ログに相関IDが欠落し、横断検索が不可能な状態となりました。既に確認されたところによれば、定例リリース直後のため、ログフォーマット変更のロールアウト漏れが推定されます。本障害は運用部門に限定された影響を及ぼしており、迅速な対応が求められます。また、エラーコードはMON-09-00656です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00656', 'INC-2020-00656', '本障害の調査を行ったところ、定例リリース直後に発生したことが確認されました。運用コンソールにてログに相関IDが欠落しており、横断検索が不可となっている状態です。原因として、ログフォーマット変更のロールアウト漏れが強く疑われます。影響範囲は運用部門のみであり、早急な対応が必要です。', '本障害の調査を行ったところ、定例リリース直後に発生したことが確認されました。運用コンソールにてログに相関IDが欠落しており、横断検索が不可となっている状態です。原因として、ログフォーマット変更のロールアウト漏れが強く疑われます。影響範囲は運用部門のみであり、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-10T18:02:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00970', 'INC-2020-00656', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T18:17:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T19:17:31+09:00', '【初期対応】【監視・可用性障害】ログ相関ID欠落の初期対応', '本障害に対しては、運用部門が即座に状況を確認し、ログフォーマットの変更内容を再確認しました。再発防止策として、定例リリース前のテスト環境での検証を強化することを決定しました。運用者間での情報共有も行い、類似の事象が発生しないよう努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00971', 'INC-2020-00656', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-09T19:47:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-09T20:47:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00658', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-18T12:30:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T13:00:11+09:00', '【障害報告】【CLU-09】クロスリージョンレプリケーション', '2023-10-01T14:00:00+09:00 に、株式会社ストッククラウドの Mercury サービスにおいて、クロスリージョン複製が片系のみ更新される事象が発生しました。事象発生の原因として、リージョンルーティングの誤設定が疑われています。この影響により、特定リージョンのユーザーのデータ同期に障害が生じ、在庫登録が失敗しました。エラーコードは SYNC-07-00658 です。発生契機はインフラメンテナンス明けであり、影響を受けたコンポーネントは Mercury AWS AP（ゾーンA）およびレプリケーションゲートウェイです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00658', 'INC-2020-00658', '本事象について調査を行った結果、インフラメンテナンス明けにおいて、クロスリージョン複製が片系のみ更新されていることが確認されました。特にリージョンルーティングの誤設定が原因として考えられ、影響範囲としては特定リージョンのユーザーに限定されていることが明らかになりました。今後はこの問題の解決に向けた対応が必要です。', '本事象について調査を行った結果、インフラメンテナンス明けにおいて、クロスリージョン複製が片系のみ更新されていることが確認されました。特にリージョンルーティングの誤設定が原因として考えられ、影響範囲としては特定リージョンのユーザーに限定されていることが明らかになりました。今後はこの問題の解決に向けた対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-19T13:00:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00973', 'INC-2020-00658', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-18T13:15:11+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T14:15:11+09:00', '初期対応', '初期対応として、運用部の運用 一郎がこの事象に対処するために迅速に調査を開始しました。リージョンルーティングの設定を確認し、不具合の修正を行う計画を立てています。また、ユーザーへの影響を最小限に抑えるため、緊急メンテナンスを実施する予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00659', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-29T05:09:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T06:09:52+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '2020年5月15日 08:15:30、株式会社ストッククラウドにおいて、顧客拠点ネットワークに関するDNSキャッシュの古い情報が返され続ける事象が発生しました。影響を受けたのは単一店舗で、DNSリゾルバが旧IPアドレスを返すため、顧客がサービスにアクセスできない状況となりました。この問題は定例リリース直後に発生し、DNS TTL設定とキャッシュ方針の不一致が原因であると推定されます。エラーコードはNW-08-00659です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00659', 'INC-2020-00659', '顧客拠点NWでのDNSキャッシュ不具合について調査を行いました。定例リリース直後に問題が発生したことから、リリース内容とDNS設定の整合性を確認しました。DNS TTL設定が実際のキャッシュ方針と一致しておらず、旧IPがキャッシュされ続けていることが確認されました。このことが原因となり、顧客がサービス利用に影響を受けました。', '顧客拠点NWでのDNSキャッシュ不具合について調査を行いました。定例リリース直後に問題が発生したことから、リリース内容とDNS設定の整合性を確認しました。DNS TTL設定が実際のキャッシュ方針と一致しておらず、旧IPがキャッシュされ続けていることが確認されました。このことが原因となり、顧客がサービス利用に影響を受けました。', TIMESTAMP WITH TIME ZONE '2020-04-30T06:09:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00974', 'INC-2020-00659', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-29T06:24:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T07:24:52+09:00', '【初動対応】顧客ネットワーク障害', '問題の発生を受け、即座に初動対応を開始しました。DNS設定の見直しを行い、TTLの値を適切に修正することで、キャッシュの情報を更新しました。また、顧客へ状況を連絡し、影響を受けた範囲について説明を行いました。今後同様の問題が発生しないよう、設定の見直しとリリース前の確認プロセスを強化する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00660', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-20T12:24:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T13:24:44+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2023-10-10T10:00:00+09:00に発生した、株式会社ストッククラウドの顧客ネットワークに関する障害について報告します。顧客固定IP変更が許可リストに未反映となり、2023-10-10T10:30:00+09:00に営業部の花子が問題を発見しました。この障害は、特定の顧客拠点NWにおいて発生し、単一店舗に影響を及ぼしています。発生契機は顧客オンボーディング当日であり、推定原因としてはIP許可リストの更新漏れが考えられます。具体的には、顧客オンボーディング当日に顧客固定IP変更が許可リストに登録されていないため、ネットワーク接続に問題が生じています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00660', 'INC-2020-00660', '今回の顧客ネットワーク障害に関する調査を行いました。営業部の花子が発見した時点で、既に顧客の固定IP変更が許可リストに反映されていないことが確認されました。調査の結果、IP許可リストの更新が漏れていたことが主要な原因であると考えられます。現在、影響を受けている顧客に対して、速やかに許可リストの更新作業を行う必要があります。', '今回の顧客ネットワーク障害に関する調査を行いました。営業部の花子が発見した時点で、既に顧客の固定IP変更が許可リストに反映されていないことが確認されました。調査の結果、IP許可リストの更新が漏れていたことが主要な原因であると考えられます。現在、影響を受けている顧客に対して、速やかに許可リストの更新作業を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-21T13:24:44+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00975', 'INC-2020-00660', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T13:39:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T14:39:44+09:00', '【初期対応】【顧客ネットワーク障害】固定IP変更未連絡', '2023-10-10T10:15:00+09:00に、営業部の花子が顧客ネットワーク障害に関する報告を受け、初期対応を開始しました。最初に顧客の固定IP変更が許可リストに反映されていないことを確認し、迅速に許可リストの修正を行う指示を出しました。また、関係者に対して状況を共有し、今後の再発防止策を検討するように依頼しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00976', 'INC-2020-00660', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T15:09:44+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T16:09:44+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00664', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-08T10:37:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T11:07:37+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2020年4月8日10時37分37秒に、株式会社ストッククラウドのMercuryサービスにおいて、在庫マスター設定ミスによる在庫登録失敗が発生しました。発見者は運用部の運用 一郎で、顧客には影響がありませんでした。具体的には、データ移行バッチ実行中に在庫CSVの3行目以降が取込されず、JANコード重複チェックの誤設定が推定原因と考えられます。影響範囲はバッチ処理のみで、オンラインには影響がありません。エラーコードはMST-03-00664です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00664', 'INC-2020-00664', '調査の結果、データ移行バッチ実行中に在庫CSVの3行目以降が取込されない事象が確認されました。JANコード重複チェックの設定が誤っており、そのために取込が阻害されていることが明らかとなりました。今後は設定を見直し、再発防止策を講じる必要があります。', '調査の結果、データ移行バッチ実行中に在庫CSVの3行目以降が取込されない事象が確認されました。JANコード重複チェックの設定が誤っており、そのために取込が阻害されていることが明らかとなりました。今後は設定を見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-09T11:07:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00981', 'INC-2020-00664', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T11:22:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T12:22:37+09:00', '【初期対応】【在庫マスター設定障害】CSVバッチ取込欠損', '初期対応として、運用部の運用 一郎がバッチ処理を一時停止し、設定の見直しを開始しました。また、影響範囲を確認し、必要に応じて顧客への情報提供を準備しました。エラーコードMST-03-00664についての詳細も収集し、次のステップに備えています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00982', 'INC-2020-00664', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T12:52:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T13:52:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00667', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-07-08T12:08:40+09:00', TIMESTAMP WITH TIME ZONE '2020-07-08T13:08:40+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2020年7月9日、架空食品店Aで顧客側ネットワーク障害が発生しました。症状として、顧客固定IP変更が許可リストに未反映との報告がありました。発生時刻はおおよそ12時08分で、検知が行われたのは12時57分、約49分の遅延がありました。影響範囲は単一店舗のみで、顧客拠点NW（ゾーンA）及び顧客側FWに問題が発生しています。発見者は営業部の花子です。推定原因としては、IP許可リストの更新漏れが挙げられています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00667', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00667', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00667', 'INC-2020-00667', '調査の結果、顧客オンボーディング当日において、架空食品店Aの固定IP変更が許可リストに未反映であったことが確認されました。これにより、顧客側ネットワークにアクセスできない状態が生じました。今後、同様の事象を防ぐためには、IP許可リストの更新手続きの見直しが必要です。また、顧客との連携を強化し、変更点についての通知を徹底することが求められます。', '調査の結果、顧客オンボーディング当日において、架空食品店Aの固定IP変更が許可リストに未反映であったことが確認されました。これにより、顧客側ネットワークにアクセスできない状態が生じました。今後、同様の事象を防ぐためには、IP許可リストの更新手続きの見直しが必要です。また、顧客との連携を強化し、変更点についての通知を徹底することが求められます。', TIMESTAMP WITH TIME ZONE '2020-07-09T13:08:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00986', 'INC-2020-00667', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-07-08T13:23:40+09:00', TIMESTAMP WITH TIME ZONE '2020-07-08T14:23:40+09:00', '【初期対応】【顧客ネットワーク障害】固定IP変更未連絡', '2020年7月9日、営業部の花子から架空食品店Aにおけるネットワーク障害の報告を受けました。固定IP変更が許可リストに未反映となっていることが原因と考えられるため、即座にIP許可リストの確認作業を開始しました。顧客に対しては、状況の説明と今後の対応について連絡を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00987', 'INC-2020-00667', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-07-08T14:53:40+09:00', TIMESTAMP WITH TIME ZONE '2020-07-08T15:53:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00669', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-12-14T06:36:52+09:00', TIMESTAMP WITH TIME ZONE '2020-12-14T07:06:52+09:00', '【障害報告】【API連携・EDI障害】配送連携ステータス停滞', '2020年12月14日06時36分52秒に、株式会社ストッククラウドが提供するMercuryにおいて、架空食品店Bにおける配送連携のステータスが出荷済みで停滞している事象が発生しました。この障害は、2020年12月14日06時57分52秒に検知され、約21分間の放置が確認されました。推定原因として、ステータスマッピング表の更新漏れが考えられます。本障害は、単一店舗にのみ影響を及ぼしており、エラーコードはEDI-09-00669です。大規模セール開始直前という発生契機も相まって、緊急対応が求められました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00669', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00669', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00669', 'INC-2020-00669', '本障害に関する調査を行ったところ、配送連携のステータスが出荷済みで停滞している状態が確認されました。この現象は、Mercury AWS APおよび配送連携アダプタに関連しており、影響範囲は架空食品店Bに限られています。技術的な分析の結果、ステータスマッピング表の更新漏れが根本原因となっている可能性が高いと判断されました。', '本障害に関する調査を行ったところ、配送連携のステータスが出荷済みで停滞している状態が確認されました。この現象は、Mercury AWS APおよび配送連携アダプタに関連しており、影響範囲は架空食品店Bに限られています。技術的な分析の結果、ステータスマッピング表の更新漏れが根本原因となっている可能性が高いと判断されました。', TIMESTAMP WITH TIME ZONE '2020-12-15T07:06:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00990', 'INC-2020-00669', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-12-14T07:21:52+09:00', TIMESTAMP WITH TIME ZONE '2020-12-14T08:21:52+09:00', '【初期対応】配送連携ステータス停滞', '初期対応として、運用部の運用一郎が主導し、ステータスマッピング表の確認を行いました。更新漏れが確認されたため、即座に修正を実施し、その後、配送連携のステータスを正常に戻すことができました。影響を受けた顧客へは、障害発生の報告と現在の状況を説明し、信頼回復に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00671', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-25T18:15:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T18:45:54+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2020年4月25日18時15分54秒に、株式会社ストッククラウドのMercuryにおいてマスター設定ミスによる在庫登録失敗が発生しました。症状はバルクAPIが部分失敗しロールバックが未完了であることです。この影響により、サービス全体の一部機能が利用できなくなり、顧客に影響を及ぼしました。エラーコードはEDI-10-00671であり、発生契機はデータ移行バッチの実行中でした。発見者は運用部の運用 一郎です。この問題は2020年4月25日18時32分54秒に検知され、検知までに17分を要しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00671', 'INC-2020-00671', '調査の結果、バルクAPIが部分失敗した原因は、部分成功時の補償トランザクションが欠如していたことに起因する可能性が高いと判断されました。データ移行バッチの実行中に発生したこの問題により、ロールバックが未完了となり、結果として在庫登録が失敗しました。今後、同様の問題が発生しないよう、補償トランザクションの適切な実装を確認する必要があります。', '調査の結果、バルクAPIが部分失敗した原因は、部分成功時の補償トランザクションが欠如していたことに起因する可能性が高いと判断されました。データ移行バッチの実行中に発生したこの問題により、ロールバックが未完了となり、結果として在庫登録が失敗しました。今後、同様の問題が発生しないよう、補償トランザクションの適切な実装を確認する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-26T18:45:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00993', 'INC-2020-00671', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T19:00:54+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T20:00:54+09:00', '初期対応', '初期対応として、影響を受けたバルクAPIの状態を確認し、すぐにロールバック処理を試みました。また、データ移行バッチの実行状況を詳細に調査し、他の機能への影響を最小限に抑えるための措置を講じました。今後は、同様の問題を未然に防ぐため、定期的なシステムチェックを実施することが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00674', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-11T01:06:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T03:06:02+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023年10月01日01時06分02秒に、株式会社ストッククラウドのサービスMercuryにおいて、定例リリース直後にマスター更新と在庫が二重反映される事象が発生しました。検知は2023年10月01日01時46分02秒に行われ、発見者は営業部の花子です。本事象により、同一顧客の全店舗に影響が及び、エラーコードSYNC-01-00674が記録されました。影響を受けたコンポーネントは顧客店舗POS（Secondary）およびイベントバスであり、事象の発生は定例リリース直後に集中しています。このような二重反映は、データ同期・整合性における重大な問題を示唆しています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00674', 'INC-2020-00674', '調査の結果、マスター更新と在庫の二重反映が確認されました。これは、イベント順序の逆転配信が原因であると推定されます。特に、定例リリース直後に発生したことから、リリース後の処理フローにおける手続きの見直しが必要です。今後の影響を最小限に抑えるためには、イベントの配信順序を厳密に管理する必要があります。', '調査の結果、マスター更新と在庫の二重反映が確認されました。これは、イベント順序の逆転配信が原因であると推定されます。特に、定例リリース直後に発生したことから、リリース後の処理フローにおける手続きの見直しが必要です。今後の影響を最小限に抑えるためには、イベントの配信順序を厳密に管理する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-12T03:06:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00997', 'INC-2020-00674', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-11T03:21:02+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T04:21:02+09:00', '【初期対応】データ同期・整合性障害の初期対応', '初期対応として、全店舗の在庫データの整合性を確認し、二重反映の影響を受けたデータを修正しました。また、関連するエンジニアチームと連携して、イベント順序の管理を強化するための改善策を検討しております。影響範囲を把握し、迅速な対応に努めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00678', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-19T06:31:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T07:01:45+09:00', '【障害報告】【認証・セッション障害】パスワードポリシー衝突', '2023年10月15日、株式会社ストッククラウドのサービスMercuryにおいて、定例リリース直後に新パスワードポリシーの適用に伴い、既存API認証が失敗する事象が発生しました。この影響により、全テナントにおいて認証失敗の報告が相次ぎ、サービス利用に支障をきたしました。症状としては、新パスワードポリシーにより、レガシー認証方式を活用しているユーザーが認証を通過できない状態となりました。エラーコードはAUTH-05-00678であり、現在影響を受けるコンポーネントはVenus Azure APの認証サービスです。障害発生から検知までの時間は約32分であり、問題の早急な解決が求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00678', 'INC-2020-00678', '本事象に関する調査を行った結果、定例リリース直後に適用された新パスワードポリシーが、レガシー認証方式に依存している既存のAPI認証に影響を及ぼしていることが確認されました。これにより、ユーザーが新しいポリシーに準拠したパスワードを設定していない場合、認証に失敗する状況が発生しています。影響範囲は全テナントに及び、迅速な対応が必要です。', '本事象に関する調査を行った結果、定例リリース直後に適用された新パスワードポリシーが、レガシー認証方式に依存している既存のAPI認証に影響を及ぼしていることが確認されました。これにより、ユーザーが新しいポリシーに準拠したパスワードを設定していない場合、認証に失敗する状況が発生しています。影響範囲は全テナントに及び、迅速な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-20T07:01:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01002', 'INC-2020-00678', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T07:16:45+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T08:16:45+09:00', '【対応ログ】【認証・セッション障害】初動対応記録', '2023年10月15日、運用部の運用 一郎がこの障害を初めて確認し、速やかに該当の問題をエスカレーションしました。対応チームは直ちに調査を開始し、影響範囲の特定と問題の早期解決に向けた対策を検討しています。ユーザーに対しては、認証失敗の事象について通知し、引き続き状況を監視しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00680', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-05T17:13:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T19:13:07+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2023-10-10T14:00:00+09:00 株式会社ストッククラウドにて、POS連携の売上が翌営業日まで在庫に反映されない事象が発生しました。この影響は単一店舗に限定されており、エラーコードは INV-02-00680 です。発生契機は年末年始の稼働切替時であり、前日締め処理の二重実行が推定されます。営業部の花子が発見し、2023-10-10T16:30:00+09:00 に検知されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00680', 'INC-2020-00680', '発生した不具合について調査した結果、年末年始の稼働切替時において、POS連携の売上が翌営業日まで在庫に反映されないことが確認されました。原因として前日締め処理の二重実行が疑われています。このため、詳細なログ調査を実施し、再発防止策を講じる必要があります。', '発生した不具合について調査した結果、年末年始の稼働切替時において、POS連携の売上が翌営業日まで在庫に反映されないことが確認されました。原因として前日締め処理の二重実行が疑われています。このため、詳細なログ調査を実施し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-06T19:13:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01005', 'INC-2020-00680', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T19:28:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T20:28:07+09:00', '初期対応', '2023-10-10T14:30:00+09:00 に初期対応を開始し、影響を受けた店舗の状況を確認しました。POSシステムの状態を点検し、必要に応じて手動で在庫を更新しました。引き続き、締め処理のプロセスを確認し、二重実行を防ぐための改善策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01006', 'INC-2020-00680', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T20:58:07+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T21:58:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00681', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-05T08:17:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T09:02:37+09:00', '【障害報告】【ストレージ・容量障害】オブジェクトライフサイクル誤り', '2023-10-10T09:00:00+09:00に株式会社ストッククラウドのサービスMercuryにおいてストレージ溢れが発生しました。以下の観点から詳細をお伝えします。
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00681', 'INC-2020-00681', '発生したストレージ溢れに関して、初期の調査を行いました。
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01007', 'INC-2020-00681', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-05T09:17:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T10:17:37+09:00', '初期対応', '現在、運用部の運用 一郎がこのインシデントの対応を行っています。ライフサイクルポリシーの適用状況を確認するため、必要なデータの収集を開始しました。また、影響を受けるサービス機能の範囲を特定し、ユーザーへの影響を最小限に抑えるための対応策を検討中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00683', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-10T10:46:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T11:31:53+09:00', '【障害報告】【監視・可用性障害】合成監視失敗', '2023-10-15 14:30:00に発生したストレージ溢れに関するインシデントです。合成監視が特定ステップで失敗しました。検知は2023-10-15 14:55:00で、検知までに25分かかりました。影響範囲はサービス全体の一部機能に及び、エラーコードはMON-08-00683です。発生契機として、定例リリース直後に合成監視が失敗したことが確認されています。原因としてはテストデータの期限切れが疑われます。影響コンポーネントにはMercury AWS Storage（DRサイト）および合成監視ランナーが含まれます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00683', 'INC-2020-00683', 'インシデントの調査を行った結果、合成監視が詳細なステップで失敗したことが判明しました。この事象は定例リリース直後に発生し、テストデータの管理が不十分であったことが原因とされます。具体的なステップ失敗については、ログの確認を通じて特定のテストデータが期限切れであったことが分かりました。今後の対応として、テストデータの更新管理を強化する必要があります。', 'インシデントの調査を行った結果、合成監視が詳細なステップで失敗したことが判明しました。この事象は定例リリース直後に発生し、テストデータの管理が不十分であったことが原因とされます。具体的なステップ失敗については、ログの確認を通じて特定のテストデータが期限切れであったことが分かりました。今後の対応として、テストデータの更新管理を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T11:31:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01010', 'INC-2020-00683', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T11:46:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T12:46:53+09:00', '【初期対応】【監視・可用性障害】合成監視失敗に対する初期対応', 'インシデント発生後、運用部の運用 一郎が即座に対応を開始しました。合成監視の設定およびテストデータの状況を確認し、期限切れのテストデータを更新する作業を進めました。また、影響を受けた部分についてはサービスの安定稼働を確保するため、迅速な修正を行いました。今後は合成監視の定期的な確認も実施し、再発防止に向けた対策を強化する意向です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01011', 'INC-2020-00683', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T13:16:53+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T14:16:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00684', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-10T23:36:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T23:51:49+09:00', '【障害報告】【CLU-08】MFAデバイス不一致', '・発生日時: 2023-10-05T14:30:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00684', 'INC-2020-00684', '2023-10-05に発生したMFAデバイス不一致の障害について調査を行った。顧客オンボーディング時に、運用コンソールにてMFAデバイスが登録されていないことが判明した。MFAシードの再発行と登録が未同期であったために、正しいデバイスが認識されなかったと考えられる。現在、早急にMFAデバイスの再登録を進めている。', '2023-10-05に発生したMFAデバイス不一致の障害について調査を行った。顧客オンボーディング時に、運用コンソールにてMFAデバイスが登録されていないことが判明した。MFAシードの再発行と登録が未同期であったために、正しいデバイスが認識されなかったと考えられる。現在、早急にMFAデバイスの再登録を進めている。', TIMESTAMP WITH TIME ZONE '2020-04-11T23:51:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01012', 'INC-2020-00684', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T00:06:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T01:06:49+09:00', '初期対応', '・運用チームは障害発生直後に、MFAデバイスの登録状況を確認。・顧客対応のため、迅速にMFAデバイス再登録の手続きを開始。・影響を受けた顧客に対し、状況説明と今後の対応について連絡を行った。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01013', 'INC-2020-00684', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T01:36:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T02:36:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00685', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-22T07:49:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T08:19:34+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2020年4月22日07時49分34秒、株式会社ストッククラウドのサービスMercuryにて、単一店舗のWebhook再送が嵐状になり、先方で拒否される事象が発生しました。発見者は運用部の運用 一郎で、定例リリース直後に発生したため、再送間隔の指数バックオフ未設定が推定原因と考えられます。影響範囲はMercury AWS APのWebhookディスパッチャであり、エラーコードはEDI-02-00685です。26分後に検知され、顧客からの影響報告はありません。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00685', 'INC-2020-00685', '定例リリース直後にWebhook再送が頻発したことが確認されました。再送間隔の指数バックオフが未設定であることが原因と判断され、API連携・EDI障害が影響を及ぼしました。調査を通じて、Webhookの設定ミスが特定され、システム全体に及ぼす影響を考慮する必要があります。', '定例リリース直後にWebhook再送が頻発したことが確認されました。再送間隔の指数バックオフが未設定であることが原因と判断され、API連携・EDI障害が影響を及ぼしました。調査を通じて、Webhookの設定ミスが特定され、システム全体に及ぼす影響を考慮する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-23T08:19:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01014', 'INC-2020-00685', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-22T08:34:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-22T09:34:34+09:00', '初期対応', '運用部は事態の把握後、直ちに再送間隔の設定確認を行い、適切なバックオフ設定を推奨しました。また、必要に応じてAPI連携の設定を見直し、今後の障害を未然に防ぐための手続きを検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00686', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-05T10:53:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T11:53:16+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '・発生日時: 2020-10-10T11:00:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00686', 'INC-2020-00686', '調査を行った結果、顧客名A において発生したDNSキャッシュの問題が確認されました。定例リリース直後に、店舗DNSキャッシュが旧IPを返している症状が発生し、DNS TTL設定とキャッシュ方針に不一致が見られました。このため、DNS設定の見直しが必要であると考えられます。', '調査を行った結果、顧客名A において発生したDNSキャッシュの問題が確認されました。定例リリース直後に、店舗DNSキャッシュが旧IPを返している症状が発生し、DNS TTL設定とキャッシュ方針に不一致が見られました。このため、DNS設定の見直しが必要であると考えられます。', TIMESTAMP WITH TIME ZONE '2020-04-06T11:53:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01015', 'INC-2020-00686', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T12:08:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T13:08:16+09:00', '初期対応', '顧客名A からの連絡を受け、直ちに状況を把握するための確認を行いました。DNSキャッシュが旧IPを返すという報告を受け、責任者として調査を開始しました。顧客拠点NWのDNSリゾルバの設定を確認し、TTL設定の見直しを提案しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01016', 'INC-2020-00686', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-05T13:38:16+09:00', TIMESTAMP WITH TIME ZONE '2020-04-05T14:38:16+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00687', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-21T18:05:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T20:05:17+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '・2023-10-05T14:30:00+09:00に、株式会社ストッククラウドの顧客店舗POSでEDI経由の棚卸ファイル取込において、件数不一致が発生しました。
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00687', 'INC-2020-00687', '・調査を開始したところ、データ移行バッチ実行中にEDI経由の棚卸ファイル取込で件数不一致が確認されました。
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01017', 'INC-2020-00687', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T20:20:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T21:20:17+09:00', '【初期対応】【棚卸・POS突合障害】EDI棚卸ファイル異常', '・初動対応を行い、問題の影響範囲を確認しました。バッチ処理のみに影響があり、オンラインサービスは正常です。
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01018', 'INC-2020-00687', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-21T21:50:17+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T22:50:17+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00688', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-05-21T04:55:39+09:00', TIMESTAMP WITH TIME ZONE '2020-05-21T05:55:39+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2020年5月21日04時55分39秒に、株式会社ストッククラウドが提供するMercuryの顧客拠点NWにおいて、架空食品店Aに対するSD-WANの経路選択に誤りが見られ、結果として遅延が増大しました。特に、大規模セール開始直前にこの障害が発生し、同一顧客の全店舗に影響を及ぼしました。検知が行われたのは発生から46分後の5時41分39秒であり、遅延によって顧客の業務に支障を来しました。推定される原因はSD-WANポリシーの閾値設定誤りで、技術的な詳細として、劣化した回線が選択されたことが指摘されます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00688', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00688', 'INC-2020-00688', '調査の結果、SD-WANが劣化した回線を選択したことが遅延の原因であることが確認されました。これは大規模セール開始直前のタイミングで発生したため、顧客への影響が大きくなりました。SD-WANのポリシーにおける閾値設定が不適切であったことが問題の核心であり、今後は設定の見直しが必要です。', '調査の結果、SD-WANが劣化した回線を選択したことが遅延の原因であることが確認されました。これは大規模セール開始直前のタイミングで発生したため、顧客への影響が大きくなりました。SD-WANのポリシーにおける閾値設定が不適切であったことが問題の核心であり、今後は設定の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2020-05-22T05:55:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01019', 'INC-2020-00688', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-05-21T06:10:39+09:00', TIMESTAMP WITH TIME ZONE '2020-05-21T07:10:39+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤りへの初期対応', '発生を受け、営業部の花子が迅速に状況を確認し、顧客に対して遅延の原因調査を開始しました。障害の影響を最小化するため、SD-WANの設定を確認し、必要に応じて手動で経路を切り替える対応を行いました。また、影響を受ける店舗への連絡を行い、改善策の検討を始めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01020', 'INC-2020-00688', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-05-21T07:40:39+09:00', TIMESTAMP WITH TIME ZONE '2020-05-21T08:40:39+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00689', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-27T01:38:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T01:53:15+09:00', '【障害報告】【CLU-08】JWT署名鍵ローテ漏れ', '2023-10-01T09:00:00+09:00に株式会社ストッククラウドの運用コンソールにおいて、JWT署名鍵ローテ後に旧トークン検証失敗の事象が発生しました。発見者は運用 一郎(運用部)で、2023-10-01T09:13:00+09:00にこの事象を検知しました。インフラメンテナンス明けに発生したこの問題は、全テナントに波及する影響がありました。エラーコードはAUTH-07-00689です。推定原因としては、鍵ローテの段階的切替未実施が考えられます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00689', 'INC-2020-00689', '運用コンソールにおけるJWT署名鍵ローテ後に旧トークン検証失敗の原因を調査しました。インフラメンテナンス明けに発生したこの障害は、全テナントに影響を及ぼしました。鍵ローテの段階的切替が未実施であったことが、推定原因として挙げられます。技術的には、JWT署名鍵のローテーション処理に問題があったと考えられます。', '運用コンソールにおけるJWT署名鍵ローテ後に旧トークン検証失敗の原因を調査しました。インフラメンテナンス明けに発生したこの障害は、全テナントに影響を及ぼしました。鍵ローテの段階的切替が未実施であったことが、推定原因として挙げられます。技術的には、JWT署名鍵のローテーション処理に問題があったと考えられます。', TIMESTAMP WITH TIME ZONE '2020-04-28T01:53:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01021', 'INC-2020-00689', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-27T02:08:15+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T03:08:15+09:00', '【初動対応】【CLU-08】JWT署名鍵ローテ漏れ', 'インシデント発生後、運用 一郎(運用部)チームは直ちに影響範囲の特定に着手しました。旧トークンが検証に失敗しているため、全テナントへの影響を防ぐために、既存のJWT署名鍵を一時的に再利用する手順を実施しました。また、鍵ローテの段階的切替が未実施であったことを確認し、早急にシステムの修正を行う計画を立てました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00691', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-17T19:01:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T19:31:10+09:00', '【障害報告】【CLU-06】オートスケール遅延', '2023-10-10T14:01:10+09:00に発生した株式会社ストッククラウドのMercuryサービスにおいて、オートスケールが間に合わず応答劣化が確認されました。発見者である運用 一郎が19:25:10にこの事象を検知し、影響範囲は全テナントに波及しました。大規模セール開始直前のタイミングであったため、スケールアウト閾値の設定遅延が推定されます。この問題により、Venus Azure AP（ゾーンA）のAPサーバークラスタにおいて性能・負荷障害が発生しました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00691', 'INC-2020-00691', '本事象の調査において、オートスケールの機能不全が確認されました。特にスケールアウト閾値の設定遅延が問題の根源であると考えられ、これにより応答劣化が引き起こされました。大規模セール開始直前という要因が、さらなる影響を悪化させました。今後は、スケールアウト設定の監視を強化し、事前に検知する仕組みを導入する必要があります。', '本事象の調査において、オートスケールの機能不全が確認されました。特にスケールアウト閾値の設定遅延が問題の根源であると考えられ、これにより応答劣化が引き起こされました。大規模セール開始直前という要因が、さらなる影響を悪化させました。今後は、スケールアウト設定の監視を強化し、事前に検知する仕組みを導入する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-18T19:31:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01023', 'INC-2020-00691', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T19:46:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T20:46:10+09:00', '【初期対応】【CLU-06】オートスケール遅延', '運用 一郎が最初に障害を検知後、直ちに技術チームに通知を行い、状況確認を開始しました。オートスケールの設定状況をチェックし、スケールアウト閾値が適切に設定されていないことを確認しました。その後、緊急対応として設定の見直しを実施し、システムの応答性を回復させるための手順を踏みました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01024', 'INC-2020-00691', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-17T21:16:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-17T22:16:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00692', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-14T12:53:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T13:23:37+09:00', '【障害報告】【CLU-08】MFAデバイス不一致', '・発生日時: 2023-10-01T12:00:00+09:00  
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00692', 'INC-2020-00692', '本件の調査を開始したところ、MFAデバイスの登録状況を確認した結果、顧客のMFAシードが再発行されていない状態であることが判明しました。このため、ログインに必要なMFAデバイスの認証情報が一致せず、ログイン不可の状態が発生しました。今後の対応として、MFAシードの再発行を適切に行い、システムの同期を図る必要があります。', '本件の調査を開始したところ、MFAデバイスの登録状況を確認した結果、顧客のMFAシードが再発行されていない状態であることが判明しました。このため、ログインに必要なMFAデバイスの認証情報が一致せず、ログイン不可の状態が発生しました。今後の対応として、MFAシードの再発行を適切に行い、システムの同期を図る必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-15T13:23:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01025', 'INC-2020-00692', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T13:38:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T14:38:37+09:00', '【対応ログ】【CLU-08】MFAデバイス不一致 - 初期対応', '顧客からのログイン不可能に関する報告を受け、迅速に対応を開始しました。問題解決のために、MFAデバイスの状態を確認し、シードの再発行を実施する手順を踏むこととしました。さらに、影響範囲の特定とログイン状況を確認し、必要に応じて顧客へのサポートを行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01026', 'INC-2020-00692', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-14T15:08:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T16:08:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00694', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-28T11:14:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T11:59:29+09:00', '【障害報告】【ストレージ・容量障害】WALアーカイブ滞留', '2020年4月28日11時14分29秒に、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れが発生いたしました。これはWALアーカイブが滞留し、ディスクを圧迫する事象であり、全テナントに波及する可能性がある重大な問題です。発生契機は定例リリース直後であり、エラーコードはSTR-08-00694です。Mercury AWS StorageのDRサイトおよびバックアップ領域への影響が確認されております。運用部の運用 一郎が発見したこの問題は、アーカイブ先のマウントポイントが枯渇していることが推定される原因です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00694', 'INC-2020-00694', '本事象に関する調査を実施した結果、定例リリース直後にWALアーカイブが滞留し、その結果、ディスクが圧迫される事態が発生しました。アーカイブ先のマウントポイントが枯渇していることが主な原因として考えられます。今後は、WALアーカイブの処理を適切に行うための対策を講じる必要があります。また、影響範囲が全テナントに及ぶため、迅速な対応が求められます。', '本事象に関する調査を実施した結果、定例リリース直後にWALアーカイブが滞留し、その結果、ディスクが圧迫される事態が発生しました。アーカイブ先のマウントポイントが枯渇していることが主な原因として考えられます。今後は、WALアーカイブの処理を適切に行うための対策を講じる必要があります。また、影響範囲が全テナントに及ぶため、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-29T11:59:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01028', 'INC-2020-00694', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T12:14:29+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T13:14:29+09:00', '初期対応', '初期対応として、運用部は直ちにWALアーカイブの状況を確認し、アーカイブ先のマウントポイントの状態を調査しました。マウントポイントの枯渇が確認されたため、緊急対策を講じ、アーカイブ処理を再開する準備を進めています。また、全テナントへの影響を最小限に抑えるため、情報共有を迅速に行い、状況を把握するよう努めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00697', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-07-10T01:53:27+09:00', TIMESTAMP WITH TIME ZONE '2020-07-10T02:23:27+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2023年10月01日11:00:00に発生した障害について報告いたします。株式会社ストッククラウドのサービスMercuryにおいて、スナップショット復元後に在庫整合が崩れる事象が発生しました。この障害は、データ移行バッチ実行中に発生し、全テナントに波及する影響を及ぼしました。復元ポイントのトランザクションログが欠落していることが推定原因として考えられます。具体的には、Mercury AWS AP（DRサイト）におけるバックアップ管理に関する問題であり、エラーコードはSYNC-09-00697です。本事象により、在庫登録が失敗する重大な影響を及ぼしました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00697', 'INC-2020-00697', '本障害に関する調査を行いました。データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れ、復元ポイントのトランザクションログが欠落していたことが確認されました。この問題は、全テナントに影響を及ぼしており、早急な対応が求められます。原因の特定と対策を講じる必要があります。', '本障害に関する調査を行いました。データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れ、復元ポイントのトランザクションログが欠落していたことが確認されました。この問題は、全テナントに影響を及ぼしており、早急な対応が求められます。原因の特定と対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-07-11T02:23:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01033', 'INC-2020-00697', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-10T02:38:27+09:00', TIMESTAMP WITH TIME ZONE '2020-07-10T03:38:27+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合', '本件に関し、初期対応としてデータ移行バッチの実行状況を確認し、スナップショット復元のプロセスを見直しました。また、復元ポイントのトランザクションログの状況を調査し、所定の手順に従って修正を行う方針です。関係者には必要な情報を共有し、影響を最小限に抑えるための対策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00698', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-26T10:57:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T12:57:52+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2023-10-10T11:00:00+09:00に発生した棚卸突合失敗のインシデントについて報告します。本インシデントは、顧客店舗POSにおいて分散トランザクションがタイムアウトし、片側のみコミットされる事象が確認されました。発生契機は大規模セールの開始直前であり、全テナントに影響を及ぼしました。エラーコードはSYNC-04-00698で、推定原因は2PCタイムアウト設定の過短です。データ同期・整合性の確保が求められる中、この障害は重要な業務の妨げとなり、今後の改善が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00698', 'INC-2020-00698', 'インシデントの調査を行った結果、発生した分散トランザクションがタイムアウトした原因として、2PCのタイムアウト設定が適切でなかったことが明らかになりました。この設定の見直しが必要であり、今後の実施においては十分な時間配分を行うことが重要であると考えます。大規模セール直前という特異な状況が影響したことも考慮し、トランザクション管理の強化を検討する必要があります。', 'インシデントの調査を行った結果、発生した分散トランザクションがタイムアウトした原因として、2PCのタイムアウト設定が適切でなかったことが明らかになりました。この設定の見直しが必要であり、今後の実施においては十分な時間配分を行うことが重要であると考えます。大規模セール直前という特異な状況が影響したことも考慮し、トランザクション管理の強化を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-27T12:57:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01034', 'INC-2020-00698', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T13:12:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T14:12:52+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウトに対する初期対応', '本インシデントに対して初期対応を実施しました。エラー発生を確認後、関連チームと連携し、トランザクションの状況をリアルタイムで監視しました。また、顧客店舗POSの状態を確認し、必要に応じて手動での対応を行い、影響を最小限に抑える努力をしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01035', 'INC-2020-00698', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T14:42:52+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T15:42:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00699', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-20T15:44:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T17:44:08+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2023年10月15日、株式会社ストッククラウドのMercuryサービスにおいて、棚卸突合失敗のインシデントが発生しました。発生時刻は15:44で、顧客店舗POSにおいてスナップショット復元後に在庫整合が崩れる事象が確認されました。この問題はデータ移行バッチ実行中に発生し、復元ポイントのトランザクションログの欠落が推定原因として考えられます。影響範囲は全テナントに波及する可能性があり、エラーコードはSYNC-09-00699です。検知時刻は17:38であり、114分後に問題が確認されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00699', 'INC-2020-00699', '本インシデントについての調査を行った結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れたことが判明しました。特に、復元ポイントのトランザクションログの欠落が主な原因として考えられ、システムの整合性に影響を及ぼしました。この事象は全テナントに影響を与えるため、早急な対応が求められます。', '本インシデントについての調査を行った結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れたことが判明しました。特に、復元ポイントのトランザクションログの欠落が主な原因として考えられ、システムの整合性に影響を及ぼしました。この事象は全テナントに影響を与えるため、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-21T17:44:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01036', 'INC-2020-00699', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-20T17:59:08+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T18:59:08+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合', '初期対応として、該当のデータ移行バッチの実行を一時停止し、スナップショットの復元プロセスを確認しました。また、復元ポイントのトランザクションログの欠落に関して調査を開始しました。この問題を解決するために、関連チームと連携し、迅速な対応を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00703', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-28T00:23:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T00:53:13+09:00', '【障害報告】【CLU-07】文字コード変換事故', '2023-10-01T15:00:00+09:00、株式会社ストッククラウドのサービスMercuryにおいて、Shift_JIS変換で商品名が文字化けする事象が発生しました。発生契機は、データ移行バッチ実行中に見られました。この障害は、単一店舗のみに影響を及ぼし、エラーコードはEDI-07-00703です。現時点での推定原因として、文字コード変換テーブルの誤選択が考えられます。最初の検知は2023-10-01T15:25:00+09:00で、検知までに25分間の差がありました。影響を受けるコンポーネントは、Mercury AWS AP（Primary）およびEDIアダプタです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00703', 'INC-2020-00703', '本事象に関する調査を行いました。データ移行バッチ実行中にShift_JIS変換が行われた際、商品名が文字化けしていることが確認されました。原因として挙げられるのは、文字コード変換テーブルの誤選択です。今後、再発防止策を講じる必要があります。影響範囲は単一店舗に限定されているため、速やかに対応が求められます。', '本事象に関する調査を行いました。データ移行バッチ実行中にShift_JIS変換が行われた際、商品名が文字化けしていることが確認されました。原因として挙げられるのは、文字コード変換テーブルの誤選択です。今後、再発防止策を講じる必要があります。影響範囲は単一店舗に限定されているため、速やかに対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-29T00:53:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01041', 'INC-2020-00703', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T01:08:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T02:08:13+09:00', '【初動対応】【CLU-07】文字コード変換事故対応', '2023-10-01T15:30:00+09:00に初動対応を開始しました。影響を受けた店舗に対して迅速に商品名の修正を行うと共に、文字コード変換に関する設定を見直しました。影響範囲が単一店舗に限られているため、迅速な対応が可能であると考えています。また、今後のデータ移行バッチでの再発防止策を検討することが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01042', 'INC-2020-00703', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-28T02:38:13+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T03:38:13+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00705', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-14T16:43:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T17:43:49+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023-10-05T10:30:00+09:00に、株式会社ストッククラウドの顧客拠点において特定拠点のみAPI呼び出しが失敗する事象が発生しました。発生した原因は、店舗LANのスイッチ故障と推定されています。影響範囲は単一店舗に限定されており、その影響により、顧客側FWや顧客拠点NW（ゾーンB）の機能が制限されています。新規店舗追加の初日に発生したこの障害により、顧客は十分なサービスを受けられない状況となりました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00705', 'INC-2020-00705', '調査の結果、特定拠点におけるAPI呼び出し失敗の原因として、店舗LANのスイッチに問題があることが確認されました。これにより、顧客ネットワークに関するサービスの品質が低下し、影響が顕著になりました。現在、スイッチの修理または交換が必要です。新規店舗の追加に伴うネットワーク設定の見直しも行う予定です。', '調査の結果、特定拠点におけるAPI呼び出し失敗の原因として、店舗LANのスイッチに問題があることが確認されました。これにより、顧客ネットワークに関するサービスの品質が低下し、影響が顕著になりました。現在、スイッチの修理または交換が必要です。新規店舗の追加に伴うネットワーク設定の見直しも行う予定です。', TIMESTAMP WITH TIME ZONE '2020-04-15T17:43:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01045', 'INC-2020-00705', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-14T17:58:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T18:58:49+09:00', '初期対応', '2023-10-05T10:40:00+09:00に、営業の花子が現場に赴きました。スイッチの確認を行い、故障が確認されました。顧客に状況を説明し、修理作業を開始しました。さらに、顧客ネットワークの安定性を確保するための暫定手続きを実施し、次の段階の対策を検討中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01046', 'INC-2020-00705', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-14T19:28:49+09:00', TIMESTAMP WITH TIME ZONE '2020-04-14T20:28:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00708', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-06T21:11:56+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T21:26:56+09:00', '【障害報告】【CLU-10】ログ相関ID欠落', '2023年10月01日14時30分、株式会社ストッククラウドの運用コンソールにおいて、ログに相関IDが欠落し、横断検索が不可能となる事象が発生しました。本件は定例リリース直後に確認され、運用部門のみが影響を受けています。発見者は運用 一郎（運用部）であり、問題発生の検知は14時41分に行われました。推定される原因は、ログフォーマット変更のロールアウト漏れであり、これにより監視・可用性障害が発生しました。エラーコードはMON-09-00708です。今後の対策として、ログフォーマット変更の影響を受ける全コンポーネントの確認が必要です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00708', 'INC-2020-00708', '本インシデントにおいては、定例リリース直後に発生したため、ログフォーマット変更の適用漏れが疑われます。運用コンソール及びログパイプラインの設定を確認した結果、相関IDが欠落した状態でログが生成されていることが明らかになりました。影響を受けるコンポーネントの特定と、ログフォーマットに関する設定を再確認する必要があります。', '本インシデントにおいては、定例リリース直後に発生したため、ログフォーマット変更の適用漏れが疑われます。運用コンソール及びログパイプラインの設定を確認した結果、相関IDが欠落した状態でログが生成されていることが明らかになりました。影響を受けるコンポーネントの特定と、ログフォーマットに関する設定を再確認する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-07T21:26:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01050', 'INC-2020-00708', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T21:41:56+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T22:41:56+09:00', '【初動対応】【CLU-10】ログ相関ID欠落', '運用部門は直ちに問題の把握を行い、障害発生の事実を関連部門に報告いたしました。運用 一郎がリードして、ログフォーマット変更に関するドキュメントを確認し、ロールアウト漏れの詳細を調査しました。影響を受けたログデータについては、修正作業を開始するための実施計画を立案中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01051', 'INC-2020-00708', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T23:11:56+09:00', TIMESTAMP WITH TIME ZONE '2020-04-07T00:11:56+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00714', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-10T05:53:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T06:23:34+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2020年4月10日05時53分34秒に、株式会社ストッククラウドのMercuryにおいてマスター設定ミスによる在庫登録失敗が発生しました。定例リリース直後にマスター更新を行ったにもかかわらず、在庫登録が拒否される事象が確認されました。この症状は、マスター更新後も旧設定で在庫登録が行われることで、全テナントに影響を及ぼしました。エラーコードはMST-10-00714であり、推定原因はキャッシュレイヤの無効化漏れです。運用部の運用 一郎が06時33分34秒にこの問題を検知し、迅速に対応を開始しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00714', 'INC-2020-00714', '調査の結果、定例リリース後にマスター更新が行われた際、キャッシュレイヤが無効化されていなかったことが原因と考えられます。この無効化漏れにより、旧設定が残存し、在庫登録が拒否される不整合が生じました。影響を受けた全テナントに対して迅速な情報提供を行い、リリース手順の見直しを検討しています。今後の対策としては、キャッシュの管理と更新手順の徹底を行う必要があります。', '調査の結果、定例リリース後にマスター更新が行われた際、キャッシュレイヤが無効化されていなかったことが原因と考えられます。この無効化漏れにより、旧設定が残存し、在庫登録が拒否される不整合が生じました。影響を受けた全テナントに対して迅速な情報提供を行い、リリース手順の見直しを検討しています。今後の対策としては、キャッシュの管理と更新手順の徹底を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-11T06:23:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01057', 'INC-2020-00714', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-10T06:38:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-10T07:38:34+09:00', '【初期対応】【在庫マスター設定障害】キャッシュ不整合登録', '運用部は、06時33分34秒に問題を検知した後、直ちに関連するテナントに通知を行い、影響を受けた在庫データの確認を実施しました。旧設定が残っていることを確認し、キャッシュの無効化を行う手続きを開始しました。最終的には、マスター設定の再確認と修正を実施し、問題の解決に努めました。今後は、定例リリース前にキャッシュの状態を確認する手順を追加することを提案します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00716', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-10-13T12:41:25+09:00', TIMESTAMP WITH TIME ZONE '2020-10-13T13:26:25+09:00', '【障害報告】【監視・可用性障害】PagerDuty連携失敗', '2020年10月13日12時41分、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れに関連する障害が発生しました。この問題により、PagerDuty連携が失敗し、オンコール通知が未達となりました。運用部門がこの障害に気づいたのは、2020年10月13日13時30分で、検知までに49分の時間を要しました。影響のあるコンポーネントはMercury AWS Storage（ゾーンB）およびインシデント通知であり、主な推定原因は連携APIキーの権限不足です。この問題が発生した契機は年末年始の稼働切替時であり、運用部門のみが影響を受けました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00716', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00716', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00716', 'INC-2020-00716', '運用部では、PagerDuty連携失敗に関する調査を実施しました。まず、連携APIキーの権限設定を確認し、必要な権限が不足していることを確認しました。次に、年末年始の稼働切替時において、特定の条件下でのみこの問題が発生することが判明しました。調査結果を基に、適切な権限の設定を行うことで、再発防止策を検討します。', '運用部では、PagerDuty連携失敗に関する調査を実施しました。まず、連携APIキーの権限設定を確認し、必要な権限が不足していることを確認しました。次に、年末年始の稼働切替時において、特定の条件下でのみこの問題が発生することが判明しました。調査結果を基に、適切な権限の設定を行うことで、再発防止策を検討します。', TIMESTAMP WITH TIME ZONE '2020-10-14T13:26:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01059', 'INC-2020-00716', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-10-13T13:41:25+09:00', TIMESTAMP WITH TIME ZONE '2020-10-13T14:41:25+09:00', '【対応ログ】【監視・可用性障害】初期対応', '初期対応として、運用部では即座に連携APIキーの権限を確認し、問題の特定に注力しました。確認の結果、権限不足が原因であることがわかり、速やかに必要な権限を付与しました。また、PagerDutyの設定を見直し、今後の通知が確実に行われるよう改善策を講じることを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00718', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-29T13:05:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T15:05:14+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2020年5月1日、株式会社ストッククラウドにおいて、顧客店舗POSがパートナーAPIから429を返され、連携が停止しました。この事象は大規模セール開始直前の影響により発生し、サービス全体の一部機能に影響を与えました。発見者は営業部の花子で、発生契機から167分後に検知されています。推定原因としては呼出頻度の事前調整不足が考えられます。今後の対策として、API呼出の頻度を再評価し、事前調整を徹底する必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00718', 'INC-2020-00718', '調査の結果、2020年5月1日に発生したパートナーAPIの429エラーは、大規模セール開始直前の呼出頻度が原因であることが確認されました。API連携が正常に行われなかったため、顧客店舗POSへの影響が見られました。追加の調整が必要です。', '調査の結果、2020年5月1日に発生したパートナーAPIの429エラーは、大規模セール開始直前の呼出頻度が原因であることが確認されました。API連携が正常に行われなかったため、顧客店舗POSへの影響が見られました。追加の調整が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-30T15:05:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01062', 'INC-2020-00718', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-29T15:20:14+09:00', TIMESTAMP WITH TIME ZONE '2020-04-29T16:20:14+09:00', '【対応ログ】【API連携・EDI障害】レート超過429', '2020年5月1日、株式会社ストッククラウドの営業部の花子からの報告に基づき、顧客店舗POSの連携停止に関する初期対応を開始しました。429エラーが返された理由を調査し、呼出頻度の調整に着手しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00722', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-03T20:15:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T22:15:20+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2023-10-01T15:30:00+09:00に発生したインシデントについて報告します。顧客店舗POSにて、データ移行バッチ実行中にShift_JIS変換を行ったところ、商品名が文字化けしました。これにより、単一店舗のみの影響が確認され、顧客は株式会社ストッククラウドです。この問題は2023-10-01T16:45:00+09:00に検知されました。影響範囲は限られたものの、エラーコードはEDI-07-00722として記録されています。今回の障害は、文字コード変換テーブルの誤選択が原因と考えられています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00722', 'INC-2020-00722', 'インシデント発生後、調査を行いました。Shift_JIS変換を使用する際に、誤った変換テーブルが選択されたことが問題の根本原因であると確認されました。データ移行バッチの実行時にこの誤選択が生じ、結果として商品名が文字化けする事象が発生しました。今後の対策として、変換テーブルの選択プロセスを見直し、再発防止策を講じる必要があります。', 'インシデント発生後、調査を行いました。Shift_JIS変換を使用する際に、誤った変換テーブルが選択されたことが問題の根本原因であると確認されました。データ移行バッチの実行時にこの誤選択が生じ、結果として商品名が文字化けする事象が発生しました。今後の対策として、変換テーブルの選択プロセスを見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-04T22:15:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01068', 'INC-2020-00722', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T22:30:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T23:30:20+09:00', '【初期対応】【API連携・EDI障害】文字コード変換事故', '初期対応として、影響を受けた商品名の修正作業を開始しました。また、担当者の営業 花子が、今後の対応策に関するチームミーティングを開催し、全員に状況を周知しました。さらに、データ移行バッチの監視体制を強化することを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01069', 'INC-2020-00722', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-04T00:00:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-04T01:00:20+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00723', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-15T00:10:33+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T02:10:33+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2023-10-01T10:15:33+09:00に発生した棚卸突合失敗に関する障害報告です。顧客店舗POSにおいて、POS連携の売上が翌営業日まで在庫に反映されない状況が発生しました。これは、年末年始の稼働切替時における問題であり、前日締め処理の二重実行が原因と推測されます。影響範囲は単一店舗のみで、エラーコードはINV-02-00723です。なお、2023-10-01T12:14:33+09:00に検知されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00723', 'INC-2020-00723', '本事象についての調査を行いました。年末年始の稼働切替時に発生したため、POS売上が翌営業日まで在庫に反映されない現象が見られました。原因として前日締め処理の二重実行が疑われ、現在その確認を進めています。', '本事象についての調査を行いました。年末年始の稼働切替時に発生したため、POS売上が翌営業日まで在庫に反映されない現象が見られました。原因として前日締め処理の二重実行が疑われ、現在その確認を進めています。', TIMESTAMP WITH TIME ZONE '2020-04-16T02:10:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01070', 'INC-2020-00723', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-15T02:25:33+09:00', TIMESTAMP WITH TIME ZONE '2020-04-15T03:25:33+09:00', '初期対応', '2023-10-01T10:30:00+09:00に初期対応を開始しました。顧客への影響を最小限に抑えるため、速やかに問題を特定し、解決策を講じることを目指します。これにより、POS売上遅延の問題を解決するための次のステップを考案します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00725', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-12-21T19:45:23+09:00', TIMESTAMP WITH TIME ZONE '2020-12-21T20:45:23+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2020年12月21日19時45分23秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客拠点NWにおけるネットワーク障害が発生しました。本障害により、架空食品店Aおよび架空食品店Bは店舗VPN経由でSaaSに到達できない事象が確認されました。今回の障害は、顧客オンボーディング当日に発生し、影響を受けたのは単一店舗のみです。原因として、拠点FWのルール変更が推定されます。エラーコードはNW-01-00725です。営業の花子が発見したことにより、20時31分23秒にその障害が検知され、検知までの時間は46分でした。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00725', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00725', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00725', 'INC-2020-00725', '顧客拠点NWにおける店舗VPNの接続不良に関して、詳細な調査を行いました。その結果、拠点FWのルール変更が原因である可能性が高いことが確認されました。顧客オンボーディング当日に発生した経緯から、このルール変更が意図したものであったのか、あるいは予期せぬものであったのかを今後確認する必要があります。', '顧客拠点NWにおける店舗VPNの接続不良に関して、詳細な調査を行いました。その結果、拠点FWのルール変更が原因である可能性が高いことが確認されました。顧客オンボーディング当日に発生した経緯から、このルール変更が意図したものであったのか、あるいは予期せぬものであったのかを今後確認する必要があります。', TIMESTAMP WITH TIME ZONE '2020-12-22T20:45:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01072', 'INC-2020-00725', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-12-21T21:00:23+09:00', TIMESTAMP WITH TIME ZONE '2020-12-21T22:00:23+09:00', '【初期対応】【顧客ネットワーク障害】店舗VPN到達不可', '初期対応として、拠点FWのルールを確認し、必要に応じて修正を行う手続きを開始しました。また、顧客である架空食品店Aおよび架空食品店Bに対して、現在の状況を報告し、影響範囲についても説明を行いました。この問題を早急に解決するため、技術チームと連携を取りながら進めていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00729', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-21T00:20:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T00:35:04+09:00', '【障害報告】【CLU-10】アラート疲労', '2020年4月21日00時20分に運用コンソールにおいて、同一アラートが短時間に数百件発報する事象が発生しました。このアラート疲労により、運用部門は正常な監視が困難となり、影響範囲は運用部門のみです。発報の発生契機は大規模セール開始直前であり、運用部の運用 一郎がこの事象を発見しました。検知は2020年4月21日00時36分であり、検知まで16分間の遅延が確認されました。影響コンポーネントは運用コンソール（DRサイト）及びアラートマネージャです。推定原因としてアラート抑制ルールの未設定が疑われます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00729', 'INC-2020-00729', '本事象に関する調査を行った結果、大規模セール開始直前に同一アラートが短時間に数百件発報したことが確認されました。アラート疲労の原因として、アラート抑制ルールが未設定であった可能性が高いです。この問題により、運用部門は監視および対応が困難となり、迅速な対応が求められました。', '本事象に関する調査を行った結果、大規模セール開始直前に同一アラートが短時間に数百件発報したことが確認されました。アラート疲労の原因として、アラート抑制ルールが未設定であった可能性が高いです。この問題により、運用部門は監視および対応が困難となり、迅速な対応が求められました。', TIMESTAMP WITH TIME ZONE '2020-04-22T00:35:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01077', 'INC-2020-00729', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T00:50:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T01:50:04+09:00', '【初期対応】【CLU-10】アラート疲労', '運用部門はこのアラート疲労を受け、直ちにアラート抑制ルールの設定を行い、再発防止策を検討しています。また、運用 一郎が中心となり、発報の原因分析と適切な対策を講じるために関連部署と連携し、事態の収束に向けて取り組んでいます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00731', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-23T17:57:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T18:57:27+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2020年04月23日17時57分、株式会社ストッククラウドの顧客拠点NWにおいて、ISP側BGP経路障害により複数拠点が同時不通となりました。この影響により、同一顧客の全店舗で通信障害が発生しました。発生契機はインフラメンテナンス明けであり、影響コンポーネントには顧客拠点NW（ゾーンB）およびDNSリゾルバが含まれます。障害は18時50分に検知され、53分のタイムラグがありました。現時点での推定原因は、ISP側のBGP経路障害と考えられます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00731', 'INC-2020-00731', '調査の結果、インフラメンテナンス明けに発生したISP側のBGP経路障害が、顧客拠点NWに影響を及ぼしました。ISPからの情報では、経路障害が複数箇所で同時に発生したことが確認されています。今後、ISPとの連携を強化し、再発防止策を講じていく必要があります。', '調査の結果、インフラメンテナンス明けに発生したISP側のBGP経路障害が、顧客拠点NWに影響を及ぼしました。ISPからの情報では、経路障害が複数箇所で同時に発生したことが確認されています。今後、ISPとの連携を強化し、再発防止策を講じていく必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T18:57:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01080', 'INC-2020-00731', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T19:12:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T20:12:27+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '初期対応として、顧客に対して障害の発生状況を連絡しました。続いて、営業部の花子がISPとの連絡を開始し、経路障害の詳細情報を収集しています。また、障害が解消されるまでの間、顧客に対して進捗状況を報告することを約束しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01081', 'INC-2020-00731', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-23T20:42:27+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T21:42:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00732', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-07-11T23:00:12+09:00', TIMESTAMP WITH TIME ZONE '2020-07-12T01:00:12+09:00', '【障害報告】【API連携・EDI障害】EDI在庫差分遅延', '2023年10月10日、株式会社ストッククラウドの顧客である架空食品店Aにおいて、在庫管理に関するEDI在庫差分ファイルの反映が2時間遅延する事象が発生しました。本障害は、顧客店舗POSにおいてデータ移行バッチ実行中に発生し、その結果としてEDI在庫差分の反映が遅延しました。推定される原因は、EDIキューの優先度設定誤りであり、影響範囲は同一顧客の全店舗に及ぶことが確認されております。エラーコードはEDI-01-00732であり、技術的詳細としては、データ移行バッチ実行中における反映遅延が関連しています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00732', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00732', 'INC-2020-00732', '調査の結果、EDI在庫差分ファイルの反映遅延は、データ移行バッチの実行中に発生したことが確認されました。特に、EDIキューの優先度設定に誤りがあり、これが原因でファイルの処理が遅れたと考えられます。今後、同様の問題を防ぐために、優先度設定の見直しおよび監視体制の強化を検討しています。', '調査の結果、EDI在庫差分ファイルの反映遅延は、データ移行バッチの実行中に発生したことが確認されました。特に、EDIキューの優先度設定に誤りがあり、これが原因でファイルの処理が遅れたと考えられます。今後、同様の問題を防ぐために、優先度設定の見直しおよび監視体制の強化を検討しています。', TIMESTAMP WITH TIME ZONE '2020-07-13T01:00:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01082', 'INC-2020-00732', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-07-12T01:15:12+09:00', TIMESTAMP WITH TIME ZONE '2020-07-12T02:15:12+09:00', '【初期対応】【API連携・EDI障害】EDI在庫差分遅延に対する初期対応', '初期対応として、データ移行バッチの実行状況を確認し、EDIキューの優先度設定を迅速に見直しました。また、影響を受けた顧客店舗POSの再起動を行い、在庫差分の反映が正常に行われるかどうかを確認しました。顧客への情報提供も行い、状況を説明し、謝罪いたしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01083', 'INC-2020-00732', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-07-12T02:45:12+09:00', TIMESTAMP WITH TIME ZONE '2020-07-12T03:45:12+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00733', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-20T08:41:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T09:11:30+09:00', '【障害報告】【CLU-09】マスター在庫二重反映', '2023-10-01T10:30:00+09:00に、株式会社ストッククラウドのMercuryにおいて、マスター更新と在庫が二重反映される事象が発生しました。この問題は、定例リリース直後に起こり、同一顧客の全店舗に影響を及ぼしました。具体的には、在庫データの整合性が損なわれ、複数の店舗において不正確な在庫状況が表示されました。直ちに運用部の運用 一郎が発見し、問題の詳細な調査を開始しました。なお、エラーコードはSYNC-01-00733です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00733', 'INC-2020-00733', '本件は、定例リリース直後に発生したマスター更新の際に、在庫が二重反映される問題が発生したものです。初期調査によると、イベント順序の逆転配信が原因であると考えられます。この逆転配信により、マスター更新の情報が正常に処理されず、データ同期・整合性に支障をきたしました。今後さらに詳細な原因分析が必要です。', '本件は、定例リリース直後に発生したマスター更新の際に、在庫が二重反映される問題が発生したものです。初期調査によると、イベント順序の逆転配信が原因であると考えられます。この逆転配信により、マスター更新の情報が正常に処理されず、データ同期・整合性に支障をきたしました。今後さらに詳細な原因分析が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-21T09:11:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01084', 'INC-2020-00733', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-20T09:26:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T10:26:30+09:00', '【初期対応】【CLU-09】マスター在庫二重反映', '2023-10-01T10:31:00+09:00に、運用 一郎がマスター在庫の二重反映事象を確認し、初期対応を実施しました。影響を受けた店舗に対して迅速に通知を行い、在庫データの修正に向けた手続きを開始します。また、システムの状態を監視し、問題の拡大を防止するための措置も講じています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01085', 'INC-2020-00733', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-20T10:56:30+09:00', TIMESTAMP WITH TIME ZONE '2020-04-20T11:56:30+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00735', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-16T03:03:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T03:48:28+09:00', '【障害報告】【ストレージ・容量障害】インデックス再構築膨張', '2023年10月05日03時03分、株式会社ストッククラウドのMercuryサービスにおいて、ストレージの容量障害が発生した。具体的には、インフラメンテナンス明けにインデックス再構築中に一時領域が枯渇した。この事象は特定リージョンのユーザーに影響を及ぼすものであり、エラーコードSTR-07-00735が記録されている。運用部署の運用 一郎が初めてこの問題を検知したのは03時44分であり、検知までに41分を要した。影響を受けたコンポーネントはMercury AWS Storage（ゾーンB）にあるDBデータファイルである。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00735', 'INC-2020-00735', '現在の調査結果として、インフラメンテナンス明けに行われたインデックス再構築が一時領域のサイズ見積不足により失敗した可能性が高い。詳細な原因分析を行った結果、再構築中に必要な一時領域の確保が困難になり、結果としてインデックス再構築が中断された。この問題による影響は、特定リージョンのユーザーに限定されていることが確認された。', '現在の調査結果として、インフラメンテナンス明けに行われたインデックス再構築が一時領域のサイズ見積不足により失敗した可能性が高い。詳細な原因分析を行った結果、再構築中に必要な一時領域の確保が困難になり、結果としてインデックス再構築が中断された。この問題による影響は、特定リージョンのユーザーに限定されていることが確認された。', TIMESTAMP WITH TIME ZONE '2020-04-17T03:48:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01087', 'INC-2020-00735', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T04:03:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T05:03:28+09:00', '【初期対応】【ストレージ・容量障害】インデックス再構築膨張', '2023年10月05日03時44分、運用 一郎がMercuryのストレージ容量障害を初めて検知した。まず、インフラメンテナンスが行われた後のインデックス再構築中に問題が発生したことを確認した。エラーコードSTR-07-00735をもとに、一時領域のサイズを見直す必要があると判断し、担当チームに連絡を取り、迅速な解決策の検討を依頼した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01088', 'INC-2020-00735', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-16T05:33:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-16T06:33:28+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
