INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00741', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00741', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00741', 'INC-2020-00741', '顧客拠点NWの状態を確認した結果、プロキシ経由での接続時に502エラーが発生していることが確認されました。タイムアウト設定が短い可能性が考えられます。今後、タイムアウト設定の見直しや、サーバーの負荷状況を調査することが必要です。', '顧客拠点NWの状態を確認した結果、プロキシ経由での接続時に502エラーが発生していることが確認されました。タイムアウト設定が短い可能性が考えられます。今後、タイムアウト設定の見直しや、サーバーの負荷状況を調査することが必要です。', TIMESTAMP WITH TIME ZONE '2020-11-24T12:41:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01096', 'INC-2020-00741', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-11-23T12:56:51+09:00', TIMESTAMP WITH TIME ZONE '2020-11-23T13:56:51+09:00', '【初動対応】【顧客ネットワーク障害】代理サーバー502', 'このインシデントに関して、即時対応を開始しました。まずは、プロキシの上流タイムアウト設定を確認し、必要に応じて変更を行います。また、関連する顧客側FWのログも確認し、502エラーの原因を特定するための分析を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01097', 'INC-2020-00741', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-11-23T14:26:51+09:00', TIMESTAMP WITH TIME ZONE '2020-11-23T15:26:51+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00745', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-03T18:25:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T19:10:37+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2023-10-10T14:00:00+09:00に発生したインシデントに関してご報告いたします。本インシデントは株式会社ストッククラウドが提供するMercuryサービスにおいて、運用部門に影響を与えるストレージ溢れに関連するものであり、具体的にはログに相関IDが欠落し、横断検索が不可となりました。定例リリース直後に発生したことから、ログフォーマット変更のロールアウト漏れが原因として推定されます。エラーコードはMON-09-00745で、影響を受けたコンポーネントはMercury AWS Storageとログパイプラインです。今後の対応が求められます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00745', 'INC-2020-00745', '本インシデントの調査を行った結果、定例リリース直後において、ログの相関IDが欠落していることが確認されました。横断検索が不可であるため、運用部門の業務に大きな影響を与えている状況です。原因として、ログフォーマット変更のロールアウト漏れが考えられます。今後はログフォーマットの確認および修正が必要です。', '本インシデントの調査を行った結果、定例リリース直後において、ログの相関IDが欠落していることが確認されました。横断検索が不可であるため、運用部門の業務に大きな影響を与えている状況です。原因として、ログフォーマット変更のロールアウト漏れが考えられます。今後はログフォーマットの確認および修正が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-04T19:10:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01102', 'INC-2020-00745', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-03T19:25:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T20:25:37+09:00', '【初期対応】【監視・可用性障害】ログ相関ID欠落', '本インシデントについて、運用部門における初期対応を行いました。影響範囲は運用部門のみに限られており、速やかにログフォーマットの確認を実施し、相関IDの復旧作業を進めました。横断検索機能の再稼働に向けて、必要な対応を迅速に進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01103', 'INC-2020-00745', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-03T20:55:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T21:55:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00746', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-26T14:25:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T15:10:10+09:00', '【障害報告】【ストレージ・容量障害】監査ログ削除未実行', '2023年10月12日14時25分に、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れのインシデントが発生しました。古い監査ログ削除ジョブが未実行であり、その結果、容量が不足する事態が発生しました。定例リリース直後に起こったこの障害は、容量アラート閾値の未設定が推定原因とされています。影響範囲はバッチ処理のみに限定されており、オンラインサービスへの影響は確認されておりません。エラーコードはSTR-05-00746です。本事象に関し、運用部の運用 一郎が発見し、検知まで47分を要しました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00746', 'INC-2020-00746', '本インシデントに関し、定例リリース直後において古い監査ログ削除ジョブが未実行であったことを確認しました。容量アラート閾値が未設定であったため、監査ログ削除が行われなかったと考えられます。今後の再発防止策として、容量アラートの設定を見直し、定期的な監査ログの確認を実施する必要があります。システムのストレージ管理を強化し、容量不足のリスクを軽減する方針です。', '本インシデントに関し、定例リリース直後において古い監査ログ削除ジョブが未実行であったことを確認しました。容量アラート閾値が未設定であったため、監査ログ削除が行われなかったと考えられます。今後の再発防止策として、容量アラートの設定を見直し、定期的な監査ログの確認を実施する必要があります。システムのストレージ管理を強化し、容量不足のリスクを軽減する方針です。', TIMESTAMP WITH TIME ZONE '2020-04-27T15:10:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01104', 'INC-2020-00746', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-26T15:25:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T16:25:10+09:00', '【初動対応】【ストレージ・容量障害】監査ログ削除未実行', 'インシデント発生後、運用部の担当者は直ちに定例リリースの影響を確認しました。古い監査ログ削除ジョブが未実行であることが判明し、発生した問題に対し迅速に対策を講じました。容量アラート設定の確認と、必要なログ削除作業を実施しました。また、再発防止のための手順も見直し、運用体制を強化する方針を立てました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00747', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-26T06:27:05+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T08:27:05+09:00', '【障害報告】【CLU-07】レート超過429', '2023-10-01T10:00:00+09:00、株式会社ストッククラウドにて発生した棚卸突合失敗について報告します。発生時刻は2023-10-01T10:00:00+09:00、検知時刻は2023-10-01T11:15:00+09:00であり、検知までの時間は75分でした。顧客店舗POSにおいて、パートナーAPIが429を返し連携が停止しました。この事象は大規模セール開始直前に発生しており、呼出頻度の事前調整不足が原因と考えられます。サービス全体の一部機能に影響を及ぼし、多くのお客様にご迷惑をおかけしました。エラーコードはEDI-06-00747です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00747', 'INC-2020-00747', '本件について調査を行った結果、大規模セール開始直前にパートナーAPIが429を返し、連携が停止したことが確認されました。原因として、呼出頻度の事前調整不足が疑われます。今後の対策として、呼出頻度の見直しと適切な調整を行う必要があります。', '本件について調査を行った結果、大規模セール開始直前にパートナーAPIが429を返し、連携が停止したことが確認されました。原因として、呼出頻度の事前調整不足が疑われます。今後の対策として、呼出頻度の見直しと適切な調整を行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-27T08:27:05+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01105', 'INC-2020-00747', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T08:42:05+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T09:42:05+09:00', '初期対応', '2023-10-01T10:05:00+09:00、営業部の花子が事象を確認し、状況を把握しました。即座に関係部署に連絡し、影響範囲の特定と影響を受けた顧客への対応を開始しました。429エラーが確認されたため、パートナーAPIの状況を監視しつつ、次回の大規模セールに向けた対策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01106', 'INC-2020-00747', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T10:12:05+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T11:12:05+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00749', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-12-26T17:04:22+09:00', TIMESTAMP WITH TIME ZONE '2020-12-26T18:04:22+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2020年12月26日17時04分、株式会社ストッククラウドの顧客である架空食品店Aにおいて、ISP側BGP経路障害が発生し、複数拠点が同時不通となりました。17時34分に問題が検知され、顧客拠点NWに影響が及んでいます。影響範囲は同一顧客の全店舗であり、主な原因はISP側のBGP経路障害と推定されています。インフラメンテナンス明けのタイミングでの障害発生が確認されており、DNSリゾルバにも影響が及んでいます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00749', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00749', 'INC-2020-00749', 'インフラメンテナンス明けに発生したISP側BGP経路障害により、架空食品店Aの複数拠点が同時不通となりました。原因としては、ISP側での設定不具合や機器故障が考えられ、技術詳細においてはDNSリゾルバが影響を受けたことも確認されています。関係者への詳細な調査が必要です。', 'インフラメンテナンス明けに発生したISP側BGP経路障害により、架空食品店Aの複数拠点が同時不通となりました。原因としては、ISP側での設定不具合や機器故障が考えられ、技術詳細においてはDNSリゾルバが影響を受けたことも確認されています。関係者への詳細な調査が必要です。', TIMESTAMP WITH TIME ZONE '2020-12-27T18:04:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01109', 'INC-2020-00749', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-12-26T18:19:22+09:00', TIMESTAMP WITH TIME ZONE '2020-12-26T19:19:22+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '2020年12月26日17時04分に発生したISP側BGP経路障害に対し、初期調査を行い、問題の特定を進めました。複数拠点の同時不通が確認されたため、顧客拠点NWの状態を詳細に分析し、ISPに連絡を取りました。影響範囲が広いため、速やかに対応策を講じる必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01110', 'INC-2020-00749', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-12-26T19:49:22+09:00', TIMESTAMP WITH TIME ZONE '2020-12-26T20:49:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00754', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-23T02:09:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T02:39:00+09:00', '【障害報告】【性能・負荷障害】下流APIレート制限', '2020年4月23日02時09分、株式会社ストッククラウドのMercuryサービスにおいて、下流APIのレート制限により処理待ちが増大しました。この問題は、大規模セール開始直前に発生し、サービス全体の一部機能に影響を及ぼしました。サーバーが処理待ち行列に多くのリクエストを抱え、応答遅延が発生した状況です。02時20分に運用部の運用 一郎によりこの問題が検知されました。エラーコードはPRF-07-00754です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00754', 'INC-2020-00754', '調査結果として、大規模セールの開始直前に下流APIのレート制限が影響したことが確認されました。このため、待ち行列が発生し、応答が遅れる事象が見受けられました。特に、Venus Azure AP（ゾーンA）とAPIゲートウェイが影響を受けたことが分かりました。今後、これに対する改善策を講じる必要があります。', '調査結果として、大規模セールの開始直前に下流APIのレート制限が影響したことが確認されました。このため、待ち行列が発生し、応答が遅れる事象が見受けられました。特に、Venus Azure AP（ゾーンA）とAPIゲートウェイが影響を受けたことが分かりました。今後、これに対する改善策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-24T02:39:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01118', 'INC-2020-00754', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-23T02:54:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-23T03:54:00+09:00', '【対応】【性能・負荷障害】初期対応', '最初の対応として、下流APIのレート制限を緩和するための手順を実施しました。具体的には、APIゲートウェイの設定を見直し、処理能力を向上させるためのリソースを追加しました。また、待ち行列の状況を監視し、リアルタイムでの応答速度の改善を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00756', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-26T19:07:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T20:07:22+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '・発生日時: 2020-04-26T19:07:22+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00756', 'INC-2020-00756', '本インシデントは、2020年4月26日19時07分22秒に発生しました。顧客側のネットワークにおいて、代理サーバー経由でのアクセス時に502エラーが返されました。検知は20時08分22秒で、発生から61分後に確認されました。プロキシの上流タイムアウト設定が過短であることが原因として考えられます。', '本インシデントは、2020年4月26日19時07分22秒に発生しました。顧客側のネットワークにおいて、代理サーバー経由でのアクセス時に502エラーが返されました。検知は20時08分22秒で、発生から61分後に確認されました。プロキシの上流タイムアウト設定が過短であることが原因として考えられます。', TIMESTAMP WITH TIME ZONE '2020-04-27T20:07:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01120', 'INC-2020-00756', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T20:22:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T21:22:22+09:00', '【初期対応】【顧客ネットワーク障害】代理サーバー502', '初期対応として、代理サーバーの設定を確認し、上流タイムアウトの設定を見直すことを検討しています。現時点では、顧客には影響が少ないと判断していますが、早急な対応が必要です。今後の進捗については、随時報告いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01121', 'INC-2020-00756', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-26T21:52:22+09:00', TIMESTAMP WITH TIME ZONE '2020-04-26T22:52:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00759', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-21T19:32:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T20:02:34+09:00', '【障害報告】【認証・セッション障害】サービスアカウント鍵漏洩対応', '2020年4月22日、株式会社ストッククラウドのMercuryにおいて、サービスアカウント鍵漏洩疑いによる一括無効化が発生いたしました。発生は定例リリース直後であり、影響範囲はバッチ処理のみに限られ、オンラインサービスには影響がございませんでした。エラーコードはAUTH-09-00759で、検知は2020年4月22日20:06:34に行われました。緊急鍵無効化手順の過剰適用が推定原因とされており、技術的にはVenus Azure APにおける認可サービスが影響を受けました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00759', 'INC-2020-00759', '本件に関する調査を行った結果、定例リリース後にサービスアカウント鍵漏洩疑いが発生し、これに対して緊急鍵無効化手順が適用されました。その際、過剰な対応が行われたことが確認され、無効化された鍵が必要なプロセスに影響を及ぼしました。今後は、同様の事象を防止するため、手順の見直しを検討する必要があります。', '本件に関する調査を行った結果、定例リリース後にサービスアカウント鍵漏洩疑いが発生し、これに対して緊急鍵無効化手順が適用されました。その際、過剰な対応が行われたことが確認され、無効化された鍵が必要なプロセスに影響を及ぼしました。今後は、同様の事象を防止するため、手順の見直しを検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-22T20:02:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01125', 'INC-2020-00759', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T20:17:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T21:17:34+09:00', '【初動対応】【認証・セッション障害】サービスアカウント鍵漏洩対応', '初動対応として、運用部の運用 一郎が中心となり、影響範囲の確認やサービスアカウントの鍵無効化の原因特定を行いました。また、関係者と連携し、影響を受けたバッチ処理の復旧作業も同時に進めました。今後の対応に向けて、緊急手順の適正な適用を徹底する方針とし、再発防止策を検討いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01126', 'INC-2020-00759', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-21T21:47:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-21T22:47:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00760', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-24T01:38:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T01:53:25+09:00', '【障害報告】【運用操作・権限障害】監査ログ出力停止', '発生日時: 2023-10-01T14:00:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00760', 'INC-2020-00760', '監査ログの外部出力が停止した原因を特定するために、運用コンソールのログを確認しました。初期調査の結果、ログシッパーの認証トークンが期限切れであることが判明しました。これにより監査ログの外部出力が行われなくなっていることが確認されました。', '監査ログの外部出力が停止した原因を特定するために、運用コンソールのログを確認しました。初期調査の結果、ログシッパーの認証トークンが期限切れであることが判明しました。これにより監査ログの外部出力が行われなくなっていることが確認されました。', TIMESTAMP WITH TIME ZONE '2020-04-25T01:53:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01127', 'INC-2020-00760', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T02:08:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T03:08:25+09:00', '初期対応', '問題の発生を受けて、運用部は直ちにログシッパーの認証トークンを更新する作業を開始しました。更新後、監査ログの外部出力が正常に行われるか再度確認します。顧客への影響は伴わないため、速やかな対応が求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01128', 'INC-2020-00760', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T03:38:25+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T04:38:25+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00761', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-08T20:20:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T20:35:06+09:00', '【障害報告】【運用操作・権限障害】メンテ解除失敗', '2020年4月8日20時20分、株式会社ストッククラウドのサービスMercuryで、運用コンソールにおいてメンテナンスモード解除操作が失敗する事象が発生しました。この障害は、インフラメンテナンス明けに発生したもので、メンテナンスフラグの残留が推定原因とされています。発見者は運用部の運用 一郎で、障害は20時35分に検知されました。影響範囲はサービス全体の一部機能に及び、エラーコードはOPS-03-00761です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00761', 'INC-2020-00761', '運用 一郎が確認したところ、インフラメンテナンス後にメンテナンスモード解除の操作が正常に行われず、メンテナンスフラグが残留していることが原因である可能性が高いことが判明しました。この問題により、運用コンソールからの操作が制限され、サービスの一部機能が正常に動作しない状態が続いていました。', '運用 一郎が確認したところ、インフラメンテナンス後にメンテナンスモード解除の操作が正常に行われず、メンテナンスフラグが残留していることが原因である可能性が高いことが判明しました。この問題により、運用コンソールからの操作が制限され、サービスの一部機能が正常に動作しない状態が続いていました。', TIMESTAMP WITH TIME ZONE '2020-04-09T20:35:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01129', 'INC-2020-00761', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T20:50:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T21:50:06+09:00', '【障害対応】【運用操作・権限障害】メンテ解除失敗対応', '運用 一郎がメンテナンスフラグの状態を確認し、運用コンソールでの解除操作を再試行しました。その結果、フラグが正常にリセットされ、サービスが復旧しました。これにより、影響範囲であった機能も正常に動作するようになりました。今後は、メンテナンス後の確認手順を厳守し、再発防止に努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01130', 'INC-2020-00761', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-08T22:20:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-08T23:20:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00763', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-01T18:05:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T18:35:40+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2023-10-01T14:00:00+09:00に発生したインシデントです。分散トランザクションがタイムアウトし、片側のみコミットされる状況が発生しました。この問題は、全テナントに波及し、在庫登録が失敗する事態に至りました。原因として、2PCタイムアウト設定の過短が推定されます。特に、大規模セール開始直前という発生契機も影響していると考えられます。技術的には、Mercury AWS AP（ゾーンA）において在庫計算エンジンがこの問題に関与しており、これが全体のデータ同期に悪影響を及ぼしたことが確認されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00763', 'INC-2020-00763', '本インシデントの調査を行った結果、分散トランザクションがタイムアウトした理由は、2PCタイムアウト設定が適切に設定されていなかったためであるということが判明しました。具体的には、大規模セール開始直前にシステム負荷が急増し、タイムアウトが発生したことが要因とされています。今後は、タイムアウト設定の見直しや、負荷テストの実施を行い、再発防止に努めます。', '本インシデントの調査を行った結果、分散トランザクションがタイムアウトした理由は、2PCタイムアウト設定が適切に設定されていなかったためであるということが判明しました。具体的には、大規模セール開始直前にシステム負荷が急増し、タイムアウトが発生したことが要因とされています。今後は、タイムアウト設定の見直しや、負荷テストの実施を行い、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2020-04-02T18:35:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01133', 'INC-2020-00763', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-01T18:50:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-01T19:50:40+09:00', '初期対応', 'インシデント発生後、運用チームは迅速に状況を把握し、影響範囲を確認しました。なお、運用部の運用 一郎が中心となり、緊急対応チームを編成し、問題の解決に向けて必要な措置を講じました。具体的には、2PCタイムアウト設定の見直しを行い、その後、システムの監視を強化し、テストを実施して問題の再発を防ぐ体制を整えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00772', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-18T16:40:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T17:40:41+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2020年4月18日16時40分41秒に、株式会社ストッククラウドのMercuryサービスにおいて、特定拠点のみAPI呼び出しが失敗する顧客側ネットワーク障害が発生しました。これにより、影響を受けたのは単一店舗のみであり、顧客は特に存在しませんでした。発生の契機は新規店舗追加の初日であり、16時40分41秒に障害が発生。その後、17時48分41秒にかけて68分間の間に検知されました。技術的には、店舗LANのスイッチ故障が原因として疑われています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00772', 'INC-2020-00772', '本障害の調査を行った結果、特定拠点においてAPI呼び出しが失敗するという症状が確認されました。調査では、店舗LANのスイッチ故障が推定原因として特定され、ネットワークの状態や構成に異常がないか詳細に確認しました。今後、店舗LANの機器に対するメンテナンスを実施し、再発防止策を講じる必要があります。', '本障害の調査を行った結果、特定拠点においてAPI呼び出しが失敗するという症状が確認されました。調査では、店舗LANのスイッチ故障が推定原因として特定され、ネットワークの状態や構成に異常がないか詳細に確認しました。今後、店舗LANの機器に対するメンテナンスを実施し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-19T17:40:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01147', 'INC-2020-00772', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-18T17:55:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T18:55:41+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗', '初期対応として、現地のネットワーク機器の状態を確認するため、担当営業の花子が迅速に現地に向かいました。特に、店舗LANのスイッチに異常がないかを優先的に確認し、必要に応じて交換を検討することとしました。また、顧客には障害についての情報を提供し、影響範囲の把握を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01148', 'INC-2020-00772', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-18T19:25:41+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T20:25:41+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00773', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-24T21:21:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T23:21:09+09:00', '【障害報告】【棚卸・POS突合障害】差異リスト空表示', '2023-10-01 10:00:00に発生したインシデントにより、顧客店舗POSにおいて棚卸差異リストが空表示になりました。この影響は同一顧客の全店舗に及んでおり、特にデータ移行バッチ実行中に発生しました。推定原因としては、店舗別在庫の集計粒度不一致が考えられます。影響を受けたエラーコードはINV-04-00773であり、店舗端末において必要な情報が表示されず、業務に支障をきたしています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00773', 'INC-2020-00773', '調査の結果、データ移行バッチが実行中に店舗端末で棚卸差異リストが空表示となる事象が確認されました。原因として、店舗別在庫の集計粒度が不一致であることが判明しました。この問題により、必要な棚卸データが表示されない状態が続いています。引き続き、影響範囲を特定し、適切な対応を検討します。', '調査の結果、データ移行バッチが実行中に店舗端末で棚卸差異リストが空表示となる事象が確認されました。原因として、店舗別在庫の集計粒度が不一致であることが判明しました。この問題により、必要な棚卸データが表示されない状態が続いています。引き続き、影響範囲を特定し、適切な対応を検討します。', TIMESTAMP WITH TIME ZONE '2020-04-25T23:21:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01149', 'INC-2020-00773', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-24T23:36:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T00:36:09+09:00', '【初期対応】【棚卸・POS突合障害】差異リスト空表示', '初期対応として、データ移行バッチの状況を確認し、集計粒度の不一致を解消するための検討を開始しました。また、影響を受けている店舗に対しては、代替手段として手動での棚卸の実施を指示しました。今後の進捗については随時報告いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01150', 'INC-2020-00773', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-25T01:06:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T02:06:09+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00776', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-11T09:09:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T09:39:37+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2023-10-25T14:00:00+09:00、株式会社ストッククラウドのサービスMercuryにおいて、Webhook再送が嵐状になり先方で拒否される事象が発生しました。発生は定例リリース直後であり、影響範囲は単一店舗のみです。エラーコードはEDI-02-00776です。この問題はMercury AWS AP（ゾーンB）内のWebhookディスパッチャに関連しており、再送間隔の指数バックオフ未設定が推定原因とされています。対応が急務です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00776', 'INC-2020-00776', '発生日時は2023-10-25T14:00:00+09:00です。定例リリース直後にWebhook再送が発生し、先方で拒否されたことが確認されています。現時点で再送間隔の指数バックオフが未設定であることが問題とされています。関連するエラーコードはEDI-02-00776です。影響範囲は単一店舗であり、早急な対応が求められます。', '発生日時は2023-10-25T14:00:00+09:00です。定例リリース直後にWebhook再送が発生し、先方で拒否されたことが確認されています。現時点で再送間隔の指数バックオフが未設定であることが問題とされています。関連するエラーコードはEDI-02-00776です。影響範囲は単一店舗であり、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2020-04-12T09:39:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01154', 'INC-2020-00776', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T09:54:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T10:54:37+09:00', '初期対応の実施', 'これに対する初期対応を実施しました。Webhook再送に関する設定を見直し、再送間隔の指数バックオフを適切に設定する作業を開始しました。また、影響を受けた店舗に対する連絡を行い、詳細な情報を提供しました。問題の解決に向けて、進捗を随時報告していく予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00779', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2020-04-03T01:25:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T03:25:40+09:00', '【障害報告】【API連携・EDI障害】冪等キー重複', '発生日時: 2023-10-05T01:25:40+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00779', 'INC-2020-00779', '冪等キーの重複が発生した原因を調査した結果、定例リリース直後に冪等キー生成ロジックに問題があったことが判明しました。このロジックの衝突により、在庫更新がスキップされ、同一顧客の全店舗に影響を与えました。今後、この問題を回避するための対策を検討する必要があります。', '冪等キーの重複が発生した原因を調査した結果、定例リリース直後に冪等キー生成ロジックに問題があったことが判明しました。このロジックの衝突により、在庫更新がスキップされ、同一顧客の全店舗に影響を与えました。今後、この問題を回避するための対策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-04T03:25:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01158', 'INC-2020-00779', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-03T03:40:40+09:00', TIMESTAMP WITH TIME ZONE '2020-04-03T04:40:40+09:00', '【初期対応】【API連携・EDI障害】冪等キー重複に対する初期対応', '発見後すぐに、冪等キー重複の問題を認識し、関連チームに連絡しました。まずは、影響を受けた店舗の在庫更新を手動で行うことを指示し、並行して冪等キー生成ロジックの確認を行うことにしました。影響範囲を把握するために、全店舗の状況を収集し始めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
