INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01165', 'INC-2020-00783', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-19T22:16:19+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T23:16:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00787', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-11T12:50:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T13:20:10+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2023-10-10T14:00:00+09:00に、株式会社ストッククラウドのMercuryにおいて、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けする障害が発生しました。これにより、単一店舗で在庫登録が失敗しました。発生契機は、データ移行バッチ実行中であり、エラーコードはEDI-07-00787です。影響範囲は単一店舗に限定されており、字化けにより正確な商品情報が反映されませんでした。発見者は運用 一郎(運用部)で、検知までの時間は37分でした。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00787', 'INC-2020-00787', '調査の結果、Shift_JIS変換において商品名が文字化けする現象が確認されました。推定原因は文字コード変換テーブルの誤選択と考えられます。影響を受けたコンポーネントはMercury AWS AP（DRサイト）とEDIアダプタです。今後は、テーブル選択のプロセスを見直し、検証を確実に行う必要があります。', '調査の結果、Shift_JIS変換において商品名が文字化けする現象が確認されました。推定原因は文字コード変換テーブルの誤選択と考えられます。影響を受けたコンポーネントはMercury AWS AP（DRサイト）とEDIアダプタです。今後は、テーブル選択のプロセスを見直し、検証を確実に行う必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-12T13:20:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01171', 'INC-2020-00787', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T13:35:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T14:35:10+09:00', '【初期対応】【API連携・EDI障害】文字コード変換事故への対応', '初期対応として、運用部門は直ちに障害を確認し、影響を受けたデータを洗い出しました。エラーコードEDI-07-00787に基づき、原因の特定と修正作業を開始しました。さらに、データ移行バッチの実行を一時停止し、再発防止のための対策を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01172', 'INC-2020-00787', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-11T15:05:10+09:00', TIMESTAMP WITH TIME ZONE '2020-04-11T16:05:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00790', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-25T12:20:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T12:35:35+09:00', '【障害報告】【CLU-08】リフレッシュトークン再利用', '2020年4月25日12時20分、株式会社ストッククラウドのMercuryサービスにおいて、運用コンソールでトークンローテーション実装の不備により、リフレッシュトークン再利用が検知され、同一顧客の全店舗で全端末ログアウトが発生しました。これは年末年始の稼働切替時に発生し、顧客に対する影響が及びました。この障害は2020年4月25日12時33分に検知され、検知までに13分を要しました。証拠として、エラーコードAUTH-10-00790が確認されています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00790', 'INC-2020-00790', '障害発生の原因として、トークンローテーション実装の不備が疑われます。年末年始の稼働切替時に実装されたトークンが適切に管理されておらず、リフレッシュトークンの再利用が発生しました。この問題は、運用コンソールおよびセッションストアに直接的な影響を及ぼしました。トークンの管理方法やローテーションのプロセスについて再確認が必要です。', '障害発生の原因として、トークンローテーション実装の不備が疑われます。年末年始の稼働切替時に実装されたトークンが適切に管理されておらず、リフレッシュトークンの再利用が発生しました。この問題は、運用コンソールおよびセッションストアに直接的な影響を及ぼしました。トークンの管理方法やローテーションのプロセスについて再確認が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-26T12:35:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01175', 'INC-2020-00790', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T12:50:35+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T13:50:35+09:00', '【初期対応】【CLU-08】リフレッシュトークン再利用', 'この問題を受けて、運用部の運用 一郎が直ちに対応にあたり、リフレッシュトークンの状況を確認しました。その後、全端末のログイン状況を把握し、影響を受けた顧客への連絡を開始しました。トークンローテーションの実装に関しても、迅速に修正作業を行う必要があると判断しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00791', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-07-18T23:30:46+09:00', TIMESTAMP WITH TIME ZONE '2020-07-19T00:00:46+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2020年7月18日23時30分46秒に、株式会社ストッククラウドのサービスMercuryにおいて、データ移行バッチ実行中にバルクAPIが部分失敗し、ロールバックが未完了となる事象が発生しました。この影響により、サービス全体の一部機能に障害が生じ、顧客である架空食品店Bや架空食品店Aに影響を及ぼしました。原因として、部分成功時の補償トランザクションが欠如していたことが推測されています。エラーコードはEDI-10-00791です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00791', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2020-00791', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00791', 'INC-2020-00791', '本インシデントに関する調査を実施した結果、バルクAPIが部分失敗した際にロールバックが正常に実行されなかったことが確認されました。これは、データ移行バッチが実行されている際に発生したもので、部分成功時には補償トランザクションが必要ですが、それが適切に処理されていなかったことが主な原因と考えられます。このような事象が再発しないよう、補償トランザクションの実装を見直す必要があります。', '本インシデントに関する調査を実施した結果、バルクAPIが部分失敗した際にロールバックが正常に実行されなかったことが確認されました。これは、データ移行バッチが実行されている際に発生したもので、部分成功時には補償トランザクションが必要ですが、それが適切に処理されていなかったことが主な原因と考えられます。このような事象が再発しないよう、補償トランザクションの実装を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2020-07-20T00:00:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01176', 'INC-2020-00791', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-19T00:15:46+09:00', TIMESTAMP WITH TIME ZONE '2020-07-19T01:15:46+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗', 'インシデント発生後、運用部の運用 一郎が早急に対応を開始しました。影響を受けた顧客への通知を行い、問題の詳細を把握するための調査を開始しました。また、システムの状況を確認し、即座にバルクAPIの処理状況を監視する体制を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01177', 'INC-2020-00791', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-07-19T01:45:46+09:00', TIMESTAMP WITH TIME ZONE '2020-07-19T02:45:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00793', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-19T10:36:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T10:51:34+09:00', '【障害報告】【運用操作・権限障害】ロールバック途中停止', '2023-10-10T14:15:00+09:00に発生した運用者の作業ミスによるアクセス障害について報告します。運用コンソールにて、定例リリース直後にロールバック操作が途中で停止し不整合が発生しました。これにより、サービス全体の一部機能に影響が及びました。発見者は運用部の運用 一郎で、障害は2023-10-10T14:30:00+09:00に検知されました。この障害は、リリース手順のスキップが原因であると推定されており、今後の対策として手順の遵守が求められます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00793', 'INC-2020-00793', '本インシデントの調査を行った結果、定例リリース直後に実施されたロールバック操作が途中で停止し、その結果不整合が生じました。リリース手順のスキップが推定される原因であり、今後は手順の遵守を徹底する必要があります。運用操作・権限障のリスクを軽減するためのルールを再確認し、運用部全体で意識を高めていくことが重要です。', '本インシデントの調査を行った結果、定例リリース直後に実施されたロールバック操作が途中で停止し、その結果不整合が生じました。リリース手順のスキップが推定される原因であり、今後は手順の遵守を徹底する必要があります。運用操作・権限障のリスクを軽減するためのルールを再確認し、運用部全体で意識を高めていくことが重要です。', TIMESTAMP WITH TIME ZONE '2020-04-20T10:51:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01180', 'INC-2020-00793', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T11:06:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T12:06:34+09:00', '【初期対応】【運用操作・権限障害】ロールバック途中停止', '運用 一郎が定例リリース後にロールバック操作を実施した際、作業手順の不備が確認されました。このため、ロールバックが途中で停止し不整合が発生しました。影響を受けたサービス機能を迅速に復旧するため、運用部は直ちに対応を開始し、影響範囲を特定し、原因を分析することとなりました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01181', 'INC-2020-00793', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T12:36:34+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T13:36:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00795', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2020-04-06T12:51:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T13:06:31+09:00', '【障害報告】【運用操作・権限障害】運用コンソールログイン不可', '2023-10-10T14:30:00+09:00に発生した運用者の作業ミスによるアクセス障害について報告いたします。運用コンソールにログインできない事象が発生し、全テナントに影響を及ぼしました。発生の契機は定例リリース直後であり、運用部の運用 一郎が発見しました。エラーコードはOPS-01-00795で、症状として運用コンソールへのログインが不可能となっています。技術詳細として、IAMポリシーの誤削除が原因として考えられます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00795', 'INC-2020-00795', '事象の発生後、運用コンソールへのログイン不可の原因を調査しました。定例リリース直後に運用コンソールへのアクセスができない状況が確認され、IAMポリシーの誤削除が原因である可能性が浮上しました。全テナントに影響及ぼすこの事象は、運用操作・権限障害にあたるため、早急な対処が必要です。', '事象の発生後、運用コンソールへのログイン不可の原因を調査しました。定例リリース直後に運用コンソールへのアクセスができない状況が確認され、IAMポリシーの誤削除が原因である可能性が浮上しました。全テナントに影響及ぼすこの事象は、運用操作・権限障害にあたるため、早急な対処が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-07T13:06:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01183', 'INC-2020-00795', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T13:21:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T14:21:31+09:00', '【初期対応】【運用操作・権限障害】運用コンソールログイン不可', 'このたびの障害に対し、初期対応を行いました。運用 一郎は、運用コンソールへのログインを試みましたが、依然としてアクセスできない状態が続いています。IAMポリシーの確認を行い、誤った設定がなされているかどうかを精査するため、関連チームへの連携を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01184', 'INC-2020-00795', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-06T14:51:31+09:00', TIMESTAMP WITH TIME ZONE '2020-04-06T15:51:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00797', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-28T06:48:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T07:48:04+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '日時: 2023-10-15T10:30:00+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00797', 'INC-2020-00797', '調査の結果、顧客ネットワークにおけるDNSキャッシュ汚染が確認されました。店舗DNSが旧IPアドレスを返し続けており、これはDNS TTL設定とキャッシュ方針の不一致によるものと考えられます。影響は単一店舗に限定されており、早急な対応が必要です。', '調査の結果、顧客ネットワークにおけるDNSキャッシュ汚染が確認されました。店舗DNSが旧IPアドレスを返し続けており、これはDNS TTL設定とキャッシュ方針の不一致によるものと考えられます。影響は単一店舗に限定されており、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2020-04-29T07:48:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01187', 'INC-2020-00797', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-28T08:03:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T09:03:04+09:00', '初動対応: DNSキャッシュ問題', '初動対応として、顧客拠点のDNS設定を確認し、TTL設定の見直しを行いました。また、DNSキャッシュのクリアを実施し、最新のIPアドレスを反映させる手続きを進めました。この対応により、店舗DNSの正常な動作が確認されました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01188', 'INC-2020-00797', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-28T09:33:04+09:00', TIMESTAMP WITH TIME ZONE '2020-04-28T10:33:04+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00804', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2020-04-25T12:54:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T13:39:06+09:00', '【障害報告】【ストレージ・容量障害】レプリカ遅延肥大', '2020年4月25日12時54分に、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れに関連するレプリカ遅延が発生しました。レプリカ遅延により差分ログが肥大化し、AWS Storage上でのデータアクセスに影響が出ました。この問題は大規模セール開始直前に発生し、読取専用レプリカ利用者に対して重大な影響を及ぼしました。運用部の運用 一郎が問題を発見し、検知までに49分かかりました。エラーコードはSTR-10-00804です。今後、レプリカ帯域制限設定の見直しが必要です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00804', 'INC-2020-00804', '本インシデントの調査を行った結果、大規模セール開始直前に発生したレプリカ遅延が原因であることが確認されました。レプリカ帯域制限設定が過小であり、これが差分ログを肥大化させる要因となりました。さらに、影響を受けたのは読取専用レプリカの利用者であり、ストレージシステム全体に対する影響を最小限に抑えるための対策が急務でした。', '本インシデントの調査を行った結果、大規模セール開始直前に発生したレプリカ遅延が原因であることが確認されました。レプリカ帯域制限設定が過小であり、これが差分ログを肥大化させる要因となりました。さらに、影響を受けたのは読取専用レプリカの利用者であり、ストレージシステム全体に対する影響を最小限に抑えるための対策が急務でした。', TIMESTAMP WITH TIME ZONE '2020-04-26T13:39:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01198', 'INC-2020-00804', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-25T13:54:06+09:00', TIMESTAMP WITH TIME ZONE '2020-04-25T14:54:06+09:00', '【初動対応】【ストレージ・容量障害】レプリカ遅延肥大', 'インシデント発生後、運用 一郎は速やかに対応を開始しました。最初の対応として、レプリカ帯域制限設定の確認を行い、必要な調整を検討しました。また、影響を受けた顧客への情報提供を始め、状況の把握と対策のための内部協議を実施しました。この初動対応により、さらなる影響の拡大を防ぐことができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00810', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-19T08:08:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T08:38:20+09:00', '【障害報告】【認証・セッション障害】Cookie SameSite拒否', '2023年10月15日、株式会社ストッククラウドのMercuryサービスで、Cookie SameSite設定に関連する問題が発生しました。この問題により、埋込画面が認証不可となる事象が確認されました。発生は定例リリース直後であり、影響範囲は単一店舗のみです。エラーコードはAUTH-06-00810であり、影響コンポーネントはVenus Azure AP（DRサイト）およびセッションストアです。運用部の運用 一郎がこの問題を発見したのは、発生から44分後の08:52:20でした。今後はSameSite属性の変更が原因である可能性を考慮し、早急な対応が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00810', 'INC-2020-00810', '調査を進めた結果、定例リリース直後にCookie SameSite設定の変更が行われたことが確認されました。この変更により、埋込画面が認証不可となる症状が発生したと推測されます。運用 一郎が早期に問題を報告したことにより、影響が広がる前に対処が可能となりました。今後、リリース時の設定確認を徹底する必要があります。', '調査を進めた結果、定例リリース直後にCookie SameSite設定の変更が行われたことが確認されました。この変更により、埋込画面が認証不可となる症状が発生したと推測されます。運用 一郎が早期に問題を報告したことにより、影響が広がる前に対処が可能となりました。今後、リリース時の設定確認を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2020-04-20T08:38:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01205', 'INC-2020-00810', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T08:53:20+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T09:53:20+09:00', '【初期対応】【認証・セッション障害】Cookie SameSite拒否', '運用 一郎より、2023年10月15日の08:52に報告を受け、直ちに確認を開始しました。CookieのSameSite設定が原因であることを特定し、緊急対応を実施することが決定されました。影響を受けた店舗には状況を説明し、修正対応を急ぐ旨を伝えました。次に、リリースの設定方法を見直し、再発防止策を講じる必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00811', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2020-04-19T04:51:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T05:21:09+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2023-10-10T08:30:00+09:00において、株式会社ストッククラウドのMercuryにおいてマスター設定ミスによる在庫登録失敗が発生しました。具体的には、マスター更新後も旧設定で在庫登録が拒否されるという症状が確認されました。この影響は全テナントに波及し、顧客への影響が懸念されます。エラーコードはMST-10-00811であり、定例リリース直後に発生したことがこの問題の発生契機とされています。技術的には、キャッシュレイヤの無効化漏れが推定されており、これにより不整合が生じたと考えられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00811', 'INC-2020-00811', '本インシデントに関する調査を行い、キャッシュレイヤの無効化漏れが原因であることが確認されました。マスター更新後にもかかわらず、旧設定での在庫登録が拒否されるという症状が発生し、全テナントに影響を及ぼしました。特に、定例リリース直後にこの問題が顕在化したことから、リリースプロセスに関する見直しが必要です。今後、キャッシュの管理手順を強化することで、再発防止に努めます。', '本インシデントに関する調査を行い、キャッシュレイヤの無効化漏れが原因であることが確認されました。マスター更新後にもかかわらず、旧設定での在庫登録が拒否されるという症状が発生し、全テナントに影響を及ぼしました。特に、定例リリース直後にこの問題が顕在化したことから、リリースプロセスに関する見直しが必要です。今後、キャッシュの管理手順を強化することで、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2020-04-20T05:21:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01206', 'INC-2020-00811', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T05:36:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T06:36:09+09:00', '【初期対応】【在庫マスター設定障害】キャッシュ不整合登録', '本障害発生を受けて、運用部の運用 一郎が迅速に対応を開始しました。まず、システムの状況を確認し、キャッシュレイヤの状態を検証しました。旧設定の影響を受けている在庫データを特定し、影響範囲を把握するためにログ解析を行いました。また、関係者への情報共有を行い、影響範囲に関するインシデント報告を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01207', 'INC-2020-00811', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-19T07:06:09+09:00', TIMESTAMP WITH TIME ZONE '2020-04-19T08:06:09+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00812', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-27T14:42:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T15:42:37+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2020年4月27日14時42分、株式会社ストッククラウドの顧客において、ISP側BGP経路障害が発生し、複数拠点が同時不通となった。この障害はインフラメンテナンス明けに発生したことが確認されており、影響範囲は同一顧客の全店舗に及ぶ。2020年4月27日15時49分にこの障害が検知されており、検知までに67分を要した。顧客拠点NW（DRサイト）およびDNSリゾルバに影響を及ぼしている。原因としてISP側のBGP経路障害が疑われているため、今後の対応が必要。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00812', 'INC-2020-00812', '障害発生後、営業部の花子が現地調査を行い、顧客拠点NWにおける通信状況を確認した。ISP側における経路障害が原因と考えられるため、ISPへの確認を急ぎ行う必要がある。また、DNSリゾルバの正常性も確認することが重要である。今後の調査結果に基づいて対応方針を決定することとする。', '障害発生後、営業部の花子が現地調査を行い、顧客拠点NWにおける通信状況を確認した。ISP側における経路障害が原因と考えられるため、ISPへの確認を急ぎ行う必要がある。また、DNSリゾルバの正常性も確認することが重要である。今後の調査結果に基づいて対応方針を決定することとする。', TIMESTAMP WITH TIME ZONE '2020-04-28T15:42:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01208', 'INC-2020-00812', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-27T15:57:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T16:57:37+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '本障害に対して、営業部の花子がISPへ連絡を取り、BGP経路障害の詳細な情報を確認した。ISP側の障害が解消され次第、各拠点への通信を再確認し、影響を受けた店舗への支援を行う予定である。また、顧客に対しては状況を説明し、引き続き進捗を報告することとした。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01209', 'INC-2020-00812', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-27T17:27:37+09:00', TIMESTAMP WITH TIME ZONE '2020-04-27T18:27:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00813', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2020-04-18T06:11:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T07:11:00+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2023-10-10 10:30:00 に発生した顧客側ネットワーク障害について報告します。顧客固定IP変更が許可リストに未反映のため、本日、顧客NWの接続に問題が発生しました。影響範囲は単一店舗のみで、顧客オンボーディング当日におけるIP許可リスト更新漏れが推定原因です。エラーコードは NW-07-00813 です。この事象により、顧客の業務に支障が出る可能性があります。今後、同様の事象が発生しないよう、社内での情報共有と手続きの徹底を図ります。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00813', 'INC-2020-00813', '本件の調査を行った結果、顧客の固定IP変更がサービスの許可リストに未反映であったことが確認されました。具体的には、顧客オンボーディング当日にIP許可リストの更新が漏れていたため、接続障害が発生しました。今後は、顧客オンボーディング時に必ず確認作業を行うよう、業務フローの見直しを検討します。', '本件の調査を行った結果、顧客の固定IP変更がサービスの許可リストに未反映であったことが確認されました。具体的には、顧客オンボーディング当日にIP許可リストの更新が漏れていたため、接続障害が発生しました。今後は、顧客オンボーディング時に必ず確認作業を行うよう、業務フローの見直しを検討します。', TIMESTAMP WITH TIME ZONE '2020-04-19T07:11:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01210', 'INC-2020-00813', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2020-04-18T07:26:00+09:00', TIMESTAMP WITH TIME ZONE '2020-04-18T08:26:00+09:00', '【初期対応】', '営業部の花子です。本日、顧客側ネットワークに障害が発生しました。顧客の固定IP変更が許可リストに反映されていないため、ネットワーク接続が行えない状況です。急ぎ、許可リストの更新を行い、接続可能にするための対応を進めます。今後は、顧客とのコミュニケーションを強化し、このような事象が再発しないよう努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2020-00814', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2020-04-24T18:25:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T18:55:28+09:00', '【障害報告】【認証・セッション障害】リフレッシュトークン再利用', '2020年4月24日18時25分に、株式会社ストッククラウドのMercuryサービスにおいて、リフレッシュトークン再利用検知による全端末ログアウトが発生しました。影響を受けたのは同一顧客の全店舗であり、特にVenus Azure APにおいて問題が顕在化しました。この事象は年末年始の稼働切替時に発生し、トークンローテーション実装の不備が原因と考えられています。検知は18時56分に行われ、約31分のタイムラグがありました。今後、このようなリフレッシュトークンの取り扱いについては、さらなる確認と改善が求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00814', 'INC-2020-00814', '本事象の詳細な調査により、リフレッシュトークンの再利用が検知されたため、全端末でのログアウトが発生したことが確認されました。原因は、トークンローテーション実装に関連する不備であると考えられます。特に、年末年始の稼働切替時にシステムが適切にトークンを更新できなかったことが引き金となった可能性があります。今後は、ローテーションの実装を見直し、再発防止策を講じることが必要です。', '本事象の詳細な調査により、リフレッシュトークンの再利用が検知されたため、全端末でのログアウトが発生したことが確認されました。原因は、トークンローテーション実装に関連する不備であると考えられます。特に、年末年始の稼働切替時にシステムが適切にトークンを更新できなかったことが引き金となった可能性があります。今後は、ローテーションの実装を見直し、再発防止策を講じることが必要です。', TIMESTAMP WITH TIME ZONE '2020-04-25T18:55:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01211', 'INC-2020-00814', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T19:10:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T20:10:28+09:00', '【対応ログ】【認証・セッション障害】初期対応', 'この度のリフレッシュトークン再利用による全端末ログアウトに関して、運用部の運用 一郎が初期対応を行いました。全店舗に影響が及んでいるため、迅速にシステムの状態を確認し、再発防止のための対策を検討しました。また、関連する顧客への報告と、今後の予防策についても迅速に策定する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01212', 'INC-2020-00814', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2020-04-24T20:40:28+09:00', TIMESTAMP WITH TIME ZONE '2020-04-24T21:40:28+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00010', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-09-18T14:13:39+09:00', TIMESTAMP WITH TIME ZONE '2021-09-18T16:13:39+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '2021年9月18日14時13分39秒、株式会社ストッククラウドの顧客である架空食品店Aおよび架空食品店Bにおいて、棚卸突合失敗が発生しました。発見者である営業部の花子が、顧客店舗POSでのデータ移行バッチ実行中に、同期メッセージがデッドレターに大量蓄積される事象を確認しました。エラーコードはSYNC-08-00010です。これにより、バッチ処理のみの影響が確認されましたが、オンラインには影響がないことがわかりました。状況の早急な把握と、適切な対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00010', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00010', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00010', 'INC-2021-00010', 'インシデント発生後、調査を開始しました。データ移行バッチ実行中にメッセージキューにおいて同期メッセージがデッドレターに蓄積し、現在の原因としてデッドレター再処理ジョブの未設定が疑われます。今後は、再処理ジョブの設定状況を確認し、必要に応じて設定を行う方針です。メッセージキューの確認も並行して進めます。', 'インシデント発生後、調査を開始しました。データ移行バッチ実行中にメッセージキューにおいて同期メッセージがデッドレターに蓄積し、現在の原因としてデッドレター再処理ジョブの未設定が疑われます。今後は、再処理ジョブの設定状況を確認し、必要に応じて設定を行う方針です。メッセージキューの確認も並行して進めます。', TIMESTAMP WITH TIME ZONE '2021-09-19T16:13:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00015', 'INC-2021-00010', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-09-18T16:28:39+09:00', TIMESTAMP WITH TIME ZONE '2021-09-18T17:28:39+09:00', '【初期対応】【データ同期・整合性障害】メッセージキュー確認', '営業部の花子が初期対応として、メッセージキューの状態を確認しました。結果、デッドレターに大量のメッセージが蓄積していることが確認されました。これに対し、デッドレター再処理ジョブの設定を急ぎ確認する必要があると判断しました。今後の対応に向け、必要な手続きを直ちに進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00016', 'INC-2021-00010', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-09-18T17:58:39+09:00', TIMESTAMP WITH TIME ZONE '2021-09-18T18:58:39+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00013', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2021-01-29T15:33:26+09:00', TIMESTAMP WITH TIME ZONE '2021-01-29T16:33:26+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2021年02月01日15時30分頃、株式会社ストッククラウドの顧客において、特定拠点のみAPI呼び出しが失敗する事象が発生しました。影響を受けたのは新規店舗追加の初日であり、顧客拠点NW（DRサイト）および顧客側FWに関する障害です。エラーコードはNW-02-00013で、特定の拠点でのみAPIが正常に機能せず、他の拠点には影響がありませんでした。原因として、店舗LANのスイッチ故障が疑われています。この問題は64分後の16時37分に検知されました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00013', 'INC-2021-00013', '問題の発生に伴い、店舗LANのスイッチに関する詳細な調査を実施しました。特定拠点のLAN機器に異常が見つかり、これがAPI呼び出し失敗の直接的な原因であることが確認されました。調査は迅速に行われ、問題の根本的な解決策を検討しています。', '問題の発生に伴い、店舗LANのスイッチに関する詳細な調査を実施しました。特定拠点のLAN機器に異常が見つかり、これがAPI呼び出し失敗の直接的な原因であることが確認されました。調査は迅速に行われ、問題の根本的な解決策を検討しています。', TIMESTAMP WITH TIME ZONE '2021-01-30T16:33:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00019', 'INC-2021-00013', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-01-29T16:48:26+09:00', TIMESTAMP WITH TIME ZONE '2021-01-29T17:48:26+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗', '初期対応として、該当する店舗のLAN機器を再起動し、API呼び出しの状況を監視しました。再起動後、APIの正常動作が確認され、影響範囲は特定の拠点に限定されていることが再確認されました。追加の対策として、スイッチの交換を検討しております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00017', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2021-04-19T20:34:18+09:00', TIMESTAMP WITH TIME ZONE '2021-04-19T20:49:18+09:00', '【障害報告】【CLU-10】SLO燃焼率警告', '2021年4月20日、架空食品店Bにおいて、運用コンソールにアクセス障害が発生しました。症状としてはSLO燃焼率が閾値を超え、エラーバジェット警告が出力されました。影響範囲は全テナントに波及しており、大規模セール開始直前という発生契機がありました。推定原因はSLO計算ウィンドウの設定誤りです。この障害により、架空食品店Bの運用に深刻な影響が及びました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00017', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00017', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00017', 'INC-2021-00017', '障害の発生後、原因調査を行った結果、SLO燃焼率が閾値を超えてエラーバジェット警告が出力されたことが確認されました。大規模セール開始直前の影響で、SLO計算ウィンドウの設定に誤りが混入した可能性が高いと考えています。関連する運用コンソールとSLOダッシュボードには、問題の根本的な解決が必要です。', '障害の発生後、原因調査を行った結果、SLO燃焼率が閾値を超えてエラーバジェット警告が出力されたことが確認されました。大規模セール開始直前の影響で、SLO計算ウィンドウの設定に誤りが混入した可能性が高いと考えています。関連する運用コンソールとSLOダッシュボードには、問題の根本的な解決が必要です。', TIMESTAMP WITH TIME ZONE '2021-04-20T20:49:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00025', 'INC-2021-00017', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-04-19T21:04:18+09:00', TIMESTAMP WITH TIME ZONE '2021-04-19T22:04:18+09:00', '【初期対応】【CLU-10】SLO燃焼率警告', '運用部の運用 一郎が初期対応を行い、運用コンソールの設定を確認しました。設定誤りが見つかり、修正作業を実施しました。修正後、SLO燃焼率の正常化を確認し、エラーバジェット警告は解消されました。今後の再発防止のため、設定確認プロセスを見直す必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00036', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2021-09-27T12:52:27+09:00', TIMESTAMP WITH TIME ZONE '2021-09-27T13:22:27+09:00', '【障害報告】【CLU-06】コールドスタート連鎖', '2023-09-27 12:52:27頃、株式会社ストッククラウドが提供するMercuryにおいて、サーバーレス関数のコールドスタートが連鎖し、サービス全体の一部機能に影響を及ぼしました。運用部の運用 一郎が発見し、検知までに34分を要しました。発生契機は定例リリース直後であり、エラーコードはPRF-06-00036です。影響を受けたコンポーネントはVenus Azure AP（Primary）およびCDNエッジです。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00036', 'INC-2021-00036', '調査の結果、定例リリース直後に発生したコールドスタートの連鎖が原因と考えられます。サーバーレス環境での負荷が一時的に増加し、これが連鎖的に問題を引き起こす要因となりました。さらに、システムリソースの供給が追いつかず、性能・負荷障害が生じました。', '調査の結果、定例リリース直後に発生したコールドスタートの連鎖が原因と考えられます。サーバーレス環境での負荷が一時的に増加し、これが連鎖的に問題を引き起こす要因となりました。さらに、システムリソースの供給が追いつかず、性能・負荷障害が生じました。', TIMESTAMP WITH TIME ZONE '2021-09-28T13:22:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00051', 'INC-2021-00036', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-09-27T13:37:27+09:00', TIMESTAMP WITH TIME ZONE '2021-09-27T14:37:27+09:00', '【初期対応】【CLU-06】コールドスタート連鎖', '運用部の運用 一郎が問題を検知し、初期対応を開始しました。まずは影響を受けたサーバーレス関数の状態を確認し、必要に応じてリソースを増強することで、コールドスタートの連鎖を防ぐ措置を講じました。また、ユーザーへの影響を最小限に抑えるため、関連するサービスの監視を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00037', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-02-24T08:21:19+09:00', TIMESTAMP WITH TIME ZONE '2021-02-24T10:21:19+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2021年2月24日午前8時21分19秒に、株式会社ストッククラウドの顧客である架空食品店Aにおいて、POS連携が中断する事象が発生しました。原因として、OAuthトークンが失効したことが確認されました。この障害は、年末年始の稼働切替時にリフレッシュトークンの保存先に障害が発生したためと考えられており、影響は単一店舗に限られています。お客様にはご迷惑をおかけし、深くお詫び申し上げます。今後、再発防止に向けた対策を講じてまいります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00037', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00037', 'INC-2021-00037', '本事象に関する調査を行った結果、OAuthトークンの失効が原因でPOS連携が中断したことが確認されました。リフレッシュトークンの保存先に障害が発生したため、トークンが正常に更新されず、連携機能に影響を及ぼしました。この問題は、年末年始の稼働切替時に発生したため、運用ポリシーの見直しが必要です。', '本事象に関する調査を行った結果、OAuthトークンの失効が原因でPOS連携が中断したことが確認されました。リフレッシュトークンの保存先に障害が発生したため、トークンが正常に更新されず、連携機能に影響を及ぼしました。この問題は、年末年始の稼働切替時に発生したため、運用ポリシーの見直しが必要です。', TIMESTAMP WITH TIME ZONE '2021-02-25T10:21:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00052', 'INC-2021-00037', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-02-24T10:36:19+09:00', TIMESTAMP WITH TIME ZONE '2021-02-24T11:36:19+09:00', '初動対応', '事象発生直後、営業部の花子が確認し、問題を把握しました。顧客には即座に連絡を行い、進捗状況を報告しました。技術チームには直ちに調査を依頼し、原因特定を急ぎました。顧客店舗POSとPOS連携ハブの状態を確認し、影響範囲と再発防止策について検討を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00053', 'INC-2021-00037', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-02-24T12:06:19+09:00', TIMESTAMP WITH TIME ZONE '2021-02-24T13:06:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00042', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-05-04T02:34:03+09:00', TIMESTAMP WITH TIME ZONE '2021-05-04T04:34:03+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2021年5月4日02:34に、架空食品店AにおいてEDI経由の棚卸ファイル取込で件数不一致が発生しました。この問題は、データ移行バッチ実行中に発生し、影響範囲はバッチ処理のみで、オンラインへの影響はありませんでした。04:49に問題が検知され、営業部の花子が発見者となりました。エラーコードはINV-06-00042です。原因としてはEDI連携ファイルの文字コード不一致が疑われており、技術的にはデータ移行バッチ実行中の処理において、EDI経由の棚卸ファイル取込にて件数不一致が確認されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00042', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00042', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00042', 'INC-2021-00042', '調査の結果、EDI連携ファイルの文字コード不一致が原因である可能性が高いと判断されました。データ移行の際、適切な文字コードでファイルが生成されていなかったため、POSシステムが正しい件数を認識できなかったことが確認されました。今後のバッチ処理においては、文字コードの確認を徹底することが必要です。', '調査の結果、EDI連携ファイルの文字コード不一致が原因である可能性が高いと判断されました。データ移行の際、適切な文字コードでファイルが生成されていなかったため、POSシステムが正しい件数を認識できなかったことが確認されました。今後のバッチ処理においては、文字コードの確認を徹底することが必要です。', TIMESTAMP WITH TIME ZONE '2021-05-05T04:34:03+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00059', 'INC-2021-00042', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-05-04T04:49:03+09:00', NULL, '初期対応', '初期対応として、営業部の花子が顧客店舗AのPOSシステムに対して状況を確認し、EDI連携ファイルの文字コードを調査しました。また、バッチ処理のログを確認し、今後同様の問題が発生しないように、データ移行プロセスを見直す必要があることを認識しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00050', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2021-11-28T01:55:04+09:00', TIMESTAMP WITH TIME ZONE '2021-11-28T02:55:04+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2021年11月28日01時55分頃、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bの顧客拠点NWでISP側BGP経路障害が発生しました。これにより、複数拠点が同時不通となり、全店舗が影響を受けました。検知時刻は02時22分で、発見は営業部の花子によって行われました。この障害は、インフラメンテナンス明けに発生しており、ISP側のBGP経路障害が原因と推定されます。該当のエラーコードはNW-06-00050です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00050', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00050', 'INC-2021-00050', '本インシデントに関する調査を行った結果、インフラメンテナンス明けにISP側のBGP経路障害が発生したことが確認されました。この障害により、架空食品店Bの全店舗が同時にネットワーク障害に見舞われました。原因として特定されたのはISP側のBGP経路障害であり、今後の対応策を検討中です。', '本インシデントに関する調査を行った結果、インフラメンテナンス明けにISP側のBGP経路障害が発生したことが確認されました。この障害により、架空食品店Bの全店舗が同時にネットワーク障害に見舞われました。原因として特定されたのはISP側のBGP経路障害であり、今後の対応策を検討中です。', TIMESTAMP WITH TIME ZONE '2021-11-29T02:55:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00070', 'INC-2021-00050', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-11-28T03:10:04+09:00', TIMESTAMP WITH TIME ZONE '2021-11-28T04:10:04+09:00', '【初動対応】【顧客ネットワーク障害】BGP経路障害波及に対する初動対応', '障害発生から27分後の02時22分に検知され、即座に営業部の花子が対応を開始しました。ISPへのエスカレーションを行い、障害の影響範囲を確認するための調査を実施しました。顧客には障害の詳細を報告し、ISP側の修復状況を随時更新することを約束しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00071', 'INC-2021-00050', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-11-28T04:40:04+09:00', TIMESTAMP WITH TIME ZONE '2021-11-28T05:40:04+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00052', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-05-26T16:56:31+09:00', TIMESTAMP WITH TIME ZONE '2021-05-26T18:56:31+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '2021年6月1日16時56分31秒に発生した棚卸突合失敗に関するインシデントです。顧客店舗POSにおいて、アウトボックステーブル滞留が発生し、通知遅延が確認されました。この障害は定例リリース直後に発生し、サービス全体の一部機能に影響を及ぼしました。エラーコードはSYNC-05-00052であり、影響を受けたコンポーネントは顧客店舗POS（Secondary）およびイベントバスです。推定原因として、アウトボックスポーラーの停止が疑われます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00052', 'INC-2021-00052', '発生したインシデントについて調査を行った結果、アウトボックステーブルの滞留が確認されました。この滞留が原因で、通知遅延が発生していることが明らかになりました。さらに、定例リリース直後に発生したことから、リリースに関連する要因が影響している可能性があります。現在、アウトボックスポーラーの状態を調査中です。', '発生したインシデントについて調査を行った結果、アウトボックステーブルの滞留が確認されました。この滞留が原因で、通知遅延が発生していることが明らかになりました。さらに、定例リリース直後に発生したことから、リリースに関連する要因が影響している可能性があります。現在、アウトボックスポーラーの状態を調査中です。', TIMESTAMP WITH TIME ZONE '2021-05-27T18:56:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00074', 'INC-2021-00052', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-05-26T19:11:31+09:00', TIMESTAMP WITH TIME ZONE '2021-05-26T20:11:31+09:00', '【初動対応】【データ同期・整合性障害】アウトボックス滞留に対する初動対応', '初動対応として、アウトボックステーブルの状況を確認し、滞留の原因を特定するための調査を開始しました。また、関連するシステムログを確認し、アウトボックスポーラーの稼働状態を確認しました。これにより、どの時点で停止したのかを特定し、今後の対応策を講じる基礎情報を収集しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00059', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2021-04-15T20:50:21+09:00', TIMESTAMP WITH TIME ZONE '2021-04-15T21:20:21+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2023年10月12日、株式会社ストッククラウドが提供するMercuryサービスにおいて、架空食品店Aに対して応答遅延が発生いたしました。症状として、ログに相関IDが欠落し横断検索が不可となりました。この事象は、定例リリース直後に発生し、運用部門のみが影響を受けました。検知時刻は2023年10月12日21時03分であり、発生から13分後に確認されました。原因として、ログフォーマット変更のロールアウト漏れが疑われます。影響を受けるコンポーネントはVenus Azure AP（ゾーンB）およびログパイプラインであり、今後の対策が求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00059', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00059', 'INC-2021-00059', '事故の調査において、定例リリース直後に発生したこの監視・可用性障害の原因を分析いたしました。ログに相関IDが欠落しているため、横断検索が不可能になっています。ログフォーマットの変更が行われた際に、そのロールアウトに漏れがあったと推定されます。運用部門のみが影響を受けており、早急な対応が必要です。', '事故の調査において、定例リリース直後に発生したこの監視・可用性障害の原因を分析いたしました。ログに相関IDが欠落しているため、横断検索が不可能になっています。ログフォーマットの変更が行われた際に、そのロールアウトに漏れがあったと推定されます。運用部門のみが影響を受けており、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2021-04-16T21:20:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00084', 'INC-2021-00059', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-04-15T21:35:21+09:00', TIMESTAMP WITH TIME ZONE '2021-04-15T22:35:21+09:00', '【初期対応】【監視・可用性障害】ログ相関ID欠落', '本件につきまして、運用部門にて迅速な初期対応を実施いたしました。ログフォーマット変更の影響を確認し、相関IDの欠落が原因であることを特定しました。今後の影響を最小限に抑えるため、適切なロールアウト手順の見直しを行い、再発防止策を策定いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00086', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-06-27T22:59:56+09:00', TIMESTAMP WITH TIME ZONE '2021-06-27T23:44:56+09:00', '【障害報告】【監視・可用性障害】トレースサンプリング過少', '2021年6月27日22時59分56秒に株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れが発生しました。影響を受けたのはMercury AWS Storageの運用部門であり、顧客として架空食品店B及び架空食品店Aが確認されています。エラーコードはMON-05-00086で、定例リリース直後に分散トレースのサンプリング率が過少となり、原因特定が困難な状況です。運用部の運用 一郎より発見され、検知までに24分を要しました。本事象により、分散トレースのサンプリングに影響が及び、原因特定が難航しております。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00086', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00086', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00086', 'INC-2021-00086', '本インシデントにおいて、分散トレースのサンプリング率が過少であったことが確認されました。技術的な調査を進めた結果、サンプリング率の本番設定誤りが疑われます。定例リリース直後に発生したため、設定内容の見直しが必要です。今後、さらなる調査を進め、具体的な原因を特定し、再発防止策を検討します。', '本インシデントにおいて、分散トレースのサンプリング率が過少であったことが確認されました。技術的な調査を進めた結果、サンプリング率の本番設定誤りが疑われます。定例リリース直後に発生したため、設定内容の見直しが必要です。今後、さらなる調査を進め、具体的な原因を特定し、再発防止策を検討します。', TIMESTAMP WITH TIME ZONE '2021-06-28T23:44:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00126', 'INC-2021-00086', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-06-27T23:59:56+09:00', TIMESTAMP WITH TIME ZONE '2021-06-28T00:59:56+09:00', '【監視・可用性障害】初期対応', '本事象に対する初期対応として、運用部門は速やかにシステムログの確認を行い、分散トレースのサンプリング率設定のレビューを開始しました。また、影響を受けた顧客への連絡を行い、状況の説明及び今後の対応について案内しました。顧客への影響を最小限に抑えるため、サンプリング率を一時的に修正し、監視体制を強化する対応を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00127', 'INC-2021-00086', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-06-28T01:29:56+09:00', TIMESTAMP WITH TIME ZONE '2021-06-28T02:29:56+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00088', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2021-12-29T14:01:07+09:00', TIMESTAMP WITH TIME ZONE '2021-12-29T15:01:07+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2021年12月29日14時01分07秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bの顧客拠点NWでDNS解決成功後にTLS握手で接続切断の問題が発生しました。問題はインフラメンテナンス明けに発生しており、全店舗に影響を及ぼしました。エラーコードはNW-03-00088で、発見者は営業部の花子です。原因としてはプロキシ証明書の期限切れが推定されており、技術的にはDNS解決後にTLS握手で接続が切断される状況が確認されています。この問題は顧客ネットワークの信頼性に影響を与えており、早急な対応が求められます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00088', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00088', 'INC-2021-00088', '本件の調査において、発生した時刻にインフラメンテナンスが行われていたことが確認されました。DNS解決は成功したものの、その後のTLS握手で接続が切断される事象が発生しています。この切断の原因としてプロキシ証明書の期限切れが疑われます。全店舗に影響が及んでいるため、設計の見直しとハードウェアのチェックが必要です。早急に対策を講じ、再発防止策を実施することが求められます。', '本件の調査において、発生した時刻にインフラメンテナンスが行われていたことが確認されました。DNS解決は成功したものの、その後のTLS握手で接続が切断される事象が発生しています。この切断の原因としてプロキシ証明書の期限切れが疑われます。全店舗に影響が及んでいるため、設計の見直しとハードウェアのチェックが必要です。早急に対策を講じ、再発防止策を実施することが求められます。', TIMESTAMP WITH TIME ZONE '2021-12-30T15:01:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00129', 'INC-2021-00088', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-12-29T15:16:07+09:00', TIMESTAMP WITH TIME ZONE '2021-12-29T16:16:07+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断の初期対応', '初期対応として、顧客拠点NWの状況を確認し、DNS解決が正常に行われているかを検証しました。また、プロキシ証明書の状態を確認するため、担当部門と連携し、証明書の更新作業を進めました。短期的な対策として、接続が切断されないように、代替のプロキシ証明書を準備し、即時の対応を行う方針で進めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00147', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-03-05T13:40:27+09:00', TIMESTAMP WITH TIME ZONE '2021-03-05T14:10:27+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2021年3月5日13時40分27秒、株式会社ストッククラウドのMercuryサービスにおいて、分散トランザクションがタイムアウトし、片側のみコミットされる事象が発生しました。この障害は、大規模セール開始直前に発生し、全テナントに波及する影響を及ぼしました。エラーコードはSYNC-04-00147です。原因として、2PCタイムアウト設定が過短であったことが推定されています。特に、Mercury AWS APにおいて在庫計算エンジンが影響を受けました。運用部の運用 一郎がこの事象を発見し、検知までに10分の時間を要しました。この障害は、今後のデータ同期における整合性確保の重要性を再認識させるものであり、引き続き注意深い監視が必要です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00147', 'INC-2021-00147', '発生した障害に関し、調査を行いました。分散トランザクションがタイムアウトした原因は、2PCタイムアウト設定が過短であったことに起因しています。この設定によって、トランザクション処理が正常に完了せず、一部のデータのみがコミットされる結果となりました。トランザクションの整合性が損なわれたため、全テナントに影響が及びました。今後は、タイムアウト設定の見直しを行い、再発防止策を講じる必要があります。', '発生した障害に関し、調査を行いました。分散トランザクションがタイムアウトした原因は、2PCタイムアウト設定が過短であったことに起因しています。この設定によって、トランザクション処理が正常に完了せず、一部のデータのみがコミットされる結果となりました。トランザクションの整合性が損なわれたため、全テナントに影響が及びました。今後は、タイムアウト設定の見直しを行い、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-03-06T14:10:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00214', 'INC-2021-00147', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-05T14:25:27+09:00', TIMESTAMP WITH TIME ZONE '2021-03-05T15:25:27+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウトに対する初期対応', 'この分散トランザクションタイムアウトの事象を受けて、迅速に初期対応を行いました。運用部の運用 一郎が即座に状況を確認し、システムの監視を強化しました。また、2PCタイムアウト設定の調査を開始し、問題の特定を急ぎました。影響を受けた全テナントへの通知を行い、障害の内容と経緯を説明しました。顧客への影響を最小限に抑えるため、必要に応じて手動でのデータ修正を行う準備も整えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00173', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-09-20T17:47:38+09:00', TIMESTAMP WITH TIME ZONE '2021-09-20T18:32:38+09:00', '【障害報告】【ストレージ・容量障害】開発ダンプ誤配置', '2021年9月20日17時47分38秒に、株式会社ストッククラウドの顧客「架空食品店A」において、Mercury AWS Storageでストレージ溢れが発生しました。この障害は、開発環境ダンプが本番ボリュームを占有しているために発生したものと推測されており、影響範囲はサービス全体の一部機能に及んでいます。運用部の運用 一郎が17時47分に発見しました。エラーコードはSTR-06-00173であり、発生契機はデータ移行バッチ実行中でした。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00173', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00173', 'INC-2021-00173', '本番環境におけるストレージの容量不足が確認され、開発環境ダンプの誤配置が原因である可能性が高いと考えられます。データ移行バッチの実行中に開発ダンプが本番ボリュームを占有し、これによりサービスの一部機能が影響を受けました。今後、開発環境と本番環境のデータ管理を徹底し、同様の問題を未然に防ぐ必要があります。', '本番環境におけるストレージの容量不足が確認され、開発環境ダンプの誤配置が原因である可能性が高いと考えられます。データ移行バッチの実行中に開発ダンプが本番ボリュームを占有し、これによりサービスの一部機能が影響を受けました。今後、開発環境と本番環境のデータ管理を徹底し、同様の問題を未然に防ぐ必要があります。', TIMESTAMP WITH TIME ZONE '2021-09-21T18:32:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00255', 'INC-2021-00173', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-09-20T18:47:38+09:00', TIMESTAMP WITH TIME ZONE '2021-09-20T19:47:38+09:00', '【初期対応】【ストレージ・容量障害】開発ダンプ誤配置', '運用部の運用 一郎です。開発ダンプの誤配置が本番ボリュームを占有していることが確認できました。この問題に対処するために、直ちにデータ移行バッチの停止と、開発ダンプの移動を実施しました。影響を受けたサービス機能の復旧を優先的に進めていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00184', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2021-10-07T16:09:10+09:00', TIMESTAMP WITH TIME ZONE '2021-10-07T16:39:10+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2021年10月07日16時09分10秒、架空食品店Aにおいて、Venus Azure AP（ゾーンA）に関する同一アラートが短時間に数百件発報されました。これにより、運用部門でのアラート疲労が発生しました。この現象は大規模セール開始直前に観測されており、アラート抑制ルールの未設定が推定原因とされています。検知は16時45分10秒で、発報から36分後でした。特に影響を受けたのは運用部門のみであり、アラートマネージャにおいては正常な運用が困難となりました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00184', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00184', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00184', 'INC-2021-00184', '調査を行った結果、大規模セール開始直前に同一アラートが数百件発報されたことが確認されました。アラート抑制ルールが未設定であったために、正常な運用が阻害され、運用部門に多大な影響を及ぼしました。アラートの発報が頻発したことで、運用部門はアラート疲労に悩まされ、その状況がさらに混乱を招く結果となりました。', '調査を行った結果、大規模セール開始直前に同一アラートが数百件発報されたことが確認されました。アラート抑制ルールが未設定であったために、正常な運用が阻害され、運用部門に多大な影響を及ぼしました。アラートの発報が頻発したことで、運用部門はアラート疲労に悩まされ、その状況がさらに混乱を招く結果となりました。', TIMESTAMP WITH TIME ZONE '2021-10-08T16:39:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00271', 'INC-2021-00184', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-10-07T16:54:10+09:00', TIMESTAMP WITH TIME ZONE '2021-10-07T17:54:10+09:00', '【対応ログ】【監視・可用性障害】アラート疲労の初期対応', '運用部門では、次の手順で初期対応を実施しました。まず、発報されたアラートの内容を確認し、原因の特定を試みました。その後、アラート抑制ルールの設定を行うための調整を図り、運用状況を把握するために監視体制を強化しました。これにより、今後のアラート疲労を軽減し、適切な運用が行えるよう努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00194', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-03-23T02:32:41+09:00', TIMESTAMP WITH TIME ZONE '2021-03-23T03:02:41+09:00', '【障害報告】【API連携・EDI障害】バルクAPI部分失敗', '2021年3月23日02時32分41秒に、株式会社ストッククラウドのサービスMercuryにおいて、在庫登録に関するマスター設定ミスが発生しました。この結果、バルクAPIが部分失敗しロールバックが未完了となり、サービス全体の一部機能に影響を及ぼしました。顧客である架空食品店Aにおいても在庫登録の失敗が発生しました。問題はデータ移行バッチ実行中に発生し、影響範囲には在庫登録APIも含まれます。エラーコードはEDI-10-00194であり、原因として部分成功時の補償トランザクションの欠如が疑われています。これにより、バルクAPIの運用が不安定となり、サービスの信頼性にも影響を及ぼす結果となりました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00194', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00194', 'INC-2021-00194', '調査の結果、2021年3月23日03時15分41秒に検知されたこの問題は、データ移行バッチ実行中に発生したことが確認されました。バルクAPIが部分失敗しその後のロールバックが未完了であったため、顧客に影響を与えました。問題の根本原因は、部分成功時の補償トランザクションが欠如していたことに起因しています。この欠如が、在庫登録APIの機能不全につながったと考えられます。', '調査の結果、2021年3月23日03時15分41秒に検知されたこの問題は、データ移行バッチ実行中に発生したことが確認されました。バルクAPIが部分失敗しその後のロールバックが未完了であったため、顧客に影響を与えました。問題の根本原因は、部分成功時の補償トランザクションが欠如していたことに起因しています。この欠如が、在庫登録APIの機能不全につながったと考えられます。', TIMESTAMP WITH TIME ZONE '2021-03-24T03:02:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00286', 'INC-2021-00194', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-23T03:17:41+09:00', TIMESTAMP WITH TIME ZONE '2021-03-23T04:17:41+09:00', '【初期対応】【API連携・EDI障害】バルクAPI部分失敗への初期対応', 'この事象が発生した際、運用部の運用 一郎が直ちに対応を開始しました。まず、影響を受けた顧客である架空食品店Aへの連絡を行い、状況を説明し、影響範囲を確認しました。その後、バルクAPIの状態を監視し、ロールバック処理を試みましたが、完全な回復には至らず、修正作業が必要であることが確認されました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00210', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-11-13T07:43:44+09:00', TIMESTAMP WITH TIME ZONE '2021-11-13T08:28:44+09:00', '【障害報告】【ストレージ・容量障害】WALアーカイブ滞留', '2021年11月13日07時43分44秒に、株式会社ストッククラウドのサービスMercuryにおいて、WALアーカイブが滞留しディスクを圧迫する事象が発生しました。影響を受けた顧客は架空食品店Bおよび架空食品店Aであり、全テナントに波及する問題となっています。エラーコードはSTR-08-00210です。発生契機は定例リリース直後であり、Mercury AWS Storageにおいてバックアップ領域が影響を受けています。この問題により、システムのパフォーマンスが著しく低下する可能性があります。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00210', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00210', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00210', 'INC-2021-00210', '本事象の調査を進めた結果、定例リリース後にWALアーカイブが滞留し、ダウンストリームのストレージに影響を及ぼしていることが明らかとなりました。推定原因として、アーカイブ先のマウントポイントが枯渇することで、アーカイブ処理が停止したと考えられます。この影響により、全テナントがストレージ・容量に関する問題に直面している状況です。', '本事象の調査を進めた結果、定例リリース後にWALアーカイブが滞留し、ダウンストリームのストレージに影響を及ぼしていることが明らかとなりました。推定原因として、アーカイブ先のマウントポイントが枯渇することで、アーカイブ処理が停止したと考えられます。この影響により、全テナントがストレージ・容量に関する問題に直面している状況です。', TIMESTAMP WITH TIME ZONE '2021-11-14T08:28:44+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00309', 'INC-2021-00210', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-11-13T08:43:44+09:00', TIMESTAMP WITH TIME ZONE '2021-11-13T09:43:44+09:00', '【初期対応】【ストレージ・容量障害】WALアーカイブ滞留への初期対応', 'インシデント発生後、運用部の運用 一郎が即座に事象の確認を行い、WALアーカイブが滞留していることを確認しました。直ちに、アーカイブ先のマウントポイントの状況を調査し、必要な対策を講じるよう指示しました。また、全テナントに対し、影響に関する告知を行い、状況の把握を徹底しました。今後の対策として、マウントポイントの監視強化を予定しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00310', 'INC-2021-00210', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-11-13T10:13:44+09:00', TIMESTAMP WITH TIME ZONE '2021-11-13T11:13:44+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00225', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2021-04-03T04:44:34+09:00', TIMESTAMP WITH TIME ZONE '2021-04-03T05:44:34+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2021年4月3日04:44:34、株式会社ストッククラウドの顧客である架空食品店Bにて、顧客拠点NWにおいて特定拠点のみAPI呼び出しが失敗する事象が発生。発見者は営業部の花子であり、発見時刻は05:54:34。発生契機は新規店舗追加の初日であり、この影響で単一店舗のみがサービスを利用できない状況に陥った。推定原因は店舗LANのスイッチ故障と考えられる。エラーコードはNW-02-00225で、顧客側FWにも影響を及ぼしている可能性がある。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00225', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00225', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00225', 'INC-2021-00225', '調査を開始し、特定拠点におけるAPI失敗の原因を確認。顧客LAN内のスイッチに異常が見つかり、これがAPI呼び出し失敗の直接的な原因であることが判明。顧客拠点NW（DRサイト）と顧客側FWも確認したところ、スイッチの故障が影響していることが確認された。迅速な対応が必要である。', '調査を開始し、特定拠点におけるAPI失敗の原因を確認。顧客LAN内のスイッチに異常が見つかり、これがAPI呼び出し失敗の直接的な原因であることが判明。顧客拠点NW（DRサイト）と顧客側FWも確認したところ、スイッチの故障が影響していることが確認された。迅速な対応が必要である。', TIMESTAMP WITH TIME ZONE '2021-04-04T05:44:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00332', 'INC-2021-00225', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-04-03T05:59:34+09:00', TIMESTAMP WITH TIME ZONE '2021-04-03T06:59:34+09:00', '【対応報告】【顧客ネットワーク障害】拠点限定API失敗', '営業部の花子が顧客架空食品店Bに直接連絡を取り、問題の詳細を説明。顧客には影響の範囲を明示し、現在対応中である旨を伝達。店舗LANのスイッチについては早急に専門技術者を派遣する予定であることを報告。顧客からは状況の理解を得て、引き続き進捗を観察することを約束。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00231', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-06-14T04:03:17+09:00', TIMESTAMP WITH TIME ZONE '2021-06-14T04:48:17+09:00', '【障害報告】【ストレージ・容量障害】WALアーカイブ滞留', '2021年6月14日04時03分に、株式会社ストッククラウドのサービスMercuryにおいて、全テナントに影響を及ぼすストレージ溢れが発生しました。具体的には、WALアーカイブが滞留しディスクを圧迫する事象が確認されました。運用部の運用 一郎が発見し、検知までに45分の時間を要しました。発生契機は定例リリース直後となっており、推定原因としてアーカイブ先のマウントポイント枯渇が考えられます。エラーコードはSTR-08-00231で、影響を受けたコンポーネントはMercury AWS Storage（DRサイト）及びバックアップ領域です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00231', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00231', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00231', 'INC-2021-00231', '本件についての調査を行った結果、定例リリース直後に発生したWALアーカイブの滞留が原因で、ストレージが圧迫されていることが確認されました。アーカイブ先のマウントポイントが枯渇していることが影響していると推測されます。今後は、マウントポイントの監視を強化し、同様の事象が再発しないよう対策を講じる必要があります。', '本件についての調査を行った結果、定例リリース直後に発生したWALアーカイブの滞留が原因で、ストレージが圧迫されていることが確認されました。アーカイブ先のマウントポイントが枯渇していることが影響していると推測されます。今後は、マウントポイントの監視を強化し、同様の事象が再発しないよう対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-06-15T04:48:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00339', 'INC-2021-00231', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-06-14T05:03:17+09:00', TIMESTAMP WITH TIME ZONE '2021-06-14T06:03:17+09:00', '【初動対応】【ストレージ・容量障害】WALアーカイブ滞留への初動対応', '初動対応として、運用部は直ちにWALアーカイブの滞留を解消するための対策を実施しました。具体的には、アーカイブ先のマウントポイントの状態を確認し、必要に応じて不要なデータを削除するなどの措置をとりました。また、影響を受ける全テナントへの通知を行い、状況を周知しました。今後の再発防止に向けた対応策についても検討を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00340', 'INC-2021-00231', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-06-14T06:33:17+09:00', TIMESTAMP WITH TIME ZONE '2021-06-14T07:33:17+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00238', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-04-28T16:24:46+09:00', TIMESTAMP WITH TIME ZONE '2021-04-28T17:09:46+09:00', '【障害報告】【監視・可用性障害】合成監視失敗', '2021年5月1日、架空食品店Aにおいて、Mercuryのストレージが溢れ、合成監視が特定ステップで失敗しました。この影響により、サービス全体の一部機能が利用できなくなりました。発生契機は定例リリース直後であり、エラーコードはMON-08-00238です。合成監視ランナーが正常に機能せず、テストデータの期限切れが推定原因として挙げられます。具体的には、Mercury AWS Storage（DRサイト）にて、合成監視が正常に稼働しなかったため、即座に対応が必要です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00238', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00238', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00238', 'INC-2021-00238', '本件に関して、運用部の運用 一郎が調査を行いました。合成監視が特定ステップで失敗した原因は、テストデータの期限切れであると考えられます。定例リリース直後に発生したことから、リリース時のテストデータ管理に問題があった可能性があります。今後はテストデータの管理方法を見直し、再発防止策を講じる必要があります。', '本件に関して、運用部の運用 一郎が調査を行いました。合成監視が特定ステップで失敗した原因は、テストデータの期限切れであると考えられます。定例リリース直後に発生したことから、リリース時のテストデータ管理に問題があった可能性があります。今後はテストデータの管理方法を見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-04-29T17:09:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00353', 'INC-2021-00238', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-04-28T17:24:46+09:00', TIMESTAMP WITH TIME ZONE '2021-04-28T18:24:46+09:00', '【初動対応】【監視・可用性障害】合成監視失敗', '発生直後に運用 一郎が監視システムを確認し、合成監視の失敗を確認しました。テストデータの期限切れが原因であると判断し、迅速に新しいテストデータを用意する手続きを開始しました。サービス提供に影響が出ないよう、影響範囲を特定し、必要な措置を講じる準備を進めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00275', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2021-11-15T15:34:51+09:00', TIMESTAMP WITH TIME ZONE '2021-11-15T15:49:51+09:00', '【障害報告】【運用操作・権限障害】メンテ解除失敗', '2021年11月15日15時34分51秒に株式会社ストッククラウドの運用コンソールにおいて、運用一郎（運用部）がメンテナンスモード解除操作を実施したが、解除が失敗した。この事象は架空食品店Bおよび架空食品店Aに影響を及ぼし、サービス全体の一部機能が利用できなくなった。影響が発生したのは、インフラメンテナンス明けのタイミングであり、推定原因はメンテナンスフラグの残留と考えられる。エラーコードはOPS-03-00275である。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00275', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00275', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00275', 'INC-2021-00275', '運用一郎がメンテナンスモード解除を試みた際、運用コンソールからの操作が正常に完了しなかった。本件の調査では、メンテナンスフラグが残留していたことが原因として特定された。これにより、サービス全体の一部機能に障害が発生し、顧客に影響が及んだことが確認された。', '運用一郎がメンテナンスモード解除を試みた際、運用コンソールからの操作が正常に完了しなかった。本件の調査では、メンテナンスフラグが残留していたことが原因として特定された。これにより、サービス全体の一部機能に障害が発生し、顧客に影響が及んだことが確認された。', TIMESTAMP WITH TIME ZONE '2021-11-16T15:49:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00407', 'INC-2021-00275', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-11-15T16:04:51+09:00', TIMESTAMP WITH TIME ZONE '2021-11-15T17:04:51+09:00', '【初期対応】【運用操作・権限障害】メンテ解除失敗', '運用一郎がメンテナンスモード解除失敗の連絡を受け、即座に状況を確認。メンテナンスフラグの残留が原因と判断し、フラグを解除する手続きを開始した。これにより、サービスの復旧に向けた初期対応を実施。早急に解決に向けて動いている。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00284', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-01-22T00:21:24+09:00', TIMESTAMP WITH TIME ZONE '2021-01-22T00:51:24+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '・発生日時: 2023-03-15T00:21:24+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00284', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00284', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00284', 'INC-2021-00284', '本障害における調査を実施。CDCイベントの欠損が確認され、下流倉庫のデータが更新されていないことが報告された。CDCコネクタのオフセット巻戻しが原因である可能性が高いと考えられる。データ移行バッチ実行中に何らかの問題が発生し、CDCイベントが正常に取得されなかったことが想定される。', '本障害における調査を実施。CDCイベントの欠損が確認され、下流倉庫のデータが更新されていないことが報告された。CDCコネクタのオフセット巻戻しが原因である可能性が高いと考えられる。データ移行バッチ実行中に何らかの問題が発生し、CDCイベントが正常に取得されなかったことが想定される。', TIMESTAMP WITH TIME ZONE '2021-01-23T00:51:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00419', 'INC-2021-00284', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-01-22T01:06:24+09:00', TIMESTAMP WITH TIME ZONE '2021-01-22T02:06:24+09:00', '【対応ログ】【データ同期・整合性障害】初期対応', '障害発生を確認後、運用部の運用 一郎がシステムの状態を確認し、CDCイベントの欠損を特定。直ちにデータ移行バッチの再実行を指示し、原因の究明を開始。関連コンポーネントのログも確認し、今後の再発防止策を検討するために必要な情報を収集中。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00286', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-07-07T16:09:12+09:00', TIMESTAMP WITH TIME ZONE '2021-07-07T16:54:12+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2023-10-01T10:00:00+09:00、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れに関する問題が発生しました。顧客の架空食品店Bおよび架空食品店Aに影響が及び、運用部門においてPagerDuty連携が失敗し、オンコール通知未達の事象が確認されました。エラーコードはMON-07-00286です。発生契機は年末年始の稼働切替時で、影響コンポーネントはMercury AWS Storage（ゾーンB）およびインシデント通知です。技術的には、年末年始の稼働切替時における連携APIキーの権限不足が疑われています。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00286', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00286', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00286', 'INC-2021-00286', '本インシデントに関する調査を行ったところ、PagerDuty連携が失敗した原因は、連携APIキーの権限不足であることが判明しました。特に、年末年始の稼働切替時において、APIキーが正しく設定されていなかったため、オンコール通知が運用部門に届かない結果となりました。', '本インシデントに関する調査を行ったところ、PagerDuty連携が失敗した原因は、連携APIキーの権限不足であることが判明しました。特に、年末年始の稼働切替時において、APIキーが正しく設定されていなかったため、オンコール通知が運用部門に届かない結果となりました。', TIMESTAMP WITH TIME ZONE '2021-07-08T16:54:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00422', 'INC-2021-00286', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-07-07T17:09:12+09:00', TIMESTAMP WITH TIME ZONE '2021-07-07T18:09:12+09:00', '【初期対応】【CLU-10】PagerDuty連携失敗の対応', '初期対応として、連携APIキーの権限を確認し、必要な権限を付与する作業を行いました。また、PagerDutyの設定を見直し、今後のオンコール通知が確実に行われるよう改善策を講じました。運用部門への影響を最小限に抑えるため、速やかに復旧作業を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00289', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-08-24T04:45:51+09:00', TIMESTAMP WITH TIME ZONE '2021-08-24T06:45:51+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '株式会社ストッククラウドのサービスMercuryにおいて、顧客である架空食品店Bの店舗で発生した棚卸突合失敗に関する障害について報告いたします。発生日時は2021年8月24日04時45分51秒で、同日06時39分51秒に検知されました。症状としては、実地棚卸数とシステム在庫が大幅に乖離していることが確認されました。この障害は同一顧客の全店舗に影響を及ぼしており、発生は月末棚卸の開始時に見られました。エラーコードはINV-01-00289です。原因としては、棚卸スナップショット時刻のずれが推定されます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00289', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00289', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00289', 'INC-2021-00289', '調査の結果、顧客店舗POS及び棚卸突合エンジンの稼働状況を確認しました。月末棚卸の開始時に、実地棚卸数とシステム在庫に大幅な乖離が生じているため、棚卸スナップショット時刻のずれが障害の主な原因と考えられます。今後、関係部署においてスナップショットの正確性を確保するための対策を講じる必要があります。', '調査の結果、顧客店舗POS及び棚卸突合エンジンの稼働状況を確認しました。月末棚卸の開始時に、実地棚卸数とシステム在庫に大幅な乖離が生じているため、棚卸スナップショット時刻のずれが障害の主な原因と考えられます。今後、関係部署においてスナップショットの正確性を確保するための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-08-25T06:45:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00426', 'INC-2021-00289', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-08-24T07:00:51+09:00', TIMESTAMP WITH TIME ZONE '2021-08-24T08:00:51+09:00', '【初期対応】【棚卸・POS突合障害】棚卸実地差異', '初期対応として、営業部の花子が顧客店舗POSのデータを確認し、実地棚卸数とシステム在庫の乖離状況を詳細に調査しました。影響を受けている全店舗に対して、障害の発生について通知し、必要に応じて代替策を講じるよう指示をしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00305', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2021-03-19T16:57:30+09:00', TIMESTAMP WITH TIME ZONE '2021-03-19T17:12:30+09:00', '【障害報告】【CLU-10】SLO燃焼率警告', '2023-10-01に発生した運用者の作業ミスによるアクセス障害について報告します。顧客は架空食品店Bで、運用コンソールにおいてSLO燃焼率が閾値を超過し、エラーバジェット警告が発生しました。推定原因はSLO計算ウィンドウの設定誤りであり、全テナントに波及する影響を及ぼしました。発生契機は大規模セール開始直前であり、運用 一郎（運用部）が発見しました。技術詳細としては、大規模セール開始直前にSLO燃焼率が閾値超過でエラーバジェット警告が発生し、原因としてSLO計算ウィンドウの設定誤りを疑っています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00305', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00305', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00305', 'INC-2021-00305', '今回のSLO燃焼率のエラーバジェット警告について、運用者の作業ミスにより設定誤りが発生した可能性が高いです。運用コンソールでの確認を行い、原因分析を進める必要があります。全テナントに影響が及んでいるため、早急に対応を行う必要があります。エラーバジェットの状況を再確認し、適切な設定を行うことで再発防止のためのアクションプランを策定することが求められます。', '今回のSLO燃焼率のエラーバジェット警告について、運用者の作業ミスにより設定誤りが発生した可能性が高いです。運用コンソールでの確認を行い、原因分析を進める必要があります。全テナントに影響が及んでいるため、早急に対応を行う必要があります。エラーバジェットの状況を再確認し、適切な設定を行うことで再発防止のためのアクションプランを策定することが求められます。', TIMESTAMP WITH TIME ZONE '2021-03-20T17:12:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00447', 'INC-2021-00305', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-19T17:27:30+09:00', TIMESTAMP WITH TIME ZONE '2021-03-19T18:27:30+09:00', '【初期対応】【CLU-10】SLO燃焼率警告', '運用 一郎が発見後、即座に運用コンソールの設定を確認しました。設定誤りが判明し、SLO燃焼率の値を適切に修正しました。全テナントへの影響を最小限に抑えるため、関連する顧客に状況を通知し、問題解決に向けた対応を継続しています。エラーバジェットの状態をモニタリングし、次回の大規模セールに向けて再発防止策を講じることが急務です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00323', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-05-30T20:42:33+09:00', TIMESTAMP WITH TIME ZONE '2021-05-30T21:12:33+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2021年6月15日20時42分33分、株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Aの在庫登録が失敗しました。発生契機として、大規模セール開始直前のタイミングで、分散トランザクションがタイムアウトし片側のみコミットされました。この事象は全テナントに波及し、影響範囲を広げる結果となりました。エラーコードSYNC-04-00323が記録され、技術的な詳細として2PCタイムアウト設定の過短が原因として疑われます。運用部の運用 一郎によって発見され、16分後に検知されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00323', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00323', 'INC-2021-00323', 'インシデントの調査を行った結果、問題の根本的な原因は2PCタイムアウト設定の過短であることが判明しました。大規模セール開始直前に発生したため、通常時とは異なるトラフィックが発生し、分散トランザクションがタイムアウトしました。このため、片側のみのコミットが行われ、在庫登録が失敗しました。この事象は全テナントに影響を及ぼし、データ同期・整合性の問題が顕在化しました。', 'インシデントの調査を行った結果、問題の根本的な原因は2PCタイムアウト設定の過短であることが判明しました。大規模セール開始直前に発生したため、通常時とは異なるトラフィックが発生し、分散トランザクションがタイムアウトしました。このため、片側のみのコミットが行われ、在庫登録が失敗しました。この事象は全テナントに影響を及ぼし、データ同期・整合性の問題が顕在化しました。', TIMESTAMP WITH TIME ZONE '2021-05-31T21:12:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00472', 'INC-2021-00323', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-05-30T21:27:33+09:00', TIMESTAMP WITH TIME ZONE '2021-05-30T22:27:33+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウト', 'インシデント発生直後、運用部の運用 一郎が状況を確認し、影響を受けた顧客に対して迅速に通知を行いました。問題の特定を急ぎ、技術チームが調査を開始しました。また、2PCタイムアウト設定の見直しや、トランザクションの監視を強化する方針が決定されました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00473', 'INC-2021-00323', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-05-30T22:57:33+09:00', TIMESTAMP WITH TIME ZONE '2021-05-30T23:57:33+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00331', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-05-10T01:03:41+09:00', TIMESTAMP WITH TIME ZONE '2021-05-10T01:33:41+09:00', '【障害報告】【データ同期・整合性障害】楽観ロック競合多発', '2021年5月10日、株式会社ストッククラウドのMercuryにおいて、架空食品店A及び架空食品店Bでの在庫登録において、楽観ロック競合が多発し、更新失敗率が上昇する事象が発生しました。発生時刻は01:03:41で、検知は01:28:41でした。全テナントに波及する影響が出る可能性が高く、特に大規模セール開始直前のタイミングでの事象であるため、事業への影響が懸念されます。原因として、バージョンカラム更新ロジックの不備が考えられています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00331', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00331', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00331', 'INC-2021-00331', '調査の結果、楽観ロック競合が多発したことにより、在庫登録が頻繁に失敗していることが確認されました。特に、バージョンカラム更新ロジックに不備が見つかり、これが主な原因と考えられます。影響を受けた全テナントからのフィードバックを受け、詳細なデータ分析を進めています。新たなロジックを導入することで、将来の競合を軽減する対策が必要です。', '調査の結果、楽観ロック競合が多発したことにより、在庫登録が頻繁に失敗していることが確認されました。特に、バージョンカラム更新ロジックに不備が見つかり、これが主な原因と考えられます。影響を受けた全テナントからのフィードバックを受け、詳細なデータ分析を進めています。新たなロジックを導入することで、将来の競合を軽減する対策が必要です。', TIMESTAMP WITH TIME ZONE '2021-05-11T01:33:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00485', 'INC-2021-00331', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-05-10T01:48:41+09:00', TIMESTAMP WITH TIME ZONE '2021-05-10T02:48:41+09:00', '初動対応', '初動対応として、運用部の運用 一郎が状況を確認し、影響を受けているテナントに対して状況報告を行いました。楽観ロック競合の原因であるバージョンカラム更新ロジックの不備については、早急にエンジニアリングチームに連絡し、修正を進めるよう指示を出しました。また、顧客への影響を最小限に抑えるため、在庫登録APIの使用を一時的に制限し、安定化を図る措置を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00344', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-05-30T03:44:09+09:00', TIMESTAMP WITH TIME ZONE '2021-05-30T04:14:09+09:00', '【障害報告】【CLU-07】JSONスキーマ不一致', '2021年5月30日03時44分に、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。顧客の架空食品店Aに影響を及ぼし、連携JSONのスキーマ不一致が原因で全件拒否される事態となりました。この問題は、定例リリース直後に起こり、影響範囲はバッチ処理のみに限られ、オンラインシステムには影響を与えませんでした。エラーコードはEDI-04-00344です。運用部の運用 一郎がこの問題を発見しました。問題の技術的な詳細として、スキーマバージョンの同期漏れが疑われています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00344', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00344', 'INC-2021-00344', '事象の詳細な調査を行った結果、連携JSONのスキーマ不一致が発生した原因として、スキーマバージョンの同期漏れが考えられることが確認されました。定例リリース直後のスキーマ変更が適切に通知されず、関連コンポーネントに反映されていなかったことが要因と考えられます。今後の再発防止策としては、リリース時のスキーマ変更についての情報共有を徹底し、バージョン管理のプロセスを見直す必要があります。', '事象の詳細な調査を行った結果、連携JSONのスキーマ不一致が発生した原因として、スキーマバージョンの同期漏れが考えられることが確認されました。定例リリース直後のスキーマ変更が適切に通知されず、関連コンポーネントに反映されていなかったことが要因と考えられます。今後の再発防止策としては、リリース時のスキーマ変更についての情報共有を徹底し、バージョン管理のプロセスを見直す必要があります。', TIMESTAMP WITH TIME ZONE '2021-05-31T04:14:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00507', 'INC-2021-00344', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-05-30T04:29:09+09:00', TIMESTAMP WITH TIME ZONE '2021-05-30T05:29:09+09:00', '【対応ログ】【CLU-07】初期対応', 'インシデント発生後、運用部は直ちに影響範囲の特定と問題の根本原因の調査を開始しました。連携JSONのスキーマの確認を行い、全件拒否の原因がスキーマ不一致であることを特定しました。また、関係者に対して事象の報告と、必要な修正作業を行うための指示を出しました。具体的には、スキーマのバージョンを確認し、更新されたスキーマに従ったデータ修正を行うことを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00363', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-10-19T09:01:47+09:00', TIMESTAMP WITH TIME ZONE '2021-10-19T09:31:47+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2021年10月19日09時01分47秒に、架空食品店A及び架空食品店Bの在庫登録において、在庫CSVの3行目以降が取込されない事象が発生しました。これはデータ移行バッチ実行中に起きた問題で、JANコード重複チェックの誤設定が原因と推測されます。09時33分47秒にこの問題が検知され、影響範囲はバッチ処理に限定され、オンラインサービスには影響がありません。エラーコードはMST-03-00363です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00363', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00363', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00363', 'INC-2021-00363', '事象の調査を行った結果、データ移行バッチ実行中に在庫CSVの取込が3行目以降で失敗していることが確認されました。具体的には、JANコード重複チェックの誤設定がこの問題を引き起こしていると特定しました。バッチ取込ワーカー及びMercury AWS APの動作に関連しており、即時の修正が求められます。', '事象の調査を行った結果、データ移行バッチ実行中に在庫CSVの取込が3行目以降で失敗していることが確認されました。具体的には、JANコード重複チェックの誤設定がこの問題を引き起こしていると特定しました。バッチ取込ワーカー及びMercury AWS APの動作に関連しており、即時の修正が求められます。', TIMESTAMP WITH TIME ZONE '2021-10-20T09:31:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00531', 'INC-2021-00363', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-10-19T09:46:47+09:00', TIMESTAMP WITH TIME ZONE '2021-10-19T10:46:47+09:00', '初期対応', '2021年10月19日09時34分に運用部の運用 一郎が対応を開始しました。問題の特定と解決に向けて、データ移行バッチの設定を確認し、JANコード重複チェックの誤設定を修正するための手続きを行います。進捗状況を随時確認し、影響を受けた顧客に状況を報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00379', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-08-13T22:30:37+09:00', TIMESTAMP WITH TIME ZONE '2021-08-14T00:30:37+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '2023-10-04T14:30:37+09:00に、株式会社ストッククラウドの顧客である架空食品店Bにおいて、CDCイベント欠損の事象が発生しました。この事象により、下流倉庫が未更新の状態となっており、影響範囲はバッチ処理のみに限られ、オンラインには影響がありませんでした。エラーコードはSYNC-03-00379です。発生契機はデータ移行バッチ実行中であり、CDCコネクタのオフセット巻戻しが推定原因とされております。発見者は営業部の花子で、問題は2023-10-04T17:01:37+09:00に検知されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00379', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00379', 'INC-2021-00379', '調査の結果、発生時にはデータ移行バッチが実行中であり、CDCイベント欠損が確認されました。具体的には、CDCコネクタのオフセットが巻き戻され、これが原因で下流倉庫が未更新であることが分かりました。データの整合性確保のため、今後の対応策を講じる必要があります。', '調査の結果、発生時にはデータ移行バッチが実行中であり、CDCイベント欠損が確認されました。具体的には、CDCコネクタのオフセットが巻き戻され、これが原因で下流倉庫が未更新であることが分かりました。データの整合性確保のため、今後の対応策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-08-15T00:30:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00556', 'INC-2021-00379', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-08-14T00:45:37+09:00', TIMESTAMP WITH TIME ZONE '2021-08-14T01:45:37+09:00', '初期対応', '初期対応として、影響を受けた顧客店舗POS（ゾーンB）に対して、データ移行バッチの再実行を行いました。また、CDCイベントのログを解析し、今後同様の事象が発生しないように監視体制を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00557', 'INC-2021-00379', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-08-14T02:15:37+09:00', TIMESTAMP WITH TIME ZONE '2021-08-14T03:15:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00381', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-02-01T18:25:51+09:00', TIMESTAMP WITH TIME ZONE '2021-02-01T18:55:51+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2021年2月1日18時25分51秒、株式会社ストッククラウドの顧客である架空食品店Bにおいて、在庫CSVの3行目以降が取込されない事象が発生しました。原因としては、データ移行バッチ実行中にJANコード重複チェックの誤設定が考えられます。この問題により、バッチ処理のみが影響を受け、オンラインにおけるサービスには影響がありませんでした。エラーコードはMST-03-00381です。運用部の運用 一郎がこの問題を発見し、18時57分51秒に検知しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00381', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00381', 'INC-2021-00381', '運用部の運用 一郎が発見したCSVバッチ取込の欠損問題について調査を行いました。データ移行バッチ実行中に、在庫CSVの3行目以降が取込されないことが確認されました。これにより、JANコード重複チェックの誤設定が推定原因とされ、早急な修正が必要です。影響を受けたのはバッチ処理のみで、オンラインサービスには問題がありませんでした。', '運用部の運用 一郎が発見したCSVバッチ取込の欠損問題について調査を行いました。データ移行バッチ実行中に、在庫CSVの3行目以降が取込されないことが確認されました。これにより、JANコード重複チェックの誤設定が推定原因とされ、早急な修正が必要です。影響を受けたのはバッチ処理のみで、オンラインサービスには問題がありませんでした。', TIMESTAMP WITH TIME ZONE '2021-02-02T18:55:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00559', 'INC-2021-00381', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-02-01T19:10:51+09:00', TIMESTAMP WITH TIME ZONE '2021-02-01T20:10:51+09:00', '【応答】【在庫マスター設定障害】CSVバッチ取込欠損', 'この問題に対して初期対応を実施しました。在庫マスター設定の見直しを行い、特にJANコードの重複チェック設定について重点的に確認しました。影響範囲がバッチ処理に限られているため、早急な対応が求められます。運用部からの情報をもとに、状況の早期改善に努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00386', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2021-08-24T06:10:17+09:00', TIMESTAMP WITH TIME ZONE '2021-08-24T06:40:17+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2021年8月24日06時10分17秒、株式会社ストッククラウドのMercuryサービスにおいて、同一アラートが短時間に数百件発報する事象が発生しました。これは大規模セール開始直前に観測されたもので、運用部門に影響を及ぼしました。発報の原因としてアラート抑制ルールの未設定が疑われております。06時45分17秒にこの事象が検知され、運用部の運用 一郎がこの問題に対応しました。エラーコードはMON-02-00386であり、影響を受けたコンポーネントはVenus Azure AP（ゾーンA）およびアラートマネージャです。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00386', 'INC-2021-00386', '発報から検知までの35分間、運用部門での監視が強化され、アラートの内容が確認されました。同一のアラートが大量に発報していることから、アラート抑制ルールが未設定であることが判明しました。大規模セールが近づいていたため、通常以上のトラフィックが予想されていたことも影響していると考えられます。この事象により、運用部門は監視体制の見直しを進める必要があります。', '発報から検知までの35分間、運用部門での監視が強化され、アラートの内容が確認されました。同一のアラートが大量に発報していることから、アラート抑制ルールが未設定であることが判明しました。大規模セールが近づいていたため、通常以上のトラフィックが予想されていたことも影響していると考えられます。この事象により、運用部門は監視体制の見直しを進める必要があります。', TIMESTAMP WITH TIME ZONE '2021-08-25T06:40:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00566', 'INC-2021-00386', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-08-24T06:55:17+09:00', NULL, '【対応ログ】【監視・可用性障害】アラート疲労に関する初期対応', '初期対応として、運用 一郎は発報されたアラートの内容をレビューし、アラート抑制ルールの設定を急務として認識しました。大規模セール前に発報が集中したため、直ちに対応策の策定を指示しました。また、影響を最小限に抑えるため、他のチームメンバーに状況を共有し、サポートを促しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00390', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2021-10-25T22:07:20+09:00', TIMESTAMP WITH TIME ZONE '2021-10-25T22:22:20+09:00', '【障害報告】【CLU-08】セッション突然切断', '・発生日時: 2023-10-01T10:15:00+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00390', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00390', 'INC-2021-00390', '調査を行った結果、インフラメンテナンス後にセッションTTL設定が誤って短縮されていたことが確認されました。このため、特定リージョンのユーザーにおいて操作中にセッションが切断される事象が発生しました。今後の対策としては、設定変更の管理と確認プロセスを見直す必要があります。また、再発防止策として、事前のテストを行うことが推奨されます。', '調査を行った結果、インフラメンテナンス後にセッションTTL設定が誤って短縮されていたことが確認されました。このため、特定リージョンのユーザーにおいて操作中にセッションが切断される事象が発生しました。今後の対策としては、設定変更の管理と確認プロセスを見直す必要があります。また、再発防止策として、事前のテストを行うことが推奨されます。', TIMESTAMP WITH TIME ZONE '2021-10-26T22:22:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00572', 'INC-2021-00390', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-10-25T22:37:20+09:00', TIMESTAMP WITH TIME ZONE '2021-10-25T23:37:20+09:00', '【初動対応】【CLU-08】セッション切断の初動対応', '初動対応として、影響を受けたユーザーへの情報提供を行い、セッションの再接続手順を案内しました。また、運用部内での情報共有を進め、原因究明に取り組む体制を整えました。セッションTTL設定の修正作業を行い、正常な状態に戻すための作業を即座に開始しました。影響を受けたリージョンのユーザーには謝罪を行い、状況の改善を図る方針としました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00398', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-09-13T11:10:36+09:00', TIMESTAMP WITH TIME ZONE '2021-09-13T11:40:36+09:00', '【障害報告】【CLU-09】アウトボックス滞留', '2021年9月13日11時10分36分に、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。この障害は定例リリース直後に起こり、アウトボックステーブルに滞留が生じ、通知遅延が発生しました。この影響により、サービス全体の一部機能に支障をきたしており、エラーコードはSYNC-05-00398です。検知は2021年9月13日11時25分36分に行われ、約15分後に確認されました。アウトボックスポーラーの停止が推定される原因として挙げられています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00398', 'INC-2021-00398', '障害発生の原因として、定例リリース直後のアウトボックステーブルの滞留が疑われています。運用部の運用 一郎が発見し、速やかに調査を開始しました。調査の結果、アウトボックスポーラーが停止していることが確認され、この停止が通知遅延を引き起こしている可能性が高いと考えられます。今後、再発防止策を検討し、適切な対応を行う必要があります。', '障害発生の原因として、定例リリース直後のアウトボックステーブルの滞留が疑われています。運用部の運用 一郎が発見し、速やかに調査を開始しました。調査の結果、アウトボックスポーラーが停止していることが確認され、この停止が通知遅延を引き起こしている可能性が高いと考えられます。今後、再発防止策を検討し、適切な対応を行う必要があります。', TIMESTAMP WITH TIME ZONE '2021-09-14T11:40:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00583', 'INC-2021-00398', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-09-13T11:55:36+09:00', TIMESTAMP WITH TIME ZONE '2021-09-13T12:55:36+09:00', '【初動対応】【CLU-09】アウトボックス滞留への対応', '初動対応として、運用部の運用 一郎が障害を発見後、直ちに状況を確認し、アウトボックスポーラーの状況を調査しました。初期の調査により、ポーラーの停止が確認され、再起動手続きを行いました。また、通知遅延の影響を受けている顧客への連絡を行い、障害の進捗について報告することにしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00403', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-12-16T22:33:27+09:00', TIMESTAMP WITH TIME ZONE '2021-12-16T23:03:27+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2021年12月16日22時33分、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店B様と架空食品店A様に対し、在庫登録が行えない事象が発生しました。具体的には、マスター更新後も旧設定で在庫登録が拒否される症状が確認されました。この問題は全テナントに波及し、特に定例リリース直後に発生したことが特徴です。影響を受けたコンポーネントはMercury AWS AP（Secondary）及びキャッシュレイヤであり、推定される原因としてキャッシュレイヤの無効化漏れが挙げられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00403', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00403', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00403', 'INC-2021-00403', '本事象の調査を行った結果、定例リリース直後にマスター更新が行われたにも関わらず、キャッシュレイヤが無効化されていなかったことが主な原因であると確認されました。これにより、マスター更新の不整合が生じ、在庫登録が拒否される事態が発生しました。今後はキャッシュの管理と更新手順を見直し、再発防止に努める必要があります。', '本事象の調査を行った結果、定例リリース直後にマスター更新が行われたにも関わらず、キャッシュレイヤが無効化されていなかったことが主な原因であると確認されました。これにより、マスター更新の不整合が生じ、在庫登録が拒否される事態が発生しました。今後はキャッシュの管理と更新手順を見直し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2021-12-17T23:03:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00590', 'INC-2021-00403', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-12-16T23:18:27+09:00', TIMESTAMP WITH TIME ZONE '2021-12-17T00:18:27+09:00', '【初期対応】', '発生から約32分後の23時05分に問題が検知され、即座に運用部の運用一郎が対応にあたりました。影響範囲を確認し、顧客への情報共有を行った上で、技術チームと連携し、キャッシュの強制無効化と再読み込みを実施しました。顧客には状況を説明し、必要なサポートを提供しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00591', 'INC-2021-00403', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-12-17T00:48:27+09:00', TIMESTAMP WITH TIME ZONE '2021-12-17T01:48:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00435', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-09-11T23:27:32+09:00', TIMESTAMP WITH TIME ZONE '2021-09-12T00:12:32+09:00', '【障害報告】【監視・可用性障害】トレースサンプリング過少', '2023年10月01日、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れの障害が発生いたしました。発生日時は2023年10月01日23時27分32秒です。障害の検知は2023年10月01日00時15分32秒に行われ、検知までに48分を要しました。影響を受けたのはMercury AWS Storageであり、運用部門の運用 一郎が発見者です。特に、分散トレースのサンプリング率が過少であったため、原因の特定が困難な状況となりました。推定される原因は、サンプリング率の本番設定誤りです。この問題は定例リリース直後に発生し、運用に影響を及ぼしました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00435', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00435', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00435', 'INC-2021-00435', '本事象に対する調査の結果、分散トレースのサンプリング率が不足していることが確認されました。原因特定が難しい状態であったため、運用部門はサンプリング設定の確認を進めています。定例リリース直後の影響を考慮し、サンプリング率の本番設定誤りが本問題の根本的原因であると推定しています。今後、再発防止策を講じるための検討が必要です。', '本事象に対する調査の結果、分散トレースのサンプリング率が不足していることが確認されました。原因特定が難しい状態であったため、運用部門はサンプリング設定の確認を進めています。定例リリース直後の影響を考慮し、サンプリング率の本番設定誤りが本問題の根本的原因であると推定しています。今後、再発防止策を講じるための検討が必要です。', TIMESTAMP WITH TIME ZONE '2021-09-13T00:12:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00639', 'INC-2021-00435', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-09-12T00:27:32+09:00', TIMESTAMP WITH TIME ZONE '2021-09-12T01:27:32+09:00', '【初期対応】【監視・可用性障害】トレースサンプリング過少', '初期対応として、運用部門は分散トレースのサンプリング率設定を速やかに確認し、必要な修正を行いました。また、チーム内での情報共有を行い、影響範囲の分析を実施しました。速やかに問題を解決し、運用の正常化を図るため、エラーコードMON-05-00435に基づく監視体制を強化する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00444', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2021-06-01T16:57:01+09:00', TIMESTAMP WITH TIME ZONE '2021-06-01T17:42:01+09:00', '【障害報告】【ストレージ・容量障害】インデックス再構築膨張', '2023-10-01T14:30:00+09:00に、株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れのインシデントが発生しました。顧客の架空食品店Aが影響を受け、特定リージョンのユーザーのみがインデックス再構築中に一時領域が枯渇し、正常な動作が阻害されました。発見者は運用部の運用 一郎であり、発生はインフラメンテナンス明けに確認されました。この問題は2023-10-01T14:53:00+09:00に検知され、23分後のことでした。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00444', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00444', 'INC-2021-00444', '本インシデントに関する調査を実施した結果、インフラメンテナンス明けにインデックス再構築中に一時領域が枯渇したことが原因と考えられます。再構築用一時領域のサイズ見積が不足していたことが推定されています。このような状況が発生した背景には、過去のデータを基にした容量計画の見直しが必要であると認識されます。', '本インシデントに関する調査を実施した結果、インフラメンテナンス明けにインデックス再構築中に一時領域が枯渇したことが原因と考えられます。再構築用一時領域のサイズ見積が不足していたことが推定されています。このような状況が発生した背景には、過去のデータを基にした容量計画の見直しが必要であると認識されます。', TIMESTAMP WITH TIME ZONE '2021-06-02T17:42:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00655', 'INC-2021-00444', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-06-01T17:57:01+09:00', TIMESTAMP WITH TIME ZONE '2021-06-01T18:57:01+09:00', '【初期対応】【ストレージ・容量障害】インデックス再構築膨張', 'インシデント発生後、直ちに運用部の運用 一郎が対応にあたり、再構築プロセスの停止を実施しました。一時領域の拡張を行い、再構築の再開を検討しました。顧客の架空食品店Aに対しては、進捗状況をリアルタイムで報告し、影響範囲の特定を徹底しました。エラーコードはSTR-07-00444として記録され、今後の対策を講じるための資料としました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00447', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2021-03-03T10:16:24+09:00', TIMESTAMP WITH TIME ZONE '2021-03-03T10:46:24+09:00', '【障害報告】【在庫マスター設定障害】商品同期全件失敗', '2023年10月05日、株式会社ストッククラウドの顧客である架空食品店Bのマスター設定ミスによる在庫登録失敗が発生しました。このインシデントは、顧客オンボーディング当日に商品マスター同期後に在庫登録が全件失敗するという症状を呈しました。発見者は運用部の運用 一郎で、問題はMercury AWS APに関連しています。エラーコードはMST-04-00447です。推定原因として、カテゴリ階層の循環参照が考えられます。この問題により、サービス全体の一部機能に影響が及ぶ可能性があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00447', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00447', 'INC-2021-00447', '調査の結果、顧客オンボーディング当日に発生した商品マスター同期後の在庫登録失敗の原因は、カテゴリ階層の循環参照によるものであることが確認されました。この循環参照により、在庫マスター設定が正常に機能せず、全件失敗が発生しました。今後、同様の問題を回避するための対策を講じる必要があります。', '調査の結果、顧客オンボーディング当日に発生した商品マスター同期後の在庫登録失敗の原因は、カテゴリ階層の循環参照によるものであることが確認されました。この循環参照により、在庫マスター設定が正常に機能せず、全件失敗が発生しました。今後、同様の問題を回避するための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-03-04T10:46:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00659', 'INC-2021-00447', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-03T11:01:24+09:00', TIMESTAMP WITH TIME ZONE '2021-03-03T12:01:24+09:00', '【初期対応】【在庫マスター設定障害】商品同期全件失敗', '初期対応として、運用部の運用 一郎が問題の状況を確認し、カテゴリ階層の循環参照に関する詳細な調査を実施しました。即座に開発チームにエスカレーションし、必要な修正を行う方針を定めました。顧客には、状況を説明し、問題解決に向けた進捗を随時報告することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00460', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2021-03-13T06:10:21+09:00', TIMESTAMP WITH TIME ZONE '2021-03-13T06:40:21+09:00', '【障害報告】【性能・負荷障害】ピーク時画面10秒', '2021年3月13日06時10分21秒に発生したインシデントにおいて、ピーク時に画面表示が10秒以上かかる状況が確認されました。本障害は大規模セール開始直前に発生し、全テナントに影響を及ぼすものでした。推定原因としては、キャンペーンによるアクセス急増が考えられます。技術的には、Venus Azure AP（DRサイト）においてAPサーバークラスタの性能・負荷障害が発生し、結果として画面遅延が生じました。なお、エラーコードはPRF-01-00460です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00460', 'INC-2021-00460', '本障害の調査を実施した結果、キャンペーンによるアクセス急増が主な要因であることが確認されました。特に、大規模セール開始直前の時期において多くのユーザーが同時にアクセスしたため、Venus Azure AP（DRサイト）のAPサーバークラスタに負荷がかかり、応答遅延が発生しました。今後、アクセス集中対策を検討し、再発防止策を講じる必要があります。', '本障害の調査を実施した結果、キャンペーンによるアクセス急増が主な要因であることが確認されました。特に、大規模セール開始直前の時期において多くのユーザーが同時にアクセスしたため、Venus Azure AP（DRサイト）のAPサーバークラスタに負荷がかかり、応答遅延が発生しました。今後、アクセス集中対策を検討し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-03-14T06:40:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00680', 'INC-2021-00460', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-13T06:55:21+09:00', TIMESTAMP WITH TIME ZONE '2021-03-13T07:55:21+09:00', '【初期対応】【性能・負荷障害】ピーク時画面10秒', '初期対応として、運用部の運用 一郎が状況を把握し、即座にアクセス集中を緩和するための対策に着手しました。まず、負荷分散の調整を行い、一時的にピーク時のアクセスを制限しました。加えて、システム監視を強化し、リアルタイムでのパフォーマンス分析を実施しました。これにより、一時的な遅延の改善が図られましたが、根本的な問題解決にはさらなる対策が必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00681', 'INC-2021-00460', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-13T08:25:21+09:00', TIMESTAMP WITH TIME ZONE '2021-03-13T09:25:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00501', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-05-24T03:38:20+09:00', TIMESTAMP WITH TIME ZONE '2021-05-24T05:38:20+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '2021年5月24日03時38分に、株式会社ストッククラウドのサービスMercuryにおいて、顧客架空食品店Bで棚卸突合失敗が発生しました。この問題により、顧客店舗POSにおける実地棚卸数とシステム在庫が大幅に乖離する事象が確認されました。影響範囲は同一顧客の全店舗で、月末棚卸の開始時に発生しました。エラーコードはINV-01-00501です。弊社営業部の花子がこの問題を発見し、6時33分に検知しました。検知までに175分を要しました。技術的な詳細としては、棚卸スナップショット時刻のずれが疑われています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00501', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00501', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00501', 'INC-2021-00501', '本インシデントに対する調査を実施しました。まず、棚卸スナップショット時刻のずれが実地棚卸数とシステム在庫の乖離の原因である可能性が高いことが確認されました。この問題は月末棚卸の開始時に発生することが多く、全店舗に影響を及ぼしています。今後の対策として、スナップショット時刻の設定を見直し、再発防止に努める必要があります。', '本インシデントに対する調査を実施しました。まず、棚卸スナップショット時刻のずれが実地棚卸数とシステム在庫の乖離の原因である可能性が高いことが確認されました。この問題は月末棚卸の開始時に発生することが多く、全店舗に影響を及ぼしています。今後の対策として、スナップショット時刻の設定を見直し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2021-05-25T05:38:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00738', 'INC-2021-00501', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-05-24T05:53:20+09:00', TIMESTAMP WITH TIME ZONE '2021-05-24T06:53:20+09:00', '【初期応答】【棚卸・POS突合障害】初期対応', '本障害に関する初期対応を実施しました。まず、影響を受けた店舗の確認を行い、実地棚卸数とシステム在庫の差異を把握しました。加えて、問題の根本原因である棚卸スナップショット時刻のずれについて、技術チームに報告し、早急な対策を講じるよう指示しました。今後、詳細な調査を進め、必要に応じて追加の対応を行って参ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00739', 'INC-2021-00501', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-05-24T07:23:20+09:00', TIMESTAMP WITH TIME ZONE '2021-05-24T08:23:20+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00507', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2021-06-14T15:05:23+09:00', TIMESTAMP WITH TIME ZONE '2021-06-14T17:05:23+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '2021年06月14日15時05分に、株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Aおよび架空食品店Bの顧客店舗POSでアウトボックステーブル滞留による通知遅延が発生しました。この問題は定例リリース直後に発生し、アウトボックスポーラーの停止が推定原因と考えられています。障害は2021年06月14日16時47分に検知され、通知遅延が発生していることが確認されました。この障害はサービス全体の一部機能に影響を及ぼすもので、迅速な対応が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00507', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00507', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00507', 'INC-2021-00507', '本障害に対する調査を実施した結果、定例リリース直後にアウトボックステーブルが滞留し、通知遅延が発生したことが明らかとなりました。特に、アウトボックスポーラーの停止が原因である可能性が高いと考えられます。今後はその詳細をさらに深堀りし、再発防止策を講じる必要があります。', '本障害に対する調査を実施した結果、定例リリース直後にアウトボックステーブルが滞留し、通知遅延が発生したことが明らかとなりました。特に、アウトボックスポーラーの停止が原因である可能性が高いと考えられます。今後はその詳細をさらに深堀りし、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2021-06-15T17:05:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00747', 'INC-2021-00507', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-06-14T17:20:23+09:00', TIMESTAMP WITH TIME ZONE '2021-06-14T18:20:23+09:00', '【初動対応】【データ同期・整合性障害】アウトボックス滞留', '初動対応として、直ちにシステムの監視を強化し、アウトボックスポーラーの稼働状況を確認しました。必要に応じて手動で再起動を行い、状況の改善を図りました。また、顧客に対して障害発生の通知を行い、進捗状況についても随時報告を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00748', 'INC-2021-00507', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-06-14T18:50:23+09:00', TIMESTAMP WITH TIME ZONE '2021-06-14T19:50:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00543', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2021-04-01T18:42:41+09:00', TIMESTAMP WITH TIME ZONE '2021-04-01T19:42:41+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2023年10月01日18時42分41秒、株式会社ストッククラウドのサービスMercuryにおいて、顧客「架空食品店B」と「架空食品店A」に対しネットワーク障害が発生しました。影響範囲は同一顧客の全店舗であり、SD-WANが劣化回線を選択したことにより遅延が増大しました。この事象は、大規模セール開始直前に発生し、営業部の花子が発見しました。2023年10月01日19時52分41秒に検知されるまで70分間の影響があり、エラーコードはNW-10-00543です。推定原因はSD-WANポリシーの閾値設定誤りと考えられます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00543', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00543', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00543', 'INC-2021-00543', '本事象の調査結果として、大規模セール開始直前にSD-WANが劣化回線を選択した結果、遅延が増大したことが確認されました。特にSD-WANポリシーの閾値設定に問題があったと推測されます。今後の手段としては、ポリシーの見直しと適切な監視体制の強化が求められます。', '本事象の調査結果として、大規模セール開始直前にSD-WANが劣化回線を選択した結果、遅延が増大したことが確認されました。特にSD-WANポリシーの閾値設定に問題があったと推測されます。今後の手段としては、ポリシーの見直しと適切な監視体制の強化が求められます。', TIMESTAMP WITH TIME ZONE '2021-04-02T19:42:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00802', 'INC-2021-00543', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-04-01T19:57:41+09:00', TIMESTAMP WITH TIME ZONE '2021-04-01T20:57:41+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '障害発生後、迅速に調査を開始し、SD-WANポリシーの設定を確認しました。劣化回線選択の原因を特定し、修正作業を実施しました。また、顧客への情報提供を行い、状況の把握を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00803', 'INC-2021-00543', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2021-04-01T21:27:41+09:00', TIMESTAMP WITH TIME ZONE '2021-04-01T22:27:41+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2021-00556', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2021-03-23T10:57:02+09:00', TIMESTAMP WITH TIME ZONE '2021-03-23T11:12:02+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2023-10-10T09:15:00+09:00に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bに対して運用者の作業ミスによるアクセス障害が発生しました。運用コンソールでのCookie SameSite設定の不具合により、埋込画面が認証不可となりました。この事象は、定例リリース直後に発生し、運用 一郎（運用部）が発見しました。検知は2023-10-10T09:45:00+09:00で、約30分の遅延がありました。エラーコードはAUTH-06-00556です。この影響を受けたのは架空食品店Bのみです。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00556', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2021-00556', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00556', 'INC-2021-00556', '今回のアクセス障害の原因として、定例リリース直後にCookie SameSite設定の変更が考えられます。運用 一郎が報告したところによれば、SameSite属性を変更したことで埋込画面が認証不可となった模様です。この影響範囲は架空食品店Bに限られており、他の店舗には影響が出ていないことを確認済みです。', '今回のアクセス障害の原因として、定例リリース直後にCookie SameSite設定の変更が考えられます。運用 一郎が報告したところによれば、SameSite属性を変更したことで埋込画面が認証不可となった模様です。この影響範囲は架空食品店Bに限られており、他の店舗には影響が出ていないことを確認済みです。', TIMESTAMP WITH TIME ZONE '2021-03-24T11:12:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00824', 'INC-2021-00556', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2021-03-23T11:27:02+09:00', TIMESTAMP WITH TIME ZONE '2021-03-23T12:27:02+09:00', '【対応ログ】【CLU-08】初期対応', '運用 一郎が初期対応を行いました。まず、Cookie設定を確認し、SameSite属性の変更が影響しているかを調査しました。その際、運用コンソールでの設定ミスが判明し、速やかに修正を行いました。認証・セッションに関連する問題は重大であり、早急な対応が必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
