INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00205', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-04-04T01:46:24+09:00', TIMESTAMP WITH TIME ZONE '2023-04-04T02:16:24+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2023年4月4日01時46分24秒に、株式会社ストッククラウドのサービスMercuryにおいて、OAuthトークン失効が発生し、POS連携が中断しました。この障害は、架空食品店Aにおいて発生しました。発見者は運用部の運用 一郎であり、障害の検知は2023年4月4日02時24分24秒に行われました。検知までの時間は38分でした。今回は単一店舗に限定されており、影響範囲は架空食品店AのPOSシステムにのみ及んでいます。推定原因としては、リフレッシュトークン保存先の障害が疑われます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00205', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00205', 'INC-2023-00205', '発生したOAuthトークン失効について調査を行った結果、年末年始の稼働切替時におけるリフレッシュトークン保存先に障害があったことが原因と考えられます。この問題により、POS連携が中断され、架空食品店Aでの取引に影響を及ぼしました。今後の対策として、リフレッシュトークンの保存先の信頼性を向上させる必要があります。', '発生したOAuthトークン失効について調査を行った結果、年末年始の稼働切替時におけるリフレッシュトークン保存先に障害があったことが原因と考えられます。この問題により、POS連携が中断され、架空食品店Aでの取引に影響を及ぼしました。今後の対策として、リフレッシュトークンの保存先の信頼性を向上させる必要があります。', TIMESTAMP WITH TIME ZONE '2023-04-05T02:16:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00302', 'INC-2023-00205', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-04-04T02:31:24+09:00', TIMESTAMP WITH TIME ZONE '2023-04-04T03:31:24+09:00', '初期対応', '障害が発生した時点で、運用部の運用 一郎が迅速に対応し、問題の特定を行いました。初期対応として、トークンの再発行を行い、POS連携を復旧させることに成功しました。また、リフレッシュトークンの保存先に関する調査を開始し、根本原因の特定に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00215', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-01-15T18:06:20+09:00', TIMESTAMP WITH TIME ZONE '2023-01-15T18:36:20+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2023年01月15日18時06分20秒に発生したインシデントは、株式会社ストッククラウドのサービスMercuryにおけるマスター設定ミスによる在庫登録失敗です。この問題は、バルクAPIが部分失敗しロールバック未完了の症状を引き起こしました。発生契機はデータ移行バッチの実行中であり、サービス全体の一部機能に影響を及ぼしました。推定原因として、部分成功時の補償トランザクションが欠如していることが考えられます。エラーコードはEDI-10-00215であり、影響を受けたコンポーネントはMercury AWS AP（Secondary）及び在庫登録APIです。このインシデントは18分後の検知に至りましたが、顧客である架空食品店Bに対しては早急な対応が求められました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00215', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00215', 'INC-2023-00215', 'インシデントの調査において、データ移行バッチ実行中にバルクAPIが部分的に失敗し、ロールバックが未完了であることが確認されました。原因として疑われるのは、部分成功時の補償トランザクション欠如です。この問題の影響は、サービス全体の一部機能に及び、特に在庫登録APIにおいて目立ちました。運用部の運用 一郎がこの問題を発見し、速やかに対処する必要がありました。本調査の結果を元に、再発防止策を講じることが', 'インシデントの調査において、データ移行バッチ実行中にバルクAPIが部分的に失敗し、ロールバックが未完了であることが確認されました。原因として疑われるのは、部分成功時の補償トランザクション欠如です。この問題の影響は、サービス全体の一部機能に及び、特に在庫登録APIにおいて目立ちました。運用部の運用 一郎がこの問題を発見し、速やかに対処する必要がありました。本調査の結果を元に、再発防止策を講じることが重要です。', TIMESTAMP WITH TIME ZONE '2023-01-16T18:36:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00316', 'INC-2023-00215', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-15T18:51:20+09:00', TIMESTAMP WITH TIME ZONE '2023-01-15T19:51:20+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗の初期対応', '初期対応として、運用部の運用 一郎が即座に障害の原因を特定し、影響を受けた在庫登録APIの状況を確認しました。また、バルクAPIの部分失敗の解消に向けたロールバック処理を手動で実施しました。顧客である架空食品店Bには、このインシデントについての情報提供を行い、状況説明と早急な復旧についてお知らせしました。今後の再発防止に向けて、管理体制の強化も検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00216', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-05-29T11:23:54+09:00', TIMESTAMP WITH TIME ZONE '2023-05-29T12:23:54+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023年5月29日11時23分54秒に株式会社ストッククラウドの顧客、架空食品店Aにおいて、特定拠点のみAPI呼び出しが失敗する事象が発生しました。問題が発生したのは顧客拠点のネットワークで、発見者は営業部の花子です。この問題の検知は12時50分54秒であり、発生から87分後に確認されました。発生契機は新規店舗追加の初日であり、影響範囲は単一店舗に限られています。推定原因としては店舗LANのスイッチ故障が疑われています。エラーコードはNW-02-00216です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00216', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00216', 'INC-2023-00216', '調査の結果、特定拠点においてAPI呼び出しが失敗している原因は、店舗LANのスイッチ故障であることが確認されました。この問題は新規店舗追加の初日というタイミングで発生しました。影響を受けたのは顧客拠点ネットワークのゾーンBおよび顧客側ファイアウォールです。今後、LAN機器の点検および交換作業が必要です。', '調査の結果、特定拠点においてAPI呼び出しが失敗している原因は、店舗LANのスイッチ故障であることが確認されました。この問題は新規店舗追加の初日というタイミングで発生しました。影響を受けたのは顧客拠点ネットワークのゾーンBおよび顧客側ファイアウォールです。今後、LAN機器の点検および交換作業が必要です。', TIMESTAMP WITH TIME ZONE '2023-05-30T12:23:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00317', 'INC-2023-00216', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-05-29T12:38:54+09:00', TIMESTAMP WITH TIME ZONE '2023-05-29T13:38:54+09:00', '初期対応', '初期対応として、顧客拠点のLAN機器の確認を実施し、スイッチの故障を特定しました。故障したスイッチの交換作業を進め、なるべく早急にAPIの正常化を図るため、技術チームが対応にあたる予定です。また、顧客には状況報告を行い、復旧作業の進捗を随時連絡します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00221', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-02-19T10:26:40+09:00', TIMESTAMP WITH TIME ZONE '2023-02-19T11:26:40+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '・発生日時: 2023年2月19日 10:26
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00221', 'INC-2023-00221', '2023年2月19日 11:12に502エラーが発生したとの報告を受け、調査を開始。顧客拠点NWにて代理サーバー経由でのアクセスが影響を受けていることを確認。プロキシの設定を見直したところ、上流タイムアウト設定が適切でないことが判明。これにより再発防止策を検討中。', '2023年2月19日 11:12に502エラーが発生したとの報告を受け、調査を開始。顧客拠点NWにて代理サーバー経由でのアクセスが影響を受けていることを確認。プロキシの設定を見直したところ、上流タイムアウト設定が適切でないことが判明。これにより再発防止策を検討中。', TIMESTAMP WITH TIME ZONE '2023-02-20T11:26:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00325', 'INC-2023-00221', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-02-19T11:41:40+09:00', TIMESTAMP WITH TIME ZONE '2023-02-19T12:41:40+09:00', '【初期対応】【顧客ネットワーク障害】代理サーバー502', '初期対応として、顧客に状況を報告し、502エラーの影響を受ける店舗に対して代理サーバーの利用停止を提案。プロキシ設定の確認を行い、必要な修正を実施。顧客には進捗を逐次報告し、問題解決に向けての対応を継続中。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00326', 'INC-2023-00221', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-02-19T13:11:40+09:00', TIMESTAMP WITH TIME ZONE '2023-02-19T14:11:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00226', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-03-16T16:52:48+09:00', TIMESTAMP WITH TIME ZONE '2023-03-16T17:22:48+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2023年3月16日16時52分に、株式会社ストッククラウドのMercuryサービスにおいて、在庫マスター設定ミスによる在庫登録失敗が発生しました。顧客である架空食品店A及び架空食品店Bで、マスター更新後も旧設定で在庫登録が拒否される現象が確認されました。この問題は定例リリース直後に発生しており、全テナントに波及する影響を及ぼしました。推定原因としてはキャッシュレイヤの無効化漏れが考えられ、これにより不整合が生じ、正常な在庫登録が行えない状態が続いています。運用部の運用 一郎がこの問題を発見し、17時32分に検知しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00226', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00226', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00226', 'INC-2023-00226', '本インシデントに関する調査を行いました。定例リリース後、マスター更新が行われたにもかかわらず、キャッシュレイヤが適切に無効化されなかったため、旧設定が残り、在庫登録に失敗しました。この問題は全テナントに影響を与え、迅速な対策が求められました。技術的な詳細として、キャッシュの更新漏れや設定ミスが原因であることが確認され、今後の対策としてキャッシュの無効化プロセスの見直しが必要とされます。', '本インシデントに関する調査を行いました。定例リリース後、マスター更新が行われたにもかかわらず、キャッシュレイヤが適切に無効化されなかったため、旧設定が残り、在庫登録に失敗しました。この問題は全テナントに影響を与え、迅速な対策が求められました。技術的な詳細として、キャッシュの更新漏れや設定ミスが原因であることが確認され、今後の対策としてキャッシュの無効化プロセスの見直しが必要とされます。', TIMESTAMP WITH TIME ZONE '2023-03-17T17:22:48+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00333', 'INC-2023-00226', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-16T17:37:48+09:00', NULL, '【初期対応】【在庫マスター設定障害】キャッシュ不整合登録', '本インシデントの初期対応として、まずは影響を受けた顧客に対して迅速な情報提供を行いました。次に、キャッシュレイヤの状態を確認し、必要に応じて手動で無効化を行いました。また、運用部の運用 一郎を中心に、問題の再発防止に向けた調査を進めると共に、適切なドキュメントを作成し、関係者への周知を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00258', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-09-28T22:39:17+09:00', TIMESTAMP WITH TIME ZONE '2023-09-28T23:09:17+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2023年10月01日22時39分、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aに対して発生した障害について報告します。読取レプリカ遅延により在庫照会が古い値となり、顧客に混乱を引き起こしました。原因としては、レプリケーション遅延の監視閾値超過が推定されます。特定リージョンのユーザーに影響が及び、大規模セール開始直前という発生契機が重なったため、問題が顕在化しました。エラーコードはSYNC-02-00258で、この問題はMercury AWS AP（Secondary）で発生しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00258', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00258', 'INC-2023-00258', '運用部の運用 一郎が本障害の調査を開始しました。大規模セール開始直前の状況で、読取レプリカの遅延が確認され、在庫照会が古い値を返す事象が発生しました。レプリケーション遅延の監視閾値を超過している可能性が高く、詳細な調査が必要です。特定リージョンのユーザーのみが影響を受けているため、広範な影響が今後予想されることから、迅速な対応が求められます。', '運用部の運用 一郎が本障害の調査を開始しました。大規模セール開始直前の状況で、読取レプリカの遅延が確認され、在庫照会が古い値を返す事象が発生しました。レプリケーション遅延の監視閾値を超過している可能性が高く、詳細な調査が必要です。特定リージョンのユーザーのみが影響を受けているため、広範な影響が今後予想されることから、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2023-09-29T23:09:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00381', 'INC-2023-00258', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-09-28T23:24:17+09:00', TIMESTAMP WITH TIME ZONE '2023-09-29T00:24:17+09:00', '【初期対応】【データ同期・整合性障害】読取レプリカ遅延', '運用 一郎が本件について、まずはMercury AWS APの状態を確認しました。レプリカ遅延を解消するために、設定を見直し、監視閾値の調整を行いました。また、影響を受けた顧客に対して、在庫情報の確認を行う旨の連絡を実施しました。今後の対策として、レプリケーションの監視体制を強化し、再発防止に努める方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
