INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00274', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-01-15T22:03:26+09:00', TIMESTAMP WITH TIME ZONE '2023-01-15T22:33:26+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2023年1月15日22時03分26秒に発生したインシデントについて報告いたします。本事象は、株式会社ストッククラウドが提供するMercuryサービスにおけるマスター設定ミスによる在庫登録失敗です。スナップショット復元後に在庫整合が崩れる症状が確認され、影響範囲は全テナントに波及しています。推定原因としては、復元ポイントのトランザクションログが欠落していることが挙げられます。特にデータ移行バッチ実行中にこの問題が発生したことが判明しました。エラーコードはSYNC-09-00274です。運用部の運用 一郎が本事象を発見し、検知までに26分を要しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00274', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00274', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00274', 'INC-2023-00274', 'インシデントの調査を行いました。データ移行バッチ実行中にスナップショット復元が行われ、その後に在庫整合が崩れる事象が発生しました。復元ポイントのトランザクションログ欠落が原因として考えられており、これによりデータ同期・整合性に影響を及ぼす結果となりました。現在のところ、全テナントに影響が及んでいるため、早急な対応が求められます。', 'インシデントの調査を行いました。データ移行バッチ実行中にスナップショット復元が行われ、その後に在庫整合が崩れる事象が発生しました。復元ポイントのトランザクションログ欠落が原因として考えられており、これによりデータ同期・整合性に影響を及ぼす結果となりました。現在のところ、全テナントに影響が及んでいるため、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2023-01-16T22:33:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00406', 'INC-2023-00274', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-15T22:48:26+09:00', TIMESTAMP WITH TIME ZONE '2023-01-15T23:48:26+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合', 'この度は、スナップショット復元不整合の発生によりご迷惑をおかけし、誠に申し訳ございません。現在、当該事象の解決に向けて、運用部の運用 一郎を中心に調査を進めております。影響を受けた顧客には適宜情報を提供し、迅速に問題を解決できるよう努めてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00280', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2023-08-01T08:33:36+09:00', TIMESTAMP WITH TIME ZONE '2023-08-01T09:03:36+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2023年8月1日08時33分36秒に、株式会社ストッククラウドのサービスMercuryにおいて、運用部の運用一郎が発見した障害について報告いたします。障害の症状は、ログに相関IDが欠落しており、横断検索が不可能な状態です。本障害は定例リリース直後に発生し、運用部門に影響を及ぼしました。推定原因としては、ログフォーマット変更のロールアウト漏れが考えられます。エラーコードはMON-09-00280であり、影響コンポーネントはVenus Azure AP（ゾーンA）およびログパイプラインです。今後、詳細な調査が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00280', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00280', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00280', 'INC-2023-00280', '本障害について調査した結果、定例リリース後にログフォーマットが変更されたにも関わらず、相関IDがログに含まれていないことが確認されました。これにより、運用部門が必要な横断検索を行うことができず、対応に支障をきたしました。原因を特定するために、ログの生成過程やリリース管理の手順を見直す必要があります。今後も継続して監視を強化し、再発防止策を講じて参ります。', '本障害について調査した結果、定例リリース後にログフォーマットが変更されたにも関わらず、相関IDがログに含まれていないことが確認されました。これにより、運用部門が必要な横断検索を行うことができず、対応に支障をきたしました。原因を特定するために、ログの生成過程やリリース管理の手順を見直す必要があります。今後も継続して監視を強化し、再発防止策を講じて参ります。', TIMESTAMP WITH TIME ZONE '2023-08-02T09:03:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00414', 'INC-2023-00280', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-08-01T09:18:36+09:00', TIMESTAMP WITH TIME ZONE '2023-08-01T10:18:36+09:00', '【対応報告】【監視・可用性障害】ログ相関ID欠落', '本障害に関する初期対応として、運用部の担当者がログの検証を行い、相関ID欠落の原因としてログフォーマット変更のロールアウト漏れを確認しました。即時に運用部門内で情報共有を行い、影響範囲を把握しました。また、関連するシステムの監視を強化し、今後の定例リリース時には事前に十分な確認を行うことを約束します。引き続き、状況を注視し、必要に応じて追加対応を実施します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00281', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-08-08T20:50:07+09:00', TIMESTAMP WITH TIME ZONE '2023-08-08T21:20:07+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023年8月8日20時50分に、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。症状として、マスター更新と在庫が二重反映される事象が確認されました。この問題は、同一顧客の全店舗に影響を及ぼし、エラーコードはSYNC-01-00281です。また、発生契機は定例リリース直後であり、推定原因としてイベント順序の逆転配信が考えられます。これにより、在庫データの整合性が損なわれ、業務に影響を及ぼす可能性がありました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00281', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00281', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00281', 'INC-2023-00281', '障害発生後、原因を特定するための調査を実施しました。調査の結果、定例リリース直後にマスター更新と在庫データに二重反映が見られ、イベント順序の逆転配信が関与している可能性が高いことが判明しました。この障害が発生した背景には、リリース後のデータ同期処理の不具合が根底にあると考えられます。今後は、より厳密なテストを行い、再発防止策を講じる必要があります。', '障害発生後、原因を特定するための調査を実施しました。調査の結果、定例リリース直後にマスター更新と在庫データに二重反映が見られ、イベント順序の逆転配信が関与している可能性が高いことが判明しました。この障害が発生した背景には、リリース後のデータ同期処理の不具合が根底にあると考えられます。今後は、より厳密なテストを行い、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2023-08-09T21:20:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00415', 'INC-2023-00281', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-08-08T21:35:07+09:00', TIMESTAMP WITH TIME ZONE '2023-08-08T22:35:07+09:00', '【障害対応】【データ同期・整合性障害】マスター在庫二重反映', '障害発生を受け、運用部の運用 一郎が迅速に対応にあたりました。初動対応として、影響を受けた店舗の在庫状況を確認し、必要に応じて手動で在庫データを修正しました。また、関連システムのログを収集し、問題原因の詳細な分析を開始しました。これにより、二重反映の影響を最小限に抑える措置を講じることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00311', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-08-20T14:24:43+09:00', TIMESTAMP WITH TIME ZONE '2023-08-20T16:24:43+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '株式会社ストッククラウドのMercuryにおいて、2023年9月15日14時24分43秒に棚卸突合失敗が発生しました。顧客店舗POSにおいて同期メッセージがデッドレターに大量蓄積し、影響範囲はバッチ処理のみに限られ、オンラインサービスには影響がありません。発見者は営業部の花子さんで、16時06分43秒に検知されました。発生契機はデータ移行バッチの実行中で、考えられる推定原因はデッドレター再処理ジョブの未設定です。この問題は、メッセージキューにおけるデータ同期・整合性の障害として認識されており、早急な対応が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00311', 'INC-2023-00311', '調査の結果、2023年9月15日に発生したデッドレターの大量蓄積は、データ移行バッチ実行中におけるメッセージキューの不具合によるものでした。デッドレター再処理ジョブが未設定であったため、正常な処理が行われず、蓄積したデータが処理されない状態が続きました。この問題により、顧客店舗POSのバッチ処理が遅延し、影響が出る可能性があります。', '調査の結果、2023年9月15日に発生したデッドレターの大量蓄積は、データ移行バッチ実行中におけるメッセージキューの不具合によるものでした。デッドレター再処理ジョブが未設定であったため、正常な処理が行われず、蓄積したデータが処理されない状態が続きました。この問題により、顧客店舗POSのバッチ処理が遅延し、影響が出る可能性があります。', TIMESTAMP WITH TIME ZONE '2023-08-21T16:24:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00457', 'INC-2023-00311', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-08-20T16:39:43+09:00', TIMESTAMP WITH TIME ZONE '2023-08-20T17:39:43+09:00', '【対応ログ】【データ同期・整合性障害】初期対応', '2023年9月15日16時10分に営業部の花子さんより、デッドレターの蓄積が発見され、初期対応を開始しました。メッセージキューの状態を確認し、デッドレター再処理ジョブの設定が行われていないことを特定。直ちに設定作業を行い、蓄積したデータの再処理を進めています。今後、同様の事象が発生しないよう、定期的な監視の強化を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00317', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2023-03-21T04:34:49+09:00', TIMESTAMP WITH TIME ZONE '2023-03-21T04:49:49+09:00', '【障害報告】【運用操作・権限障害】メンテ解除失敗', '2023年3月21日、株式会社ストッククラウドの運用コンソールにおいて、運用 一郎がメンテナンスモード解除操作を試みたところ、解除操作が失敗しました。これは、インフラメンテナンス明けの影響で起こった事象です。メンテナンスフラグの残留が原因で、サービス全体の一部機能が影響を受ける事態となりました。顧客である架空食品店Aおよび架空食品店Bにも影響を及ぼしており、運用部ではこの問題の迅速な解決に向けて動いています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00317', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00317', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00317', 'INC-2023-00317', 'インフラメンテナンス明けのメンテナンスモード解除操作が失敗したことについて調査を行いました。運用 一郎の操作ログを確認したところ、メンテナンスフラグが残存していることが確認されました。このフラグが原因でメンテナンスモードの解除が正常に行えなかったため、適切な権限を持った運用担当者が再度確認し、フラグを解除する必要があります。', 'インフラメンテナンス明けのメンテナンスモード解除操作が失敗したことについて調査を行いました。運用 一郎の操作ログを確認したところ、メンテナンスフラグが残存していることが確認されました。このフラグが原因でメンテナンスモードの解除が正常に行えなかったため、適切な権限を持った運用担当者が再度確認し、フラグを解除する必要があります。', TIMESTAMP WITH TIME ZONE '2023-03-22T04:49:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00466', 'INC-2023-00317', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-21T05:04:49+09:00', TIMESTAMP WITH TIME ZONE '2023-03-21T06:04:49+09:00', '【初動対応】【運用操作・権限障害】メンテ解除失敗', '運用 一郎より、メンテナンスモード解除操作に失敗したとの報告がありました。影響を受けた顧客に対しては、状況を説明し、メンテナンスの進行状況を把握するためのフォローアップを行っています。また、運用部内で迅速に原因を追究し、顧客への影響を最小限に抑えるための対応策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00341', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-03-30T19:02:23+09:00', TIMESTAMP WITH TIME ZONE '2023-03-30T21:02:23+09:00', '【障害報告】【棚卸・POS突合障害】店舗間転送未反映', '2023年3月30日19時02分23秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客である架空食品店Aの店舗間在庫転送が発生いたしました。発生当初、在庫転送が送信側のみ減算される症状が確認されました。この障害は新規店舗追加の初日に発生したため、影響範囲は同一顧客の全店舗に及びました。エラーコードはINV-08-00341であり、店舗間転送におけるトランザクションの二相コミット失敗が推定原因として挙げられます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00341', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00341', 'INC-2023-00341', '本事象の調査を行った結果、新規店舗追加の初日であることから、店舗間在庫転送が正しく処理されていないことが判明いたしました。特に、トランザクションにおける二相コミットが失敗した可能性が高いと考えられます。このため、在庫転送サービスにおいて、適切なエラーハンドリングと再試行の実装が必要です。', '本事象の調査を行った結果、新規店舗追加の初日であることから、店舗間在庫転送が正しく処理されていないことが判明いたしました。特に、トランザクションにおける二相コミットが失敗した可能性が高いと考えられます。このため、在庫転送サービスにおいて、適切なエラーハンドリングと再試行の実装が必要です。', TIMESTAMP WITH TIME ZONE '2023-03-31T21:02:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00501', 'INC-2023-00341', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-03-30T21:17:23+09:00', TIMESTAMP WITH TIME ZONE '2023-03-30T22:17:23+09:00', '【初期対応】【棚卸・POS突合障害】店舗間転送未反映', 'インシデントが発生した時点で、営業部の花子が状況を把握し、顧客へ影響範囲について通知いたしました。また、技術チームに対して初期調査を依頼し、トランザクションの状態を確認するためのログ収集を指示しました。問題の根本原因を特定するため、調査を迅速に進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00502', 'INC-2023-00341', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-03-30T22:47:23+09:00', TIMESTAMP WITH TIME ZONE '2023-03-30T23:47:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00343', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-10-22T21:52:34+09:00', TIMESTAMP WITH TIME ZONE '2023-10-22T22:52:34+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2023年10月22日 21:52頃、架空食品店Aにて特定拠点のみAPI呼び出しが失敗する事象が発生しました。この障害は顧客拠点NWに影響を及ぼし、顧客側FWにも関連しています。発生の契機は新規店舗追加の初日であり、影響範囲は単一店舗に限定されています。エラーコードはNW-02-00343であり、顧客からの報告では特定のAPIが正常に動作しないという内容でした。この問題は2023年10月22日 23:07まで検知されず、検知までに75分を要しました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00343', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00343', 'INC-2023-00343', '特定拠点のAPI呼び出し失敗の原因として、店舗LANのスイッチ故障が疑われます。新規店舗が追加された初日にこの問題が発生したことから、スイッチの設定や性能に問題があった可能性があります。今後、同様の障害が発生しないよう、スイッチのメンテナンスと確認を行う必要があります。', '特定拠点のAPI呼び出し失敗の原因として、店舗LANのスイッチ故障が疑われます。新規店舗が追加された初日にこの問題が発生したことから、スイッチの設定や性能に問題があった可能性があります。今後、同様の障害が発生しないよう、スイッチのメンテナンスと確認を行う必要があります。', TIMESTAMP WITH TIME ZONE '2023-10-23T22:52:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00505', 'INC-2023-00343', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-10-22T23:07:34+09:00', TIMESTAMP WITH TIME ZONE '2023-10-23T00:07:34+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗', '2023年10月22日 21:55、顧客からの報告を受け、緊急対応チームが現地調査を開始しました。まず、顧客拠点NWのLANスイッチの動作状況を確認し、API呼び出しのログを収集します。また、顧客側FWの設定もチェックし、問題の特定を急ぎます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00506', 'INC-2023-00343', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-10-23T00:37:34+09:00', TIMESTAMP WITH TIME ZONE '2023-10-23T01:37:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00347', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-09-19T09:49:54+09:00', TIMESTAMP WITH TIME ZONE '2023-09-19T11:49:54+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2023-09-19 09:49:54に株式会社ストッククラウドの顧客、架空食品店BにてEDI経由の棚卸ファイル取込で件数不一致が発生しました。発生契機はデータ移行バッチ実行中です。影響範囲はバッチ処理のみであり、オンラインには影響がありません。エラーコードはINV-06-00347です。問題は顧客店舗POS（ゾーンB）およびEDIアダプタに関連しており、推定原因としてEDI連携ファイルの文字コード不一致が考えられます。検知は2023-09-19 12:21:54に行われ、検知まで152分かかりました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00347', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00347', 'INC-2023-00347', 'インシデント発生後、データ移行バッチの実行状況を調査しました。EDI経由の棚卸ファイル取込時に発生した件数不一致は、EDI連携ファイルの文字コード不一致によるものである可能性が高いと判断されました。関連するシステムログを分析し、文字コードの設定を確認しました。追加のテストを実施し、問題の再現性を確認する必要があります。', 'インシデント発生後、データ移行バッチの実行状況を調査しました。EDI経由の棚卸ファイル取込時に発生した件数不一致は、EDI連携ファイルの文字コード不一致によるものである可能性が高いと判断されました。関連するシステムログを分析し、文字コードの設定を確認しました。追加のテストを実施し、問題の再現性を確認する必要があります。', TIMESTAMP WITH TIME ZONE '2023-09-20T11:49:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00510', 'INC-2023-00347', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-09-19T12:04:54+09:00', TIMESTAMP WITH TIME ZONE '2023-09-19T13:04:54+09:00', '【初動対応】【棚卸・POS突合障害】EDI棚卸ファイル異常', '初動対応として、発生したEDI棚卸ファイルの内容を確認し、件数不一致の原因を特定しました。また、データ移行バッチに関連する設定を見直し、文字コードの不一致を解消するための手順を策定しました。さらに、顧客店舗POSの状態を確認し、影響を受けたバッチ処理を再実行する準備を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00372', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-12-02T08:31:31+09:00', TIMESTAMP WITH TIME ZONE '2023-12-02T09:01:31+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2023年12月2日08時31分31秒に、株式会社ストッククラウドのサービスMercuryにおいて、在庫登録失敗が発生しました。顧客である架空食品店Aに対する影響があり、分散トランザクションがタイムアウトし片側のみコミットされました。この事象は大規模セール開始直前に発生し、全テナントに影響を及ぼす可能性がありました。エラーコードはSYNC-04-00372です。運用部の運用 一郎が発見し、検知までに22分を要しました。推定原因は2PCタイムアウト設定の過短であり、これは在庫計算エンジンを含むMercury AWS APに影響を与えました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00372', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00372', 'INC-2023-00372', '本インシデントの調査において、分散トランザクションがタイムアウトした原因として、2PCのタイムアウト設定が過短であることが確認されました。大規模セール開始直前というタイミングで、予期しないトラフィックの増加が影響を与えた可能性があります。このため、今後のセールの際にこの設定を見直し、適切なタイムアウト時間を設定することが必要です。', '本インシデントの調査において、分散トランザクションがタイムアウトした原因として、2PCのタイムアウト設定が過短であることが確認されました。大規模セール開始直前というタイミングで、予期しないトラフィックの増加が影響を与えた可能性があります。このため、今後のセールの際にこの設定を見直し、適切なタイムアウト時間を設定することが必要です。', TIMESTAMP WITH TIME ZONE '2023-12-03T09:01:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00545', 'INC-2023-00372', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-12-02T09:16:31+09:00', TIMESTAMP WITH TIME ZONE '2023-12-02T10:16:31+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウトの初期対応', 'インシデント発生直後、運用部は即座に状況を確認し、分散トランザクションがタイムアウトしていることを特定しました。エンジニアチームに連絡を取り、2PCタイムアウト設定の見直しを提案するとともに、影響を受けた顧客に通知しました。影響範囲を把握し、必要に応じて手動で在庫を調整しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00546', 'INC-2023-00372', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-12-02T10:46:31+09:00', TIMESTAMP WITH TIME ZONE '2023-12-02T11:46:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00373', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-01-08T19:39:06+09:00', TIMESTAMP WITH TIME ZONE '2023-01-08T20:09:06+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2023年01月08日19時39分06秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bの在庫登録が失敗しました。この障害は、パートナーAPIが429を返し連携が停止したことに起因しています。原因としては、呼出頻度の事前調整不足が推定されており、特に大規模セール開始直前という発生契機から考えると、この問題が影響を及ぼした可能性があります。影響を受けたエラーコードはEDI-06-00373です。現時点では、サービス全体の一部機能が影響を受けている状況です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00373', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00373', 'INC-2023-00373', '本件についての調査を進めた結果、大規模セール開始直前にパートナーAPIが429を返し、連携が停止していることが確認されました。API連携・EDIに関連するコンポーネントとして、Mercury AWS AP（ゾーンA）およびAPIゲートウェイが特定されました。この障害によって、架空食品店Bの在庫登録に影響が出ているため、早急な対応が求められます。', '本件についての調査を進めた結果、大規模セール開始直前にパートナーAPIが429を返し、連携が停止していることが確認されました。API連携・EDIに関連するコンポーネントとして、Mercury AWS AP（ゾーンA）およびAPIゲートウェイが特定されました。この障害によって、架空食品店Bの在庫登録に影響が出ているため、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2023-01-09T20:09:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00547', 'INC-2023-00373', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-08T20:24:06+09:00', TIMESTAMP WITH TIME ZONE '2023-01-08T21:24:06+09:00', '【初動対応】【API連携・EDI障害】レート超過429', '運用部の運用 一郎です。現在の状況を把握しています。架空食品店Bへの影響を最小限に抑えるため、パートナーAPIの呼出頻度に関する調整を行い、再度連携を試みます。429エラーが解消されるまで、進捗を逐次報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00548', 'INC-2023-00373', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-08T21:54:06+09:00', TIMESTAMP WITH TIME ZONE '2023-01-08T22:54:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00393', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2023-03-28T05:58:28+09:00', TIMESTAMP WITH TIME ZONE '2023-03-28T06:28:28+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2023年3月28日05:58に、株式会社ストッククラウドのサービスMercuryにおいて主要メトリクス系列が15分間欠損するという事象が発生しました。この障害は、インフラメンテナンス明けに発生し、運用部門に影響を及ぼしました。現象が検知されたのは06:15で、検知までに17分の遅延がありました。環境としては、Venus Azure AP（DRサイト）およびメトリクスコレクタが関与しています。推定される原因は、メトリクスエージェントの再起動失敗です。この問題により、顧客である架空食品店A及び架空食品店Bは監視機能に影響を受けました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00393', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00393', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00393', 'INC-2023-00393', '本インシデントに関する調査を行った結果、メトリクスエージェントの再起動失敗が主要メトリクス系列の欠損に繋がったことが判明しました。具体的には、インフラメンテナンス明けの初期状態において、エージェントが正しく稼働しなかったため、メトリクスデータが収集されず、結果として欠損が発生しました。今後の対策として、メトリクスエージェントの再起動プロセスの見直しと、監視体制の強化を検討する必要があります。', '本インシデントに関する調査を行った結果、メトリクスエージェントの再起動失敗が主要メトリクス系列の欠損に繋がったことが判明しました。具体的には、インフラメンテナンス明けの初期状態において、エージェントが正しく稼働しなかったため、メトリクスデータが収集されず、結果として欠損が発生しました。今後の対策として、メトリクスエージェントの再起動プロセスの見直しと、監視体制の強化を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2023-03-29T06:28:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00576', 'INC-2023-00393', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-28T06:43:28+09:00', NULL, '【初期対応】【監視・可用性障害】メトリクス欠損への対応', 'インシデント発生直後、運用部の運用 一郎が直ちに状況を把握し、メトリクスエージェントの再起動を試みました。しかし、再起動が成功せず、問題を特定するために追加調査を開始しました。また、影響を受けた顧客である架空食品店A及び架空食品店Bに状況を報告し、監視機能の復旧を優先的に進める旨をお伝えしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00437', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-03-26T13:53:26+09:00', TIMESTAMP WITH TIME ZONE '2023-03-26T14:23:26+09:00', '【障害報告】【API連携・EDI障害】配送連携ステータス停滞', '2023年3月26日13時53分に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店A及び架空食品店Bに対する配送連携のステータスが出荷済みで停滞する事象が発生しました。発見者は運用部の運用 一郎であり、発生から検知までに32分を要しました。本事象は、特定の店舗に対してのみ影響を及ぼしました。大規模セール開始直前に発生したため、販売活動に影響を与える可能性があります。エラーコードはEDI-09-00437です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00437', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00437', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00437', 'INC-2023-00437', '本障害の原因について調査を行った結果、配送連携のステータスマッピング表の更新漏れが要因であると考えられます。具体的には、大規模セール開始直前に必要なステータスマッピングの情報が適切に反映されておらず、出荷済みのステータスが更新されなかったことが確認されました。影響を受けたのはMercury AWS AP（ゾーンA）であり、配送連携アダプタに関わる問題です。', '本障害の原因について調査を行った結果、配送連携のステータスマッピング表の更新漏れが要因であると考えられます。具体的には、大規模セール開始直前に必要なステータスマッピングの情報が適切に反映されておらず、出荷済みのステータスが更新されなかったことが確認されました。影響を受けたのはMercury AWS AP（ゾーンA）であり、配送連携アダプタに関わる問題です。', TIMESTAMP WITH TIME ZONE '2023-03-27T14:23:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00641', 'INC-2023-00437', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-26T14:38:26+09:00', TIMESTAMP WITH TIME ZONE '2023-03-26T15:38:26+09:00', '【初期対応】配送連携ステータス停滞に関する初動', '初動対応として、運用部はまず影響を受けた架空食品店A及び架空食品店Bの配送連携設定を確認しました。次に、ステータスマッピング表の状況を確認し、更新漏れの確認を行いました。その後、必要な修正を施し、適切なステータスへの更新を行いました。これにより、改めて配送連携の正常化を図るための措置を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00642', 'INC-2023-00437', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-26T16:08:26+09:00', TIMESTAMP WITH TIME ZONE '2023-03-26T17:08:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00445', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2023-04-19T19:20:25+09:00', TIMESTAMP WITH TIME ZONE '2023-04-19T20:05:25+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2023年4月19日19時20分に、株式会社ストッククラウドのサービスMercuryにおいてストレージ溢れが発生しました。特に、Mercury AWS StorageにおいてPagerDuty連携が失敗し、オンコール通知が未達となりました。この障害は、運用部門に影響を及ぼしました。検知は2023年4月19日19時51分に行われ、約31分間の未検知期間が存在しました。推定される原因としては、連携APIキーの権限不足が挙げられます。年末年始の稼働切替時に問題が発生したことが影響しています。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00445', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00445', 'INC-2023-00445', '今回のPagerDuty連携失敗に関する調査を行いました。運用部門からの報告に基づいて、連携APIキーの権限不足が原因である可能性が高いと考えられます。具体的には、年末年始の稼働切替時にこの問題が発生したことが確認されており、影響範囲は運用部門のみに限定されています。現在、さらなる原因究明と対策を進めています。', '今回のPagerDuty連携失敗に関する調査を行いました。運用部門からの報告に基づいて、連携APIキーの権限不足が原因である可能性が高いと考えられます。具体的には、年末年始の稼働切替時にこの問題が発生したことが確認されており、影響範囲は運用部門のみに限定されています。現在、さらなる原因究明と対策を進めています。', TIMESTAMP WITH TIME ZONE '2023-04-20T20:05:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00656', 'INC-2023-00445', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-04-19T20:20:25+09:00', TIMESTAMP WITH TIME ZONE '2023-04-19T21:20:25+09:00', '【初期対応】【CLU-10】PagerDuty連携失敗', '初期対応として、運用部門は連携APIキーの権限を確認し、必要に応じて修正を行いました。また、PagerDutyの設定を見直し、通知未達の原因を特定するための調査を依頼しました。その結果、連携失敗の根本的な原因が特定されるまでの間、他の通知手段を確保することでオンコール体制を維持しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00657', 'INC-2023-00445', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-04-19T21:50:25+09:00', TIMESTAMP WITH TIME ZONE '2023-04-19T22:50:25+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00468', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-09-13T06:40:58+09:00', TIMESTAMP WITH TIME ZONE '2023-09-13T07:10:58+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2023年9月13日、株式会社ストッククラウドが提供するMercuryにおいて、架空食品店Aおよび架空食品店Bへの在庫登録失敗が発生しました。発生時刻は06:40頃で、バルクAPIが部分失敗しロールバック未完了の状態が続いていました。この事象は、データ移行バッチ実行中に引き起こされ、影響範囲はサービス全体の一部機能に及んでいます。具体的には、Mercury AWS AP（ゾーンB）における在庫登録APIの機能が不完全な状態となりました。エラーコードはEDI-10-00468です。問題の根本原因として、部分成功時の補償トランザクション欠如が疑われます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00468', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00468', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00468', 'INC-2023-00468', '調査の結果、バルクAPIが部分失敗し、ロールバックが未完了の状態になりました。データ移行バッチ実行中に発生したこの事象は、部分成功時に必要な補償トランザクションが欠如していたためと考えられます。この事象は、API連携・EDI障害の一環として捉えることができ、影響を受けた機能はサービス全体の一部に及びます。今後の対策としては、バルクAPIのトランザクション管理強化が必要です。', '調査の結果、バルクAPIが部分失敗し、ロールバックが未完了の状態になりました。データ移行バッチ実行中に発生したこの事象は、部分成功時に必要な補償トランザクションが欠如していたためと考えられます。この事象は、API連携・EDI障害の一環として捉えることができ、影響を受けた機能はサービス全体の一部に及びます。今後の対策としては、バルクAPIのトランザクション管理強化が必要です。', TIMESTAMP WITH TIME ZONE '2023-09-14T07:10:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00691', 'INC-2023-00468', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-09-13T07:25:58+09:00', TIMESTAMP WITH TIME ZONE '2023-09-13T08:25:58+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗', '初期対応として、運用部の運用 一郎が06:50に事象を確認し、エラーコードEDI-10-00468の詳細調査を開始しました。06:55には関係者に通知し、09:00までに影響の範囲を特定しました。サービスの復旧作業は09:10に開始し、09:30までには問題を解決しました。今後は、データ移行時のトランザクション処理を見直し、同様の事象が発生しないように対策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00692', 'INC-2023-00468', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-09-13T08:55:58+09:00', TIMESTAMP WITH TIME ZONE '2023-09-13T09:55:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00490', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2023-06-07T18:56:31+09:00', TIMESTAMP WITH TIME ZONE '2023-06-07T19:11:31+09:00', '【障害報告】【CLU-10】死活監視誤検知', '2023年6月7日18時56分31秒に、株式会社ストッククラウドのサービスMercuryにおいて、運用コンソールに関連する死活監視が正常系をDOWNと誤検知する障害が発生しました。検知は2023年6月7日19時15分31秒で、約19分後に発見されました。この障害は運用部門に限定されており、運用部の運用 一郎が発見者となります。定例リリース直後の発生契機が影響していると考えられ、監視プローブのUser-Agentブロックを推定原因としております。死活監視の誤検知により、サービスの可用性に深刻な影響を及ぼしました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00490', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00490', 'INC-2023-00490', '本障害の調査を行った結果、定例リリース後に死活監視が正常系をDOWNと誤検知したことが確認されました。監視プローブのUser-Agentがブロックされている可能性が高く、これが死活監視誤検知の根本原因であると考えられます。運用コンソールの監視・可用性障害に起因しているため、今後の改善策として、監視プローブの設定見直しが必要です。', '本障害の調査を行った結果、定例リリース後に死活監視が正常系をDOWNと誤検知したことが確認されました。監視プローブのUser-Agentがブロックされている可能性が高く、これが死活監視誤検知の根本原因であると考えられます。運用コンソールの監視・可用性障害に起因しているため、今後の改善策として、監視プローブの設定見直しが必要です。', TIMESTAMP WITH TIME ZONE '2023-06-08T19:11:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00723', 'INC-2023-00490', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-06-07T19:26:31+09:00', TIMESTAMP WITH TIME ZONE '2023-06-07T20:26:31+09:00', '【対応ログ】【CLU-10】初期対応', '現在、死活監視による誤検知の問題について初期対応を実施中です。運用 一郎が中心となり、監視プローブの設定を確認し、User-Agentのブロック状況を調査しております。必要に応じて、運用コンソールの再起動や設定変更を行い、正常系の監視を復旧させる方針です。状況を注視し、適切な措置を講じてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00496', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-03-04T01:57:43+09:00', TIMESTAMP WITH TIME ZONE '2023-03-04T02:27:43+09:00', '【障害報告】【CLU-09】CDCイベント欠損', '・発生日時: 2023-03-04T01:57:43+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00496', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00496', 'INC-2023-00496', '本件についての調査を実施しました。CDCイベント欠損の原因として、CDCコネクタのオフセット巻戻しが疑われます。データ移行バッチが実行中に発生したため、下流倉庫のデータが更新されておらず、影響範囲はバッチ処理のみに限定されています。今後、CDCイベントの整合性を確認し、再発防止策を講じる必要があります。', '本件についての調査を実施しました。CDCイベント欠損の原因として、CDCコネクタのオフセット巻戻しが疑われます。データ移行バッチが実行中に発生したため、下流倉庫のデータが更新されておらず、影響範囲はバッチ処理のみに限定されています。今後、CDCイベントの整合性を確認し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2023-03-05T02:27:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00730', 'INC-2023-00496', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-04T02:42:43+09:00', TIMESTAMP WITH TIME ZONE '2023-03-04T03:42:43+09:00', '初期対応', '運用部の運用 一郎が発見し、状況確認を行いました。CDCイベント欠損により下流倉庫が未更新であることを確認し、即時にデータ移行バッチの再実行を検討中です。影響範囲はバッチ処理のみであり、オンラインサービスへの影響は確認されていません。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00498', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2023-11-23T03:51:53+09:00', TIMESTAMP WITH TIME ZONE '2023-11-23T04:21:53+09:00', '【障害報告】【監視・可用性障害】PagerDuty連携失敗', '2023年11月23日03時51分53秒、株式会社ストッククラウドの顧客である架空食品店Bにおいて、Venus Azure APでPagerDuty連携が失敗し、オンコール通知未達の事象が発生しました。運用部門の運用 一郎がこの問題を発見し、04時25分53秒に検知されました。年末年始の稼働切替時に発生したこの利用者増による応答遅延は、連携APIキーの権限不足が推定される原因として考えられています。運用部門のみが影響を受けるこの障害は、適切な通知が行われなかったために、迅速な対応が難しくなりました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00498', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00498', 'INC-2023-00498', '本インシデントは、年末年始の稼働切替時に発生しました。原因として連携APIキーの権限不足が挙げられ、これによりPagerDutyとの連携が失敗しました。結果として、オンコール通知が未達となり、運用部門への影響が生じました。今後の改善策として、APIキーの権限管理を強化し、事前のシステムテストを実施することが必要です。この問題は、監視・可用性障害に関わる重要な事案です。', '本インシデントは、年末年始の稼働切替時に発生しました。原因として連携APIキーの権限不足が挙げられ、これによりPagerDutyとの連携が失敗しました。結果として、オンコール通知が未達となり、運用部門への影響が生じました。今後の改善策として、APIキーの権限管理を強化し、事前のシステムテストを実施することが必要です。この問題は、監視・可用性障害に関わる重要な事案です。', TIMESTAMP WITH TIME ZONE '2023-11-24T04:21:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00733', 'INC-2023-00498', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-11-23T04:36:53+09:00', TIMESTAMP WITH TIME ZONE '2023-11-23T05:36:53+09:00', '【初期対応】【監視・可用性障害】PagerDuty連携失敗', '運用 一郎が発見したPagerDuty連携の失敗に対し、直ちに技術チームに連絡を取り、事象の詳細確認を行いました。APIキーの設定を確認したところ、権限不足が原因であることが判明し、迅速に修正作業に取り掛かりました。運用部門には、改めてこの状況を共有し、今後の対応策について検討を始めました。この初期対応により、再発防止策を検討するための基盤が整いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00734', 'INC-2023-00498', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-11-23T06:06:53+09:00', TIMESTAMP WITH TIME ZONE '2023-11-23T07:06:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00537', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-01-09T22:58:55+09:00', TIMESTAMP WITH TIME ZONE '2023-01-10T00:58:55+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2023年1月9日22:58:55、株式会社ストッククラウドの顧客である架空食品店Aおよび架空食品店Bにおいて、読取レプリカ遅延が発生し、在庫照会が古い値となった。これは大規模セール開始直前に発生しており、昨日時点でのレプリケーション遅延の監視閾値を超過したことが原因であると考えられる。影響範囲は特定リージョンのユーザーに限られており、顧客店舗POSおよび読取専用レプリカが影響を受けた。エラーコードはSYNC-02-00537である。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00537', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00537', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00537', 'INC-2023-00537', '調査を開始し、レプリケーション遅延の監視データを確認したところ、確かに監視閾値を超過していることが確認された。大規模セール開始直前のため、トラフィックが急増し、読取レプリカ遅延が発生したと推測される。今後の対策として、トラフィックピーク時の監視強化や、リソースの最適化が考えられる。', '調査を開始し、レプリケーション遅延の監視データを確認したところ、確かに監視閾値を超過していることが確認された。大規模セール開始直前のため、トラフィックが急増し、読取レプリカ遅延が発生したと推測される。今後の対策として、トラフィックピーク時の監視強化や、リソースの最適化が考えられる。', TIMESTAMP WITH TIME ZONE '2023-01-11T00:58:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00794', 'INC-2023-00537', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-01-10T01:13:55+09:00', TIMESTAMP WITH TIME ZONE '2023-01-10T02:13:55+09:00', '初期対応', '初期対応として、読取レプリカの監視を強化し、トラフィックが急増した際の対応策を策定することが急務である。在庫照会の迅速な更新を行うため、当該データセットの再同期を実施した。顧客への影響を最小限に抑えるため、関連する店舗に対して状況を説明し、今後の改善策を提示した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00544', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-01-10T02:23:58+09:00', TIMESTAMP WITH TIME ZONE '2023-01-10T04:23:58+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '2023年01月10日02時23分58秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客「架空食品店A」の店舗POSにて棚卸突合失敗が発生しました。実地棚卸数とシステム在庫が大幅に乖離し、この事象は月末棚卸の開始時に検知されました。影響範囲は同一顧客の全店舗であり、エラーコードはINV-01-00544です。顧客店舗POSと棚卸突合エンジンに影響を及ぼすこの問題は、棚卸スナップショット時刻のずれが原因と推定されます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00544', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00544', 'INC-2023-00544', '発見者である営業部の花子は、実地棚卸数とシステム在庫の乖離を発見後、原因の特定にあたりました。調査の結果、棚卸スナップショット時刻にずれが生じていることが確認されました。このため、月末棚卸の開始時に実地棚卸数とシステム在庫が大幅に乖離する現象が発生した可能性が高いと考えられます。今後、この問題を解消するための対策を講じる必要があります。', '発見者である営業部の花子は、実地棚卸数とシステム在庫の乖離を発見後、原因の特定にあたりました。調査の結果、棚卸スナップショット時刻にずれが生じていることが確認されました。このため、月末棚卸の開始時に実地棚卸数とシステム在庫が大幅に乖離する現象が発生した可能性が高いと考えられます。今後、この問題を解消するための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2023-01-11T04:23:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00804', 'INC-2023-00544', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-01-10T04:38:58+09:00', TIMESTAMP WITH TIME ZONE '2023-01-10T05:38:58+09:00', '【初期対応】【棚卸・POS突合障害】棚卸実地差異への初期対応', 'この問題に対して、初期対応として、棚卸スナップショット時刻の設定を見直すことが直ちに求められました。また、関連する顧客店舗POSのログを確認し、スナップショットの時間設定を整えるよう指示しました。さらに、影響を受けた店舗に対しては一時的な対応策を講じ、実地棚卸を手動で確認することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00805', 'INC-2023-00544', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-01-10T06:08:58+09:00', TIMESTAMP WITH TIME ZONE '2023-01-10T07:08:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00547', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2023-12-30T20:23:45+09:00', TIMESTAMP WITH TIME ZONE '2023-12-30T20:53:45+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2023年12月30日20時23分45秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bに影響を及ぼす応答遅延が発生しました。この問題は、Venus Azure APにおけるヘルスチェック過多によるAPサーバーへの負荷増加が原因です。発生契機はインフラメンテナンス明けであり、全テナントに波及する影響範囲を持っています。エラーコードはMON-06-00547であり、運用部の運用 一郎が発見しました。問題の解決に向けた調査を開始しますが、まずはヘルスチェックの状況を確認する必要があります。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00547', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00547', 'INC-2023-00547', '今回のヘルスチェック過負荷について、根本原因を明確にするための調査を行います。まず、LBヘルスチェックの設定を確認し、過短設定が行われている場合はその調整を検討します。また、APサーバーの負荷状況をモニタリングし、影響の範囲を明確にする必要があります。過負荷の影響が全テナントに及んでいるため、迅速な対応が求められます。', '今回のヘルスチェック過負荷について、根本原因を明確にするための調査を行います。まず、LBヘルスチェックの設定を確認し、過短設定が行われている場合はその調整を検討します。また、APサーバーの負荷状況をモニタリングし、影響の範囲を明確にする必要があります。過負荷の影響が全テナントに及んでいるため、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2023-12-31T20:53:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00809', 'INC-2023-00547', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-12-30T21:08:45+09:00', TIMESTAMP WITH TIME ZONE '2023-12-30T22:08:45+09:00', '【初期対応】ヘルスチェック設定の確認', '運用 一郎が始めにLBのヘルスチェック設定を確認します。過短設定が影響を及ぼしている場合は、即座に設定変更を行う必要があります。また、APサーバーの負荷状況をリアルタイムで監視し、状況を把握することで、さらなる対応を検討します。ヘルスチェックの過負荷による影響を最小限に抑えるため、早急な調査と対応が重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00810', 'INC-2023-00547', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-12-30T22:38:45+09:00', TIMESTAMP WITH TIME ZONE '2023-12-30T23:38:45+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00565', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-11-27T20:52:12+09:00', TIMESTAMP WITH TIME ZONE '2023-11-27T21:22:12+09:00', '【障害報告】【CLU-01】キャッシュ不整合登録', '2023年11月27日20時52分に発生した在庫マスター設定障害について報告します。株式会社ストッククラウドのMercuryにおいて、定例リリース直後にマスター更新を実施しましたが、更新後も旧設定で在庫登録が拒否される事象が発生しました。これにより、全テナントに対して波及的な影響が及びました。特に、キャッシュレイヤの無効化漏れが原因であると考えられます。エラーコードはMST-10-00565です。この事象は、顧客に直接影響を及ぼしていないものの、内部のシステム整合性に問題を生じさせました。今後の対策として、キャッシュの管理やマスター更新の手順を見直す必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00565', 'INC-2023-00565', '本件に関する調査を行った結果、定例リリース直後のマスター更新において、キャッシュレイヤの無効化が行われていなかったことが主な原因として特定されました。これにより、在庫登録時に旧設定が参照され、不整合が生じたと考えられます。今後は、リリース作業におけるキャッシュの無効化処理を確実に行うため、手順文書の整備とトレーニングの実施を検討する必要があります。', '本件に関する調査を行った結果、定例リリース直後のマスター更新において、キャッシュレイヤの無効化が行われていなかったことが主な原因として特定されました。これにより、在庫登録時に旧設定が参照され、不整合が生じたと考えられます。今後は、リリース作業におけるキャッシュの無効化処理を確実に行うため、手順文書の整備とトレーニングの実施を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2023-11-28T21:22:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00836', 'INC-2023-00565', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-11-27T21:37:12+09:00', TIMESTAMP WITH TIME ZONE '2023-11-27T22:37:12+09:00', '【対応】【CLU-01】キャッシュ不整合登録', 'インシデント発生後、運用部の運用 一郎が対応にあたり、迅速に影響範囲を把握しました。定例リリース後のキャッシュレイヤの無効化漏れを確認したため、即時にキャッシュの無効化を実施し、その後の在庫登録が正常に行われることを確認しました。引き続き、原因の追及と再発防止策の策定を進めていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00837', 'INC-2023-00565', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-11-27T23:07:12+09:00', TIMESTAMP WITH TIME ZONE '2023-11-28T00:07:12+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00566', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-08-31T13:35:45+09:00', TIMESTAMP WITH TIME ZONE '2023-08-31T14:05:45+09:00', '【障害報告】【データ同期・整合性障害】楽観ロック競合多発', '2023年9月1日、架空食品店Bにおいて、楽観ロック競合が多発し、更新失敗率が上昇する事象が発生しました。これは、バージョンカラム更新ロジックの不備が疑われ、全テナントに波及する影響を持ちました。特に、大規模セール開始直前に発生したため、在庫登録APIへの影響が顕著でした。運用部の運用 一郎が発見し、13時35分頃に発生した事象は、14時14分に検知されました。エラーコードはSYNC-10-00566です。これにより、顧客へのサービス提供に影響を与える結果となりました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00566', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00566', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00566', 'INC-2023-00566', '調査の結果、大規模セール開始直前に楽観ロック競合が多発し、更新失敗率が上昇したことが確認されました。原因として、バージョンカラムの更新ロジックに不備があることが疑われ、システム全体の整合性に影響を及ぼしました。データ同期の処理が正常に行われなかったことが、全テナントに波及した要因と考えられます。', '調査の結果、大規模セール開始直前に楽観ロック競合が多発し、更新失敗率が上昇したことが確認されました。原因として、バージョンカラムの更新ロジックに不備があることが疑われ、システム全体の整合性に影響を及ぼしました。データ同期の処理が正常に行われなかったことが、全テナントに波及した要因と考えられます。', TIMESTAMP WITH TIME ZONE '2023-09-01T14:05:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00838', 'INC-2023-00566', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-08-31T14:20:45+09:00', TIMESTAMP WITH TIME ZONE '2023-08-31T15:20:45+09:00', '初期対応', '初期対応として、運用部門は直ちにシステムのログを収集し、楽観ロック競合の発生状況を確認しました。影響範囲を特定するため、全テナントの在庫登録状況を調査し、緊急メンテナンスを実施することを決定しました。さらに、バージョンカラムの更新ロジックに関するエンジニアリングチームとの連携を強化し、早急に根本原因の特定と修正に取り組む方針を固めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00839', 'INC-2023-00566', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-08-31T15:50:45+09:00', TIMESTAMP WITH TIME ZONE '2023-08-31T16:50:45+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00582', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2023-04-25T15:44:26+09:00', TIMESTAMP WITH TIME ZONE '2023-04-25T15:59:26+09:00', '【障害報告】【CLU-08】MFAデバイス不一致', '・発生日時: 2023-10-01T10:30:00+09:00  
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00582', 'INC-2023-00582', '2023年10月1日10時30分に発生したMFAデバイス登録不一致によるログイン不可の事象について、運用コンソール（DRサイト）の認証サービスにおいて、MFAシードの再発行未同期が原因であることを確認しました。特定の顧客オンボーディング当日に発生したため、当該顧客のMFA設定を再確認する必要があります。', '2023年10月1日10時30分に発生したMFAデバイス登録不一致によるログイン不可の事象について、運用コンソール（DRサイト）の認証サービスにおいて、MFAシードの再発行未同期が原因であることを確認しました。特定の顧客オンボーディング当日に発生したため、当該顧客のMFA設定を再確認する必要があります。', TIMESTAMP WITH TIME ZONE '2023-04-26T15:59:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00861', 'INC-2023-00582', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-04-25T16:14:26+09:00', TIMESTAMP WITH TIME ZONE '2023-04-25T17:14:26+09:00', '【初期対応】【CLU-08】MFAデバイス不一致の初期対応', '顧客オンボーディング当日に発生したMFAデバイス登録不一致の問題について、直ちに運用コンソールのログを確認し、MFAシードの再発行状況を調査しました。確認の結果、顧客のMFAデバイスが正しく登録されていないことが判明しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00588', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-09-25T13:59:10+09:00', TIMESTAMP WITH TIME ZONE '2023-09-25T14:59:10+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2023年10月01日、株式会社ストッククラウドは、顧客である架空食品店Aおよび架空食品店Bのネットワーク障害を確認しました。この障害は、顧客拠点NWにおいてSD-WANが劣化回線を選択し、遅延が増大するという症状が見られました。発生は大規模セール開始直前であり、影響範囲は同一顧客の全店舗に及んでいます。検知は2023年10月01日14:37に行われ、発見者は営業部の花子です。本インシデントは、SD-WANポリシーの閾値設定に誤りがあったと推定されています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00588', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00588', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00588', 'INC-2023-00588', '調査の結果、SD-WANが不適切な経路を選択した原因は、ポリシー設定における閾値の誤りに起因することが判明しました。これにより、劣化した回線が選択され、遅延が発生していました。今後はSD-WANのポリシー設定の見直しを行い、再発防止策を講じる必要があります。また、監視体制の強化も検討する必要があります。', '調査の結果、SD-WANが不適切な経路を選択した原因は、ポリシー設定における閾値の誤りに起因することが判明しました。これにより、劣化した回線が選択され、遅延が発生していました。今後はSD-WANのポリシー設定の見直しを行い、再発防止策を講じる必要があります。また、監視体制の強化も検討する必要があります。', TIMESTAMP WITH TIME ZONE '2023-09-26T14:59:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00871', 'INC-2023-00588', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-09-25T15:14:10+09:00', TIMESTAMP WITH TIME ZONE '2023-09-25T16:14:10+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤りへの初期対応', 'インシデント発生後、直ちに技術チームを招集し、SD-WANの設定を確認しました。設定に誤りがあることが確認され、閾値を適正に調整する作業を開始しました。影響を受けている全拠点に対して、代替経路を提供し、遅延の軽減を図るための対応を実施しました。また、顧客には経過報告を行い、影響の最小化に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00872', 'INC-2023-00588', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-09-25T16:44:10+09:00', TIMESTAMP WITH TIME ZONE '2023-09-25T17:44:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00591', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-01-31T18:36:02+09:00', TIMESTAMP WITH TIME ZONE '2023-01-31T19:06:02+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2023年2月15日、株式会社ストッククラウドのMercuryサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。発生時刻は18時36分、検知時刻は18時51分であり、検知までの時間は15分でした。症状としては、マスター更新後も旧設定で在庫登録が拒否されるというものであり、全テナントに波及する影響がありました。推定原因としては、キャッシュレイヤの無効化漏れが考えられます。特に、定例リリース直後にこの障害が発生したことから、リリース後の確認作業が不十分であった可能性が指摘されます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00591', 'INC-2023-00591', '調査の結果、定例リリース直後にマスター更新が行われたにもかかわらず、キャッシュレイヤの無効化が行われていなかったことが確認されました。このため、旧設定がキャッシュに残存し、新しい設定による在庫登録が拒否される状態が続いていました。全テナントに影響したことから、リリース管理プロセスの見直しが必要です。今後は、リリース後のキャッシュのクリアを自動化する手段を講じる必要があります。', '調査の結果、定例リリース直後にマスター更新が行われたにもかかわらず、キャッシュレイヤの無効化が行われていなかったことが確認されました。このため、旧設定がキャッシュに残存し、新しい設定による在庫登録が拒否される状態が続いていました。全テナントに影響したことから、リリース管理プロセスの見直しが必要です。今後は、リリース後のキャッシュのクリアを自動化する手段を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2023-02-01T19:06:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00875', 'INC-2023-00591', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-31T19:21:02+09:00', TIMESTAMP WITH TIME ZONE '2023-01-31T20:21:02+09:00', '【初期対応】【在庫マスター設定障害】キャッシュ不整合登録', '運用部の運用 一郎が確認したところ、キャッシュレイヤの無効化漏れが原因であることが判明しました。直ちに関連するシステムのキャッシュを手動でクリアし、正常に在庫登録が行えることを確認しました。今後はリリース後の確認プロセスを強化し、同様の問題が再発しないようにします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00876', 'INC-2023-00591', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-31T20:51:02+09:00', TIMESTAMP WITH TIME ZONE '2023-01-31T21:51:02+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00603', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-01-19T01:05:57+09:00', TIMESTAMP WITH TIME ZONE '2023-01-19T01:35:57+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2023-10-15T10:00:00+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00603', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00603', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00603', 'INC-2023-00603', '今回のインシデントは、2023-10-15T10:00:00+09:00に発生した冪等キー重複により、在庫更新がスキップされる事象です。調査の結果、定例リリース直後に冪等キー生成ロジックに衝突が発生したと考えられます。影響を受けたのは、架空食品店Bの全店舗であり、API連携が正常に機能しなかったことが確認されています。この調査結果をもとに、再発防止策を検討する必要があります。', '今回のインシデントは、2023-10-15T10:00:00+09:00に発生した冪等キー重複により、在庫更新がスキップされる事象です。調査の結果、定例リリース直後に冪等キー生成ロジックに衝突が発生したと考えられます。影響を受けたのは、架空食品店Bの全店舗であり、API連携が正常に機能しなかったことが確認されています。この調査結果をもとに、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2023-01-20T01:35:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00892', 'INC-2023-00603', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-01-19T01:50:57+09:00', TIMESTAMP WITH TIME ZONE '2023-01-19T02:50:57+09:00', '【初期対応】【CLU-07】冪等キー重複の初期対応', '2023-10-15T10:00:00+09:00に発生した冪等キー重複に関する初期対応を行いました。運用部の運用 一郎が中心となり、影響を受けた全店舗に対して在庫登録の状況を確認しました。冪等キー生成ロジックの見直しを行うため、関連するログデータを収集し、詳細な分析を開始しました。顧客には本件に関する情報提供を行い、現状の把握と再発防止策に関する取組をお知らせしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00604', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-09-04T12:52:00+09:00', TIMESTAMP WITH TIME ZONE '2023-09-04T13:52:00+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2023-09-04 12:52に、株式会社ストッククラウドの顧客拠点NWでISP側BGP経路障害により複数拠点が同時不通となる事象が発生しました。発見者は営業の花子で、発生契機はインフラメンテナンス明けでした。13:42に検知され、検知まで50分の遅延がありました。この影響範囲は同一顧客の全店舗に及び、エラーコードNW-06-00604が記録されています。技術詳細として、ISP側のBGP経路障害が推定原因とされています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00604', 'INC-2023-00604', '本インシデントに関して、ISP側のBGP経路障害が確認されました。これはインフラメンテナンス後に発生し、顧客ネットワークへの影響が広範囲に及んでいます。調査チームは、ISPと連携して問題を解決するための手続きを進めており、今後の影響を最小限に抑えるための対策を講じます。', '本インシデントに関して、ISP側のBGP経路障害が確認されました。これはインフラメンテナンス後に発生し、顧客ネットワークへの影響が広範囲に及んでいます。調査チームは、ISPと連携して問題を解決するための手続きを進めており、今後の影響を最小限に抑えるための対策を講じます。', TIMESTAMP WITH TIME ZONE '2023-09-05T13:52:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00893', 'INC-2023-00604', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-09-04T14:07:00+09:00', TIMESTAMP WITH TIME ZONE '2023-09-04T15:07:00+09:00', '【初動対応】顧客ネットワーク障害', '初動対応として、障害発生時点での顧客のネットワーク状況を確認しました。ISP側からの情報も取得し、BGP経路障害が原因であることを特定しました。顧客には事象の詳細を説明し、継続的なアップデートを提供する旨をお伝えしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00639', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2023-02-02T18:17:15+09:00', TIMESTAMP WITH TIME ZONE '2023-02-02T18:47:15+09:00', '【障害報告】【性能・負荷障害】GC一時停止多発', '・発生日時: 2023-02-02T18:17:15+09:00
