INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00943', 'INC-2023-00639', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-02-02T19:02:15+09:00', TIMESTAMP WITH TIME ZONE '2023-02-02T20:02:15+09:00', '【初期対応】GC一時停止多発への初期対応', '・問題発生の報告を受け、即座に監視ツールで状況を確認しました。
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00647', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-03-24T22:21:53+09:00', TIMESTAMP WITH TIME ZONE '2023-03-24T23:21:53+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bにおける顧客側ネットワーク障害が発生しました。本事象は2023年3月24日22時21分53秒に発生し、23時06分53秒に検知されました。発生から検知までの時間は45分です。症状としては、店舗DNSキャッシュが旧IPを返し続ける状態が確認されており、影響範囲は単一店舗のみです。エラーコードはNW-08-00647です。本件は定例リリース直後に発生しました。推定原因としてDNS TTL設定とキャッシュ方針の不一致が考えられます。影響を受けるコンポーネントは顧客拠点NW（ゾーンB）及びDNSリゾルバです。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00647', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00647', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00647', 'INC-2023-00647', '調査の結果、架空食品店Bの店舗DNSキャッシュが旧IPを返し続けている原因は、DNS TTL設定とキャッシュ方針の不一致であると考えられます。定例リリース直後にこの問題が発生したことから、リリース内容の影響が強く疑われます。今後はDNS設定の見直しと、キャッシュ方針の整合性確認が必要です。', '調査の結果、架空食品店Bの店舗DNSキャッシュが旧IPを返し続けている原因は、DNS TTL設定とキャッシュ方針の不一致であると考えられます。定例リリース直後にこの問題が発生したことから、リリース内容の影響が強く疑われます。今後はDNS設定の見直しと、キャッシュ方針の整合性確認が必要です。', TIMESTAMP WITH TIME ZONE '2023-03-25T23:21:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00956', 'INC-2023-00647', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-03-24T23:36:53+09:00', TIMESTAMP WITH TIME ZONE '2023-03-25T00:36:53+09:00', '【初期対応】【顧客ネットワーク障害】DNSキャッシュ汚染', '初期対応として、架空食品店BのDNS設定を確認し、TTL設定を適切に変更しました。また、DNSリゾルバのキャッシュをクリアする手続きを実施しました。これにより、店舗のDNSキャッシュが新しいIPアドレスを返すようになりました。影響を受けた顧客には状況を説明し、今後の対応についても案内しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00957', 'INC-2023-00647', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-03-25T01:06:53+09:00', TIMESTAMP WITH TIME ZONE '2023-03-25T02:06:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00677', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2023-07-05T02:03:08+09:00', TIMESTAMP WITH TIME ZONE '2023-07-05T02:48:08+09:00', '【障害報告】【監視・可用性障害】可用性レポート誤集計', '2023年7月5日、株式会社ストッククラウドのサービスMercuryにて、ストレージ溢れが発生しました。顧客である架空食品店Bにおいて、月次可用性レポートが実績よりも高く表示されるという症状が確認されました。この件は、運用部の運用 一郎によって発見され、影響範囲は運用部門のみでした。発生したエラーコードはMON-10-00677であり、月末棚卸の開始時に発生しました。技術的な詳細としては、メンテナンス除外時間の二重計上が原因として推定されており、これにより可用性レポートが誤集計されていた可能性があります。このインシデントは、監視・可用性障害として重要度が高く扱われています。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00677', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00677', 'INC-2023-00677', 'インシデントに対する調査が行われ、月末棚卸の開始時における可用性レポートに誤集計が発生した原因が特定されました。メンテナンス除外時間の二重計上が影響を及ぼし、結果として実績よりも高い可用性レポートが表示されました。運用部門はこの問題に迅速に対応し、再発防止策を講じる必要があります。今後はメンテナンス時間の管理を厳密に行い、誤集計の防止に努める方針です。', 'インシデントに対する調査が行われ、月末棚卸の開始時における可用性レポートに誤集計が発生した原因が特定されました。メンテナンス除外時間の二重計上が影響を及ぼし、結果として実績よりも高い可用性レポートが表示されました。運用部門はこの問題に迅速に対応し、再発防止策を講じる必要があります。今後はメンテナンス時間の管理を厳密に行い、誤集計の防止に努める方針です。', TIMESTAMP WITH TIME ZONE '2023-07-06T02:48:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01001', 'INC-2023-00677', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-07-05T03:03:08+09:00', TIMESTAMP WITH TIME ZONE '2023-07-05T04:03:08+09:00', '【初動対応】【監視・可用性障害】可用性レポート誤集計に対する初動', '運用部は、月次可用性レポートの誤集計を受けて即座に対応策を講じました。影響を受けたデータを確認し、メンテナンス除外時間の二重計上についての調査を開始しました。また、関係部門に通知を行い、影響範囲を最小限に抑えるための措置を講じました。この初動により、将来的な問題の早期発見につながることが期待されています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00700', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2023-07-19T16:46:37+09:00', TIMESTAMP WITH TIME ZONE '2023-07-19T17:01:37+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2023年7月19日16時46分、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aの運用コンソールでCookie SameSite設定に関連したアクセス障害が発生しました。発見者は運用部の運用 一郎で、定例リリース直後に問題が確認されました。具体的には、埋込画面が認証不可となり、SameSite属性変更の影響が疑われます。本インシデントの重大度はCRITICALで、影響範囲は単一店舗のみに限られています。エラーコードはAUTH-06-00700です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00700', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00700', 'INC-2023-00700', '本インシデントについて調査を実施しましたが、定例リリース直後にCookie SameSite設定が変更されたため、埋込画面での認証が行えなくなったことが確認されました。これは、SameSite属性の変更が原因であると考えられ、影響を受けるコンポーネントは運用コンソール（Secondary）およびセッションストアです。引き続き、問題解決に向けて詳細を確認していきます。', '本インシデントについて調査を実施しましたが、定例リリース直後にCookie SameSite設定が変更されたため、埋込画面での認証が行えなくなったことが確認されました。これは、SameSite属性の変更が原因であると考えられ、影響を受けるコンポーネントは運用コンソール（Secondary）およびセッションストアです。引き続き、問題解決に向けて詳細を確認していきます。', TIMESTAMP WITH TIME ZONE '2023-07-20T17:01:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01037', 'INC-2023-00700', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-07-19T17:16:37+09:00', TIMESTAMP WITH TIME ZONE '2023-07-19T18:16:37+09:00', '【対応】【CLU-08】Cookie SameSite拒否', '運用 一郎からの報告を受け、迅速に問題の特定と対応を開始しました。運用コンソールでのCookie SameSite設定を確認し、必要に応じて修正を行います。また、同様の問題が今後発生しないよう、定期的な設定のレビューを実施することを検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00704', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2023-03-05T15:16:05+09:00', TIMESTAMP WITH TIME ZONE '2023-03-05T15:46:05+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2023年3月5日、架空食品店Bにおいて、Mercuryの主要メトリクス系列が15分間欠損する事象が発生しました。この問題は、Venus Azure APに関連しており、運用部門のみが影響を受けました。発生の契機はインフラメンテナンス明けであり、メトリクスエージェントの再起動が失敗したことが推定されます。この間、運用一郎が監視していたところ、メトリクス欠損を検知したのは、発生から51分後の16:07:05でした。影響の範囲は限定的でしたが、監視・可用性障害として対応が必要とされます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00704', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00704', 'INC-2023-00704', '本事象の調査において、インフラメンテナンス明けにメトリクスエージェントの再起動が失敗したことが確認されました。この再起動失敗が主要メトリクス系列の欠損を引き起こし、結果として15分間のメトリクス欠損が発生しました。今後は、エージェントの再起動手順の見直し及び監視体制の強化が必要です。', '本事象の調査において、インフラメンテナンス明けにメトリクスエージェントの再起動が失敗したことが確認されました。この再起動失敗が主要メトリクス系列の欠損を引き起こし、結果として15分間のメトリクス欠損が発生しました。今後は、エージェントの再起動手順の見直し及び監視体制の強化が必要です。', TIMESTAMP WITH TIME ZONE '2023-03-06T15:46:05+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01043', 'INC-2023-00704', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-05T16:01:05+09:00', TIMESTAMP WITH TIME ZONE '2023-03-05T17:01:05+09:00', '初期対応', '運用一郎が事象を確認後、即時にメトリクスエージェントの状態を調査し、再起動手順を実行しました。再起動後、メトリクスが正常に収集されることを確認し、顧客に対して状況を報告しました。また、再発防止策として、エージェントの監視体制の強化を提案しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01044', 'INC-2023-00704', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-05T17:31:05+09:00', TIMESTAMP WITH TIME ZONE '2023-03-05T18:31:05+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00721', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-09-28T15:16:26+09:00', TIMESTAMP WITH TIME ZONE '2023-09-28T15:46:26+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '2023年10月10日15:16に、株式会社ストッククラウドのMercuryにおいて、データ移行バッチ実行中に同期メッセージがデッドレターに大量蓄積する事象が発生しました。運用部の運用 一郎が発見し、15:42に検知されました。この事象の推定原因はデッドレター再処理ジョブの未設定です。この影響はバッチ処理のみで、オンラインには影響がありません。エラーコードはSYNC-08-00721です。データの同期や整合性に関わる問題が懸念されるため、早急な対応が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00721', 'INC-2023-00721', '運用 一郎による調査の結果、データ移行バッチ実行中に発生したデッドレターの蓄積が確認されました。特に、デッドレター再処理ジョブが未設定であったことが原因と考えられます。これにより、メッセージキューに蓄積されたデッドレターが処理されず、正常なデータ同期が妨げられています。今後の対策として、デッドレター再処理ジョブの設定が急務です。', '運用 一郎による調査の結果、データ移行バッチ実行中に発生したデッドレターの蓄積が確認されました。特に、デッドレター再処理ジョブが未設定であったことが原因と考えられます。これにより、メッセージキューに蓄積されたデッドレターが処理されず、正常なデータ同期が妨げられています。今後の対策として、デッドレター再処理ジョブの設定が急務です。', TIMESTAMP WITH TIME ZONE '2023-09-29T15:46:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01066', 'INC-2023-00721', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-09-28T16:01:26+09:00', TIMESTAMP WITH TIME ZONE '2023-09-28T17:01:26+09:00', '【初期対応】【データ同期・整合性障害】デッドレター蓄積に対する初期対応', '運用 一郎が事象を確認後、関係者に通知しました。まずはデッドレターの状況を把握し、デッドレター再処理ジョブの設定を急ぎ行う必要があります。これにより、データの同期と整合性を回復するための初期対応を開始しました。メッセージキューの監視を強化し、今後同様の事象が発生しないように対策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01067', 'INC-2023-00721', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-09-28T17:31:26+09:00', TIMESTAMP WITH TIME ZONE '2023-09-28T18:31:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00730', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-01-14T12:45:30+09:00', TIMESTAMP WITH TIME ZONE '2023-01-14T14:45:30+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023年1月14日12時45分30秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客である架空食品店A及び架空食品店Bの店舗POSにおいて、マスター更新と在庫が二重反映される事象が発生しました。本障害は定例リリース直後に確認され、全店舗に影響を及ぼしました。エラーコードはSYNC-01-00730です。検知時刻は2023年1月14日14時37分30秒であり、問題発生から112分後に判明しました。現在、原因としてイベント順序の逆転配信が疑われており、この問題によって在庫情報の不整合が生じています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00730', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00730', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00730', 'INC-2023-00730', '調査の結果、定例リリース直後に発生したマスター更新と在庫の二重反映について、イベント順序の逆転配信が主な要因であることが確認されました。この問題は、顧客店舗POSにおけるデータ同期・整合性に対する重大な影響を及ぼしました。現在、他の店舗においても同様の問題が発生していないか、確認が進められています。引き続き、影響範囲の特定と是正措置を講じる必要があります。', '調査の結果、定例リリース直後に発生したマスター更新と在庫の二重反映について、イベント順序の逆転配信が主な要因であることが確認されました。この問題は、顧客店舗POSにおけるデータ同期・整合性に対する重大な影響を及ぼしました。現在、他の店舗においても同様の問題が発生していないか、確認が進められています。引き続き、影響範囲の特定と是正措置を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2023-01-15T14:45:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01078', 'INC-2023-00730', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-01-14T15:00:30+09:00', TIMESTAMP WITH TIME ZONE '2023-01-14T16:00:30+09:00', '【対応ログ】【データ同期・整合性障害】マスター在庫二重反映', '本事象を受けて、担当の営業部 花子が直ちに対応を開始しました。初期対応として、顧客店舗POSの設定を確認し、在庫データの整合性を調査しました。問題の発生した顧客店舗に対して、状況説明と謝罪を行い、影響範囲を特定するための調査を進めています。今後、必要に応じて追加の技術的対策を検討し、早急に正常な状態へ戻すことを目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01079', 'INC-2023-00730', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-01-14T16:30:30+09:00', TIMESTAMP WITH TIME ZONE '2023-01-14T17:30:30+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00734', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2023-02-13T15:47:55+09:00', TIMESTAMP WITH TIME ZONE '2023-02-13T16:02:55+09:00', '【障害報告】【CLU-08】リフレッシュトークン再利用', '2023年3月1日、株式会社ストッククラウドのサービスMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。具体的には、リフレッシュトークンの再利用が検知され、全端末がログアウトする事態となりました。この問題は、年末年始の稼働切替時にトークンローテーションの実装に不備があったことが推定されます。影響範囲は、同一顧客の全店舗で、運用コンソール（ゾーンB）およびセッションストアに関連する全ての操作に影響が及びました。これにより、顧客はサービスを利用できなくなり、運用部の運用 一郎が発見しました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00734', 'INC-2023-00734', '本障害の調査を行った結果、年末年始の稼働切替時にリフレッシュトークン再利用が発生した原因として、トークンローテーションの実装に不備があったことが確認されました。この不備により、全端末がログアウトし、認証・セッションの管理に深刻な影響を与えました。今後は、この問題を防ぐために、トークンローテーションの実装を見直す必要があります。', '本障害の調査を行った結果、年末年始の稼働切替時にリフレッシュトークン再利用が発生した原因として、トークンローテーションの実装に不備があったことが確認されました。この不備により、全端末がログアウトし、認証・セッションの管理に深刻な影響を与えました。今後は、この問題を防ぐために、トークンローテーションの実装を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2023-02-14T16:02:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01086', 'INC-2023-00734', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-02-13T16:17:55+09:00', TIMESTAMP WITH TIME ZONE '2023-02-13T17:17:55+09:00', '【初動対応】【CLU-08】リフレッシュトークン再利用', 'インシデント発生後、初動対応として運用部は速やかに全端末のログイン状況を確認し、影響を受けた顧客へ適切な情報提供を行いました。また、運用コンソールの状態を確認し、トークンローテーション処理を一時的に停止する措置を講じました。これにより、再発防止に向けた対策がスタートしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00738', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-05-21T18:40:01+09:00', TIMESTAMP WITH TIME ZONE '2023-05-21T19:10:01+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2023年5月21日18時40分、株式会社ストッククラウドのMercuryにおいて、架空食品店Bからの在庫登録に関する重大な障害が発生しました。症状として、在庫CSVの3行目以降が取込されないという問題が確認されました。この問題はデータ移行バッチ実行中に発生しており、検知までに36分を要しました。影響範囲はバッチ処理に限定され、オンラインには影響がありません。エラーコードはMST-03-00738です。推定原因はJANコード重複チェックの誤設定と考えられています。技術的には、データ移行バッチ実行中にJANコードの重複チェックが誤って設定されており、その結果、在庫CSVの3行目以降のデータが取込されない状況が発生しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00738', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00738', 'INC-2023-00738', '障害発生直後から、運用部の運用 一郎が調査を開始しました。まず、在庫CSVファイルの内容を確認し、3行目以降のデータが取込されていないことを確認しました。次に、データ移行バッチの設定を確認したところ、JANコード重複チェックに関する設定に誤りがあることが判明しました。この誤設定が原因で、CSVファイルの適切なデータが読み込まれていなかったことがわかりました。現在、設定の修正を進めています。', '障害発生直後から、運用部の運用 一郎が調査を開始しました。まず、在庫CSVファイルの内容を確認し、3行目以降のデータが取込されていないことを確認しました。次に、データ移行バッチの設定を確認したところ、JANコード重複チェックに関する設定に誤りがあることが判明しました。この誤設定が原因で、CSVファイルの適切なデータが読み込まれていなかったことがわかりました。現在、設定の修正を進めています。', TIMESTAMP WITH TIME ZONE '2023-05-22T19:10:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01092', 'INC-2023-00738', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-05-21T19:25:01+09:00', TIMESTAMP WITH TIME ZONE '2023-05-21T20:25:01+09:00', '【初動対応】【在庫マスター設定障害】CSVバッチ取込欠損', '初動対応として、運用 一郎が障害発生の報告を受け、直ちに在庫CSVの取込状況を確認しました。設定ミスが原因と考えられるため、JANコード重複チェックの修正作業を開始し、エラーコードMST-03-00738に基づく対応を行っています。影響を受けた顧客への連絡も行い、状況を説明するとともに、復旧作業を進める旨を伝えています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01093', 'INC-2023-00738', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-05-21T20:55:01+09:00', TIMESTAMP WITH TIME ZONE '2023-05-21T21:55:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00766', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-03-12T19:17:20+09:00', TIMESTAMP WITH TIME ZONE '2023-03-12T19:47:20+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2023年3月12日19時17分20秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bが登録したデータに対し、パートナーAPIが429を返し連携停止の事象が発生しました。この障害は、大規模セール開始直前に発生したものであり、サービス全体の一部機能に影響を及ぼしました。私たちはこの事象を運用部の運用 一郎が発見し、即座に原因を調査しました。推定原因として呼出頻度の事前調整不足が考えられます。エラーコードはEDI-06-00766で、影響コンポーネントにはMercury AWS AP（DRサイト）およびAPIゲートウェイが含まれています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00766', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00766', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00766', 'INC-2023-00766', '調査の結果、大規模セール開始直前においてパートナーAPIが429を返したことが確認されました。この事象は、呼出頻度の事前調整が不十分であったことが原因であると考えられます。今後は、事前にAPIの呼出頻度を見直し、適切な調整を行う必要があります。また、この影響により、特定の機能が利用できなくなったことが確認されており、サービス全体への影響を考慮する必要があります。', '調査の結果、大規模セール開始直前においてパートナーAPIが429を返したことが確認されました。この事象は、呼出頻度の事前調整が不十分であったことが原因であると考えられます。今後は、事前にAPIの呼出頻度を見直し、適切な調整を行う必要があります。また、この影響により、特定の機能が利用できなくなったことが確認されており、サービス全体への影響を考慮する必要があります。', TIMESTAMP WITH TIME ZONE '2023-03-13T19:47:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01137', 'INC-2023-00766', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-12T20:02:20+09:00', TIMESTAMP WITH TIME ZONE '2023-03-12T21:02:20+09:00', '【初動対応】【API連携・EDI障害】レート超過429', '運用 一郎が障害を発見した時点で、すぐに関係者へ通知しました。その後、運用チームは緊急で対応を開始し、影響範囲の特定を行いました。APIの呼出頻度についての確認を行い、再発防止策を検討することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01138', 'INC-2023-00766', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-03-12T21:32:20+09:00', TIMESTAMP WITH TIME ZONE '2023-03-12T22:32:20+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00767', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-11-30T17:53:21+09:00', TIMESTAMP WITH TIME ZONE '2023-11-30T19:53:21+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2023年11月30日17時53分に発生した棚卸突合失敗のインシデントについて報告いたします。本事象は、株式会社ストッククラウドのサービス「Mercury」において、顧客店舗POSにてマスター更新と在庫が二重反映されるという症状が確認されました。影響範囲は、架空食品店Bおよび架空食品店Aの全店舗に及びました。定例リリース直後に発生したことから、イベント順序の逆転配信が推定原因として疑われます。お客様にはご不便をおかけし、深くお詫び申し上げます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00767', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00767', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00767', 'INC-2023-00767', '本障害に関する調査を行った結果、定例リリース直後に顧客店舗POSおよびイベントバスにおいて、イベント順序の逆転配信が発生し、マスター更新と在庫が二重反映される事象が引き起こされたことが確認されました。今後、再発防止策を講じる必要があります。', '本障害に関する調査を行った結果、定例リリース直後に顧客店舗POSおよびイベントバスにおいて、イベント順序の逆転配信が発生し、マスター更新と在庫が二重反映される事象が引き起こされたことが確認されました。今後、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2023-12-01T19:53:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01139', 'INC-2023-00767', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-11-30T20:08:21+09:00', TIMESTAMP WITH TIME ZONE '2023-11-30T21:08:21+09:00', '初期対応', '本事象が発生した際、弊社の営業部の花子が即座に状況を確認し、顧客に対して情報提供を行いました。また、技術チームは速やかに問題の調査を開始し、影響を受けた顧客に対して適切な対応策を検討しました。二重反映の原因がイベント順序の逆転配信であるとの仮説の下、さらに詳細な分析を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01140', 'INC-2023-00767', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-11-30T21:38:21+09:00', TIMESTAMP WITH TIME ZONE '2023-11-30T22:38:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00778', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2023-04-05T07:09:17+09:00', TIMESTAMP WITH TIME ZONE '2023-04-05T09:09:17+09:00', '【障害報告】【データ同期・整合性障害】クロスリージョンレプリケーション', '2023年4月5日、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSにて棚卸突合失敗が発生しました。発見者は営業部の花子で、影響を受けた顧客は架空食品店Bおよび架空食品店Aです。症状としては、クロスリージョン複製が片系のみ更新され、特定リージョンのユーザーに影響が及びました。発生契機はインフラメンテナンス明けであり、エラーコードはSYNC-07-00778です。この事象は178分後に検知され、迅速な対応が求められました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00778', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00778', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00778', 'INC-2023-00778', '調査の結果、インフラメンテナンス明けにおいてクロスリージョン複製が片系のみ更新される事象が確認されました。原因としてはリージョンルーティングの誤設定が疑われます。特定のリージョンにおいてデータの同期・整合に問題が発生していることが明らかとなり、影響範囲は特定リージョンのユーザーのみに限定されていることが確認されています。', '調査の結果、インフラメンテナンス明けにおいてクロスリージョン複製が片系のみ更新される事象が確認されました。原因としてはリージョンルーティングの誤設定が疑われます。特定のリージョンにおいてデータの同期・整合に問題が発生していることが明らかとなり、影響範囲は特定リージョンのユーザーのみに限定されていることが確認されています。', TIMESTAMP WITH TIME ZONE '2023-04-06T09:09:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01156', 'INC-2023-00778', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-04-05T09:24:17+09:00', TIMESTAMP WITH TIME ZONE '2023-04-05T10:24:17+09:00', '初期対応', '初期対応として、リージョンのルーティング設定を確認し、誤設定がないか調査を開始しました。また、影響を受けた顧客に対しては、事象の説明と今後の対応について通知を行い、影響を最小限に抑えるための措置を講じました。継続的に状況をモニタリングし、必要な対策を実施する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01157', 'INC-2023-00778', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-04-05T10:54:17+09:00', TIMESTAMP WITH TIME ZONE '2023-04-05T11:54:17+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00784', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2023-10-01T15:40:11+09:00', TIMESTAMP WITH TIME ZONE '2023-10-01T16:40:11+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2023年10月01日15時40分、株式会社ストッククラウドの顧客である架空食品店Bにおいて、顧客拠点NWでISP側BGP経路障害が発生しました。この障害により、架空食品店B及び架空食品店Aの全店舗が同時にネットワーク不通となりました。16時29分に検知され、発見者は営業部の花子です。インフラメンテナンス明けに発生したため、推定原因はISP側のBGP経路障害と考えられます。各店舗に影響を及ぼす事態となっており、早急な対応が求められます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00784', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00784', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00784', 'INC-2023-00784', '顧客拠点NWにおけるBGP経路障害の調査を行いました。ISP側のBGP経路に異常が発生し、複数拠点が同時不通となっています。技術詳細では、インフラメンテナンス明けにこの障害が顕在化したことが確認されました。問題の根本原因として、ISP側のBGP経路障害が疑われ、現在はISPと連携し、正常化の見込みを探っています。', '顧客拠点NWにおけるBGP経路障害の調査を行いました。ISP側のBGP経路に異常が発生し、複数拠点が同時不通となっています。技術詳細では、インフラメンテナンス明けにこの障害が顕在化したことが確認されました。問題の根本原因として、ISP側のBGP経路障害が疑われ、現在はISPと連携し、正常化の見込みを探っています。', TIMESTAMP WITH TIME ZONE '2023-10-02T16:40:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01166', 'INC-2023-00784', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-10-01T16:55:11+09:00', TIMESTAMP WITH TIME ZONE '2023-10-01T17:55:11+09:00', '【対応ログ】【顧客ネットワーク障害】BGP経路障害波及 - 初期対応', 'ISP側に対し、BGP経路障害の状況を確認しました。現在、障害の解消に向けた作業が進められており、進捗状況を随時確認しながら、顧客に対しても適宜情報提供を行う方針です。顧客におかれましては、引き続きご不便をおかけしており申し訳ありませんが、回復までお待ちいただくようお願い申し上げます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01167', 'INC-2023-00784', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2023-10-01T18:25:11+09:00', TIMESTAMP WITH TIME ZONE '2023-10-01T19:25:11+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00798', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2023-02-16T22:47:52+09:00', TIMESTAMP WITH TIME ZONE '2023-02-16T23:02:52+09:00', '【障害報告】【運用操作・権限障害】運用コンソールログイン不可', '2023年2月16日22時47分52秒に、顧客である架空食品店Bにおいて運用コンソールへのログインが不可能な事象が発生しました。本事象は運用コンソールにログインできないという症状が見られ、影響範囲は全テナントに波及しています。推定原因としてはIAMポリシーの誤削除が考えられており、定例リリース直後に発生したことが契機となっています。この問題に対する技術詳細としては、運用コンソールにログインできない状況が続いており、原因の特定が急務です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00798', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2023-00798', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00798', 'INC-2023-00798', '発生した障害に関して、運用部の運用 一郎が検知したのは発生から10分後の22時57分52秒でした。調査の結果、IAMポリシーが誤って削除された可能性が高いと推測されます。運用コンソールのログイン障害は、全テナントに対して影響を及ぼすため、早急な対応が必要です。', '発生した障害に関して、運用部の運用 一郎が検知したのは発生から10分後の22時57分52秒でした。調査の結果、IAMポリシーが誤って削除された可能性が高いと推測されます。運用コンソールのログイン障害は、全テナントに対して影響を及ぼすため、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2023-02-17T23:02:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01189', 'INC-2023-00798', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-02-16T23:17:52+09:00', TIMESTAMP WITH TIME ZONE '2023-02-17T00:17:52+09:00', '【初期対応】運用コンソールログイン不可', '運用部は22時58分より初期対応を開始し、IAMポリシーの復元を試みました。運用コンソールへのアクセス障害は重大度が高いため、専任チームを立ち上げ、影響を受けたテナントに対して情報提供を行い、ログイン問題の早期解決に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2023-00801', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2023-10-14T05:27:17+09:00', TIMESTAMP WITH TIME ZONE '2023-10-14T05:57:17+09:00', '【障害報告】【在庫マスター設定障害】商品同期全件失敗', '2023年10月14日05時27分17秒に発生したインシデントにより、商品マスター同期後に在庫登録が全件失敗する事象が発生しました。本事象は、株式会社ストッククラウドのサービスMercuryにおいて、顧客オンボーディング当日に発生しました。影響範囲はサービス全体の一部機能であり、エラーコードはMST-04-00801です。推定原因としては、カテゴリ階層の循環参照が考えられます。影響を受けたコンポーネントはMercury AWS AP（DRサイト）及び商品マスターDBです。この問題は運用部の運用 一郎によって検知され、05時59分17秒に確認されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00801', 'INC-2023-00801', 'インシデント発生後の調査において、商品マスター同期が行われた際にカテゴリ階層の循環参照が確認されました。この循環参照により、在庫登録が正常に行われず、全件失敗する結果となりました。調査チームは、具体的なデータパターンを分析し、影響を及ぼした設定ミスを特定しました。今後の対策として、マスター設定の見直しとテストプロセスの強化を検討しています。', 'インシデント発生後の調査において、商品マスター同期が行われた際にカテゴリ階層の循環参照が確認されました。この循環参照により、在庫登録が正常に行われず、全件失敗する結果となりました。調査チームは、具体的なデータパターンを分析し、影響を及ぼした設定ミスを特定しました。今後の対策として、マスター設定の見直しとテストプロセスの強化を検討しています。', TIMESTAMP WITH TIME ZONE '2023-10-15T05:57:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01194', 'INC-2023-00801', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2023-10-14T06:12:17+09:00', TIMESTAMP WITH TIME ZONE '2023-10-14T07:12:17+09:00', '【初動対応】【在庫マスター設定障害】商品同期全件失敗', '初動対応として、本インシデントに関しては速やかに運用部の運用 一郎が対応を開始しました。顧客への影響を最小限に抑えるため、緊急対応チームが編成され、事象の詳細確認及び影響範囲の特定が行われました。関連部門と連携し、設定の見直しを行う準備を進めており、必要に応じて顧客への報告を行う方針です。運用部では再発防止策を講じるための検討も開始いたしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00001', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-06-02T16:34:32+09:00', TIMESTAMP WITH TIME ZONE '2024-06-02T17:04:32+09:00', '【障害報告】【在庫マスター設定障害】多言語商品名登録失敗', '2024年6月2日16時34分32秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店A及び架空食品店Bの顧客に影響を及ぼす在庫マスター設定ミスによる商品名の登録失敗が発生しました。具体的には、多言語商品名の登録保存時に制約違反が発生し、その影響範囲はサービス全体の一部機能に及んでいます。この問題は、インフラメンテナンス明けに発生したことが特に重要です。エラーコードはMST-09-00001で、影響コンポーネントはMercury AWS AP（ゾーンB）および商品マスターDBです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00001', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00001', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00001', 'INC-2024-00001', 'このインシデントに関する調査を実施した結果、ロケール別名称テーブルの欠損が原因として特定されました。多言語商品名の登録保存時に制約違反が発生し、正常な登録処理ができない状況にありました。この現象はインフラメンテナンス明けのタイミングで顕在化し、今後の対策としてテーブルの整合性確認と再構築が必要です。', 'このインシデントに関する調査を実施した結果、ロケール別名称テーブルの欠損が原因として特定されました。多言語商品名の登録保存時に制約違反が発生し、正常な登録処理ができない状況にありました。この現象はインフラメンテナンス明けのタイミングで顕在化し、今後の対策としてテーブルの整合性確認と再構築が必要です。', TIMESTAMP WITH TIME ZONE '2024-06-03T17:04:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00001', 'INC-2024-00001', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-06-02T17:19:32+09:00', TIMESTAMP WITH TIME ZONE '2024-06-02T18:19:32+09:00', '【初期対応】【在庫マスター設定障害】多言語商品名登録失敗', '初期対応として、運用部の運用 一郎が16時40分にインシデントを確認し、関連データのバックアップを取得しました。その後、影響を受けた顧客への通知を開始し、状況を共有しました。ロケール別名称テーブルの欠損が原因であることを見込み、テーブルの修復作業を17時05分に開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00002', 'INC-2024-00001', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-06-02T18:49:32+09:00', TIMESTAMP WITH TIME ZONE '2024-06-02T19:49:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00005', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-22T15:44:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T16:14:31+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2024年8月22日15時44分31秒に、株式会社ストッククラウドのVenusサービスにおいて、メトリクス欠損が発生しました。主要メトリクス系列が15分間欠損し、この問題は運用部門にのみ影響を及ぼしました。発生契機はインフラメンテナンス明けであり、問題が検知されるまでに19分を要しました。検知は16時03分31秒でした。エラーコードはMON-04-00005で、メトリクスエージェントの再起動失敗が推定原因と考えられます。今後の監視・可用性障害に対処するための教訓として、エージェントの監視体制の強化が必要です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00005', 'INC-2024-00005', '問題の調査を行った結果、インフラメンテナンス後に主要メトリクス系列が15分間欠損したことが確認されました。この欠損は、メトリクスエージェントの再起動が適切に行われなかったことに起因していると考えられます。運用部門からの報告により、迅速な検知と原因特定がなされましたが、エージェントの状態を常に確認する監視体制の向上が求められます。', '問題の調査を行った結果、インフラメンテナンス後に主要メトリクス系列が15分間欠損したことが確認されました。この欠損は、メトリクスエージェントの再起動が適切に行われなかったことに起因していると考えられます。運用部門からの報告により、迅速な検知と原因特定がなされましたが、エージェントの状態を常に確認する監視体制の向上が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-23T16:14:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00009', 'INC-2024-00005', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-22T16:29:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T17:29:31+09:00', '【初期対応】【監視・可用性障害】メトリクス欠損の初期対応', 'インシデント発生後、運用部の運用 一郎が即座に対応チームを編成し、メトリクスエージェントの状態を確認しました。再起動手順が実施され、主要メトリクス系列が正常に復旧しました。今後は、同様の問題を未然に防ぐために、定期的なメトリクスエージェントの健康チェックを行うことが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00006', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-28T21:18:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T21:48:19+09:00', '【障害報告】【在庫マスター設定障害】バーコード照合エラー', '2024年8月28日21時18分に、株式会社ストッククラウドのVenusにおいて、新規店舗追加の初日にバーコードスキャン後に照合エラーが発生し、登録が不可能となった事象が確認されました。影響範囲は単一店舗のみで、Mercury AWS AP（ゾーンB）とPOS連携アダプタに関連しています。チェックディジット検証ロジックの誤設定が推定原因とされており、21時59分にこの事象が検知されました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00006', 'INC-2024-00006', '運用部の運用 一郎です。新規店舗追加初日におけるバーコードスキャン後の照合エラー問題について調査を進めます。検証ロジックの設定に誤りがある可能性が高いため、各コードの確認及びテストを実施します。問題の根本的な解決を図るため、影響を受けたコンポーネントの詳細な分析を行います。', '運用部の運用 一郎です。新規店舗追加初日におけるバーコードスキャン後の照合エラー問題について調査を進めます。検証ロジックの設定に誤りがある可能性が高いため、各コードの確認及びテストを実施します。問題の根本的な解決を図るため、影響を受けたコンポーネントの詳細な分析を行います。', TIMESTAMP WITH TIME ZONE '2024-08-29T21:48:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00010', 'INC-2024-00006', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T22:03:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T23:03:19+09:00', '【初期対応】【在庫マスター設定障害】バーコード照合エラー対応', '運用 一郎がこの問題に対応します。まずはバーコードスキャン時の処理フローを確認し、エラーの原因を特定するためのログ収集を開始します。影響を受けた店舗のスタッフにも状況を共有し、適切な対応をお願いする予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00011', 'INC-2024-00006', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T23:33:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T00:33:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00008', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-17T20:23:23+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T22:23:23+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2024年8月17日20時23分23秒に、株式会社ストッククラウドのサービスVenusにおいて、棚卸突合失敗が発生しました。具体的には、顧客店舗POSにてバルクAPIが部分失敗し、ロールバックが未完了となりました。発見者は営業部の花子であり、検知は21時56分に行われ、検知までに93分を要しました。この問題は、データ移行バッチ実行中に生じたもので、部分成功時の補償トランザクションが欠如していたことが推定されています。影響範囲はサービス全体の一部機能に及び、エラーコードはEDI-10-00008です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00008', 'INC-2024-00008', '本件の調査において、データ移行バッチ実行中にバルクAPIが部分失敗したことが確認されました。ロールバックが未完了であったため、顧客店舗POSに影響を及ぼしました。分析の結果、部分成功時の補償トランザクションが欠如していたことが原因であると考えられます。今後はこのような事例を防ぐために、補償トランザクションの実装を強化し、バルクAPIの監視を徹底する必要があります。', '本件の調査において、データ移行バッチ実行中にバルクAPIが部分失敗したことが確認されました。ロールバックが未完了であったため、顧客店舗POSに影響を及ぼしました。分析の結果、部分成功時の補償トランザクションが欠如していたことが原因であると考えられます。今後はこのような事例を防ぐために、補償トランザクションの実装を強化し、バルクAPIの監視を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-18T22:23:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00013', 'INC-2024-00008', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-17T22:38:23+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T23:38:23+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗への初期対応', '発生した障害に対し、初期対応として、営業部の花子が顧客店舗POSの状況を確認しました。また、技術チームに連絡を取り、バルクAPIの状態を調査し、ロールバックの処理が完了していないことを確認しました。調査結果をもとに、迅速に対応策を講じる必要があることをチーム全体で共有しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00011', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-08T22:04:35+09:00', TIMESTAMP WITH TIME ZONE '2024-08-08T23:04:35+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2024年8月8日22時04分、株式会社ストッククラウドの顧客において、ISP側BGP経路障害が発生し、複数拠点が同時不通となりました。発見者は営業部の花子で、発見されたのは22時27分でした。インフラメンテナンス明けのタイミングでの障害発生が確認され、全店舗が影響を受けています。エラーコードはNW-06-00011です。ISP側のBGP経路障害による顧客ネットワークの影響範囲は広範で、顧客の業務に支障をきたしています。今後の対応が必要です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00011', 'INC-2024-00011', 'ISP側のBGP経路障害について調査を行いました。インフラメンテナンス後に発生したことから、メンテナンスが関連している可能性が高いです。複数拠点が同時に影響を受けていることから、ISP全体での障害ではないかと考えられます。具体的な原因はISP側の調査を待つ必要がありますが、現在のところ、技術的な問題が疑われます。', 'ISP側のBGP経路障害について調査を行いました。インフラメンテナンス後に発生したことから、メンテナンスが関連している可能性が高いです。複数拠点が同時に影響を受けていることから、ISP全体での障害ではないかと考えられます。具体的な原因はISP側の調査を待つ必要がありますが、現在のところ、技術的な問題が疑われます。', TIMESTAMP WITH TIME ZONE '2024-08-09T23:04:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00017', 'INC-2024-00011', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-08T23:19:35+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T00:19:35+09:00', '【初動対応】【顧客ネットワーク障害】BGP経路障害波及', '初動対応として、ISPへの問い合わせを行い、障害の詳細情報を確認しました。全店舗に影響が出ているため、顧客への連絡を行い、状況を説明するとともに、復旧作業の進捗を共有することを約束しました。障害の影響を最小限に抑えるための対応策についても協議を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00019', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-07T03:03:18+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T05:03:18+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '2024年8月7日03:03:18に、株式会社ストッククラウドのサービスVenusにおいて、顧客店舗POSでの棚卸突合失敗が発生しました。この障害により、同期メッセージがデッドレターに大量蓄積される事象が確認されました。営業部の花子が発見したこの問題は、2024年8月7日06:10:18に検知されました。検知までの時間は187分であり、影響範囲はバッチ処理のみに限られています。この問題はデータ移行バッチ実行中に発生しており、デッドレター再処理ジョブの未設定が原因であると考えられます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00019', 'INC-2024-00019', '調査の結果、データ移行バッチ実行中に発生した同期メッセージがデッドレターに大量蓄積していることが確認されました。これにより、オンラインサービスへの影響はありませんが、バッチ処理が正常に行われていない状況が続いています。原因として、デッドレター再処理ジョブが未設定である可能性が高いと判断されます。対応を急ぎ、設定を行う必要があります。', '調査の結果、データ移行バッチ実行中に発生した同期メッセージがデッドレターに大量蓄積していることが確認されました。これにより、オンラインサービスへの影響はありませんが、バッチ処理が正常に行われていない状況が続いています。原因として、デッドレター再処理ジョブが未設定である可能性が高いと判断されます。対応を急ぎ、設定を行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-08T05:03:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00027', 'INC-2024-00019', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-07T05:18:18+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T06:18:18+09:00', '【初期対応】【データ同期・整合性障害】デッドレター蓄積について', '初期対応として、データ移行バッチに関連するログを確認し、デッドレターに蓄積されたメッセージの内容を調査します。また、再処理ジョブの設定状況を確認し、必要な設定を行う方針です。営業部の花子は、進捗を随時報告し、問題解決に向けてチームで連携を図ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00023', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-16T12:32:02+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T13:32:02+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '2024年8月16日12時32分に株式会社ストッククラウドのサービスVenusにおいて、顧客側ネットワーク障害が発生しました。発生場所は顧客拠点NWであり、症状としては店舗Wi-Fiの認証ページでAPI通信が遮断されていることが確認されました。発見者は営業部の花子であり、顧客の影響は単一店舗のみです。推定原因としては、キャプティブポータルによるHTTPSインターセプトが疑われます。新規店舗追加の初日であり、エラーコードはNW-09-00023です。検知は2024年8月16日13時41分に行われ、検知までの時間は69分でした。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00023', 'INC-2024-00023', '本障害について調査を行いましたところ、新規店舗追加の初日にあたることが確認されました。技術詳細として、店舗Wi-Fiの認証ページにおいてAPI通信が遮断されていることが判明しました。HTTPSインターセプトが原因である可能性が高く、今後の対策が必要です。影響を受けたのは顧客拠点NW（DRサイト）および顧客側FWです。今後、詳細な原因究明および対応策を講じる必要があります。', '本障害について調査を行いましたところ、新規店舗追加の初日にあたることが確認されました。技術詳細として、店舗Wi-Fiの認証ページにおいてAPI通信が遮断されていることが判明しました。HTTPSインターセプトが原因である可能性が高く、今後の対策が必要です。影響を受けたのは顧客拠点NW（DRサイト）および顧客側FWです。今後、詳細な原因究明および対応策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-17T13:32:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00032', 'INC-2024-00023', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-16T13:47:02+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T14:47:02+09:00', '【初期対応】【顧客ネットワーク障害】Wi-Fi captive portal', 'この度は、店舗Wi-Fiにおける認証ページでのAPI通信遮断について、初期対応を実施いたしました。現在、キャプティブポータルの設定を確認し、HTTPSインターセプトの影響を受けているかどうかを調査中です。お客様にはご不便をおかけしておりますが、早急な復旧を目指して対応を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00025', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-10T13:37:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T14:37:19+09:00', '【障害報告】【顧客ネットワーク障害】回線断後セッション未復旧', '2024年8月10日13時37分に株式会社ストッククラウドのVenusサービスにて、顧客拠点NWで回線断が発生しました。14時45分に検知された時点で、拠点回線は復旧していましたが、セッションが復旧しない状況が続いています。拠点のWi-Fi接続が正常であったにもかかわらず、VPN接続が確立されず、業務に影響を及ぼしております。影響を受けているのは単一店舗であり、エラーコードはNW-05-00025です。また、発生契機は年末年始の稼働切替時であり、技術的にはVPNクライアントのバージョン不整合が推定されています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00025', 'INC-2024-00025', '調査の結果、拠点回線は復旧しているにもかかわらず、セッションが復旧しない現象が確認されました。特に、VPNクライアントのバージョン不整合が問題として挙げられ、これが原因でVPN接続が正常に確立できない状況を引き起こしている可能性があります。今後、クライアントのバージョン確認及び更新が必要です。', '調査の結果、拠点回線は復旧しているにもかかわらず、セッションが復旧しない現象が確認されました。特に、VPNクライアントのバージョン不整合が問題として挙げられ、これが原因でVPN接続が正常に確立できない状況を引き起こしている可能性があります。今後、クライアントのバージョン確認及び更新が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-11T14:37:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00034', 'INC-2024-00025', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-10T14:52:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T15:52:19+09:00', '【対応ログ】【顧客ネットワーク障害】回線断後セッション未復旧', '初期対応として、本事象に関するログを収集し、影響範囲の確認を行いました。関連するクライアントのバージョン情報を調査し、最新のバージョンへの更新を推奨いたします。必要に応じて、顧客との連携を行い、状況の把握を図ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00035', 'INC-2024-00025', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-10T16:22:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T17:22:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00026', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-20T05:33:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T06:33:40+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '株式会社ストッククラウドのVenusサービスにおいて、2024年8月20日05時33分40秒に顧客拠点NWで顧客側ネットワーク障害が発生しました。顧客はなし、発見者は営業部の花子です。大規模セール開始直前に、代理サーバー経由のアクセスで502エラーが返され、影響を受けたのは単一店舗の顧客ネットワークです。プロキシの上流タイムアウト設定が過短であることが推定原因と考えられます。障害は2024年8月20日06時05分40秒に検知され、検知までに32分の時間を要しました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00026', 'INC-2024-00026', '障害の発生に関して、詳細な調査を実施しました。代理サーバー経由でのアクセスが502エラーを引き起こしている状況を確認し、原因としてプロキシの上流タイムアウト設定が過短である可能性を確認しました。大規模セール直前の影響で、顧客拠点NWや顧客側FWに問題が発生したことが明らかになりました。今後の対策として、タイムアウト設定の見直しが必要です。', '障害の発生に関して、詳細な調査を実施しました。代理サーバー経由でのアクセスが502エラーを引き起こしている状況を確認し、原因としてプロキシの上流タイムアウト設定が過短である可能性を確認しました。大規模セール直前の影響で、顧客拠点NWや顧客側FWに問題が発生したことが明らかになりました。今後の対策として、タイムアウト設定の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-21T06:33:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00036', 'INC-2024-00026', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-20T06:48:40+09:00', NULL, '【初動対応】【顧客ネットワーク障害】代理サーバー502', '初動対応として、代理サーバーのタイムアウト設定の確認を行いました。502エラーの原因として、プロキシの上流タイムアウト設定が過短であることが明らかになりました。そのため、設定の見直しと調整を行い、再発防止策を講じる必要があります。また、顧客に対して状況説明を行い、影響範囲を報告することが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00028', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-03T05:29:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T07:29:58+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2024年8月3日05:29に、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSで読取レプリカ遅延が発生。これにより在庫照会が古い値を表示し、顧客への影響が懸念される。06:54に検知に至った。発見者は営業部の花子であり、大規模セール開始直前のタイミングでの発生であった。特定リージョンのユーザーのみが影響を受けた模様。エラーコードはSYNC-02-00028であり、レプリケーション遅延の監視閾値超過が推定原因である。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00028', 'INC-2024-00028', '調査において、発生したレプリカ遅延は、大規模セール開始直前に発生したことが確認された。在庫照会で表示された古い値は、特定の顧客店舗POSでのみ確認されており、他の店舗への影響は見られなかった。原因として、レプリケーション遅延の監視閾値を超過したことが考えられる。今後の対策として、監視体制の見直しが必要である。', '調査において、発生したレプリカ遅延は、大規模セール開始直前に発生したことが確認された。在庫照会で表示された古い値は、特定の顧客店舗POSでのみ確認されており、他の店舗への影響は見られなかった。原因として、レプリケーション遅延の監視閾値を超過したことが考えられる。今後の対策として、監視体制の見直しが必要である。', TIMESTAMP WITH TIME ZONE '2024-08-04T07:29:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00039', 'INC-2024-00028', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-03T07:44:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T08:44:58+09:00', '初期対応', '初期対応として、営業部の花子が問題を認識し、緊急対応を開始した。システム監視を強化し、レプリカ遅延の状況をリアルタイムで確認する体制を整えた。また、関連部署への情報共有を行い、影響を受けた特定のリージョンのユーザーへの連絡を開始した。顧客への影響を最小限に抑えるための措置を講じながら、原因の特定を急ぐ。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00040', 'INC-2024-00028', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-03T09:14:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T10:14:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00035', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-07-04T16:29:17+09:00', TIMESTAMP WITH TIME ZONE '2024-07-04T16:59:17+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2024年7月4日16時29分17秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店A及び架空食品店Bに影響を及ぼすヘルスチェック過多によるAPサーバー負荷増が発生しました。本事象はインフラメンテナンス明けに突発的に発生し、全テナントに波及する形で影響が拡大した模様です。17時には運用部の運用 一郎が検知を行い、問題の解決に向けた対応が必要となっています。エラーコードはMON-06-00035で、LBヘルスチェック間隔の過短設定が原因と推定されています。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00035', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00035', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00035', 'INC-2024-00035', '運用 一郎の調査により、ヘルスチェック過多がAPサーバーに負荷を与えていることが確認されました。LBヘルスチェック間隔が過短に設定されていることが主な原因と考えられ、調整が必要です。この問題は発生契機であるインフラメンテナンス明けに関連している可能性が高く、影響範囲は全テナントに及んでいます。今後の対策として、LB設定を見直すことが急務です。', '運用 一郎の調査により、ヘルスチェック過多がAPサーバーに負荷を与えていることが確認されました。LBヘルスチェック間隔が過短に設定されていることが主な原因と考えられ、調整が必要です。この問題は発生契機であるインフラメンテナンス明けに関連している可能性が高く、影響範囲は全テナントに及んでいます。今後の対策として、LB設定を見直すことが急務です。', TIMESTAMP WITH TIME ZONE '2024-07-05T16:59:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00050', 'INC-2024-00035', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-07-04T17:14:17+09:00', TIMESTAMP WITH TIME ZONE '2024-07-04T18:14:17+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎が架空食品店A及び架空食品店Bに影響を及ぼすヘルスチェック過負荷を発見し、直ちに対応を開始しました。LBのヘルスチェック設定を確認し、過負荷の軽減に向けた調整案を検討しています。全テナントへの影響を最小限に抑えるため、迅速な対応を心掛けます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00038', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-23T07:08:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T08:08:30+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月23日07時08分30秒に発生した顧客側ネットワーク障害について報告します。SD-WANが劣化回線を選択したことで遅延が増大し、影響は同一顧客の全店舗に及びました。発生は大規模セール開始直前であり、SD-WANポリシーの閾値設定に誤りがあったと推定されます。その結果、顧客拠点NW（Secondary）および拠点VPNゲートウェイに影響を及ぼし、遅延の増加が見られました。エラーコードはNW-10-00038です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00038', 'INC-2024-00038', '本インシデントの調査を行った結果、大規模セール開始直前にSD-WANが劣化回線を選択したことが遅延の原因であることが確認されました。この現象はSD-WANポリシーの閾値設定に誤りがあったために発生しました。今後は、ポリシー設定の見直しと定期的な監視を強化し、同様の問題が再発しないよう対策を講じる必要があります。', '本インシデントの調査を行った結果、大規模セール開始直前にSD-WANが劣化回線を選択したことが遅延の原因であることが確認されました。この現象はSD-WANポリシーの閾値設定に誤りがあったために発生しました。今後は、ポリシー設定の見直しと定期的な監視を強化し、同様の問題が再発しないよう対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-24T08:08:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00054', 'INC-2024-00038', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-23T08:23:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T09:23:30+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '初期対応として、2024年8月23日07時56分30秒に障害を検知しました。検知後、関係者に連絡を取り、SD-WANポリシーの設定を確認しました。設定に誤りがあることが判明し、直ちに修正作業に着手しました。修正後、SD-WANの経路選択を正常に戻すことで、遅延の改善が見られました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00055', 'INC-2024-00038', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-23T09:53:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T10:53:30+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00046', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-12T14:14:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T14:44:34+09:00', '【障害報告】【在庫マスター設定障害】ロット管理初回入庫不可', '2024年8月12日14時14分34秒に、株式会社ストッククラウドのMercuryにて、架空食品店Aに関するマスター設定ミスによる在庫登録失敗が発生しました。この障害は、初回入庫処理でロット番号採番に失敗するという症状を引き起こしました。原因としては、ロット管理フラグの誤った有効化が推定されており、影響範囲は単一店舗に限られています。発生契機は顧客オンボーディング当日であり、エラーコードはMST-08-00046です。影響を受けるコンポーネントはMercury AWS AP（ゾーンB）のロット管理サービスです。この障害は、顧客にとって重大な影響を及ぼす可能性があるため、迅速な対応が求められます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00046', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00046', 'INC-2024-00046', '調査の結果、顧客オンボーディング当日に発生した初回入庫処理において、ロット番号の採番に失敗したことが確認されました。原因として、ロット管理フラグが誤って有効化されていたことが疑われます。この設定ミスが原因で、在庫マスター設定が正しく機能せず、入庫処理に影響を及ぼしました。現在、必要な修正作業を進めています。', '調査の結果、顧客オンボーディング当日に発生した初回入庫処理において、ロット番号の採番に失敗したことが確認されました。原因として、ロット管理フラグが誤って有効化されていたことが疑われます。この設定ミスが原因で、在庫マスター設定が正しく機能せず、入庫処理に影響を及ぼしました。現在、必要な修正作業を進めています。', TIMESTAMP WITH TIME ZONE '2024-08-13T14:44:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00064', 'INC-2024-00046', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-12T14:59:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T15:59:34+09:00', '【初期対応】【在庫マスター設定障害】ロット管理初回入庫不可', '本件について、運用部の運用 一郎が担当となり、初期対応を開始しました。顧客の架空食品店Aに対しては、障害の経緯と現在の状況を説明し、影響を受ける入庫処理の代替手段を提案しました。また、ロット管理フラグの設定を確認し、不具合の修正作業を優先的に進める方針を打ち出しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00065', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-04T11:35:05+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T12:05:05+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2024年8月4日11時35分に、株式会社ストッククラウドのサービスVenusにおいて、在庫登録に関するマスター設定ミスが発生しました。症状としては、マスター更新後にも関わらず、旧設定での在庫登録が拒否される状態が確認されました。これは定例リリース直後に発生したもので、全テナントに影響を及ぼしました。推定される原因は、キャッシュレイヤの無効化漏れによるものであり、Mercury AWS APのキャッシュレイヤに問題があったと考えられます。この障害により、顧客は在庫登録が行えない状況となりました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00065', 'INC-2024-00065', '障害発生の原因を調査したところ、定例リリース後のマスター更新が正しく反映されず、旧設定のキャッシュが保持されていることが判明しました。キャッシュレイヤの無効化が適切に行われていなかったことが直接的な要因で、これにより在庫登録が拒否される不整合が生じました。我々は、この問題を解決するための手順を見直し、再発防止策を講じる必要があります。', '障害発生の原因を調査したところ、定例リリース後のマスター更新が正しく反映されず、旧設定のキャッシュが保持されていることが判明しました。キャッシュレイヤの無効化が適切に行われていなかったことが直接的な要因で、これにより在庫登録が拒否される不整合が生じました。我々は、この問題を解決するための手順を見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-05T12:05:05+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00091', 'INC-2024-00065', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-04T12:20:05+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T13:20:05+09:00', '【初動対応】【在庫マスター設定障害】キャッシュ不整合登録', '障害を検知した後、運用部の運用 一郎が迅速に対応を行いました。まず、キャッシュレイヤの状態を確認し、マスター設定が正常に更新されているかを検証しました。その後、キャッシュを手動で無効化し、再度在庫登録を試みたところ、問題が解消されることを確認しました。顧客への影響を最小限に抑えるため、迅速な対応を心掛けました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00092', 'INC-2024-00065', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-04T13:50:05+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T14:50:05+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00067', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-29T23:40:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T00:10:31+09:00', '【障害報告】【性能・負荷障害】CDNエッジミス', '2024年8月29日23時40分31分に発生した本インシデントは、サービス『Venus』において、CDNエッジで古い静的資産が配信される現象が確認されました。これは定例リリース直後に発生し、影響範囲としてサービス全体の一部機能に及びました。推定される原因はCDNキャッシュ無効化の未実施であり、運用部の運用 一郎が発見した時点で、検知までに25分という遅延がありました。この件により、ユーザーの体験に悪影響を与えたことを深く反省します。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00067', 'INC-2024-00067', '本インシデントの調査により、CDNエッジで古い静的資産が配信されるという症状が発生したことが確認されました。原因は、定例リリース直後にCDNキャッシュの無効化が行われていなかったことにあると推定されています。今後、この問題を防ぐための対策として、定例リリース前に必ずCDNキャッシュの無効化を実施することを徹底する必要があります。', '本インシデントの調査により、CDNエッジで古い静的資産が配信されるという症状が発生したことが確認されました。原因は、定例リリース直後にCDNキャッシュの無効化が行われていなかったことにあると推定されています。今後、この問題を防ぐための対策として、定例リリース前に必ずCDNキャッシュの無効化を実施することを徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-31T00:10:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00094', 'INC-2024-00067', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-30T00:25:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T01:25:31+09:00', '【初期対応】【性能・負荷障害】CDNエッジミス', '発生直後に運用部の運用 一郎が問題を認識し、速やかに対応チームに通知しました。初期対応として、CDNキャッシュの無効化を実施し、古い静的資産が配信されないように対策を取りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00095', 'INC-2024-00067', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-30T01:55:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T02:55:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00070', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-13T21:09:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T23:09:45+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2024年8月13日21時09分45秒頃、株式会社ストッククラウドの顧客店舗POSにおいて、棚卸確定ボタンがグレーアウトしたまま操作できない事象が発生しました。この障害は月末棚卸の開始時に発生し、影響範囲は単一店舗のみに限定されています。エラーコードはINV-03-00070であり、推定原因は未処理の差異調整レコード残留です。発見者は営業部の花子で、検知は22時59分45秒でした。現在原因究明に向けて調査を進めています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00070', 'INC-2024-00070', '調査チームは、棚卸確定ボタンがグレーアウトした原因として、未処理の差異調整レコードの存在を疑っています。月末棚卸の開始時にこの現象が発生したため、店舗在庫ビューの状態を確認し、差異調整に関するレコードの処理状況を重点的に調査しています。現在、問題の再現性についても確認中です。', '調査チームは、棚卸確定ボタンがグレーアウトした原因として、未処理の差異調整レコードの存在を疑っています。月末棚卸の開始時にこの現象が発生したため、店舗在庫ビューの状態を確認し、差異調整に関するレコードの処理状況を重点的に調査しています。現在、問題の再現性についても確認中です。', TIMESTAMP WITH TIME ZONE '2024-08-14T23:09:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00100', 'INC-2024-00070', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-13T23:24:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T00:24:45+09:00', '【対応ログ】【棚卸・POS突合障害】棚卸確定不可 - 初期対応', '営業部の花子が21時09分に棚卸確定ボタンのグレーアウトに気付き、即座に対応を開始しました。チームメンバーにも連絡を取り、影響を受ける店舗の特定と、差異調整レコードの状況を確認するよう指示しました。初期調査の結果、店舗における棚卸・POS突合の障害が確認され、問題解決に向けた手続きを進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00072', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-01T10:50:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T11:20:27+09:00', '【障害報告】【CLU-06】オートスケール遅延', '2024年8月1日10時50分27分に株式会社ストッククラウドのサービスVenusにおいて、利用者増による応答遅延が発生しました。具体的には、オートスケールが間に合わず応答劣化が見られ、全テナントに波及する影響がありました。発生契機は大規模セールの開始直前であり、スケールアウト閾値の設定遅延が推定される原因です。問題が検知されたのは11時25分27分で、検知までには35分の時間がかかりました。このインシデントは、Venus Azure APにおいて発生し、運用部の運用 一郎が発見しました。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00072', 'INC-2024-00072', '本インシデントの原因は、オートスケールの設定に関する遅延であると考えられます。具体的には、大規模セール開始直前にスケールアウトの閾値が適切に設定されず、その結果としてオートスケールが機能せず、応答劣化が発生しました。影響アイテムにはVenus Azure APが含まれ、全テナントに広がる性能・負荷障害が発生しました。今後の対策としては、スケールアウト閾値の設定プロセスを見直し、事前のテストを強化す', '本インシデントの原因は、オートスケールの設定に関する遅延であると考えられます。具体的には、大規模セール開始直前にスケールアウトの閾値が適切に設定されず、その結果としてオートスケールが機能せず、応答劣化が発生しました。影響アイテムにはVenus Azure APが含まれ、全テナントに広がる性能・負荷障害が発生しました。今後の対策としては、スケールアウト閾値の設定プロセスを見直し、事前のテストを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-02T11:20:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00103', 'INC-2024-00072', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-01T11:35:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T12:35:27+09:00', '初期対応', 'インシデント発生直後、運用部が迅速に状況を把握し、オートスケールの設定状況を確認しました。スケールアウト閾値の設定遅延が確認され、その後、設定の修正を行いました。全テナントへの影響を最小限に抑えるため、即時のリソース追加が実施され、応答性能の回復を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00104', 'INC-2024-00072', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-01T13:05:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T14:05:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00079', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-06T04:36:24+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T04:51:24+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2024年08月06日04時36分頃、株式会社ストッククラウドの運用者による作業ミスにより、運用コンソールにおいてCookie SameSite設定が適切に配置されず、埋込画面が認証不可となる事象が発生しました。影響範囲は単一店舗のみで、エラーコードはAUTH-06-00079となります。定例リリース直後の影響として、SameSite属性変更の影響が推定されます。この問題により、顧客は予期しない影響を受け、業務に支障をきたす結果となっています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00079', 'INC-2024-00079', 'インシデント発生から10分後の2024年08月06日04時46分に問題を検知しました。運用 一郎（運用部）が初期調査を実施した結果、同日実施された定例リリースが原因であることが確認されました。技術的には、Cookie SameSite設定が誤配置されたため、埋込画面の認証が不可能となったことが分かりました。引き続き、詳細な調査を行い、原因の特定と再発防止策を検討します。', 'インシデント発生から10分後の2024年08月06日04時46分に問題を検知しました。運用 一郎（運用部）が初期調査を実施した結果、同日実施された定例リリースが原因であることが確認されました。技術的には、Cookie SameSite設定が誤配置されたため、埋込画面の認証が不可能となったことが分かりました。引き続き、詳細な調査を行い、原因の特定と再発防止策を検討します。', TIMESTAMP WITH TIME ZONE '2024-08-07T04:51:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00115', 'INC-2024-00079', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T05:06:24+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T06:06:24+09:00', '【応答】【CLU-08】Cookie SameSite拒否 初動対応', '運用 一郎（運用部）より、インシデント発生直後に影響範囲の特定が行われました。CookieのSameSite設定に問題があるため、埋込画面における認証ができない状態が続いております。本事象に関し、利用者への情報提供を急ぎ、影響を受ける店舗への対策を講じる必要があります。技術チームに対し、緊急の修正対応を依頼します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00116', 'INC-2024-00079', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T06:36:24+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T07:36:24+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00082', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-27T13:06:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T14:06:47+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2024年8月27日13時06分47秒に、株式会社ストッククラウドの顧客拠点ネットワークにて障害が発生しました。症状として、店舗VPN経由でSaaSに到達できない状況となっております。これは顧客オンボーディング当日に発生したもので、影響範囲は単一店舗に限られています。発見者は営業部の花子であり、検知は13時43分47秒であり、その間に37分の遅延がありました。推定原因としては拠点FWのルール変更が考えられており、顧客のネットワーク環境に影響を与えています。今後の対応が必要です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00082', 'INC-2024-00082', '障害発生の原因を調査した結果、顧客拠点NW（DRサイト）および拠点VPNゲートウェイにおいて、FWのルール変更が行われたことが確認されました。この変更が原因で、店舗VPN経由でのSaaS到達が不可能となり、お客様に影響を及ぼしました。今後は、FWルールの見直しを行い、再発防止策の検討が必要です。', '障害発生の原因を調査した結果、顧客拠点NW（DRサイト）および拠点VPNゲートウェイにおいて、FWのルール変更が行われたことが確認されました。この変更が原因で、店舗VPN経由でのSaaS到達が不可能となり、お客様に影響を及ぼしました。今後は、FWルールの見直しを行い、再発防止策の検討が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-28T14:06:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00120', 'INC-2024-00082', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T14:21:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T15:21:47+09:00', '【初動対応】【顧客ネットワーク障害】店舗VPN到達不可', '初動対応として、障害発生の原因となるFWのルールについての確認を行いました。顧客拠点NWにアクセスし、設定内容を精査したところ、ルールの変更が行われていることが確認されました。これにより、店舗VPNがSaaSに到達できなくなっていることが判明しました。顧客に対しては状況の説明と、対応策を講じている旨を連絡いたしました。今後の対応については、迅速なルールの修正を計画し、障害の解消を図ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00089', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-11-22T02:23:42+09:00', TIMESTAMP WITH TIME ZONE '2024-11-22T04:23:42+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '2024年11月22日02時23分42秒に、株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aの顧客店舗POSでCDCイベント欠損が発生しました。この問題により、下流倉庫が未更新の状態となっています。発生契機はデータ移行バッチの実行中であり、影響範囲はバッチ処理に限られており、オンライン環境には影響がありません。エラーコードはSYNC-03-00089です。特に、CDCコネクタのオフセット巻戻しが推定原因として考えられており、技術的にはデータ移行バッチ実行中にCDCイベントが欠損したため、下流倉庫の更新が行われていないことが示唆されています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00089', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00089', 'INC-2024-00089', '調査の結果、CDCイベント欠損の原因としてCDCコネクタのオフセット巻戻しが疑われることが分かりました。データ移行バッチの実行中に、特定のCDCイベントの処理が抜け落ちてしまったため、下流倉庫が未更新となっており、これにより影響を受けたコンポーネントは顧客店舗POSとCDCパイプラインです。この問題の再発防止策を講じる必要があります。', '調査の結果、CDCイベント欠損の原因としてCDCコネクタのオフセット巻戻しが疑われることが分かりました。データ移行バッチの実行中に、特定のCDCイベントの処理が抜け落ちてしまったため、下流倉庫が未更新となっており、これにより影響を受けたコンポーネントは顧客店舗POSとCDCパイプラインです。この問題の再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-11-23T04:23:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00130', 'INC-2024-00089', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-11-22T04:38:42+09:00', TIMESTAMP WITH TIME ZONE '2024-11-22T05:38:42+09:00', '初期対応ログ', '2024年11月22日04時40分42秒に問題が検知され、営業部の花子が初期対応を開始しました。顧客店舗POSの状況を確認したところ、CDCイベント欠損が確認されました。迅速にエンジニアチームへエスカレーションし、原因調査と修正作業を依頼しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00131', 'INC-2024-00089', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-11-22T06:08:42+09:00', TIMESTAMP WITH TIME ZONE '2024-11-22T07:08:42+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00095', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-10T02:00:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T02:30:16+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2024年8月10日02時00分16秒に発生した障害について報告いたします。株式会社ストッククラウドのサービスVenusにおいて、マスター更新と在庫が二重反映される事象が発生しました。この障害は定例リリース直後に発生し、同一顧客の全店舗に影響を及ぼしました。エラーコードはSYNC-01-00095で、Mercury AWS AP（ゾーンB）及びイベントバスに関連する問題と考えられます。検知は同日02時34分16秒に行われ、約34分の間、影響範囲におけるデータの整合性が保たれない状態が続きました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00095', 'INC-2024-00095', '本障害の調査を進めた結果、イベント順序の逆転配信が原因である可能性が高いと考えられます。定例リリースの直後に、マスター更新が正常に行われず、在庫が二重に反映される結果となりました。この問題により、同一顧客の全店舗でデータ同期・整合性の障害が引き起こされました。今後は、イベント順序の管理を徹底し、同様の問題が発生しないようにする必要があります。', '本障害の調査を進めた結果、イベント順序の逆転配信が原因である可能性が高いと考えられます。定例リリースの直後に、マスター更新が正常に行われず、在庫が二重に反映される結果となりました。この問題により、同一顧客の全店舗でデータ同期・整合性の障害が引き起こされました。今後は、イベント順序の管理を徹底し、同様の問題が発生しないようにする必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-11T02:30:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00140', 'INC-2024-00095', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T02:45:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T03:45:16+09:00', '【初動対応】【データ同期・整合性障害】マスター在庫二重反映', '2024年8月10日02時34分16秒に検知した障害について、初動対応を実施しました。運用部の運用 一郎が状況を確認し、障害の原因を特定するために調査を開始しました。障害の影響を受けた店舗に対して、在庫データの整合性を早急に確認し、必要に応じて手動で修正を行う指示を出しました。また、定例リリースの内容を精査し、今後の対策を検討するための会議を開催することを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00141', 'INC-2024-00095', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T04:15:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T05:15:16+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00109', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-02T04:05:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T04:35:45+09:00', '【障害報告】【性能・負荷障害】キャッシュヒット率低下', '2024年8月2日04:05:45に、株式会社ストッククラウドのサービスVenusにおいて、キャッシュヒット率低下が発生しDB負荷が増加しました。本事象は定例リリース直後に確認され、全テナントに波及する影響がありました。特に、Venus Azure APとキャッシュレイヤにおいて顕著な影響が見られました。エラーコードはPRF-09-00109であり、推定原因としてインデックス未適用の新機能が疑われています。検知は04:35:45に行われ、発見者は運用部の運用 一郎です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00109', 'INC-2024-00109', '調査の結果、定例リリース直後にキャッシュヒット率が低下したことが確認されました。これは、未適用のインデックスによる新機能が原因でDBに負荷がかかる事象です。全テナントに影響を及ぼしており、速やかな対応が求められます。さらなる技術的分析が必要ですが、初期段階ではインデックスの改善が最優先となります。', '調査の結果、定例リリース直後にキャッシュヒット率が低下したことが確認されました。これは、未適用のインデックスによる新機能が原因でDBに負荷がかかる事象です。全テナントに影響を及ぼしており、速やかな対応が求められます。さらなる技術的分析が必要ですが、初期段階ではインデックスの改善が最優先となります。', TIMESTAMP WITH TIME ZONE '2024-08-03T04:35:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00158', 'INC-2024-00109', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-02T04:50:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T05:50:45+09:00', '【初期対応】【性能・負荷障害】キャッシュヒット率低下', '初期対応として、影響を受けたVenus Azure APのキャッシュ設定を見直し、キャッシュヒット率の向上に努めます。また、インデックス未適用の新機能に関しては、早急に適用するための計画を立てます。全テナントへの影響を抑えるため、必要な修正を迅速に行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00159', 'INC-2024-00109', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-02T06:20:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T07:20:45+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00110', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-06T03:51:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T04:21:50+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2024年8月6日03時51分50秒に、株式会社ストッククラウドのVenusサービスにおいて、SKU登録APIがHTTP 500を返し、在庫反映に失敗する事象が発生しました。この障害は、Mercury AWS APに関連する在庫登録APIにて確認されました。現時点で顧客はおらず、影響範囲は単一店舗の登録機能のみに及びます。発生契機は定例リリース直後であり、推定原因は単位換算係数の設定漏れと考えられています。この事象の影響により、商品の在庫反映が正常に行われず、業務運営に支障をきたす可能性があります。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00110', 'INC-2024-00110', '障害の発生後、原因調査を実施しました。定例リリース直後にSKU登録APIがHTTP 500を返すことが確認され、特に単位換算係数の設定に問題があると疑われました。今回の事象は、在庫登録APIにおいて発生しており、影響を受ける店舗への影響を最小限に抑えるため、早急な対応が必要です。', '障害の発生後、原因調査を実施しました。定例リリース直後にSKU登録APIがHTTP 500を返すことが確認され、特に単位換算係数の設定に問題があると疑われました。今回の事象は、在庫登録APIにおいて発生しており、影響を受ける店舗への影響を最小限に抑えるため、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-07T04:21:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00160', 'INC-2024-00110', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T04:36:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T05:36:50+09:00', '【初期対応】【在庫マスター設定障害】SKU登録HTTP500', '初期対応として、運用部の運用 一郎が障害を検知後、ただちに技術チームにエスカレーションを行いました。また、影響範囲の確認を行い、関連する設定の再確認を実施しました。今後、単位換算係数の設定状況を詳細に調査し、必要な修正を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00111', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-03-04T21:40:41+09:00', TIMESTAMP WITH TIME ZONE '2024-03-04T23:40:41+09:00', '【障害報告】【棚卸・POS突合障害】移動平均単価異常', '2024年3月4日21時40分41秒、株式会社ストッククラウドのサービスMercuryにおいて、棚卸突合失敗に関するインシデントが発生しました。発生場所は顧客店舗POSであり、営業の花子が発見者です。発見後161分後の2024年3月5日00時21分41秒に検知されました。この事象は、棚卸後の評価単価が想定外の値になるという症状を呈しています。定例リリース直後の影響で、サービス全体の一部機能に影響を及ぼす可能性があります。エラーコードはINV-07-00111であり、推定原因は移動平均計算式の適用期間誤りと考えられています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00111', 'INC-2024-00111', 'インシデント発生後の調査において、定例リリース直後に発生した棚卸後の評価単価が想定外の値になる原因を探りました。調査の結果、移動平均計算式の適用期間に誤りがあったことが確認されました。この誤りが原因で、顧客店舗POSの在庫評価エンジンに影響が出てしまったことが判明しています。今後、このような事象を防ぐために、リリース前のテストを強化する必要があります。', 'インシデント発生後の調査において、定例リリース直後に発生した棚卸後の評価単価が想定外の値になる原因を探りました。調査の結果、移動平均計算式の適用期間に誤りがあったことが確認されました。この誤りが原因で、顧客店舗POSの在庫評価エンジンに影響が出てしまったことが判明しています。今後、このような事象を防ぐために、リリース前のテストを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-03-05T23:40:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00161', 'INC-2024-00111', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-03-04T23:55:41+09:00', TIMESTAMP WITH TIME ZONE '2024-03-05T00:55:41+09:00', '【初期対応】【棚卸・POS突合障害】移動平均単価異常', 'インシデント発生直後、営業の花子が顧客店舗POSの評価単価の異常を確認し、迅速に調査を開始しました。システムログを確認した結果、定例リリース前の環境でのテストが不十分であったことが判明しました。移動平均計算式の適用期間に誤りがあることが疑われ、この問題に対処するための初期対応が求められました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00162', 'INC-2024-00111', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-03-05T01:25:41+09:00', TIMESTAMP WITH TIME ZONE '2024-03-05T02:25:41+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00112', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-12-09T14:03:10+09:00', TIMESTAMP WITH TIME ZONE '2024-12-09T14:33:10+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2024年12月9日14時03分10秒、株式会社ストッククラウドのMercuryにおいて、架空食品店B、架空食品店Aの顧客に対し、在庫登録失敗が発生しました。症状としては、読取レプリカ遅延により在庫照会が古い値となり、特定リージョンのユーザーに影響が及びました。この事象は、レプリケーション遅延の監視閾値を超過したことが推定原因と考えられます。大規模セール開始直前のタイミングで、この問題が発生したため、顧客へは影響を最小限に抑える必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00112', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00112', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00112', 'INC-2024-00112', '運用部の運用一郎が、発見した時刻は2024年12月9日14時39分10秒です。このタイミングで、MercuryのAWS APにおける読取専用レプリカでの遅延が発生していることが確認されました。これにより、在庫照会で提示される値が古いものとなっており、ユーザーに正確な情報が届いていないことが判明しました。', '運用部の運用一郎が、発見した時刻は2024年12月9日14時39分10秒です。このタイミングで、MercuryのAWS APにおける読取専用レプリカでの遅延が発生していることが確認されました。これにより、在庫照会で提示される値が古いものとなっており、ユーザーに正確な情報が届いていないことが判明しました。', TIMESTAMP WITH TIME ZONE '2024-12-10T14:33:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00163', 'INC-2024-00112', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-12-09T14:48:10+09:00', TIMESTAMP WITH TIME ZONE '2024-12-09T15:48:10+09:00', '【初動対応】【データ同期・整合性障害】読取レプリカ遅延に対する初動', '運用部の運用一郎が、読取レプリカ遅延を確認後、即座に技術チームにエスカレーションを行いました。技術チームは、レプリケーション遅延の監視閾値を見直し、改善策を検討することになりました。顧客に対しては、状況報告を行い、問題解決の進捗を随時伝える旨の案内をしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00113', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-04T01:39:39+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T02:09:39+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2024年8月4日01時39分39秒、株式会社ストッククラウドのサービスVenusにおいて、ログに相関IDが欠落し横断検索が不可となる事象が発生いたしました。影響を受けたのは運用部門のみであり、発生契機は定例リリース直後でありました。エラーコードはMON-09-00113です。運用 一郎がこの障害を発見し、検知は同日01時59分39秒に行われました。技術的な詳細については、定例リリース直後にログのフォーマット変更が行われたことから、そのロールアウト漏れが原因であると考えられます。現在、監視・可用性障害の状況を確認中であり、速やかな対応が求められます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00113', 'INC-2024-00113', '本事象に関して、ログの相関IDが欠落していることが確認されました。これは、定例リリース直後に実施されたログフォーマット変更に伴い、適切なロールアウトが行われていなかったことが推定されています。これにより、横断検索ができず、運用部門への影響が限定的ではありますが、迅速な改善が必要です。今後は、リリース前の確認プロセスを強化することで、同様の問題の再発を防止する方針です。', '本事象に関して、ログの相関IDが欠落していることが確認されました。これは、定例リリース直後に実施されたログフォーマット変更に伴い、適切なロールアウトが行われていなかったことが推定されています。これにより、横断検索ができず、運用部門への影響が限定的ではありますが、迅速な改善が必要です。今後は、リリース前の確認プロセスを強化することで、同様の問題の再発を防止する方針です。', TIMESTAMP WITH TIME ZONE '2024-08-05T02:09:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00164', 'INC-2024-00113', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-04T02:24:39+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T03:24:39+09:00', '【初期対応】【監視・可用性障害】ログ相関ID欠落への対応', '運用部門では、ログの相関ID欠落に関し、直ちに問題の調査を開始いたしました。現在、ログフォーマット変更の内容を確認し、ロールアウト漏れが発生した箇所を特定する作業を進めています。また、必要に応じてリリース関係者へのヒアリングを行い、今後の改善策を講じる予定です。担当者が確認を行い、問題解決に向けて速やかに対応いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00118', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-07T10:58:39+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T11:13:39+09:00', '【障害報告】【CLU-08】SSOリダイレクトループ', '株式会社ストッククラウドのサービスVenusにおいて、2024年8月7日10時58分39秒に運用者の作業ミスによるアクセス障害が発生いたしました。本事象は、運用コンソールにおいてSSOログインを行った際にリダイレクトループが発生し、全テナントに波及する影響がありました。検知は同日11時10分39秒に行われ、発見者は運用部の運用 一郎です。定例リリース直後の発生契機を考慮すると、推定原因はSAMLメタデータのURL不一致と推測されます。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00118', 'INC-2024-00118', '本インシデントに関する調査を行った結果、SAMLメタデータのURL不一致がリダイレクトループを引き起こす主な要因であることが確認されました。運用コンソールと認証サービス間での通信において、メタデータの誤設定が原因と考えられ、早急な修正が必要です。影響範囲は全テナントに及んでおり、速やかなサービス復旧が求められます。', '本インシデントに関する調査を行った結果、SAMLメタデータのURL不一致がリダイレクトループを引き起こす主な要因であることが確認されました。運用コンソールと認証サービス間での通信において、メタデータの誤設定が原因と考えられ、早急な修正が必要です。影響範囲は全テナントに及んでおり、速やかなサービス復旧が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-08T11:13:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00171', 'INC-2024-00118', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-07T11:28:39+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T12:28:39+09:00', '【初期対応】【CLU-08】SSOリダイレクトループへの初期対応', 'インシデント発生後、運用チームは直ちに調査を開始し、SSOリダイレクトループの影響を受けている全テナントの状況を確認しました。該当する設定に関するログを収集し、問題の根本原因となるSAMLメタデータのURL不一致を特定しました。現在、修正作業が進められており、影響を受けたお客様には随時報告を行っております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00122', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-09-16T23:04:15+09:00', TIMESTAMP WITH TIME ZONE '2024-09-16T23:34:15+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2024年9月16日23時04分に、株式会社ストッククラウドのサービスMercuryにおいて、OAuthトークン失効によるPOS連携の中断が発生しました。この障害は、架空食品店Aに限定された影響を及ぼしました。障害の発見は同日23時52分で、検知までに48分を要しました。発生契機は年末年始の稼働切替時であり、リフレッシュトークン保存先の障害が推定されます。この問題により、API連携・EDIの機能が失われ、業務に支障を来す恐れがあります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00122', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00122', 'INC-2024-00122', '本障害に関する調査を行った結果、年末年始の稼働切替時にOAuthトークンが失効したことが確認されました。原因としてリフレッシュトークン保存先の障害が疑われ、早急な対応が必要です。調査チームは、影響を受けたPOS連携ハブおよびMercury AWS APの状況を詳細に分析しています。', '本障害に関する調査を行った結果、年末年始の稼働切替時にOAuthトークンが失効したことが確認されました。原因としてリフレッシュトークン保存先の障害が疑われ、早急な対応が必要です。調査チームは、影響を受けたPOS連携ハブおよびMercury AWS APの状況を詳細に分析しています。', TIMESTAMP WITH TIME ZONE '2024-09-17T23:34:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00178', 'INC-2024-00122', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-16T23:49:15+09:00', TIMESTAMP WITH TIME ZONE '2024-09-17T00:49:15+09:00', '【初動対応】【CLU-07】OAuthトークン失効', '障害発生後、運用部の運用 一郎が初動対応を行いました。まず、OAuthトークンのステータスを確認し、POS連携の中断が確認された後、リフレッシュトークン保存先の調査を開始しました。必要なログを収集し、エラーコードEDI-05-00122に基づく分析を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00128', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-05T12:23:11+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T14:23:11+09:00', '【障害報告】【棚卸・POS突合障害】棚卸ラベル印刷失敗', '2024年8月5日12:23:11に発生した棚卸突合失敗の事象について報告します。顧客店舗POSにて、棚卸用ラベル印刷APIが404を返す問題が発生しました。今回の障害は、月末棚卸の開始時に発生し、影響範囲は単一店舗のみとなっております。エラーコードはINV-09-00128です。発見者は営業部の花子であり、検知は2024年8月5日13:57:11に行われ、検知までに94分を要しました。障害の原因として、店舗プリンタ設定のテンプレートID誤りが推定されています。影響コンポーネントは顧客店舗POS（DRサイト）およびラベル印刷サービスです。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00128', 'INC-2024-00128', '本障害の調査を行った結果、棚卸用ラベル印刷APIが404を返す原因は、店舗プリンタ設定のテンプレートIDの誤りであることが確認されました。この設定ミスは、月末棚卸の開始時に多くの店舗で同様のエラーが報告される可能性があります。今後の対策として、プリンタ設定の見直しや確認プロセスの強化が必要です。', '本障害の調査を行った結果、棚卸用ラベル印刷APIが404を返す原因は、店舗プリンタ設定のテンプレートIDの誤りであることが確認されました。この設定ミスは、月末棚卸の開始時に多くの店舗で同様のエラーが報告される可能性があります。今後の対策として、プリンタ設定の見直しや確認プロセスの強化が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-06T14:23:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00185', 'INC-2024-00128', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-05T14:38:11+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T15:38:11+09:00', '初期対応', '初期対応として、障害発生後すぐに影響を受けた店舗のプリンタ設定を確認しました。リーダブルなエラーが確認されたため、営業部の花子が該当店舗の担当者と連携し、設定の修正を行いました。これにより、ラベル印刷が正常に機能することが確認されました。今後は、同様の問題を防ぐために、定期的な設定確認を実施することを提案します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00186', 'INC-2024-00128', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-05T16:08:11+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T17:08:11+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00134', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-02-25T22:43:06+09:00', TIMESTAMP WITH TIME ZONE '2024-02-25T22:58:06+09:00', '【障害報告】【CLU-10】トレースサンプリング過少', '2024年2月25日22時43分に、株式会社ストッククラウドのサービスMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。症状として、分散トレースのサンプリング率が過少であるため、原因特定が困難な状況となっております。定例リリース直後のタイミングで発生しており、影響範囲は運用部門のみに限られています。エラーコードはMON-05-00134で、運用コンソールに関連するトレーシング基盤に影響を及ぼしています。運用 一郎が障害を発見し、検知まで16分を要しました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00134', 'INC-2024-00134', '本障害に関する調査を進めた結果、分散トレースのサンプリング率が過少であることが確認されました。この状況が原因特定を難しくしており、推定原因はサンプリング率の本番設定誤りであると考えられます。運用コンソールにおけるこの問題が、を引き起こしている可能性があります。早急な対応が求められます。', '本障害に関する調査を進めた結果、分散トレースのサンプリング率が過少であることが確認されました。この状況が原因特定を難しくしており、推定原因はサンプリング率の本番設定誤りであると考えられます。運用コンソールにおけるこの問題が、を引き起こしている可能性があります。早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2024-02-26T22:58:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00195', 'INC-2024-00134', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-25T23:13:06+09:00', TIMESTAMP WITH TIME ZONE '2024-02-26T00:13:06+09:00', '【初期対応】【CLU-10】トレースサンプリング過少', '初期対応として、運用部門において分散トレースのサンプリング設定の確認を行い、正しい設定値への修正作業を実施しました。定例リリース直後の誤設定が原因であるため、今後のリリースにおいて同様のミスを防ぐための手順見直しを検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00137', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-09-16T03:43:01+09:00', TIMESTAMP WITH TIME ZONE '2024-09-16T04:43:01+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年9月16日03時43分に、株式会社ストッククラウドのサービスVenusにおいて顧客拠点NWで顧客の架空服飾店Aに対する顧客側ネットワーク障害が発生しました。発生時にはDNS解決が成功しましたが、続くTLS握手において接続が切断される症状が確認されました。この問題は、同一顧客の全店舗に影響を及ぼしました。特に、インフラメンテナンス明けに発生したことから、プロキシ証明書の期限切れが原因として推定されています。この障害により、顧客のネットワーク接続に支障をきたしたことは明らかであり、早急な対応が求められました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00137', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00137', 'INC-2024-00137', '本インシデントに関する調査を実施した結果、DNS解決後にTLS握手での接続切断が発生していることが確認されました。原因としてプロキシ証明書の期限切れが考えられ、これにより正常な接続が阻害されている可能性があります。影響範囲が同一顧客の全店舗に及ぶため、早期の修正が必要です。また、インフラメンテナンス明けのタイミングでの発生が示唆されており、今後のメンテナンス作業における注意が必要です。', '本インシデントに関する調査を実施した結果、DNS解決後にTLS握手での接続切断が発生していることが確認されました。原因としてプロキシ証明書の期限切れが考えられ、これにより正常な接続が阻害されている可能性があります。影響範囲が同一顧客の全店舗に及ぶため、早期の修正が必要です。また、インフラメンテナンス明けのタイミングでの発生が示唆されており、今後のメンテナンス作業における注意が必要です。', TIMESTAMP WITH TIME ZONE '2024-09-17T04:43:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00200', 'INC-2024-00137', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-09-16T04:58:01+09:00', TIMESTAMP WITH TIME ZONE '2024-09-16T05:58:01+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断への初期対応', 'インシデント発生直後、営業部の花子が対応にあたり、顧客の架空服飾店Aへ状況を説明し、暫定的な回避策として手動での接続試行を提案しました。さらに、ネットワークの詳細な状態を確認するために、技術チームにエスカレーションを行い、プロキシ証明書の確認作業を開始しました。顧客には、進捗状況を随時報告することを約束し、信頼回復に努めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00144', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-07-28T11:16:37+09:00', TIMESTAMP WITH TIME ZONE '2024-07-28T11:46:37+09:00', '【障害報告】【CLU-10】合成監視失敗', '■ 発生日時: 2024-07-28T11:16:37+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00144', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00144', 'INC-2024-00144', '合成監視が特定ステップで失敗したことが確認されました。テストデータが期限切れであることが原因として考えられています。利用者数の増加に伴い応答遅延も発生しており、監視・可用性障害が顕在化しました。今後、テストデータの更新と監視システムの強化を検討する必要があります。', '合成監視が特定ステップで失敗したことが確認されました。テストデータが期限切れであることが原因として考えられています。利用者数の増加に伴い応答遅延も発生しており、監視・可用性障害が顕在化しました。今後、テストデータの更新と監視システムの強化を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-07-29T11:46:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00210', 'INC-2024-00144', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-07-28T12:01:37+09:00', TIMESTAMP WITH TIME ZONE '2024-07-28T13:01:37+09:00', '初期対応', '運用部において合成監視の失敗が確認され、直ちにテストデータの更新作業を実施しました。また、運用 一郎が影響を受けた顧客への連絡を行い、状況を説明したうえで問題解決に努めています。引き続き、影響範囲の把握と監視状況の確認を行っていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00146', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-02-02T02:31:21+09:00', TIMESTAMP WITH TIME ZONE '2024-02-02T03:31:21+09:00', '【障害報告】【顧客ネットワーク障害】回線断後セッション未復旧', '2024年2月2日02時31分に、株式会社ストッククラウドの顧客である架空食品店Aにおいて、拠点回線断復旧後もセッションが復旧しないというネットワーク障害が発生いたしました。検知は同日03時41分に行われ、発見者は営業部の花子でございます。この影響により、単一店舗にて顧客ネットワークが利用できない状態が続いております。原因としてVPNクライアントのバージョン不整合が推測され、年末年始の稼働切替時に発生したことが影響していると考えられます。現在、迅速な対応を進めており、お客様にご迷惑をおかけしないよう努めてまいります。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00146', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00146', 'INC-2024-00146', '本件について調査を進めた結果、年末年始の稼働切替時に拠点回線が断絶し、復旧後もセッションが復旧しない状況が確認されました。顧客拠点NWおよび拠点VPNゲートウェイに関連するコンポーネントが影響を受けており、VPNクライアントのバージョン不整合が主要な原因として挙げられます。この問題は、営業部の花子が発見し、約70分後に検知されました。今後は、VPNクライアントのバージョンを統一することを提案いたし', '本件について調査を進めた結果、年末年始の稼働切替時に拠点回線が断絶し、復旧後もセッションが復旧しない状況が確認されました。顧客拠点NWおよび拠点VPNゲートウェイに関連するコンポーネントが影響を受けており、VPNクライアントのバージョン不整合が主要な原因として挙げられます。この問題は、営業部の花子が発見し、約70分後に検知されました。今後は、VPNクライアントのバージョンを統一することを提案いたします。', TIMESTAMP WITH TIME ZONE '2024-02-03T03:31:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00212', 'INC-2024-00146', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-02-02T03:46:21+09:00', TIMESTAMP WITH TIME ZONE '2024-02-02T04:46:21+09:00', '【対応ログ】【顧客ネットワーク障害】初期対応', '2024年2月2日03時45分、初期対応を開始しました。VPNクライアントのバージョン確認を行い、最新のバージョンを導入するよう指示いたしました。また、お客様には障害の進捗状況を定期的に報告し、信頼関係の維持に努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00213', 'INC-2024-00146', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-02-02T05:16:21+09:00', TIMESTAMP WITH TIME ZONE '2024-02-02T06:16:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00150', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-16T06:46:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T07:16:01+09:00', '【障害報告】【認証・セッション障害】セッション突然切断', '2024年08月16日06時46分頃、株式会社ストッククラウドのサービスVenusにおいて、操作中にセッションが突然切断される事象が発生しました。これにより、特定リージョンのユーザーに影響が及びました。07時14分にこの事象が検知され、検知まで28分の遅延が確認されました。切断の原因として、セッションTTL設定の短縮反映が推定されております。影響を受けたコンポーネントはVenus Azure AP（ゾーンB）およびセッションストアです。この問題はインフラメンテナンス明けに発生しており、迅速な対応が求められます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00150', 'INC-2024-00150', '本事象に関しては、インフラメンテナンス後に操作中のセッションが突然切断されるという症状が確認されました。現時点では、セッションTTL設定の短縮反映が原因である可能性が高いと考えられています。特定リージョンのユーザーに対して影響が出ており、迅速な改善策が必要です。技術的な詳細をもとに、正確な原因解明と再発防止策の策定を行います。', '本事象に関しては、インフラメンテナンス後に操作中のセッションが突然切断されるという症状が確認されました。現時点では、セッションTTL設定の短縮反映が原因である可能性が高いと考えられています。特定リージョンのユーザーに対して影響が出ており、迅速な改善策が必要です。技術的な詳細をもとに、正確な原因解明と再発防止策の策定を行います。', TIMESTAMP WITH TIME ZONE '2024-08-17T07:16:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00217', 'INC-2024-00150', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-16T07:31:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T08:31:01+09:00', '対応ログ - 初期対応', '2024年08月16日07時15分、運用部の運用 一郎が状況を確認し、ユーザーへの周知および影響範囲の特定を開始しました。セッションTTL設定の確認を行い、必要に応じて設定の修正を検討しました。また、システムの安定性を監視するための体制を整備し、継続的なログ収集を行うこととしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00218', 'INC-2024-00150', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-16T09:01:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T10:01:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00151', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-20T01:42:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T02:42:06+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '発生日時: 2024-08-20T01:42:06+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00151', 'INC-2024-00151', '調査を行った結果、店舗のDNSキャッシュが旧IPを返し続ける原因として、DNS TTL設定とキャッシュ方針の不一致が確認されました。この問題は、定例リリース後に発生し、影響を受けたのは単一店舗のみでした。DNS設定を再確認し、迅速に対応を進めています。', '調査を行った結果、店舗のDNSキャッシュが旧IPを返し続ける原因として、DNS TTL設定とキャッシュ方針の不一致が確認されました。この問題は、定例リリース後に発生し、影響を受けたのは単一店舗のみでした。DNS設定を再確認し、迅速に対応を進めています。', TIMESTAMP WITH TIME ZONE '2024-08-21T02:42:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00219', 'INC-2024-00151', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-20T02:57:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T03:57:06+09:00', '【初期対応】【顧客ネットワーク障害】DNSキャッシュ汚染への初期対応', '初期調査を実施し、店舗のDNSリゾルバ設定を見直しました。DNS TTLの設定に問題があることがわかり、キャッシュのクリアを行いました。その後、DNSが正しいIPアドレスを返すことを確認しました。さらに、今後の再発防止に向けて、DNS設定の見直しを行う方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00152', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-13T00:19:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T01:19:26+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月13日00時19分26秒、株式会社ストッククラウドのサービスVenusにおいて、顧客のネットワーク障害が発生しました。具体的には、SD-WANが劣化回線を選択したため、接続遅延が増大しました。この障害は、大規模セール開始直前に発生し、同一顧客の全店舗に影響を及ぼしました。エラーコードはNW-10-00152です。問題の発見は、2024年8月13日01時16分26秒に行われました。この遅延は、SD-WANポリシーの閾値設定誤りが原因と考えられています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00152', 'INC-2024-00152', '本インシデントに関する調査結果を以下にまとめます。SD-WANが劣化回線を選択した原因として、ポリシーの閾値設定が適切でなかったことが確認されました。これにより遅延が発生し、顧客のネットワークに深刻な影響を及ぼしました。今後はポリシー設定の見直しとテストを強化し、再発防止策を講じる必要があります。', '本インシデントに関する調査結果を以下にまとめます。SD-WANが劣化回線を選択した原因として、ポリシーの閾値設定が適切でなかったことが確認されました。これにより遅延が発生し、顧客のネットワークに深刻な影響を及ぼしました。今後はポリシー設定の見直しとテストを強化し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-14T01:19:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00220', 'INC-2024-00152', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-13T01:34:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T02:34:26+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月13日01時16分に、該当するネットワーク障害について初期対応を実施しました。技術チームが迅速に障害内容を特定し、SD-WANの設定を確認したところ、ポリシーの閾値設定に誤りがあることが判明しました。この情報をもとに、設定の修正を行い、遅延の改善に向けて対応を進めました。さらなる調査を行い、問題の根本原因を明確にして再発防止策を講じる予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00221', 'INC-2024-00152', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-13T03:04:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T04:04:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00168', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-28T04:26:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T05:11:38+09:00', '【障害報告】【監視・可用性障害】合成監視失敗', '・発生日時: 2024-08-28T04:26:38+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00168', 'INC-2024-00168', '合成監視が特定のステップで失敗した原因を調査中。定例リリース後の合成監視において、テストデータの期限切れが疑われる。影響範囲はサービス全体の一部機能であり、早急な対策が必要。テストデータの更新状態を確認し、必要な修正を行う。', '合成監視が特定のステップで失敗した原因を調査中。定例リリース後の合成監視において、テストデータの期限切れが疑われる。影響範囲はサービス全体の一部機能であり、早急な対策が必要。テストデータの更新状態を確認し、必要な修正を行う。', TIMESTAMP WITH TIME ZONE '2024-08-29T05:11:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00245', 'INC-2024-00168', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T05:26:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T06:26:38+09:00', '【対応ログ】【監視・可用性障害】合成監視失敗', '初期対応として、テストデータの確認を実施。期限切れのデータが確認されたため、迅速に更新作業を行った。合成監視のステップ失敗により、サービス全体の一部機能に影響が出る可能性があるため、今後の監視強化を提案。再度合成監視のテストを行い、問題解決を目指す。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00246', 'INC-2024-00168', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T06:56:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T07:56:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00169', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-27T20:11:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T20:41:32+09:00', '【障害報告】【CLU-08】ブルートフォース誤検知', '2024年8月27日20時11分32秒、株式会社ストッククラウドのVenusサービスにおいて、ブルートフォース検知による正常IPの遮断が発生しました。この事象は、大規模セール開始直前に発生し、影響範囲は単一店舗のみとなります。エラーコードはAUTH-08-00169であり、Venus Azure AP（DRサイト）およびWAFが影響を受けました。検知は17分後の20時28分32秒に行われました。推定原因としては、検知閾値の過敏設定が疑われます。今後、ブルートフォース検知の設定見直しを行う必要があります。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00169', 'INC-2024-00169', '調査の結果、2024年8月27日に発生したブルートフォース誤検知は、正常なIPアドレスがWAFによって遮断された事象でした。影響を受けたのは単一店舗で、大規模セール開始直前に発生したため、システムに対する負荷が高まり、正常なリクエストまでブロックされた可能性があります。今後、検知閾値の設定を見直す必要があります。', '調査の結果、2024年8月27日に発生したブルートフォース誤検知は、正常なIPアドレスがWAFによって遮断された事象でした。影響を受けたのは単一店舗で、大規模セール開始直前に発生したため、システムに対する負荷が高まり、正常なリクエストまでブロックされた可能性があります。今後、検知閾値の設定を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-28T20:41:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00247', 'INC-2024-00169', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-27T20:56:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T21:56:32+09:00', '【初期対応】【CLU-08】ブルートフォース誤検知', 'インシデントに対して初期対応を実施しました。正常IPの遮断を解除し、影響を受けた顧客に連絡を行いました。また、WAFの設定を一時的に緩和し、正常なトラフィックが通過できるよう対応しています。今後も状況を監視し、必要に応じて追加の対応を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00248', 'INC-2024-00169', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-27T22:26:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T23:26:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00170', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-10-06T13:51:00+09:00', TIMESTAMP WITH TIME ZONE '2024-10-06T14:21:00+09:00', '【障害報告】【性能・負荷障害】照会API p99超過', '2024年10月6日13:51, 株式会社ストッククラウドのVenusにおいて、在庫照会APIのp99レイテンシが閾値を超過する事象が発生した。この事象は、特定リージョンのユーザーにのみ影響を及ぼしており、原因としてN+1クエリの混入が推定されている。発生契機としては、大規模セール開始直前であった。レイテンシの測定は14:17に確認され、検知までに26分を要した。影響を受けたコンポーネントはVenus Azure APのゾーンBにある読取専用レプリカである。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00170', 'INC-2024-00170', '本件の調査を行った結果、在庫照会APIのp99レイテンシが閾値を超過していることが確認された。原因として、N+1クエリの混入が疑われ、この影響により特定リージョンのユーザーにパフォーマンスの低下が認められる。大規模セール開始前のトラフィック増加が直接的な契機となっている可能性が高い。今後の対策として、クエリの最適化が必要である。', '本件の調査を行った結果、在庫照会APIのp99レイテンシが閾値を超過していることが確認された。原因として、N+1クエリの混入が疑われ、この影響により特定リージョンのユーザーにパフォーマンスの低下が認められる。大規模セール開始前のトラフィック増加が直接的な契機となっている可能性が高い。今後の対策として、クエリの最適化が必要である。', TIMESTAMP WITH TIME ZONE '2024-10-07T14:21:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00249', 'INC-2024-00170', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-10-06T14:36:00+09:00', TIMESTAMP WITH TIME ZONE '2024-10-06T15:36:00+09:00', '【初動対応】【性能・負荷障害】照会API p99超過', '2024年10月6日14:00, 運用 一郎が初動対応を行い、在庫照会APIのパフォーマンスを監視し始めた。問題の根本原因であるN+1クエリの特定を行うためのログ分析を実施。その後、トラフィックの急増に伴う負荷を軽減するため、キャッシュ機能の強化やロードバランサの設定見直しを検討することとした。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00250', 'INC-2024-00170', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-10-06T16:06:00+09:00', TIMESTAMP WITH TIME ZONE '2024-10-06T17:06:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00171', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-11-27T01:44:50+09:00', TIMESTAMP WITH TIME ZONE '2024-11-27T02:14:50+09:00', '【障害報告】【在庫マスター設定障害】ロット管理初回入庫不可', '2024年11月27日01:44:50に、株式会社ストッククラウドのMercuryサービスにて、架空食品店Aにおいてマスター設定ミスによる在庫登録失敗が発生しました。症状としては、初回入庫処理でロット番号採番に失敗する事象が確認されました。主な原因として、ロット管理フラグの誤った有効化が推定されます。影響範囲は単一店舗であり、エラーコードはMST-08-00171です。発生契機は、顧客オンボーディング当日であり、影響コンポーネントはMercury AWS APのロット管理サービスです。技術詳細としては、顧客オンボーディング当日に初回入庫処理でロット番号採番に失敗することが挙げられ、これにより在庫マスター設定に影響が出ています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00171', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00171', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00171', 'INC-2024-00171', '本インシデントにおいて、初回入庫処理でロット番号採番に失敗した原因を調査しました。ロット管理フラグが誤って有効化されていたことが判明しました。この設定ミスにより、顧客である架空食品店Aにて在庫登録が正常に行われず、業務に影響を及ぼしました。今後同様の事象を防ぐため、設定の確認プロセスの見直しを行う必要があります。', '本インシデントにおいて、初回入庫処理でロット番号採番に失敗した原因を調査しました。ロット管理フラグが誤って有効化されていたことが判明しました。この設定ミスにより、顧客である架空食品店Aにて在庫登録が正常に行われず、業務に影響を及ぼしました。今後同様の事象を防ぐため、設定の確認プロセスの見直しを行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-11-28T02:14:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00251', 'INC-2024-00171', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-27T02:29:50+09:00', TIMESTAMP WITH TIME ZONE '2024-11-27T03:29:50+09:00', '【対応ログ】【在庫マスター設定障害】ロット管理初回入庫不可', '2024年11月27日02:09:50に本インシデントが検知されました。運用部の運用 一郎が問題を確認し、迅速に調査を開始しました。障害の影響を受けた顧客に対して、事象の詳細を説明し、今後の対策についても協議しました。また、ロット管理フラグの設定を再確認し、正しい値に修正する手続きが進められています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00252', 'INC-2024-00171', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-27T03:59:50+09:00', TIMESTAMP WITH TIME ZONE '2024-11-27T04:59:50+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00174', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-11T04:10:37+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T05:10:37+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2024年8月11日04:10に、株式会社ストッククラウドの顧客拠点NWにてISP側BGP経路障害が発生し、複数拠点が同時不通となりました。影響範囲は同一顧客の全店舗に及んでおり、顧客からの報告はありません。発生契機はインフラメンテナンス明けであり、05:37に障害を検知しました。技術詳細としては、インフラメンテナンス明けに発生したISP側のBGP経路障害が原因と考えられます。今後の対応が求められます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00174', 'INC-2024-00174', '障害発生から87分後、ISP側のBGP経路障害が確認されました。複数の拠点が同時に影響を受けたことから、原因はISP側の障害であることが強く疑われます。今後、ISPとの連携を強化し、障害の詳細を確認する必要があります。また、影響を受けた店舗への連絡も早急に行い、情報共有を行います。', '障害発生から87分後、ISP側のBGP経路障害が確認されました。複数の拠点が同時に影響を受けたことから、原因はISP側の障害であることが強く疑われます。今後、ISPとの連携を強化し、障害の詳細を確認する必要があります。また、影響を受けた店舗への連絡も早急に行い、情報共有を行います。', TIMESTAMP WITH TIME ZONE '2024-08-12T05:10:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00256', 'INC-2024-00174', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-11T05:25:37+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T06:25:37+09:00', '【初期対応】BGP経路障害の報告', '初期対応として、担当の営業部 花子がISPに連絡を取り、BGP経路障害の詳細確認を進めています。また、影響を受けた顧客への情報提供を開始しました。顧客ネットワークの復旧に向けた対応を優先事項とし、進捗状況を随時報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00175', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-02-08T01:49:59+09:00', TIMESTAMP WITH TIME ZONE '2024-02-08T03:49:59+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2024年2月8日01:49に、架空食品店Aにおいて、EDI経由の棚卸ファイル取込中に件数不一致が発生しました。営業部の花子がこの事象を発見し、03:00に検知されました。対象となるのは顧客店舗POSで、データ移行バッチの実行中に発生した問題です。推定原因はEDI連携ファイルの文字コード不一致と考えられ、影響を受けたのはバッチ処理のみでオンラインには影響がありません。エラーコードはINV-06-00175で、影響コンポーネントは顧客店舗POS（ゾーンA）およびEDIアダプタです。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00175', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00175', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00175', 'INC-2024-00175', '発生したEDI経由の棚卸ファイル取込での件数不一致について詳細調査を行った結果、データ移行バッチの実行中にEDI連携ファイルの文字コード不一致が原因であることが判明しました。この問題はバッチ処理にのみ影響し、オンライン取引には影響がありませんでした。今後は、EDIファイルの文字コードを事前に確認し、再発防止策を講じることが必要です。', '発生したEDI経由の棚卸ファイル取込での件数不一致について詳細調査を行った結果、データ移行バッチの実行中にEDI連携ファイルの文字コード不一致が原因であることが判明しました。この問題はバッチ処理にのみ影響し、オンライン取引には影響がありませんでした。今後は、EDIファイルの文字コードを事前に確認し、再発防止策を講じることが必要です。', TIMESTAMP WITH TIME ZONE '2024-02-09T03:49:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00257', 'INC-2024-00175', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-02-08T04:04:59+09:00', TIMESTAMP WITH TIME ZONE '2024-02-08T05:04:59+09:00', '初期対応ログ', '2024年2月8日01:50に事象を確認し、初期調査を開始しました。EDI連携ファイルの内容を確認し、文字コードの不一致が疑われることを記録。03:00に正式に事象として検知したため、エスカレーションを行い、関連部署に通知しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00258', 'INC-2024-00175', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-02-08T05:34:59+09:00', TIMESTAMP WITH TIME ZONE '2024-02-08T06:34:59+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00178', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-19T09:57:41+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T10:12:41+09:00', '【障害報告】【CLU-08】JWT署名鍵ローテ漏れ', '2024年8月19日09時57分41秒に株式会社ストッククラウドの運用コンソールにおいて、JWT署名鍵ローテ後に旧トークン検証失敗が発生しました。影響範囲は全テナントに波及し、発生契機はインフラメンテナンス明けでした。運用 一郎が発見し、10分後の10時07分41秒に検知されました。推定原因は鍵ローテの段階的切替未実施と考えられます。エラーコードはAUTH-07-00178です。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00178', 'INC-2024-00178', '本件についての調査を行った結果、運用コンソールにおいてJWT署名鍵をローテーションした際、段階的な切替を実施しなかったことが原因であると確認されました。インフラメンテナンス明けのため、現在のトークンと旧トークンの両方が存在し、旧トークンの検証が失敗しました。これにより、全テナントに影響が出たことが明らかになりました。', '本件についての調査を行った結果、運用コンソールにおいてJWT署名鍵をローテーションした際、段階的な切替を実施しなかったことが原因であると確認されました。インフラメンテナンス明けのため、現在のトークンと旧トークンの両方が存在し、旧トークンの検証が失敗しました。これにより、全テナントに影響が出たことが明らかになりました。', TIMESTAMP WITH TIME ZONE '2024-08-20T10:12:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00262', 'INC-2024-00178', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T10:27:41+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T11:27:41+09:00', '初期対応', '初期対応として、直ちにJWT署名鍵のローテーションを見直し、段階的切替を実施する手順を策定しました。また、全テナントに対して影響が及んでいることを通知し、必要な場合には新しいトークンの生成を指示しました。引き続き、運用状況を監視し、再発防止策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00263', 'INC-2024-00178', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T11:57:41+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T12:57:41+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00183', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-19T00:36:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T01:06:38+09:00', '【障害報告】【在庫マスター設定障害】セット商品分解失敗', '2024年8月19日00時36分38秒に、株式会社ストッククラウドのVenusにおいて、在庫マスター設定ミスによる在庫登録失敗が発生しました。症状として、セット商品の在庫分解時に構成エラーが確認されました。この問題は定例リリース直後に発生し、BOM構成テーブルの親子関係不整合が推定原因として挙げられます。本障害の影響範囲は、同一顧客の全店舗に及び、Mercury AWS AP内の在庫計算エンジンに関連しています。エラーコードはMST-07-00183です。本件は私たちの業務運営に影響を及ぼす可能性があるため、早急な対応が必要です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00183', 'INC-2024-00183', '本インシデントに関して、定例リリース直後におけるセット商品の在庫分解時に構成エラーが発生したことを確認しました。原因として、BOM構成テーブルの親子関係不整合が疑われます。この不整合が影響して、在庫計算エンジンが正常に機能せず、全店舗で在庫登録が失敗しました。今後の対応として、BOMテーブルの整合性を確認し、修正を行う必要があります。', '本インシデントに関して、定例リリース直後におけるセット商品の在庫分解時に構成エラーが発生したことを確認しました。原因として、BOM構成テーブルの親子関係不整合が疑われます。この不整合が影響して、在庫計算エンジンが正常に機能せず、全店舗で在庫登録が失敗しました。今後の対応として、BOMテーブルの整合性を確認し、修正を行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-20T01:06:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00270', 'INC-2024-00183', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T01:21:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T02:21:38+09:00', '【初期対応】【在庫マスター設定障害】セット商品分解失敗', '本インシデントに対して、運用部の運用 一郎が初期対応を実施しました。最初の確認で、定例リリース直後に発生した構成エラーが原因であることが判明しました。BOM構成テーブルの再確認を行い、親子関係の不整合を特定し、早急に修正作業を行う準備を進めています。全店舗への影響を最小限に抑えるため、迅速な対応が求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00185', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-03T09:42:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T10:42:04+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2024-08-03 09:42:04に株式会社ストッククラウドのVenusサービスにおいて、顧客ネットワーク障害が発生しました。症状として、ISP側BGP経路障害で複数拠点が同時不通となっており、同一顧客の全店舗に影響が及んでいます。発生契機はインフラメンテナンス明けであり、エラーコードはNW-06-00185です。技術的には、インフラメンテナンス明けにISP側のBGP経路障害が原因と考えられています。検知は2024-08-03 10:41:04に行われました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00185', 'INC-2024-00185', 'インフラメンテナンス明けに発生したISP側のBGP経路障害が原因で、顧客の全店舗が同時にネットワーク障害に見舞われました。ISPとの連絡を取り、経路の状況を確認しています。また、他の顧客からの影響も調査中です。', 'インフラメンテナンス明けに発生したISP側のBGP経路障害が原因で、顧客の全店舗が同時にネットワーク障害に見舞われました。ISPとの連絡を取り、経路の状況を確認しています。また、他の顧客からの影響も調査中です。', TIMESTAMP WITH TIME ZONE '2024-08-04T10:42:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00272', 'INC-2024-00185', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-03T10:57:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T11:57:04+09:00', '【初動対応】【顧客ネットワーク障害】BGP経路障害波及', '発生直後にISPに連絡を取り、BGP経路の障害状況を確認しました。現時点では、ISP側での確認が必要であるとの回答がありました。影響範囲を把握するため、顧客にも状況報告を行い、進捗を待つこととなっています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00187', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-06T11:08:43+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T13:08:43+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2024年8月6日11時08分43秒に、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSでの棚卸突合失敗が発生しました。発見者は営業部の花子で、影響範囲は単一店舗です。13時00分43秒に検知され、検知までに112分かかりました。この障害は定例リリース直後に発生し、Webhookの再送が嵐状になり先方で拒否される事象が確認されました。再送間隔の指数バックオフが未設定であることが推定される原因です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00187', 'INC-2024-00187', '障害発生時、Webhookの再送が異常に多く、先方のシステムに対して過負荷を引き起こしました。この影響で、Webhook再送が拒否される結果になりました。定例リリース後の状況を確認したところ、再送間隔の指数バックオフが設定されていないことが原因と思われます。現在、技術チームが詳細な調査を行い、回避策を検討しています。', '障害発生時、Webhookの再送が異常に多く、先方のシステムに対して過負荷を引き起こしました。この影響で、Webhook再送が拒否される結果になりました。定例リリース後の状況を確認したところ、再送間隔の指数バックオフが設定されていないことが原因と思われます。現在、技術チームが詳細な調査を行い、回避策を検討しています。', TIMESTAMP WITH TIME ZONE '2024-08-07T13:08:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00275', 'INC-2024-00187', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-06T13:23:43+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T14:23:43+09:00', '【対応ログ】【CLU-07】Webhook再送嵐', '2024年8月6日13時10分に、初期対応として技術チームが障害内容を確認しました。発生契機の定例リリース後の状況を調査し、Webhook再送が嵐状になる原因として再送間隔の指数バックオフ未設定を特定しました。即時の修正案を策定し、対応を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00276', 'INC-2024-00187', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-06T14:53:43+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T15:53:43+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00188', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-05-22T04:57:34+09:00', TIMESTAMP WITH TIME ZONE '2024-05-22T05:27:34+09:00', '【障害報告】【監視・可用性障害】合成監視失敗', '発生日時: 2024-05-22T04:57:34+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00188', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00188', 'INC-2024-00188', '合成監視が特定ステップで失敗したため、テストデータの状態を調査しています。初期の観察では、定例リリースに伴うテストデータの期限切れが疑われます。この影響により、合成監視は正常な動作を行えず、サービスの一部機能に障害が発生しています。引き続き原因を特定し、必要な修正を行います。', '合成監視が特定ステップで失敗したため、テストデータの状態を調査しています。初期の観察では、定例リリースに伴うテストデータの期限切れが疑われます。この影響により、合成監視は正常な動作を行えず、サービスの一部機能に障害が発生しています。引き続き原因を特定し、必要な修正を行います。', TIMESTAMP WITH TIME ZONE '2024-05-23T05:27:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00277', 'INC-2024-00188', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-05-22T05:42:34+09:00', TIMESTAMP WITH TIME ZONE '2024-05-22T06:42:34+09:00', '【対応】合成監視失敗の初期対応', '合成監視が特定ステップで失敗した件について、運用チームが最初の対応を行いました。テストデータの期限切れを確認し、必要なデータの更新を行うことで、合成監視の正常化を図ります。顧客への影響を最小限に抑えるため、迅速に対応し、進捗を随時報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00278', 'INC-2024-00188', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-05-22T07:12:34+09:00', TIMESTAMP WITH TIME ZONE '2024-05-22T08:12:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00193', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-28T02:33:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T03:33:16+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2024年8月28日02時33分、株式会社ストッククラウドのVenusサービスにおいて、顧客拠点NWにおいてISP側BGP経路障害が発生し、複数拠点が同時不通となりました。03時05分に検知され、検知までに32分のタイムラグがありました。発生契機はインフラメンテナンス明けであり、影響範囲は同一顧客の全店舗に及びました。特に、顧客拠点NW（DRサイト）及びDNSリゾルバが影響を受けました。エラーコードはNW-06-00193です。技術詳細としては、ISP側のBGP経路障害が原因と考えられています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00193', 'INC-2024-00193', '調査の結果、2024年8月28日02時33分に発生した障害は、ISP側のBGP経路障害によるものであることが確認されました。ISPのメンテナンス作業が影響を及ぼし、同時に複数の拠点が接続不良となりました。顧客からの報告もあり、全店舗が影響を受けていることが確認されています。さらなる詳細なデータ分析を行う必要があります。', '調査の結果、2024年8月28日02時33分に発生した障害は、ISP側のBGP経路障害によるものであることが確認されました。ISPのメンテナンス作業が影響を及ぼし、同時に複数の拠点が接続不良となりました。顧客からの報告もあり、全店舗が影響を受けていることが確認されています。さらなる詳細なデータ分析を行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-29T03:33:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00284', 'INC-2024-00193', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-28T03:48:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T04:48:16+09:00', '【初動対応】【顧客ネットワーク障害】BGP経路障害波及', '初動対応として、2024年8月28日03時05分に障害を検知し、速やかにISPに連絡を取りました。問題点を共有し、障害の影響範囲を確認しました。ISPも問題を認識しており、復旧作業に着手するとのことです。顧客には状況を報告し、進捗に関しては随時連絡を行う方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00285', 'INC-2024-00193', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-28T05:18:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T06:18:16+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00196', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-24T01:10:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T02:10:16+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月24日01時10分16秒、株式会社ストッククラウドの顧客ネットワークにおいて、SD-WANが劣化回線を選択し遅延が増大する事象が発生しました。この影響により、同一顧客の全店舗でネットワークの品質が低下し、顧客へのサービス提供に支障をきたしました。発生契機は大規模セール開始直前であり、特にこの時期においては多くのトラフィックが集中するため、影響が顕著に出ました。エラーコードはNW-10-00196であり、今後の再発防止に向けて、SD-WANポリシーの閾値設定を見直す必要があります。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00196', 'INC-2024-00196', '本事象の調査を進める中で、SD-WANが劣化回線を選択した背景にSD-WANポリシーの閾値設定誤りが疑われました。この設定ミスにより、本来選択すべき最適な経路が選ばれず、結果として遅延が生じるという事態に至りました。調査結果として、今後の運用においてSD-WANのポリシー設定を適切に行うことが必須であると考えられます。', '本事象の調査を進める中で、SD-WANが劣化回線を選択した背景にSD-WANポリシーの閾値設定誤りが疑われました。この設定ミスにより、本来選択すべき最適な経路が選ばれず、結果として遅延が生じるという事態に至りました。調査結果として、今後の運用においてSD-WANのポリシー設定を適切に行うことが必須であると考えられます。', TIMESTAMP WITH TIME ZONE '2024-08-25T02:10:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00288', 'INC-2024-00196', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-24T02:25:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T03:25:16+09:00', '初期対応', '事象発生後、速やかにネットワークの調査を開始しました。まず、SD-WANの設定を確認し、ポリシーに誤りがないかを検証しました。さらに、遅延の原因を特定するため、過去のトラフィックデータと現在の経路選択状況を比較分析しました。この調査により、劣化回線の選択が誤って行われたことが確認され、即時に設定の修正を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00289', 'INC-2024-00196', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-24T03:55:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T04:55:16+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00199', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-13T04:57:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T05:12:38+09:00', '【障害報告】【CLU-08】セッション突然切断', '2024年8月13日04時57分38秒に、株式会社ストッククラウドのサービスVenusにおいて運用者の作業ミスによるアクセス障害が発生した。特定リージョンのユーザーが操作中にセッションが突然切断される事象を確認。発見者は運用部の運用 一郎であり、発生から検知まで14分を要した。確認されたエラーコードはAUTH-02-00199である。障害はインフラメンテナンス明けに発生し、セッションTTL設定の短縮反映が原因と推定される。影響を受けたのは運用コンソールおよびセッションストアである。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00199', 'INC-2024-00199', '障害発生の調査を行った結果、インフラメンテナンス後にセッションTTL設定が短縮されたことが確認された。この影響により、特定リージョンのユーザーにおいて操作中のセッションが突然切断される現象が発生した。なお、切断の原因はセッションTTL設定の変更によるものであり、再発防止策として設定の見直しを提案する。', '障害発生の調査を行った結果、インフラメンテナンス後にセッションTTL設定が短縮されたことが確認された。この影響により、特定リージョンのユーザーにおいて操作中のセッションが突然切断される現象が発生した。なお、切断の原因はセッションTTL設定の変更によるものであり、再発防止策として設定の見直しを提案する。', TIMESTAMP WITH TIME ZONE '2024-08-14T05:12:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00293', 'INC-2024-00199', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-13T05:27:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T06:27:38+09:00', '初期対応', 'インシデント発生後、運用部では迅速に対策を講じ、影響を受けたユーザーに対して謝罪と情報提供を行った。また、セッションTTL設定の確認と必要な修正を実施し、再発防止に向けた対応を開始した。集中的なモニタリングを行い、ユーザーからのフィードバックを受け付ける体制を整えた。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00294', 'INC-2024-00199', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-13T06:57:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T07:57:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00200', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-04-24T23:58:48+09:00', TIMESTAMP WITH TIME ZONE '2024-04-25T01:58:48+09:00', '【障害報告】【棚卸・POS突合障害】自動補充提案誤算', '2024年4月24日、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSにて自動補充提案数量が実需とかけ離れるという棚卸突合失敗が発生しました。本障害は特定リージョンのユーザーに影響を及ぼし、発生契機として大規模セール開始直前のタイミングが挙げられます。検知は2024年4月25日1時57分に行われ、119分を要しました。販売予測モデルの学習データ欠損が推定原因として疑われており、補充提案エンジンの機能不全が影響範囲に含まれています。今後、この問題を解決するために技術的な対策を講じる必要があります。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00200', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00200', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00200', 'INC-2024-00200', '本インシデントにおける調査により、大規模セール開始直前に自動補充提案数量が実需とかけ離れていた背景が明らかとなりました。販売予測モデルの学習データに欠損があったため、正確な提案が行えず、顧客店舗POSの機能に影響が出たと考えられます。これにより、自動補充の効率が低下し、在庫管理に混乱を招く結果となりました。今後は学習データの整備を進め、予測モデルの精度向上に努めます。', '本インシデントにおける調査により、大規模セール開始直前に自動補充提案数量が実需とかけ離れていた背景が明らかとなりました。販売予測モデルの学習データに欠損があったため、正確な提案が行えず、顧客店舗POSの機能に影響が出たと考えられます。これにより、自動補充の効率が低下し、在庫管理に混乱を招く結果となりました。今後は学習データの整備を進め、予測モデルの精度向上に努めます。', TIMESTAMP WITH TIME ZONE '2024-04-26T01:58:48+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00295', 'INC-2024-00200', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-04-25T02:13:48+09:00', TIMESTAMP WITH TIME ZONE '2024-04-25T03:13:48+09:00', '初期対応', 'インシデント発生時、営業部の花子が問題を認識し、まずは顧客店舗Bと顧客店舗Aに状況を報告しました。続いて、技術チームに連絡を取り、販売予測モデルのデータを確認し始めました。問題の特定と解決に向けた最初のステップとして、関連データを収集し、分析を行う体制を整えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00201', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-08T00:36:33+09:00', TIMESTAMP WITH TIME ZONE '2024-08-08T01:36:33+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2024年8月8日00時36分33秒に、株式会社ストッククラウドのVenusサービスにおいて顧客側ネットワーク障害が発生しました。症状としては、顧客固定IP変更が許可リストに未反映となっており、これは顧客拠点NWに影響を及ぼしています。また、当該事象は単一店舗に限られており、エラーコードNW-07-00201が記録されています。発生契機は顧客オンボーディング当日であり、発見者は営業の花子です。技術的には、顧客オンボーディングの際に固定IP変更が許可リストに反映されていないことが原因と考えられており、IP許可リストの更新漏れが疑われます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00201', 'INC-2024-00201', '本ケースにおいて、顧客の固定IP変更が許可リストに未反映であったため、顧客のネットワークに障害が発生しました。調査の結果、IP許可リストの更新が漏れていたことが明らかになりました。原因の特定においては、顧客オンボーディング当日の手続きにおけるミスが影響していると考えられます。今後は、こうした事象を防ぐための確認プロセスを強化する必要があります。', '本ケースにおいて、顧客の固定IP変更が許可リストに未反映であったため、顧客のネットワークに障害が発生しました。調査の結果、IP許可リストの更新が漏れていたことが明らかになりました。原因の特定においては、顧客オンボーディング当日の手続きにおけるミスが影響していると考えられます。今後は、こうした事象を防ぐための確認プロセスを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-09T01:36:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00296', 'INC-2024-00201', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-08T01:51:33+09:00', TIMESTAMP WITH TIME ZONE '2024-08-08T02:51:33+09:00', '【初動対応】【顧客ネットワーク障害】固定IP変更未連絡', '2024年8月8日01時37分33秒に障害を検知しました。初動として、営業部の花子が顧客に連絡を取り、問題の状況を確認しました。顧客側の構成情報を調査し、固定IPの変更履歴を確認することで、許可リストに反映されていないことが culprit であると特定しました。この情報をもとに、早急に許可リストの更新を実施し、問題の解決に向けて動き出しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00202', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-12-02T13:36:23+09:00', TIMESTAMP WITH TIME ZONE '2024-12-02T14:06:23+09:00', '【障害報告】【認証・セッション障害】ブルートフォース誤検知', '2024年12月2日13時36分23秒、株式会社ストッククラウドが提供するVenusのAzure APにおいて、架空服飾店Aに対してブルートフォース検知のため、正常IPが遮断される事象が発生しました。この影響により、顧客はセッションの確立が困難となり、利用者増による応答遅延が報告されています。発生契機は大規模セール開始直前であり、検知閾値が過敏に設定されていた可能性が考えられます。影響を受けたコンポーネントはVenus Azure AP（ゾーンA）およびWAFです。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00202', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00202', 'INC-2024-00202', '運用部の運用 一郎による調査の結果、正常IPの遮断はブルートフォース検知によるものであることが判明しました。検知閾値の設定が過敏であったため、実際には攻撃ではないトラフィックが遮断され、顧客に影響を及ぼしました。今後、この設定を見直し、正常トラフィックが影響を受けないよう適切な閾値の再設定を行う必要があります。', '運用部の運用 一郎による調査の結果、正常IPの遮断はブルートフォース検知によるものであることが判明しました。検知閾値の設定が過敏であったため、実際には攻撃ではないトラフィックが遮断され、顧客に影響を及ぼしました。今後、この設定を見直し、正常トラフィックが影響を受けないよう適切な閾値の再設定を行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-12-03T14:06:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00297', 'INC-2024-00202', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-12-02T14:21:23+09:00', TIMESTAMP WITH TIME ZONE '2024-12-02T15:21:23+09:00', '【初期対応】【認証・セッション障害】ブルートフォース誤検知対応', '2024年12月2日14時06分23秒、運用部が事象を認識しました。直ちにWAFの設定を確認し、過敏な検知閾値を見直すことを決定しました。また、架空服飾店Aには状況を説明し、影響を受けたトラフィックの復旧を進める旨を伝えました。さらに、他の店舗への影響を防ぐため、全店舗の設定確認を実施し、再発防止策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00298', 'INC-2024-00202', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-12-02T15:51:23+09:00', TIMESTAMP WITH TIME ZONE '2024-12-02T16:51:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00206', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-05-29T19:32:33+09:00', TIMESTAMP WITH TIME ZONE '2024-05-29T20:02:33+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2024年5月29日19時32分33秒に、株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Bに関連するマスター設定ミスによる在庫登録失敗が発生しました。この障害により、マスター更新と在庫が二重反映される現象が確認されました。発生は定例リリース直後であり、全店舗に影響を及ぼしました。エラーコードはSYNC-01-00206であり、原因としてイベント順序の逆転配信が疑われます。検知は19時58分33秒であり、26分間の間に問題が発生していました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00206', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00206', 'INC-2024-00206', '本件についての調査を行った結果、定例リリース直後に発生したことが問題の根源であることが判明しました。特に、Mercury AWS APとイベントバス間での通信において、イベントの順序が逆転して配信されたことが原因で、マスター更新と在庫の二重反映が引き起こされたものと考えられます。全店舗への影響があったため、迅速な対応が求められます。', '本件についての調査を行った結果、定例リリース直後に発生したことが問題の根源であることが判明しました。特に、Mercury AWS APとイベントバス間での通信において、イベントの順序が逆転して配信されたことが原因で、マスター更新と在庫の二重反映が引き起こされたものと考えられます。全店舗への影響があったため、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2024-05-30T20:02:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00303', 'INC-2024-00206', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-05-29T20:17:33+09:00', TIMESTAMP WITH TIME ZONE '2024-05-29T21:17:33+09:00', '【初期対応】【データ同期・整合性障害】マスター在庫二重反映への初期対応', '初期対応として、運用部の運用 一郎が担当し、問題の詳細な原因分析を開始しました。また、直ちにイベント順序の確認を行い、二重反映の影響を受けた在庫データの修正を行うための手順を整備しました。影響を受けた全店舗に情報連絡を行い、再発防止策の策定も同時に進めることとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00304', 'INC-2024-00206', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-05-29T21:47:33+09:00', TIMESTAMP WITH TIME ZONE '2024-05-29T22:47:33+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00209', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-16T12:36:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T13:36:30+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月16日12時36分に、株式会社ストッククラウドの顧客ネットワークにおいてSD-WANが劣化回線を選択する事象が発生しました。この影響により、全店舗において遅延が増大し、顧客の業務に支障をきたしました。発生契機として、大規模セール開始直前のタイミングであったため、影響は特に顕著でした。問題は2024年8月16日13時39分に検知され、営業部の花子が初めて確認しました。トラブルの根本原因として、SD-WANポリシーの閾値設定誤りが疑われます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00209', 'INC-2024-00209', '調査の結果、SD-WANが劣化回線を選択する原因として、ポリシーの閾値設定誤りが特定されました。これにより、通常時よりも不適切な経路が選択され、遅延が発生していました。また、現場でのモニタリング不足も要因と考えられ、今後の改善としては、設定の見直し及びモニタリング強化が求められます。', '調査の結果、SD-WANが劣化回線を選択する原因として、ポリシーの閾値設定誤りが特定されました。これにより、通常時よりも不適切な経路が選択され、遅延が発生していました。また、現場でのモニタリング不足も要因と考えられ、今後の改善としては、設定の見直し及びモニタリング強化が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-17T13:36:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00308', 'INC-2024-00209', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-16T13:51:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T14:51:30+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '初期対応として、SD-WANの設定を確認し、劣化回線が選択されないような閾値の調整を行いました。また、対象の顧客に対しては、影響が出ている旨を迅速に報告し、業務に支障が出ていることを謝罪しました。さらに、遅延が発生している時間帯におけるトラフィックの監視を強化し、必要に応じて追加の対策を講じることとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00213', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-11T15:57:56+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T16:57:56+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '2024年8月11日15時57分56秒、株式会社ストッククラウドのVenusサービスにおいて、顧客拠点NWに関連するネットワーク障害が発生いたしました。発生時には、店舗Wi-Fiの認証ページにおいてAPI通信が遮断される症状が確認されました。この障害は、新規店舗追加の初日に発生したもので、影響範囲は単一店舗のみとなっております。推定される原因は、キャプティブポータルによるHTTPSインターセプトです。この件に関してお客様からの報告はありませんが、我々の監視システムにより、2024年8月11日17時25分56秒に検知されました。検知までの時間は88分となります。対応には、顧客側FWと顧客拠点NW（Secondary）が関与しています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00213', 'INC-2024-00213', '本件につきまして調査を行った結果、新規店舗追加の初日に店舗Wi-Fiの認証ページでAPI通信が遮断される状態が発生したことが確認されました。特に、キャプティブポータルによるHTTPSインターセプトが原因である可能性が高いと考えられます。現在、詳細な技術的解析を進めており、今後の対応策を検討中です。', '本件につきまして調査を行った結果、新規店舗追加の初日に店舗Wi-Fiの認証ページでAPI通信が遮断される状態が発生したことが確認されました。特に、キャプティブポータルによるHTTPSインターセプトが原因である可能性が高いと考えられます。現在、詳細な技術的解析を進めており、今後の対応策を検討中です。', TIMESTAMP WITH TIME ZONE '2024-08-12T16:57:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00314', 'INC-2024-00213', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-11T17:12:56+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T18:12:56+09:00', '【初動対応】【顧客ネットワーク障害】Wi-Fi captive portal', '弊社営業部の花子が本件の初動対応を実施いたしました。まず、該当店舗のネットワーク設定を確認し、キャプティブポータルの設定に不備がないかをチェックしました。同時に、お客様への影響を最小限に抑えるため、必要なネットワーク設定の変更を行い、通信の正常化を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00214', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-09-08T13:30:34+09:00', TIMESTAMP WITH TIME ZONE '2024-09-08T13:45:34+09:00', '【障害報告】【運用操作・権限障害】監視画面真っ白', '・発生日時: 2024年9月8日 13:30
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00214', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00214', 'INC-2024-00214', '監視ダッシュボードが真っ白でメトリクスが表示されない問題の調査を実施。運用者の作業ミスによる可能性が高いことが判明。特に、グラフクエリの時間範囲パラメータの誤設定が直接の原因と考えられる。定例リリース直後の影響も確認されており、運用部門全体に影響を及ぼしている。', '監視ダッシュボードが真っ白でメトリクスが表示されない問題の調査を実施。運用者の作業ミスによる可能性が高いことが判明。特に、グラフクエリの時間範囲パラメータの誤設定が直接の原因と考えられる。定例リリース直後の影響も確認されており、運用部門全体に影響を及ぼしている。', TIMESTAMP WITH TIME ZONE '2024-09-09T13:45:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00315', 'INC-2024-00214', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-08T14:00:34+09:00', TIMESTAMP WITH TIME ZONE '2024-09-08T15:00:34+09:00', '【初期対応】【運用操作・権限障害】監視画面真っ白', '障害を受けて運用部門に対し、監視ダッシュボードの復旧作業を実施。グラフクエリの時間範囲パラメータに関する設定を確認し、誤設定を修正した。運用コンソールの監視機能を復旧させ、メトリクスが正常に表示されることを確認。定例リリース後の影響についても今後の作業で検証を行う予定。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00218', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-12-24T17:54:36+09:00', TIMESTAMP WITH TIME ZONE '2024-12-24T19:54:36+09:00', '【障害報告】【データ同期・整合性障害】クロスリージョンレプリケーション', '発生日時: 2024-12-24 17:54:36
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00218', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00218', 'INC-2024-00218', 'インフラメンテナンス明けに発生した障害に関して、調査を行いました。結果として、クロスリージョン複製の片系のみが更新される状態が確認されました。この事象は、リージョンルーティングの誤設定が原因であると考えられます。特定のリージョンのユーザーだけが影響を受けているため、迅速な対策が求められています。', 'インフラメンテナンス明けに発生した障害に関して、調査を行いました。結果として、クロスリージョン複製の片系のみが更新される状態が確認されました。この事象は、リージョンルーティングの誤設定が原因であると考えられます。特定のリージョンのユーザーだけが影響を受けているため、迅速な対策が求められています。', TIMESTAMP WITH TIME ZONE '2024-12-25T19:54:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00320', 'INC-2024-00218', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-12-24T20:09:36+09:00', TIMESTAMP WITH TIME ZONE '2024-12-24T21:09:36+09:00', '【初期対応】【データ同期・整合性障害】クロスリージョンレプリケーション', '初期対応として、影響を受けた顧客店舗POSの設定を確認し、リージョンルーティングの設定を見直しました。また、レプリケーションゲートウェイの状態を監視して、更新状況を確認する体制を整えました。さらに、障害の影響範囲を特定し、 affected users への報告を行い、問題解決に向けた進捗を共有しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00220', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-19T09:22:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T09:52:20+09:00', '【障害報告】【監視・可用性障害】ログ相関ID欠落', '2024年8月19日09時22分20秒に、株式会社ストッククラウドのサービスVenusにおいて、ログに相関IDが欠落し、横断検索が不可となる事象が発生しました。この障害は、運用部門に影響を及ぼし、定例リリース直後に発生したものです。検知は2024年8月19日09時46分20秒に行われ、検知までに24分の時間を要しました。主な影響コンポーネントはVenus Azure APおよびログパイプラインです。この障害の推定原因は、ログフォーマット変更に関するロールアウト漏れと考えられています。今後の対応を進める必要があります。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00220', 'INC-2024-00220', '調査の結果、定例リリース直後において、ログに相関IDが欠落する事象が発生したことが確認されました。原因としては、ログフォーマット変更のロールアウト漏れが疑われています。このため、運用部門では監視システムの確認を行い、再発防止に向けた対策を講じる必要があります。ログの整合性を保つため、今後のリリース時には十分なテストを実施することが求められます。', '調査の結果、定例リリース直後において、ログに相関IDが欠落する事象が発生したことが確認されました。原因としては、ログフォーマット変更のロールアウト漏れが疑われています。このため、運用部門では監視システムの確認を行い、再発防止に向けた対策を講じる必要があります。ログの整合性を保つため、今後のリリース時には十分なテストを実施することが求められます。', TIMESTAMP WITH TIME ZONE '2024-08-20T09:52:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00323', 'INC-2024-00220', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T10:07:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T11:07:20+09:00', '初期対応', '運用部門は、ログの相関ID欠落に関する初期調査を開始しました。エラーコードMON-09-00220に基づき、発生した事象の詳細を分析し、ログフォーマット変更の影響を検証しています。また、定例リリース時の手順を見直し、今後同様の問題が発生しないよう改善策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00324', 'INC-2024-00220', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T11:37:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T12:37:20+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00234', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-19T07:00:02+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T09:00:02+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2024-08-19 07:00:02に、株式会社ストッククラウドのサービスVenusにおいて、顧客店舗POSでの棚卸突合失敗が発生しました。発見者は営業部の花子です。定例リリース直後にWebhook再送が嵐状になり先方で拒否されました。再送間隔の指数バックオフ未設定が推定され、影響範囲は単一店舗です。エラーコードはEDI-02-00234であり、影響コンポーネントは顧客店舗POSおよびWebhookディスパッチャです。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00234', 'INC-2024-00234', '', '', TIMESTAMP WITH TIME ZONE '2024-08-20T09:00:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
