INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00346', 'INC-2024-00234', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-19T10:45:02+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T11:45:02+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00243', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-09T07:36:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T07:51:40+09:00', '【障害報告】【監視・可用性障害】トレースサンプリング過少', '2024年8月9日07時36分40秒、株式会社ストッククラウドのサービスVenusにおいて、運用者の作業ミスによるアクセス障害が発生しました。発生場所は運用コンソールであり、障害の検知は07時56分40秒に行われました。障害の症状としては、分散トレースのサンプリング率が過少であるため、原因特定が困難な状況となっていました。この影響は運用部門に限定されており、エラーコードはMON-05-00243です。障害の発生契機は定例リリース直後であり、影響コンポーネントには運用コンソール（ゾーンB）やトレーシング基盤が含まれます。技術的な詳細としては、定例リリース直後に発生した分散トレースのサンプリング率過少のため、原因特定が困難であることが挙げられます。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00243', 'INC-2024-00243', '運用者による作業ミスが原因で、分散トレースのサンプリング率が過少になったことが確認されました。調査の結果、サンプリング率の本番設定誤りが推定されており、このことにより原因特定が困難な状況が継続しています。運用部門への影響が大きく、迅速な対応が求められます。', '運用者による作業ミスが原因で、分散トレースのサンプリング率が過少になったことが確認されました。調査の結果、サンプリング率の本番設定誤りが推定されており、このことにより原因特定が困難な状況が継続しています。運用部門への影響が大きく、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-10T07:51:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00359', 'INC-2024-00243', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-09T08:06:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T09:06:40+09:00', '【初期対応】【監視・可用性障害】トレースサンプリング過少', '障害が発生した際には、直ちに運用コンソールの設定を確認しました。その結果、サンプリング率の本番設定に誤りがあることが判明し、速やかに修正作業を開始しました。運用部門と連携し、影響を最小限に抑えるための対応を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00360', 'INC-2024-00243', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-09T09:36:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T10:36:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00246', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-28T01:18:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T01:48:38+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2024年8月28日01時18分38秒に、株式会社ストッククラウドのVenusサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。発生個所はMercury AWS APであり、運用部の運用 一郎が発見しました。スナップショット復元後に在庫整合が崩れる事象が確認され、全テナントに波及する影響が懸念されています。この問題は、データ移行バッチ実行中に発生し、復元ポイントのトランザクションログ欠落が推定される原因です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00246', 'INC-2024-00246', '本事象に関する調査を実施しました。データ移行バッチ実行中にスナップショット復元を行った結果、在庫整合が崩れたことが確認されました。調査の過程で、復元ポイントのトランザクションログが欠落していることが明らかとなり、これが整合崩れの直接的な原因であると考えています。今後の対策として、トランザクションログの堅持を強化する必要があります。', '本事象に関する調査を実施しました。データ移行バッチ実行中にスナップショット復元を行った結果、在庫整合が崩れたことが確認されました。調査の過程で、復元ポイントのトランザクションログが欠落していることが明らかとなり、これが整合崩れの直接的な原因であると考えています。今後の対策として、トランザクションログの堅持を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-29T01:48:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00365', 'INC-2024-00246', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T02:03:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T03:03:38+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合に対する初期対応', '初期対応として、まずはデータ移行バッチの実行を一時停止し、影響範囲の特定を行いました。その後、運用部の運用 一郎を中心に、スナップショット復元の設定およびログの確認を行い、復元ポイントのトランザクションログの欠落を確認しました。現在は、全テナントへの影響を最小限に抑えるべく、復元プロセスを見直し、再発防止策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00248', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-09-28T07:16:51+09:00', TIMESTAMP WITH TIME ZONE '2024-09-28T08:16:51+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年9月28日07時16分51秒に発生した顧客側ネットワーク障害について報告します。発生した障害は、SD-WANが劣化回線を選択し、結果として遅延が増大するというものでした。影響範囲は同一顧客の全店舗に及び、顧客名は特定されていません。エラーコードはNW-10-00248です。発生の契機は、大規模セール開始直前であり、このタイミングでの経路選択の誤りが影響を及ぼしました。技術的には、SD-WANポリシーの閾値設定誤りが疑われます。なお、検知は2024年9月28日08時05分51秒に行われ、検知までの時間は49分でした。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00248', 'INC-2024-00248', '調査の結果、SD-WANが劣化回線を選択した原因として、SD-WANポリシーの閾値設定誤りが示唆されました。この設定ミスにより、経路選択が適切に行われず、遅延が増大しました。影響を受けたのは同一顧客の全店舗であり、顧客ネットワーク全体に悪影響を及ぼしました。今後の対策としては、SD-WANポリシーの設定見直しと、障害発生時の迅速な検知および対応体制の強化が必要です。', '調査の結果、SD-WANが劣化回線を選択した原因として、SD-WANポリシーの閾値設定誤りが示唆されました。この設定ミスにより、経路選択が適切に行われず、遅延が増大しました。影響を受けたのは同一顧客の全店舗であり、顧客ネットワーク全体に悪影響を及ぼしました。今後の対策としては、SD-WANポリシーの設定見直しと、障害発生時の迅速な検知および対応体制の強化が必要です。', TIMESTAMP WITH TIME ZONE '2024-09-29T08:16:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00367', 'INC-2024-00248', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-09-28T08:31:51+09:00', TIMESTAMP WITH TIME ZONE '2024-09-28T09:31:51+09:00', '【初動対応】【顧客ネットワーク障害】障害の初動対応', '初動対応として、2024年9月28日08時05分51秒に障害を検知し、迅速に状況を把握しました。営業部の花子が中心となり、影響を受けた顧客店舗への連絡を行い、現在の状況を説明しました。また、技術部門と連携し、SD-WANポリシーの設定確認を開始しました。障害の影響範囲を把握するため、全店舗のネットワーク状況を調査し、必要な対策を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00368', 'INC-2024-00248', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-09-28T10:01:51+09:00', TIMESTAMP WITH TIME ZONE '2024-09-28T11:01:51+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00251', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-20T04:20:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T04:35:32+09:00', '【障害報告】【CLU-10】トレースサンプリング過少', '2024年8月20日04時20分32秒に発生した運用者の作業ミスによるアクセス障害に関して報告いたします。本障害は運用コンソールにおいて、分散トレースのサンプリング率が過少となり、原因特定が困難な状況を引き起こしました。影響範囲は運用部門のみとなり、特に定例リリース直後に発生したことが影響を及ぼしている可能性があります。エラーコードはMON-05-00251で、運用部の運用 一郎が発見しました。検知までの時間は14分でした。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00251', 'INC-2024-00251', '本障害の調査において、分散トレースのサンプリング率が過少であることが確認されました。これはサンプリング率の本番設定誤りによるものであり、技術詳細として定例リリース直後の影響が大きいと考えられます。原因特定が困難な状況が続いているため、早急に対応策を講じる必要があります。', '本障害の調査において、分散トレースのサンプリング率が過少であることが確認されました。これはサンプリング率の本番設定誤りによるものであり、技術詳細として定例リリース直後の影響が大きいと考えられます。原因特定が困難な状況が続いているため、早急に対応策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-21T04:35:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00372', 'INC-2024-00251', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-20T04:50:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T05:50:32+09:00', '【初期対応】【CLU-10】トレースサンプリング過少', '運用部では早急に分散トレースのサンプリング設定を確認し、正しい値に修正いたしました。また、影響を受けた運用コンソールのログを分析し、再発防止策を検討するためのデータを収集しました。顧客への影響は確認されておりませんが、今後の監視体制を強化し、同様の障害が発生しないよう努めてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00253', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-01T20:36:12+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T20:51:12+09:00', '【障害報告】【運用操作・権限障害】メンテ解除失敗', '2024年8月1日20時36分12秒に、株式会社ストッククラウドのVenusサービスにおいて、運用コンソールにてメンテナンスモード解除操作が失敗しました。運用部の運用 一郎が発見し、20時37分12秒に検知しました。この障害はサービス全体の一部機能に影響を与え、インフラメンテナンス明けにメンテナンスフラグの残留が原因と推定されます。エラーコードはOPS-03-00253です。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00253', 'INC-2024-00253', '運用 一郎が発見したメンテナンスモード解除操作の失敗について調査を行いました。原因としてメンテナンスフラグの残留が疑われ、影響範囲はサービス全体の一部機能に及びました。今後、メンテナンスフラグの管理を徹底し、同様の障害が発生しないよう努めます。', '運用 一郎が発見したメンテナンスモード解除操作の失敗について調査を行いました。原因としてメンテナンスフラグの残留が疑われ、影響範囲はサービス全体の一部機能に及びました。今後、メンテナンスフラグの管理を徹底し、同様の障害が発生しないよう努めます。', TIMESTAMP WITH TIME ZONE '2024-08-02T20:51:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00375', 'INC-2024-00253', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-01T21:06:12+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T22:06:12+09:00', '【初期対応】【運用操作・権限障害】メンテ解除失敗の初期対応', '障害発生後、運用 一郎が直ちにメンテナンスフラグの状況を確認しました。フラグの状態に異常が見られ、解除操作が行えないことを確認しました。迅速に関係者との連携を図り、問題解決に向けた措置を講じております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00257', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-11T08:35:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T09:35:30+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月11日08時35分30秒、株式会社ストッククラウドのVenusサービスにおいて顧客側ネットワーク障害が発生しました。症状としては、SD-WANが劣化回線を選択し、遅延が増大しました。この問題は大規模セール開始直前に発生し、全店舗に影響が及んでいます。発見者は営業部の花子であり、08時54分30秒にこの障害を検知しました。推定原因として、SD-WANポリシーの閾値設定誤りが考えられます。エラーコードはNW-10-00257です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00257', 'INC-2024-00257', '調査の結果、SD-WANが劣化回線を選択する原因として、設定されたポリシーの閾値が適切でなかったことが確認されました。これにより、顧客ネットワークにおいて遅延が顕著に増加しました。本件は大規模セールの開始前に発生したため、影響範囲は同一顧客の全店舗に及びました。今後は、ポリシーの設定を見直し、類似の障害を未然に防ぐための対策を講じる必要があります。', '調査の結果、SD-WANが劣化回線を選択する原因として、設定されたポリシーの閾値が適切でなかったことが確認されました。これにより、顧客ネットワークにおいて遅延が顕著に増加しました。本件は大規模セールの開始前に発生したため、影響範囲は同一顧客の全店舗に及びました。今後は、ポリシーの設定を見直し、類似の障害を未然に防ぐための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-12T09:35:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00380', 'INC-2024-00257', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-11T09:50:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T10:50:30+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤りの初期対応', '初期対応として、該当のSD-WANポリシー設定を確認し、閾値を適切に調整する作業を実施しました。影響を受けた全店舗に対し、状況の説明とお詫びを行い、遅延の解消に向けた取り組みを進めました。顧客からの問い合わせに対しては、迅速に応答し、トラブルシューティングを行いながら進捗を報告しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00269', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-12-28T12:39:47+09:00', TIMESTAMP WITH TIME ZONE '2024-12-28T13:39:47+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '株式会社ストッククラウドのVenusサービスにおいて、架空服飾店Aの顧客拠点NWにおいて顧客側ネットワーク障害が発生しました。発生日時は2024年12月28日12時39分で、代理サーバー経由のアクセスで502エラーが返されました。これは、大規模セール開始直前に発生しており、顧客に少なからぬ影響を及ぼしています。推定原因としては、プロキシの上流タイムアウト設定が過短である可能性があります。影響範囲は単一店舗のみであり、エラーコードはNW-04-00269です。技術的には、顧客拠点NW（ゾーンA）及び顧客側FWに影響が出ています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00269', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00269', 'INC-2024-00269', '本障害の調査において、代理サーバー経由でのアクセス時に502エラーが返されることが確認されました。大規模セール開始直前のタイミングで発生しているため、通常のアクセスパターンとは異なる状況が想定されます。プロキシの上流タイムアウト設定が短すぎることが、根本原因として疑われています。今後の調査では、この設定値の確認と適切な値への修正を行います。', '本障害の調査において、代理サーバー経由でのアクセス時に502エラーが返されることが確認されました。大規模セール開始直前のタイミングで発生しているため、通常のアクセスパターンとは異なる状況が想定されます。プロキシの上流タイムアウト設定が短すぎることが、根本原因として疑われています。今後の調査では、この設定値の確認と適切な値への修正を行います。', TIMESTAMP WITH TIME ZONE '2024-12-29T13:39:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00398', 'INC-2024-00269', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-12-28T13:54:47+09:00', TIMESTAMP WITH TIME ZONE '2024-12-28T14:54:47+09:00', '【障害対応】【顧客ネットワーク障害】代理サーバー502', '営業部の花子が架空服飾店Aのシステムに対し、早急に連絡を取り、状況を確認しました。顧客には現在の状況を説明し、エンジニアチームが調査を開始したことを伝えました。プロキシの設定確認を行い、必要に応じてタイムアウト設定を見直す方針です。また、顧客には問題解決の進捗を随時報告する旨を約束しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00399', 'INC-2024-00269', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-12-28T15:24:47+09:00', TIMESTAMP WITH TIME ZONE '2024-12-28T16:24:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00271', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-03T14:05:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T14:50:46+09:00', '【障害報告】【CLU-10】メトリクス欠損', '2024年8月3日14時05分46秒、株式会社ストッククラウドのVenusにおいて、Mercury AWS Storageに関するストレージ溢れのインシデントが発生しました。この障害により、主要メトリクス系列が15分間欠損し、運用部門に影響を及ぼしました。発生契機はインフラメンテナンス明けであり、推定原因としてメトリクスエージェントの再起動失敗が考えられています。14時41分46秒に検知されたこの問題は、エラーコードMON-04-00271が関連しています。この事象により監視・可用性障害が発生し、運用部門は重要なデータの欠損を経験しました。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00271', 'INC-2024-00271', 'インシデントの調査では、インフラメンテナンス後にメトリクスエージェントが正常に再起動されなかったことが原因とされています。この結果、主要メトリクス系列が15分間欠損し、運用部門の監視能力が低下しました。問題の根本原因を特定するために、メトリクスエージェントのログを確認し、関連するエラーメッセージを分析しました。障害の再発防止に向けて、エージェントの監視と再起動手順の見直しが必要です。', 'インシデントの調査では、インフラメンテナンス後にメトリクスエージェントが正常に再起動されなかったことが原因とされています。この結果、主要メトリクス系列が15分間欠損し、運用部門の監視能力が低下しました。問題の根本原因を特定するために、メトリクスエージェントのログを確認し、関連するエラーメッセージを分析しました。障害の再発防止に向けて、エージェントの監視と再起動手順の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-04T14:50:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00402', 'INC-2024-00271', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-03T15:05:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T16:05:46+09:00', '【初期対応】【CLU-10】メトリクス欠損の初期対応', 'インシデント発生後、運用部門は直ちにメトリクスエージェントの状態を確認し、再起動を試みました。しかし、再起動に失敗し、主要メトリクスが依然として欠損していることが確認されました。エラーコードMON-04-00271に基づき、技術チームが急遽対応にあたり、さらなる分析を実施しました。状況の把握と迅速な対応が求められました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00403', 'INC-2024-00271', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-03T16:35:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T17:35:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00273', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-20T23:50:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T00:50:32+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年8月20日23時50分32分に株式会社ストッククラウドのサービスVenusにおいて、顧客側ネットワーク障害が発生しました。症状としては、DNS解決成功後にTLS握手で接続が切断されるというもので、影響範囲は同一顧客の全店舗に及びました。エラーコードはNW-03-00273です。発生契機はインフラメンテナンス明けであり、トラブルシューティングを開始した結果、原因としてプロキシ証明書の期限切れが疑われます。この問題は営業部の花子によって発見され、検知までに51分を要しました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00273', 'INC-2024-00273', '発生した顧客ネットワーク障害に関して調査を行った結果、インフラメンテナンス後にDNS解決は成功したものの、TLS握手時に接続が切断されていることが確認されました。プロキシ証明書の期限切れが今回の問題の直接的な原因と考えられ、この証明書が失効したことにより、正常なTLS接続が行えなくなったものと推測されます。本件に関するさらなる詳細な調査が必要です。', '発生した顧客ネットワーク障害に関して調査を行った結果、インフラメンテナンス後にDNS解決は成功したものの、TLS握手時に接続が切断されていることが確認されました。プロキシ証明書の期限切れが今回の問題の直接的な原因と考えられ、この証明書が失効したことにより、正常なTLS接続が行えなくなったものと推測されます。本件に関するさらなる詳細な調査が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-22T00:50:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00405', 'INC-2024-00273', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-21T01:05:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T02:05:32+09:00', '【障害対応】【顧客ネットワーク障害】TLS握手切断', '本件に関して初動対応を実施しました。まず、プロキシ証明書の状態を確認し、期限切れであることを確認しました。証明書の更新を行い、その後TLS接続の確認テストを実施しました。テストの結果、正常に接続できることを確認し、全店舗に対してサービスの復旧を報告しました。今後は、証明書の管理体制を強化し、同様の障害が再発しないような対策を検討していく必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00276', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-09-22T06:03:11+09:00', TIMESTAMP WITH TIME ZONE '2024-09-22T07:03:11+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2024年9月22日06時03分に、株式会社ストッククラウドの顧客拠点ネットワークにおいて、店舗VPN経由でSaaSに到達できない事象が発生しました。本事象は顧客オンボーディング当日に発生しており、影響範囲は単一店舗のみとなっております。検知時刻は07時04分であり、発見者は営業部の花子です。推定原因としては、拠点FWのルール変更が考えられます。エラーコードはNW-01-00276です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00276', 'INC-2024-00276', '調査の結果、顧客拠点NWにおけるFWのルール変更が実施されたことが確認されました。この変更により、店舗VPN経由でのSaaSへの接続が妨げられ、顧客ネットワークに影響を与えました。今後、FWの設定を見直し、必要に応じてルールを修正することで、同様の事象を防止する取り組みを進めます。', '調査の結果、顧客拠点NWにおけるFWのルール変更が実施されたことが確認されました。この変更により、店舗VPN経由でのSaaSへの接続が妨げられ、顧客ネットワークに影響を与えました。今後、FWの設定を見直し、必要に応じてルールを修正することで、同様の事象を防止する取り組みを進めます。', TIMESTAMP WITH TIME ZONE '2024-09-23T07:03:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00408', 'INC-2024-00276', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-09-22T07:18:11+09:00', TIMESTAMP WITH TIME ZONE '2024-09-22T08:18:11+09:00', '【初動対応】【顧客ネットワーク障害】店舗VPN到達不可', '初動対応として、拠点FWの設定を確認し、ルール変更の影響を特定しました。顧客の店舗に異常が発生しているため、速やかにFWの設定を元に戻し、VPN接続の復旧を図ることを優先しました。顧客には状況を説明し、復旧作業の進捗を随時報告しております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00409', 'INC-2024-00276', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-09-22T08:48:11+09:00', TIMESTAMP WITH TIME ZONE '2024-09-22T09:48:11+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00277', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-25T01:06:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T01:36:26+09:00', '【障害報告】【認証・セッション障害】パスワードポリシー衝突', '2024年8月25日01時06分26秒に、株式会社ストッククラウドのサービスVenusにおいて、利用者増による応答遅延が発生しました。新パスワードポリシーにより、既存API認証が失敗する事象が観測され、影響範囲は全テナントに波及しました。エラーコードはAUTH-05-00277であり、発生は定例リリース直後ということが確認されています。運用部の運用 一郎がこの事象を発見し、01時41分26秒に検知しました。この事象は、レガシー認証方式の残存が原因であると考えられます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00277', 'INC-2024-00277', '本事象に関する調査を行った結果、定例リリース直後に新パスワードポリシーが導入され、その影響で既存のAPI認証が失敗したことが明らかになりました。レガシー認証方式が依然として残っていることが、認証失敗の主な要因であると推定されます。今後この問題を解決するためには、新しいパスワードポリシーに対応した認証基盤の見直しが必要です。', '本事象に関する調査を行った結果、定例リリース直後に新パスワードポリシーが導入され、その影響で既存のAPI認証が失敗したことが明らかになりました。レガシー認証方式が依然として残っていることが、認証失敗の主な要因であると推定されます。今後この問題を解決するためには、新しいパスワードポリシーに対応した認証基盤の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-26T01:36:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00410', 'INC-2024-00277', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-25T01:51:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T02:51:26+09:00', '【初動対応】【認証・セッション障害】パスワードポリシー衝突に関する初動', '初動対応として、発生した事象に関して詳細なログを収集し、影響を受けたテナントに対して通知を行いました。次に、レガシー認証方式の排除を含む、認証基盤の緊急修正作業を開始しました。この作業により、既存API認証の正常化を図るとともに、新パスワードポリシーに対応した認証の確立を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00411', 'INC-2024-00277', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-25T03:21:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T04:21:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00278', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-13T02:48:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T03:18:27+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2024年8月13日02時48分27秒、株式会社ストッククラウドのVenusにて、Cookie SameSite設定により埋込画面が認証不可となる事象が発生しました。今回の障害は定例リリース直後に発生しており、影響範囲は単一店舗に限られています。エラーコードはAUTH-06-00278で、運用部の運用 一郎が発見しました。検知は03時17分27秒に行われ、発見から29分後の出来事でした。主要な影響コンポーネントはVenus Azure AP及びセッションストアです。現在、SameSite属性変更の影響を疑い、調査を進めております。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00278', 'INC-2024-00278', '今回の事象について運用部の運用 一郎が調査に入っています。定例リリース直後に発生したため、リリース内容にCookie SameSite設定の変更が含まれているか詳細に確認しています。埋込画面の認証不可という症状は、SameSite属性の影響を受けている可能性が高いです。どの店舗に影響が出たのか、またその影響範囲を正確に把握するため、さらなるデータ収集を行っています。', '今回の事象について運用部の運用 一郎が調査に入っています。定例リリース直後に発生したため、リリース内容にCookie SameSite設定の変更が含まれているか詳細に確認しています。埋込画面の認証不可という症状は、SameSite属性の影響を受けている可能性が高いです。どの店舗に影響が出たのか、またその影響範囲を正確に把握するため、さらなるデータ収集を行っています。', TIMESTAMP WITH TIME ZONE '2024-08-14T03:18:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00412', 'INC-2024-00278', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-13T03:33:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T04:33:27+09:00', '【初期対応】【CLU-08】Cookie SameSite拒否', '運用 一郎です。Cookie SameSite設定に起因する認証不可の事象を確認しました。影響を受けている店舗を特定し、リリース内容を再確認する必要があります。依然としてSameSite属性の変更がこの問題を引き起こしているかもしれないため、早急に修正対応を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00290', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-14T12:11:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T12:41:45+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2024年8月14日12時11分45秒に、株式会社ストッククラウドのVenusサービスにおいて、在庫登録が拒否される事象が発生しました。この問題は、マスター更新後にも旧設定が適用され、在庫登録が行えないという症状が見られました。影響範囲は全テナントに波及し、特にMercury AWS APのキャッシュレイヤにおいて、定例リリース直後のキャッシュ無効化漏れが原因として疑われます。検知は、同日12時47分45秒に行われ、発見者は運用部の運用 一郎です。このキャッシュの不整合により、多くの顧客に影響が及ぶことが予想されます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00290', 'INC-2024-00290', '調査の結果、定例リリース直後に行われたマスター更新が、適切にキャッシュレイヤによって反映されていないことが確認されました。具体的には、キャッシュの無効化が漏れ、旧設定が残っているため新しい設定が利用されず、在庫登録が失敗していました。この事象は、全テナントに影響を及ぼすため、早急な改善策が求められます。', '調査の結果、定例リリース直後に行われたマスター更新が、適切にキャッシュレイヤによって反映されていないことが確認されました。具体的には、キャッシュの無効化が漏れ、旧設定が残っているため新しい設定が利用されず、在庫登録が失敗していました。この事象は、全テナントに影響を及ぼすため、早急な改善策が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-15T12:41:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00427', 'INC-2024-00290', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-14T12:56:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T13:56:45+09:00', '【対応ログ】【在庫マスター設定障害】初期対応', '初回の対応として、運用部は直ちにキャッシュレイヤの無効化作業を実施しました。また、関連ドキュメントを確認し、定例リリース後のキャッシュ管理についての手順を見直しました。問題の根本原因を明確にするために、技術チームと連携を取り、迅速な対応を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00291', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-09-01T14:36:08+09:00', TIMESTAMP WITH TIME ZONE '2024-09-01T15:06:08+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2024年9月1日14時36分08秒、株式会社ストッククラウドのMercuryサービスにおいて、運用部の運用 一郎がVenus Azure APに関連する監視・可用性障害を発見しました。大規模セール開始直前に同一アラートが短時間に数百件発報し、運用部門に影響を及ぼしています。これにより、運用部はアラート疲労に陥り、適切な対応が困難な状況となりました。推定原因として、アラート抑制ルールの未設定が挙げられます。エラーコードはMON-02-00291です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00291', 'INC-2024-00291', '本障害に関する調査を実施した結果、大規模セール開始直前における同一アラートの短時間発報が確認されました。運用部門においてアラート抑制ルールが未設定であったため、過剰なアラートが発生し、監視システムの効率が著しく低下したことが推察されます。今後、適切なアラート抑制ルールの設定が必要です。', '本障害に関する調査を実施した結果、大規模セール開始直前における同一アラートの短時間発報が確認されました。運用部門においてアラート抑制ルールが未設定であったため、過剰なアラートが発生し、監視システムの効率が著しく低下したことが推察されます。今後、適切なアラート抑制ルールの設定が必要です。', TIMESTAMP WITH TIME ZONE '2024-09-02T15:06:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00428', 'INC-2024-00291', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-01T15:21:08+09:00', TIMESTAMP WITH TIME ZONE '2024-09-01T16:21:08+09:00', '【初期対応】アラート疲労に対する暫定措置', '運用部は直ちに状況を確認し、影響を受けているアラートの抑制を実施しました。また、発報されたアラートの内容を精査し、重要度に応じた対応を行う方針を決定しました。今後はアラート抑制ルールの設定を優先し、同様の事態が再発しないように努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00294', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-02T09:34:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T10:34:29+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '・発生日時: 2024-08-02T09:34:29+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00294', 'INC-2024-00294', '顧客拠点NWにおいて、代理サーバー経由でのアクセス時に502エラーが発生しました。この問題の原因として、プロキシの上流タイムアウト設定が過短である可能性が高いと考えられます。影響範囲は単一店舗に限定されており、迅速な対応が求められます。', '顧客拠点NWにおいて、代理サーバー経由でのアクセス時に502エラーが発生しました。この問題の原因として、プロキシの上流タイムアウト設定が過短である可能性が高いと考えられます。影響範囲は単一店舗に限定されており、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-03T10:34:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00431', 'INC-2024-00294', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-02T10:49:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T11:49:29+09:00', '【初期対応】【顧客ネットワーク障害】代理サーバー502', '本インシデントに対する初期対応を実施しました。代理サーバー経由での502エラーについて、プロキシ設定の確認と修正を行いました。また、該当顧客に対して障害の内容と進捗を報告し、状況の改善を図るためのフォローアップも行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00298', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-29T10:19:36+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T10:49:36+09:00', '【障害報告】【CLU-09】CDCイベント欠損', '2024年8月29日10時19分36秒に発生したインシデントでは、CDCイベント欠損により下流倉庫が未更新となりました。これは、データ移行バッチ実行中に発生した問題であり、影響範囲はバッチ処理のみでオンラインには影響ありません。CDCコネクタのオフセット巻戻しが推定原因と考えられます。エラーコードはSYNC-03-00298です。運用部の運用 一郎が発見し、2024年8月29日10時31分36秒に検知しました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00298', 'INC-2024-00298', '調査の結果、CDCイベントが欠損していることが確認されました。CDCコネクタのオフセットが巻き戻されている可能性が高く、これにより下流倉庫が更新されない事象が発生しました。現在、影響の及ぶバッチ処理の詳細な分析を行い、必要な修正を検討しています。引き続き、倉庫のデータ同期・整合性を確保するための対策を進めてまいります。', '調査の結果、CDCイベントが欠損していることが確認されました。CDCコネクタのオフセットが巻き戻されている可能性が高く、これにより下流倉庫が更新されない事象が発生しました。現在、影響の及ぶバッチ処理の詳細な分析を行い、必要な修正を検討しています。引き続き、倉庫のデータ同期・整合性を確保するための対策を進めてまいります。', TIMESTAMP WITH TIME ZONE '2024-08-30T10:49:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00436', 'INC-2024-00298', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-29T11:04:36+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T12:04:36+09:00', '【初期対応】【CLU-09】CDCイベント欠損への初期対応', 'インシデント発生後、運用部の運用 一郎が直ちに初期対応を開始しました。CDCイベントの欠損の原因としてCDCコネクタのオフセット巻戻しが疑われ、まずは影響を受けたバッチ処理を一時停止しました。次に、データ移行バッチの設定を確認し、必要な修正および再実行の準備を進めました。引き続き、状況を監視し、詳細な原因分析を実施します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00437', 'INC-2024-00298', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-29T12:34:36+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T13:34:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00304', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-28T19:05:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T19:35:15+09:00', '【障害報告】【データ同期・整合性障害】読取レプリカ遅延', '2024年8月28日、19時05分頃、株式会社ストッククラウドのVenusサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。読取レプリカ遅延により、在庫照会が古い値を表示しています。この事象は、大規模セール開始直前に発生し、特定リージョンのユーザーに影響を及ぼしています。19時32分に検知され、レプリケーション遅延の監視閾値を超過した疑いがあります。影響コンポーネントはMercury AWS AP（ゾーンB）の読取専用レプリカです。ユーザーからの問い合わせが増加しており、適切な対策が求められます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00304', 'INC-2024-00304', '影響範囲として、特定リージョンのユーザーが在庫照会で古い値を受け取る事象を確認しました。レプリケーション遅延の監視閾値を超過していることが原因と考えられます。現在、システムの監視データを精査し、設定ミスがどのように発生したのかを調査中です。問題の根本原因を特定し、修正手順を早急に策定する必要があります。', '影響範囲として、特定リージョンのユーザーが在庫照会で古い値を受け取る事象を確認しました。レプリケーション遅延の監視閾値を超過していることが原因と考えられます。現在、システムの監視データを精査し、設定ミスがどのように発生したのかを調査中です。問題の根本原因を特定し、修正手順を早急に策定する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-29T19:35:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00445', 'INC-2024-00304', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T19:50:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T20:50:15+09:00', '【初期対応】【データ同期・整合性障害】読取レプリカ遅延', '初期対応として、影響を受けている読取専用レプリカの再起動を実施しました。この手順により、レプリケーション遅延が解消されることを期待しています。再起動後、在庫照会の値が更新されるかどうかを確認しており、今後の対応方針についても協議する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00446', 'INC-2024-00304', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-28T21:20:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-28T22:20:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00314', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-18T19:05:03+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T19:35:03+09:00', '【障害報告】【CLU-09】CDCイベント欠損', '発生日時: 2024-08-18T19:05:03+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00314', 'INC-2024-00314', '本事象は、2024-08-18T19:05:03+09:00に発生し、30分後の2024-08-18T19:35:03+09:00に検知されました。 CDCイベントの欠損により下流倉庫が未更新であることが確認されました。担当者は運用部の運用 一郎です。 CDCコネクタのオフセット巻戻しが原因である可能性が高いと考えられています。', '本事象は、2024-08-18T19:05:03+09:00に発生し、30分後の2024-08-18T19:35:03+09:00に検知されました。 CDCイベントの欠損により下流倉庫が未更新であることが確認されました。担当者は運用部の運用 一郎です。 CDCコネクタのオフセット巻戻しが原因である可能性が高いと考えられています。', TIMESTAMP WITH TIME ZONE '2024-08-19T19:35:03+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00462', 'INC-2024-00314', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-18T19:50:03+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T20:50:03+09:00', '【初期対応】【CLU-09】CDCイベント欠損', '初期対応として、CDCコネクタの設定を再確認し、オフセットの状態を確認しました。 また、データ移行バッチのログを解析し、欠損したCDCイベントがどの地点で発生したかを特定し、必要に応じて再実行を検討しました。これにより、下流倉庫のデータ整合性を確保するための措置を講じています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00463', 'INC-2024-00314', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-18T21:20:03+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T22:20:03+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00322', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-05T17:41:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T18:11:19+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2024年8月5日17時41分19秒に、株式会社ストッククラウドのVenusにおいて、SKU登録APIがHTTP 500を返し在庫反映に失敗するという事象が発生しました。この障害は、定例リリース直後に発生し、影響範囲は単一店舗の登録機能のみとなっております。具体的には、単位換算係数の設定漏れが考えられており、それが原因でSKUの登録処理が正常に行われなかったものと推測されます。なお、事象が検知されたのは2024年8月5日18時13分19秒で、検知までに32分を要しました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00322', 'INC-2024-00322', '調査の結果、SKU登録APIがHTTP 500を返す原因として、単位換算係数の設定漏れが確認されました。これにより在庫登録機能が正常に動作せず、ユーザーに影響を及ぼしました。この問題は定例リリース後に発生したため、リリース内容の確認も行い、再発防止策を講じる必要があります。今後、リリース前の設定確認を徹底し、類似のインシデントを防ぐ方針です。', '調査の結果、SKU登録APIがHTTP 500を返す原因として、単位換算係数の設定漏れが確認されました。これにより在庫登録機能が正常に動作せず、ユーザーに影響を及ぼしました。この問題は定例リリース後に発生したため、リリース内容の確認も行い、再発防止策を講じる必要があります。今後、リリース前の設定確認を徹底し、類似のインシデントを防ぐ方針です。', TIMESTAMP WITH TIME ZONE '2024-08-06T18:11:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00471', 'INC-2024-00322', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-05T18:26:19+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T19:26:19+09:00', '初期対応', '初期対応として、運用部の運用 一郎が即座に障害の調査を開始し、エラーコードMST-01-00322に基づいて問題の特定を進めました。また、関連するシステムのログを確認し、発生したエラーの詳細を収集しました。今回の事象を早急に解決するため、設定漏れの修正を行い、再度SKU登録APIの動作確認を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00329', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-01T19:05:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T20:05:40+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '2024年8月1日19時05分40秒に、株式会社ストッククラウドのサービスVenusにおいて顧客側ネットワーク障害が発生しました。本障害は、特定の店舗におけるWi-Fiの認証ページでAPI通信が遮断される症状が見られました。発生契機は新規店舗追加の初日で、影響範囲は単一店舗に限定されました。推定原因としては、キャプティブポータルによるHTTPSインターセプトが考えられます。この問題により、利用者はWi-Fi接続後に必要な機能にアクセスできない状態となりました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00329', 'INC-2024-00329', '本障害に関する調査を開始しました。顧客拠点NWおよび顧客側FWについて、ログデータを確認し、キャプティブポータルの設定に異常がないかを詳細に調査しています。新規店舗追加の初日という特異な状況下で、何らかの設定ミスやトラフィックの制限がかかっている可能性があるため、関連する設定ファイル・ルールを見直し、原因を特定する方針です。', '本障害に関する調査を開始しました。顧客拠点NWおよび顧客側FWについて、ログデータを確認し、キャプティブポータルの設定に異常がないかを詳細に調査しています。新規店舗追加の初日という特異な状況下で、何らかの設定ミスやトラフィックの制限がかかっている可能性があるため、関連する設定ファイル・ルールを見直し、原因を特定する方針です。', TIMESTAMP WITH TIME ZONE '2024-08-02T20:05:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00482', 'INC-2024-00329', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-01T20:20:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T21:20:40+09:00', '【対応ログ】【顧客ネットワーク障害】Wi-Fi captive portal', '本障害に対する初期対応を実施しました。顧客拠点NWの設定を確認し、キャプティブポータルの動作状況を確認しました。HTTPSインターセプトの可能性を踏まえ、関連設定の見直しを行い、影響を受けている店舗に対して必要な対策を講じました。今後の調査結果に基づき、追加措置を検討する予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00483', 'INC-2024-00329', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-01T21:50:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T22:50:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00330', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-05T20:42:13+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T20:57:13+09:00', '【障害報告】【運用操作・権限障害】手動設定編集事故', '2024年8月5日20時42分頃、株式会社ストッククラウドの運用コンソールにおいて、設定ファイル手動編集で必須キーが欠落する事象が発生しました。この障害は、インフラメンテナンス明けに実施された設定ファイルの手動編集によるもので、サービス全体の一部機能に影響を及ぼしました。運用 一郎（運用部）がこの事象を発見し、20時53分に検知されました。この時点で、既に11分が経過しており、運用チームは直ちに対応を開始しました。手動編集された設定ファイルには、必要な必須キーが欠落しており、そのため正常なサービス提供に支障をきたしました。エラーコードは OPS-07-00330 です。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00330', 'INC-2024-00330', '調査の結果、インフラメンテナンス明けに行われた設定ファイルの手動編集時に必須キーが欠落していたことが確認されました。このミスは、運用者による手動編集の際の不注意によるものであり、設定ファイルの正確性が欠如していました。今後、このような事態を防ぐため、手動編集を行う場合の確認手順を見直し、品質管理を強化する必要があります。', '調査の結果、インフラメンテナンス明けに行われた設定ファイルの手動編集時に必須キーが欠落していたことが確認されました。このミスは、運用者による手動編集の際の不注意によるものであり、設定ファイルの正確性が欠如していました。今後、このような事態を防ぐため、手動編集を行う場合の確認手順を見直し、品質管理を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-06T20:57:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00484', 'INC-2024-00330', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-05T21:12:13+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T22:12:13+09:00', '初期対応', '初期対応として、運用チームは直ちに設定ファイルの修正を行い、必要な必須キーを追加しました。その後、サービスの正常な動作を確認し、影響を受けた機能の復旧を実施しました。また、運用部内でこの事象についての振り返りを行い、再発防止に向けた教育を行うことを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00337', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-03T01:30:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T02:00:46+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2024年8月3日01時30分46秒に、株式会社ストッククラウドのサービスVenusにおいて、ヘルスチェック過多でAPサーバー負荷が増加する事象が発生しました。今回は特に全テナントに影響が及び、運用部の運用 一郎が発見しました。検知までに30分を要し、02時00分46秒に問題が把握されました。発生契機はインフラメンテナンス明けであり、LBヘルスチェック間隔の過短設定が推定原因として挙げられます。この影響により、Venus Azure AP（ゾーンB）およびロードバランサにおいて、監視・可用性障害が発生している状況です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00337', 'INC-2024-00337', '調査の結果、インフラメンテナンス明けにおいてヘルスチェックの過多が確認され、APサーバーへの負荷が増加していることがわかりました。原因としては、LBのヘルスチェック間隔が過短に設定されていることが考えられ、これが全テナントに波及する形で影響を及ぼしています。今後の対策として、ヘルスチェックの設定見直しが急務です。', '調査の結果、インフラメンテナンス明けにおいてヘルスチェックの過多が確認され、APサーバーへの負荷が増加していることがわかりました。原因としては、LBのヘルスチェック間隔が過短に設定されていることが考えられ、これが全テナントに波及する形で影響を及ぼしています。今後の対策として、ヘルスチェックの設定見直しが急務です。', TIMESTAMP WITH TIME ZONE '2024-08-04T02:00:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00494', 'INC-2024-00337', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-03T02:15:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T03:15:46+09:00', '【対応ログ】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎: 2024年8月3日02時00分46秒にヘルスチェック過多によるAPサーバー負荷の増加を確認しました。全テナントに影響が出ているため、速やかにLBヘルスチェック間隔の設定を見直します。対応を急ぎます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00338', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-11-19T00:44:46+09:00', TIMESTAMP WITH TIME ZONE '2024-11-19T01:44:46+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '2024年11月19日、架空服飾店Aにおいて、顧客拠点NWに関連するネットワーク障害が発生しました。代理サーバー経由でのアクセス時に502エラーが返される事象が確認されました。この障害は、大規模セール開始直前に発生し、単一店舗に影響を及ぼしています。詳細な技術調査により、プロキシの上流タイムアウト設定が過短であることが推定されています。顧客ネットワークへの影響範囲は限定的ですが、迅速な対応が求められます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00338', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00338', 'INC-2024-00338', '発生した502エラーについて詳細に調査を行いました。プロキシサーバーの設定を確認したところ、上流タイムアウトの設定が短すぎることが原因と考えられます。この設定が適切でないため、顧客拠点NW（ゾーンB）での通信に支障をきたし、502エラーが発生しています。今後はこの設定を見直し、安定した運用を確保する必要があります。', '発生した502エラーについて詳細に調査を行いました。プロキシサーバーの設定を確認したところ、上流タイムアウトの設定が短すぎることが原因と考えられます。この設定が適切でないため、顧客拠点NW（ゾーンB）での通信に支障をきたし、502エラーが発生しています。今後はこの設定を見直し、安定した運用を確保する必要があります。', TIMESTAMP WITH TIME ZONE '2024-11-20T01:44:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00495', 'INC-2024-00338', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-11-19T01:59:46+09:00', TIMESTAMP WITH TIME ZONE '2024-11-19T02:59:46+09:00', '初期対応', '2024年11月19日、営業部の花子が障害を確認し、即座に技術部門に報告しました。初期調査により、プロキシの設定が原因と判断されました。今後の対応策を検討し、迅速に問題を解決するための手続きを進めています。影響を受けた顧客には、状況を報告し、解決までの見通しを案内する準備をしています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00496', 'INC-2024-00338', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-11-19T03:29:46+09:00', TIMESTAMP WITH TIME ZONE '2024-11-19T04:29:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00339', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-10T23:37:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T00:07:01+09:00', '【障害報告】【性能・負荷障害】コールドスタート連鎖', '2024年8月10日23時37分頃、株式会社ストッククラウドのサービスVenusにおいて、サーバーレス関数のコールドスタートが連鎖し、応答遅延が発生しました。影響範囲はサービス全体の一部機能に及び、顧客からの問い合わせもありました。発生契機は定例リリース直後であり、運用部の運用 一郎が検知したのは翌日0時16分でした。技術詳細としては、定例リリース後にコールドスタートの連鎖が確認され、これによりサービスのレスポンスが遅延している状況です。この問題のエラーコードはPRF-06-00339です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00339', 'INC-2024-00339', '調査の結果、定例リリース直後に発生したサーバーレス関数のコールドスタートが連鎖したことが原因と考えられます。今回の性能・負荷障害は、特にVenus Azure AP（Secondary）やCDNエッジに影響を及ぼしています。この連鎖は一時的なものである可能性が高いですが、根本的な対策が必要です。', '調査の結果、定例リリース直後に発生したサーバーレス関数のコールドスタートが連鎖したことが原因と考えられます。今回の性能・負荷障害は、特にVenus Azure AP（Secondary）やCDNエッジに影響を及ぼしています。この連鎖は一時的なものである可能性が高いですが、根本的な対策が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-12T00:07:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00497', 'INC-2024-00339', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-11T00:22:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T01:22:01+09:00', '【初動対応】【性能・負荷障害】コールドスタート連鎖', '運用 一郎がこの障害を初めて認識したのは発生から39分後の0時16分です。すぐに関連チームに連絡を取り、問題の影響範囲を確認すると共に、サーバーレス関数の状態を監視しました。また、エラーコードPRF-06-00339に基づき、迅速な対応が求められることを認識し、関連するメトリクスの分析を始めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00498', 'INC-2024-00339', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-11T01:52:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T02:52:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00340', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-11-24T10:33:02+09:00', TIMESTAMP WITH TIME ZONE '2024-11-24T11:03:02+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2024年11月24日10時33分02秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店A及び架空食品店Bに影響を与えるメトリクス欠損の事象が発生しました。主要メトリクス系列が15分間欠損し、運用部門において業務に支障をきたしました。原因としてメトリクスエージェントの再起動失敗が疑われ、これにより正常なデータ収集が行われませんでした。インフラメンテナンス明けの影響である可能性が高いと考えられ、監視体制の再確認が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00340', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00340', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00340', 'INC-2024-00340', '本件に関して、運用部門において詳細な調査を行いました。確認したところ、インフラメンテナンス明けにメトリクスエージェントが正常に再起動されず、その結果、主要メトリクス系列が15分間収集されない状態が続いていました。この問題は運用部門のみへの影響があり、今後の運用体制に影響を及ぼす可能性があります。', '本件に関して、運用部門において詳細な調査を行いました。確認したところ、インフラメンテナンス明けにメトリクスエージェントが正常に再起動されず、その結果、主要メトリクス系列が15分間収集されない状態が続いていました。この問題は運用部門のみへの影響があり、今後の運用体制に影響を及ぼす可能性があります。', TIMESTAMP WITH TIME ZONE '2024-11-25T11:03:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00499', 'INC-2024-00340', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-24T11:18:02+09:00', TIMESTAMP WITH TIME ZONE '2024-11-24T12:18:02+09:00', '【初動対応】【監視・可用性障害】メトリクス欠損の初動対応', '発生したメトリクス欠損に関して、運用部門の運用一郎が迅速に対応を開始しました。まずはエージェントの再起動を試み、その後、正常にデータが収集されることを確認しました。業務への影響を最小限に抑えるため、状況を上司に報告し、問題の根本原因の調査に着手しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00500', 'INC-2024-00340', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-24T12:48:02+09:00', TIMESTAMP WITH TIME ZONE '2024-11-24T13:48:02+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00348', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-01T10:36:08+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T11:06:08+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2024年8月1日10時36分に、株式会社ストッククラウドのVenusサービスにおいて、Webhook再送が嵐状になり先方で拒否される事象が発生しました。影響範囲は単一店舗のみで、エラーコードはEDI-02-00348です。この問題は定例リリース直後に発生し、運用部の運用 一郎が発見しました。検知は11時08分に行われましたが、発生から検知までに32分のタイムラグがありました。再送間隔の指数バックオフが未設定であったことが推定原因として考えられます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00348', 'INC-2024-00348', '調査の結果、Webhook再送が嵐状になる原因として、再送間隔の指数バックオフ未設定が確認されました。この設定が無いため、過剰な再送が発生し、最終的に先方で拒否される事象が引き起こされました。影響コンポーネントはMercury AWS AP（Primary）およびWebhookディスパッチャです。今後、再送設定の見直しが必須です。', '調査の結果、Webhook再送が嵐状になる原因として、再送間隔の指数バックオフ未設定が確認されました。この設定が無いため、過剰な再送が発生し、最終的に先方で拒否される事象が引き起こされました。影響コンポーネントはMercury AWS AP（Primary）およびWebhookディスパッチャです。今後、再送設定の見直しが必須です。', TIMESTAMP WITH TIME ZONE '2024-08-02T11:06:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00511', 'INC-2024-00348', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-01T11:21:08+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T12:21:08+09:00', '初動対応', '初動対応として、運用 一郎がただちにWebhookの再送設定を確認し、指数バックオフの設定を行う必要があると判断しました。また、定例リリース後の影響について、運用部内での情報共有を強化することを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00512', 'INC-2024-00348', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-01T12:51:08+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T13:51:08+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00352', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-01-16T19:41:12+09:00', TIMESTAMP WITH TIME ZONE '2024-01-16T21:41:12+09:00', '【障害報告】【CLU-07】冪等キー重複', '2024年1月16日19時41分12秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客の架空食品店Aおよび架空食品店Bの全店舗で棚卸突合失敗が発生。症状としては冪等キー重複により在庫更新がスキップされる事象が確認された。発生契機は定例リリース直後であり、影響範囲は同一顧客の全店舗となる。エラーコードはEDI-08-00352で、発見者は営業部の花子である。検知は2024年1月16日21時54分に行われ、検知までに133分を要した。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00352', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00352', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00352', 'INC-2024-00352', '発生した冪等キー重複の原因について調査を行った結果、冪等キー生成ロジックの衝突が疑われる。定例リリースによる変更が影響している可能性が高く、特にAPI連携・EDI障害が発生したことが関連していると考えられる。今後は再発防止に向けて、冪等キー生成ロジックの見直しとテスト項目の追加を検討する必要がある。', '発生した冪等キー重複の原因について調査を行った結果、冪等キー生成ロジックの衝突が疑われる。定例リリースによる変更が影響している可能性が高く、特にAPI連携・EDI障害が発生したことが関連していると考えられる。今後は再発防止に向けて、冪等キー生成ロジックの見直しとテスト項目の追加を検討する必要がある。', TIMESTAMP WITH TIME ZONE '2024-01-17T21:41:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00517', 'INC-2024-00352', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-01-16T21:56:12+09:00', TIMESTAMP WITH TIME ZONE '2024-01-16T22:56:12+09:00', '初期対応', '発見後、営業部の花子は直ちに関係部署に通知し、影響を受けた顧客店舗の在庫管理状況を確認した。在庫更新がスキップされた店舗については、手動で在庫を調整する対応を行った。また、冪等キー重複の根本原因を突き止めるため、技術部門との連携を強化し、問題の再現性を確認するためのテストを実施することとした。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00356', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-03-09T08:26:11+09:00', TIMESTAMP WITH TIME ZONE '2024-03-09T08:41:11+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2024年3月9日08時26分、株式会社ストッククラウドのサービスMercuryにおいて、運用者の作業ミスによりアクセス障害が発生しました。症状としては、PagerDuty連携が失敗し、運用部門へのオンコール通知が未達となりました。この障害は、運用コンソールに影響を及ぼし、運用部門のみが影響を受けました。初めの発見は運用部の運用 一郎によるもので、08時45分に検知され、検知までの時間は19分でした。発生契機として年末年始の稼働切替時が挙げられ、推定原因は連携APIキーの権限不足です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00356', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00356', 'INC-2024-00356', '障害が発生した2024年3月9日08時26分の時点で、運用コンソールにおいてPagerDuty連携が失敗していることが確認されました。原因としては、年末年始の稼働切替時における連携APIキーの権限不足が疑われます。この権限不足により、オンコール通知が運用部門に届かない事態が生じました。今後はAPIキーの権限を見直し、再発防止策を講じる必要があります。', '障害が発生した2024年3月9日08時26分の時点で、運用コンソールにおいてPagerDuty連携が失敗していることが確認されました。原因としては、年末年始の稼働切替時における連携APIキーの権限不足が疑われます。この権限不足により、オンコール通知が運用部門に届かない事態が生じました。今後はAPIキーの権限を見直し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-03-10T08:41:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00521', 'INC-2024-00356', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-03-09T08:56:11+09:00', TIMESTAMP WITH TIME ZONE '2024-03-09T09:56:11+09:00', '【対応ログ】【CLU-10】PagerDuty連携失敗', '2024年3月9日08時45分に障害が検知されたため、運用担当者が即座に対応を開始しました。PagerDutyの設定を確認したところ、連携APIキーの権限が不十分であることが判明しました。このため、権限を修正し、再度連携を試みることにしました。対応後、オンコール通知が正常に送信されることを確認しました。今後は、連携設定の見直しと定期的なチェックを行う方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00522', 'INC-2024-00356', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-03-09T10:26:11+09:00', TIMESTAMP WITH TIME ZONE '2024-03-09T11:26:11+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00361', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-06T11:49:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T12:04:31+09:00', '【障害報告】【運用操作・権限障害】手動設定編集事故', '2024年8月6日11時49分31秒に、株式会社ストッククラウドのVenusにおいて運用者の作業ミスによるアクセス障害が発生しました。運用コンソールにおいて、設定ファイルの手動編集で必須キーが欠落していることが確認されました。発見者は運用部の運用 一郎で、発見時刻は11時55分31秒でした。インフラメンテナンス明けにこの問題が発生し、サービス全体の一部機能に影響を及ぼしました。エラーコードはOPS-07-00361です。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00361', 'INC-2024-00361', '調査の結果、インフラメンテナンス明けに実施された設定ファイルの手動編集において、必要な必須キーが欠落していることが原因であると推定されました。運用部のスタッフによる手動編集ミスが影響を及ぼしたと考えられ、今後の作業において手動編集の注意喚起が必要です。サービス全体の影響を考慮し、影響を受けたコンポーネントは運用コンソール及び設定管理DBです。', '調査の結果、インフラメンテナンス明けに実施された設定ファイルの手動編集において、必要な必須キーが欠落していることが原因であると推定されました。運用部のスタッフによる手動編集ミスが影響を及ぼしたと考えられ、今後の作業において手動編集の注意喚起が必要です。サービス全体の影響を考慮し、影響を受けたコンポーネントは運用コンソール及び設定管理DBです。', TIMESTAMP WITH TIME ZONE '2024-08-07T12:04:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00527', 'INC-2024-00361', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T12:19:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T13:19:31+09:00', '初期対応', '初期対応として、設定ファイルの手動編集を行った担当者に事情を確認し、必須キーの修正を行いました。また、運用コンソール及び設定管理DBの状態を監視し、サービス全体の正常稼働を確認しました。再発防止策として、手動編集を行う際のチェックリストを作成し、運用部全体に周知徹底させる方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00528', 'INC-2024-00361', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T13:49:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T14:49:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00364', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-06T13:02:12+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T13:47:12+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2024年8月6日13時02分頃、株式会社ストッククラウドのVenusサービスにおいて、Mercury AWS Storageでストレージ溢れが発生しました。この事象により、PagerDuty連携が失敗し、運用部門へのオンコール通知が未達となりました。発生契機は年末年始の稼働切替時であり、連携APIキーの権限不足が推定原因とされています。検知は13時38分に行われ、約36分後の事象でした。影響範囲は運用部門のみで、エラーコードはMON-07-00364です。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00364', 'INC-2024-00364', '本インシデントにおける調査では、年末年始の稼働切替時に発生したPagerDuty連携の失敗が確認されました。原因として連携APIキーの権限不足が疑われており、これにより運用部へのオンコール通知が未達の事態が発生しました。今後はAPIキーの権限の見直しを行い、再発防止に努めます。', '本インシデントにおける調査では、年末年始の稼働切替時に発生したPagerDuty連携の失敗が確認されました。原因として連携APIキーの権限不足が疑われており、これにより運用部へのオンコール通知が未達の事態が発生しました。今後はAPIキーの権限の見直しを行い、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2024-08-07T13:47:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00532', 'INC-2024-00364', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T14:02:12+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T15:02:12+09:00', '【初動対応】【CLU-10】PagerDuty連携失敗', '初動対応として、運用部門での状況確認を行い、PagerDutyの設定を見直しました。連携APIキーの権限を確認し、必要な権限を追加することで再度連携を試みました。また、運用部門への通知が未達だった件について、直接の連絡を行い、対応状況を共有しました。今後の対応策についても検討を始めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00378', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-27T18:05:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T19:05:58+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2024年8月27日18:05、株式会社ストッククラウドのVenusサービスにおいて顧客拠点NWで特定拠点のみAPI呼び出しが失敗する障害が発生。発生契機は新規店舗追加の初日であり、影響範囲は単一店舗のみ。エラーコードはNW-02-00378で、推定原因として店舗LANのスイッチ故障が考えられる。18:52に検知され、検知までの時間は47分。営業部の花子が発見者となった。問題の影響コンポーネントには顧客拠点NW（Secondary）と顧客側FWが含まれている。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00378', 'INC-2024-00378', '障害発生から約40分後、営業部の花子がAPI呼び出し失敗の報告を受け、調査を開始。特定拠点におけるLANの状態を確認したところ、スイッチに異常が発生していることが判明した。具体的には、特定のポートが応答せず、API連携が行えない状態であった。これにより、問題の根本原因をスイッチ故障として特定した。', '障害発生から約40分後、営業部の花子がAPI呼び出し失敗の報告を受け、調査を開始。特定拠点におけるLANの状態を確認したところ、スイッチに異常が発生していることが判明した。具体的には、特定のポートが応答せず、API連携が行えない状態であった。これにより、問題の根本原因をスイッチ故障として特定した。', TIMESTAMP WITH TIME ZONE '2024-08-28T19:05:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00554', 'INC-2024-00378', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T19:20:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T20:20:58+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗', '初期対応として、まずは顧客拠点NWのLANスイッチを再起動する作業を実施。再起動後、API呼び出しの状況を確認したところ、正常に動作するようになった。顧客に対しては、APIの利用再開を案内し、今後の監視体制を強化する旨を伝えた。今後、スイッチの状態を定期的にチェックし、再発防止を図る。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00555', 'INC-2024-00378', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T20:50:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T21:50:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00385', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-21T19:15:25+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T21:15:25+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2024年8月21日19時15分に、月末棚卸の開始時に発生した整合性チェックに関して、顧客店舗POSで不一致アラートが多発しました。これにより、夜間整合性チェックが正常に機能せず、データの整合性に影響が出る可能性がありました。営業部の花子がこの問題を発見し、21時16分に検知した時点で121分が経過していました。影響はバッチ処理に限られており、オンラインサービスには影響を及ぼしていないことが確認されています。本問題の推定原因として、整合性チェック基準の変更が未反映であることが考えられます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00385', 'INC-2024-00385', '調査の結果、月末棚卸の開始時に実施される夜間整合性チェックでの不一致アラート多発の原因は、整合性チェック基準の変更が未反映であったことが判明しました。この問題は、顧客店舗POSにおける整合性チェックジョブに関連しており、影響範囲はバッチ処理に限定されております。今後、整合性チェック基準の変更は迅速に反映されるよう改善策を講じる必要があります。', '調査の結果、月末棚卸の開始時に実施される夜間整合性チェックでの不一致アラート多発の原因は、整合性チェック基準の変更が未反映であったことが判明しました。この問題は、顧客店舗POSにおける整合性チェックジョブに関連しており、影響範囲はバッチ処理に限定されております。今後、整合性チェック基準の変更は迅速に反映されるよう改善策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-22T21:15:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00565', 'INC-2024-00385', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-21T21:30:25+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T22:30:25+09:00', '初期対応', '初期対応として、整合性チェック基準の変更内容を確認し、適切に反映するための手続きを開始しました。また、影響を受けたデータセットの確認及び修正を行い、再度整合性チェックを実施する計画を立てました。問題が解決した後、顧客への報告を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00389', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-06-01T12:51:47+09:00', TIMESTAMP WITH TIME ZONE '2024-06-01T13:51:47+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '・発生日時: 2024年6月1日 12:51:47
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00389', 'INC-2024-00389', '今回の顧客ネットワーク障害は、代理サーバーを通じてのアクセスで502エラーが発生したものである。大規模セールの開始直前に発生しており、影響範囲は単一店舗に限られている。調査の結果、プロキシの上流タイムアウト設定が過短であることが原因として考えられる。さらに、顧客拠点NW及び顧客側FWに関連する問題が存在する可能性がある。', '今回の顧客ネットワーク障害は、代理サーバーを通じてのアクセスで502エラーが発生したものである。大規模セールの開始直前に発生しており、影響範囲は単一店舗に限られている。調査の結果、プロキシの上流タイムアウト設定が過短であることが原因として考えられる。さらに、顧客拠点NW及び顧客側FWに関連する問題が存在する可能性がある。', TIMESTAMP WITH TIME ZONE '2024-06-02T13:51:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00571', 'INC-2024-00389', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-06-01T14:06:47+09:00', TIMESTAMP WITH TIME ZONE '2024-06-01T15:06:47+09:00', '【対応】【顧客ネットワーク障害】代理サーバー502', '当社はこの顧客ネットワーク障害に対し、迅速に対応を開始した。まず、プロキシ設定を確認し、上流タイムアウト設定を適切な値に変更した。これにより、502エラーの発生を防止するための第一歩を踏み出した。今後、必要に応じて追加の調整を行い、障害の再発防止に努める。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00394', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-06-14T16:04:22+09:00', TIMESTAMP WITH TIME ZONE '2024-06-14T17:04:22+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年6月14日16時04分22秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bおよび架空食品店Aの顧客拠点NWにおいて顕在化した障害が発生しました。発生後、DNS解決は成功したものの、TLS握手の段階で接続が切断されました。この問題はインフラメンテナンス明けに発生し、全店舗に影響を及ぼしました。現在、原因としてプロキシ証明書の期限切れが疑われており、一刻も早い対策が求められています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00394', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00394', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00394', 'INC-2024-00394', '発生した顧客ネットワーク障害に関する調査を実施しました。DNS解決は正常に行われたものの、TLS握手段階で接続が切断される事象が確認されました。全店舗に影響を及ぼしたこの問題の根本原因として、プロキシ証明書の期限切れが有力視されています。今後は、この証明書の管理方法に改善を施す必要があります。', '発生した顧客ネットワーク障害に関する調査を実施しました。DNS解決は正常に行われたものの、TLS握手段階で接続が切断される事象が確認されました。全店舗に影響を及ぼしたこの問題の根本原因として、プロキシ証明書の期限切れが有力視されています。今後は、この証明書の管理方法に改善を施す必要があります。', TIMESTAMP WITH TIME ZONE '2024-06-15T17:04:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00578', 'INC-2024-00394', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-06-14T17:19:22+09:00', TIMESTAMP WITH TIME ZONE '2024-06-14T18:19:22+09:00', '初期対応', '障害発生後、状況を確認するために即座に影響を受けた顧客に連絡を取りました。架空食品店Bと架空食品店Aに対し、障害の概要を説明し、解決に向けた対応を検討している旨を伝えました。プロキシ証明書の確認を早急に行うことを約束しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00400', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-19T00:18:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T01:03:16+09:00', '【障害報告】【ストレージ・容量障害】バックアップ連続失敗', '2024年8月19日00時18分16秒に、株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Bに対しストレージ溢れの問題が発生しました。バックアップジョブが連続して失敗するという症状が確認されました。発見者である運用部の運用 一郎は、発生した問題がMercury AWS Storageに関連していることを特定しました。エラーコードはSTR-03-00400です。推定される原因として、スナップショットの蓄積が挙げられます。この事象は、年末年始の稼働切替時に発生し、影響範囲はバッチ処理のみでオンラインには影響しません。技術的には、バックアップ領域に対するストレージ・容量の問題が原因と考えられます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00400', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00400', 'INC-2024-00400', 'このインシデントに対する調査は、運用部の運用 一郎によって実施されました。調査の結果、年末年始の稼働切替時におけるスナップショットの蓄積が、バックアップジョブの連続失敗を引き起こしている可能性が高いことが分かりました。今後の対応として、スナップショット管理の見直しを行い、大量のスナップショットが蓄積しないような対策が必要です。また、バックアッププロセスの最適化も検討します。', 'このインシデントに対する調査は、運用部の運用 一郎によって実施されました。調査の結果、年末年始の稼働切替時におけるスナップショットの蓄積が、バックアップジョブの連続失敗を引き起こしている可能性が高いことが分かりました。今後の対応として、スナップショット管理の見直しを行い、大量のスナップショットが蓄積しないような対策が必要です。また、バックアッププロセスの最適化も検討します。', TIMESTAMP WITH TIME ZONE '2024-08-20T01:03:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00585', 'INC-2024-00400', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T01:18:16+09:00', NULL, '【初期対応】【ストレージ・容量障害】バックアップ連続失敗に関する初期対応', 'インシデント発生後、運用部の運用 一郎は即座に対応に着手しました。まず、バックアップジョブの状態を確認し、失敗したジョブの詳細を収集しました。次に、スナップショットの現状を把握するためにストレージの利用状況を監視しました。影響範囲がバッチ処理に限られていることを把握したため、他のシステムへの影響は少ないと判断しました。その後、スナップショットの蓄積を防ぐための初動として、不要なスナップショットの削除を行い、バックアップジョブの再起動を試みました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00401', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-22T22:27:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T23:27:47+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2024年8月22日22時27分47秒に、株式会社ストッククラウドの顧客である店舗において、ISP側BGP経路障害が発生しました。この障害により、複数拠点が同時不通となり、顧客ネットワークに深刻な影響が及びました。発生契機はインフラメンテナンス明けであり、発見者は営業部の花子です。23時21分47秒に検知され、54分後には影響範囲が確認されました。影響を受けたのは同一顧客の全店舗であり、顧客拠点のネットワークが主に影響を受けています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00401', 'INC-2024-00401', '調査の結果、ISP側のBGP経路障害が原因と考えられます。複数の拠点が同時に不通となっていることから、ISPのインフラに問題が生じている可能性が高いです。技術詳細としては、インフラメンテナンス明けでのBGP経路の安定性が損なわれたことが影響しています。引き続きISPと連携し、詳細な原因究明を進めます。', '調査の結果、ISP側のBGP経路障害が原因と考えられます。複数の拠点が同時に不通となっていることから、ISPのインフラに問題が生じている可能性が高いです。技術詳細としては、インフラメンテナンス明けでのBGP経路の安定性が損なわれたことが影響しています。引き続きISPと連携し、詳細な原因究明を進めます。', TIMESTAMP WITH TIME ZONE '2024-08-23T23:27:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00587', 'INC-2024-00401', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-22T23:42:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T00:42:47+09:00', '【対応ログ】【顧客ネットワーク障害】BGP経路障害波及', 'ISPに連絡を取り、障害の詳細状況を確認しました。現在、ISP側でのBGP経路の復旧作業が進行中です。顧客には一次的な状況説明を行い、復旧の見込みを伝えました。問題が解決次第、再度報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00404', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-05-03T15:48:09+09:00', TIMESTAMP WITH TIME ZONE '2024-05-03T17:48:09+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2024年5月3日15時48分に、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSにて棚卸突合失敗が発生しました。症状として、POS連携の売上が翌営業日まで在庫に反映されない状況が確認されました。影響範囲は単一店舗のみで、エラーコードはINV-02-00404です。発生契機は年末年始の稼働切替時です。この問題は2024年5月3日18時01分に検知されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00404', 'INC-2024-00404', '調査の結果、年末年始の稼働切替時に発生した前日締め処理の二重実行が原因である可能性が高いと考えられます。POS連携ハブと顧客店舗POS間の連携において、既存のデータが更新されず、売上遅延が生じたと推測されます。', '調査の結果、年末年始の稼働切替時に発生した前日締め処理の二重実行が原因である可能性が高いと考えられます。POS連携ハブと顧客店舗POS間の連携において、既存のデータが更新されず、売上遅延が生じたと推測されます。', TIMESTAMP WITH TIME ZONE '2024-05-04T17:48:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00592', 'INC-2024-00404', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-05-03T18:03:09+09:00', TIMESTAMP WITH TIME ZONE '2024-05-03T19:03:09+09:00', '【初期対応】【棚卸・POS突合障害】POS売上遅延反映', '初期対応として、影響を受けた店舗に対して、POSシステムの再起動及び前日締め処理の確認を実施しました。さらに、顧客店舗POSのログを確認し、問題の再発防止策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00593', 'INC-2024-00404', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-05-03T19:33:09+09:00', TIMESTAMP WITH TIME ZONE '2024-05-03T20:33:09+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00411', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-09T13:47:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T14:02:51+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2024年8月9日13時47分51秒、株式会社ストッククラウドの運用コンソールにて同一アラートが短時間に数百件発報する現象が発生しました。このアラート疲労は、大規模セール開始直前というタイミングで顕在化し、運用部門に限定して影響を及ぼしました。14時10分51秒に監視システムがこの異常を検知し、23分の間に多くのエラーが通知されました。推定原因としては、アラート抑制ルールの未設定が考えられ、これにより不要なアラートが大量に発生し、運用部門の業務に混乱を招く結果となりました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00411', 'INC-2024-00411', '調査の結果、運用コンソールのアラート抑制ルールが未設定であったことが確認されました。このため、同一アラートが大規模セール開始前に数百件発報し、運用部門においてアラート疲労を引き起こしました。迅速に設定を行うことで、今後の同様の事象を防ぐための対策が必要です。', '調査の結果、運用コンソールのアラート抑制ルールが未設定であったことが確認されました。このため、同一アラートが大規模セール開始前に数百件発報し、運用部門においてアラート疲労を引き起こしました。迅速に設定を行うことで、今後の同様の事象を防ぐための対策が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-10T14:02:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00601', 'INC-2024-00411', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-09T14:17:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T15:17:51+09:00', '【対応】アラート疲労の初期対応', '初期対応として、運用部門は発報されたアラートを一旦確認し、重要度に応じて優先順位を付けました。続いて、アラート抑制ルールの設定を行い、不要なアラートの発生を防ぐための作業を開始しました。また、影響を受けた運用部門に対しては、必要な情報を共有し、業務の継続を支援します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00416', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-23T22:19:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T22:34:20+09:00', '【障害報告】【認証・セッション障害】リフレッシュトークン再利用', '2024年8月23日22時19分20秒に、株式会社ストッククラウドのサービスVenusにおいて、リフレッシュトークン再利用が検知され、全端末がログアウトしました。この問題は運用コンソールに関連しており、影響範囲は同一顧客の全店舗に及びます。発生契機としては、年末年始の稼働切替時を挙げることができます。技術的にはリフレッシュトークンのローテーションに不備があり、セッションストアに影響を与えました。このため、ユーザーは再認証を求められ、業務の継続に障害が生じました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00416', 'INC-2024-00416', '本障害の調査を進めた結果、トークンローテーション実装に不備が発見されました。これにより、リフレッシュトークン再利用が発生し、全端末のログアウトを引き起こしました。詳細な分析を行ったところ、年末年始の稼働切替時におけるトークン管理の不備が主な原因であることが確認されました。今後はこのような事象を防ぐため、トークン管理システムの見直しとテストを強化する必要があります。', '本障害の調査を進めた結果、トークンローテーション実装に不備が発見されました。これにより、リフレッシュトークン再利用が発生し、全端末のログアウトを引き起こしました。詳細な分析を行ったところ、年末年始の稼働切替時におけるトークン管理の不備が主な原因であることが確認されました。今後はこのような事象を防ぐため、トークン管理システムの見直しとテストを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-24T22:34:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00607', 'INC-2024-00416', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-23T22:49:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T23:49:20+09:00', '初動対応', '初動対応として、2024年8月23日22時25分20秒に運用部の運用 一郎が障害を検知しました。直ちに、リフレッシュトークン再利用の原因究明とユーザーへの通知が行われました。また、運用コンソールのアクセスログを確認し、影響を受けたユーザーに対して個別に連絡を行いました。今後の対応策として、トークン管理に対する教育とシステムの改善を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00428', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-21T01:32:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T02:17:06+09:00', '【障害報告】【ストレージ・容量障害】インデックス再構築膨張', '2024年8月21日01時32分に株式会社ストッククラウドのVenusサービスにおいて、Mercury AWS Storageでインデックス再構築中に一時領域が枯渇するという障害が発生しました。このインシデントは、インフラメンテナンス明けにおける一時領域のサイズ見積不足が原因と考えられています。障害が発生した際の影響範囲は特定リージョンのユーザーに限られており、エラーコードはSTR-07-00428です。発見者は運用部の運用 一郎であり、障害の検知はその41分後の02時13分に行われました。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00428', 'INC-2024-00428', 'インフラメンテナンス明けに発生したこの障害について、調査を行った結果、インデックス再構築中に一時領域が枯渇したことが確認されました。再構築に必要な一時領域のサイズ見積が不足していたことが主な原因であると考えられます。今後の対策として、再構築用一時領域のサイズ見積を見直し、必要容量に対する理解を深める必要があります。', 'インフラメンテナンス明けに発生したこの障害について、調査を行った結果、インデックス再構築中に一時領域が枯渇したことが確認されました。再構築に必要な一時領域のサイズ見積が不足していたことが主な原因であると考えられます。今後の対策として、再構築用一時領域のサイズ見積を見直し、必要容量に対する理解を深める必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-22T02:17:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00627', 'INC-2024-00428', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-21T02:32:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T03:32:06+09:00', '【初期対応】', '障害発生直後に運用部よりインフラチームへの通知を行い、即座に状況確認を実施しました。インフラチームは、再構築プロセスを一時停止し、必要な一時領域を追加する手順を進めました。影響を受けたユーザーに対しては状況説明を行い、問題解決に向けた対応を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00628', 'INC-2024-00428', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-21T04:02:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T05:02:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00430', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-02-18T02:17:23+09:00', TIMESTAMP WITH TIME ZONE '2024-02-18T02:32:23+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2024年2月18日2時17分23秒、株式会社ストッククラウドの運用コンソールにおいて、架空食品店Aに影響を及ぼす運用者の作業ミスによるアクセス障害が発生しました。症状はヘルスチェック過多でAPサーバーの負荷が増加し、全テナントに波及しました。発見者の運用 一郎が問題を発見したのは、発生から21分後の2時38分23秒でした。インフラメンテナンス明けの設定変更により、LBヘルスチェック間隔が過短に設定されていたことが推定されています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00430', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00430', 'INC-2024-00430', 'インフラメンテナンス明けにおいて、運用コンソールでのヘルスチェック過多が確認されました。原因としてLBヘルスチェック間隔の過短設定が疑われ、これによりAPサーバーの負荷が増加しました。全テナントが影響を受ける事態となりました。今後の監視体制を強化し、同様の障害を未然に防ぐための対策が求められます。', 'インフラメンテナンス明けにおいて、運用コンソールでのヘルスチェック過多が確認されました。原因としてLBヘルスチェック間隔の過短設定が疑われ、これによりAPサーバーの負荷が増加しました。全テナントが影響を受ける事態となりました。今後の監視体制を強化し、同様の障害を未然に防ぐための対策が求められます。', TIMESTAMP WITH TIME ZONE '2024-02-19T02:32:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00630', 'INC-2024-00430', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-18T02:47:23+09:00', TIMESTAMP WITH TIME ZONE '2024-02-18T03:47:23+09:00', '【対応ログ】【監視・可用性障害】初期対応', '運用 一郎: 02:17に障害発生、ヘルスチェック過多でAPサーバーの負荷が増加中。全テナント影響。02:38に問題を確認、迅速に調査に着手。エラーコードMON-06-00430を記録。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00631', 'INC-2024-00430', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-18T04:17:23+09:00', TIMESTAMP WITH TIME ZONE '2024-02-18T05:17:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00439', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-15T01:47:10+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T02:02:10+09:00', '【障害報告】【運用操作・権限障害】監視画面真っ白', '・発生日時: 2024-08-15 01:47:10
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00439', 'INC-2024-00439', '運用コンソールにおいて、監視ダッシュボードが真っ白でメトリクスが表示されない事象が発生しました。定例リリース直後にこの障害が検知されました。原因として、グラフクエリの時間範囲パラメータの誤設定が疑われます。運用部門における影響が確認されており、迅速な対応が必要です。', '運用コンソールにおいて、監視ダッシュボードが真っ白でメトリクスが表示されない事象が発生しました。定例リリース直後にこの障害が検知されました。原因として、グラフクエリの時間範囲パラメータの誤設定が疑われます。運用部門における影響が確認されており、迅速な対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-16T02:02:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00645', 'INC-2024-00439', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-15T02:17:10+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T03:17:10+09:00', '初期対応', '障害の発生に対し、運用部門は即座に監視ダッシュボードの設定確認を行いました。グラフクエリの時間範囲パラメータの誤設定が原因であることが判明し、修正作業を開始しました。影響を受けた運用部門に対して状況を報告し、対応の進捗を共有しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00646', 'INC-2024-00439', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-15T03:47:10+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T04:47:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00442', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-25T04:55:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T05:55:46+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月25日04時55分46秒に、株式会社ストッククラウドのサービスVenusにおいて顧客側ネットワーク障害が発生しました。症状としてSD-WANが劣化回線を選択し、遅延が増大しました。本障害は、大規模セール開始直前に発生し、影響範囲は同一顧客の全店舗に及びました。発見者は営業部の花子で、発見は05時53分46秒でした。推定原因はSD-WANポリシーの閾値設定誤りであり、これにより顧客拠点ネットワーク（ゾーンB）の拠点VPNゲートウェイに影響を及ぼしました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00442', 'INC-2024-00442', '本件に関する調査を行った結果、SD-WANが劣化回線を選択した原因はポリシーの設定ミスに起因していることが判明しました。遅延の増大が確認される中、SD-WANの経路選択に関する設定が適切でない状況でした。今後は、SD-WANポリシーの見直しを行い、閾値設定を再評価する必要があります。特に、経路選択のロジックを精査し、障害の再発防止策を講じることが求められます。', '本件に関する調査を行った結果、SD-WANが劣化回線を選択した原因はポリシーの設定ミスに起因していることが判明しました。遅延の増大が確認される中、SD-WANの経路選択に関する設定が適切でない状況でした。今後は、SD-WANポリシーの見直しを行い、閾値設定を再評価する必要があります。特に、経路選択のロジックを精査し、障害の再発防止策を講じることが求められます。', TIMESTAMP WITH TIME ZONE '2024-08-26T05:55:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00651', 'INC-2024-00442', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-25T06:10:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T07:10:46+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月25日04時55分46秒に発生した顧客側ネットワーク障害に関して、初期対応を実施しました。問題が発生してから約58分後に確認された内容は、SD-WANが劣化回線を選択しているために遅延が発生していることであり、即時に技術チームにエスカレーションしました。技術チームは、SD-WANポリシーの設定を確認し、問題の原因を特定するための調査を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00652', 'INC-2024-00442', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-25T07:40:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T08:40:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00448', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-06T20:14:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T20:44:58+09:00', '【障害報告】【CLU-07】冪等キー重複', '株式会社ストッククラウドのVenusサービスにおいて、2024年8月6日20時14分58秒に、冪等キー重複が発生しました。この障害により、在庫更新がスキップされる事象が確認されました。発生は、定例リリース直後であり、同一顧客の全店舗に影響を及ぼしています。エラーコードはEDI-08-00448です。発見者は運用部の運用 一郎です。さらに、影響コンポーネントとしてMercury AWS AP（ゾーンA）の在庫登録APIが関与していると考えられます。現在、冪等キー生成ロジックの衝突を推定原因としています。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00448', 'INC-2024-00448', '今回の冪等キー重複の障害は、定例リリース直後に発生したことから、リリースによる冪等キー生成ロジックの衝突が疑われます。調査を進める中で、同一顧客の全店舗において在庫更新がスキップされる事象が多数確認されています。API連携・EDIの観点からも、今後の対応策を検討する必要があります。', '今回の冪等キー重複の障害は、定例リリース直後に発生したことから、リリースによる冪等キー生成ロジックの衝突が疑われます。調査を進める中で、同一顧客の全店舗において在庫更新がスキップされる事象が多数確認されています。API連携・EDIの観点からも、今後の対応策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-07T20:44:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00660', 'INC-2024-00448', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T20:59:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T21:59:58+09:00', '【初期対応】【CLU-07】冪等キー重複への初期対応', '初期対応として、冪等キー生成ロジックの確認と修正を行いました。また、在庫更新のスキップが発生した店舗について、手動での在庫登録を実施しました。運用部門は、冪等キーの重複が再発しないよう、リリース前後のチェック体制を強化する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00661', 'INC-2024-00448', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T22:29:58+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T23:29:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00449', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-07-19T14:05:54+09:00', TIMESTAMP WITH TIME ZONE '2024-07-19T15:05:54+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '2024年7月19日14時05分54秒に、株式会社ストッククラウドの顧客である架空食品店Aにおいて、顧客拠点NWに関連するネットワーク障害が発生しました。本障害は、店舗Wi-Fiの認証ページでAPI通信が遮断される事象です。発生の契機は、新規店舗追加の初日であり、影響範囲は単一店舗のみとなっています。推定される原因は、キャプティブポータルによるHTTPSインターセプトであると考えられます。この影響により、顧客側FWへの影響も懸念されております。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00449', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00449', 'INC-2024-00449', '調査の結果、架空食品店Aの店舗Wi-Fiにおいて、API通信が遮断される問題が確認されました。キャプティブポータルによるHTTPSインターセプトが原因と推測され、これは新規店舗追加に伴い設定されたネットワーク機器によるものと考えられます。現在、詳細な技術分析を進めており、早急な解決策の検討を行っています。', '調査の結果、架空食品店Aの店舗Wi-Fiにおいて、API通信が遮断される問題が確認されました。キャプティブポータルによるHTTPSインターセプトが原因と推測され、これは新規店舗追加に伴い設定されたネットワーク機器によるものと考えられます。現在、詳細な技術分析を進めており、早急な解決策の検討を行っています。', TIMESTAMP WITH TIME ZONE '2024-07-20T15:05:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00662', 'INC-2024-00449', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-07-19T15:20:54+09:00', TIMESTAMP WITH TIME ZONE '2024-07-19T16:20:54+09:00', '初期対応', '初期対応として、架空食品店Aの店舗Wi-Fiに関する設定を見直し、キャプティブポータルの挙動を確認する作業を開始しました。また、影響を受けた顧客には、状況説明と今後の対策について連絡を行い、さらなる情報提供を的確に行う予定です。この問題について、迅速な解決を図ってまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00663', 'INC-2024-00449', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-07-19T16:50:54+09:00', TIMESTAMP WITH TIME ZONE '2024-07-19T17:50:54+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00456', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-27T19:13:00+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T20:13:00+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2024年8月27日19時13分に発生した顧客側ネットワーク障害について報告します。特定の拠点においてAPI呼び出しが失敗する事象が確認されました。この障害の影響範囲は単一店舗に限定され、顧客拠点NWおよび顧客側FWに影響を及ぼしています。推定される原因としては、店舗LANのスイッチ故障が考えられます。なお、この障害は新規店舗追加の初日に発生したことも特徴的です。2024年8月27日20時01分に検知され、約48分間の無通信状態が続きました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00456', 'INC-2024-00456', '調査を開始した結果、特定拠点のみでAPI呼び出しが失敗していることが確認されました。店舗LANのスイッチの状態を確認したところ、故障が疑われる状況が見受けられました。この状態がAPI呼び出しの障害の原因である可能性が高いと判断しています。引き続き、スイッチの修理を進める予定です。', '調査を開始した結果、特定拠点のみでAPI呼び出しが失敗していることが確認されました。店舗LANのスイッチの状態を確認したところ、故障が疑われる状況が見受けられました。この状態がAPI呼び出しの障害の原因である可能性が高いと判断しています。引き続き、スイッチの修理を進める予定です。', TIMESTAMP WITH TIME ZONE '2024-08-28T20:13:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00672', 'INC-2024-00456', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T20:28:00+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T21:28:00+09:00', '【対応ログ】【顧客ネットワーク障害】拠点限定API失敗', '2024年8月27日20時05分、営業部の花子がこの障害について確認し、顧客に状況を報告しました。顧客拠点NWの状態を監視し、スイッチの修理に向けて手配を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00673', 'INC-2024-00456', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T21:58:00+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T22:58:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00464', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-30T14:50:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T15:05:27+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2024年8月30日14時50分27分に、株式会社ストッククラウドの運用コンソールにおいて、死活監視が正常系をDOWNと誤検知する事象が発生しました。本事象は定例リリース直後に発覚し、運用部門にのみ影響を及ぼしました。検知は2024年8月30日14時59分27分で、発覚から9分後のことでした。死活監視の誤検知により、運用部門では正常に稼働しているサービスがダウンしていると報告され、混乱を招きました。エラーコードはMON-01-00464で、原因として監視プローブのUser-Agentブロックが疑われています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00464', 'INC-2024-00464', '本事象の調査を行った結果、定例リリース直後に死活監視が正常系をDOWNと誤検知したことが確認されました。監視プローブのUser-Agentがブロックされていたことが主な原因として特定されました。この影響により、運用部門では誤ったサービスダウンの情報が流れ、業務に影響を及ぼす結果となりました。', '本事象の調査を行った結果、定例リリース直後に死活監視が正常系をDOWNと誤検知したことが確認されました。監視プローブのUser-Agentがブロックされていたことが主な原因として特定されました。この影響により、運用部門では誤ったサービスダウンの情報が流れ、業務に影響を及ぼす結果となりました。', TIMESTAMP WITH TIME ZONE '2024-08-31T15:05:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00687', 'INC-2024-00464', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-30T15:20:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T16:20:27+09:00', '【初期対応】【監視・可用性障害】死活監視誤検知', '初期対応として、監視プローブの設定を確認し、User-Agentブロックを解除する手続きを迅速に実施しました。また、運用部門に対して誤った情報が流れたことについて謝罪し、正確な状態を確認するための手続きを進めました。今後このような事象が発生しないよう、監視システムの設定確認を定期的に行うことを約束します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00469', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-25T05:06:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T05:21:29+09:00', '【障害報告】【監視・可用性障害】可用性レポート誤集計', '2024年8月25日05時06分29秒、株式会社ストッククラウドのサービスVenusにおいて、運用者の作業ミスによるアクセス障害が発生しました。運用コンソールにて、月次可用性レポートが実績よりも高く表示されるという症状が確認されました。影響を受けたのは運用部門のみで、月末棚卸の開始時にメンテナンス除外時間の二重計上が起こったと推定されています。このエラーにより、運用部は正確な可用性レポートを得ることができず、業務運営に支障をきたしました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00469', 'INC-2024-00469', '本インシデントは、月末棚卸の開始時に発生しました。調査の結果、月次可用性レポートが実績より高く表示される原因は、メンテナンス除外時間の二重計上であることが判明しました。この誤集計により、運用部は正確な報告を得られず、業務に混乱をもたらしました。今後は、メンテナンスの取り扱いについて再度確認し、誤集計を防ぐための対策を講じる必要があります。', '本インシデントは、月末棚卸の開始時に発生しました。調査の結果、月次可用性レポートが実績より高く表示される原因は、メンテナンス除外時間の二重計上であることが判明しました。この誤集計により、運用部は正確な報告を得られず、業務に混乱をもたらしました。今後は、メンテナンスの取り扱いについて再度確認し、誤集計を防ぐための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-26T05:21:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00693', 'INC-2024-00469', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-25T05:36:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T06:36:29+09:00', '初期対応', '運用部門は、月次可用性レポートの誤集計を受けて直ちに状況確認を行いました。運用者の作業ミスが確認され、メンテナンス除外時間の二重計上が原因と特定されました。全ての関連データを確認し、運用コンソールの設定を見直す作業を開始しました。エラーコードMON-10-00469に基づき、適切な修正作業を進めることとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00475', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-26T01:40:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T03:40:50+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2024年8月26日01時40分50秒に、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSに関連する棚卸突合失敗が発生しました。この障害は、分散トランザクションがタイムアウトし、片側のみコミットされるという症状を引き起こしました。影響範囲は全テナントに及び、特に大規模セール開始直前に発生したことから、在庫計算エンジンに対する影響が懸念されます。原因として、2PCタイムアウト設定の過短が疑われています。検知は03時36分50秒であり、116分間の遅延がありました。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00475', 'INC-2024-00475', '本障害の調査結果として、発生時の状況は大規模セール開始直前であったため、トランザクションの負荷が高まっていたことが影響していると考えられます。また、2PCタイムアウト設定が適切でなかったため、分散トランザクションがタイムアウトし、片側コミットとなる事象が発生しました。この点については、設定の見直しが急務です。', '本障害の調査結果として、発生時の状況は大規模セール開始直前であったため、トランザクションの負荷が高まっていたことが影響していると考えられます。また、2PCタイムアウト設定が適切でなかったため、分散トランザクションがタイムアウトし、片側コミットとなる事象が発生しました。この点については、設定の見直しが急務です。', TIMESTAMP WITH TIME ZONE '2024-08-27T03:40:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00701', 'INC-2024-00475', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-26T03:55:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T04:55:50+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウト', '障害発生後、営業部の花子が速やかに関連部門に連絡し、問題の特定を進めました。初期調査では、分散トランザクションがタイムアウトしたことが判明し、関連する設定を確認する必要があることがわかりました。全テナントへの影響を考慮し、影響範囲を迅速に評価しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00476', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-10T20:48:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T22:48:32+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2024年8月10日20:48:32、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSでの棚卸突合が失敗しました。発見者は営業部の花子です。Shift_JIS変換により商品名が文字化けし、影響範囲は単一店舗のみです。エラーコードはEDI-07-00476で、データ移行バッチ実行中にこの事象が発生しました。検知は2024年8月10日23:06:32、発生から138分後です。技術詳細としては、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしたことが報告されています。原因として文字コード変換テーブルの誤選択が疑われています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00476', 'INC-2024-00476', '発生したShift_JIS変換による文字化けは、顧客店舗POSに影響を及ぼしました。調査の結果、データ移行バッチ実行中に使用された文字コード変換テーブルの誤選択が原因であることが確認されました。今後、文字コード変換のプロセスにおける検証を強化し、再発防止に向けた対策を講じる必要があります。', '発生したShift_JIS変換による文字化けは、顧客店舗POSに影響を及ぼしました。調査の結果、データ移行バッチ実行中に使用された文字コード変換テーブルの誤選択が原因であることが確認されました。今後、文字コード変換のプロセスにおける検証を強化し、再発防止に向けた対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-11T22:48:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00702', 'INC-2024-00476', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-10T23:03:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T00:03:32+09:00', '【初動対応】【API連携・EDI障害】文字コード変換事故の初動対応', '初動対応として、該当のデータ移行バッチを停止し、文字コード変換テーブルの設定を再確認しました。また、影響を受けた商品リストを抽出し、文字化けを修正する作業を行っています。顧客店舗への影響を最小限に抑えるため、直ちに修正パッチの適用を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00703', 'INC-2024-00476', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-11T00:33:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T01:33:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00479', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-07-19T19:21:27+09:00', TIMESTAMP WITH TIME ZONE '2024-07-19T19:36:27+09:00', '【障害報告】【運用操作・権限障害】本番DB誤接続', '2024年7月19日19時21分27秒に、株式会社ストッククラウドの運用コンソールにおいて、運用ツールが本番DB以外に接続している事象が発生しました。発見者は運用部の運用 一郎で、同日19時31分27秒に検知されました。エラーコードはOPS-06-00479で、定例リリース直後に発生したことから、設定ミスによる影響が考えられます。この事象は全テナントに波及する可能性があり、運用操作・権限障害の一環として分類されました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00479', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00479', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00479', 'INC-2024-00479', '調査の結果、定例リリース直後に運用ツールが本番DB以外に接続していたことが確認されました。推定される原因は、本番DBへの誤接続設定であり、運用コンソールと設定管理DBの両方に影響を及ぼしています。この障害により、全テナントが影響を受ける状況が発生しました。再発防止策として、接続設定の見直しが急務です。', '調査の結果、定例リリース直後に運用ツールが本番DB以外に接続していたことが確認されました。推定される原因は、本番DBへの誤接続設定であり、運用コンソールと設定管理DBの両方に影響を及ぼしています。この障害により、全テナントが影響を受ける状況が発生しました。再発防止策として、接続設定の見直しが急務です。', TIMESTAMP WITH TIME ZONE '2024-07-20T19:36:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00707', 'INC-2024-00479', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-07-19T19:51:27+09:00', TIMESTAMP WITH TIME ZONE '2024-07-19T20:51:27+09:00', '【初期対応】【運用操作・権限障害】本番DB誤接続', '初期対応として、運用部は直ちに運用ツールの接続設定を確認し、誤接続の原因を特定しました。設定の見直しを行い、本番DBへの正しい接続を確立する作業を進めています。また、影響を受けたテナントへの連絡を行い、障害の詳細を説明しています。今後の再発防止策についても検討中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00480', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-21T16:32:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T17:02:34+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '株式会社ストッククラウドのサービスVenusにおいて、2024年8月21日16時32分34秒に、在庫登録失敗の事象が発生しました。この障害は、楽観ロック競合が多発し、更新失敗率が上昇するという症状を呈しました。発見は2024年8月21日17時04分34秒であり、検知までに32分を要しました。発生場所はMercury AWS APで、エラーコードはSYNC-10-00480です。大規模セール開始直前のタイミングで発生したこの問題は、すべてのテナントに影響を及ぼす可能性があります。推定原因としては、バージョンカラム更新ロジックの不備が考えられます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00480', 'INC-2024-00480', '本インシデントに関する調査の結果、大規模セール開始直前に楽観ロック競合が多発し、更新失敗率が上昇したことが確認されました。この競合によりデータの同期や整合性に問題が生じ、多くのテナントが影響を受けました。原因は、バージョンカラムの更新ロジックに不備があることが指摘されています。今後は、このロジックの見直しと改善が急務であると考えています。', '本インシデントに関する調査の結果、大規模セール開始直前に楽観ロック競合が多発し、更新失敗率が上昇したことが確認されました。この競合によりデータの同期や整合性に問題が生じ、多くのテナントが影響を受けました。原因は、バージョンカラムの更新ロジックに不備があることが指摘されています。今後は、このロジックの見直しと改善が急務であると考えています。', TIMESTAMP WITH TIME ZONE '2024-08-22T17:02:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00708', 'INC-2024-00480', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-21T17:17:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T18:17:34+09:00', '【初動対応】楽観ロック競合多発', 'インシデント発生を受け、運用部の運用 一郎が迅速に対応を開始しました。影響を受けたエリアの特定を行い、データベースのログを調査することで、楽観ロックの競合が原因であることを突き止めました。関係者への連絡を行い、問題解決に向けたチームを編成しました。また、エラーの発生状況をリアルタイムでモニタリングし、追加の影響を防ぐための対策を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00709', 'INC-2024-00480', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-21T18:47:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T19:47:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00484', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-10T17:01:23+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T17:16:23+09:00', '【障害報告】【運用操作・権限障害】夜間バッチ手動停止', '2024年8月10日17時01分に、株式会社ストッククラウドの運用 一郎が運用コンソールにおいて、夜間バッチを手動停止した後、再起動を忘れてしまった。そのため、バッチ処理が実施されず、運用業務に影響を及ぼした。この事象は17時11分に検知され、運用部の確認により直ちに対応が求められた。影響範囲はバッチ処理のみに限られ、オンラインサービスには影響がなかった。この障害は年末年始の稼働切替時に発生したものであり、運用手順書の再起動ステップが省略されたことが推定原因として挙げられている。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00484', 'INC-2024-00484', '運用 一郎による手動停止後の夜間バッチの再起動忘れが確認されました。運用手順書において、再起動のステップが明記されていなかったことが問題です。運用部は、手順書の見直しを行う必要があります。今後同様の事象を防ぐために、運用教育も重要です。', '運用 一郎による手動停止後の夜間バッチの再起動忘れが確認されました。運用手順書において、再起動のステップが明記されていなかったことが問題です。運用部は、手順書の見直しを行う必要があります。今後同様の事象を防ぐために、運用教育も重要です。', TIMESTAMP WITH TIME ZONE '2024-08-11T17:16:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00714', 'INC-2024-00484', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T17:31:23+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T18:31:23+09:00', '【初動対応】【運用操作・権限障害】夜間バッチ手動停止', '運用 一郎が手動停止した夜間バッチの再起動を確認した後、直ちに再起動を行いました。影響を受けたスケジューラの状態を確認し、正常に稼働を再開させました。今後、手動操作後の確認作業を徹底し、再発防止策を検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00485', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-24T12:48:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T13:48:49+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年8月24日12時48分49秒に発生した顧客側ネットワーク障害について報告いたします。症状としては、DNS解決成功後にTLS握手で接続が切断される事象が発生しました。本障害は、インフラメンテナンス明けに発生し、影響範囲は同一顧客の全店舗に及びました。推定原因としてはプロキシ証明書の期限切れが考えられます。エラーコードはNW-03-00485です。営業の花子が発見し、2024年8月24日13時42分49秒に検知されました。今回の障害により、顧客ネットワークの信頼性に影響が出ております。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00485', 'INC-2024-00485', '本インシデントについての調査を実施しました。インフラメンテナンス明けにおいて、DNS解決が成功した後にTLS握手で接続が切断される事象を確認しました。これは、プロキシ証明書の期限切れが原因である可能性が高いと結論しました。今後は、証明書の管理を強化し、定期的な確認を行うことで同様の障害を防ぐ必要があります。', '本インシデントについての調査を実施しました。インフラメンテナンス明けにおいて、DNS解決が成功した後にTLS握手で接続が切断される事象を確認しました。これは、プロキシ証明書の期限切れが原因である可能性が高いと結論しました。今後は、証明書の管理を強化し、定期的な確認を行うことで同様の障害を防ぐ必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-25T13:48:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00715', 'INC-2024-00485', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-24T14:03:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T15:03:49+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', 'インシデント発生時、担当者である営業の花子が迅速に対応を開始しました。顧客に対して状況を説明し、影響を受けている全店舗への情報提供を行いました。また、技術チームに連絡を取り、問題の詳細な調査を依頼しました。現場においては、接続が切断された原因を特定するためのログ分析を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00716', 'INC-2024-00485', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-24T15:33:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T16:33:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00486', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-24T06:25:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T06:55:04+09:00', '【障害報告】【認証・セッション障害】Cookie SameSite拒否', '2024年8月24日06:25に、株式会社ストッククラウドのVenusサービスにおいて、Cookie SameSite設定が原因で埋込画面の認証が不可となる事象が発生しました。影響範囲は単一店舗のみで、発見者は運用部の運用 一郎です。定例リリース直後の発生で、推定原因としてSameSite属性変更の影響が考えられます。エラーコードはAUTH-06-00486で、発生から検知まで22分を要しました。技術的な詳細として、埋込画面が認証不可となっているため、迅速な対応が求められます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00486', 'INC-2024-00486', 'この度の事象について、運用部の運用 一郎が調査を実施しました。埋込画面の認証不可の原因は、定例リリース直後に行われたCookie SameSite設定の変更であることが確認されました。技術的には、SameSite属性変更が影響を及ぼしているため、この点に注目し、迅速な修正が必要です。影響コンポーネントはVenus Azure APとセッションストアに関連しています。', 'この度の事象について、運用部の運用 一郎が調査を実施しました。埋込画面の認証不可の原因は、定例リリース直後に行われたCookie SameSite設定の変更であることが確認されました。技術的には、SameSite属性変更が影響を及ぼしているため、この点に注目し、迅速な修正が必要です。影響コンポーネントはVenus Azure APとセッションストアに関連しています。', TIMESTAMP WITH TIME ZONE '2024-08-25T06:55:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00717', 'INC-2024-00486', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-24T07:10:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T08:10:04+09:00', '【対応ログ】【認証・セッション障害】初期対応', '2024年8月24日06:50に運用部の運用 一郎が初期対応を開始しました。Cookie SameSite設定に関して、定例リリース直後の影響を受けていることを確認しました。迅速な修正に向けて、技術チームと連携を取り、必要な変更を行うことを提案しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00487', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-29T17:11:02+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T17:41:02+09:00', '【障害報告】【在庫マスター設定障害】セット商品分解失敗', '2024年8月29日17時11分に、株式会社ストッククラウドのサービスVenusにおいて、セット商品の在庫分解時に構成エラーが発生しました。この障害は定例リリース直後に発生し、BOM構成テーブルの親子関係不整合が推定される原因とされています。影響範囲は同一顧客の全店舗に及び、Mercury AWS AP および在庫計算エンジンが影響を受けています。エラーコードはMST-07-00487です。検知は2024年8月29日17時46分に行われ、検知までに35分を要しました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00487', 'INC-2024-00487', '本インシデントの調査において、定例リリース直後に発生した障害により、セット商品の在庫分解時に構成エラーが確認されました。調査の結果、BOM構成テーブルにおいて親子関係の不整合が見つかりました。この不整合が原因で、在庫計算エンジンが適切に動作せず、全店舗に影響が及ぶ結果となりました。', '本インシデントの調査において、定例リリース直後に発生した障害により、セット商品の在庫分解時に構成エラーが確認されました。調査の結果、BOM構成テーブルにおいて親子関係の不整合が見つかりました。この不整合が原因で、在庫計算エンジンが適切に動作せず、全店舗に影響が及ぶ結果となりました。', TIMESTAMP WITH TIME ZONE '2024-08-30T17:41:02+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00718', 'INC-2024-00487', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-29T17:56:02+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T18:56:02+09:00', '【初動対応】【在庫マスター設定障害】セット商品分解失敗', 'インシデント発生から直ちに初動対応を開始し、技術チームが迅速に原因調査に着手しました。BOM構成テーブルの確認を行い、親子関係の不整合を特定しました。対応策として、構成テーブルの修正を提案し、システムの安定化を図るための作業を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00491', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-02T05:26:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T06:11:15+09:00', '【障害報告】【CLU-10】SLO燃焼率警告', '・発生日時: 2024-08-02 05:26:15
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00491', 'INC-2024-00491', '本インシデントについて、SLO燃焼率が閾値を超過した原因を調査しました。大規模セール直前にSLO計算ウィンドウの設定が誤っていたことが確認されました。この誤設定により、エラーバジェット警告が発生し、全テナントに影響を及ぼしました。今後の再発防止策として、設定の見直しと監視体制の強化が必要です。', '本インシデントについて、SLO燃焼率が閾値を超過した原因を調査しました。大規模セール直前にSLO計算ウィンドウの設定が誤っていたことが確認されました。この誤設定により、エラーバジェット警告が発生し、全テナントに影響を及ぼしました。今後の再発防止策として、設定の見直しと監視体制の強化が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-03T06:11:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00724', 'INC-2024-00491', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-02T06:26:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T07:26:15+09:00', '【初期対応】【CLU-10】SLO燃焼率警告', '本件については、運用部による初期対応を実施しました。SLO設定の見直しと共に、該当コンポーネントの監視強化を行い、再発防止に向けた対策を講じています。影響を受けた全テナントに対しても状況を報告し、適切な対応を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00499', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-23T03:14:13+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T03:44:13+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2024年8月23日03時14分、株式会社ストッククラウドのVenusサービスにおいて、死活監視が正常系をDOWNと誤検知する事象が発生しました。発生時刻から36分後の03時50分に検知され、影響を受けたのは運用部門のみです。この障害は、定例リリース直後に発生したため、リリースによる影響が考えられます。具体的には、監視プローブのUser-Agentブロックが原因と推定されており、一時的に死活監視が誤った状態を報告する結果となりました。エラーコードはMON-01-00499です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00499', 'INC-2024-00499', '本事象について調査を行った結果、死活監視が正常系をDOWNと誤検知したことが確認されました。監視プローブの設定に問題がある可能性が高く、特にUser-Agentブロックが影響していると見られます。今後、監視設定の見直しを行い、再発防止策を講じる必要があります。', '本事象について調査を行った結果、死活監視が正常系をDOWNと誤検知したことが確認されました。監視プローブの設定に問題がある可能性が高く、特にUser-Agentブロックが影響していると見られます。今後、監視設定の見直しを行い、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-24T03:44:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00735', 'INC-2024-00499', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-23T03:59:13+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T04:59:13+09:00', '【対応】INITIAL', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00505', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-18T02:55:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T03:55:31+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年8月18日02時55分31秒に、株式会社ストッククラウドのVenusサービスにおいて、顧客側ネットワーク障害が発生しました。発生場所は顧客拠点NWであり、症状としてはDNS解決成功後にTLS握手で接続が切断されました。推定される原因はプロキシ証明書の期限切れであり、影響範囲は同一顧客の全店舗に及びました。なお、発生契機はインフラメンテナンス明けであり、2024年8月18日04時05分31秒に検知されるまで70分を要しました。この期間中、顧客は全店舗でサービス利用ができない状態に陥りました。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00505', 'INC-2024-00505', 'インフラメンテナンス明けにDNS解決が成功した後、TLS握手で接続が切断される現象が確認されました。原因としてプロキシ証明書の期限切れが強く疑われます。この問題により、顧客ネットワーク全体に影響を与え、全店舗でのサービス利用が不可能となりました。今後はプロキシ証明書の管理体制を見直し、定期的な確認を行う必要があります。', 'インフラメンテナンス明けにDNS解決が成功した後、TLS握手で接続が切断される現象が確認されました。原因としてプロキシ証明書の期限切れが強く疑われます。この問題により、顧客ネットワーク全体に影響を与え、全店舗でのサービス利用が不可能となりました。今後はプロキシ証明書の管理体制を見直し、定期的な確認を行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-19T03:55:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00744', 'INC-2024-00505', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-18T04:10:31+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T05:10:31+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', '障害発生直後、営業部の花子が状況を把握し、顧客への連絡を行いました。影響を受けた全店舗に対して、問題の状況と対応中である旨を通知しました。また、技術部門にも報告し、迅速な問題解決に向けた調査を依頼しました。初期対応として、顧客からの問い合わせには丁寧に応対し、安心感を提供することを心がけました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00509', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-07T13:25:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T13:40:47+09:00', '【障害報告】【CLU-10】ログ相関ID欠落', '2024年8月7日13時25分47秒に発生した運用者の作業ミスによるアクセス障害について報告いたします。発生直後、運用部門の運用 一郎が運用コンソール上でログに相関IDが欠落している事象を確認しました。このため、横断検索が不可となり、監視・可用性障害の影響が出ております。定例リリース直後という契機で、この障害は発生いたしました。推定される原因は、ログフォーマット変更のロールアウト漏れであり、影響範囲は運用部門のみとなります。エラーコードはMON-09-00509です。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00509', 'INC-2024-00509', '調査を行った結果、定例リリース直後において運用コンソールのログに相関IDが欠落していることが確認されました。この問題により、横断検索が不可能となる事象が発生しました。原因としては、ログフォーマット変更のロールアウト漏れが疑われており、これが運用部門の作業に大きな影響を及ぼしています。今後の対応が必要です。', '調査を行った結果、定例リリース直後において運用コンソールのログに相関IDが欠落していることが確認されました。この問題により、横断検索が不可能となる事象が発生しました。原因としては、ログフォーマット変更のロールアウト漏れが疑われており、これが運用部門の作業に大きな影響を及ぼしています。今後の対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-08T13:40:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00751', 'INC-2024-00509', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-07T13:55:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T14:55:47+09:00', '【初動対応】【CLU-10】ログ相関ID欠落', '初動対応として、運用部門の運用 一郎は直ちにログの状況を確認し、相関ID欠落の影響範囲を特定しました。運用コンソールおよびログパイプラインにおける問題を認識し、担当チームに迅速な対応を指示しました。また、監視システムのチェックを行い、他の関連するログに影響が出ていないことを確認しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00752', 'INC-2024-00509', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-07T15:25:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T16:25:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00511', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-03T11:40:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T12:10:45+09:00', '【障害報告】【API連携・EDI障害】バルクAPI部分失敗', '2024年8月3日11時40分45秒、株式会社ストッククラウドのVenusにおいて、データ移行バッチ実行中にバルクAPIが部分失敗し、ロールバックが未完了となる事象が発生しました。発生箇所はMercury AWS APで、発見者は運用部の運用 一郎です。影響を受けたのはサービス全体の一部機能であり、エラーコードはEDI-10-00511です。バルクAPIの部分失敗により、正常な在庫登録ができず、業務に支障をきたす状況となりました。原因としては、部分成功時の補償トランザクションが欠如していることが疑われます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00511', 'INC-2024-00511', '本事象の調査を行った結果、データ移行バッチ実行中に発生したバルクAPIの部分失敗が確認されました。ロールバックが未完了であったため、在庫登録が正常に行えず、複数の機能に影響を及ぼしました。詳細な調査を進めたところ、部分成功時に行うべき補償トランザクションが存在しなかったことが根本原因であると特定されました。この問題により、サービスの安定性に対する影響も考えられます。', '本事象の調査を行った結果、データ移行バッチ実行中に発生したバルクAPIの部分失敗が確認されました。ロールバックが未完了であったため、在庫登録が正常に行えず、複数の機能に影響を及ぼしました。詳細な調査を進めたところ、部分成功時に行うべき補償トランザクションが存在しなかったことが根本原因であると特定されました。この問題により、サービスの安定性に対する影響も考えられます。', TIMESTAMP WITH TIME ZONE '2024-08-04T12:10:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00754', 'INC-2024-00511', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-03T12:25:45+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T13:25:45+09:00', '【初期対応】【API連携・EDI障害】バルクAPI部分失敗への初期対応', '本事象を受けて、初期対応として運用部は速やかにバルクAPIの状態を確認し、同時にデータ移行バッチの状況を監視しました。部分失敗が確認されたため、関係者への報告と影響範囲の特定を行い、ロールバック処理を手動で実施する方針を決定しました。さらに、この問題が再発しないよう、補償トランザクションの設計見直しを行うことも検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00515', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-06T14:36:52+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T15:06:52+09:00', '【障害報告】【CLU-06】キャッシュヒット率低下', '2024年8月6日14時36分52秒に発生した障害について報告いたします。今回のインシデントは、株式会社ストッククラウドが提供するサービス「Venus」において、定例リリース直後にキャッシュヒット率低下が発生し、DB負荷が増加するという性能・負荷障害です。検知は2024年8月6日15時07分52秒に行われ、検知までの時間は31分でした。この問題は全テナントに波及し、影響範囲は広範囲にわたります。エラーコードはPRF-09-00515です。原因としては、インデックスが未適用の新機能が疑われています。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00515', 'INC-2024-00515', '本件について、詳細な調査を行いました。定例リリース直後にキャッシュヒット率が低下したことが確認され、これによりDB負荷が増加したことも明らかになりました。原因として、インデックスが未適用の新機能が関与している可能性が高いと判断されます。今後、さらなる詳細な分析を行い、根本的な解決策を見出す必要があります。', '本件について、詳細な調査を行いました。定例リリース直後にキャッシュヒット率が低下したことが確認され、これによりDB負荷が増加したことも明らかになりました。原因として、インデックスが未適用の新機能が関与している可能性が高いと判断されます。今後、さらなる詳細な分析を行い、根本的な解決策を見出す必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-07T15:06:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00760', 'INC-2024-00515', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T15:21:52+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T16:21:52+09:00', '【初期対応】【CLU-06】キャッシュヒット率低下に対する初期対応', '本障害に対する初期対応を行いました。運用部の運用一郎が中心となり、影響を受けたテナントへの通知を実施し、DB負荷を軽減するための一時的な回避策を導入しました。また、リリース内容の再確認を行い、該当機能に関するインデックス適用を急ぎ実施する方針を決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00761', 'INC-2024-00515', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-06T16:51:52+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T17:51:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00523', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-20T15:57:42+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T17:57:42+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2024年8月20日15時57分42秒、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POS（ゾーンB）で月末棚卸の開始時に夜間整合性チェックで不一致アラートが多発しました。この現象は、整合性チェック基準の変更が未反映であることが推定されています。18時10分42秒に検知され、133分の間に複数の不一致が確認されました。影響範囲はバッチ処理のみで、オンラインには影響がありませんでした。今後の影響を最小限に抑えるため、早急な対応が求められます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00523', 'INC-2024-00523', '調査の結果、月末棚卸の開始時に整合性チェックにおいて不一致アラートが多発していることが確認されました。具体的には、夜間に実施される整合性チェックジョブが、変更された基準を反映していない可能性が高いです。今後は、整合性チェック基準の見直し及び、システムの更新を検討します。', '調査の結果、月末棚卸の開始時に整合性チェックにおいて不一致アラートが多発していることが確認されました。具体的には、夜間に実施される整合性チェックジョブが、変更された基準を反映していない可能性が高いです。今後は、整合性チェック基準の見直し及び、システムの更新を検討します。', TIMESTAMP WITH TIME ZONE '2024-08-21T17:57:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00773', 'INC-2024-00523', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-20T18:12:42+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T19:12:42+09:00', '初期対応', '初期対応として、整合性チェック基準の確認及び、関連システムの確認を開始しました。営業部の花子が対応に当たり、影響範囲を正確に把握するためのデータ収集を行っています。顧客には影響がないことを周知し、今後の対応についても情報を提供する予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00774', 'INC-2024-00523', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-20T19:42:42+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T20:42:42+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00525', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-19T18:59:12+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T20:59:12+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '2024年8月19日18時59分頃、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSにおける棚卸突合が失敗しました。発生時点でデッドレターが大量に蓄積されており、原因としてデッドレター再処理ジョブの未設定が疑われます。この問題はバッチ処理にのみ影響を及ぼし、オンラインには影響がありませんでした。19時58分に検知され、その後の調査により、問題がデータ移行バッチ実行中に発生したことが判明しました。今後、再発防止策を講じる必要があります。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00525', 'INC-2024-00525', '調査を行ったところ、データ移行バッチ実行中に同期メッセージが多くのデッドレターに蓄積されていたことが確認されました。この状態は、デッドレター再処理ジョブが未設定であったために引き起こされたと推定されます。バッチ処理中にエラーが発生し、その結果がデッドレターに反映されたため、メッセージキューの処理が滞っていました。', '調査を行ったところ、データ移行バッチ実行中に同期メッセージが多くのデッドレターに蓄積されていたことが確認されました。この状態は、デッドレター再処理ジョブが未設定であったために引き起こされたと推定されます。バッチ処理中にエラーが発生し、その結果がデッドレターに反映されたため、メッセージキューの処理が滞っていました。', TIMESTAMP WITH TIME ZONE '2024-08-20T20:59:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00776', 'INC-2024-00525', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-19T21:14:12+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T22:14:12+09:00', '初期対応', '営業部の花子が19時58分に問題を検知し、直ちに技術チームにエスカレーションしました。技術チームは問題確認後、デッドレターの再処理ジョブ設定を確認し、未設定であることを確認しました。状況を把握した上で、再処理ジョブの設定を行うことでデッドレターの削除を進めました。今後は、定期的なジョブ設定の見直しが必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00527', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-12-05T00:34:54+09:00', TIMESTAMP WITH TIME ZONE '2024-12-05T01:04:54+09:00', '【障害報告】【CLU-07】バルクAPI部分失敗', '2024年12月5日00時34分54秒に、株式会社ストッククラウドのサービスVenusにおいて、バルクAPIが部分失敗する事象が発生しました。影響を受けたのは架空服飾店A様の在庫登録APIで、データ移行バッチ実行中にロールバックが未完了となりました。このため、サービス全体の一部機能に影響が及びました。エラーコードはEDI-10-00527です。検知は2024年12月5日00時59分54秒で、発見者は運用部の運用 一郎です。これにより、部分成功時の補償トランザクションの欠如が推定される原因として考えられています。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00527', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00527', 'INC-2024-00527', '今回の事象は、データ移行バッチが実行中にバルクAPIが部分失敗したことで発生しました。ロールバックが未完了となったため、影響が広がったと考えられます。部分成功時の補償トランザクションが欠如していたことが主な原因であると推定され、今後このような事象が再発しないよう注意が必要です。', '今回の事象は、データ移行バッチが実行中にバルクAPIが部分失敗したことで発生しました。ロールバックが未完了となったため、影響が広がったと考えられます。部分成功時の補償トランザクションが欠如していたことが主な原因であると推定され、今後このような事象が再発しないよう注意が必要です。', TIMESTAMP WITH TIME ZONE '2024-12-06T01:04:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00779', 'INC-2024-00527', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-12-05T01:19:54+09:00', TIMESTAMP WITH TIME ZONE '2024-12-05T02:19:54+09:00', '【初期対応】【CLU-07】バルクAPI部分失敗の初期対応', '初期対応として、運用部の運用 一郎が即座にバルクAPIの状態を確認し、原因調査を開始しました。バルクAPIのログを解析し、部分失敗の状況を把握するためのデータ収集を行いました。また、影響を受けた顧客に対しては、状況を報告し、適切な対応を検討する旨を伝えました。今後の対応策としては、補償トランザクションの仕組みを見直し、再発防止策を講じる予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00528', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-15T03:17:54+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T03:47:54+09:00', '【障害報告】【認証・セッション障害】Cookie SameSite拒否', '2024年8月15日03時17分頃、株式会社ストッククラウドのVenusサービスにおいて、Cookie SameSite設定により埋込画面が認証不可となる事象が発生しました。本事象は定例リリース直後に発生し、運用部の運用 一郎が発見しました。影響範囲は単一店舗のみであり、発生契機としてSameSite属性変更の影響が考えられます。エラーコードはAUTH-06-00528で、影響コンポーネントはVenus Azure AP（Secondary）及びセッションストアです。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00528', 'INC-2024-00528', '運用 一郎です。調査の結果、定例リリース直後に行われたCookie SameSite設定の変更が原因で、埋込画面が認証不可になっていることが確認されました。この変更により、多くのユーザーが影響を受け、一時的にサービスの利用が制限される事態となりました。今後、SameSite属性についての再確認を行い、リリース前のテストを強化する必要があります。', '運用 一郎です。調査の結果、定例リリース直後に行われたCookie SameSite設定の変更が原因で、埋込画面が認証不可になっていることが確認されました。この変更により、多くのユーザーが影響を受け、一時的にサービスの利用が制限される事態となりました。今後、SameSite属性についての再確認を行い、リリース前のテストを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-16T03:47:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00780', 'INC-2024-00528', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-15T04:02:54+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T05:02:54+09:00', '【初動対応】【認証・セッション障害】Cookie SameSite拒否', '運用 一郎です。障害を確認した時点で、影響を受けている店舗に対して緊急対応を開始しました。まずはCookie設定を確認し、必要に応じてリリース内容のロールバックを行う準備を進めています。また、エラーコードAUTH-06-00528の詳細を関係部署に周知し、迅速な対応を依頼しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00781', 'INC-2024-00528', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-15T05:32:54+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T06:32:54+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00530', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-26T21:30:22+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T23:30:22+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2024年8月26日21時30分、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSで棚卸確定ボタンがグレーアウトしたまま操作できない事象が発生しました。発見者は営業部の花子で、発生契機は月末棚卸の開始時でした。これにより、単一店舗のみが影響を受け、棚卸確定が行えない状況となっています。推定原因として未処理の差異調整レコード残留が考えられます。影響コンポーネントは顧客店舗POS（ゾーンA）および店舗在庫ビューです。この問題の解決が急務です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00530', 'INC-2024-00530', '初期調査の結果、2024年8月26日21時30分に発生した棚卸確定ボタンがグレーアウトした事象について、未処理の差異調整レコード残留が原因である可能性が高いことが確認されました。影響を受けた店舗は単一であり、業務の進行に支障をきたしています。詳細なログ分析を行い、この差異調整レコードの特定と処理を急ぎます。', '初期調査の結果、2024年8月26日21時30分に発生した棚卸確定ボタンがグレーアウトした事象について、未処理の差異調整レコード残留が原因である可能性が高いことが確認されました。影響を受けた店舗は単一であり、業務の進行に支障をきたしています。詳細なログ分析を行い、この差異調整レコードの特定と処理を急ぎます。', TIMESTAMP WITH TIME ZONE '2024-08-27T23:30:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00784', 'INC-2024-00530', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-26T23:45:22+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T00:45:22+09:00', '【初期対応】【棚卸・POS突合障害】棚卸確定不可', '2024年8月26日23時19分、営業部の花子が初期対応を行いました。まず、問題の発生した顧客店舗POSのログを確認し、未処理の差異調整レコードが残っていることを確認しました。これに対して、差異調整レコードの処理手順を早急に作成し、店舗担当者に連絡を取る必要があります。今後の対応を迅速に進める方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00785', 'INC-2024-00530', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T01:15:22+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T02:15:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00533', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-09-21T21:53:10+09:00', TIMESTAMP WITH TIME ZONE '2024-09-21T22:23:10+09:00', '【障害報告】【認証・セッション障害】サービスアカウント鍵漏洩対応', '2024年9月21日21時53分に、株式会社ストッククラウドのサービスMercuryにおいて、サービスアカウント鍵漏洩疑いによる一括無効化が発生しました。この事象は、定例リリース直後に発生し、影響範囲はバッチ処理のみであり、オンラインサービスへの影響は確認されておりません。エラーコードはAUTH-09-00533で、運用部の運用 一郎が発見者となっております。検知は同日22時26分に行われ、発生から検知までの時間は33分でした。今回の事象は、緊急鍵無効化手順の過剰適用が原因と推定されており、影響を受けたコンポーネントはVenus Azure AP（DRサイト）及び認可サービスです。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00533', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00533', 'INC-2024-00533', '本件に関する調査を実施した結果、サービスアカウント鍵漏洩疑いの発生は、定例リリース直後における緊急鍵無効化手順の過剰適用に起因する可能性が高いことが判明しました。具体的には、リリース時の変更に伴い、意図せず複数の鍵が無効化される事態が生じました。今後の再発防止に向けて、緊急鍵無効化手順の見直しおよび運用フローの改善が必要です。', '本件に関する調査を実施した結果、サービスアカウント鍵漏洩疑いの発生は、定例リリース直後における緊急鍵無効化手順の過剰適用に起因する可能性が高いことが判明しました。具体的には、リリース時の変更に伴い、意図せず複数の鍵が無効化される事態が生じました。今後の再発防止に向けて、緊急鍵無効化手順の見直しおよび運用フローの改善が必要です。', TIMESTAMP WITH TIME ZONE '2024-09-22T22:23:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00788', 'INC-2024-00533', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-21T22:38:10+09:00', TIMESTAMP WITH TIME ZONE '2024-09-21T23:38:10+09:00', '【初動対応】【認証・セッション障害】サービスアカウント鍵漏洩対応', 'インシデント発生後、運用部の担当者は、直ちに影響範囲の特定を行い、サービスアカウントの鍵無効化に関するログを収集しました。その後、緊急対応として、影響を受けたバッチ処理の復旧作業を優先的に実施し、オンラインサービスの安定性を確保しました。また、関係者への情報共有を行い、事象の全体像を把握するための会議を開催しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00536', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-19T23:06:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T01:06:50+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2024年8月19日23時06分50秒に、株式会社ストッククラウドのVenusにおいて棚卸突合失敗のインシデントが発生しました。発生地点は顧客店舗POSで、営業部の花子が発見しました。この問題により、サービス全体の一部機能が影響を受けました。具体的には、パートナーAPIが429を返し、連携が停止したためです。このエラーは大規模セール開始直前に発生しており、呼出頻度の事前調整不足が推定原因と考えられています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00536', 'INC-2024-00536', 'インシデント発生後の調査により、パートナーAPIが429のステータスコードを返したことが確認されました。このため、連携が停止しています。原因として大規模セール開始直前に呼出頻度の調整が行われていなかったことが考えられ、これによりパートナーAPIが過負荷状態に入った可能性があります。今後の対策として、呼出頻度の管理を徹底する必要があります。', 'インシデント発生後の調査により、パートナーAPIが429のステータスコードを返したことが確認されました。このため、連携が停止しています。原因として大規模セール開始直前に呼出頻度の調整が行われていなかったことが考えられ、これによりパートナーAPIが過負荷状態に入った可能性があります。今後の対策として、呼出頻度の管理を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-21T01:06:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00793', 'INC-2024-00536', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-20T01:21:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T02:21:50+09:00', '【初動対応】', 'この度のインシデントに関し、初動対応として顧客店舗POSへの影響範囲を確認し、パートナーAPIの状況を把握することが急務です。エラーコードEDI-06-00536に関連する情報を収集し、レート超過429に関する詳細を調査しています。今後の対応は、適切な呼出頻度の設定を行うことを最優先し、再発防止策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00539', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-18T09:23:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T09:53:34+09:00', '【障害報告】【在庫マスター設定障害】キャッシュ不整合登録', '2024年8月18日09時23分34秒に、株式会社ストッククラウドのVenusサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。この障害は、定例リリース直後にマスター更新を行った際、更新後も旧設定で在庫登録が拒否されるという症状が観測されました。影響範囲は全テナントに波及し、エラーコードMST-10-00539が記録されています。推定原因として、キャッシュレイヤの無効化漏れが考えられます。この件による影響は、在庫マスター設定に関する信頼性に関わるため、迅速な対応が求められました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00539', 'INC-2024-00539', '障害発生の背景を調査した結果、定例リリース直後に実施されたマスター更新が原因であることが判明しました。具体的には、マスター更新後も旧設定がキャッシュに残っており、在庫登録が拒否されてしまったことが確認されました。このキャッシュの不整合は、全テナントに影響を及ぼし、業務に支障をきたしました。今後はキャッシュの管理体制を見直し、定期的に無効化を行う対策が必要です。', '障害発生の背景を調査した結果、定例リリース直後に実施されたマスター更新が原因であることが判明しました。具体的には、マスター更新後も旧設定がキャッシュに残っており、在庫登録が拒否されてしまったことが確認されました。このキャッシュの不整合は、全テナントに影響を及ぼし、業務に支障をきたしました。今後はキャッシュの管理体制を見直し、定期的に無効化を行う対策が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-19T09:53:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00796', 'INC-2024-00539', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-18T10:08:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T11:08:34+09:00', '【初期対応】【在庫マスター設定障害】キャッシュ不整合登録', '障害発生から41分後の10時04分34秒に、運用部の運用 一郎がこの問題を検知し、即座に初期対応を開始しました。影響を受けた全テナントに対して障害の内容を通知し、その後、キャッシュの無効化作業を実施しました。さらに、関連ログを収集し、原因分析を進めるとともに、顧客への対応にも注力しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00797', 'INC-2024-00539', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-18T11:38:34+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T12:38:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00540', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-22T22:20:33+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T23:20:33+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2024年8月22日22:20頃、株式会社ストッククラウドの顧客である店舗で特定拠点のみAPI呼び出しが失敗する事象が発生しました。原因として店舗LANのスイッチ故障が疑われます。この問題は新規店舗追加の初日に発生しており、影響範囲は単一店舗に限定されています。その後、2024年8月23日00:03に検知され、103分の遅延が確認されました。該当するエラーコードはNW-02-00540です。顧客拠点のネットワーク（ゾーンB）と顧客側ファイアウォールが影響を受けていることが報告されています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00540', 'INC-2024-00540', '特定拠点のみでAPI呼び出しが失敗した問題について調査を行いました。新規店舗追加の初日という契機から、店舗LANのスイッチ故障が主な原因と考えられます。詳細な技術分析の結果、LANの障害がAPIの通信に影響を与えていたことが確認されました。今後、店舗LANの正常性確認を徹底することが必要です。', '特定拠点のみでAPI呼び出しが失敗した問題について調査を行いました。新規店舗追加の初日という契機から、店舗LANのスイッチ故障が主な原因と考えられます。詳細な技術分析の結果、LANの障害がAPIの通信に影響を与えていたことが確認されました。今後、店舗LANの正常性確認を徹底することが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-23T23:20:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00798', 'INC-2024-00540', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-22T23:35:33+09:00', TIMESTAMP WITH TIME ZONE '2024-08-23T00:35:33+09:00', '【初期対応】【顧客ネットワーク障害】拠点限定API失敗', '当該問題に対して初期対応を実施しました。顧客に対して問題の報告を行い、影響範囲の確認を行いました。また、店舗LANのスイッチの状態を確認するために、技術担当者を派遣する手配を行いました。顧客には状況を逐次報告し、速やかに復旧作業を進める旨を伝えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00542', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-30T05:25:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T06:25:29+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2024年8月30日05:25に発生した顧客側ネットワーク障害について報告します。株式会社ストッククラウドのVenusサービスにおいて、顧客固定IP変更が許可リストに未反映の状態が確認されました。この障害は特定の単一店舗に影響を及ぼし、顧客オンボーディング当日に発生したことが判明しました。5時25分に発生し、6時17分に検知されたため、52分の遅延がありました。影響を受けたコンポーネントは顧客拠点NW（ゾーンB）および顧客側FWです。発見者は営業部の花子です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00542', 'INC-2024-00542', '調査の結果、顧客オンボーディング当日におけるIP許可リストの更新漏れが原因であると推定されます。固定IPが許可リストに未反映のため、顧客側NWに接続できない状況が発生しました。これにより、顧客がサービスを利用できない障害が生じたことが確認されました。', '調査の結果、顧客オンボーディング当日におけるIP許可リストの更新漏れが原因であると推定されます。固定IPが許可リストに未反映のため、顧客側NWに接続できない状況が発生しました。これにより、顧客がサービスを利用できない障害が生じたことが確認されました。', TIMESTAMP WITH TIME ZONE '2024-08-31T06:25:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00800', 'INC-2024-00542', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-30T06:40:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T07:40:29+09:00', '【初期対応】【顧客ネットワーク障害】固定IP変更未連絡', '営業部の花子がこの顧客ネットワーク障害を最初に報告しました。固定IPの変更が許可リストに未反映という症状が確認されました。まずは、IP許可リストの更新を行う必要があります。今後、顧客に対して適切な連絡を行い、この問題の解決に向けて迅速に対応します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00801', 'INC-2024-00542', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-30T08:10:29+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T09:10:29+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00557', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-17T12:32:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T13:17:46+09:00', '【障害報告】【ストレージ・容量障害】DB自動拡張上限', '2024年8月17日12時32分46秒に、株式会社ストッククラウドのサービスVenusにおいて、Mercury AWS StorageでDB自動拡張が上限に到達し書込停止する事象が発生しました。この障害の影響により、全テナントに波及し、業務に支障をきたしました。発生契機は大規模セール開始直前であり、事前のDB拡張が行われなかったことが推定原因として考えられます。エラーコードはSTR-04-00557であり、運用部の運用 一郎によって発見されました。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00557', 'INC-2024-00557', '本事象の調査を行った結果、DB自動拡張の上限設定不足が主な原因であることが確認されました。大規模セールに伴い、通常以上の書き込みが発生することが予想されていたにもかかわらず、適切なDB拡張が実施されなかったため、上限に到達し書込停止となりました。今後は、上限設定を見直し、事前に拡張を行うことで再発防止に努めます。', '本事象の調査を行った結果、DB自動拡張の上限設定不足が主な原因であることが確認されました。大規模セールに伴い、通常以上の書き込みが発生することが予想されていたにもかかわらず、適切なDB拡張が実施されなかったため、上限に到達し書込停止となりました。今後は、上限設定を見直し、事前に拡張を行うことで再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2024-08-18T13:17:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00825', 'INC-2024-00557', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-17T13:32:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T14:32:46+09:00', '【初動対応】【ストレージ・容量障害】DB自動拡張上限', '初動として、運用部が速やかに原因の特定を行い、DBの上限設定を確認しました。結果として、DB自動拡張が上限に達していることが判明し、即座に上限の引き上げ作業を実施しました。すべてのテナントに影響が及んでいるため、顧客への連絡と状況報告を行い、業務の復旧に向けた対策を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00563', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-02T19:06:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T19:21:27+09:00', '【障害報告】【運用操作・権限障害】夜間バッチ手動停止', '2024年8月2日19時06分、株式会社ストッククラウドの運用コンソールにおいて、夜間バッチを手動停止後に再起動を忘れたことが原因でアクセス障害が発生しました。運用部の運用 一郎が発見し、19分後の19時25分に検知されました。影響範囲はバッチ処理のみで、オンラインへの影響はありませんでした。エラーコードはOPS-10-00563です。年末年始の稼働切替時に発生したため、運用手順書の再起動ステップ省略が推定原因とされています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00563', 'INC-2024-00563', '調査の結果、夜間バッチの手動停止後に再起動をしないまま放置されていたことが確認されました。運用手順書に再起動ステップが明記されていなかったため、運用部の運用 一郎のミスが引き起こしたと考えられます。今後は手順書の見直しと周知徹底を行い、再発防止に努めます。', '調査の結果、夜間バッチの手動停止後に再起動をしないまま放置されていたことが確認されました。運用手順書に再起動ステップが明記されていなかったため、運用部の運用 一郎のミスが引き起こしたと考えられます。今後は手順書の見直しと周知徹底を行い、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2024-08-03T19:21:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00832', 'INC-2024-00563', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-02T19:36:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T20:36:27+09:00', '【初期対応】【運用操作・権限障害】夜間バッチ手動停止', '運用部の運用 一郎からの報告を受け、即座に夜間バッチの再起動を実施しました。スケジューラの状態を確認し、バッチ処理が正常に再開されることを確認しました。また、運用手順書の不備についても、速やかに改善策を検討し、関係者への周知を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00833', 'INC-2024-00563', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-02T21:06:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T22:06:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00564', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-13T11:47:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T13:47:49+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2024年8月13日11時47分49秒に発生した棚卸突合失敗に関する障害報告です。本障害は、顧客店舗POSにおいて、マスター更新と在庫が二重反映される事象が確認されました。特に、定例リリース直後という契機に発生したことが影響していると考えられます。これにより、同一顧客の全店舗において在庫情報に混乱が生じ、正確な棚卸が行えない状況に至りました。エラーコードはSYNC-01-00564であり、この問題の解決には迅速な対応が求められます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00564', 'INC-2024-00564', '本事象の調査を進めた結果、定例リリース直後に発生したことが主要因であると考えます。特に、イベント順序の逆転配信が疑われ、これによりマスター更新と在庫が重複して反映される状況が生じました。今後、同様の問題を防ぐため、リリース前のテストや確認作業を強化する必要があります。', '本事象の調査を進めた結果、定例リリース直後に発生したことが主要因であると考えます。特に、イベント順序の逆転配信が疑われ、これによりマスター更新と在庫が重複して反映される状況が生じました。今後、同様の問題を防ぐため、リリース前のテストや確認作業を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-14T13:47:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00834', 'INC-2024-00564', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-13T14:02:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T15:02:49+09:00', '【初期対応】【データ同期・整合性障害】マスター在庫二重反映', '2024年8月13日15時07分49秒に本障害を検知しました。営業部の花子が初期対応を開始し、影響範囲を確認しました。まず、影響を受けた全店舗に連絡を取り、事象の詳細を伝えました。また、エンジニアチームを招集し、早急な原因調査を開始しました。今後の対策として、システムのログを確認し、イベント順序の検証を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00835', 'INC-2024-00564', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-13T15:32:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T16:32:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00574', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-10T00:19:10+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T01:19:10+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年8月10日00時19分10秒に株式会社ストッククラウドの顧客ネットワークにおいて、SD-WANが劣化回線を選択したことにより遅延が増大するという障害が発生しました。この障害は、同一顧客の全店舗に影響を及ぼしました。発生契機は大規模セール開始直前であり、顧客拠点NWと拠点VPNゲートウェイが影響を受けました。検知は01時35分10秒に行われ、発見者は営業部の花子でした。現在、SD-WANポリシーの閾値設定誤りが推定原因として疑われています。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00574', 'INC-2024-00574', '障害発生の原因として、SD-WANポリシーの閾値設定が誤っていることが疑われています。調査により、SD-WANが劣化回線を選択することが確認され、これにより遅延が発生しました。今後はポリシー設定の見直しと、監視システムの強化が必要です。大規模セールという特別なトラフィック状況において、適切な経路が選択されるよう改善を図ります。', '障害発生の原因として、SD-WANポリシーの閾値設定が誤っていることが疑われています。調査により、SD-WANが劣化回線を選択することが確認され、これにより遅延が発生しました。今後はポリシー設定の見直しと、監視システムの強化が必要です。大規模セールという特別なトラフィック状況において、適切な経路が選択されるよう改善を図ります。', TIMESTAMP WITH TIME ZONE '2024-08-11T01:19:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00849', 'INC-2024-00574', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-10T01:34:10+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T02:34:10+09:00', '【初期対応】【顧客ネットワーク障害】SD-WAN経路選択誤りの初期対応', 'インシデント発生直後、営業部の花子が事象を検知し、技術チームにエスカレーションしました。技術チームは直ちに問題の切り分けを開始し、SD-WANの設定を確認しました。劣化回線の選択が確認された後、ポリシーの調整を行い、正常な経路選択に戻るよう対応を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00575', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-13T12:06:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T13:06:46+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2024年8月13日12時06分46秒、株式会社ストッククラウドの顧客拠点NWにおいて、顧客固定IP変更が許可リストに未反映の問題が発生しました。この問題により、単一店舗のみが影響を受けており、顧客ネットワークの正常な運用が妨げられています。発見者は営業部の花子で、発生契機は顧客のオンボーディング当日です。このような事象が発生する背景には、IP許可リストの更新漏れが推定されます。エラーコードはNW-07-00575です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00575', 'INC-2024-00575', 'インシデント発生後の調査では、顧客の固定IP変更が許可リストに未反映であることが確認されました。これは、顧客オンボーディングの際にIP許可リストの更新が行われなかったためと考えられます。今後、このような事象を防ぐため、顧客オンボーディングプロセスの見直しを検討する必要があります。', 'インシデント発生後の調査では、顧客の固定IP変更が許可リストに未反映であることが確認されました。これは、顧客オンボーディングの際にIP許可リストの更新が行われなかったためと考えられます。今後、このような事象を防ぐため、顧客オンボーディングプロセスの見直しを検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-14T13:06:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00850', 'INC-2024-00575', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-13T13:21:46+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T14:21:46+09:00', '【初動対応】【顧客ネットワーク障害】固定IP変更未連絡', '営業部の花子です。顧客固定IPの変更が許可リストに未反映なため、直ちに顧客に連絡を取り、影響を確認します。また、IP許可リストの更新作業を急いで行います。問題が解決次第、改めて報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00580', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-07-11T19:11:43+09:00', TIMESTAMP WITH TIME ZONE '2024-07-11T19:26:43+09:00', '【障害報告】【運用操作・権限障害】監査ログ出力停止', '2024年7月11日19時11分43秒、株式会社ストッククラウドの運用コンソールにおいて、顧客である架空食品店B及び架空食品店Aに対して監査ログの外部出力が停止している事象が発生しました。この障害は運用部の運用 一郎が発見し、検知までに14分を要しました。原因としては年末年始の稼働切替時にログシッパーの認証トークンが期限切れとなり、監査ログの外部出力ができなくなったと推測されます。影響範囲はバッチ処理のみであり、オンラインサービスには影響がありませんでした。エラーコードはOPS-09-00580です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00580', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00580', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00580', 'INC-2024-00580', '調査の結果、監査ログの外部出力が停止している原因は、ログシッパーの認証トークンが期限切れとなったためであることが確認されました。年末年始の稼働切替時に発生した本事象は、運用コンソールの監査ログコレクタに影響を及ぼしました。確認した技術的詳細には、監査ログシッパーの設定を見直し、権限障害の解消を図る必要があることが含まれています。', '調査の結果、監査ログの外部出力が停止している原因は、ログシッパーの認証トークンが期限切れとなったためであることが確認されました。年末年始の稼働切替時に発生した本事象は、運用コンソールの監査ログコレクタに影響を及ぼしました。確認した技術的詳細には、監査ログシッパーの設定を見直し、権限障害の解消を図る必要があることが含まれています。', TIMESTAMP WITH TIME ZONE '2024-07-12T19:26:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00857', 'INC-2024-00580', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-07-11T19:41:43+09:00', TIMESTAMP WITH TIME ZONE '2024-07-11T20:41:43+09:00', '【初期対応】【運用操作・権限障害】監査ログ出力停止初期対応', '初期対応として、運用部はログシッパーの認証トークンの更新を行い、監査ログの外部出力を再開する手続きを実施しました。また、影響を受けた顧客には迅速に状況を報告し、必要な情報を提供しました。今後は、認証トークンの管理を徹底し、同様の事象が再発しないよう、運用フローの見直しを検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00858', 'INC-2024-00580', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-07-11T21:11:43+09:00', TIMESTAMP WITH TIME ZONE '2024-07-11T22:11:43+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00581', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-10-01T12:28:46+09:00', TIMESTAMP WITH TIME ZONE '2024-10-01T14:28:46+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2024年10月1日12時28分46秒に発生した棚卸突合失敗について報告します。影響範囲は全テナントに波及し、顧客店舗POSにおいて分散トランザクションがタイムアウトし、片側のみコミットされる事象が発生しました。本事象の発生契機は、大規模セール開始直前であり、特に2PCタイムアウト設定が過短であったことが推定されます。検知は14時56分46秒に行われ、148分間の間に問題が続きました。この事象は在庫計算エンジンにも影響を及ぼし、業務に支障を来たしました。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00581', 'INC-2024-00581', '本事象の調査を行った結果、分散トランザクションがタイムアウトした原因は、2PCタイムアウト設定の過短に起因することが明らかになりました。大規模セール開始前の特異なトラフィックが影響し、タイムアウト設定を見直す必要があると考えられます。今後は、設定値の適正化を図り、再発防止策を講じることが急務です。また、データ同期・整合性障害の全容を把握し、影響を受けた全テナントに対する対応を検討します。', '本事象の調査を行った結果、分散トランザクションがタイムアウトした原因は、2PCタイムアウト設定の過短に起因することが明らかになりました。大規模セール開始前の特異なトラフィックが影響し、タイムアウト設定を見直す必要があると考えられます。今後は、設定値の適正化を図り、再発防止策を講じることが急務です。また、データ同期・整合性障害の全容を把握し、影響を受けた全テナントに対する対応を検討します。', TIMESTAMP WITH TIME ZONE '2024-10-02T14:28:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00859', 'INC-2024-00581', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-10-01T14:43:46+09:00', TIMESTAMP WITH TIME ZONE '2024-10-01T15:43:46+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウトへの対応', '本事象に対し、初期対応として全ての関連システムを確認し、分散トランザクションの状態をモニタリングしました。また、2PCタイムアウト設定の見直しを行い、設定値の変更を実施しました。顧客への影響を最小限に抑えるために、関連部署と連携し、業務を継続できるよう努めました。今後は、定期的なシステム監視体制を強化し、再発防止に向けた取り組みを推進します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00860', 'INC-2024-00581', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-10-01T16:13:46+09:00', TIMESTAMP WITH TIME ZONE '2024-10-01T17:13:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00585', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-05T03:42:37+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T04:12:37+09:00', '【障害報告】【在庫マスター設定障害】在庫APIタイムアウト', '2024年8月5日03:42:37に、株式会社ストッククラウドのVenusにおいて在庫登録APIが30秒超でタイムアウトするという事象が発生しました。この障害は、特定リージョンのユーザーに影響を及ぼしました。発生の契機は大規模セール開始直前であり、推定原因として税率テーブルの不整合が考えられます。原因究明のため、運用部の運用 一郎が発見者として問題を確認しました。検知は04:27:37に行われ、発見から検知まで45分の遅延がありました。今後、税率設定の整合性を確認し、再発防止策を講じる必要があります。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00585', 'INC-2024-00585', '本障害について調査した結果、在庫登録APIがタイムアウトした原因は税率テーブルの不整合であることが判明しました。この問題は大規模セール開始直前に発生し、適切な税率が適用されていないためにAPIが正しく機能しなかったことが主な要因でした。従って、当該設定の見直しと検証が必要であると言えます。', '本障害について調査した結果、在庫登録APIがタイムアウトした原因は税率テーブルの不整合であることが判明しました。この問題は大規模セール開始直前に発生し、適切な税率が適用されていないためにAPIが正しく機能しなかったことが主な要因でした。従って、当該設定の見直しと検証が必要であると言えます。', TIMESTAMP WITH TIME ZONE '2024-08-06T04:12:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00866', 'INC-2024-00585', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-05T04:27:37+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T05:27:37+09:00', '初期対応', '事象発生後、運用部はすぐに調査を開始し、問題の影響範囲を特定しました。税率テーブルの不整合が確認され、関連する設定がすぐに修正されました。影響を受けたユーザーには通知を行い、今後同様の問題を防ぐための対策を協議しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00867', 'INC-2024-00585', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-05T05:57:37+09:00', TIMESTAMP WITH TIME ZONE '2024-08-05T06:57:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00586', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-11T15:47:08+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T16:32:08+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2024年8月11日15時47分に発生したストレージ溢れによる障害について報告します。主要メトリクス系列が15分間欠損し、運用部門に影響を及ぼしました。発見者は運用 一郎で、問題はMercury AWS Storageに関連しています。エラーコードはMON-04-00586です。発生契機としてインフラメンテナンス明けが挙げられ、メトリクスエージェントの再起動失敗が推定されます。この問題は、運用部門の監視・可用性に深刻な影響を与えました。原因の特定と対策の実施が急務です。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00586', 'INC-2024-00586', '本障害の原因調査を実施しました。主要メトリクス系列の欠損は、インフラメンテナンス明けに発生しました。メトリクスエージェントの再起動が失敗し、監視データが収集できなかったことが主な原因です。運用部門への影響範囲が限定的だったものの、メトリクス欠損は運用監視において重大な問題であるため、再発防止策を講じる必要があります。', '本障害の原因調査を実施しました。主要メトリクス系列の欠損は、インフラメンテナンス明けに発生しました。メトリクスエージェントの再起動が失敗し、監視データが収集できなかったことが主な原因です。運用部門への影響範囲が限定的だったものの、メトリクス欠損は運用監視において重大な問題であるため、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-12T16:32:08+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00868', 'INC-2024-00586', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-11T16:47:08+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T17:47:08+09:00', '【初動対応】【監視・可用性障害】メトリクス欠損', '初動対応として、メトリクスエージェントの状態を確認しました。再起動を試みましたが、再び失敗しました。運用 一郎は、迅速にエンジニアリングチームにエスカレーションし、根本原因の特定を依頼しました。運用部門としては、欠損データへの対応策として代替監視手段の検討を始めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00587', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-13T20:02:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T20:32:38+09:00', '【障害報告】【CLU-09】クロスリージョンレプリケーション', '2024年8月13日20時02分38秒に発生したインシデントは、株式会社ストッククラウドのサービスVenusにおいて、クロスリージョン複製が片系のみ更新される現象が確認されました。これは、特定リージョンのユーザーに影響を及ぼし、エラーコードはSYNC-07-00587です。インフラメンテナンス明けに発生したため、リージョンルーティングの誤設定が推定原因として考えられています。影響を受けたコンポーネントはMercury AWS AP（DRサイト）及びレプリケーションゲートウェイであり、データ同期・整合性障害が発生しています。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00587', 'INC-2024-00587', 'インフラメンテナンス明けに確認されたクロスリージョン複製の問題について、詳細な調査が実施されました。調査の結果、リージョンルーティングの誤設定が原因である可能性が高いことが判明しました。このため、特定リージョンにおいてデータが正しく同期されていない状況が発生しています。今後、設定の見直しとともに、再発防止策を検討する必要があります。', 'インフラメンテナンス明けに確認されたクロスリージョン複製の問題について、詳細な調査が実施されました。調査の結果、リージョンルーティングの誤設定が原因である可能性が高いことが判明しました。このため、特定リージョンにおいてデータが正しく同期されていない状況が発生しています。今後、設定の見直しとともに、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-14T20:32:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00869', 'INC-2024-00587', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-13T20:47:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T21:47:38+09:00', '初期対応状況', 'インシデント発生直後に運用部の運用 一郎が状況を確認し、影響範囲を特定しました。初期対応として、リージョンルーティングの設定確認を行い、必要に応じて修正を進めました。影響を受けるユーザーへの周知も行い、状況を報告しました。今後の対応については、再発防止策の検討を含む改善計画を策定していきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00870', 'INC-2024-00587', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-13T22:17:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-13T23:17:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00589', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-07-31T20:41:25+09:00', TIMESTAMP WITH TIME ZONE '2024-07-31T20:56:25+09:00', '【障害報告】【運用操作・権限障害】監視画面真っ白', '2024年7月31日20時41分25秒、株式会社ストッククラウドの運用コンソールにおいて、監視ダッシュボードが真っ白でメトリクスが非表示となる事象が発生しました。発見者は運用部の運用 一郎であり、問題は定例リリース直後に発生しました。影響範囲は運用部門のみで、エラーコードはOPS-04-00589です。技術詳細として、グラフクエリの時間範囲パラメータの誤設定が原因として疑われています。この問題により、監視業務に影響を及ぼしているため、早急な対応が求められます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00589', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00589', 'INC-2024-00589', '2024年7月31日20時57分25秒に本障害が検知されました。監視ダッシュボードの状態を確認したところ、メトリクスが全く表示されていないことが確認されました。定例リリース直後に発生しており、グラフクエリの時間範囲パラメータの誤設定が原因である可能性が高いことが判明しました。運用部門に対して影響が及んでいるため、迅速な対応が必要です。', '2024年7月31日20時57分25秒に本障害が検知されました。監視ダッシュボードの状態を確認したところ、メトリクスが全く表示されていないことが確認されました。定例リリース直後に発生しており、グラフクエリの時間範囲パラメータの誤設定が原因である可能性が高いことが判明しました。運用部門に対して影響が及んでいるため、迅速な対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-01T20:56:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00873', 'INC-2024-00589', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-07-31T21:11:25+09:00', TIMESTAMP WITH TIME ZONE '2024-07-31T22:11:25+09:00', '【初動対応】【運用操作・権限障害】監視画面真っ白', '初動対応として、運用部門に対して監視ダッシュボードの障害状況を報告し、グラフクエリの時間範囲パラメータを確認するよう指示しました。また、運用コンソールの設定を見直す作業を同時に進め、問題の原因を特定するためにデータのログを分析しました。運用部全体での監視機能回復に向けた行動を速やかに進めることが重要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00594', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-11-14T04:21:18+09:00', TIMESTAMP WITH TIME ZONE '2024-11-14T04:36:18+09:00', '【障害報告】【運用操作・権限障害】手動設定編集事故', '2024年11月14日04時21分18秒、株式会社ストッククラウドのサービスMercuryにおいて、運用コンソールで設定ファイル手動編集を行った際に必須キーが欠落したことが原因で、サービス全体の一部機能に影響が及んだ。運用部の運用 一郎が発見し、04時33分18秒に検知。インフラメンテナンス明けの作業中に発生した可能性が高いと考えられる。現時点での影響範囲、エラーコードOPS-07-00594については、さらなる調査が必要である。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00594', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00594', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00594', 'INC-2024-00594', '調査を進めた結果、設定ファイルの手動編集時に必須キーが欠落していたことが確認された。このミスが原因で運用コンソールと設定管理DBに影響を及ぼし、サービス全体の一部機能に障害を引き起こした。引き続き、手動編集のプロセスを見直し、再発防止策を検討していく必要がある。', '調査を進めた結果、設定ファイルの手動編集時に必須キーが欠落していたことが確認された。このミスが原因で運用コンソールと設定管理DBに影響を及ぼし、サービス全体の一部機能に障害を引き起こした。引き続き、手動編集のプロセスを見直し、再発防止策を検討していく必要がある。', TIMESTAMP WITH TIME ZONE '2024-11-15T04:36:18+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00880', 'INC-2024-00594', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-14T04:51:18+09:00', TIMESTAMP WITH TIME ZONE '2024-11-14T05:51:18+09:00', '初期対応', '初期対応として、運用部が設定ファイルの変更履歴を確認し、どの部分で必須キーが欠落したのかを特定した。また、影響を受けた機能については一時的な回避策を実施し、サービスの運用を継続できるようにした。専門チームによる詳細な原因分析と再発防止策の策定に着手している。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00881', 'INC-2024-00594', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-14T06:21:18+09:00', TIMESTAMP WITH TIME ZONE '2024-11-14T07:21:18+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00597', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-14T12:26:54+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T12:56:54+09:00', '【障害報告】【CLU-08】JWT署名鍵ローテ漏れ', '2024年8月14日12時26分54秒、株式会社ストッククラウドのVenusサービスにおいて、JWT署名鍵ローテ後に旧トークンの検証が失敗する事象が発生しました。発生契機はインフラメンテナンス明けで、全テナントに波及する影響が確認されています。この問題は、JWTと署名鍵のローテーションに関連するもので、鍵ローテの段階的切替が未実施であったことが推測されます。発見者は運用部の運用 一郎であり、問題の検知は12時46分54秒でした。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00597', 'INC-2024-00597', 'JWT署名鍵ローテ後に旧トークンの検証が失敗する事象について調査を行いました。インフラメンテナンス明けに発生したことから、鍵ローテの段階的切替未実施が要因として浮上しました。現在、影響範囲は全テナントに及び、再発防止策として鍵ローテ手順の見直しが必要です。', 'JWT署名鍵ローテ後に旧トークンの検証が失敗する事象について調査を行いました。インフラメンテナンス明けに発生したことから、鍵ローテの段階的切替未実施が要因として浮上しました。現在、影響範囲は全テナントに及び、再発防止策として鍵ローテ手順の見直しが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-15T12:56:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00884', 'INC-2024-00597', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-14T13:11:54+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T14:11:54+09:00', '【初期対応】【CLU-08】JWT署名鍵ローテ漏れ', '第1の初期対応として、運用部の運用 一郎が直ちに対応を開始しました。関係者への周知を行い、最新のJWT署名鍵ローテーション手順の確認を行いました。また、影響を受けるテナントへの通知を実施し、旧トークンの使用停止を促しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00885', 'INC-2024-00597', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-14T14:41:54+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T15:41:54+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00600', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-22T10:21:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T12:21:38+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '2024年8月22日10時21分に、株式会社ストッククラウドのVenusサービスにおいて棚卸突合失敗が発生しました。この障害は顧客店舗POSに関連し、CDCイベント欠損で下流倉庫が未更新となっております。発見者は営業部の花子であり、検知は11時51分に行われました。発生契機はデータ移行バッチ実行中であり、影響範囲はバッチ処理のみでオンラインには影響がありません。エラーコードはSYNC-03-00600で、技術詳細としてはCDCコネクタのオフセット巻戻しが原因と考えられています。この問題により、倉庫のデータ同期・整合性が損なわれました。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00600', 'INC-2024-00600', '発生した障害について調査を行った結果、CDCイベント欠損が確認されました。この影響により下流倉庫が未更新となっており、データ移行バッチ実行中に発生したことがわかりました。原因はCDCコネクタのオフセット巻戻しであると推測され、今後の対策としてはCDCの監視を強化し、再発防止策を検討する必要があります。', '発生した障害について調査を行った結果、CDCイベント欠損が確認されました。この影響により下流倉庫が未更新となっており、データ移行バッチ実行中に発生したことがわかりました。原因はCDCコネクタのオフセット巻戻しであると推測され、今後の対策としてはCDCの監視を強化し、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-23T12:21:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00888', 'INC-2024-00600', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-22T12:36:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T13:36:38+09:00', '【初期対応】CDCイベント欠損', '初期対応として、CDCイベント欠損の原因調査を開始しました。営業部の花子が発見したため、迅速に事象を報告し、技術チームと連携を取っています。また、影響を受けた倉庫の状態を確認するためのログ解析を行い、必要に応じてデータの再取得を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00601', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-22T15:09:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T15:39:40+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '2024年8月22日15時09分40分に、株式会社ストッククラウドのサービスVenusにおいて、在庫登録APIの更新失敗が発生しました。症状として楽観ロック競合が多発し、更新失敗率が上昇しました。本事象は大規模セール開始直前に発生し、全テナントに波及する影響を及ぼしました。推定される原因は、バージョンカラム更新ロジックの不備です。検知は15時41分40分に行われ、検知までに32分を要しました。影響コンポーネントはMercury AWS AP（Secondary）であり、エラーコードはSYNC-10-00601です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00601', 'INC-2024-00601', '調査の結果、楽観ロック競合が多発した理由は、バージョンカラム更新ロジックに不備があったためと考えられます。この問題は、在庫登録APIの設計上の欠陥が原因で発生したものであり、特に大規模セールを控えたタイミングで発生しました。今後、同様の事象が発生しないよう、ロジックの見直しとテストが必要です。', '調査の結果、楽観ロック競合が多発した理由は、バージョンカラム更新ロジックに不備があったためと考えられます。この問題は、在庫登録APIの設計上の欠陥が原因で発生したものであり、特に大規模セールを控えたタイミングで発生しました。今後、同様の事象が発生しないよう、ロジックの見直しとテストが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-23T15:39:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00889', 'INC-2024-00601', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-22T15:54:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T16:54:40+09:00', '【初期対応】【CLU-09】楽観ロック競合多発', '初期対応として、運用部の運用 一郎が状況を確認し、楽観ロック競合の発生原因を調査しました。顧客への影響を最小限に抑えるため、一時的な対策として在庫登録APIの使用を制限しました。引き続き、根本原因の特定と恒久的な解決策の検討を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00602', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-11-21T21:27:17+09:00', TIMESTAMP WITH TIME ZONE '2024-11-21T21:57:17+09:00', '【障害報告】【CLU-06】キャッシュヒット率低下', '2024年11月21日21時27分17秒に、株式会社ストッククラウドのVenusサービスにおいて、利用者増による応答遅延が発生しました。発生直後よりキャッシュヒット率が低下し、DB負荷が増加する事象が確認されました。この障害は、全テナントに波及する影響を及ぼしており、特にVenus Azure APのキャッシュレイヤにおいて顕著な問題が見受けられます。エラーコードはPRF-09-00602で、定例リリース直後に発生したことから、インデックス未適用の新機能が推定原因として考えられます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00602', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00602', 'INC-2024-00602', '本障害の調査を進めた結果、定例リリース直後にキャッシュヒット率が低下したことが確認されました。この影響で、DBへの負荷が増加し、応答遅延が発生しています。現在、インデックス未適用の新機能が原因である可能性が高いと考えられ、今後の対応が必要です。', '本障害の調査を進めた結果、定例リリース直後にキャッシュヒット率が低下したことが確認されました。この影響で、DBへの負荷が増加し、応答遅延が発生しています。現在、インデックス未適用の新機能が原因である可能性が高いと考えられ、今後の対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-11-22T21:57:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00890', 'INC-2024-00602', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-21T22:12:17+09:00', TIMESTAMP WITH TIME ZONE '2024-11-21T23:12:17+09:00', '【初動対応】【CLU-06】キャッシュヒット率低下', '障害発生を受けて、運用部の運用一郎が初動対応を開始しました。エラーコードPRF-09-00602に基づき、システムのログ解析を行い、キャッシュヒット率低下の原因を特定すべく調査を進めています。また、全テナントへの影響を最小限に抑えるため、関連機能の停止等を検討しております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00891', 'INC-2024-00602', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-21T23:42:17+09:00', TIMESTAMP WITH TIME ZONE '2024-11-22T00:42:17+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00605', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-21T04:31:55+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T05:01:55+09:00', '【障害報告】【CLU-08】JWT署名鍵ローテ漏れ', '2024年8月21日04:31に、株式会社ストッククラウドのVenusサービスにおいてJWT署名鍵ローテ後に旧トークンの検証が失敗する事象が発生しました。検知は04:54に行われ、発生から検知までの時間は23分でした。今回の障害は、インフラメンテナンス明けに発生し、全テナントに波及する影響を及ぼしました。エラーコードはAUTH-07-00605で、影響を受けたコンポーネントはVenus Azure AP（ゾーンB）の認証サービスです。原因としては、鍵ローテの段階的切替が未実施であることが推定されます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00605', 'INC-2024-00605', '本事象の調査を行った結果、JWT署名鍵ローテ後に旧トークンの検証が失敗したことが確認されました。インフラメンテナンス明けに鍵ローテを実施しましたが、段階的な切替が行われていなかったため、全テナントに影響が及ぶ結果となりました。詳細なログ分析を行い、直ちに鍵ローテの手順を見直す必要があります。', '本事象の調査を行った結果、JWT署名鍵ローテ後に旧トークンの検証が失敗したことが確認されました。インフラメンテナンス明けに鍵ローテを実施しましたが、段階的な切替が行われていなかったため、全テナントに影響が及ぶ結果となりました。詳細なログ分析を行い、直ちに鍵ローテの手順を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-22T05:01:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00894', 'INC-2024-00605', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-21T05:16:55+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T06:16:55+09:00', '【対応ログ】【CLU-08】初期対応', '2024年8月21日04:55、運用部の運用 一郎が事象を確認し、影響範囲を調査するためのチームを編成しました。直ちにシステムの状態を確認し、影響を受けた全テナントに連絡を行い、トークンの更新を促しました。また、原因調査を開始し、再発防止策を検討することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00895', 'INC-2024-00605', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-21T06:46:55+09:00', TIMESTAMP WITH TIME ZONE '2024-08-21T07:46:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00606', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-09T23:12:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T23:42:26+09:00', '【障害報告】【在庫マスター設定障害】セット商品分解失敗', '2024年8月9日23時12分26秒に、株式会社ストッククラウドのVenusサービスにおいて、在庫マスター設定に関連する障害が発生いたしました。症状としては、セット商品の在庫分解時に構成エラーが発生しました。この事象は、定例リリース直後に発生し、検知までに44分を要しました。影響範囲は、同一顧客の全店舗に及び、エラーコードはMST-07-00606となります。技術的には、BOM構成テーブルの親子関係不整合が推定される原因とされています。再発防止に向けての対応が急務です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00606', 'INC-2024-00606', '障害発生後の調査において、定例リリース直後に発生したセット商品の在庫分解時に構成エラーが生じた原因として、BOM構成テーブルの親子関係不整合が疑われています。特に、在庫計算エンジンにおける処理が不適切であった可能性が高いと考えられます。このため、今後の対策としましては、BOM構成テーブルの見直し及び、リリース手順の再評価を実施する必要があります。', '障害発生後の調査において、定例リリース直後に発生したセット商品の在庫分解時に構成エラーが生じた原因として、BOM構成テーブルの親子関係不整合が疑われています。特に、在庫計算エンジンにおける処理が不適切であった可能性が高いと考えられます。このため、今後の対策としましては、BOM構成テーブルの見直し及び、リリース手順の再評価を実施する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-10T23:42:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00896', 'INC-2024-00606', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-09T23:57:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T00:57:26+09:00', '【初期対応】【在庫マスター設定障害】セット商品分解失敗', '障害発生直後に運用部の運用 一郎がアラートを受信し、状況を確認いたしました。在庫分解における構成エラーが見受けられたため、関連部門と連携し、初期対応として該当リリースのロールバックを実施しました。その後、技術的な詳細調査を行い、BOM構成テーブルの確認作業を進めることとなりました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00897', 'INC-2024-00606', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T01:27:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T02:27:26+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00607', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-02-17T09:32:52+09:00', TIMESTAMP WITH TIME ZONE '2024-02-17T10:02:52+09:00', '【障害報告】【在庫マスター設定障害】商品同期全件失敗', '2024年2月17日09時32分52秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店B及び架空食品店Aの顧客に対し、商品マスター同期後に在庫登録が全件失敗するという事象が発生いたしました。発生の契機は顧客オンボーディング当日であり、問題が発生した場所はMercury AWS APです。この影響により、サービス全体の一部機能に不具合が生じております。エラーコードはMST-04-00607であり、原因としてはカテゴリ階層の循環参照が推測されております。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00607', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00607', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00607', 'INC-2024-00607', '本障害に関し、運用部の運用 一郎が調査を行った結果、顧客オンボーディング当日における商品マスター同期が原因で在庫登録が全件失敗したことが確認されました。カテゴリ階層に循環参照が存在し、このことが在庫マスター設定に影響を及ぼした可能性が高いと考えられます。さらに、商品マスターDBにも影響が及んでいることが確認されており、早急な対応が求められます。', '本障害に関し、運用部の運用 一郎が調査を行った結果、顧客オンボーディング当日における商品マスター同期が原因で在庫登録が全件失敗したことが確認されました。カテゴリ階層に循環参照が存在し、このことが在庫マスター設定に影響を及ぼした可能性が高いと考えられます。さらに、商品マスターDBにも影響が及んでいることが確認されており、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2024-02-18T10:02:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00898', 'INC-2024-00607', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-17T10:17:52+09:00', TIMESTAMP WITH TIME ZONE '2024-02-17T11:17:52+09:00', '【初期対応】【在庫マスター設定障害】商品同期全件失敗', '問題の発覚後、運用部では直ちに対応を開始しました。まず、Mercury AWS APの設定を確認し、循環参照に関するログを精査しました。また、顧客への影響を最小限に抑えるため、暫定的な措置として在庫登録処理を一時停止し、問題の根本的な解決に向けた作業を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00899', 'INC-2024-00607', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-17T11:47:52+09:00', TIMESTAMP WITH TIME ZONE '2024-02-17T12:47:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00609', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-02-17T16:37:51+09:00', TIMESTAMP WITH TIME ZONE '2024-02-17T17:37:51+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '発生日時: 2024年2月17日 16:37
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00609', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00609', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00609', 'INC-2024-00609', '調査の結果、店舗DNSキャッシュが旧IPアドレスを返し続けている理由として、DNS TTL設定とキャッシュ方針の不一致が疑われます。このため、DNSリゾルバが以前のIPアドレスを保持し続けることが確認されました。影響の範囲は単一店舗に限られ、他の店舗には影響が出ていないことが分かりました。', '調査の結果、店舗DNSキャッシュが旧IPアドレスを返し続けている理由として、DNS TTL設定とキャッシュ方針の不一致が疑われます。このため、DNSリゾルバが以前のIPアドレスを保持し続けることが確認されました。影響の範囲は単一店舗に限られ、他の店舗には影響が出ていないことが分かりました。', TIMESTAMP WITH TIME ZONE '2024-02-18T17:37:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00902', 'INC-2024-00609', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-02-17T17:52:51+09:00', TIMESTAMP WITH TIME ZONE '2024-02-17T18:52:51+09:00', '【対応ログ】初期対応', '初期対応として、店舗のDNS設定を確認し、TTL値の適正を見直す作業を開始しました。また、DNSキャッシュのクリアを実施し、最新のIPアドレスが返されることを確認するプロセスを実施しました。顧客にも状況を報告し、問題解決までの進捗を共有しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00616', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-11-28T04:40:01+09:00', TIMESTAMP WITH TIME ZONE '2024-11-28T06:40:01+09:00', '【障害報告】【棚卸・POS突合障害】差異リスト空表示', '2024年11月28日04時40分、株式会社ストッククラウドの顧客店舗POSにて、棚卸差異リストが空表示になる事象が発生しました。データ移行バッチ実行中に、店舗端末での表示に問題が生じ、同一顧客の全店舗に影響を及ぼしました。推定原因として、店舗別在庫の集計粒度不一致が考えられます。この事象は0450時に発生し、095分後に06時15分に検知されました。影響コンポーネントには顧客店舗POS（Primary）および店舗在庫ビューが含まれます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00616', 'INC-2024-00616', '調査の結果、データ移行バッチ実行中に店舗端末で棚卸差異リストが空表示となる問題が確認されました。店舗別在庫の集計粒度に不一致があり、これが空表示の直接的な原因と推測されます。この問題は、顧客の全店舗に影響を及ぼし、業務に支障をきたす可能性があります。さらに詳細な分析を進め、早急に対策を講じる必要があります。', '調査の結果、データ移行バッチ実行中に店舗端末で棚卸差異リストが空表示となる問題が確認されました。店舗別在庫の集計粒度に不一致があり、これが空表示の直接的な原因と推測されます。この問題は、顧客の全店舗に影響を及ぼし、業務に支障をきたす可能性があります。さらに詳細な分析を進め、早急に対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-11-29T06:40:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00911', 'INC-2024-00616', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-11-28T06:55:01+09:00', TIMESTAMP WITH TIME ZONE '2024-11-28T07:55:01+09:00', '【初期対応】【棚卸・POS突合障害】差異リスト空表示', '初期対応として、関連するデータ移行バッチの状態を確認し、店舗別在庫の集計粒度の調整を行いました。また、店舗端末における表示の再確認を行い、問題が解消されるかを検証するための手順を実施しました。顧客店舗との連携を図り、必要に応じて追加のサポートを提供することを検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00619', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-11-01T08:59:07+09:00', TIMESTAMP WITH TIME ZONE '2024-11-01T09:14:07+09:00', '【障害報告】【運用操作・権限障害】監視画面真っ白', '2024年11月1日08時59分07分に、株式会社ストッククラウドの運用コンソールにおいて架空服飾店A向けに監視ダッシュボードが真っ白でメトリクス非表示のアクセス障害が発生しました。発生から15分後の09時14分07分に運用部の運用 一郎によって検知されました。定例リリース直後の出来事であり、本件の影響範囲は運用部門のみです。エラーコードはOPS-04-00619で、技術詳細としては、監視ダッシュボードのグラフクエリの時間範囲パラメータ誤設定が原因と考えられます。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00619', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00619', 'INC-2024-00619', '運用部門による調査の結果、監視ダッシュボードが真っ白でメトリクス非表示となった原因は、グラフクエリの時間範囲パラメータの誤設定であることが確認されました。定例リリース直後に発生し、影響を受けたのは運用部門のみでした。今後の再発防止策として、リリース前に設定内容の確認を徹底することが提案されます。', '運用部門による調査の結果、監視ダッシュボードが真っ白でメトリクス非表示となった原因は、グラフクエリの時間範囲パラメータの誤設定であることが確認されました。定例リリース直後に発生し、影響を受けたのは運用部門のみでした。今後の再発防止策として、リリース前に設定内容の確認を徹底することが提案されます。', TIMESTAMP WITH TIME ZONE '2024-11-02T09:14:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00915', 'INC-2024-00619', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-01T09:29:07+09:00', TIMESTAMP WITH TIME ZONE '2024-11-01T10:29:07+09:00', '【初動対応】【運用操作・権限障害】監視画面真っ白', '運用部では発生した監視ダッシュボードの真っ白状態について、速やかに各担当者で状況を確認し、グラフクエリの設定を見直しました。顧客への影響を最小限に抑えるため、エンジニアによる迅速な対応を行い、問題解決に向けて全力を尽くしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00916', 'INC-2024-00619', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-11-01T10:59:07+09:00', TIMESTAMP WITH TIME ZONE '2024-11-01T11:59:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00625', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-04-17T21:04:36+09:00', TIMESTAMP WITH TIME ZONE '2024-04-17T22:04:36+09:00', '【障害報告】【顧客ネットワーク障害】DNSキャッシュ汚染', '発生日時: 2024年4月17日 21:04
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00625', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00625', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00625', 'INC-2024-00625', '本インシデントは、顧客拠点NWにおいてDNSキャッシュが旧IPを返し続ける現象が発生したことに起因します。調査の結果、DNS TTL設定とキャッシュ方針の不一致が原因である可能性が高いことが確認されました。現在、影響を受けた店舗のDNS設定を見直す必要があります。', '本インシデントは、顧客拠点NWにおいてDNSキャッシュが旧IPを返し続ける現象が発生したことに起因します。調査の結果、DNS TTL設定とキャッシュ方針の不一致が原因である可能性が高いことが確認されました。現在、影響を受けた店舗のDNS設定を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2024-04-18T22:04:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00924', 'INC-2024-00625', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-04-17T22:19:36+09:00', TIMESTAMP WITH TIME ZONE '2024-04-17T23:19:36+09:00', '【初動対応】【顧客ネットワーク障害】DNSキャッシュ汚染', '初動対応として、影響を受けた架空食品店AのDNS設定を確認し、DNS TTLの設定値を見直しました。また、キャッシュのクリアを実施し、旧IPが返されないか再確認しました。顧客には状況を報告し、問題解決に向けた手続きを進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00627', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-14T16:02:21+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T16:17:21+09:00', '[障害報告][CLU-10]メトリクス欠損', '2024年8月14日16時02分21秒に、株式会社ストッククラウドのVenus運用コンソールにおいて、主要メトリクス系列が15分間欠損する事象が発生しました。本事象は運用部門に影響を及ぼし、発見者は運用 一郎（運用部）です。発生契機はインフラメンテナンス明けであり、メトリクスエージェントの再起動失敗が推定原因とされています。エラーコードはMON-04-00627で、検知は16時15分21秒であり、検知までに13分を要しました。この障害により、運用部門は重要なメトリクス情報を得られず、通常業務に支障を来しました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00627', 'INC-2024-00627', '本インシデントの調査を行った結果、メトリクスエージェントがインフラメンテナンス後に正常に再起動されなかったことが原因であると特定されました。このため、主要メトリクス系列が15分間欠損したことが確認され、運用部門にのみ影響が及びました。今後、メトリクスエージェントの再起動手順の見直しと、インフラメンテナンス後の確認プロセスの強化が必要です。', '本インシデントの調査を行った結果、メトリクスエージェントがインフラメンテナンス後に正常に再起動されなかったことが原因であると特定されました。このため、主要メトリクス系列が15分間欠損したことが確認され、運用部門にのみ影響が及びました。今後、メトリクスエージェントの再起動手順の見直しと、インフラメンテナンス後の確認プロセスの強化が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-15T16:17:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00926', 'INC-2024-00627', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-14T16:32:21+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T17:32:21+09:00', '[初期対応][CLU-10]メトリクス欠損', 'インシデント発生直後、運用部門では主要メトリクス系列が欠損していることを確認し、迅速にメトリクスエージェントの再起動を試みました。しかし、エージェントは正常に再起動できず、障害が持続しました。このため、運用 一郎が他の技術者と協力し、問題解決に向けた対策を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00630', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-03T01:07:03+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T03:07:03+09:00', '【障害報告】【棚卸・POS突合障害】棚卸ラベル印刷失敗', '2024年8月3日01:07:03に、株式会社ストッククラウドのVenusサービスにおいて、棚卸用ラベル印刷APIが404を返す事象が発生しました。発見者は営業部の花子で、影響を受けたのは顧客店舗POSです。エラーコードはINV-09-00630で、発生契機は月末棚卸の開始時でした。原因として、店舗プリンタ設定のテンプレートID誤りが推定され、影響範囲は単一店舗のみとなっています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00630', 'INC-2024-00630', '本事象についての調査では、月末棚卸の開始時に棚卸用ラベル印刷APIが404を返すことが確認されました。そのため、店舗プリンタの設定に誤りがあるテンプレートIDが使用されている可能性が高いと判断されました。今後、プリンタ設定の見直しを行い、再発防止策を検討する必要があります。', '本事象についての調査では、月末棚卸の開始時に棚卸用ラベル印刷APIが404を返すことが確認されました。そのため、店舗プリンタの設定に誤りがあるテンプレートIDが使用されている可能性が高いと判断されました。今後、プリンタ設定の見直しを行い、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-04T03:07:03+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00931', 'INC-2024-00630', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-03T03:22:03+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T04:22:03+09:00', '【初期対応】【棚卸・POS突合障害】棚卸ラベル印刷失敗', '事象発生後、直ちに営業部の花子が対応し、顧客店舗POSのプリンタ設定を確認しました。設定ミスが疑われるため、テンプレートIDの修正を実施し、正常動作の確認を行いました。今後は、棚卸時の印刷物の品質管理を強化する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00635', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-29T11:24:28+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T11:54:28+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2024年8月29日11時24分28秒に、株式会社ストッククラウドのVenusサービスにおいて、在庫マスター設定ミスによる在庫登録失敗が発生しました。症状として、在庫CSVの3行目以降が取込されない事象が確認されました。本件はデータ移行バッチ実行中に発生し、JANコード重複チェックの誤設定が推定原因として挙げられます。影響範囲はバッチ処理のみに留まり、オンラインには影響がありません。発見者は運用部の運用 一郎氏で、発生から検知までの時間は37分でした。エラーコードはMST-03-00635です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00635', 'INC-2024-00635', '本インシデントに関連する調査を実施しました。Mercury AWS APのバッチ取込ワーカーにおいて、データ移行バッチ実行中に在庫CSVの3行目以降が取込されないことが確認されました。これにより、JANコード重複チェックの設定ミスが原因であることが示唆されました。引き続き、設定内容の確認と必要な修正が求められます。', '本インシデントに関連する調査を実施しました。Mercury AWS APのバッチ取込ワーカーにおいて、データ移行バッチ実行中に在庫CSVの3行目以降が取込されないことが確認されました。これにより、JANコード重複チェックの設定ミスが原因であることが示唆されました。引き続き、設定内容の確認と必要な修正が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-30T11:54:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00937', 'INC-2024-00635', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-29T12:09:28+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T13:09:28+09:00', '初期対応', '初期対応として、運用部の運用 一郎氏が早急に問題の把握を行い、設定内容の確認作業を開始しました。また、影響を受けたデータの復旧作業も同時に進められました。関係者への情報共有を行い、今後の対応フローを策定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00938', 'INC-2024-00635', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-29T13:39:28+09:00', TIMESTAMP WITH TIME ZONE '2024-08-29T14:39:28+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00636', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-02T03:47:07+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T04:17:07+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2024年8月2日03時47分に、株式会社ストッククラウドのサービスVenusにおいて、マスター設定ミスによる在庫登録失敗が発生しました。今回の事象は、全テナントに波及するスナップショット復元後に在庫整合が崩れる症状が確認され、発生契機はデータ移行バッチの実行中でした。影響を受けたコンポーネントはMercury AWS AP（DRサイト）であり、バックアップ管理における整合性が損なわれました。推定原因として、復元ポイントのトランザクションログ欠落が考えられます。この問題を受けて、早急な対応が求められます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00636', 'INC-2024-00636', '本障害に関する調査を進めた結果、データ移行バッチ実行中に発生したスナップショット復元後に在庫整合が崩れたことが確認されました。原因としては、復元ポイントのトランザクションログが欠落していたことが挙げられます。この欠落により、データ同期が正しく行われず、全テナントに影響を及ぼす事態となりました。引き続き、詳細なログ分析を実施し、再発防止策を検討する必要があります。', '本障害に関する調査を進めた結果、データ移行バッチ実行中に発生したスナップショット復元後に在庫整合が崩れたことが確認されました。原因としては、復元ポイントのトランザクションログが欠落していたことが挙げられます。この欠落により、データ同期が正しく行われず、全テナントに影響を及ぼす事態となりました。引き続き、詳細なログ分析を実施し、再発防止策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-03T04:17:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00939', 'INC-2024-00636', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-02T04:32:07+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T05:32:07+09:00', '【初期対応】【データ同期・整合性障害】スナップショット復元不整合', '本インシデントに対し、初期対応として運用部の運用 一郎が状況を確認し、影響範囲を特定しました。在庫整合が崩れた原因を分析するため、関連するトランザクションログの調査を開始しました。また、全テナントへの影響を考慮し、必要に応じて復旧作業を検討する方針を決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00637', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-26T17:05:22+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T19:05:22+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2024年8月26日17:05に発生した棚卸突合失敗について報告します。症状として、POS連携の売上が翌営業日まで在庫に反映されない事象が確認されました。影響範囲は単一店舗に限定されています。この事象は、年末年始の稼働切替時に発生し、原因として前日締め処理の二重実行が推測されます。2024年8月26日18:46に検知、発見者は営業部の花子です。本件はエラーコードINV-02-00637に関連しています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00637', 'INC-2024-00637', '調査の結果、年末年始の稼働切替時に発生したPOS売上遅延の原因として、前日締め処理の二重実行が疑われます。この問題は、顧客店舗POSとPOS連携ハブに影響を及ぼしており、対策を講じる必要があります。今後、再発防止策を検討し、早急に対応を進めます。', '調査の結果、年末年始の稼働切替時に発生したPOS売上遅延の原因として、前日締め処理の二重実行が疑われます。この問題は、顧客店舗POSとPOS連携ハブに影響を及ぼしており、対策を講じる必要があります。今後、再発防止策を検討し、早急に対応を進めます。', TIMESTAMP WITH TIME ZONE '2024-08-27T19:05:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00940', 'INC-2024-00637', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-26T19:20:22+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T20:20:22+09:00', '【初期対応】【棚卸・POS突合障害】POS売上遅延反映', '初期対応として、事象を確認し直ちに影響を受けている店舗に通知を行いました。また、該当の締め処理を再確認し、必要に応じて修正を行いました。今後、再発しないようにプロセスの見直しを行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00941', 'INC-2024-00637', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-26T20:50:22+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T21:50:22+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00640', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-12T06:22:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T06:52:40+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2024年8月12日06時22分40秒に、株式会社ストッククラウドのVenusサービスにおいて、分散トランザクションがタイムアウトし、片側のみコミットされる事象が発生しました。この障害はMercury AWS APにおいて発生し、全テナントに波及する影響を及ぼしました。発見者は運用部の運用 一郎で、06時53分40秒に検知されました。今回の障害は大規模セール開始直前というタイミングで発生しており、エラーコードはSYNC-04-00640です。技術的には、分散トランザクションがタイムアウトした原因として、2PCタイムアウト設定の過短が疑われます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00640', 'INC-2024-00640', '本障害の調査を行った結果、分散トランザクションがタイムアウトする主な要因は、2PCタイムアウト設定の過短であることが明らかになりました。特に、大規模セール開始直前にトランザクションが集中したことによる負荷が影響しています。このような状況では、タイムアウトの設定を見直し、適切な値に調整することが必要です。今後は、同様の事象が発生しないよう、事前の負荷テストや評価を行うことが重要です。', '本障害の調査を行った結果、分散トランザクションがタイムアウトする主な要因は、2PCタイムアウト設定の過短であることが明らかになりました。特に、大規模セール開始直前にトランザクションが集中したことによる負荷が影響しています。このような状況では、タイムアウトの設定を見直し、適切な値に調整することが必要です。今後は、同様の事象が発生しないよう、事前の負荷テストや評価を行うことが重要です。', TIMESTAMP WITH TIME ZONE '2024-08-13T06:52:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00944', 'INC-2024-00640', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-12T07:07:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T08:07:40+09:00', '初期対応', '障害発生後、運用部は迅速に初期対応を実施しました。具体的には、システムの状況を確認し、分散トランザクションの設定を再確認しました。また、影響を受けたテナントへの通知を行い、状況の把握に努めました。初期対応の結果、一部のトランザクションのロールバックが実施され、影響を最小限に抑えることができました。今後は、障害発生を未然に防ぐために、タイムアウト設定の見直しを行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00945', 'INC-2024-00640', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-12T08:37:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T09:37:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00645', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-21T23:44:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T01:44:27+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2024年8月21日23時44分に、株式会社ストッククラウドのサービスVenusにおいて棚卸突合失敗の事象が発生しました。症状としては、マスター更新と在庫が二重反映される現象が確認されました。この問題は、同一顧客の全店舗に影響を及ぼしており、営業部の花子が発見しました。発生契機は定例リリース直後であり、影響コンポーネントには顧客店舗POSおよびイベントバスが含まれます。現在、原因としてイベント順序の逆転配信が疑われており、詳細な調査を進めております。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00645', 'INC-2024-00645', '本事象の調査にあたり、ログの解析を行いました。定例リリース後のタイミングで、マスター更新が在庫情報に対して逆転した順序で配信された可能性が考えられます。このため、更新されたデータが正確に反映されず、二重反映の症状が発生したと推定されます。データ同期の整合性を確保するための改善策を検討し、再発防止に向けて取り組んでおります。', '本事象の調査にあたり、ログの解析を行いました。定例リリース後のタイミングで、マスター更新が在庫情報に対して逆転した順序で配信された可能性が考えられます。このため、更新されたデータが正確に反映されず、二重反映の症状が発生したと推定されます。データ同期の整合性を確保するための改善策を検討し、再発防止に向けて取り組んでおります。', TIMESTAMP WITH TIME ZONE '2024-08-23T01:44:27+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00953', 'INC-2024-00645', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-22T01:59:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T02:59:27+09:00', '初期対応', '本事象に関しては、初期対応として関連システムの状態を確認し、二重反映の影響を受けたデータを手動で修正する作業を開始しました。また、マスター更新の順序を確認するために、関連するイベントログの詳細な解析を実施しました。今後の対応として、データ同期プロセスの見直しを検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00954', 'INC-2024-00645', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-22T03:29:27+09:00', TIMESTAMP WITH TIME ZONE '2024-08-22T04:29:27+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00646', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-01T21:22:56+09:00', TIMESTAMP WITH TIME ZONE '2024-08-01T23:22:56+09:00', '【障害報告】【API連携・EDI障害】配送連携ステータス停滞', '2024年8月1日21時22分56秒に、株式会社ストッククラウドのサービス「Venus」において、配送連携のステータスが出荷済みで停滞する障害が発生しました。発生個所は顧客店舗POSであり、影響範囲は単一店舗のみです。本障害は大規模セール開始直前に発生し、検知までに165分を要しました。発見者は営業部の花子です。推定原因としては、ステータスマッピング表の更新漏れが考えられます。今後の対応が必要です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00646', 'INC-2024-00646', '本障害について調査を実施した結果、大規模セール開始直前に配送連携のステータスが出荷済みで停滞していることが確認されました。原因としてステータスマッピング表の更新漏れが疑われ、経過時間を含めた影響度の評価も行いました。この問題は顧客店舗POS（DRサイト）および配送連携アダプタに影響を及ぼしています。', '本障害について調査を実施した結果、大規模セール開始直前に配送連携のステータスが出荷済みで停滞していることが確認されました。原因としてステータスマッピング表の更新漏れが疑われ、経過時間を含めた影響度の評価も行いました。この問題は顧客店舗POS（DRサイト）および配送連携アダプタに影響を及ぼしています。', TIMESTAMP WITH TIME ZONE '2024-08-02T23:22:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00955', 'INC-2024-00646', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-01T23:37:56+09:00', TIMESTAMP WITH TIME ZONE '2024-08-02T00:37:56+09:00', '【初期対応】【API連携・EDI障害】配送連携ステータス停滞に対する初動対応', '初期対応として、ステータスマッピング表の内容を確認し、更新漏れが発生している箇所を特定しました。その後、必要な修正を行い、配送連携のステータスが正常に遷移することを確認しました。また、今後同様の事象を防ぐために、マッピング表の更新を定期的に確認する体制を整えることを提案いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00652', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-01-25T06:19:19+09:00', TIMESTAMP WITH TIME ZONE '2024-01-25T06:34:19+09:00', '【障害報告】【運用操作・権限障害】監視画面真っ白', '2024年1月25日06:19:19に発生したインシデントについて報告します。顧客は架空食品店Aおよび架空食品店Bで、運用 一郎が発見しました。運用コンソールにおいて監視ダッシュボードが真っ白になり、メトリクスが非表示となっています。このことにより、全ての運用部門に影響が出ており、正常な運用操作が困難な状況です。発生契機は定例リリース直後であり、エラーコードはOPS-04-00652です。調査の結果、グラフクエリの時間範囲パラメータが誤設定されたことが原因として推定されています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00652', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00652', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00652', 'INC-2024-00652', '運用操作・権限障害に関する調査を実施しました。監視ダッシュボードが真っ白になる事象は、グラフクエリの時間範囲パラメータの誤設定によるものと考えられます。この設定ミスにより、メトリクスが全く表示されなくなっています。影響範囲は運用部門のみで、迅速な対応が求められています。', '運用操作・権限障害に関する調査を実施しました。監視ダッシュボードが真っ白になる事象は、グラフクエリの時間範囲パラメータの誤設定によるものと考えられます。この設定ミスにより、メトリクスが全く表示されなくなっています。影響範囲は運用部門のみで、迅速な対応が求められています。', TIMESTAMP WITH TIME ZONE '2024-01-26T06:34:19+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00963', 'INC-2024-00652', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-01-25T06:49:19+09:00', TIMESTAMP WITH TIME ZONE '2024-01-25T07:49:19+09:00', '初期対応ログ', 'インシデント発生後、運用部門は即座に対応を開始しました。監視ダッシュボードの状態を確認し、誤設定されていたグラフクエリの時間範囲パラメータを修正しました。修正後、メトリクスは正常に表示されるようになり、運用部門の業務を再開することができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00964', 'INC-2024-00652', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-01-25T08:19:19+09:00', TIMESTAMP WITH TIME ZONE '2024-01-25T09:19:19+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00662', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-24T16:24:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T16:54:32+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2024年8月24日16時24分32分頃、株式会社ストッククラウドのVenusサービスにおいて、死活監視が正常系をDOWNと誤検知する事象が発生しました。死活監視が正常に機能せず、運用部門に影響を及ぼしました。エラーコードはMON-01-00662です。定例リリース直後の発生であり、運用部門の監視ツールに異常が見受けられました。恐れ入りますが、原因の特定と解決に向けた調査を行っております。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00662', 'INC-2024-00662', '本事象は、定例リリース直後に発生した死活監視の誤検知によるものと推定されます。監視プローブのUser-Agentがブロックされていた可能性があり、そのため正常な通信がDOWNと誤認識されていると考えられます。運用部門への影響が限定的であったため、即時のユーザーへの通知は行われておりませんが、今後の再発防止策を講じる必要があります。', '本事象は、定例リリース直後に発生した死活監視の誤検知によるものと推定されます。監視プローブのUser-Agentがブロックされていた可能性があり、そのため正常な通信がDOWNと誤認識されていると考えられます。運用部門への影響が限定的であったため、即時のユーザーへの通知は行われておりませんが、今後の再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-25T16:54:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00978', 'INC-2024-00662', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-24T17:09:32+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T18:09:32+09:00', '初期対応', '運用部門において、死活監視の正常動作を確認するための初期調査を実施しました。監視ログを精査し、User-Agentブロックの有無を確認しました。問題が確認されたため、暫定的に監視プローブの設定を変更し、正常系の復旧を図りました。再発防止策についても検討を行っております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00665', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-06T07:49:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T09:49:51+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '株式会社ストッククラウドのVenusサービスにおいて、2024年8月6日07時49分51秒に棚卸突合失敗が発生しました。この問題は、顧客店舗POSにおける分散トランザクションがタイムアウトし、片側のみがコミットされる事象によるものです。特に、大規模セール開始直前に発生したため、全テナントに波及する影響があり、在庫計算エンジンにも影響を及ぼしました。エラーコードはSYNC-04-00665で、原因として2PCタイムアウト設定の過短が推定されています。検知は同日10時44分51秒に行われ、発見者は営業部の花子です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00665', 'INC-2024-00665', '調査の結果、分散トランザクションがタイムアウトした原因は、2PCタイムアウト設定が過短であったことに起因することが明らかとなりました。大規模セール開始直前に発生したため、トランザクションにかかる負荷が増大し、タイムアウトが引き起こされました。この問題は、全テナントに影響を及ぼしたため、早急な対応が必要でした。今後は設定の見直しや、負荷テストを行うことで、同様の問題を未然に防ぐ施策を講じる必要があり', '調査の結果、分散トランザクションがタイムアウトした原因は、2PCタイムアウト設定が過短であったことに起因することが明らかとなりました。大規模セール開始直前に発生したため、トランザクションにかかる負荷が増大し、タイムアウトが引き起こされました。この問題は、全テナントに影響を及ぼしたため、早急な対応が必要でした。今後は設定の見直しや、負荷テストを行うことで、同様の問題を未然に防ぐ施策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-07T09:49:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00983', 'INC-2024-00665', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-06T10:04:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-06T11:04:51+09:00', '【初動対応】【データ同期・整合性障害】分散トランザクションタイムアウトへの初動対応', '初動対応として、2024年8月6日10時44分51秒に問題を検知しました。営業部の花子が発見者となり、直ちに技術チームにエスカレーションしました。技術チームは、手動でのトランザクション再実行を実施し、影響を受けた全テナントに対して状況を報告しました。また、タイムアウト設定の見直しを進めるための会議を開催し、次のステップについて協議を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00666', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-26T01:54:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T03:54:47+09:00', '【障害報告】【データ同期・整合性障害】アウトボックス滞留', '2024年8月26日01時54分47秒に発生した棚卸突合失敗に関してご報告いたします。発生場所は顧客店舗POSであり、影響範囲としてはサービス全体の一部機能に影響を及ぼしております。主な症状はアウトボックステーブル滞留による通知遅延であり、根本原因としてアウトボックスポーラーの停止が推定されます。本事象は定例リリース直後に発生したため、リリースの影響が疑われます。発見者は営業部の花子であり、検知時刻は03時22分47秒で、発生から検知までの時間は88分です。エラーコードはSYNC-05-00666であり、引き続き原因の特定と解決に向けた対応を進めます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00666', 'INC-2024-00666', '本事象に関する調査を行いました。アウトボックステーブルの滞留が確認され、これにより通知遅延が発生していることが判明しました。技術的な調査を進めた結果、アウトボックスポーラーが停止していることが原因として特定されました。この問題の解決に向けて、アウトボックスポーラーの再起動および状況の監視を行う予定です。影響を受けた店舗には個別に情報提供し、必要な対応をいたします。', '本事象に関する調査を行いました。アウトボックステーブルの滞留が確認され、これにより通知遅延が発生していることが判明しました。技術的な調査を進めた結果、アウトボックスポーラーが停止していることが原因として特定されました。この問題の解決に向けて、アウトボックスポーラーの再起動および状況の監視を行う予定です。影響を受けた店舗には個別に情報提供し、必要な対応をいたします。', TIMESTAMP WITH TIME ZONE '2024-08-27T03:54:47+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00984', 'INC-2024-00666', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-26T04:09:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T05:09:47+09:00', '【初動対応】【データ同期・整合性障害】アウトボックス滞留に対する初動対応', 'インシデント発生後、初動対応として最初にアウトボックスポーラーの状態を確認し、停止していることを確認しました。即座に技術チームに連絡し、再起動手続きを実施しました。さらに、顧客店舗POSにおける影響範囲を特定し、必要な情報を関連部門と共有しました。今後の監視体制を強化し、再発防止策を講じていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00985', 'INC-2024-00666', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-26T05:39:47+09:00', TIMESTAMP WITH TIME ZONE '2024-08-26T06:39:47+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00668', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-17T04:57:00+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T05:27:00+09:00', '【障害報告】【API連携・EDI障害】配送連携ステータス停滞', '2024年8月17日04時57分に発生したマスター設定ミスによる在庫登録失敗について報告いたします。本事象では、配送連携のステータスが出荷済みで停滞していることが確認されました。影響を受けたのは単一店舗のみであり、特に配送連携に関するアダプタにおいて問題が発生しております。発生契機は大規模セール開始直前であり、ステータスマッピング表の更新漏れが原因として推定されます。初期検知は2024年8月17日05時24分であり、検知までに27分を要しました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00668', 'INC-2024-00668', '本件につきまして、運用部の運用 一郎が調査を行いました。調査の結果、大規模セール開始直前に配送連携のステータスが出荷済みで停滞していることが確認されました。この現象は、ステータスマッピング表の更新が行われていなかったことに起因していると考えられます。今後は、ステータスマッピング表の定期的な確認と更新を実施し、類似事象の再発を防止する必要があります。', '本件につきまして、運用部の運用 一郎が調査を行いました。調査の結果、大規模セール開始直前に配送連携のステータスが出荷済みで停滞していることが確認されました。この現象は、ステータスマッピング表の更新が行われていなかったことに起因していると考えられます。今後は、ステータスマッピング表の定期的な確認と更新を実施し、類似事象の再発を防止する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-18T05:27:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00988', 'INC-2024-00668', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-17T05:42:00+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T06:42:00+09:00', '【初期対応】【API連携・EDI障害】配送連携ステータス停滞', '初期対応として、運用部により事象の報告が即座に行われました。問題の影響範囲を特定し、関連するシステムのログを確認しました。また、ステータスマッピング表の状況を調査し、更新漏れがあることを確認しました。これに基づき、必要なマッピングの修正を迅速に行う手続きを開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00989', 'INC-2024-00668', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-17T07:12:00+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T08:12:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00670', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-11T17:21:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T17:51:01+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '2024年8月11日17時21分に発生したマスター設定ミスによる在庫登録失敗について報告します。本インシデントは、楽観ロック競合が多発し、更新失敗率が上昇するという症状が見られました。発見者は運用 一郎（運用部）で、全テナントに影響が及んでいることが確認されています。発生契機は大規模セール開始直前であり、特にMercury AWS AP（Secondary）において在庫登録APIの処理に支障をきたしました。エラーコードはSYNC-10-00670で、検知は2024年8月11日17時52分でした。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00670', 'INC-2024-00670', '調査の結果、楽観ロック競合が頻発し、更新失敗率が急上昇する状況が確認されました。原因としては、バージョンカラム更新ロジックの不備が推定されます。大規模セール開始直前というタイミングも影響している可能性があります。再発防止のためには、ロジックの見直しや負荷テストの実施が必要です。', '調査の結果、楽観ロック競合が頻発し、更新失敗率が急上昇する状況が確認されました。原因としては、バージョンカラム更新ロジックの不備が推定されます。大規模セール開始直前というタイミングも影響している可能性があります。再発防止のためには、ロジックの見直しや負荷テストの実施が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-12T17:51:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00991', 'INC-2024-00670', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-11T18:06:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T19:06:01+09:00', '【初期対応】【CLU-09】楽観ロック競合多発', '初期対応として、運用部からの緊急対応チームが編成されました。ログを確認し、楽観ロック競合の発生状況をトラッキングしています。影響を受けた顧客には状況を通知し、必要に応じて手動での在庫登録を行うよう指示を出しました。さらに、再発防止策として、バージョンカラム更新ロジックの早急な修正を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00992', 'INC-2024-00670', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-11T19:36:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T20:36:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00672', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-10T08:41:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T09:11:01+09:00', '【障害報告】【CLU-08】APIトークン早期失効', '2024年8月10日08時41分01秒、株式会社ストッククラウドのサービスVenusにおいて、APIトークンが発行直後に失効扱いとなる事象が発生しました。発見者は運用部の運用 一郎で、09時09分01秒に検知されました。特に、インフラメンテナンス明けにこの問題が生じており、影響範囲はサービス全体の一部機能に及びます。エラーコードはAUTH-04-00672です。この問題は、サーバー時刻のNTPずれが推定原因と考えられます。該当する影響コンポーネントはVenus Azure AP（Secondary）およびAPIゲートウェイです。今回のインシデントを受け、APIトークンの発行に関する注意が必要です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00672', 'INC-2024-00672', 'APIトークンの早期失効に関する調査を実施しました。検知からの初動対応は迅速であり、運用 一郎による発見後、直ちに調査チームが編成されました。原因はサーバー時刻のNTPずれに起因する可能性が高く、インフラメンテナンス後の確認が不十分であったことが調査によって明らかになりました。今後は、NTP同期の定期的な確認を実施し、同様の事象が発生しないよう対策を講じる必要があります。', 'APIトークンの早期失効に関する調査を実施しました。検知からの初動対応は迅速であり、運用 一郎による発見後、直ちに調査チームが編成されました。原因はサーバー時刻のNTPずれに起因する可能性が高く、インフラメンテナンス後の確認が不十分であったことが調査によって明らかになりました。今後は、NTP同期の定期的な確認を実施し、同様の事象が発生しないよう対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-11T09:11:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00994', 'INC-2024-00672', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T09:26:01+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T10:26:01+09:00', '初期対応ログ', 'インシデント発生後、運用部の運用 一郎が全体の状況を把握し、即座に調査チームを招集しました。チームはAPIトークンの発行状況を確認し、失効の理由としてサーバー時刻のNTP誤差を特定しました。影響範囲の特定と対応策の検討が優先事項として設定され、関係者に情報共有が行われました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00676', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-02-21T19:57:23+09:00', TIMESTAMP WITH TIME ZONE '2024-02-21T20:12:23+09:00', '【障害報告】【CLU-03】メンテ解除失敗', '2024年2月21日19時57分23秒、株式会社ストッククラウドの運用コンソールにて、運用 一郎がメンテナンスモード解除操作を実施したところ、操作が失敗しました。この障害は、架空食品店A及び架空食品店Bに影響を及ぼし、サービス全体の一部機能が利用できない状況となりました。なお、障害の検知は20時06分23秒で、検知までに9分を要しました。推定原因は、インフラメンテナンス明けにメンテナンスフラグが残留していたことによるものと考えられます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00676', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00676', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00676', 'INC-2024-00676', '運用 一郎がメンテナンスモード解除操作を行ったが、メンテナンスフラグの残留により解除操作が失敗したことが確認されました。この問題は、インフラメンテナンス後に発生し、影響を受けたのは運用コンソール（ゾーンA）及び設定管理DBです。再発防止策として、メンテナンスフラグの管理方法を見直す必要があります。', '運用 一郎がメンテナンスモード解除操作を行ったが、メンテナンスフラグの残留により解除操作が失敗したことが確認されました。この問題は、インフラメンテナンス後に発生し、影響を受けたのは運用コンソール（ゾーンA）及び設定管理DBです。再発防止策として、メンテナンスフラグの管理方法を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2024-02-22T20:12:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00999', 'INC-2024-00676', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-21T20:27:23+09:00', TIMESTAMP WITH TIME ZONE '2024-02-21T21:27:23+09:00', '【対応ログ】【CLU-03】メンテ解除失敗', '運用 一郎より、20時06分にメンテナンス解除失敗の報告を受け、直ちに調査を開始。運用コンソールの状態を確認し、メンテナンスフラグの残留が原因であることが判明。影響を受けている顧客への通知を準備中。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01000', 'INC-2024-00676', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-21T21:57:23+09:00', TIMESTAMP WITH TIME ZONE '2024-02-21T22:57:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00682', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-15T06:24:11+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T06:54:11+09:00', '【障害報告】【CLU-09】読取レプリカ遅延', '2024年8月15日06時24分に、株式会社ストッククラウドのVenusにおいて、在庫登録失敗が確認されました。発生場所はMercury AWS APであり、発見者は運用部の運用 一郎です。本事象においては、特定リージョンのユーザーのみが影響を受けており、読取レプリカ遅延により在庫照会が古い値となっています。エラーコードはSYNC-02-00682です。特に、大規模セール開始直前に発生したことが原因として疑われており、レプリケーション遅延の監視閾値超過が推定されています。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00682', 'INC-2024-00682', '本事象の調査を行った結果、読取レプリカ遅延が影響したことが確認されました。具体的には、在庫照会が古い値を返すことで、ユーザーに誤った情報を提供していました。今後のために、レプリケーションの監視閾値を見直し、遅延が発生した場合の対処法を強化する必要があります。', '本事象の調査を行った結果、読取レプリカ遅延が影響したことが確認されました。具体的には、在庫照会が古い値を返すことで、ユーザーに誤った情報を提供していました。今後のために、レプリケーションの監視閾値を見直し、遅延が発生した場合の対処法を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-16T06:54:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01008', 'INC-2024-00682', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-15T07:09:11+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T08:09:11+09:00', '初期対応', '初期対応として、運用部がレプリケーションの監視を強化し、遅延が発生した際のアラートを設定しました。また、ユーザーへの通知を行い、在庫情報が正確でないことを周知しました。今後は、定期的なレビューを実施し、障害の再発防止に努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01009', 'INC-2024-00682', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-15T08:39:11+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T09:39:11+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00693', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-04-26T03:54:56+09:00', TIMESTAMP WITH TIME ZONE '2024-04-26T04:09:56+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2024年4月26日03時54分56秒、株式会社ストッククラウドの運用コンソールにおいて、PagerDuty連携が失敗しオフコール通知未達の事象が発生しました。発見者は運用部の運用 一郎で、検知は04時07分56秒でした。障害の影響範囲は運用部門のみに及び、年末年始の稼働切替時において連携APIキーの権限不足が推定原因として挙げられます。エラーコードはMON-07-00693です。この事象により、運用部からの重要な連絡が届かず、監視・可用性障害が生じました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00693', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00693', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00693', 'INC-2024-00693', '本事象の調査を行った結果、年末年始の稼働切替時にPagerDuty連携が失敗したことが確認されました。主な原因は連携APIキーの権限不足であり、これによりオンコール通知が未達となったことが判明しました。運用部門の業務に影響を及ぼす結果となりました。今後の対策として、APIキーの権限設定を見直し、テストを行う必要があります。', '本事象の調査を行った結果、年末年始の稼働切替時にPagerDuty連携が失敗したことが確認されました。主な原因は連携APIキーの権限不足であり、これによりオンコール通知が未達となったことが判明しました。運用部門の業務に影響を及ぼす結果となりました。今後の対策として、APIキーの権限設定を見直し、テストを行う必要があります。', TIMESTAMP WITH TIME ZONE '2024-04-27T04:09:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01027', 'INC-2024-00693', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-04-26T04:24:56+09:00', TIMESTAMP WITH TIME ZONE '2024-04-26T05:24:56+09:00', '【対応ログ】【CLU-10】PagerDuty連携失敗', '初回の対応として、運用部の運用 一郎が障害発生を認識し、迅速に調査を開始しました。連携APIキーの設定を確認し、不足している権限を特定しました。必要な権限を付与することで、再度連携を試みる準備が整いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00695', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-05-20T02:58:23+09:00', TIMESTAMP WITH TIME ZONE '2024-05-20T03:58:23+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2024年5月20日2時58分、株式会社ストッククラウドの顧客、架空食品店Aにおいて顧客側ネットワーク障害が発生しました。症状は顧客固定IP変更が許可リストに未反映であり、単一店舗のみが影響を受けました。発見者は営業部の花子で、発見は3時43分であり、発生からの検知までに45分を要しました。発生契機は顧客のオンボーディング当日であり、推定原因としてIP許可リストの更新漏れが考えられます。技術詳細としては、顧客側FW及び顧客拠点NW（ゾーンB）において、許可リストの更新が行われていないことが確認されました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00695', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00695', 'INC-2024-00695', '現時点での調査結果としては、顧客オンボーディング当日に顧客の固定IP変更が許可リストに未反映であったことが確認されています。IP許可リストの更新漏れが原因であることが疑われ、迅速な対応が求められます。今後、許可リストの管理方法の見直しや、更新時の確認プロセスの強化が必要です。', '現時点での調査結果としては、顧客オンボーディング当日に顧客の固定IP変更が許可リストに未反映であったことが確認されています。IP許可リストの更新漏れが原因であることが疑われ、迅速な対応が求められます。今後、許可リストの管理方法の見直しや、更新時の確認プロセスの強化が必要です。', TIMESTAMP WITH TIME ZONE '2024-05-21T03:58:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01029', 'INC-2024-00695', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-05-20T04:13:23+09:00', TIMESTAMP WITH TIME ZONE '2024-05-20T05:13:23+09:00', '【初動対応】【顧客ネットワーク障害】固定IP変更未連絡', '花子（営業部）より、架空食品店Aの固定IP変更が許可リストに未反映であるとの報告を受け、速やかに調査を開始しました。顧客側ネットワークに影響が出ているため、優先的に対応する必要があります。許可リストの更新が行われていない理由と手続きを確認し、適切な対策を講じる準備を進めていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01030', 'INC-2024-00695', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-05-20T05:43:23+09:00', TIMESTAMP WITH TIME ZONE '2024-05-20T06:43:23+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00696', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-10-01T13:26:32+09:00', TIMESTAMP WITH TIME ZONE '2024-10-01T13:56:32+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2024年10月1日13時26分32秒に、株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Aの在庫登録機能に障害が発生しました。具体的には、SKU登録APIがHTTP 500を返し、在庫の反映に失敗するという事象が確認されました。この問題は、定例リリース直後に発生したため、リリース内容に起因している可能性があります。推定される原因として、単位換算係数の設定漏れが挙げられます。影響範囲は単一店舗の登録機能のみであり、直ちに対応が必要です。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00696', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00696', 'INC-2024-00696', '本障害を調査した結果、SKU登録APIがHTTP 500を返す原因として、単位換算係数の設定漏れが疑われます。定例リリース直後にこの問題が発生したため、リリース内の設定項目を重点的に確認しています。現在、影響を受けている店舗の登録機能について、修正作業を進めており、迅速な解決を目指しています。', '本障害を調査した結果、SKU登録APIがHTTP 500を返す原因として、単位換算係数の設定漏れが疑われます。定例リリース直後にこの問題が発生したため、リリース内の設定項目を重点的に確認しています。現在、影響を受けている店舗の登録機能について、修正作業を進めており、迅速な解決を目指しています。', TIMESTAMP WITH TIME ZONE '2024-10-02T13:56:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01031', 'INC-2024-00696', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-10-01T14:11:32+09:00', TIMESTAMP WITH TIME ZONE '2024-10-01T15:11:32+09:00', '【初期対応】【在庫マスター設定障害】SKU登録HTTP500', '初期対応として、運用部の運用 一郎が架空食品店Aの在庫登録APIの状況を確認しました。HTTP 500エラーが返されていることを確認したため、直ちに原因調査を開始しました。エラーコードMST-01-00696に基づき、定例リリース後の設定内容を精査中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01032', 'INC-2024-00696', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-10-01T15:41:32+09:00', TIMESTAMP WITH TIME ZONE '2024-10-01T16:41:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00709', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-18T07:07:56+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T09:07:56+09:00', '【障害報告】【API連携・EDI障害】EDI在庫差分遅延', '2024年8月18日07時07分56秒に発生したEDI在庫差分ファイルの反映遅延について報告いたします。顧客店舗POSにおいて、EDI在庫差分の反映が2時間遅延していることが確認されました。これはデータ移行バッチ実行中に発生し、同一顧客の全店舗に影響を及ぼしています。推定される原因としては、EDIキューの優先度設定誤りが考えられます。エラーコードはEDI-01-00709です。現在、影響コンポーネントである顧客店舗POSおよびEDIアダプタに対し、早急な対応が必要です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00709', 'INC-2024-00709', '本調査において、EDI在庫差分ファイルが2時間遅延している原因を探るため、データ移行バッチ実行中のシステムログを確認しました。結果として、EDIキューの優先度設定に誤りがあったことが判明しました。この設定ミスが影響し、在庫差分の反映が遅延していました。今後は、優先度設定の見直しを行うことで、再発防止に努めます。', '本調査において、EDI在庫差分ファイルが2時間遅延している原因を探るため、データ移行バッチ実行中のシステムログを確認しました。結果として、EDIキューの優先度設定に誤りがあったことが判明しました。この設定ミスが影響し、在庫差分の反映が遅延していました。今後は、優先度設定の見直しを行うことで、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2024-08-19T09:07:56+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01052', 'INC-2024-00709', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-18T09:22:56+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T10:22:56+09:00', '【初動対応】【API連携・EDI障害】EDI在庫差分遅延の初動対応', '初動対応として、2024年8月18日09時55分56秒に本障害を検知し、直ちに影響を受ける全店舗への通知を行いました。並行して、データ移行バッチの実行を一時停止し、経過観察を行っています。また、エンジニアチームに対して優先度設定の修正を依頼し、問題解決に向けた対応を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00711', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-30T08:43:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T09:28:20+09:00', '【障害報告】【ストレージ・容量障害】オブジェクトライフサイクル誤り', '発生日時: 2024-09-01T08:43:20+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00711', 'INC-2024-00711', '調査の結果、定例リリース直後に不要オブジェクトの削除が行われなかったことが確認されました。これは、ライフサイクルポリシーの適用漏れが原因と考えられます。今後の対策としては、ライフサイクルポリシーの見直しと適切な適用確認が必要です。', '調査の結果、定例リリース直後に不要オブジェクトの削除が行われなかったことが確認されました。これは、ライフサイクルポリシーの適用漏れが原因と考えられます。今後の対策としては、ライフサイクルポリシーの見直しと適切な適用確認が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-31T09:28:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01054', 'INC-2024-00711', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-30T09:43:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-30T10:43:20+09:00', '初期対応', '初期対応として、影響を受けたストレージを一時的に停止し、不要オブジェクトの削除作業を開始しました。また、ライフサイクルポリシーの適用状況を確認し、問題のある設定を修正する手続きを進めています。今後の進捗については、定期的に報告いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00712', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-04T09:28:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T10:13:26+09:00', '【障害報告】【CLU-10】合成監視失敗', '2024年8月4日09時28分26秒に、株式会社ストッククラウドのVenusサービスにおいて、合成監視が特定ステップで失敗する事象が発生しました。影響範囲はサービス全体の一部機能に及び、エラーコードはMON-08-00712です。発生契機は定例リリース直後であり、影響コンポーネントとしてMercury AWS Storage（Primary）および合成監視ランナーが挙げられます。技術詳細として、定例リリース直後に合成監視が特定ステップで失敗する原因としてテストデータの期限切れが疑われています。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00712', 'INC-2024-00712', '合成監視が特定ステップで失敗した原因を調査中です。テストデータの期限切れが主要因と考えられます。具体的な確認をするために、テストデータの状況を確認し、必要に応じて新しいデータを準備する手続きを進めます。これにより、合成監視の正常性を回復させるための手段を特定します。', '合成監視が特定ステップで失敗した原因を調査中です。テストデータの期限切れが主要因と考えられます。具体的な確認をするために、テストデータの状況を確認し、必要に応じて新しいデータを準備する手続きを進めます。これにより、合成監視の正常性を回復させるための手段を特定します。', TIMESTAMP WITH TIME ZONE '2024-08-05T10:13:26+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01055', 'INC-2024-00712', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-04T10:28:26+09:00', TIMESTAMP WITH TIME ZONE '2024-08-04T11:28:26+09:00', '【初動対応】【CLU-10】合成監視失敗', '2024年8月4日10時26分26秒に、合成監視の失敗を検知しました。運用部の運用 一郎が対応にあたり、テストデータの状況を確認するための措置を講じています。合成監視の正常な動作を確保するため、必要な修正を迅速に行うことを目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00713', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-14T23:01:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-14T23:16:51+09:00', '【障害報告】【監視・可用性障害】トレースサンプリング過少', '2024年8月14日23時01分51秒に、株式会社ストッククラウドの運用者による作業ミスにより、運用コンソールにおいて分散トレースのサンプリング率が過少となり、原因特定が困難な状況が発生しました。発見者は運用部の運用 一郎氏であり、23時10分51秒に検知されました。定例リリース直後に発生したこの監視・可用性障害により、影響を受けるのは運用部門のみです。エラーコードはMON-05-00713であり、原因としてはサンプリング率の本番設定誤りが疑われています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00713', 'INC-2024-00713', '本インシデントに関する調査を行ったところ、定例リリース直後の設定において分散トレースのサンプリング率が過少であることが確認されました。これにより、原因特定が困難な状態が続いています。サンプリング率の本番設定誤りが主要な原因として特定され、早急な修正が必要とされています。今後の運用において、設定確認のプロセスを強化し、再発防止に努めることが重要です。', '本インシデントに関する調査を行ったところ、定例リリース直後の設定において分散トレースのサンプリング率が過少であることが確認されました。これにより、原因特定が困難な状態が続いています。サンプリング率の本番設定誤りが主要な原因として特定され、早急な修正が必要とされています。今後の運用において、設定確認のプロセスを強化し、再発防止に努めることが重要です。', TIMESTAMP WITH TIME ZONE '2024-08-15T23:16:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01056', 'INC-2024-00713', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-14T23:31:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T00:31:51+09:00', '【初動対応】【監視・可用性障害】トレースサンプリング過少', '初動対応として、運用部門は直ちに運用コンソールの設定を確認し、分散トレースのサンプリング率を正常な値に戻す作業を実施しました。また、イシューを再現し、影響範囲を把握するための追加調査を開始しました。運用 一郎氏は、チームメンバーと協力し、サンプリング率の設定について詳細に確認を行い、問題の解決に向けたアクションプランを策定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00717', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-06-23T17:38:58+09:00', TIMESTAMP WITH TIME ZONE '2024-06-23T18:23:58+09:00', '【障害報告】【ストレージ・容量障害】レプリカ遅延肥大', '2024年6月23日17時38分58秒に、株式会社ストッククラウドのMercuryにおいて、ストレージ溢れが発生しました。顧客である架空食品店Bおよび架空食品店Aに対し、レプリカ遅延により差分ログが肥大化し、サービスに影響を及ぼしました。この問題は、大規模セール開始直前に発生し、運用部の運用 一郎によって発見されました。検知は発生から57分後の18時35分58秒に行われ、影響範囲は読取専用レプリカ利用者でありました。エラーコードはSTR-10-00717です。今回の事象は、レプリカ帯域制限設定の過小が推定原因です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00717', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00717', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00717', 'INC-2024-00717', '調査を行った結果、大規模セール開始直前に発生したレプリカ遅延が、差分ログの肥大化を引き起こしました。特に、レプリカ帯域制限設定が不足していたことが主な要因として挙げられます。この問題により、読取専用レプリカ利用者が影響を受け、サービスの品質が低下しました。今後は、レプリカ帯域制限設定の見直しと、定期的な監視を行うことが必要です。', '調査を行った結果、大規模セール開始直前に発生したレプリカ遅延が、差分ログの肥大化を引き起こしました。特に、レプリカ帯域制限設定が不足していたことが主な要因として挙げられます。この問題により、読取専用レプリカ利用者が影響を受け、サービスの品質が低下しました。今後は、レプリカ帯域制限設定の見直しと、定期的な監視を行うことが必要です。', TIMESTAMP WITH TIME ZONE '2024-06-24T18:23:58+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01060', 'INC-2024-00717', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-06-23T18:38:58+09:00', TIMESTAMP WITH TIME ZONE '2024-06-23T19:38:58+09:00', '初期対応', '初期対応として、運用部はレプリカ帯域制限の設定を見直し、緊急の調整を行いました。また、影響を受けた顧客には速やかに状況を連絡し、サービスの復旧に向けた対応を進めました。今後の対策として、ストレージ・容量に関する監視体制の強化を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01061', 'INC-2024-00717', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-06-23T20:08:58+09:00', TIMESTAMP WITH TIME ZONE '2024-06-23T21:08:58+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00720', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-10T02:06:35+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T02:51:35+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2024年8月10日02時06分35秒に、株式会社ストッククラウドのサービスVenusにおいて、Mercury AWS Storageでストレージ溢れが発生しました。この影響により、ヘルスチェック過多でAPサーバー負荷が増加し、全テナントに波及する可能性があります。運用部の運用 一郎が発見し、02時44分35秒に検知しました。なお、発生契機はインフラメンテナンス明けであり、エラーコードはMON-06-00720です。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00720', 'INC-2024-00720', '今回のヘルスチェック過負荷の原因としては、LBヘルスチェック間隔の過短設定が疑われます。インフラメンテナンス明けでの負荷増加が確認されており、詳細な調査を進める必要があります。全テナントが影響を受ける可能性があるため、早急な対応が求められます。', '今回のヘルスチェック過負荷の原因としては、LBヘルスチェック間隔の過短設定が疑われます。インフラメンテナンス明けでの負荷増加が確認されており、詳細な調査を進める必要があります。全テナントが影響を受ける可能性があるため、早急な対応が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-11T02:51:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01064', 'INC-2024-00720', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T03:06:35+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T04:06:35+09:00', '【初動対応】監視・可用性障害 - ヘルスチェック過負荷', '運用 一郎が最初にインシデントを報告しました。ヘルスチェックの過多によるAPサーバー負荷増が確認されたため、LBのヘルスチェック設定を見直す方針で進めます。監視・可用性障害に関する対応を優先し、影響を受けた全テナントへの通知も行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01065', 'INC-2024-00720', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T04:36:35+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T05:36:35+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00736', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-03-26T18:46:23+09:00', TIMESTAMP WITH TIME ZONE '2024-03-26T19:16:23+09:00', '【障害報告】【CLU-06】下流APIレート制限', '2024年3月26日18時46分、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店B及び架空食品店Aの利用者に対して応答遅延が発生しました。発生の契機は大規模セール開始直前であり、下流APIのレート制限により処理待ちが増大しました。影響範囲はサービス全体の一部機能に及び、特にVenus Azure AP（ゾーンA）及びAPIゲートウェイにおいて顕著でした。エラーコードはPRF-07-00736です。検知は19時13分に行われ、検知までに27分の時間が経過しました。この間、利用者からのクレームが急増し、待ち行列が発生したことを確認しています。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00736', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00736', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00736', 'INC-2024-00736', '調査の結果、下流APIのレート制限が原因であることが分かりました。大規模セール開始直前のトラフィックの急増により、処理待ちが発生し、ユーザーへの応答が遅延する事態となりました。具体的には、下流APIが負荷に耐え切れず、応答時間が大幅に延びたことが確認されています。また、影響を受けたコンポーネントはVenus Azure AP（ゾーンA）であり、APIゲートウェイも関連しています。', '調査の結果、下流APIのレート制限が原因であることが分かりました。大規模セール開始直前のトラフィックの急増により、処理待ちが発生し、ユーザーへの応答が遅延する事態となりました。具体的には、下流APIが負荷に耐え切れず、応答時間が大幅に延びたことが確認されています。また、影響を受けたコンポーネントはVenus Azure AP（ゾーンA）であり、APIゲートウェイも関連しています。', TIMESTAMP WITH TIME ZONE '2024-03-27T19:16:23+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01089', 'INC-2024-00736', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-03-26T19:31:23+09:00', TIMESTAMP WITH TIME ZONE '2024-03-26T20:31:23+09:00', '【初期対応】【CLU-06】下流APIレート制限', '初期対応として、運用部の運用一郎が即座に状況を把握し、下流APIの運用状況を確認しました。レート制限の緩和を試みるため、APIゲートウェイの設定を調整し、トラフィックを分散させる措置を講じました。また、顧客への報告を行い、影響の最小化に努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00740', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-27T11:22:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T13:22:49+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2024年8月27日11時22分49秒に、株式会社ストッククラウドの顧客店舗POSにおいて、POS連携の売上が翌営業日まで在庫に反映されない事象が発生しました。この現象は年末年始の稼働切替時に発生しており、営業部の花子が発見しました。検知は2024年8月27日13時39分49秒に行われ、発見から137分後の検知となっています。影響範囲は単一店舗のみで、エラーコードはINV-02-00740です。推定原因としては、前日締め処理の二重実行が考えられます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00740', 'INC-2024-00740', '調査を行った結果、年末年始の稼働切替時にPOS連携の売上が翌営業日まで在庫に反映されない原因として、前日締め処理の二重実行が疑われます。これにより、在庫情報の更新が遅延し、売上データが正しく処理されていないことが確認されました。今後の対策として、締め処理の管理体制を見直す必要があります。', '調査を行った結果、年末年始の稼働切替時にPOS連携の売上が翌営業日まで在庫に反映されない原因として、前日締め処理の二重実行が疑われます。これにより、在庫情報の更新が遅延し、売上データが正しく処理されていないことが確認されました。今後の対策として、締め処理の管理体制を見直す必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-28T13:22:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01095', 'INC-2024-00740', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-27T13:37:49+09:00', TIMESTAMP WITH TIME ZONE '2024-08-27T14:37:49+09:00', '【対応】【棚卸・POS突合障害】POS売上遅延反映への初期対応', '初期対応として、発生したエラーについての詳細な調査を開始しました。営業部の花子が不具合を発見したため、関係者に通知し、状況の確認を行っています。また、技術チームに連絡を取り、前日締め処理の二重実行に関するログの確認を依頼しました。さらに、影響を受けた店舗に対して、状況の説明と状況確認を行うことを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00743', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-15T20:57:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T22:57:06+09:00', '【障害報告】【CLU-07】冪等キー重複', '2024年8月15日20時57分に、株式会社ストッククラウドのVenusサービスにおいて、棚卸突合失敗の事象が発生しました。具体的には、冪等キー重複により在庫更新がスキップされました。影響範囲は同一顧客の全店舗に及び、発生契機は定例リリース直後です。エラーコードはEDI-08-00743で、影響コンポーネントは顧客店舗POSが主な原因として挙げられます。この問題は、定例リリース直後に冪等キー生成ロジックが衝突したことが原因と考えられています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00743', 'INC-2024-00743', '今回のインシデントでは、冪等キーの重複が発生し、在庫更新がスキップされる事態となりました。調査の結果、定例リリース直後に冪等キー生成ロジックが衝突したことが原因であることが判明しました。この問題は、API連携・EDIのプロセスにおいて顕著に現れています。適切な対応が必要です。', '今回のインシデントでは、冪等キーの重複が発生し、在庫更新がスキップされる事態となりました。調査の結果、定例リリース直後に冪等キー生成ロジックが衝突したことが原因であることが判明しました。この問題は、API連携・EDIのプロセスにおいて顕著に現れています。適切な対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-16T22:57:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01099', 'INC-2024-00743', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-15T23:12:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T00:12:06+09:00', '【初期対応】【CLU-07】冪等キー重複', '初期対応として、問題の影響を受けた全店舗に対し、在庫更新処理を手動で行うことを指示しました。また、冪等キー生成ロジックの見直しを行うとともに、再発防止策を検討するためのチームを結成しました。余分な負荷をかけないため、問題の全面的な解決を目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01100', 'INC-2024-00743', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-16T00:42:06+09:00', TIMESTAMP WITH TIME ZONE '2024-08-16T01:42:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00744', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-06-15T15:53:15+09:00', TIMESTAMP WITH TIME ZONE '2024-06-15T16:38:15+09:00', '【障害報告】【ストレージ・容量障害】ログローテ停止', '2024年6月15日、株式会社ストッククラウドのMercuryにおいてストレージ溢れが発生しました。発生時刻は15:53で、架空食品店Bに影響が出ました。Mercury AWS Storageのログローテーションが停止し、容量を圧迫していることが確認されました。この問題はデータ移行バッチ実行中に発生し、一時ファイルの削除バッチが停止したことが原因と考えられます。影響はバッチ処理のみに限られ、オンラインには影響がありません。運用部の運用 一郎が問題を発見し、16:49には検知されました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00744', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00744', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00744', 'INC-2024-00744', '本インシデントでは、データ移行バッチの実行中にログローテーションが停止し、結果としてストレージ容量が圧迫される状況が確認されました。特に、一時ファイルの削除バッチの停止が原因であると推定しています。ログローテの停止により、Mercury AWS Storageの監査ログボリュームが影響を受けますのが懸念事項です。', '本インシデントでは、データ移行バッチの実行中にログローテーションが停止し、結果としてストレージ容量が圧迫される状況が確認されました。特に、一時ファイルの削除バッチの停止が原因であると推定しています。ログローテの停止により、Mercury AWS Storageの監査ログボリュームが影響を受けますのが懸念事項です。', TIMESTAMP WITH TIME ZONE '2024-06-16T16:38:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01101', 'INC-2024-00744', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-06-15T16:53:15+09:00', TIMESTAMP WITH TIME ZONE '2024-06-15T17:53:15+09:00', '【初期対応】【ストレージ・容量障害】ログローテ停止', 'インシデント発生後、運用部の担当者は直ちに問題の調査を開始しました。ログローテーションが停止していることを確認し、データ移行バッチの状況を確認しました。一時ファイルの削除バッチの状況を確認するため、関連するログを収集し分析を進めることとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00750', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-12T06:02:13+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T06:32:13+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2024年8月12日06時02分13秒に、株式会社ストッククラウドのサービスVenusにおいて、在庫マスター設定ミスによる在庫登録失敗が発生しました。具体的には、データ移行バッチを実行中に在庫CSVの3行目以降が取込されない事象が確認されました。これはJANコードの重複チェックに関する誤設定が原因であると考えられます。影響範囲はバッチ処理のみであり、オンラインには影響がありませんでした。この問題は06時33分13秒に検知され、検知までの時間は31分でした。エラーコードはMST-03-00750です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00750', 'INC-2024-00750', '調査の結果、データ移行バッチ実行中に在庫CSVの3行目以降が取込されない問題が発生していることが確認されました。在庫マスター設定におけるJANコード重複チェックの誤設定が影響を与えている可能性があります。今後、JANコードの設定を見直し、再発防止に向けた対策を講じる必要があります。', '調査の結果、データ移行バッチ実行中に在庫CSVの3行目以降が取込されない問題が発生していることが確認されました。在庫マスター設定におけるJANコード重複チェックの誤設定が影響を与えている可能性があります。今後、JANコードの設定を見直し、再発防止に向けた対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-13T06:32:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01111', 'INC-2024-00750', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-12T06:47:13+09:00', TIMESTAMP WITH TIME ZONE '2024-08-12T07:47:13+09:00', '【初動対応】CSVバッチ取込欠損', '初動対応として、バッチ処理のログを確認し、JANコード重複チェック設定の再確認を行います。また、影響を受けた在庫データの確認作業を実施し、必要に応じて修正を行う手続きを進めます。運用部の運用 一郎が対応を担当します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00752', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-15T18:32:24+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T20:32:24+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2024年8月15日、株式会社ストッククラウドのVenusサービスにおいて、顧客店舗POSがパートナーAPIから429を返されたことにより、連携が停止しました。これは大規模セール開始直前に発生したもので、呼出頻度の事前調整不足が原因と推定されます。この影響により、サービス全体の一部機能が利用できない状態となっております。営業部の花子がこの事象を発見し、技術詳細としては、APIゲートウェイの処理に問題が生じたことが報告されています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00752', 'INC-2024-00752', 'インシデント発生後、影響を受けた顧客店舗POSとAPIゲートウェイのログを調査しました。パートナーAPIからの429エラーが確認され、呼出頻度が適切に管理されていなかったことが明白になりました。大規模セールが予定されていたため、予想以上のリクエストが発生したことが影響を与えたと考えられます。今後は、呼出頻度の調整プランを策定し、再発防止に努めます。', 'インシデント発生後、影響を受けた顧客店舗POSとAPIゲートウェイのログを調査しました。パートナーAPIからの429エラーが確認され、呼出頻度が適切に管理されていなかったことが明白になりました。大規模セールが予定されていたため、予想以上のリクエストが発生したことが影響を与えたと考えられます。今後は、呼出頻度の調整プランを策定し、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2024-08-16T20:32:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01114', 'INC-2024-00752', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-15T20:47:24+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T21:47:24+09:00', '【対応ログ】【API連携・EDI障害】レート超過429', '2024年8月15日18時32分に発生した障害に関し、営業部の花子が最初に報告しました。この後、技術部門が迅速に対策を講じるため、システムの調査を開始しました。初動対応として、関連するログの収集と分析を行い、呼出頻度を調整する必要があることが確認されました。今後のコミュニケーションは、社内チャットを通じて行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01115', 'INC-2024-00752', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-15T22:17:24+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T23:17:24+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00753', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-24T20:07:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T22:07:38+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '2024年8月24日20時07分38秒に発生した棚卸突合失敗のインシデントです。顧客店舗POSにおいてCDCイベント欠損が確認され、下流倉庫が未更新の状態となっています。発見者は営業部の花子で、検知は2024年8月24日22時34分38秒に行われ、検知までに147分を要しました。今回の問題は、データ移行バッチ実行中に発生したもので、推定される原因はCDCコネクタのオフセット巻戻しです。影響範囲はバッチ処理のみで、オンラインには影響がありません。エラーコードはSYNC-03-00753です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00753', 'INC-2024-00753', '調査の結果、データ移行バッチ実行中にCDCイベントが欠損したことが確認されました。これにより、下流倉庫が未更新であることが判明しました。CDCコネクタのオフセット巻戻しが原因である可能性が高く、今後の調査を通じてさらなる詳細な原因分析を行う必要があります。影響を受けたコンポーネントは顧客店舗POS（Secondary）およびCDCパイプラインです。', '調査の結果、データ移行バッチ実行中にCDCイベントが欠損したことが確認されました。これにより、下流倉庫が未更新であることが判明しました。CDCコネクタのオフセット巻戻しが原因である可能性が高く、今後の調査を通じてさらなる詳細な原因分析を行う必要があります。影響を受けたコンポーネントは顧客店舗POS（Secondary）およびCDCパイプラインです。', TIMESTAMP WITH TIME ZONE '2024-08-25T22:07:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01116', 'INC-2024-00753', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-24T22:22:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-24T23:22:38+09:00', '初期対応', '本インシデントに対して、初期対応としてCDCコネクタの設定を確認し、オフセットの状態をチェックしました。バッチ処理の再実行を行う前に、イベント欠損の修正を進めています。顧客店舗POSに関連するデータの整合性を確保するため、必要な手順を速やかに実施し、下流倉庫の更新作業を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01117', 'INC-2024-00753', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-24T23:52:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T00:52:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00755', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-01-18T01:07:55+09:00', TIMESTAMP WITH TIME ZONE '2024-01-18T01:22:55+09:00', '【障害報告】【運用操作・権限障害】本番DB誤接続', '2024年1月18日01時07分55秒、株式会社ストッククラウドの運用コンソールにおいて、運用ツールが本番DB以外に接続している事象が発生しました。発見者は運用部の運用 一郎で、発生後10分で検知されました。この障害は全テナントに波及しており、重大度はHIGHに分類されます。発生契機として定例リリース直後の設定ミスが考えられ、エラーコードはOPS-06-00755です。これにより、運用ツールの動作に支障をきたし、迅速な対応が求められました。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00755', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00755', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00755', 'INC-2024-00755', '運用ツールが本番DB以外に接続していた原因は、本番DBへの誤接続設定と推測されます。定例リリース直後に発生したこの問題は、設定管理DBの不備に起因する可能性があります。詳細な技術調査を行い、誤接続の設定を特定する必要があります。影響範囲は全テナントに及び、直ちに修正作業を実施することが求められます。', '運用ツールが本番DB以外に接続していた原因は、本番DBへの誤接続設定と推測されます。定例リリース直後に発生したこの問題は、設定管理DBの不備に起因する可能性があります。詳細な技術調査を行い、誤接続の設定を特定する必要があります。影響範囲は全テナントに及び、直ちに修正作業を実施することが求められます。', TIMESTAMP WITH TIME ZONE '2024-01-19T01:22:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01119', 'INC-2024-00755', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-01-18T01:37:55+09:00', TIMESTAMP WITH TIME ZONE '2024-01-18T02:37:55+09:00', '初期対応', '運用部は本番DBへの接続設定を確認し、誤接続を是正する作業を開始しました。また、定例リリースの影響を受けたテナントに対して状況説明を行い、必要な対応を協議しました。全テナントに対する影響を最小限に抑えるべく、迅速な修正を心掛けます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00757', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-09T14:44:39+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T16:44:39+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2024年8月9日14時44分39秒に発生した棚卸突合失敗インシデントについて報告します。顧客店舗POSにて、棚卸確定ボタンがグレーアウトしたまま操作できない症状が確認されました。これは月末棚卸の開始時に発生し、未処理の差異調整レコードが残留していることが推定原因です。影響範囲は単一店舗のみで、エラーコードはINV-03-00757です。この状況により、店舗の棚卸確定ができない状態となっています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00757', 'INC-2024-00757', 'インシデントの発生から約122分後の16時46分39秒に検知されました。調査の結果、顧客店舗のPOSシステムにおいて、棚卸確定ボタンがグレーアウトする現象が確認されました。差異調整レコードの未処理が原因であると考えられ、詳細なログを調査し問題の再現を試みます。今後、差異調整レコードの処理状況を確認し、必要な対応を行う予定です。', 'インシデントの発生から約122分後の16時46分39秒に検知されました。調査の結果、顧客店舗のPOSシステムにおいて、棚卸確定ボタンがグレーアウトする現象が確認されました。差異調整レコードの未処理が原因であると考えられ、詳細なログを調査し問題の再現を試みます。今後、差異調整レコードの処理状況を確認し、必要な対応を行う予定です。', TIMESTAMP WITH TIME ZONE '2024-08-10T16:44:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01122', 'INC-2024-00757', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-09T16:59:39+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T17:59:39+09:00', '【対応】【棚卸・POS突合障害】初期対応', 'この問題に関しては、営業部の花子が対応を行っています。初期対応として、店舗のPOSにおける棚卸確定ボタンの状態を確認し、差異調整レコードの存在を調査しています。必要に応じて、技術チームと連携し、問題の解決に向けたアクションを実施します。店舗の影響を最小限に抑えるため、迅速な対応を心掛けています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00765', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-25T03:06:25+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T04:06:25+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年8月25日03時06分25秒、株式会社ストッククラウドの顧客ネットワークにおいて、DNS解決成功後にTLS握手で接続が切断される事象が発生しました。発見者は営業部の花子で、検知時間は04時17分25秒で、発生から71分後に確認されました。この事象は同一顧客の全店舗に影響を及ぼし、エラーコードはNW-03-00765です。発生契機としては、インフラメンテナンス明けが考えられ、影響コンポーネントは顧客拠点NW（ゾーンB）およびTLS終端です。原因としてはプロキシ証明書の期限切れが疑われています。今後の教訓として、証明書の管理を徹底し、定期的な確認を行う必要があります。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00765', 'INC-2024-00765', '本事象に関する調査を行った結果、インフラメンテナンス明けに発生したDNS解決成功後にTLS握手での接続切断が確認されました。プロキシ証明書の期限切れが原因である可能性が高いです。証明書の更新を怠っていたことが明らかとなり、今後の対策としては証明書管理の強化が求められます。', '本事象に関する調査を行った結果、インフラメンテナンス明けに発生したDNS解決成功後にTLS握手での接続切断が確認されました。プロキシ証明書の期限切れが原因である可能性が高いです。証明書の更新を怠っていたことが明らかとなり、今後の対策としては証明書管理の強化が求められます。', TIMESTAMP WITH TIME ZONE '2024-08-26T04:06:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01136', 'INC-2024-00765', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-25T04:21:25+09:00', TIMESTAMP WITH TIME ZONE '2024-08-25T05:21:25+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', '発生から直ちに影響範囲を確認し、顧客店舗への連絡を行いました。また、社内での迅速な情報共有を行い、原因調査を開始しました。障害復旧に向けた取り組みとして、プロキシ証明書の確認および更新作業を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00768', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-17T10:39:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T11:09:15+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2024-08-17 10:39:15に、株式会社ストッククラウドのVenusサービスにおいて、同一アラートが短時間に数百件発報しました。この現象は大規模セール開始直前に発生しました。運用部門の運用 一郎が発見し、10:55:15に検知されました。原因としてはアラート抑制ルールの未設定が疑われ、影響範囲は運用部門のみとなっております。エラーコードはMON-02-00768です。今後、アラート疲労を解消するための対策が必要です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00768', 'INC-2024-00768', '発生したアラート疲労の原因を調査した結果、大規模セール開始直前に、同一アラートが多数発報したことが確認されました。アラート抑制ルールが未設定であるため、短時間にアラートが集中して発報したものと考えられます。運用部門における影響が限定的であったことは幸いでしたが、再発防止策を早急に講じる必要があります。', '発生したアラート疲労の原因を調査した結果、大規模セール開始直前に、同一アラートが多数発報したことが確認されました。アラート抑制ルールが未設定であるため、短時間にアラートが集中して発報したものと考えられます。運用部門における影響が限定的であったことは幸いでしたが、再発防止策を早急に講じる必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-18T11:09:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01141', 'INC-2024-00768', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-17T11:24:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T12:24:15+09:00', '【初期対応】【監視・可用性障害】アラート疲労への初期対応', '運用部門では、発報されたアラートの抑制ルールを設定する必要があります。まず、同一アラートの発報を抑制し、監視体制を強化するため、システム設定の見直しを行います。また、今回の発報状況を詳細に分析し、複数回のアラート発報の原因を特定し、必要に応じてアラート管理ポリシーを再構築します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01142', 'INC-2024-00768', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-17T12:54:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-17T13:54:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00769', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-02T23:55:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T00:10:15+09:00', '【障害報告】【運用操作・権限障害】ロールバック途中停止', '2024年8月2日23時55分15秒、株式会社ストッククラウドのVenusにおいて、運用者の作業ミスにより運用コンソールでのロールバック操作が途中で停止し、不整合が発生しました。この影響により、サービス全体の一部機能が利用できない状態となりました。発生の契機は、定例リリース直後であり、リリース手順のスキップが原因と推定されています。現時点でのエラーコードとしてOPS-05-00769が確認されており、定例リリースの手順に従うことが重要であると教訓が得られました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00769', 'INC-2024-00769', '運用部の運用 一郎が発見したこのインシデントは、定例リリース後にロールバック操作が途中で停止したことに起因しています。調査の結果、リリース手順のスキップが原因であることが確認されました。運用コンソールおよびデプロイパイプラインにおける手順の遵守が不足していたことが影響を及ぼしました。今後は手順の明確化と、運用者への教育が必要です。', '運用部の運用 一郎が発見したこのインシデントは、定例リリース後にロールバック操作が途中で停止したことに起因しています。調査の結果、リリース手順のスキップが原因であることが確認されました。運用コンソールおよびデプロイパイプラインにおける手順の遵守が不足していたことが影響を及ぼしました。今後は手順の明確化と、運用者への教育が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-04T00:10:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01143', 'INC-2024-00769', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-03T00:25:15+09:00', TIMESTAMP WITH TIME ZONE '2024-08-03T01:25:15+09:00', '【初期対応】【運用操作・権限障害】ロールバック途中停止', 'インシデント発生直後、運用部は速やかに原因調査を開始し、運用コンソールの状態を確認しました。ロールバック操作が途中で停止したことを確認後、影響を受けたサービス機能の復旧に向けて就業員を動員しました。リリース手順の見直しを提案し、今後の再発防止策を議論するための会議を設定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00774', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-09-11T10:18:44+09:00', TIMESTAMP WITH TIME ZONE '2024-09-11T11:03:44+09:00', '【障害報告】【ストレージ・容量障害】監査ログ削除未実行', '2024年9月11日10時18分44秒に、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れの障害が発生いたしました。顧客である架空食品店Bと架空食品店Aにおいて、古い監査ログ削除ジョブが未実行となっておりました。この問題は、定例リリース直後に発生し、容量アラート閾値の未設定が推定される原因です。影響範囲はバッチ処理のみで、オンラインには影響がありませんが、ストレージ・容量の問題として、早急な対応が求められます。エラーコードはSTR-05-00774です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00774', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00774', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00774', 'INC-2024-00774', '本障害の調査を行ったところ、定例リリース直後に古い監査ログ削除ジョブが未実行となっていることが確認されました。容量アラートの閾値が未設定であったため、監査ログが削除されず、ストレージの容量が逼迫している状態です。今後、アラート設定を見直し、監査ログ削除ジョブの定期的な実行を確実にする必要があります。', '本障害の調査を行ったところ、定例リリース直後に古い監査ログ削除ジョブが未実行となっていることが確認されました。容量アラートの閾値が未設定であったため、監査ログが削除されず、ストレージの容量が逼迫している状態です。今後、アラート設定を見直し、監査ログ削除ジョブの定期的な実行を確実にする必要があります。', TIMESTAMP WITH TIME ZONE '2024-09-12T11:03:44+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01151', 'INC-2024-00774', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-11T11:18:44+09:00', TIMESTAMP WITH TIME ZONE '2024-09-11T12:18:44+09:00', '【初動対応】【ストレージ・容量障害】監査ログ削除未実行', '障害発生の報告を受け、運用部の運用 一郎が即座に対応を開始しました。まず、古い監査ログ削除ジョブの実行状況を確認し、エラーコードSTR-05-00774に関連する記録を調査しました。その結果、容量アラート閾値が未設定であったことが原因であると特定し、即座に設定を見直す手続きを開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01152', 'INC-2024-00774', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-11T12:48:44+09:00', TIMESTAMP WITH TIME ZONE '2024-09-11T13:48:44+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00775', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-11-30T09:45:10+09:00', TIMESTAMP WITH TIME ZONE '2024-11-30T10:45:10+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2024年11月30日09時45分に、株式会社ストッククラウドの顧客である架空食品店Aにおいて、顧客拠点NWに関するネットワーク障害が発生しました。症状として、SD-WANが劣化回線を選択し、遅延が増大しました。これは、大規模セール開始直前という発生契機に関連しており、同一顧客の全店舗に影響を及ぼしました。エラーコードはNW-10-00775であり、技術詳細としては、SD-WANポリシーの閾値設定誤りが推定されます。検知は2024年11月30日10時31分に行われ、障害発生から46分後のことでした。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00775', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00775', 'INC-2024-00775', '調査の結果、SD-WANが劣化回線を選択した原因は、ポリシー設定における閾値設定の誤りであることが確認されました。この設定により、経路選択の精度が低下し、結果として顧客ネットワークに遅延を引き起こしました。大規模セールという特別な状況下での影響が顕著化したため、即時の対応が求められました。', '調査の結果、SD-WANが劣化回線を選択した原因は、ポリシー設定における閾値設定の誤りであることが確認されました。この設定により、経路選択の精度が低下し、結果として顧客ネットワークに遅延を引き起こしました。大規模セールという特別な状況下での影響が顕著化したため、即時の対応が求められました。', TIMESTAMP WITH TIME ZONE '2024-12-01T10:45:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01153', 'INC-2024-00775', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-11-30T11:00:10+09:00', TIMESTAMP WITH TIME ZONE '2024-11-30T12:00:10+09:00', '【初動対応】【顧客ネットワーク障害】SD-WAN経路選択誤り', '初動対応として、チームは2024年11月30日09時50分に状況を把握し、SD-WANポリシーの見直しを開始しました。営業部の花子が顧客とのコミュニケーションを取り、障害の詳細を報告しました。問題解決に向けた迅速な対応が求められ、情報を共有しながら、各店舗への影響を最小限に抑える努力を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00777', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-07-14T05:22:41+09:00', TIMESTAMP WITH TIME ZONE '2024-07-14T06:22:41+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2024年7月14日05時22分41秒、株式会社ストッククラウドの顧客である架空食品店B及び架空食品店Aにおいて、顧客拠点NWにおけるネットワーク障害が発生しました。この障害により、DNS解決は成功しましたが、TLS握手の際に接続が切断される症状が現れました。この問題は全店舗に影響を及ぼし、顧客はサービスの利用に支障をきたしました。発生契機はインフラメンテナンスの完了直後であり、推定原因としてプロキシ証明書の期限切れが考えられます。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00777', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00777', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00777', 'INC-2024-00777', '当該インシデントにおける技術詳細を確認した結果、インフラメンテナンス明けにDNS解決が成功したものの、TLS握手での接続切断が発生したことが分かりました。プロキシ証明書の期限切れが原因と推定され、この問題が顧客全店舗に影響を及ぼしたことが確認されました。今後は、証明書の管理と監視体制を強化し、再発防止に努める必要があります。', '当該インシデントにおける技術詳細を確認した結果、インフラメンテナンス明けにDNS解決が成功したものの、TLS握手での接続切断が発生したことが分かりました。プロキシ証明書の期限切れが原因と推定され、この問題が顧客全店舗に影響を及ぼしたことが確認されました。今後は、証明書の管理と監視体制を強化し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2024-07-15T06:22:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01155', 'INC-2024-00777', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-07-14T06:37:41+09:00', TIMESTAMP WITH TIME ZONE '2024-07-14T07:37:41+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', 'インシデント発生直後、営業部の花子が顧客へ連絡を行い、現状の把握と初期対応に着手しました。ネットワーク状況の詳細確認を行い、プロキシ証明書の状態を調査するよう指示しました。また、全店舗への影響範囲を確認し、迅速な復旧作業の手配を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00780', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-07T07:15:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T08:15:16+09:00', '【障害報告】【顧客ネットワーク障害】代理サーバー502', '・発生日時: 2024-08-07T07:15:16+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00780', 'INC-2024-00780', '現在、代理サーバーを通じたアクセスが502エラーを返す原因を調査中です。プロキシの上流タイムアウト設定が過短である可能性が高いと考えています。関連する設定やログを確認し、問題の根本原因を特定するために作業を進めます。また、影響を受けた顧客の情報を収集し、対応を行う準備を整えています。', '現在、代理サーバーを通じたアクセスが502エラーを返す原因を調査中です。プロキシの上流タイムアウト設定が過短である可能性が高いと考えています。関連する設定やログを確認し、問題の根本原因を特定するために作業を進めます。また、影響を受けた顧客の情報を収集し、対応を行う準備を整えています。', TIMESTAMP WITH TIME ZONE '2024-08-08T08:15:16+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01160', 'INC-2024-00780', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-07T08:30:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T09:30:16+09:00', '【初期対応】【顧客ネットワーク障害】代理サーバー502', 'インシデント発生後、直ちに調査チームを編成しました。代理サーバーの設定を確認し、プロキシの上流タイムアウト設定の見直しを行います。顧客への影響を最小限に抑えるため、暫定的な回避策として他の接続経路を提案しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01161', 'INC-2024-00780', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-07T10:00:16+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T11:00:16+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00782', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2024-08-11T01:20:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T01:50:50+09:00', '【障害報告】【認証・セッション障害】Cookie SameSite拒否', '2024年8月11日01時20分頃、株式会社ストッククラウドのサービスVenusにおいて、Cookie SameSite設定の影響により埋込画面が認証不可となる事象が発生しました。発見者の運用 一郎が報告したところによれば、定例リリース直後という発生契機から、SameSite属性変更が原因である可能性が示唆されています。この問題は現在、単一店舗に影響を及ぼしており、エラーコードはAUTH-06-00782です。20分後の01時40分に検知され、影響を受けたコンポーネントはVenus Azure APおよびセッションストアです。早急な対応が必要です。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00782', 'INC-2024-00782', '現在、運用 一郎を中心に調査を進めています。リリース直後に発生したこの問題の原因として、SameSite属性変更が疑われています。Cookieの設定が原因で埋込画面が認証不可とされ、影響範囲は単一店舗に限定されているため、迅速な対処が重要です。今後、詳細な技術分析を行い、必要な修正を加える方針です。', '現在、運用 一郎を中心に調査を進めています。リリース直後に発生したこの問題の原因として、SameSite属性変更が疑われています。Cookieの設定が原因で埋込画面が認証不可とされ、影響範囲は単一店舗に限定されているため、迅速な対処が重要です。今後、詳細な技術分析を行い、必要な修正を加える方針です。', TIMESTAMP WITH TIME ZONE '2024-08-12T01:50:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01163', 'INC-2024-00782', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-11T02:05:50+09:00', TIMESTAMP WITH TIME ZONE '2024-08-11T03:05:50+09:00', '【初期対応】【認証・セッション障害】Cookie SameSite拒否に関する初期対応', '運用 一郎より、Cookie SameSite設定に起因する認証不可の事象について初期対応が開始されました。定例リリース後、この問題が発生したため、リリース内容を確認し、SameSite属性の変更を元に戻すことを検討しています。影響を受ける店舗への連絡も含め、迅速な情報共有を図ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00785', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-02-02T10:57:32+09:00', TIMESTAMP WITH TIME ZONE '2024-02-02T11:12:32+09:00', '【障害報告】【CLU-10】死活監視誤検知', '2024年2月2日10時57分32秒に、株式会社ストッククラウドの運用コンソールにおいて、死活監視が正常系をDOWNと誤検知する事象が発生しました。顧客には架空食品店A及び架空食品店Bが含まれ、影響範囲は運用部門のみとなっています。本事象は定例リリース直後に発生し、監視プローブのUser-Agentブロックが推定原因と考えられます。本障害は高い重大度を持つため、速やかに対応が必要です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00785', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00785', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00785', 'INC-2024-00785', '発生した死活監視による誤検知の調査を開始し、原因として監視プローブのUser-Agentがブロックされている可能性に着目しました。また、定例リリースに伴う影響を確認し、監視・可用性障害に関する詳細な分析を行っています。現在、運用コンソールにおける死活監視の正常性についても調査を進めており、顧客への影響を最小限に抑えるための対策を検討中です。', '発生した死活監視による誤検知の調査を開始し、原因として監視プローブのUser-Agentがブロックされている可能性に着目しました。また、定例リリースに伴う影響を確認し、監視・可用性障害に関する詳細な分析を行っています。現在、運用コンソールにおける死活監視の正常性についても調査を進めており、顧客への影響を最小限に抑えるための対策を検討中です。', TIMESTAMP WITH TIME ZONE '2024-02-03T11:12:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01168', 'INC-2024-00785', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-02T11:27:32+09:00', TIMESTAMP WITH TIME ZONE '2024-02-02T12:27:32+09:00', '【初動対応】【CLU-10】死活監視誤検知', 'インシデント発生を受けて、運用部門は直ちに対応を開始しました。まず、監視データを確認し、誤検知の原因と考えられる要因を特定しました。次に、監視プローブの設定を見直し、必要に応じて修正を加えることとしました。顧客への影響を考慮し、迅速な情報提供を行う方針を決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01169', 'INC-2024-00785', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-02-02T12:57:32+09:00', TIMESTAMP WITH TIME ZONE '2024-02-02T13:57:32+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00796', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2024-08-15T10:40:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T12:40:04+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2024-08-15 10:40:04
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00796', 'INC-2024-00796', '調査を開始しました。まず、冪等キー生成ロジックの詳細を確認し、重複の原因を特定するためのログを検査しています。特に、定例リリース後の変更点を確認中です。また、API連携・EDIに関連する全ての顧客店舗POSのデータを集め、再現性を検証しています。', '調査を開始しました。まず、冪等キー生成ロジックの詳細を確認し、重複の原因を特定するためのログを検査しています。特に、定例リリース後の変更点を確認中です。また、API連携・EDIに関連する全ての顧客店舗POSのデータを集め、再現性を検証しています。', TIMESTAMP WITH TIME ZONE '2024-08-16T12:40:04+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01185', 'INC-2024-00796', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-15T12:55:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T13:55:04+09:00', '【初期対応】【CLU-07】冪等キー重複への初期対応', 'この問題に対しては、即座に顧客店舗POSの在庫更新プロセスを一時停止し、冪等キーの生成ロジックを見直す手続きを開始しました。重複が確認されたエントリを手動で修正し、再発防止策を講じることを計画しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01186', 'INC-2024-00796', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-15T14:25:04+09:00', TIMESTAMP WITH TIME ZONE '2024-08-15T15:25:04+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00799', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-09T21:49:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T22:19:20+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2024年8月9日21時49分20秒に、株式会社ストッククラウドのサービスVenusにおいて、マスター設定ミスによる在庫登録失敗が発生いたしました。これは、データ移行バッチ実行中に、スナップショット復元後に在庫整合が崩れるという症状が見られました。全テナントに波及する影響があり、原因として復元ポイントのトランザクションログ欠落が推定されます。エラーコードはSYNC-09-00799であり、影響コンポーネントはMercury AWS AP（ゾーンB）のバックアップ管理です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00799', 'INC-2024-00799', '本事象についての調査を行った結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れる現象が発生したことが確認されました。復元ポイントのトランザクションログが欠落していることが、この整合崩れの主な原因であると考えられます。全テナントに影響が及んでいるため、早急な対応が必要です。', '本事象についての調査を行った結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れる現象が発生したことが確認されました。復元ポイントのトランザクションログが欠落していることが、この整合崩れの主な原因であると考えられます。全テナントに影響が及んでいるため、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-10T22:19:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01190', 'INC-2024-00799', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-09T22:34:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T23:34:20+09:00', '【初動対応】【データ同期・整合性障害】スナップショット復元不整合', '初動対応として、復元ポイントのトランザクションログの確認を行い、欠落しているデータの特定を進めています。また、影響を受けたすべてのテナントに対し、状況説明を行いました。今後の対応策についても、早急に検討を進め、必要な修正を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01191', 'INC-2024-00799', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-10T00:04:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-10T01:04:20+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00800', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-18T00:34:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T01:04:38+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2024-08-18T00:34:38+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00800', 'INC-2024-00800', '本インシデントは、2024年8月18日に発生しました。冪等キーが重複したことにより、在庫更新がスキップされました。定例リリース直後の状況下で、冪等キー生成ロジックの衝突が推定されます。この問題は、API連携の品質に影響を及ぼす可能性があるため、早急に対策が必要です。', '本インシデントは、2024年8月18日に発生しました。冪等キーが重複したことにより、在庫更新がスキップされました。定例リリース直後の状況下で、冪等キー生成ロジックの衝突が推定されます。この問題は、API連携の品質に影響を及ぼす可能性があるため、早急に対策が必要です。', TIMESTAMP WITH TIME ZONE '2024-08-19T01:04:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01192', 'INC-2024-00800', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-18T01:19:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T02:19:38+09:00', '【初期対応】【CLU-07】冪等キー重複への対応', '運用部の運用 一郎が初期対応を実施しました。冪等キー重複の原因を調査し、システムログを確認しました。また、該当APIの動作を検証し、冪等キー生成ロジックの見直しを進めています。対応が完了次第、再発防止策を講じる予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01193', 'INC-2024-00800', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-18T02:49:38+09:00', TIMESTAMP WITH TIME ZONE '2024-08-18T03:49:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00803', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-08-07T11:47:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T12:32:20+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2024年8月7日11時47分に株式会社ストッククラウドのVenusにおいて、ストレージ溢れのインシデントが発生しました。症状はヘルスチェック過多によるAPサーバーの負荷増加で、全テナントに波及する影響がありました。エラーコードはMON-06-00803に関連し、発生契機はインフラメンテナンス明けです。現状、Mercury AWS Storageにおいて負荷が集中しており、運用部の運用 一郎がこの事象を発見しました。監視・可用性障害の観点から、早急な対応が求められます。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00803', 'INC-2024-00803', '運用 一郎が発見したこのインシデントについて、調査を行った結果、原因としてLBヘルスチェック間隔の過短設定が疑われます。ヘルスチェックに関する設定を見直し、負荷を軽減する必要があります。過負荷の状況が続くと、サービスの可用性に重大な影響を及ぼす可能性が高いため、他のテナントへの影響を考慮しながら早急な対応を進めていく必要があります。', '運用 一郎が発見したこのインシデントについて、調査を行った結果、原因としてLBヘルスチェック間隔の過短設定が疑われます。ヘルスチェックに関する設定を見直し、負荷を軽減する必要があります。過負荷の状況が続くと、サービスの可用性に重大な影響を及ぼす可能性が高いため、他のテナントへの影響を考慮しながら早急な対応を進めていく必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-08T12:32:20+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01197', 'INC-2024-00803', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-07T12:47:20+09:00', TIMESTAMP WITH TIME ZONE '2024-08-07T13:47:20+09:00', '【初動対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎が初動対応を行い、LBヘルスチェックの間隔設定を確認する作業に着手しました。今回の監視・可用性障害において、ヘルスチェックの設定が過剰であることが原因かもしれないため、まずは設定を適宜調整し、APサーバーの負荷を軽減させる方針です。全テナントに影響を与えないよう慎重に対応を進めていきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00805', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2024-08-09T20:41:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T21:41:51+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2024年8月9日20時41分51秒、株式会社ストッククラウドの顧客ネットワークにおいて、店舗VPN経由でSaaSに到達できないという障害が発生しました。影響範囲は単一店舗に限られ、原因として拠点FWのルール変更が推定されています。この障害は顧客オンボーディング当日に発生し、顧客拠点NWと拠点VPNゲートウェイが影響を受けたと考えられます。検知は2024年8月9日21時25分51秒に行われ、発見者は営業部の花子です。現在、解決に向けた調査を行っております。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00805', 'INC-2024-00805', '障害発生の原因として拠点FWのルール変更が疑われています。店舗VPN経由でSaaSに到達できない事象が顧客オンボーディング当日に発生したため、これに関連するネットワーク設定の変更があった可能性があります。詳細な技術調査を進めており、FW設定の履歴を確認中です。影響を受けた店舗の特定と、迅速な復旧作業を優先して行っています。', '障害発生の原因として拠点FWのルール変更が疑われています。店舗VPN経由でSaaSに到達できない事象が顧客オンボーディング当日に発生したため、これに関連するネットワーク設定の変更があった可能性があります。詳細な技術調査を進めており、FW設定の履歴を確認中です。影響を受けた店舗の特定と、迅速な復旧作業を優先して行っています。', TIMESTAMP WITH TIME ZONE '2024-08-10T21:41:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01199', 'INC-2024-00805', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2024-08-09T21:56:51+09:00', TIMESTAMP WITH TIME ZONE '2024-08-09T22:56:51+09:00', '【初期対応】【顧客ネットワーク障害】店舗VPN到達不可', '初期対応として、拠点FWの設定を確認し、ルール変更の有無を調査しています。また、顧客への影響を最小限に抑えるため、仮のVPN接続方法を提案しております。現在、セキュリティログや設定変更の履歴を精査しており、再発防止策の検討も並行して行っています。顧客への進捗報告も随時行い、透明性を持った対応を心がけています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00806', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-08-19T04:44:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T04:59:30+09:00', '【障害報告】【認証・セッション障害】リフレッシュトークン再利用', '2024年8月19日04時44分30秒、株式会社ストッククラウドのサービスVenusにおいて、運用者の作業ミスによるアクセス障害が発生しました。リフレッシュトークン再利用が検知され、全端末がログアウトしました。この問題は年末年始の稼働切替時に発生し、トークンローテーションの実装に不備があったと推定されます。障害は運用コンソールに影響を及ぼし、全店舗に広がりました。問題は2024年8月19日05時02分30秒に検知され、運用部の運用 一郎が発見しました。この障害によってすべての端末からの認証が失敗し、ユーザーはサービスにアクセスできなくなる影響を受けました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00806', 'INC-2024-00806', '障害発生後、初期調査を行った結果、リフレッシュトークン再利用の検知が問題の根源であることが確認されました。具体的には、年末年始の稼働切替時にトークンローテーションの実装に不備があり、これが全ユーザーのセッションを無効化する原因となりました。今後の対策として、実装の見直しとテストを強化し、再発防止に努める必要があります。', '障害発生後、初期調査を行った結果、リフレッシュトークン再利用の検知が問題の根源であることが確認されました。具体的には、年末年始の稼働切替時にトークンローテーションの実装に不備があり、これが全ユーザーのセッションを無効化する原因となりました。今後の対策として、実装の見直しとテストを強化し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2024-08-20T04:59:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01200', 'INC-2024-00806', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-19T05:14:30+09:00', TIMESTAMP WITH TIME ZONE '2024-08-19T06:14:30+09:00', '初期対応', '障害発生の通知を受け、即座にサポートチームが投入され、運用コンソールの状況を確認しました。リフレッシュトークンの再利用に関連するシステムログを確認し、トークンローテーション機能の不備を特定しました。ユーザーへの影響を最小限に抑えるため、緊急の修正とトークンローテーションの再実施を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00807', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2024-09-20T05:26:11+09:00', TIMESTAMP WITH TIME ZONE '2024-09-20T05:41:11+09:00', '【障害報告】【CLU-10】ヘルスチェック過負荷', '2024年09月20日05時26分に、顧客「架空食品店B」において、運用者の作業ミスによるアクセス障害が発生しました。症状として、ヘルスチェック過多でAPサーバー負荷が増加しました。原因としては、LBヘルスチェック間隔の過短設定が疑われ、全テナントに波及する影響がありました。この障害は、インフラメンテナンス明けに発生したものであり、運用コンソールにおける監視・可用性障害が原因です。現時点でのエラーコードはMON-06-00807です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00807', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00807', 'INC-2024-00807', '運用部の運用 一郎です。現在、発生した監視・可用性障害に関する調査を進めています。インフラメンテナンス明けにおけるヘルスチェックが過多になり、その結果APサーバーへの負荷が増加した状況です。LBヘルスチェック間隔設定の見直しが必要であり、影響を受けた全テナントへの影響範囲を確認する必要があります。また、根本原因の特定を急ぎます。', '運用部の運用 一郎です。現在、発生した監視・可用性障害に関する調査を進めています。インフラメンテナンス明けにおけるヘルスチェックが過多になり、その結果APサーバーへの負荷が増加した状況です。LBヘルスチェック間隔設定の見直しが必要であり、影響を受けた全テナントへの影響範囲を確認する必要があります。また、根本原因の特定を急ぎます。', TIMESTAMP WITH TIME ZONE '2024-09-21T05:41:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01201', 'INC-2024-00807', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-20T05:56:11+09:00', TIMESTAMP WITH TIME ZONE '2024-09-20T06:56:11+09:00', '【初期対応】【CLU-10】ヘルスチェック過負荷への初期対応', '運用部の運用 一郎です。ヘルスチェック過多によるAPサーバー負荷の増加が確認されました。迅速にLBヘルスチェックの間隔設定を見直し、負荷を軽減する対応を行います。また、全テナントへの影響を最小限に抑えるため、監視体制を強化し、必要に応じてメンテナンスを実施します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01202', 'INC-2024-00807', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-09-20T07:26:11+09:00', TIMESTAMP WITH TIME ZONE '2024-09-20T08:26:11+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00808', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-04-12T00:21:01+09:00', TIMESTAMP WITH TIME ZONE '2024-04-12T00:51:01+09:00', '【障害報告】【CLU-09】楽観ロック競合多発', '2024年4月12日00時21分に、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。具体的には、楽観ロック競合が多発し、更新失敗率が上昇しました。この事象は、全テナントに波及するもので、特に大規模セール開始直前に発生したことが影響を及ぼしました。エラーコードはSYNC-10-00808で、影響を受けたコンポーネントはMercury AWS AP（DRサイト）および在庫登録APIです。問題が発生してから39分後の01時00分に検知されました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00808', 'INC-2024-00808', '今回の事象を調査した結果、楽観ロック競合が発生した主な原因は、バージョンカラム更新ロジックの不備であると考えられます。このロジックが正しく機能しないことで、データ同期における整合性が損なわれ、結果として更新失敗が多発しました。調査を進める中で、全テナントに影響が出ていることが確認され、早急な対応が求められる状況でした。', '今回の事象を調査した結果、楽観ロック競合が発生した主な原因は、バージョンカラム更新ロジックの不備であると考えられます。このロジックが正しく機能しないことで、データ同期における整合性が損なわれ、結果として更新失敗が多発しました。調査を進める中で、全テナントに影響が出ていることが確認され、早急な対応が求められる状況でした。', TIMESTAMP WITH TIME ZONE '2024-04-13T00:51:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01203', 'INC-2024-00808', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-04-12T01:06:01+09:00', TIMESTAMP WITH TIME ZONE '2024-04-12T02:06:01+09:00', '【初動対応】【CLU-09】楽観ロック競合多発', '2024年4月12日01時00分に、楽観ロック競合による在庫登録失敗の問題を検知し、運用部の運用 一郎が初動対応を開始しました。影響を受けている全テナントへの通知を行い、暫定的な回避策として、バージョンカラム更新ロジックの修正案を検討しました。また、影響の拡大を防ぐため、問題の影響範囲を特定し、優先的に対策を講じるよう指示しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00816', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-10-06T14:53:07+09:00', TIMESTAMP WITH TIME ZONE '2024-10-06T15:23:07+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2024年10月6日14時53分に、架空食品店AにおいてOAuthトークンが失効し、POS連携が中断される事象が発生しました。本事象の発見者は運用部の運用 一郎であり、15時13分に検知されたことが確認されています。この障害は、Mercury AWS APに関連しており、影響を受けるのは単一店舗のみです。エラーコードはEDI-05-00816です。年末年始の稼働切替時におけるリフレッシュトークンの保存先に障害があったことが推定され、結果としてAPI連携・EDIに影響を及ぼしました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00816', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00816', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00816', 'INC-2024-00816', '調査の結果、OAuthトークン失効によるPOS連携の中断が確認されました。主な原因としてリフレッシュトークン保存先の障害が疑われています。影響を受けたのは架空食品店Aのみであり、他店舗に対する影響は認められません。この問題は年末年始の稼働切替時に発生したため、特に注意が必要です。今後の再発防止策として、トークン管理の見直しを検討する必要があります。', '調査の結果、OAuthトークン失効によるPOS連携の中断が確認されました。主な原因としてリフレッシュトークン保存先の障害が疑われています。影響を受けたのは架空食品店Aのみであり、他店舗に対する影響は認められません。この問題は年末年始の稼働切替時に発生したため、特に注意が必要です。今後の再発防止策として、トークン管理の見直しを検討する必要があります。', TIMESTAMP WITH TIME ZONE '2024-10-07T15:23:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01214', 'INC-2024-00816', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-10-06T15:38:07+09:00', TIMESTAMP WITH TIME ZONE '2024-10-06T16:38:07+09:00', '【初期対応】OAuthトークン失効', '初期対応として、運用部はトークンシステムの確認及びリフレッシュトークン保存先の障害の修正を行いました。また、架空食品店Aへの状況説明と営業への影響を最小限に抑えるための連携を行いました。POS連携の復旧を最優先に進め、その後トークン管理システムの監視を強化する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00817', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2024-12-12T16:12:09+09:00', TIMESTAMP WITH TIME ZONE '2024-12-12T16:57:09+09:00', '【障害報告】【監視・可用性障害】合成監視失敗', '2024年12月12日16時12分09秒に、株式会社ストッククラウドのMercuryにおいて、合成監視が特定ステップで失敗しました。この問題は、架空食品店A及び架空食品店Bに影響を及ぼすもので、サービス全体の一部機能に影響が出ています。エラーコードはMON-08-00817です。発生契機は定例リリース直後であり、テストデータの期限切れが推定原因として考えられます。運用部の運用 一郎が発見し、2024年12月12日17時02分09秒に検知されました。このインシデントは監視・可用性障害に関連しており、技術詳細として定例リリース直後に合成監視が特定ステップで失敗していることが挙げられます。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00817', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2024-00817', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00817', 'INC-2024-00817', '今回の合成監視失敗について、テストデータの期限切れが原因と推測されます。特定のステップでの失敗が確認されており、これが監視・可用性障害につながっています。定例リリース後の監視状況を詳細に確認し、テストデータ更新の管理体制を見直す必要があります。また、影響範囲の特定と、関連する合成監視ランナーの状態も併せて調査中です。', '今回の合成監視失敗について、テストデータの期限切れが原因と推測されます。特定のステップでの失敗が確認されており、これが監視・可用性障害につながっています。定例リリース後の監視状況を詳細に確認し、テストデータ更新の管理体制を見直す必要があります。また、影響範囲の特定と、関連する合成監視ランナーの状態も併せて調査中です。', TIMESTAMP WITH TIME ZONE '2024-12-13T16:57:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01215', 'INC-2024-00817', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-12-12T17:12:09+09:00', TIMESTAMP WITH TIME ZONE '2024-12-12T18:12:09+09:00', '【初期対応】合成監視失敗の対応', '合成監視が失敗したことを受け、運用部の運用 一郎が即座に調査を開始しました。テストデータの確認と更新を行い、特定ステップの問題解決に向けて作業を進めています。今後、テストデータの管理を強化し、再発防止策を検討する必要があります。お客様には適時情報を提供し、影響を最小限に抑えるよう努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2024-00818', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2024-08-20T05:40:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T06:10:40+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2024-08-20T05:40:40+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00818', 'INC-2024-00818', '本インシデントは、2024年8月20日に発生した冪等キーの重複が原因で在庫更新がスキップされたことに関連しています。定例リリース後、この問題が発生し、冪等キー生成ロジックの衝突が確認されています。影響を受けたのは同一顧客の全店舗であり、迅速な対応が求められます。改善策として、冪等キー生成ロジックの見直しが必要です。', '本インシデントは、2024年8月20日に発生した冪等キーの重複が原因で在庫更新がスキップされたことに関連しています。定例リリース後、この問題が発生し、冪等キー生成ロジックの衝突が確認されています。影響を受けたのは同一顧客の全店舗であり、迅速な対応が求められます。改善策として、冪等キー生成ロジックの見直しが必要です。', TIMESTAMP WITH TIME ZONE '2024-08-21T06:10:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01216', 'INC-2024-00818', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2024-08-20T06:25:40+09:00', TIMESTAMP WITH TIME ZONE '2024-08-20T07:25:40+09:00', '初期対応', 'インシデントの発生が確認された際に、運用部の運用 一郎が担当し、直ちに調査を開始しました。冪等キーの重複に関する詳細な情報を収集し、影響範囲を特定するための分析を行いました。定例リリース後に発生したことから、リリース内容の確認を進め、問題解決に向けた対策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00014', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-03-30T17:40:37+09:00', TIMESTAMP WITH TIME ZONE '2025-03-30T18:25:37+09:00', '【障害報告】【ストレージ・容量障害】DB自動拡張上限', '2025年3月30日17時40分37秒、株式会社ストッククラウドのサービスMercuryにおいて、DB自動拡張が上限に到達し書込停止の事象が発生しました。影響範囲は全テナントに波及し、特に架空食品店Bのご利用が大きな影響を受けました。発生の契機は大規模セール開始直前であり、DB自動拡張の上限設定不足が推定原因とされています。影響を受けたコンポーネントはMercury AWS Storage（ゾーンA）のDBデータファイルです。事象が発生した後、運用部の運用 一郎が検知し、18時00分37秒に報告されました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00014', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00014', 'INC-2025-00014', '調査の結果、大規模セール開始直前にDB自動拡張が上限に到達し書込停止したことが確認されました。DB拡張の上限設定が不足していたため、本事象が引き起こされました。本来であればDB自動拡張の上限を見直し、適切な設定を行っておく必要がありました。この問題を未然に防ぐために、今後の施策として定期的な設定の確認や、監視体制の強化が求められます。', '調査の結果、大規模セール開始直前にDB自動拡張が上限に到達し書込停止したことが確認されました。DB拡張の上限設定が不足していたため、本事象が引き起こされました。本来であればDB自動拡張の上限を見直し、適切な設定を行っておく必要がありました。この問題を未然に防ぐために、今後の施策として定期的な設定の確認や、監視体制の強化が求められます。', TIMESTAMP WITH TIME ZONE '2025-03-31T18:25:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00020', 'INC-2025-00014', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-30T18:40:37+09:00', TIMESTAMP WITH TIME ZONE '2025-03-30T19:40:37+09:00', '【初期対応】【ストレージ・容量障害】DB自動拡張上限に関する初期対応', '初期対応として、運用部の運用 一郎が直ちにDB設定を確認し、上限の設定を見直す作業を開始しました。また、影響を受けた顧客である架空食品店Bへの連絡を行い、事象の概要と現在の対応状況を説明しました。さらに、DB自動拡張の設定を迅速に調整し、書込停止の復旧を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00021', 'INC-2025-00014', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-30T20:10:37+09:00', TIMESTAMP WITH TIME ZONE '2025-03-30T21:10:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00016', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-09-05T23:57:38+09:00', TIMESTAMP WITH TIME ZONE '2025-09-06T00:57:38+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2025年9月5日23時57分38分に、株式会社ストッククラウドの顧客である架空食品店Aにおいて、店舗VPN経由でSaaSに到達できない障害が発生しました。影響範囲は単一店舗に限定されており、顧客拠点NW（ゾーンB）のVPNゲートウェイに関連しています。本事象は顧客オンボーディング当日に発生しており、拠点FWのルール変更が推定原因として考えられます。障害の検知は2025年9月6日00時45分38分で、発見者は営業部の花子です。お客様には多大なるご迷惑をおかけし、誠に申し訳ございません。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00016', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00016', 'INC-2025-00016', '本障害の調査を行った結果、顧客オンボーディング当日に発生したため、拠点FWのルール変更が影響を及ぼしている可能性が高いことが判明しました。VPN接続が確立されないため、店舗がSaaSにアクセスできない状態が続いており、迅速な復旧が求められます。今後、FWの設定確認を徹底し、再発防止に努めます。', '本障害の調査を行った結果、顧客オンボーディング当日に発生したため、拠点FWのルール変更が影響を及ぼしている可能性が高いことが判明しました。VPN接続が確立されないため、店舗がSaaSにアクセスできない状態が続いており、迅速な復旧が求められます。今後、FWの設定確認を徹底し、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2025-09-07T00:57:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00023', 'INC-2025-00016', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-06T01:12:38+09:00', TIMESTAMP WITH TIME ZONE '2025-09-06T02:12:38+09:00', '【初期対応】【顧客ネットワーク障害】店舗VPN到達不可', '本障害発生の報告を受け、営業部の花子が初期対応を行いました。顧客拠点のFW設定を確認し、ルール変更が実施されていることを確認しました。この情報をもとに、早急にFWの設定を修正し、VPN接続の復旧作業を開始いたしました。顧客には進捗状況を随時報告し、復旧見込みをお知らせいたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00024', 'INC-2025-00016', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-06T02:42:38+09:00', TIMESTAMP WITH TIME ZONE '2025-09-06T03:42:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00047', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-01-11T21:33:14+09:00', TIMESTAMP WITH TIME ZONE '2025-01-11T22:03:14+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2025年1月11日21時33分14秒に株式会社ストッククラウドのサービスMercuryにおいて、死活監視が正常系をDOWNと誤検知する事象が発生しました。本事象は定例リリース直後に発生し、運用部門にのみ影響を与えております。発見時刻は21時56分14秒であり、検知までに23分を要しました。エラーコードはMON-01-00047であり、影響を受けたコンポーネントはVenus Azure AP（ゾーンB）の死活監視です。技術的には、監視プローブのUser-Agentがブロックされている可能性が考えられます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00047', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00047', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00047', 'INC-2025-00047', '死活監視が正常系をDOWNと誤検知した件について調査を行いました。監視プローブの設定を確認したところ、リリース後にUser-Agentがブロックされていることが確認されました。この影響で、正常なサービスがDOWNと誤認識される事態が発生しました。今後の改善策として、監視プローブの設定見直しや、リリース後の即時監視確認を行う必要があります。', '死活監視が正常系をDOWNと誤検知した件について調査を行いました。監視プローブの設定を確認したところ、リリース後にUser-Agentがブロックされていることが確認されました。この影響で、正常なサービスがDOWNと誤認識される事態が発生しました。今後の改善策として、監視プローブの設定見直しや、リリース後の即時監視確認を行う必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-12T22:03:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00065', 'INC-2025-00047', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-11T22:18:14+09:00', TIMESTAMP WITH TIME ZONE '2025-01-11T23:18:14+09:00', '【初期対応】【監視・可用性障害】死活監視誤検知', '本件の初期対応として、運用部門が即座に死活監視の設定を確認し、監視プローブのUser-Agentのブロックを解除しました。また、障害の再発防止に向けて、監視システムの改善を検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00066', 'INC-2025-00047', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-11T23:48:14+09:00', TIMESTAMP WITH TIME ZONE '2025-01-12T00:48:14+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00056', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-01-24T00:00:34+09:00', TIMESTAMP WITH TIME ZONE '2025-01-24T01:00:34+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '本障害は、2025年1月24日00時34分に発生し、顧客拠点NWにおいて店舗Wi-Fiの認証ページでAPI通信が遮断される事象が確認されました。この障害は新規店舗追加の初日に発生し、影響を及ぼしているのは単一店舗のみです。推定原因として、キャプティブポータルによるHTTPSインターセプトが考えられます。顧客名はなし、担当者は営業部の花子が発見しました。エラーコードはNW-09-00056です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00056', 'INC-2025-00056', '調査の結果、店舗Wi-Fiの認証ページでAPI通信が遮断されている事象が確認されました。原因として、キャプティブポータルによるHTTPSインターセプトの可能性が高いと考えられます。影響範囲は単一店舗に限られており、他の店舗への影響は確認されておりません。今後、詳細な分析と対策を進めてまいります。', '調査の結果、店舗Wi-Fiの認証ページでAPI通信が遮断されている事象が確認されました。原因として、キャプティブポータルによるHTTPSインターセプトの可能性が高いと考えられます。影響範囲は単一店舗に限られており、他の店舗への影響は確認されておりません。今後、詳細な分析と対策を進めてまいります。', TIMESTAMP WITH TIME ZONE '2025-01-25T01:00:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00080', 'INC-2025-00056', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-24T01:15:34+09:00', TIMESTAMP WITH TIME ZONE '2025-01-24T02:15:34+09:00', '【対応ログ】【顧客ネットワーク障害】Wi-Fi captive portal', '本障害に関する初期対応を行いました。店舗Wi-Fiの認証ページでのAPI通信の遮断について、キャプティブポータルによるHTTPSインターセプトを疑い、詳細を確認中です。顧客には状況を説明し、引き続き調査を進める旨を伝えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00060', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-05-30T08:57:34+09:00', TIMESTAMP WITH TIME ZONE '2025-05-30T09:27:34+09:00', '【障害報告】【API連携・EDI障害】配送連携ステータス停滞', '株式会社ストッククラウドが提供するVenusに関する障害報告です。本事象は、2025年5月30日08時57分34秒に発生し、顧客である架空服飾店Aにおいて、配送連携のステータスが出荷済みで停滞する事象が確認されました。この問題は、大規模セール開始直前に発生し、影響範囲は単一店舗のみとなっております。検知は2025年5月30日09時19分34秒に行われ、約22分後に問題が特定されました。推定原因として、ステータスマッピング表の更新漏れが考えられ、影響コンポーネントはMercury AWS AP（Primary）および配送連携アダプタです。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00060', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00060', 'INC-2025-00060', '本インシデントに関して、調査を実施しました。配送連携のステータスが出荷済みで停滞していた原因として、ステータスマッピング表の更新漏れが主要な要因であると考えられます。大規模セールの開始直前にこの問題が発生したことから、特にこの期間にマッピング表の適切な更新が行われていなかった可能性があります。引き続き、各設定の確認と必要な修正を進めていく方針です。', '本インシデントに関して、調査を実施しました。配送連携のステータスが出荷済みで停滞していた原因として、ステータスマッピング表の更新漏れが主要な要因であると考えられます。大規模セールの開始直前にこの問題が発生したことから、特にこの期間にマッピング表の適切な更新が行われていなかった可能性があります。引き続き、各設定の確認と必要な修正を進めていく方針です。', TIMESTAMP WITH TIME ZONE '2025-05-31T09:27:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00085', 'INC-2025-00060', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-30T09:42:34+09:00', TIMESTAMP WITH TIME ZONE '2025-05-30T10:42:34+09:00', '【初期対応】【API連携・EDI障害】配送連携ステータス停滞への対応', '運用部の運用 一郎が本事象に対して初期対応を行いました。配送連携のステータスが出荷済みで停滞している問題について、まずは関連する設定の確認を行い、ステータスマッピング表の更新状況を調査いたしました。その結果、確かにマッピング表の更新漏れが確認されました。今後、迅速な修正策を講じるための具体的なアクションプランを策定します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00086', 'INC-2025-00060', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-30T11:12:34+09:00', TIMESTAMP WITH TIME ZONE '2025-05-30T12:12:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00064', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-10-03T00:19:28+09:00', TIMESTAMP WITH TIME ZONE '2025-10-03T00:49:28+09:00', '【障害報告】【在庫マスター設定障害】バーコード照合エラー', '2025年10月3日00時19分28秒に、架空服飾店Aにて発生した在庫登録失敗の報告です。発生した症状は、バーコードスキャン後に照合エラーが発生し、登録が不可となる事象です。発見者は運用部の運用 一郎で、影響範囲は単一店舗のみです。発生契機は新規店舗追加の初日であり、影響を受けたコンポーネントはMercury AWS AP（DRサイト）およびPOS連携アダプタです。技術的な詳細として、チェックディジット検証ロジックの誤設定が疑われています。この問題は、在庫マスター設定の不具合によるもので、即時の対応が求められます。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00064', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00064', 'INC-2025-00064', '運用部の運用 一郎が、架空服飾店Aにおけるバーコード照合エラーの原因調査を実施しました。初日の新規店舗追加時に発生したこの問題は、POS連携アダプタとMercury AWS APに関与しており、チェックディジット検証ロジックが誤設定されている可能性があります。これにより、バーコードスキャン後に照合が行われず、登録が拒否されてしまいます。早急に対応策を講じる必要があります。', '運用部の運用 一郎が、架空服飾店Aにおけるバーコード照合エラーの原因調査を実施しました。初日の新規店舗追加時に発生したこの問題は、POS連携アダプタとMercury AWS APに関与しており、チェックディジット検証ロジックが誤設定されている可能性があります。これにより、バーコードスキャン後に照合が行われず、登録が拒否されてしまいます。早急に対応策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-10-04T00:49:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00090', 'INC-2025-00064', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-10-03T01:04:28+09:00', TIMESTAMP WITH TIME ZONE '2025-10-03T02:04:28+09:00', '【初動対応】【在庫マスター設定障害】バーコード照合エラーの初動対応', '運用部の運用 一郎が、架空服飾店Aで発生したバーコード照合エラーに関する初動対応を開始しました。まず、問題が発生した時刻を確認し、影響を受けたPOS連携アダプタとMercury AWS APの状態を調査しました。運用部のメンバーが集まり、チェックディジット検証ロジックの設定をレビューし、誤設定がないかを確認しています。問題解決に向けて迅速に対応していきます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00066', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-11-19T05:08:17+09:00', TIMESTAMP WITH TIME ZONE '2025-11-19T06:08:17+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2025年11月19日05時08分17秒、株式会社ストッククラウドの顧客である架空食品店Aにおいて、顧客固定IP変更が許可リストに未反映の障害が発生しました。この障害により、架空食品店Aの顧客拠点NW（Secondary）および顧客側FWに接続できない状況となり、業務に影響を及ぼしています。発見者は営業部の花子であり、障害は顧客オンボーディング当日に発生しました。発見から41分後の05時49分17秒に検知されました。エラーコードは NW-07-00066 です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00066', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00066', 'INC-2025-00066', '調査の結果、障害の原因は顧客固定IPの変更が許可リストに未反映であることが判明しました。この件は、顧客のオンボーディング当日に発生し、IP許可リストの更新漏れが推定されています。今後、IP許可リストの管理を徹底し、同様の事象が発生しないよう対策を講じます。', '調査の結果、障害の原因は顧客固定IPの変更が許可リストに未反映であることが判明しました。この件は、顧客のオンボーディング当日に発生し、IP許可リストの更新漏れが推定されています。今後、IP許可リストの管理を徹底し、同様の事象が発生しないよう対策を講じます。', TIMESTAMP WITH TIME ZONE '2025-11-20T06:08:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00093', 'INC-2025-00066', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-11-19T06:23:17+09:00', TIMESTAMP WITH TIME ZONE '2025-11-19T07:23:17+09:00', '【初動対応】固定IP変更未連絡', '営業部の花子からの報告を受け、迅速に顧客固定IPの変更状況を確認しました。すぐに許可リストの更新を試みると、確かに最新の固定IPが未反映であることが確認されました。再度、顧客へ連絡を取り、情報を共有し、影響を最小限に抑えるよう対応を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00069', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-12-08T12:23:07+09:00', TIMESTAMP WITH TIME ZONE '2025-12-08T14:23:07+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2025年12月8日、株式会社ストッククラウドが提供するVenusにおいて、架空服飾店Aの顧客店舗POSでOAuthトークン失効が発生し、POS連携が中断しました。発見者は営業部の花子であり、検知は2025年12月8日の14:44に行われました。この事象は年末年始の稼働切替時に発生し、影響範囲は単一店舗に限定されています。原因としてリフレッシュトークン保存先の障害が疑われています。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00069', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00069', 'INC-2025-00069', 'OAuthトークンの失効に関する調査を実施した結果、年末年始の稼働切替時において、リフレッシュトークン保存先に障害が発生した可能性が高いことが判明しました。この影響により、顧客店舗POSとの連携が中断し、正常な運用が妨げられました。今後の対策が必要です。', 'OAuthトークンの失効に関する調査を実施した結果、年末年始の稼働切替時において、リフレッシュトークン保存先に障害が発生した可能性が高いことが判明しました。この影響により、顧客店舗POSとの連携が中断し、正常な運用が妨げられました。今後の対策が必要です。', TIMESTAMP WITH TIME ZONE '2025-12-09T14:23:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00098', 'INC-2025-00069', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-12-08T14:38:07+09:00', TIMESTAMP WITH TIME ZONE '2025-12-08T15:38:07+09:00', '【初動対応】【CLU-07】OAuthトークン失効', '初動対応として、営業部の花子が架空服飾店Aに連絡を取り、障害の詳細を確認しました。POS連携が中断している旨を説明し、顧客に対して適切な対応策を講じることを約束いたしました。また、技術チームに対しても速やかに調査を依頼しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00099', 'INC-2025-00069', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-12-08T16:08:07+09:00', TIMESTAMP WITH TIME ZONE '2025-12-08T17:08:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00073', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-09-30T12:29:49+09:00', TIMESTAMP WITH TIME ZONE '2025-09-30T12:44:49+09:00', '【障害報告】【運用操作・権限障害】夜間バッチ手動停止', '2025年9月30日12時29分49秒に、株式会社ストッククラウドの運用コンソールにおいて、架空食品店Bの夜間バッチを手動停止した後、再起動を忘れてしまうという運用者の作業ミスによるアクセス障害が発生しました。発見者は運用部の運用 一郎です。影響範囲はバッチ処理のみで、オンラインには影響がありませんでした。この問題は、年末年始の稼働切替時に発生したため、運用手順書における再起動ステップの省略が推定原因として考えられます。エラーコードはOPS-10-00073です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00073', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00073', 'INC-2025-00073', '運用 一郎が実施した調査によれば、夜間バッチの手動停止後に再起動を行わなかったことが原因とされます。運用手順書の内容を確認したところ、再起動に関するステップが省略されていたことが明らかになりました。このため、運用部では手順書の見直しを行い、今後の運用において同様の問題が発生しないよう、注意喚起を行う予定です。', '運用 一郎が実施した調査によれば、夜間バッチの手動停止後に再起動を行わなかったことが原因とされます。運用手順書の内容を確認したところ、再起動に関するステップが省略されていたことが明らかになりました。このため、運用部では手順書の見直しを行い、今後の運用において同様の問題が発生しないよう、注意喚起を行う予定です。', TIMESTAMP WITH TIME ZONE '2025-10-01T12:44:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00105', 'INC-2025-00073', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-09-30T12:59:49+09:00', TIMESTAMP WITH TIME ZONE '2025-09-30T13:59:49+09:00', '【対応ログ】【運用操作・権限障害】夜間バッチ手動停止', '運用 一郎が12時41分49秒に障害を検知し、その後すぐに運用部内での情報共有を開始しました。夜間バッチの手動停止による影響を確認し、運用手順書の内容を精査。再起動を忘れた理由を特定したため、手順書の改定を指示しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00106', 'INC-2025-00073', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-09-30T14:29:49+09:00', TIMESTAMP WITH TIME ZONE '2025-09-30T15:29:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00074', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-01-07T10:29:50+09:00', TIMESTAMP WITH TIME ZONE '2025-01-07T12:29:50+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2025年1月7日10時29分50秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSにおける棚卸突合が失敗しました。この障害は、大規模セール開始直前に発生し、分散トランザクションがタイムアウトして片側のみコミットされる事象が確認されました。発見者は営業部の花子であり、検知は11時39分50秒で、検知までの時間は70分でした。エラーコードはSYNC-04-00074であり、影響範囲は全テナントに波及する可能性があります。推定される原因は、2PCタイムアウト設定が過短であったことです。今後の対策としては、タイムアウト設定の見直しと障害の再発防止策が求められます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00074', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00074', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00074', 'INC-2025-00074', '調査の結果、大規模セール開始直前に発生した分散トランザクションがタイムアウトしたことにより、片側のみコミットされるという問題が確認されました。主な原因は、2PCタイムアウト設定が不適切であったためと考えられます。この設定を見直すことが必要です。また、在庫計算エンジンにも影響が及ぶ可能性があるため、全体的なシステムの健全性を確認する必要があります。', '調査の結果、大規模セール開始直前に発生した分散トランザクションがタイムアウトしたことにより、片側のみコミットされるという問題が確認されました。主な原因は、2PCタイムアウト設定が不適切であったためと考えられます。この設定を見直すことが必要です。また、在庫計算エンジンにも影響が及ぶ可能性があるため、全体的なシステムの健全性を確認する必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-08T12:29:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00107', 'INC-2025-00074', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-07T12:44:50+09:00', TIMESTAMP WITH TIME ZONE '2025-01-07T13:44:50+09:00', '【初期対応】【データ同期・整合性障害】分散トランザクションタイムアウト', 'インシデント発生の報告を受け、直ちに調査チームを立ち上げました。初期調査では、顧客店舗POSにおける分散トランザクションがタイムアウトした事象が確認され、2PCタイムアウト設定の見直しを検討する必要があることが示唆されました。顧客には現在の状況を説明し、影響を受ける可能性があることを通知しました。また、必要に応じてシステムの再起動や設定変更を行う準備を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00075', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-09-16T00:54:21+09:00', TIMESTAMP WITH TIME ZONE '2025-09-16T01:54:21+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2025年9月16日00:54に、架空服飾店Aの顧客拠点NWにおいて、ISP側のBGP経路障害が発生し、複数拠点が同時不通となりました。影響範囲は同一顧客の全店舗に及び、インフラメンテナンス明けでの障害ということで、早急な対応が求められます。営業部の花子がこの状況を発見し、01:37に検知するまでの43分間、顧客には影響が続きました。エラーコードはNW-06-00075であり、技術的にはISP側のBGP経路障害が原因と考えられます。今後の対策が重要です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00075', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00075', 'INC-2025-00075', '調査の結果、インフラメンテナンス明けに発生したISP側のBGP経路障害が確認されました。この障害により、架空服飾店Aの全店舗に影響が出ており、複数拠点が同時に不通となったことが明らかになりました。今後、ISPとの連携を強化し、再発防止に努める必要があります。', '調査の結果、インフラメンテナンス明けに発生したISP側のBGP経路障害が確認されました。この障害により、架空服飾店Aの全店舗に影響が出ており、複数拠点が同時に不通となったことが明らかになりました。今後、ISPとの連携を強化し、再発防止に努める必要があります。', TIMESTAMP WITH TIME ZONE '2025-09-17T01:54:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00108', 'INC-2025-00075', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-16T02:09:21+09:00', TIMESTAMP WITH TIME ZONE '2025-09-16T03:09:21+09:00', '【対応報告】【顧客ネットワーク障害】初期対応', 'インシデント発生後、営業の花子が迅速に状況を確認し、ISPに連絡しました。ISP側からは、BGP経路障害の影響を受けていることが確認され、復旧作業が進められる旨の回答を受けました。顧客には状況を随時報告し、影響を最小限に抑えるための対応を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00109', 'INC-2025-00075', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-16T03:39:21+09:00', TIMESTAMP WITH TIME ZONE '2025-09-16T04:39:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00077', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-12-29T02:36:06+09:00', TIMESTAMP WITH TIME ZONE '2025-12-29T03:21:06+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2025年12月29日02時36分に株式会社ストッククラウドのMercuryサービスでストレージ溢れによる問題が発生しました。発生箇所はMercury AWS Storageであり、当該問題により運用部門へのPagerDuty連携が失敗し、オンコール通知未達の状態が続きました。発見者は運用部の運用 一郎です。影響コンポーネントはMercury AWS Storage（ゾーンB）で、年末年始の稼働切替時に発生したことが確認されています。エラーコードはMON-07-00077です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00077', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00077', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00077', 'INC-2025-00077', '問題発生後、運用部は速やかに調査を開始しました。PagerDuty連携の失敗は連携APIキーの権限不足が原因であると推定されました。また、年末年始の稼働切替時に特にこの問題が顕著になったことが確認されました。この問題が運用部門に限定されていることから、影響範囲は最小限であると考えられます。今後の対策として、APIキーの権限を見直すことが重要です。', '問題発生後、運用部は速やかに調査を開始しました。PagerDuty連携の失敗は連携APIキーの権限不足が原因であると推定されました。また、年末年始の稼働切替時に特にこの問題が顕著になったことが確認されました。この問題が運用部門に限定されていることから、影響範囲は最小限であると考えられます。今後の対策として、APIキーの権限を見直すことが重要です。', TIMESTAMP WITH TIME ZONE '2025-12-30T03:21:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00111', 'INC-2025-00077', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-29T03:36:06+09:00', TIMESTAMP WITH TIME ZONE '2025-12-29T04:36:06+09:00', '初動対応', '運用部は本障害発生の確認後、直ちに関係者に通知を行い、再発防止策を検討しました。具体的には、PagerDutyとの連携設定を見直し、APIキーの権限を適切に設定する方針を決定しました。また、年末年始の稼働切替時における監視体制の強化も検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00112', 'INC-2025-00077', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-29T05:06:06+09:00', TIMESTAMP WITH TIME ZONE '2025-12-29T06:06:06+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00078', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-03-29T19:11:52+09:00', TIMESTAMP WITH TIME ZONE '2025-03-29T19:41:52+09:00', '【障害報告】【性能・負荷障害】オートスケール遅延', '2025年3月29日19時11分52秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aの利用者に対する応答が遅延する事象が発生しました。この事象は、全テナントに影響を及ぼし、オートスケールが間に合わず応答劣化が見られました。発生の契機は大規模セール開始直前であり、スケールアウト閾値の設定遅延が推定される原因です。この障害によって、Venus Azure APの主システムがパフォーマンス低下に直面し、顧客からのクレームが増加しました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00078', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00078', 'INC-2025-00078', '今回の応答遅延の調査では、オートスケール機能が正常に動作しなかった原因として、スケールアウト閾値の設定遅延が考えられます。この設定遅延により、負荷が急激に増加した際に適切なリソースが割り当てられず、応答の劣化が発生しました。今後は、設定の見直しとオートスケール機能の強化が必要です。', '今回の応答遅延の調査では、オートスケール機能が正常に動作しなかった原因として、スケールアウト閾値の設定遅延が考えられます。この設定遅延により、負荷が急激に増加した際に適切なリソースが割り当てられず、応答の劣化が発生しました。今後は、設定の見直しとオートスケール機能の強化が必要です。', TIMESTAMP WITH TIME ZONE '2025-03-30T19:41:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00113', 'INC-2025-00078', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-29T19:56:52+09:00', TIMESTAMP WITH TIME ZONE '2025-03-29T20:56:52+09:00', '【初期対応】【性能・負荷障害】オートスケール遅延への初期対応', '事象発生後、運用部の運用一郎が迅速に対応を開始しました。まず、Venus Azure APの監視ログを確認し、スケールアウト閾値の設定が適切であるかを検証しました。確認の結果、設定に遅延が生じていることが判明し、即座に修正作業を実施しました。その後、再発防止策として、オートスケール機能の監視を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00114', 'INC-2025-00078', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-29T21:26:52+09:00', TIMESTAMP WITH TIME ZONE '2025-03-29T22:26:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00080', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-11-27T06:52:24+09:00', TIMESTAMP WITH TIME ZONE '2025-11-27T07:07:24+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2025年11月27日06時52分24秒に、株式会社ストッククラウドのサービスVenusにおいて、運用者の作業ミスによるアクセス障害が発生しました。影響を受けたのは架空服飾店Aで、運用コンソールにおいて埋込画面が認証不可の状態となりました。この障害は、定例リリース直後に発生し、CookieのSameSite設定に問題があったと考えられています。顧客には影響が及び、運用部の運用 一郎が発見したため、即座に対応を開始しました。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00080', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00080', 'INC-2025-00080', '運用部の運用 一郎が確認したところ、定例リリース直後にCookieのSameSite設定が変更されたことが確認されました。この設定変更により、埋込画面が認証不可となり、根本的な原因はSameSite属性の変更にあると考えられます。影響は架空服飾店Aのみに限られ、運用コンソールとセッションストアに関連する問題であることがわかりました。', '運用部の運用 一郎が確認したところ、定例リリース直後にCookieのSameSite設定が変更されたことが確認されました。この設定変更により、埋込画面が認証不可となり、根本的な原因はSameSite属性の変更にあると考えられます。影響は架空服飾店Aのみに限られ、運用コンソールとセッションストアに関連する問題であることがわかりました。', TIMESTAMP WITH TIME ZONE '2025-11-28T07:07:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00117', 'INC-2025-00080', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-11-27T07:22:24+09:00', TIMESTAMP WITH TIME ZONE '2025-11-27T08:22:24+09:00', '【初期対応】Cookie SameSite拒否の修正作業', '運用部の運用 一郎が状況を確認し、CookieのSameSite設定を元に戻す作業を開始しました。影響範囲は単一店舗であり、迅速に対応を行うことが求められました。設定を元に戻した後、埋込画面が正常に認証できるかどうかテストを実施し、結果を踏まえた上で追加の対応が必要かを判断する予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00083', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-05-09T07:13:51+09:00', TIMESTAMP WITH TIME ZONE '2025-05-09T07:43:51+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2025年5月9日07:13:51に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aに影響を及ぼす応答遅延が発生しました。症状としては、ヘルスチェック過多によるAPサーバーの負荷増加が確認されました。この状況は、インフラメンテナンス明けに発生しており、全テナントに波及しています。エラーコードはMON-06-00083で、影響を受けているコンポーネントはVenus Azure APおよびロードバランサです。現在、LBのヘルスチェック間隔の過短設定が推定原因と考えられています。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00083', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00083', 'INC-2025-00083', 'インフラメンテナンスの後、ヘルスチェックが過剰に行われた結果、APサーバーに過負荷がかかり、応答遅延が発生しました。運用部の運用 一郎がこの問題を初めて検知したのは、2025年5月9日07:41:51で、検知までに28分かかりました。現在、LBヘルスチェックの設定を見直し、過負荷の原因を特定するための調査を進めています。', 'インフラメンテナンスの後、ヘルスチェックが過剰に行われた結果、APサーバーに過負荷がかかり、応答遅延が発生しました。運用部の運用 一郎がこの問題を初めて検知したのは、2025年5月9日07:41:51で、検知までに28分かかりました。現在、LBヘルスチェックの設定を見直し、過負荷の原因を特定するための調査を進めています。', TIMESTAMP WITH TIME ZONE '2025-05-10T07:43:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00121', 'INC-2025-00083', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-09T07:58:51+09:00', TIMESTAMP WITH TIME ZONE '2025-05-09T08:58:51+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎より、問題の初期対応が行われました。本件に関して、LBヘルスチェックの設定を再確認し、適切な間隔に調整する措置を取ります。また、全テナントへの影響を最小限に抑えるため、APサーバーのリソースも増強する方向で検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00122', 'INC-2025-00083', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-09T09:28:51+09:00', TIMESTAMP WITH TIME ZONE '2025-05-09T10:28:51+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00091', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-11-04T12:49:52+09:00', TIMESTAMP WITH TIME ZONE '2025-11-04T14:49:52+09:00', '【障害報告】【API連携・EDI障害】バルクAPI部分失敗', '2025年11月4日12時49分52秒に、株式会社ストッククラウドのサービスVenusにおいて、バルクAPIが部分失敗しロールバック未完了の事象が発生しました。発見者は営業部の花子であり、顧客店舗POSにてこの障害が発見されました。この障害はデータ移行バッチ実行中に発生し、部分成功時の補償トランザクション欠如が推定されます。影響範囲はサービス全体の一部機能であり、在庫登録APIにも影響が及んでいます。検知は発生から120分後の14時49分52秒に行われました。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00091', 'INC-2025-00091', '調査の結果、バルクAPIの部分失敗が確認されました。この失敗は、ロールバックが正常に完了しなかったことによるもので、原因として部分成功時の補償トランザクションの欠如が挙げられます。特に、顧客店舗POS（ゾーンB）における在庫登録APIとの連携が不完全であったため、データの整合性に影響が出ました。今後の対応策として、補償トランザクションの実装を強化し、同様の問題を防ぐための対策が必要です。', '調査の結果、バルクAPIの部分失敗が確認されました。この失敗は、ロールバックが正常に完了しなかったことによるもので、原因として部分成功時の補償トランザクションの欠如が挙げられます。特に、顧客店舗POS（ゾーンB）における在庫登録APIとの連携が不完全であったため、データの整合性に影響が出ました。今後の対応策として、補償トランザクションの実装を強化し、同様の問題を防ぐための対策が必要です。', TIMESTAMP WITH TIME ZONE '2025-11-05T14:49:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00133', 'INC-2025-00091', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-11-04T15:04:52+09:00', TIMESTAMP WITH TIME ZONE '2025-11-04T16:04:52+09:00', '初期対応', '発生直後にチームが緊急対応を開始し、影響を受けた顧客店舗POSの状況を確認しました。ロールバック処理を手動で実施し、データの整合性を確保するための修正作業を行いました。また、営業部への情報共有と障害報告を行い、顧客へは状況説明を実施しました。今後の対応として、再発防止策を検討し、API連携の強化を図ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00134', 'INC-2025-00091', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-11-04T16:34:52+09:00', TIMESTAMP WITH TIME ZONE '2025-11-04T17:34:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00093', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-07-10T20:05:15+09:00', TIMESTAMP WITH TIME ZONE '2025-07-10T22:05:15+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2025年07月10日20時05分15秒、株式会社ストッククラウドの顧客、架空食品店Bにおいて棚卸突合が失敗しました。この事象は顧客店舗POSで発生し、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしました。影響範囲は単一店舗のみで、発見者は営業部の花子です。発生から検知まで73分を要し、21時18分15秒に問題が確認されました。エラーコードはEDI-07-00093です。推定原因として文字コード変換テーブルの誤選択が疑われます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00093', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00093', 'INC-2025-00093', '調査を開始しました。データ移行バッチ実行中に発生したShift_JIS変換による文字化けの原因を特定するため、ログと設定を確認しています。エラーは顧客店舗POSおよびEDIアダプタに影響を及ぼしました。現在、文字コード変換テーブルの設定を見直し、正しいテーブルが選択されているか確認中です。', '調査を開始しました。データ移行バッチ実行中に発生したShift_JIS変換による文字化けの原因を特定するため、ログと設定を確認しています。エラーは顧客店舗POSおよびEDIアダプタに影響を及ぼしました。現在、文字コード変換テーブルの設定を見直し、正しいテーブルが選択されているか確認中です。', TIMESTAMP WITH TIME ZONE '2025-07-11T22:05:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00137', 'INC-2025-00093', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-07-10T22:20:15+09:00', TIMESTAMP WITH TIME ZONE '2025-07-10T23:20:15+09:00', '【初動対応】【API連携・EDI障害】文字コード変換事故への初動対応', '初動対応として、影響を受けた顧客店舗POSの状態を確認しました。Shift_JIS変換による文字化けが発生しているため、バッチ処理を一時停止し、正しい文字コード変換テーブルを選定し直す準備を進めています。顧客には状況を説明し、影響を最小限に抑えるための対応策を講じることを約束しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00107', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-06-28T12:44:53+09:00', TIMESTAMP WITH TIME ZONE '2025-06-28T14:44:53+09:00', '【障害報告】【棚卸・POS突合障害】月次突合不一致', '2025年6月28日12時44分53秒に、株式会社ストッククラウドが提供するVenusサービスにおいて、顧客「架空服飾店A」にて棚卸突合失敗が発生しました。月次突合レポートの合計が帳票と不一致となり、影響範囲は同一顧客の全店舗に及びました。障害は月末棚卸の開始時に発生し、検知は2025年6月28日14時41分53秒に行われました。推定原因として、返品データの符号反転漏れが考えられます。現在、顧客店舗POSおよび月次集計ジョブの確認を進めております。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00107', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00107', 'INC-2025-00107', '月末棚卸の開始時に発生した月次突合不一致の原因を調査したところ、返品データの符号反転漏れが疑われます。これにより、月次突合レポートの合計が帳票と不一致となり、全店舗に影響を及ぼしました。詳細なデータ分析を進めており、適切な対策を講じる必要があります。', '月末棚卸の開始時に発生した月次突合不一致の原因を調査したところ、返品データの符号反転漏れが疑われます。これにより、月次突合レポートの合計が帳票と不一致となり、全店舗に影響を及ぼしました。詳細なデータ分析を進めており、適切な対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-06-29T14:44:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00156', 'INC-2025-00107', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-06-28T14:59:53+09:00', TIMESTAMP WITH TIME ZONE '2025-06-28T15:59:53+09:00', '【初期対応】【棚卸・POS突合障害】月次突合不一致', '初期対応として、全店舗の月次突合レポートと帳票の整合性を確認する作業を開始しました。また、返品データの確認を行い、符号の反転漏れが発生しているかどうかを調査しています。関係者には情報共有を行い、影響を最小限に抑える対策を検討しております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00115', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-03-16T10:38:14+09:00', TIMESTAMP WITH TIME ZONE '2025-03-16T11:08:14+09:00', '【障害報告】【CLU-07】文字コード変換事故', '2025年3月16日10時38分14秒、株式会社ストッククラウドのMercuryにおいてマスター設定ミスによる在庫登録失敗が発生。影響範囲は単一店舗に限られ、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けする事象が確認された。エラーコードはEDI-07-00115。11時24分14秒に運用部の運用 一郎がこの事象を検知し、発見に至るまでに46分を要した。推定原因は文字コード変換テーブルの誤選択と考えられる。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00115', 'INC-2025-00115', '本インシデントの調査において、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けする現象が発生したことが確認された。原因として文字コード変換テーブルの誤選択が疑われる。影響はMercury AWS APのEDIアダプタに限定されており、他のコンポーネントには影響が及んでいない。今後、バッチ処理の見直しおよびテーブル選択の確認を強化する予定である。', '本インシデントの調査において、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けする現象が発生したことが確認された。原因として文字コード変換テーブルの誤選択が疑われる。影響はMercury AWS APのEDIアダプタに限定されており、他のコンポーネントには影響が及んでいない。今後、バッチ処理の見直しおよびテーブル選択の確認を強化する予定である。', TIMESTAMP WITH TIME ZONE '2025-03-17T11:08:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00167', 'INC-2025-00115', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-16T11:23:14+09:00', TIMESTAMP WITH TIME ZONE '2025-03-16T12:23:14+09:00', '【初期対応】【CLU-07】文字コード変換事故', '運用部の運用 一郎は、発見後直ちに該当するデータ移行バッチの停止を指示し、影響を受けたデータの確認を始めた。Shift_JIS変換で文字化けが発生している商品名を抽出し、必要に応じて修正を行う体制を整えた。また、文字コード変換テーブルの設定を見直し、再発防止策としてテスト環境での再確認を実施することを決定した。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00116', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-09-27T08:34:52+09:00', TIMESTAMP WITH TIME ZONE '2025-09-27T09:34:52+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2025年9月27日8時34分52秒、株式会社ストッククラウドのサービスMercuryにおいて、顧客「架空食品店B」の拠点ネットワークにおいて障害が発生しました。顧客の全店舗に影響を及ぼし、DNS解決は成功したものの、TLS握手での接続が切断される事象が確認されました。発生契機はインフラメンテナンス明けであり、プロキシ証明書の期限切れが推定される原因です。監視システムによる検知は2025年9月27日9時40分52秒に行われ、66分後の発見となりました。影響範囲は同一顧客の全店舗に及び、顧客拠点NWのTLS終端が影響を受けました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00116', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00116', 'INC-2025-00116', 'インフラメンテナンス明けにおいて、顧客の拠点ネットワークでTLS握手の切断が確認されました。原因として、プロキシ証明書の期限切れが考えられます。技術的には、DNS解決が成功したにもかかわらずTLS握手で切断されるという事象が再現され、CL環境では同様の問題が発生していることが確認されました。証明書の状態を確認し、期限が切れていることを特定しました。', 'インフラメンテナンス明けにおいて、顧客の拠点ネットワークでTLS握手の切断が確認されました。原因として、プロキシ証明書の期限切れが考えられます。技術的には、DNS解決が成功したにもかかわらずTLS握手で切断されるという事象が再現され、CL環境では同様の問題が発生していることが確認されました。証明書の状態を確認し、期限が切れていることを特定しました。', TIMESTAMP WITH TIME ZONE '2025-09-28T09:34:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00168', 'INC-2025-00116', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-27T09:49:52+09:00', TIMESTAMP WITH TIME ZONE '2025-09-27T10:49:52+09:00', '【初動対応】【顧客ネットワーク障害】TLS握手切断', '障害の初動対応として、顧客「架空食品店B」に連絡を取り、状況を報告しました。システム管理者が直接、顧客の拠点ネットワークにアクセスし、TLSの設定を確認しました。プロキシ証明書の状態をチェックした結果、期限切れであることが確認されました。直ちに新しい証明書を発行し、適用を行ったところ、TLS握手の問題が解決されました。その後、顧客に対しても問題が解消された旨を伝え、モニタリングを続けています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00169', 'INC-2025-00116', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-27T11:19:52+09:00', TIMESTAMP WITH TIME ZONE '2025-09-27T12:19:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00138', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-11-03T05:54:36+09:00', TIMESTAMP WITH TIME ZONE '2025-11-03T07:54:36+09:00', '【障害報告】【データ同期・整合性障害】マスター在庫二重反映', '2025年11月3日5時54分36秒、株式会社ストッククラウドの顧客である架空服飾店Aにて、棚卸突合失敗の事象が発生しました。この事象は、顧客店舗POSにおいて、マスター更新と在庫が二重反映されるという症状を伴いました。定例リリース直後に発生し、全店舗に影響を及ぼしています。検知は2025年11月3日8時35分36秒であり、161分後に確認されました。エラーコードはSYNC-01-00138です。症状の推定原因として、イベント順序の逆転配信が考えられており、今後の対応が必要です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00138', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00138', 'INC-2025-00138', '今回の二重反映事象について調査を開始しました。技術的な詳細としては、定例リリース直後に発生しており、イベントバスの配信順序が逆転した可能性があります。この影響により、在庫情報が正しく更新されていないことが確認され、顧客店舗POSでのデータ同期に問題が生じています。今後の調査では、イベント順序についてさらに詳細な確認が必要です。', '今回の二重反映事象について調査を開始しました。技術的な詳細としては、定例リリース直後に発生しており、イベントバスの配信順序が逆転した可能性があります。この影響により、在庫情報が正しく更新されていないことが確認され、顧客店舗POSでのデータ同期に問題が生じています。今後の調査では、イベント順序についてさらに詳細な確認が必要です。', TIMESTAMP WITH TIME ZONE '2025-11-04T07:54:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00201', 'INC-2025-00138', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-11-03T08:09:36+09:00', TIMESTAMP WITH TIME ZONE '2025-11-03T09:09:36+09:00', '【初期対応】【データ同期・整合性障害】マスター在庫二重反映', '初期対応として、該当する全店舗のデータを確認し、二重反映の影響を受けた在庫情報の修正を行いました。また、イベントバスの配信順序に関するログを収集し、問題発生の原因特定に向けた検証を開始しています。顧客である架空服飾店Aに対しては、状況説明と今後の対応について通知を行い、必要に応じてフォローアップする予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00139', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-05-02T05:38:51+09:00', TIMESTAMP WITH TIME ZONE '2025-05-02T06:08:51+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2025年5月2日05時38分51秒に、株式会社ストッククラウドが提供するサービスMercuryにおいて、OAuthトークン失効によるPOS連携が中断する事象が発生しました。影響を受けた顧客は架空食品店Bであり、発見者は運用部の運用 一郎です。この障害は、年末年始の稼働切替時に発生し、リフレッシュトークン保存先の障害が原因と推定されます。検知まで36分を要しましたが、この間、POS連携が正常に機能せず業務に支障が生じました。今後の対応として、リフレッシュトークン保存先のチェックと改善を進める必要があります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00139', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00139', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00139', 'INC-2025-00139', '調査の結果、2025年5月2日05時38分51秒に発生したOAuthトークン失効によるPOS連携中断の原因は、リフレッシュトークンの保存先に障害があったためであると確認されました。顧客の架空食品店Bにおいて、トークン失効が発生し、業務に深刻な影響が及びました。特に年末年始の稼働切替時にこの問題が顕在化したことから、今後はより注意深い運用が求められます。', '調査の結果、2025年5月2日05時38分51秒に発生したOAuthトークン失効によるPOS連携中断の原因は、リフレッシュトークンの保存先に障害があったためであると確認されました。顧客の架空食品店Bにおいて、トークン失効が発生し、業務に深刻な影響が及びました。特に年末年始の稼働切替時にこの問題が顕在化したことから、今後はより注意深い運用が求められます。', TIMESTAMP WITH TIME ZONE '2025-05-03T06:08:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00202', 'INC-2025-00139', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-02T06:23:51+09:00', TIMESTAMP WITH TIME ZONE '2025-05-02T07:23:51+09:00', '【初期対応】【CLU-07】OAuthトークン失効', '初期対応として、2025年5月2日06時14分51秒に運用 一郎がトークン失効を検知し、直ちにPOS連携の再設定を実施しました。リフレッシュトークン保存先の確認も行い、必要な場合は改善措置を講じる準備を進めています。今後、類似の事象が発生しないよう、運用手順の見直しを検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00203', 'INC-2025-00139', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-02T07:53:51+09:00', TIMESTAMP WITH TIME ZONE '2025-05-02T08:53:51+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00140', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-11-11T21:53:53+09:00', TIMESTAMP WITH TIME ZONE '2025-11-11T22:23:53+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2025年11月11日21時53分53秒に、株式会社ストッククラウドのVenusにて、架空服飾店Aの顧客に影響が出る事象が発生しました。症状として、パートナーAPIが429を返し連携が停止しました。推定原因としては、呼出頻度の事前調整不足が考えられます。この事象は大規模セール開始直前に発生したため、影響範囲はサービス全体の一部機能に及びました。技術的には、Mercury AWS APおよびAPIゲートウェイにおいて、連携が停止したため、業務に重大な支障をきたしました。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00140', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00140', 'INC-2025-00140', '発生後30分の2025年11月11日22時23分53秒にこの問題が検知されました。関係者が集まり、パートナーAPIが429を返した理由について調査を行いました。まず、呼出頻度の事前調整不足が原因であることが確認され、今後の大規模セールに向けて調整を行う必要があると判断されました。', '発生後30分の2025年11月11日22時23分53秒にこの問題が検知されました。関係者が集まり、パートナーAPIが429を返した理由について調査を行いました。まず、呼出頻度の事前調整不足が原因であることが確認され、今後の大規模セールに向けて調整を行う必要があると判断されました。', TIMESTAMP WITH TIME ZONE '2025-11-12T22:23:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00204', 'INC-2025-00140', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-11-11T22:38:53+09:00', TIMESTAMP WITH TIME ZONE '2025-11-11T23:38:53+09:00', '【初期対応】【API連携・EDI障害】レート超過429の初期対応', '運用部の運用 一郎が初期対応に当たりました。まず、状況を確認し、パートナーAPIからの429エラーの理由を特定するための調査を開始しました。その後、影響を受けている顧客である架空服飾店Aに対して、連携停止の通知を行い、問題解決に向けた調整を進める旨を伝えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00205', 'INC-2025-00140', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-11-12T00:08:53+09:00', TIMESTAMP WITH TIME ZONE '2025-11-12T01:08:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00160', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-01-05T05:32:54+09:00', TIMESTAMP WITH TIME ZONE '2025-01-05T06:02:54+09:00', '【障害報告】【CLU-07】EDI在庫差分遅延', '2025年1月5日05時32分54秒に株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Aに関連するEDI在庫差分ファイルの反映が2時間遅延する事象が発生しました。発生契機はデータ移行バッチの実行中で、影響範囲は同一顧客の全店舗に及びます。エラーコードはEDI-01-00160であり、今回の障害はMercury AWS APおよびEDIアダプタに影響を与えました。推定原因としてはEDIキューの優先度設定誤りが考えられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00160', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00160', 'INC-2025-00160', '障害発生後の調査により、データ移行バッチ実行中にEDI在庫差分ファイルの反映が2時間遅延したことが確認されました。原因としてEDIキューの優先度設定誤りが疑われます。現在、優先度設定の見直しを進めており、再発防止策を講じる必要があります。', '障害発生後の調査により、データ移行バッチ実行中にEDI在庫差分ファイルの反映が2時間遅延したことが確認されました。原因としてEDIキューの優先度設定誤りが疑われます。現在、優先度設定の見直しを進めており、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-06T06:02:54+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00233', 'INC-2025-00160', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-05T06:17:54+09:00', TIMESTAMP WITH TIME ZONE '2025-01-05T07:17:54+09:00', '【初動対応】【CLU-07】EDI在庫差分遅延の初動対応', '初動対応として、運用部の運用 一郎が即座に状況を把握し、関係者への連絡を行いました。また、影響を受ける全店舗に対して事象の周知を徹底し、顧客への影響を最小限に抑えるための対応を進めております。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00234', 'INC-2025-00160', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-05T07:47:54+09:00', TIMESTAMP WITH TIME ZONE '2025-01-05T08:47:54+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00177', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-01-12T20:00:07+09:00', TIMESTAMP WITH TIME ZONE '2025-01-12T21:00:07+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2025年1月12日20時00分頃、株式会社ストッククラウドの顧客である架空服飾店Aにおいて、顧客固定IP変更が許可リストに未反映のため、顧客側ネットワーク障害が発生しました。この障害は営業部の花子が発見し、20時50分に検知されました。影響を受けたのは単一店舗のみで、顧客拠点NW（Secondary）および顧客側FWが影響を受けています。発生の契機は顧客オンボーディング当日であり、IP許可リストの更新漏れが推定されます。このため、顧客のネットワーク接続に支障が出ており、早急な対応が求められます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00177', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00177', 'INC-2025-00177', '現在、発生した顧客ネットワーク障害について調査を行っています。障害の原因として、顧客固定IPの変更が許可リストに未反映であることが確認されました。これは明らかにIP許可リストの更新漏れが原因と考えられ、今後の対応として、許可リストの適切な管理体制の構築が必要です。この問題が再発しないよう、対策を講じる必要があります。', '現在、発生した顧客ネットワーク障害について調査を行っています。障害の原因として、顧客固定IPの変更が許可リストに未反映であることが確認されました。これは明らかにIP許可リストの更新漏れが原因と考えられ、今後の対応として、許可リストの適切な管理体制の構築が必要です。この問題が再発しないよう、対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-13T21:00:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00260', 'INC-2025-00177', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-12T21:15:07+09:00', TIMESTAMP WITH TIME ZONE '2025-01-12T22:15:07+09:00', '【対応】【顧客ネットワーク障害】固定IP変更未連絡', '初動対応として、営業部の花子が架空服飾店Aに連絡し、固定IP変更の情報を伝えるとともに、許可リストの更新を即座に実施しました。また、顧客側のネットワーク設定を確認し、必要な修正を加えました。今後は顧客オンボーディング時に固定IP変更の情報を必ず共有することを徹底し、同様の問題が発生しないよう努めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00261', 'INC-2025-00177', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-12T22:45:07+09:00', TIMESTAMP WITH TIME ZONE '2025-01-12T23:45:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00212', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-11-09T07:53:39+09:00', TIMESTAMP WITH TIME ZONE '2025-11-09T08:23:39+09:00', '【障害報告】【CLU-09】読取レプリカ遅延', '2025年11月9日07時53分39秒に、株式会社ストッククラウドのMercuryサービスにおいて、マスター設定ミスによる在庫登録失敗が発生しました。症状としては、読取レプリカ遅延により在庫照会が古い値となっており、影響を受けたのは特定リージョンのユーザーのみです。この障害は、大規模セール開始直前に発生し、08時18分39秒に検知されました。発見者は運用部の運用 一郎です。エラーコードはSYNC-02-00212で、Mercury AWS AP（ゾーンB）の読取専用レプリカに関連しています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00212', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00212', 'INC-2025-00212', 'この度の在庫登録失敗に関して、調査を実施しました。大規模セール開始直前にレプリケーション遅延の監視閾値を超過し、読取レプリカ遅延が発生したことが確認されました。この遅延により在庫照会が古い値となり、特定の顧客に影響を及ぼしました。今後は監視体制の見直しと閾値の設定を行い、このような事象を未然に防ぐ対策を講じる必要があります。', 'この度の在庫登録失敗に関して、調査を実施しました。大規模セール開始直前にレプリケーション遅延の監視閾値を超過し、読取レプリカ遅延が発生したことが確認されました。この遅延により在庫照会が古い値となり、特定の顧客に影響を及ぼしました。今後は監視体制の見直しと閾値の設定を行い、このような事象を未然に防ぐ対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-11-10T08:23:39+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00312', 'INC-2025-00212', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-11-09T08:38:39+09:00', TIMESTAMP WITH TIME ZONE '2025-11-09T09:38:39+09:00', '【対応】【CLU-09】読取レプリカ遅延への初期対応', '初期対応として、全ての関連コンポーネントの状態を確認し、特にMercury AWS AP（ゾーンB）のレプリケーション状況を監視しました。レプリカ遅延が発生していることが確認されたため、即座に再同期を実施し、在庫情報の最新化を図りました。また、影響を受けたユーザーには速やかに障害の発生を通知し、状況を説明しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00313', 'INC-2025-00212', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-11-09T10:08:39+09:00', TIMESTAMP WITH TIME ZONE '2025-11-09T11:08:39+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00219', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-04-04T11:23:35+09:00', TIMESTAMP WITH TIME ZONE '2025-04-04T13:23:35+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2025年4月4日11時23分、株式会社ストッククラウドにて、顧客店舗POSにおいてWebhook再送が嵐状になり、先方で拒否されました。この事象は、定例リリース直後に発生しました。発見者は営業部の花子です。影響範囲は単一店舗のみで、発生したエラーコードはEDI-02-00219です。推定される原因は再送間隔の指数バックオフ未設定です。このため、Webhookの再送が過剰になってしまい、先方のシステムに悪影響を及ぼしました。技術詳細としては、定例リリース後にWebhook再送が拒否される状況が続きました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00219', 'INC-2025-00219', '本問題の調査を開始しました。Webhook再送が嵐状になる原因として、再送間隔の指数バックオフが未設定であることが疑われます。これにより、Webhookが過剰に再送され、先方システムでの拒否を引き起こしています。影響を受けた顧客店舗POSの状況を確認し、再設定の必要性を検討しています。', '本問題の調査を開始しました。Webhook再送が嵐状になる原因として、再送間隔の指数バックオフが未設定であることが疑われます。これにより、Webhookが過剰に再送され、先方システムでの拒否を引き起こしています。影響を受けた顧客店舗POSの状況を確認し、再設定の必要性を検討しています。', TIMESTAMP WITH TIME ZONE '2025-04-05T13:23:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00321', 'INC-2025-00219', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-04-04T13:38:35+09:00', NULL, 'Webhook再送の初期対応', '今回のWebhook再送の問題に対して、初期対応を実施しました。まず、再送間隔の設定を確認し、指数バックオフが未設定であることを確認しました。この設定を見直し、再送頻度を適切に調整することで、再度先方で拒否されることのないようにします。また、顧客店舗POSと連携するシステムの動作状況を監視し、問題が再発しないように対策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00249', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-03-25T22:44:36+09:00', TIMESTAMP WITH TIME ZONE '2025-03-25T23:29:36+09:00', '【障害報告】【ストレージ・容量障害】バックアップ連続失敗', '2025年3月25日22時44分36秒に、株式会社ストッククラウドのMercuryサービスにおいてストレージ溢れが発生しました。該当するバックアップジョブが連続失敗しており、現時点での影響範囲はバッチ処理のみで、オンラインサービスには影響がありません。原因としては、年末年始の稼働切替時にスナップショットの蓄積が疑われます。エラーコードは「STR-03-00249」で、運用部の運用 一郎が発見者として確認しています。検知は発生から47分後の23時31分36秒に行われました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00249', 'INC-2025-00249', '本インシデントの調査を行った結果、バックアップジョブが連続して失敗している原因は、年末年始の稼働切替時に発生したスナップショットの蓄積に起因することが判明しました。これにより、Mercury AWS Storage内のバックアップ領域において容量の制約が生じ、正常なバックアップ処理が行えなくなっています。', '本インシデントの調査を行った結果、バックアップジョブが連続して失敗している原因は、年末年始の稼働切替時に発生したスナップショットの蓄積に起因することが判明しました。これにより、Mercury AWS Storage内のバックアップ領域において容量の制約が生じ、正常なバックアップ処理が行えなくなっています。', TIMESTAMP WITH TIME ZONE '2025-03-26T23:29:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00369', 'INC-2025-00249', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-25T23:44:36+09:00', TIMESTAMP WITH TIME ZONE '2025-03-26T00:44:36+09:00', '初動対応', 'インシデント発生後、直ちに運用部が対応を開始しました。まずは、影響を受けているバックアップジョブの確認を行い、スナップショットの削除を検討しました。また、容量を確保するための次善策として、古いデータのアーカイブや不要なスナップショットの整理を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00370', 'INC-2025-00249', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-26T01:14:36+09:00', TIMESTAMP WITH TIME ZONE '2025-03-26T02:14:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00252', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-04-08T04:08:21+09:00', TIMESTAMP WITH TIME ZONE '2025-04-08T04:53:21+09:00', '【障害報告】【ストレージ・容量障害】バックアップ連続失敗', '2025年4月8日04時08分21秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bに対するバックアップジョブが連続失敗しました。影響範囲はバッチ処理のみであり、オンラインには影響がありません。この事象はMercury AWS Storageにて発生しました。発見者は運用部の運用 一郎です。エラーコードはSTR-03-00252であり、推定原因はスナップショットの蓄積です。年末年始の稼働切替時にこの問題が発生する傾向があります。このため、バックアップの正常な実行が妨げられています。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00252', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00252', 'INC-2025-00252', 'バックアップジョブの連続失敗に関する調査を行いました。原因として、スナップショットの蓄積が疑われます。年末年始の稼働切替時にこの問題が頻発しており、ストレージの容量が逼迫している可能性があります。システムのログを確認したところ、複数のバックアップジョブが同時に失敗していることが確認されました。これにより、ストレージ・容量の問題が浮上しました。', 'バックアップジョブの連続失敗に関する調査を行いました。原因として、スナップショットの蓄積が疑われます。年末年始の稼働切替時にこの問題が頻発しており、ストレージの容量が逼迫している可能性があります。システムのログを確認したところ、複数のバックアップジョブが同時に失敗していることが確認されました。これにより、ストレージ・容量の問題が浮上しました。', TIMESTAMP WITH TIME ZONE '2025-04-09T04:53:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00373', 'INC-2025-00252', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-04-08T05:08:21+09:00', TIMESTAMP WITH TIME ZONE '2025-04-08T06:08:21+09:00', '【対応ログ】【ストレージ・容量障害】バックアップジョブの確認と対応', '初期対応として、運用部においてバックアップジョブの状況を確認しました。失敗したジョブの詳細を分析し、スナップショットのクリーンアップを実施しました。また、事象の影響を最小限に抑えるため、対象ストレージの容量を拡張する計画を立てました。今後の運用において再発防止策を講じる意思を示しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00374', 'INC-2025-00252', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-04-08T06:38:21+09:00', TIMESTAMP WITH TIME ZONE '2025-04-08T07:38:21+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00282', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-06-12T10:49:00+09:00', TIMESTAMP WITH TIME ZONE '2025-06-12T11:04:00+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2025年6月12日10時49分、株式会社ストッククラウドのサービスVenusにて、運用コンソールにおいてPagerDuty連携が失敗しました。これにより、オンコール通知が未達となり、運用部門に影響を及ぼしました。発見者は運用部の運用 一郎であり、11分後の11時00分にこの事象が検知されました。エラーコードはMON-07-00282です。年末年始の稼働切替時に発生したため、連携APIキーの権限不足が原因として疑われます。この件は重大度CRITICALとして対応を進めています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00282', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00282', 'INC-2025-00282', '本インシデントに関する調査を開始しました。まず、運用コンソールとPagerDuty間の連携APIキーの権限を確認し、適切な権限が設定されているかを検証します。次に、同様の状況が過去に発生していないかを確認し、監視・可用性障害の再発防止策を検討します。必要に応じて、PagerDutyサポートに連絡し、技術的な支援を受ける予定です。', '本インシデントに関する調査を開始しました。まず、運用コンソールとPagerDuty間の連携APIキーの権限を確認し、適切な権限が設定されているかを検証します。次に、同様の状況が過去に発生していないかを確認し、監視・可用性障害の再発防止策を検討します。必要に応じて、PagerDutyサポートに連絡し、技術的な支援を受ける予定です。', TIMESTAMP WITH TIME ZONE '2025-06-13T11:04:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00416', 'INC-2025-00282', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-06-12T11:19:00+09:00', TIMESTAMP WITH TIME ZONE '2025-06-12T12:19:00+09:00', '【初期対応】【CLU-10】PagerDuty連携失敗', '運用部門にて迅速な対応を行い、PagerDutyとの連携状態を確認しました。APIキーの権限をチェックし、必要な修正を加えました。その後、テストを行い、オンコール通知が正常に機能することを確認しました。影響を受けた顧客への情報提供も行い、今後の再発防止策についても検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00417', 'INC-2025-00282', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-06-12T12:49:00+09:00', TIMESTAMP WITH TIME ZONE '2025-06-12T13:49:00+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00302', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-02-07T14:57:50+09:00', TIMESTAMP WITH TIME ZONE '2025-02-07T15:42:50+09:00', '【障害報告】【監視・可用性障害】SLO燃焼率警告', '・発生日時: 2025年2月7日 14:57:50
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00302', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00302', 'INC-2025-00302', '本インシデントは2025年2月7日に発生し、SLO燃焼率が閾値を超過したことでエラーバジェット警告が発表されました。運用部の運用 一郎が発見し、全テナントに影響が及ぶ事象であると確認されました。調査の結果、SLO計算ウィンドウの設定誤りが原因と考えられ、直前の大規模セールに伴う影響が示唆されています。今後は設定の見直しを行い、再発防止に努めます。', '本インシデントは2025年2月7日に発生し、SLO燃焼率が閾値を超過したことでエラーバジェット警告が発表されました。運用部の運用 一郎が発見し、全テナントに影響が及ぶ事象であると確認されました。調査の結果、SLO計算ウィンドウの設定誤りが原因と考えられ、直前の大規模セールに伴う影響が示唆されています。今後は設定の見直しを行い、再発防止に努めます。', TIMESTAMP WITH TIME ZONE '2025-02-08T15:42:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00442', 'INC-2025-00302', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-02-07T15:57:50+09:00', TIMESTAMP WITH TIME ZONE '2025-02-07T16:57:50+09:00', '【初期対応】【監視・可用性障害】SLO燃焼率警告', 'インシデント発生後、迅速に対応を開始しました。まず、SLOダッシュボードを確認し、燃焼率が確かに閾値を超過していることを確認しました。運用チームは設定の確認を行い、SLO計算ウィンドウの見直しを進めることにしました。さらに、全顧客への通知と、影響範囲の確認を行い、適切な対策を講じる準備を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00443', 'INC-2025-00302', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-02-07T17:27:50+09:00', TIMESTAMP WITH TIME ZONE '2025-02-07T18:27:50+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00326', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-12-19T10:04:07+09:00', TIMESTAMP WITH TIME ZONE '2025-12-19T11:04:07+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2025年12月19日10時04分に発生した顧客側ネットワーク障害に関する報告です。顧客拠点NWにて、DNS解決成功後にTLS握手で接続が切断される事象が確認されました。この問題はインフラメンテナンス明けに発生し、全店舗へ影響が及んでいます。推定される原因はプロキシ証明書の期限切れであり、エラーコードはNW-03-00326です。顧客からの報告はありませんが、営業部の花子がこの問題を発見しました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00326', 'INC-2025-00326', 'インフラメンテナンス明けに発生した顧客ネットワークの障害について調査を実施しました。DNSは正常に解決されていたものの、TLS握手の段階で接続が切断される問題が発生しました。原因としてプロキシ証明書の期限切れが疑われており、今後の対応が必要です。技術詳細として、TLS終端における接続の切断が確認されています。', 'インフラメンテナンス明けに発生した顧客ネットワークの障害について調査を実施しました。DNSは正常に解決されていたものの、TLS握手の段階で接続が切断される問題が発生しました。原因としてプロキシ証明書の期限切れが疑われており、今後の対応が必要です。技術詳細として、TLS終端における接続の切断が確認されています。', TIMESTAMP WITH TIME ZONE '2025-12-20T11:04:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00478', 'INC-2025-00326', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-12-19T11:19:07+09:00', TIMESTAMP WITH TIME ZONE '2025-12-19T12:19:07+09:00', '初動対応', 'この問題に対して、まずは影響を受けている全店舗に対し報告を行い、状況の確認を実施しました。顧客からは具体的な影響の報告はなかったものの、接続問題が発生していることを周知しました。次に、プロキシ証明書の状態を確認し、更新作業を迅速に進める必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00358', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-08-30T15:04:38+09:00', TIMESTAMP WITH TIME ZONE '2025-08-30T15:49:38+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2025年08月30日15時04分38秒、株式会社ストッククラウドのMercuryにおいて、ストレージ溢れが発生しました。運用部の運用 一郎が発見したこの問題は、15時49分38秒に検知されるまでの45分間、同一アラートが短時間に数百件発報しており、監視・可用性障害の影響を受けました。特に、運用部門のみが影響を受けており、アラート抑制ルールの未設定が推定原因とされています。この発生契機は、大規模セール開始直前であり、Mercury AWS Storage（ゾーンA）及びアラートマネージャに対する影響が深刻でした。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00358', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00358', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00358', 'INC-2025-00358', '調査の結果、2025年08月30日に発生したアラート疲労は、大規模セール開始直前に発報された同一アラートが原因でした。アラート抑制ルールが未設定であったため、数百件のアラートが発生し、これが運用部門の混乱を招きました。今後は、アラート抑制ルールを適切に設定し、同様の事象を防止する必要があります。また、監視・可用性の仕組みの見直しも検討すべきです。', '調査の結果、2025年08月30日に発生したアラート疲労は、大規模セール開始直前に発報された同一アラートが原因でした。アラート抑制ルールが未設定であったため、数百件のアラートが発生し、これが運用部門の混乱を招きました。今後は、アラート抑制ルールを適切に設定し、同様の事象を防止する必要があります。また、監視・可用性の仕組みの見直しも検討すべきです。', TIMESTAMP WITH TIME ZONE '2025-08-31T15:49:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00524', 'INC-2025-00358', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-08-30T16:04:38+09:00', TIMESTAMP WITH TIME ZONE '2025-08-30T17:04:38+09:00', '【初動対応】【監視・可用性障害】アラート疲労に対する初動対応', '初動対応として、運用部門では直ちにアラートログを確認しました。発報数が異常であることを確認し、アラート抑制ルールの設定が行われていないことを特定しました。さらに、運用 一郎が迅速に原因分析を行い、状況の改善に向けた対応策を検討しています。これにより、今後のアラート疲労を未然に防ぐことを目指します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00360', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-06-04T03:38:48+09:00', TIMESTAMP WITH TIME ZONE '2025-06-04T04:38:48+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2025年6月4日03時38分48秒に、架空食品店Bにて顧客側ネットワーク障害が発生しました。この障害により、特定拠点のみでAPI呼び出しが失敗する事象が確認されました。確認された症状として、店舗LANのスイッチ故障が疑われます。影響を受けるのは架空食品店Bのみで、顧客拠点NW（ゾーンA）及び顧客側FWに影響が及んでいます。エラーコードはNW-02-00360であり、新規店舗追加の初日に発生したことが特筆されます。04時22分48秒に検知されるまでに44分の遅延がありました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00360', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00360', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00360', 'INC-2025-00360', '障害発生の原因を特定するため、架空食品店Bの顧客拠点NWの調査を実施しました。調査の結果、特定拠点のLANスイッチに異常が見受けられました。これにより、API呼び出しが失敗し、顧客サービスに影響を与えていることが確認されました。原因として、スイッチの故障が最も可能性が高いと考えられます。', '障害発生の原因を特定するため、架空食品店Bの顧客拠点NWの調査を実施しました。調査の結果、特定拠点のLANスイッチに異常が見受けられました。これにより、API呼び出しが失敗し、顧客サービスに影響を与えていることが確認されました。原因として、スイッチの故障が最も可能性が高いと考えられます。', TIMESTAMP WITH TIME ZONE '2025-06-05T04:38:48+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00526', 'INC-2025-00360', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-06-04T04:53:48+09:00', TIMESTAMP WITH TIME ZONE '2025-06-04T05:53:48+09:00', '【対応ログ】【顧客ネットワーク障害】拠点限定API失敗', '初期対応として、架空食品店Bのネットワーク機器を再起動し、状況を観察しました。再起動後もAPI呼び出しの失敗が続いており、さらなる調査が必要であると判断されました。顧客には状況を報告し、修正作業を進める旨を伝えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00392', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-03-09T07:54:28+09:00', TIMESTAMP WITH TIME ZONE '2025-03-09T08:09:28+09:00', '【障害報告】【監視・可用性障害】可用性レポート誤集計', '2025年3月9日07時54分28秒に、株式会社ストッククラウドの運用コンソールにおいて、月次可用性レポートが実績より高く表示される事象が発生しました。この症状は、運用部門に影響を及ぼし、原因としてメンテナンス除外時間の二重計上が疑われています。この問題は、月末棚卸の開始時に発生し、08時00分28秒に検知されました。運用部の運用 一郎によって発見され、影響範囲は運用部門のみとなります。可用性レポートの誤集計が原因で、運用に支障をきたす可能性があるため、今後の運用体制の見直しが必要です。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00392', 'INC-2025-00392', '本インシデントに関して、運用部門が行った調査の結果、月末棚卸の開始時に月次可用性レポートが実績より高く表示される問題が確認されました。推定原因として、メンテナンス除外時間の二重計上が挙げられ、これが誤集計を引き起こす要因となったと考えられます。運用部門は、今後このような事象が再発しないよう、監視体制の強化および報告手順の見直しを検討しています。', '本インシデントに関して、運用部門が行った調査の結果、月末棚卸の開始時に月次可用性レポートが実績より高く表示される問題が確認されました。推定原因として、メンテナンス除外時間の二重計上が挙げられ、これが誤集計を引き起こす要因となったと考えられます。運用部門は、今後このような事象が再発しないよう、監視体制の強化および報告手順の見直しを検討しています。', TIMESTAMP WITH TIME ZONE '2025-03-10T08:09:28+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00575', 'INC-2025-00392', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-09T08:24:28+09:00', TIMESTAMP WITH TIME ZONE '2025-03-09T09:24:28+09:00', '【初動対応】【監視・可用性障害】可用性レポート誤集計に対する初動対応', '運用部の運用 一郎は、2025年3月9日08時00分28秒に可用性レポートの誤集計を検知し、直ちに初動対応を開始しました。問題の詳細を調査し、メンテナンス時間の扱いに関するルールを確認した上で、関連するデータを集計し、誤集計の影響を最小限に抑えるための調整を実施しました。これにより、運用部門は速やかに状況を把握し、適切な情報を関係者に提供することができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00407', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-12-06T02:15:49+09:00', TIMESTAMP WITH TIME ZONE '2025-12-06T02:30:49+09:00', '【障害報告】【CLU-08】MFAデバイス不一致', '2025年12月6日02時15分49秒、株式会社ストッククラウドの運用コンソールにおいて、MFAデバイス登録不一致によりログイン不可の事象が発生しました。発見者は運用部の運用 一郎であり、事象は検知までに12分を要しました。影響範囲は単一店舗に限られています。発生契機は顧客オンボーディング当日であり、エラーコードはAUTH-03-00407です。技術詳細として、MFAシードの再発行未同期が原因として疑われており、これによりMFAデバイスの不一致が生じたと考えられます。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00407', 'INC-2025-00407', '本事象の調査において、MFAデバイスの登録状況とシードの発行履歴を確認しました。MFAシードの再発行が行われていたにもかかわらず、その変更が認証サービスに反映されておらず、ログイン試行時にMFAデバイスの不一致が発生しました。このため、顧客は認証を受けられず、ログイン不可となりました。', '本事象の調査において、MFAデバイスの登録状況とシードの発行履歴を確認しました。MFAシードの再発行が行われていたにもかかわらず、その変更が認証サービスに反映されておらず、ログイン試行時にMFAデバイスの不一致が発生しました。このため、顧客は認証を受けられず、ログイン不可となりました。', TIMESTAMP WITH TIME ZONE '2025-12-07T02:30:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00597', 'INC-2025-00407', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-06T02:45:49+09:00', TIMESTAMP WITH TIME ZONE '2025-12-06T03:45:49+09:00', '【初期対応】【CLU-08】MFAデバイス不一致', '初期対応として、運用部は同じ状況が発生しないよう、MFAシードの再発行後に必ず同期が行われるようプロセスを見直しました。また、影響を受けた顧客に対しては、迅速にMFAデバイスの登録状況を確認し、必要なサポートを提供しました。ログイン不可の状態を解消すべく、運用部は該当顧客と連携し、速やかに対応を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00413', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-06-28T01:32:21+09:00', TIMESTAMP WITH TIME ZONE '2025-06-28T01:47:21+09:00', '【障害報告】【CLU-08】APIトークン早期失効', '2025年6月28日01時32分21秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bからの報告により、運用コンソールにおいてAPIトークンが発行直後に失効扱いとなる事象が発生しました。影響範囲はサービス全体の一部機能に及び、エラーコードAUTH-04-00413が確認されています。この障害はインフラメンテナンス明けに発生したことから、サーバー時刻のNTPずれが推定原因とされています。検知は発生から21分後の01時53分21秒に行われました。この事象により、顧客への影響が懸念されるため、原因究明と再発防止策の検討が急務です。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00413', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00413', 'INC-2025-00413', '本事象の原因として、インフラメンテナンス明けのサーバー時刻のNTPずれが推定されます。APIトークンが発行された際に、サーバー時刻の誤差により失効と認識される事態が発生しました。具体的には、NTPサーバーとの同期が適切に行われなかった可能性が考えられ、これによってAPIトークンが正常に機能しなくなったと推測しています。今後、NTP設定の見直しを行い、同様の障害を防ぐための対策を講じる必要があります', '本事象の原因として、インフラメンテナンス明けのサーバー時刻のNTPずれが推定されます。APIトークンが発行された際に、サーバー時刻の誤差により失効と認識される事態が発生しました。具体的には、NTPサーバーとの同期が適切に行われなかった可能性が考えられ、これによってAPIトークンが正常に機能しなくなったと推測しています。今後、NTP設定の見直しを行い、同様の障害を防ぐための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-06-29T01:47:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00603', 'INC-2025-00413', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-06-28T02:02:21+09:00', TIMESTAMP WITH TIME ZONE '2025-06-28T03:02:21+09:00', '初動対応', '障害発生を受けて、運用部の運用 一郎が即座に問題の調査を開始しました。顧客に対しては状況を説明し、APIトークンの再発行を行いました。また、影響を受けたサービス機能の特定を進め、必要に応じて別の認証方法の提供を検討しました。障害の影響を受けた顧客には、迅速に情報提供を行うことで信頼回復を図りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00415', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-01-23T03:29:42+09:00', TIMESTAMP WITH TIME ZONE '2025-01-23T03:44:42+09:00', '【障害報告】【CLU-10】メトリクス欠損', '2025年1月23日03時29分42秒、日本の株式会社ストッククラウドが提供するサービスMercuryにおいて、運用者の作業ミスによるアクセス障害が発生しました。影響を受けた顧客は架空食品店Aであり、具体的には運用コンソールにおいて主要メトリクス系列が15分間欠損する事象が確認されました。発生の契機はインフラメンテナンス明けであり、メトリクスエージェントの再起動失敗が推定原因として挙げられています。この障害は運用部門にのみ影響を及ぼし、重大度はHIGHとされています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00415', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00415', 'INC-2025-00415', '調査の結果、インフラメンテナンス明けにおいてメトリクスエージェントが正しく再起動できなかったことが確認されました。この失敗が原因で、運用コンソールからの主要メトリクス系列が15分間欠損する障害が発生しました。影響は運用部門のみであり、監視・可用性障害として分類されます。今後、インフラメンテナンス後の再起動手順を見直し、エージェントの監視を強化する必要があります。', '調査の結果、インフラメンテナンス明けにおいてメトリクスエージェントが正しく再起動できなかったことが確認されました。この失敗が原因で、運用コンソールからの主要メトリクス系列が15分間欠損する障害が発生しました。影響は運用部門のみであり、監視・可用性障害として分類されます。今後、インフラメンテナンス後の再起動手順を見直し、エージェントの監視を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-24T03:44:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00605', 'INC-2025-00415', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-23T03:59:42+09:00', TIMESTAMP WITH TIME ZONE '2025-01-23T04:59:42+09:00', '【初期対応】【CLU-10】メトリクス欠損への即時対応', '運用部の運用 一郎が2025年1月23日03時42分42秒に本障害を検知し、直ちにメトリクスエージェントの再起動を試みました。しかし、再起動は失敗し、原因としてインフラメンテナンス後の設定ミスが疑われました。運用部では監視体制を整え、エージェントの状況を継続的に確認することが必要と判断しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00606', 'INC-2025-00415', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-23T05:29:42+09:00', TIMESTAMP WITH TIME ZONE '2025-01-23T06:29:42+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00422', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-02-15T00:27:36+09:00', TIMESTAMP WITH TIME ZONE '2025-02-15T00:57:36+09:00', '【障害報告】【API連携・EDI障害】レート超過429', '2025年2月15日00:27に、株式会社ストッククラウドのMercuryサービスにおいて、架空食品店Bおよび架空食品店Aの在庫登録が失敗しました。症状として、パートナーAPIが429を返し、連携が停止しました。これは、大規模セール開始直前に発生しました。推定される原因は、呼出頻度の事前調整不足です。影響範囲はサービス全体の一部機能に及び、特にMercury AWS AP（ゾーンA）およびAPIゲートウェイにおいて顕著です。運用部の運用 一郎が発見しました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00422', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00422', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00422', 'INC-2025-00422', '現在、運用部ではこの障害の原因を詳しく調査しています。429エラーが発生した背景には、大規模セール開始直前という状況があるため、呼出頻度の事前調整が不十分だった可能性があります。API連携・EDIの影響範囲を確認し、迅速に問題を解決するための対応を進めています。', '現在、運用部ではこの障害の原因を詳しく調査しています。429エラーが発生した背景には、大規模セール開始直前という状況があるため、呼出頻度の事前調整が不十分だった可能性があります。API連携・EDIの影響範囲を確認し、迅速に問題を解決するための対応を進めています。', TIMESTAMP WITH TIME ZONE '2025-02-16T00:57:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00616', 'INC-2025-00422', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-02-15T01:12:36+09:00', TIMESTAMP WITH TIME ZONE '2025-02-15T02:12:36+09:00', '【対応ログ】【API連携・EDI障害】初期対応', '2025年2月15日01:00、運用 一郎がパートナーAPIの429エラーを確認し、連携停止の状況を記録しました。初期対応として、呼出頻度の見直しを指示し、関連部門に通知を行いました。今後の対応については、追加の調整が必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00617', 'INC-2025-00422', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-02-15T02:42:36+09:00', TIMESTAMP WITH TIME ZONE '2025-02-15T03:42:36+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00431', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-07-26T14:09:49+09:00', TIMESTAMP WITH TIME ZONE '2025-07-26T14:39:49+09:00', '【障害報告】【CLU-08】MFAデバイス不一致', '・発生日時: 2025-07-26T14:09:49+09:00
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00431', 'INC-2025-00431', '障害が発生した原因として、MFAシードの再発行未同期が考えられます。この問題により、MFAデバイスの登録情報が正しく反映されず、ログインが不可能となってしまいました。ログイン不可の症状は顧客が新たにオンボーディングを行った当日に発生しており、影響範囲は単一店舗に限定されました。', '障害が発生した原因として、MFAシードの再発行未同期が考えられます。この問題により、MFAデバイスの登録情報が正しく反映されず、ログインが不可能となってしまいました。ログイン不可の症状は顧客が新たにオンボーディングを行った当日に発生しており、影響範囲は単一店舗に限定されました。', TIMESTAMP WITH TIME ZONE '2025-07-27T14:39:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00632', 'INC-2025-00431', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-07-26T14:54:49+09:00', TIMESTAMP WITH TIME ZONE '2025-07-26T15:54:49+09:00', '【初動対応】【CLU-08】MFAデバイス不一致', '本障害の初動対応として、MFAデバイスの登録状況を確認し、未同期の原因を特定するためにシステムログをチェックしました。影響を受けた店舗には緊急連絡を行い、現在の状況を説明し、代替手段として手動での認証手続きを推奨しました。問題の解決に向けて、技術チームと連携し、迅速な対応を進めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00633', 'INC-2025-00431', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-07-26T16:24:49+09:00', TIMESTAMP WITH TIME ZONE '2025-07-26T17:24:49+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00432', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-08-08T01:40:45+09:00', TIMESTAMP WITH TIME ZONE '2025-08-08T02:10:45+09:00', '【障害報告】【監視・可用性障害】PagerDuty連携失敗', '2025年8月8日01:40:45に株式会社ストッククラウドのMercuryサービスにおいて、PagerDuty連携が失敗しオンコール通知が未達となりました。影響を受けたのは運用部門のみで、発生したエラーコードはMON-07-00432です。年末年始の稼働切替時に発生した問題であり、連携APIキーの権限不足が推定されます。02:11:45にこの事象が検知されており、検知までの時間は31分でした。影響を受けたコンポーネントはVenus Azure AP（Secondary）およびインシデント通知です。適切な対応が求められます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00432', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00432', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00432', 'INC-2025-00432', '本インシデントについて調査を行った結果、PagerDuty連携が失敗した理由は連携APIキーの権限不足と考えられます。この権限不足により、オンコール通知が運用部門に届かない事態が発生しました。運用部門が適切に対応できなかったため、影響が拡大する可能性がありました。今後、APIキーの権限を再確認し、適切な設定を行う必要があります。', '本インシデントについて調査を行った結果、PagerDuty連携が失敗した理由は連携APIキーの権限不足と考えられます。この権限不足により、オンコール通知が運用部門に届かない事態が発生しました。運用部門が適切に対応できなかったため、影響が拡大する可能性がありました。今後、APIキーの権限を再確認し、適切な設定を行う必要があります。', TIMESTAMP WITH TIME ZONE '2025-08-09T02:10:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00634', 'INC-2025-00432', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-08-08T02:25:45+09:00', TIMESTAMP WITH TIME ZONE '2025-08-08T03:25:45+09:00', '【初動対応】PagerDuty連携失敗への対応', 'インシデント発生後、運用部門は直ちに調査を開始しました。まず、PagerDutyの設定を確認し、連携APIキーの権限不足が原因であることを特定しました。この情報を元に、権限の修正作業を実施し、今後同様の問題が発生しないよう対策を講じるためのドキュメントも作成しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00635', 'INC-2025-00432', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-08-08T03:55:45+09:00', TIMESTAMP WITH TIME ZONE '2025-08-08T04:55:45+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00436', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-10-13T23:37:36+09:00', TIMESTAMP WITH TIME ZONE '2025-10-14T01:37:36+09:00', '【障害報告】【棚卸・POS突合障害】差異リスト空表示', '2025年10月13日23時37分36秒に、株式会社ストッククラウドのサービスMercuryにおいて、顧客「架空食品店A」および「架空食品店B」の店舗端末で棚卸差異リストが空表示になる問題が発生しました。これは、同一顧客の全店舗に影響を及ぼし、発生契機はデータ移行バッチ実行中でした。該当のエラーコードはINV-04-00436です。影響を受けたコンポーネントは、顧客店舗POS（Secondary）および店舗在庫ビューであり、店舗別在庫の集計粒度不一致が推定される原因となっています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00436', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00436', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00436', 'INC-2025-00436', 'この問題に関する調査が行われました。データ移行バッチ実行中に、店舗端末で棚卸差異リストが空表示になったため、店舗別在庫の集計粒度不一致が疑われます。影響範囲は、顧客「架空食品店A」と「架空食品店B」の全店舗に及び、早急な対応が必要です。', 'この問題に関する調査が行われました。データ移行バッチ実行中に、店舗端末で棚卸差異リストが空表示になったため、店舗別在庫の集計粒度不一致が疑われます。影響範囲は、顧客「架空食品店A」と「架空食品店B」の全店舗に及び、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2025-10-15T01:37:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00640', 'INC-2025-00436', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-10-14T01:52:36+09:00', TIMESTAMP WITH TIME ZONE '2025-10-14T02:52:36+09:00', '【初動対応】【棚卸・POS突合障害】差異リスト空表示', '営業部の花子が本件を発見し、直ちに調査を開始しました。エラーコードINV-04-00436に関連するログを確認し、データ移行バッチ実行中の状況を把握するために、担当エンジニアに連絡を取りました。問題の早期解決を目指し、必要な情報を収集し続けます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00441', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-06-04T15:00:07+09:00', TIMESTAMP WITH TIME ZONE '2025-06-04T15:45:07+09:00', '【障害報告】【監視・可用性障害】ヘルスチェック過負荷', '2025年6月4日15時00分07秒に、株式会社ストッククラウドのMercuryサービスにおいて、ストレージ溢れのインシデントが発生しました。発見者である運用 一郎(運用部)が、ヘルスチェック過多によるAPサーバーの負荷増加を確認しました。この問題はインフラメンテナンス明けに起こり、全テナントに波及する影響が予想されます。エラーコードはMON-06-00441で、現時点での影響コンポーネントはMercury AWS Storage（ゾーンB）およびロードバランサです。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00441', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00441', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00441', 'INC-2025-00441', 'インフラメンテナンス明けにおけるヘルスチェック過多が原因でAPサーバーの負荷が増加したことを確認しました。LBヘルスチェック間隔が過短設定であったことが影響していると考えられ、このままでは全テナントにさらに悪影響を及ぼす可能性があります。速やかな対応が必要です。', 'インフラメンテナンス明けにおけるヘルスチェック過多が原因でAPサーバーの負荷が増加したことを確認しました。LBヘルスチェック間隔が過短設定であったことが影響していると考えられ、このままでは全テナントにさらに悪影響を及ぼす可能性があります。速やかな対応が必要です。', TIMESTAMP WITH TIME ZONE '2025-06-05T15:45:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00649', 'INC-2025-00441', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-06-04T16:00:07+09:00', TIMESTAMP WITH TIME ZONE '2025-06-04T17:00:07+09:00', '【初期対応】【監視・可用性障害】ヘルスチェック過負荷', '運用 一郎が確認したところ、ヘルスチェックが過多でAPサーバーに過負荷がかかっている状態です。LBのヘルスチェック間隔の過短設定が原因と考え、設定の見直しを検討します。この問題については全社で連携して対応する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00650', 'INC-2025-00441', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-06-04T17:30:07+09:00', TIMESTAMP WITH TIME ZONE '2025-06-04T18:30:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00450', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-12-14T15:17:38+09:00', TIMESTAMP WITH TIME ZONE '2025-12-14T15:47:38+09:00', '【障害報告】【在庫マスター設定障害】マイナス在庫表示', '2025年12月14日15時17分38秒、株式会社ストッククラウドのMercuryにおいて、架空食品店Bおよび架空食品店Aの全店舗で、登録後に在庫数量がマイナス表示になる事象が発生しました。この障害は月末棚卸の開始時に発生し、デフォルト倉庫IDの未設定が推定原因です。影響を受けたコンポーネントはMercury AWS APおよび商品マスターDBであり、エラーコードはMST-02-00450です。この事象により、同一顧客の全店舗で在庫管理が困難となり、運用への影響が懸念されます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00450', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00450', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00450', 'INC-2025-00450', '本障害は月末棚卸の開始時に発生しました。登録後に在庫数量がマイナス表示になる問題は、デフォルト倉庫IDの未設定が原因であると考えられます。これにより、全店舗で在庫の整合性が取れず、運用部門への影響も大きくなる可能性があります。引き続き詳細な調査を行い、早急に対応策を検討します。', '本障害は月末棚卸の開始時に発生しました。登録後に在庫数量がマイナス表示になる問題は、デフォルト倉庫IDの未設定が原因であると考えられます。これにより、全店舗で在庫の整合性が取れず、運用部門への影響も大きくなる可能性があります。引き続き詳細な調査を行い、早急に対応策を検討します。', TIMESTAMP WITH TIME ZONE '2025-12-15T15:47:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00664', 'INC-2025-00450', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-14T16:02:38+09:00', TIMESTAMP WITH TIME ZONE '2025-12-14T17:02:38+09:00', '【初期対応】【在庫マスター設定障害】マイナス在庫表示', '本事象が発生した際、運用部の運用 一郎が迅速に状況を確認しました。架空食品店Bと架空食品店Aからの問い合わせに対し、問題の内容を把握するとともに、デフォルト倉庫IDの設定を確認しました。今後、再発防止策として、倉庫IDの設定を定期的に確認するフローを構築することを提案します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00489', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-07-27T06:08:55+09:00', TIMESTAMP WITH TIME ZONE '2025-07-27T08:08:55+09:00', '【障害報告】【棚卸・POS突合障害】移動平均単価異常', '株式会社ストッククラウドのサービスMercuryにおいて、2025年7月27日6時08分55秒に発生した棚卸突合失敗について報告します。本事象は、架空食品店Aおよび架空食品店Bの顧客店舗POSにおいて、棚卸後の評価単価が想定外の値になるという症状が見られました。定例リリース直後の発生であり、原因として移動平均計算式の適用期間誤りが推測されます。検知は2025年7月27日8時18分55秒に行われ、検知まで130分かかりました。本事象はサービス全体の一部機能に影響を及ぼすもので、特に在庫評価エンジンに関連しています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00489', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00489', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00489', 'INC-2025-00489', '本インシデントに関する調査を行った結果、定例リリース直後に棚卸後の評価単価が想定外の値になる問題が発生したことが確認されました。移動平均計算式の適用期間に誤りがあったことが原因とされ、これにより評価単価が正しく計算されず、顧客に混乱を招く結果となりました。今後は、リリース前のテストを強化し、このような問題の再発防止策を講じる必要があります。', '本インシデントに関する調査を行った結果、定例リリース直後に棚卸後の評価単価が想定外の値になる問題が発生したことが確認されました。移動平均計算式の適用期間に誤りがあったことが原因とされ、これにより評価単価が正しく計算されず、顧客に混乱を招く結果となりました。今後は、リリース前のテストを強化し、このような問題の再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-07-28T08:08:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00721', 'INC-2025-00489', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-07-27T08:23:55+09:00', TIMESTAMP WITH TIME ZONE '2025-07-27T09:23:55+09:00', '【初動対応】【棚卸・POS突合障害】移動平均単価異常', 'インシデント発生後、迅速に初動対応を実施しました。営業部の花子が顧客に連絡を取り、状況を説明し、評価単価の異常についての情報を収集しました。また、技術チームが原因調査を始め、移動平均計算式の適用期間についての見直しを行いました。顧客に対して誤解を招かないよう、状況を把握し、報告書を作成する方針を決定しました。初回の調査結果を基に、適切な対応策を検討中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00722', 'INC-2025-00489', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-07-27T09:53:55+09:00', TIMESTAMP WITH TIME ZONE '2025-07-27T10:53:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00492', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-12-16T08:56:40+09:00', TIMESTAMP WITH TIME ZONE '2025-12-16T09:26:40+09:00', '【障害報告】【認証・セッション障害】APIトークン早期失効', '2025年12月16日08時56分40秒に、株式会社ストッククラウドのサービスMercuryにおいて、APIトークンが発行直後に失効扱いになる事象が発生しました。この障害は、顧客である架空食品店Aに影響を及ぼし、特にVenus Azure APでの応答遅延が顕著でした。検知は09時37分40秒で、影響が及んだのはサービス全体の一部機能です。推定原因として、インフラメンテナンス明けにおけるサーバー時刻のNTPずれが考えられます。なお、エラーコードはAUTH-04-00492です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00492', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00492', 'INC-2025-00492', '本事象の調査を行った結果、インフラメンテナンスが行われた直後にAPIトークンが発行された際に失効扱いとなる問題が発生していることが確認されました。NTPサーバーとの時刻同期に問題があった可能性が高く、これによりトークンの発行時刻が誤認識されたと推測されます。今後はNTPの設定や監視体制の見直しを行う必要があります。', '本事象の調査を行った結果、インフラメンテナンスが行われた直後にAPIトークンが発行された際に失効扱いとなる問題が発生していることが確認されました。NTPサーバーとの時刻同期に問題があった可能性が高く、これによりトークンの発行時刻が誤認識されたと推測されます。今後はNTPの設定や監視体制の見直しを行う必要があります。', TIMESTAMP WITH TIME ZONE '2025-12-17T09:26:40+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00725', 'INC-2025-00492', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-16T09:41:40+09:00', TIMESTAMP WITH TIME ZONE '2025-12-16T10:41:40+09:00', '初期対応ログ', 'インシデント発生後、運用チームは直ちに状況の把握に取り組み、NTPサーバーとの時刻同期を確認しました。APIトークンの発行時刻に関するログを分析し、影響を受けた顧客に対して状況を通知しました。さらに、関連するインフラの監視を強化し、問題の再発防止に向けた対策を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00726', 'INC-2025-00492', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-16T11:11:40+09:00', TIMESTAMP WITH TIME ZONE '2025-12-16T12:11:40+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00493', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-09-13T08:13:32+09:00', TIMESTAMP WITH TIME ZONE '2025-09-13T08:28:32+09:00', '【障害報告】【運用操作・権限障害】権限変更後全員403', '2025年09月13日08時13分32秒、株式会社ストッククラウドのサービスVenusにおいて、運用コンソールにおいて権限変更後全ユーザーが403になる事象が発生しました。このインシデントは運用部の運用 一郎によって発見され、検知は08時29分32秒であり、発見から16分の経過時間がありました。原因としては、インフラメンテナンス明けにロールバインディングの一括上書きミスが疑われています。この障害は全テナントに波及し、運用操作・権限障害が発生していることが確認されています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00493', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00493', 'INC-2025-00493', '調査の結果、権限変更が実施された時間とインフラメンテナンスの終了時間が密接に関連していることがわかりました。ロールバインディングの一括上書きミスが根本的な原因であると考えられ、エラーコードOPS-02-00493が関連しています。運用コンソールおよび認可サービスに影響が及んでおり、この問題は全テナントに影響を及ぼす可能性があるため、早急に対応が必要です。', '調査の結果、権限変更が実施された時間とインフラメンテナンスの終了時間が密接に関連していることがわかりました。ロールバインディングの一括上書きミスが根本的な原因であると考えられ、エラーコードOPS-02-00493が関連しています。運用コンソールおよび認可サービスに影響が及んでおり、この問題は全テナントに影響を及ぼす可能性があるため、早急に対応が必要です。', TIMESTAMP WITH TIME ZONE '2025-09-14T08:28:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00727', 'INC-2025-00493', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-09-13T08:43:32+09:00', TIMESTAMP WITH TIME ZONE '2025-09-13T09:43:32+09:00', '【対応ログ】【運用操作・権限障害】権限変更後全員403', 'インシデント発生直後、運用部の運用 一郎が状況を確認し、権限設定の変更履歴を調査しました。全ユーザーに対する403エラーが発生していることが確認され、即座に権限変更のロールバックを実施しました。引き続き、原因の特定と再発防止策の検討を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00518', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-01-21T10:20:52+09:00', TIMESTAMP WITH TIME ZONE '2025-01-21T11:20:52+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2025年1月21日10時20分に、架空服飾店Aにおいて、ISP側BGP経路障害により複数拠点が同時不通となる事象が発生しました。顧客拠点NW及びDNSリゾルバが影響を受け、インフラメンテナンス明けのタイミングで障害が起きたことが確認されました。障害発生から54分後の11時14分に検知されましたが、影響範囲は同一顧客の全店舗に及びました。今後、ISP側のBGP経路障害についての詳細な調査が必要です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00518', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00518', 'INC-2025-00518', '障害の発生後、迅速に調査を開始しました。ISP側のBGP経路障害が原因と考えられ、現在も影響を受けた全拠点での通信不具合が確認されています。調査チームは、障害の再発防止に向けた対策を検討中で、ISP側の状況確認を行っています。障害の根本的な原因が確認され次第、詳細な情報を共有予定です。', '障害の発生後、迅速に調査を開始しました。ISP側のBGP経路障害が原因と考えられ、現在も影響を受けた全拠点での通信不具合が確認されています。調査チームは、障害の再発防止に向けた対策を検討中で、ISP側の状況確認を行っています。障害の根本的な原因が確認され次第、詳細な情報を共有予定です。', TIMESTAMP WITH TIME ZONE '2025-01-22T11:20:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00764', 'INC-2025-00518', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-21T11:35:52+09:00', TIMESTAMP WITH TIME ZONE '2025-01-21T12:35:52+09:00', '【初期対応】【顧客ネットワーク障害】BGP経路障害波及', '障害発生直後、担当の営業 花子が顧客に連絡を取り、状況を把握しました。顧客には現在の障害状況やISP側の調査を行っている旨を伝えました。お客様からの問い合わせにも迅速に対応し、影響を最小限に抑えるための情報提供を心掛けました。ISPとの連携を強化し、進捗を随時報告する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00765', 'INC-2025-00518', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-21T13:05:52+09:00', TIMESTAMP WITH TIME ZONE '2025-01-21T14:05:52+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00545', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-10-26T09:37:52+09:00', TIMESTAMP WITH TIME ZONE '2025-10-26T09:52:52+09:00', '【障害報告】【運用操作・権限障害】本番DB誤接続', '2025年10月26日09時37分52分に、株式会社ストッククラウドの運用コンソールにおいて、運用ツールが本番DB以外に接続していた事象が発生しました。この障害は定例リリース直後に確認され、全テナントに波及する影響がありました。顧客である架空食品店Bおよび架空食品店Aに対して、サービスの提供に支障が出た可能性があります。エラーコードはOPS-06-00545で、運用部の運用 一郎が発見しました。この問題は、本番DBへの誤接続設定が原因であると推定されており、早急な対応が求められます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00545', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00545', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00545', 'INC-2025-00545', '本障害の発生原因として、運用ツールの設定において本番DBへの誤接続が疑われます。定例リリース直後に運用コンソールが本番DB以外のデータベースに接続したことが確認されたため、設定ミスの可能性が高いと考えられます。影響範囲は全テナントに及び、顧客への影響が懸念されるため、早急な確認と修正が必要です。', '本障害の発生原因として、運用ツールの設定において本番DBへの誤接続が疑われます。定例リリース直後に運用コンソールが本番DB以外のデータベースに接続したことが確認されたため、設定ミスの可能性が高いと考えられます。影響範囲は全テナントに及び、顧客への影響が懸念されるため、早急な確認と修正が必要です。', TIMESTAMP WITH TIME ZONE '2025-10-27T09:52:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00806', 'INC-2025-00545', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-10-26T10:07:52+09:00', TIMESTAMP WITH TIME ZONE '2025-10-26T11:07:52+09:00', '【初動対応】【運用操作・権限障害】本番DB誤接続', '初動対応としまして、運用部の運用 一郎が迅速に運用ツールの設定を確認し、誤接続の原因となる設定を特定しました。全テナントへ影響が及んでいるため、直ちに修正作業を開始し、顧客への報告と説明を行う方針です。また、運用チーム全体での連携を強化し、今後の再発防止策を検討することにいたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00550', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-10-18T23:00:45+09:00', TIMESTAMP WITH TIME ZONE '2025-10-19T00:00:45+09:00', '【障害報告】【顧客ネットワーク障害】SD-WAN経路選択誤り', '2025年10月18日23時00分45秒に、株式会社ストッククラウドのサービスVenusにおいて、顧客「架空服飾店A」の拠点ネットワークに障害が発生しました。SD-WANが劣化回線を選択し、遅延が増大しました。影響は、同一顧客の全店舗に及びました。この障害は大規模セール開始直前という発生契機によって引き起こされました。エラーコードはNW-10-00550で、問題は顧客拠点のネットワーク（DRサイト）及び拠点VPNゲートウェイに関連しています。推定原因として、SD-WANポリシーの閾値設定誤りが考えられます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00550', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00550', 'INC-2025-00550', '障害発生の原因について調査を行った結果、大規模セール開始直前にSD-WANが劣化回線を誤って選択したことが確認されました。これにより、ネットワークの遅延が著しく増大し、顧客「架空服飾店A」の全店舗に影響を及ぼしました。根本的な原因は、SD-WANポリシーの閾値設定に誤りがあったことです。この設定ミスにより、正しい経路選択が行われず、結果的にサービスの品質が低下しました。', '障害発生の原因について調査を行った結果、大規模セール開始直前にSD-WANが劣化回線を誤って選択したことが確認されました。これにより、ネットワークの遅延が著しく増大し、顧客「架空服飾店A」の全店舗に影響を及ぼしました。根本的な原因は、SD-WANポリシーの閾値設定に誤りがあったことです。この設定ミスにより、正しい経路選択が行われず、結果的にサービスの品質が低下しました。', TIMESTAMP WITH TIME ZONE '2025-10-20T00:00:45+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00815', 'INC-2025-00550', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-10-19T00:15:45+09:00', TIMESTAMP WITH TIME ZONE '2025-10-19T01:15:45+09:00', '初期対応', '障害を検知した後、即座に営業部の花子が対応にあたり、問題の特定を進めました。顧客に対しては、障害の発生を報告し、現在の状況を説明しました。具体的には、SD-WANの経路選択に関する問題を指摘し、復旧作業を開始するために技術チームとの連携を強化しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00816', 'INC-2025-00550', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-10-19T01:45:45+09:00', TIMESTAMP WITH TIME ZONE '2025-10-19T02:45:45+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00552', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-10-16T09:16:13+09:00', TIMESTAMP WITH TIME ZONE '2025-10-16T11:16:13+09:00', '【障害報告】【データ同期・整合性障害】楽観ロック競合多発', '2025年10月16日09時16分13秒に、株式会社ストッククラウドのサービスVenusにおいて、顧客「架空服飾店A」で棚卸突合失敗の事象が発生しました。症状としては、楽観ロック競合が多発し、更新失敗率が上昇しました。この影響は全テナントに波及し、特に顧客店舗POS（ゾーンB）及び在庫登録APIにおいて顕著でした。発生の契機は大規模セール開始直前であり、バージョンカラム更新ロジックの不備が推定されます。インシデントは11時04分13秒に検知され、約108分間の未検知期間がありました。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00552', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00552', 'INC-2025-00552', '本件インシデントの調査を実施しました。楽観ロック競合が多発している原因として、バージョンカラム更新ロジックに不備が見つかりました。この不備により、複数のプロセスが同時にデータ更新を試みる際に、競合が発生しやすくなり、結果として更新失敗が増加しました。これにより顧客サービスへの影響が生じており、迅速な対策が必要です。', '本件インシデントの調査を実施しました。楽観ロック競合が多発している原因として、バージョンカラム更新ロジックに不備が見つかりました。この不備により、複数のプロセスが同時にデータ更新を試みる際に、競合が発生しやすくなり、結果として更新失敗が増加しました。これにより顧客サービスへの影響が生じており、迅速な対策が必要です。', TIMESTAMP WITH TIME ZONE '2025-10-17T11:16:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00819', 'INC-2025-00552', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-10-16T11:31:13+09:00', TIMESTAMP WITH TIME ZONE '2025-10-16T12:31:13+09:00', '初期対応ログ', '2025年10月16日09時20分に、営業部の花子が顧客「架空服飾店A」からの問い合わせを受け、棚卸突合失敗の事象を確認しました。直ちに技術チームにエスカレーションし、調査を開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00820', 'INC-2025-00552', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-10-16T13:01:13+09:00', TIMESTAMP WITH TIME ZONE '2025-10-16T14:01:13+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00559', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-12-04T07:39:09+09:00', TIMESTAMP WITH TIME ZONE '2025-12-04T08:24:09+09:00', '【障害報告】【CLU-10】ヘルスチェック過負荷', '2025年12月4日07時39分、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aおよび架空食品店Bに影響を及ぼすストレージ溢れが発生しました。発見者は運用部の運用 一郎です。問題の症状は、ヘルスチェック過多でAPサーバーの負荷が増加していることです。これは、インフラメンテナンス明けにLBヘルスチェック間隔の過短設定が原因と考えられています。全テナントに波及する影響があり、エラーコードはMON-06-00559です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00559', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00559', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00559', 'INC-2025-00559', 'ヘルスチェックの設定を確認したところ、LBのヘルスチェック間隔が通常より短く設定されていることが判明しました。この設定変更が原因で、同時に多数のヘルスチェックが発生し、APサーバーの負荷が増加したと考えられます。インフラメンテナンスの影響で設定が変わった可能性が高く、今後の管理に注意が必要です。', 'ヘルスチェックの設定を確認したところ、LBのヘルスチェック間隔が通常より短く設定されていることが判明しました。この設定変更が原因で、同時に多数のヘルスチェックが発生し、APサーバーの負荷が増加したと考えられます。インフラメンテナンスの影響で設定が変わった可能性が高く、今後の管理に注意が必要です。', TIMESTAMP WITH TIME ZONE '2025-12-05T08:24:09+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00827', 'INC-2025-00559', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-04T08:39:09+09:00', TIMESTAMP WITH TIME ZONE '2025-12-04T09:39:09+09:00', '【初期対応】【CLU-10】ヘルスチェック過負荷', '運用 一郎です。現在、ヘルスチェックの過負荷に関する問題を確認しています。APサーバーの負荷を軽減するために、LBのヘルスチェック間隔を適切な設定に戻す作業を行います。全テナントに影響が及んでいるため、迅速に対応します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00828', 'INC-2025-00559', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-12-04T10:09:09+09:00', TIMESTAMP WITH TIME ZONE '2025-12-04T11:09:09+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00570', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-03-18T20:15:52+09:00', TIMESTAMP WITH TIME ZONE '2025-03-18T21:00:52+09:00', '【障害報告】【監視・可用性障害】死活監視誤検知', '2025年3月18日20時15分52秒に発生したストレージ溢れに関する障害報告です。株式会社ストッククラウドのVenusサービスにて、Mercury AWS Storageにおいて死活監視が正常系をDOWNと誤検知しました。この問題は運用部門にのみ影響を及ぼしました。定例リリース直後に発生し、監視プローブのUser-Agentがブロックされたことが原因と推定されます。検知は20時57分52秒に行われ、発見者は運用部の運用 一郎です。今後、関連コンポーネントの監視・可用性障害に関して更なる調査が必要です。', 'Mercury AWS Storage', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00570', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00570', 'INC-2025-00570', '死活監視が正常系をDOWNと誤検知した原因として、監視プローブのUser-Agentブロックが疑われます。定例リリース直後にこの問題が発生したため、リリース内容との関連性を含めて調査を進めています。運用部門への影響が限定的ではありますが、再発防止策の検討が急務であり、詳細な技術的分析を行う必要があります。', '死活監視が正常系をDOWNと誤検知した原因として、監視プローブのUser-Agentブロックが疑われます。定例リリース直後にこの問題が発生したため、リリース内容との関連性を含めて調査を進めています。運用部門への影響が限定的ではありますが、再発防止策の検討が急務であり、詳細な技術的分析を行う必要があります。', TIMESTAMP WITH TIME ZONE '2025-03-19T21:00:52+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00843', 'INC-2025-00570', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-18T21:15:52+09:00', NULL, '【初回対応】【監視・可用性障害】死活監視誤検知', '今回の死活監視誤検知に対し、運用部門が初回の対応を行いました。監視プローブの設定を確認し、User-Agentブロックの原因を特定するための調査を開始しました。定例リリースの内容も再確認し、今後の影響を最小限に抑えるための対策を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00583', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-10-14T07:24:05+09:00', TIMESTAMP WITH TIME ZONE '2025-10-14T07:39:05+09:00', '【障害報告】【運用操作・権限障害】手動設定編集事故', '2025年10月14日07:24に、株式会社ストッククラウドのVenusにおいて、架空服飾店Aからのアクセス障害が発生。運用コンソールにて設定ファイルが手動編集され、必須キーが欠落していたことが確認された。これにより、サービス全体の一部機能に影響が及んだ。運用部の運用 一郎によって発見され、07:34に検知された。発生契機として、インフラメンテナンス明けに実施された作業が関連していると考えられる。該当エラーコードはOPS-07-00583である。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00583', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00583', 'INC-2025-00583', '設定ファイルの手動編集が行われた結果、必須キーが欠落したことが確認された。インフラメンテナンス明けの作業において、編集ミスが原因と推定されている。影響範囲は、運用コンソールおよび設定管理DBに及び、サービス全体の一部機能が利用不可となった。現状、原因を特定するための詳細なログ解析が進行中である。', '設定ファイルの手動編集が行われた結果、必須キーが欠落したことが確認された。インフラメンテナンス明けの作業において、編集ミスが原因と推定されている。影響範囲は、運用コンソールおよび設定管理DBに及び、サービス全体の一部機能が利用不可となった。現状、原因を特定するための詳細なログ解析が進行中である。', TIMESTAMP WITH TIME ZONE '2025-10-15T07:39:05+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00862', 'INC-2025-00583', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-10-14T07:54:05+09:00', TIMESTAMP WITH TIME ZONE '2025-10-14T08:54:05+09:00', '【初期対応】【運用操作・権限障害】手動設定編集事故', 'この障害に対する初期対応として、運用部は直ちに設定ファイルの確認作業を開始した。手動編集を行った運用担当者に対してヒアリングを行い、状況の把握に努めた。必要に応じてバックアップからのリストアを検討し、影響を最小限に抑える措置が講じられた。また、今後の運用において同様の事故を防ぐため、手動操作のルールを見直す必要がある。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00863', 'INC-2025-00583', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-10-14T09:24:05+09:00', TIMESTAMP WITH TIME ZONE '2025-10-14T10:24:05+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00592', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-11-18T12:46:22+09:00', TIMESTAMP WITH TIME ZONE '2025-11-18T14:46:22+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2025年11月18日、架空食品店Bにて発生した棚卸突合失敗の事象について報告いたします。発生時刻は12時46分で、顧客店舗POSでのスナップショット復元後に在庫整合が崩れる症状が確認されました。影響範囲は全テナントに波及しており、データ移行バッチ実行中に発生したことが推定されます。エラーコードはSYNC-09-00592であり、原因として復元ポイントのトランザクションログ欠落が疑われます。検知は14時21分に行われ、検知まで95分を要しました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00592', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00592', 'INC-2025-00592', '本障害の調査を行った結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れる現象が発生していることを確認しました。原因として、復元ポイントのトランザクションログ欠落が影響している可能性が高いです。この問題は、データ同期・整合性に関わる重要なものであり、全テナントに影響を及ぼすため、迅速な対応が求められます。', '本障害の調査を行った結果、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れる現象が発生していることを確認しました。原因として、復元ポイントのトランザクションログ欠落が影響している可能性が高いです。この問題は、データ同期・整合性に関わる重要なものであり、全テナントに影響を及ぼすため、迅速な対応が求められます。', TIMESTAMP WITH TIME ZONE '2025-11-19T14:46:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00877', 'INC-2025-00592', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-11-18T15:01:22+09:00', TIMESTAMP WITH TIME ZONE '2025-11-18T16:01:22+09:00', '【初期対応】【データ同期・整合性障害】', '初期対応として、復元ポイントのトランザクションログの確認作業を実施しました。また、顧客店舗POSのデータ整合性を確保するための暫定的な対策を講じました。さらなる詳細な調査を行い、根本原因の特定と再発防止策を検討する必要があります。今後の進捗については、随時報告いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00599', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-03-21T12:55:29+09:00', TIMESTAMP WITH TIME ZONE '2025-03-21T13:25:29+09:00', '【障害報告】【データ同期・整合性障害】分散トランザクションタイムアウト', '2025年3月21日12時55分29秒、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店A及び架空食品店Bに対し、マスター設定ミスによる在庫登録失敗が発生しました。この障害は、分散トランザクションがタイムアウトし片側のみコミットされたことが症状として現れました。発見者は運用部の運用 一郎であり、検知は13時20分29秒に行われました。発生の契機は、大規模なセール開始直前における設定ミスであり、全テナントに波及する影響がありました。エラーコードはSYNC-04-00599です。今回の障害は、2PCタイムアウト設定の過短が推定原因として考えられます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00599', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00599', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00599', 'INC-2025-00599', '本件の調査において、分散トランザクションがタイムアウトし片側のみコミットされる現象が確認されました。特に、2PCタイムアウト設定が過短であったことが影響していることが明らかになりました。これにより、在庫登録が正常に行われず、顧客に対する影響が生じたことが分かりました。今後は、タイムアウト設定の見直しと、設定変更時の影響範囲の確認を徹底する必要があります。', '本件の調査において、分散トランザクションがタイムアウトし片側のみコミットされる現象が確認されました。特に、2PCタイムアウト設定が過短であったことが影響していることが明らかになりました。これにより、在庫登録が正常に行われず、顧客に対する影響が生じたことが分かりました。今後は、タイムアウト設定の見直しと、設定変更時の影響範囲の確認を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2025-03-22T13:25:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00887', 'INC-2025-00599', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-21T13:40:29+09:00', TIMESTAMP WITH TIME ZONE '2025-03-21T14:40:29+09:00', '初期対応ログ', 'インシデント発生後、運用 一郎が即座に対応を開始し、影響を受けた顧客に対して情報提供を行いました。具体的には、適切な設定変更を行うとともに、影響を受けた在庫情報の手動修正を行いました。顧客への影響を最小限に抑えるため、迅速な情報共有と対応が求められました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00612', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-01-12T18:27:15+09:00', TIMESTAMP WITH TIME ZONE '2025-01-12T20:27:15+09:00', '【障害報告】【棚卸・POS突合障害】月次突合不一致', '2025年1月12日18時27分に、株式会社ストッククラウドのサービスVenusにおいて、顧客「架空服飾店A」の店舗POSにおける月次突合が失敗し、月次突合レポートの合計が帳票と不一致となる事象が発生しました。この現象は、月末棚卸の開始時に発生しており、影響範囲は同一顧客の全店舗に及びます。発見者は営業部の花子であり、検知は2025年1月12日20時29分に行われました。推定される原因として、返品データの符号反転漏れが考えられます。この事象により、顧客には大きな影響を及ぼす可能性があるため、速やかな対応が必要です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00612', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00612', 'INC-2025-00612', '本障害に関する調査を行った結果、月末棚卸の開始時に月次突合レポートの合計が帳票と不一致となっていることが確認されました。原因は返品データの符号反転漏れとされており、全店舗で同様の事象が再現される可能性があります。今後、詳細な原因分析を進め、適切な対策を講じる必要があります。', '本障害に関する調査を行った結果、月末棚卸の開始時に月次突合レポートの合計が帳票と不一致となっていることが確認されました。原因は返品データの符号反転漏れとされており、全店舗で同様の事象が再現される可能性があります。今後、詳細な原因分析を進め、適切な対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-13T20:27:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00906', 'INC-2025-00612', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-12T20:42:15+09:00', TIMESTAMP WITH TIME ZONE '2025-01-12T21:42:15+09:00', '初期対応', '本件について初期対応を実施しました。まず、顧客「架空服飾店A」の全店舗に事象の影響について通知を行い、影響範囲を確認しました。同時に、返品データの符号反転漏れに関する詳細な調査を開始し、必要な修正を行う準備を進めています。今後も情報が得られ次第、随時顧客へ報告を行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00614', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-02-22T02:05:01+09:00', TIMESTAMP WITH TIME ZONE '2025-02-22T04:05:01+09:00', '【障害報告】【棚卸・POS突合障害】棚卸実地差異', '2025年2月22日02時05分に発生した棚卸突合失敗のインシデントについて報告いたします。本事象では、実地棚卸数とシステム在庫が大幅に乖離するという症状が確認されました。影響範囲は同一顧客の全店舗に及び、主に顧客店舗POSにおいて問題が発生しております。原因としては、棚卸スナップショット時刻のずれが推定されており、月末棚卸の開始時にこの問題が顕在化しました。発見者は営業部の花子であり、検知は2025年2月22日04時42分に行われ、発生から157分後のことでした。エラーコードはINV-01-00614です。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00614', 'INC-2025-00614', '現在、棚卸・POS突合障害の原因を特定するための詳細な調査を行っております。実地棚卸数とシステム在庫の乖離が生じた原因としては、棚卸スナップショット時刻のずれが疑われます。この問題により、全店舗での棚卸実施に影響が出ているため、迅速な対応が求められます。さらに、顧客店舗POSにおけるエンジンの動作状況も合わせて確認中です。', '現在、棚卸・POS突合障害の原因を特定するための詳細な調査を行っております。実地棚卸数とシステム在庫の乖離が生じた原因としては、棚卸スナップショット時刻のずれが疑われます。この問題により、全店舗での棚卸実施に影響が出ているため、迅速な対応が求められます。さらに、顧客店舗POSにおけるエンジンの動作状況も合わせて確認中です。', TIMESTAMP WITH TIME ZONE '2025-02-23T04:05:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00908', 'INC-2025-00614', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-02-22T04:20:01+09:00', TIMESTAMP WITH TIME ZONE '2025-02-22T05:20:01+09:00', '初期対応', 'インシデント発生直後に、影響を受けた全店舗に対して棚卸作業の一時停止を指示しました。また、営業部の花子が状況を把握し、関係部署との連携を強化するための会議を設定しました。次に、システムエンジニアと協力してスナップショット時刻の確認作業を開始し、影響範囲の把握に努めています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00618', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-06-26T05:19:00+09:00', TIMESTAMP WITH TIME ZONE '2025-06-26T06:04:00+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2025年6月26日05時19分、株式会社ストッククラウドのMercuryにおいてストレージ溢れのインシデントが発生しました。発生個所はMercury AWS Storageであり、運用部の運用 一郎がこの事象を検知しました。検知は05時19分から45分後の06時04分に行われました。発生契機としては大規模セールの開始直前であったため、システムの負荷が高まっていました。このインシデントにより、同一アラートが短時間に数百件発報し、アラート疲労が発生しました。運用部門に影響が及び、アラート抑制ルールの未設定が原因と推定されております。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00618', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00618', 'INC-2025-00618', 'インシデント発生後、運用部はシステムの状態を調査し、短時間に数百件の同一アラートが発報された原因を探りました。大規模セール開始直前のため、システムが高負荷状態にあったことが確認されました。また、アラート抑制ルールが未設定であったことが主な原因として浮かび上がりました。これにより、監視システムの効果的な運用ができず、運用部門に深刻な影響が出る結果となりました。', 'インシデント発生後、運用部はシステムの状態を調査し、短時間に数百件の同一アラートが発報された原因を探りました。大規模セール開始直前のため、システムが高負荷状態にあったことが確認されました。また、アラート抑制ルールが未設定であったことが主な原因として浮かび上がりました。これにより、監視システムの効果的な運用ができず、運用部門に深刻な影響が出る結果となりました。', TIMESTAMP WITH TIME ZONE '2025-06-27T06:04:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00914', 'INC-2025-00618', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-06-26T06:19:00+09:00', TIMESTAMP WITH TIME ZONE '2025-06-26T07:19:00+09:00', '【初動対応】【監視・可用性障害】アラート疲労', '運用部はアラート発報後すぐにシステムのモニタリングを強化し、問題の特定に向けてアクションを開始しました。まず、発報したアラートの内容を確認し、同一アラートが短時間に発生している事実を確認しました。その後、アラート抑制ルールが未設定であったことが原因であると特定し、迅速にルールの設定を行うことを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00621', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-01-01T06:46:31+09:00', TIMESTAMP WITH TIME ZONE '2025-01-01T07:16:31+09:00', '【障害報告】【在庫マスター設定障害】セット商品分解失敗', '2025年1月1日06時46分31秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bに関連するセット商品の在庫分解時に構成エラーが発生しました。エラーコードはMST-07-00621です。本事象は、定例リリース直後に発生し、BOM構成テーブルの親子関係不整合が原因として推定されます。影響範囲は同一顧客の全店舗に及び、Mercury AWS AP（ゾーンA）および在庫計算エンジンに影響を与えました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00621', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00621', 'INC-2025-00621', '本障害についての調査を実施した結果、定例リリース直後に発生したことが確認されました。構成エラーが発生した原因として、BOM構成テーブルの親子関係の不整合が特定されました。この問題により、在庫分解処理が正常に完了できなかったことが明らかとなっており、今後の対策としては、BOM構成テーブルの整合性を向上させることが必要です。', '本障害についての調査を実施した結果、定例リリース直後に発生したことが確認されました。構成エラーが発生した原因として、BOM構成テーブルの親子関係の不整合が特定されました。この問題により、在庫分解処理が正常に完了できなかったことが明らかとなっており、今後の対策としては、BOM構成テーブルの整合性を向上させることが必要です。', TIMESTAMP WITH TIME ZONE '2025-01-02T07:16:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00919', 'INC-2025-00621', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-01T07:31:31+09:00', TIMESTAMP WITH TIME ZONE '2025-01-01T08:31:31+09:00', '【初期対応】エラー発生時の対応', 'エラー発生後、運用部の運用 一郎が即座に状況を確認し、影響範囲の特定を行いました。架空食品店Bにおける全店舗での在庫分解エラーが確認され、BOM構成テーブルの確認と修正を迅速に進めることが決定されました。また、顧客への報告も行い、影響を最小限に抑えるための措置を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00626', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-03-07T10:37:24+09:00', TIMESTAMP WITH TIME ZONE '2025-03-07T11:07:24+09:00', '【障害報告】【データ同期・整合性障害】楽観ロック競合多発', '2025年3月7日10時37分、株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aに対する在庫登録が失敗しました。発見者は運用部の運用 一郎で、検知は11時01分に行われました。症状として、楽観ロック競合が多発し更新失敗率が上昇しており、全テナントに波及する影響範囲が確認されています。発生契機は大規模セール開始直前であり、エラーコードはSYNC-10-00626です。影響コンポーネントはMercury AWS AP（DRサイト）および在庫登録APIであり、この問題はデータ同期・整合性に関わる深刻な障害です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00626', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00626', 'INC-2025-00626', '調査の結果、大規模セール開始直前に発生した楽観ロック競合が原因で更新失敗率が上昇していることが確認されました。バージョンカラム更新ロジックの不備が根本的な原因と考えられ、修正が必要です。この問題は全テナントに影響を与えるため、早急な対応が求められます。今後の対策として、バージョン管理の見直しやロック機構の改善が必要です。', '調査の結果、大規模セール開始直前に発生した楽観ロック競合が原因で更新失敗率が上昇していることが確認されました。バージョンカラム更新ロジックの不備が根本的な原因と考えられ、修正が必要です。この問題は全テナントに影響を与えるため、早急な対応が求められます。今後の対策として、バージョン管理の見直しやロック機構の改善が必要です。', TIMESTAMP WITH TIME ZONE '2025-03-08T11:07:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00925', 'INC-2025-00626', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-07T11:22:24+09:00', TIMESTAMP WITH TIME ZONE '2025-03-07T12:22:24+09:00', '【初期対応】【データ同期・整合性障害】楽観ロック競合多発', 'インシデントが検知された後、運用部は即座に問題の調査を開始しました。楽観ロック競合の多発が確認され、影響範囲を特定するためにテナントへの問い合わせを行いました。バージョンカラム更新ロジックの不備が疑われるため、開発チームと連携し、修正案の検討を進めています。全テナントに影響が及んでいるため、迅速な対応が必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00648', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-01-21T09:04:51+09:00', TIMESTAMP WITH TIME ZONE '2025-01-21T11:04:51+09:00', '【障害報告】【棚卸・POS突合障害】移動平均単価異常', '2025年1月21日09時04分51秒に、株式会社ストッククラウドのサービスVenusにおいて、棚卸後の評価単価が想定外の値になるという事象が発生しました。この障害は、顧客店舗POSにおいて検知され、発見者は営業部の花子です。定例リリース直後の発生であり、移動平均計算式の適用期間に誤りがあったと推定されます。影響はサービス全体の一部機能に及び、エラーコードはINV-07-00648です。これにより、棚卸・POS突合に関連する業務が影響を受けました。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00648', 'INC-2025-00648', '調査の結果、移動平均計算式の適用期間に誤りがあったことが確認されました。具体的には、定例リリース直後に新たに適用された計算式が、従来の期間設定とは異なり、意図した評価単価を生成しませんでした。このため、棚卸後の評価単価が想定外の値となり、顧客店舗POSにおいて異常が発生しました。今後は、リリース前のテストで移動平均計算の検証を強化する必要があります。', '調査の結果、移動平均計算式の適用期間に誤りがあったことが確認されました。具体的には、定例リリース直後に新たに適用された計算式が、従来の期間設定とは異なり、意図した評価単価を生成しませんでした。このため、棚卸後の評価単価が想定外の値となり、顧客店舗POSにおいて異常が発生しました。今後は、リリース前のテストで移動平均計算の検証を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-22T11:04:51+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00958', 'INC-2025-00648', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-21T11:19:51+09:00', TIMESTAMP WITH TIME ZONE '2025-01-21T12:19:51+09:00', '【初期対応】【棚卸・POS突合障害】移動平均単価異常への初期対応', 'インシデント発生後、迅速に影響範囲の特定を行いました。営業部の花子が顧客店舗POSでの異常を確認し、技術部門に連絡しました。技術部門では、移動平均計算式の適用期間を確認し、修正を行う準備を進めました。顧客への影響を最小限に抑えるため、障害の詳細な状況を把握し、適切な対応策を講じることが求められました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00661', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-02-21T20:57:42+09:00', TIMESTAMP WITH TIME ZONE '2025-02-21T21:27:42+09:00', '【障害報告】【在庫マスター設定障害】SKU登録HTTP500', '2025年2月21日20時57分42秒、株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aに対しSKU登録APIがHTTP 500を返す事象が発生しました。この障害により在庫反映に失敗し、単一店舗の登録機能に影響を及ぼしました。定例リリース直後の発生であり、推定される原因は単位換算係数の設定漏れです。影響範囲は限られているものの、在庫マスター設定に関する重要な障害であるため、迅速な対応が求められます。エラーコードはMST-01-00661です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00661', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00661', 'INC-2025-00661', '本件に関する調査を実施した結果、定例リリース直後に発生したSKU登録APIのHTTP 500エラーは、単位換算係数の設定漏れが原因であると確認されました。この設定ミスにより、在庫登録の際に必要な情報が不足し、APIが正常に処理できなかったことが判明しました。今後は、設定チェックの徹底を図り、再発防止策を講じる必要があります。', '本件に関する調査を実施した結果、定例リリース直後に発生したSKU登録APIのHTTP 500エラーは、単位換算係数の設定漏れが原因であると確認されました。この設定ミスにより、在庫登録の際に必要な情報が不足し、APIが正常に処理できなかったことが判明しました。今後は、設定チェックの徹底を図り、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-02-22T21:27:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00977', 'INC-2025-00661', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-02-21T21:42:42+09:00', TIMESTAMP WITH TIME ZONE '2025-02-21T22:42:42+09:00', '【初期対応】【在庫マスター設定障害】対応ログ', '運用部の運用 一郎が本障害を確認し、システムの状況を把握するためにログの解析を開始しました。影響を受けた架空服飾店Aの在庫登録状況を確認し、必要な修正を行うための手順を検討しています。また、定例リリースの内容を見直し、再発防止に向けた対策を検討中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00663', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-09-21T04:17:50+09:00', TIMESTAMP WITH TIME ZONE '2025-09-21T05:17:50+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2025年09月21日04時17分に発生した株式会社ストッククラウドのVenusサービスに関する顧客側ネットワーク障害について報告します。本事象では、顧客固定IP変更が許可リストに未反映であり、影響範囲は単一店舗のみです。発生契機は顧客オンボーディング当日で、エラーコードはNW-07-00663です。この障害は、2025年09月21日05時18分に検知され、検知まで61分を要しました。技術詳細としては、顧客オンボーディング当日に顧客固定IP変更が許可リストに未反映となったことが挙げられ、原因としてIP許可リストの更新漏れが疑われます。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00663', 'INC-2025-00663', '本障害の調査を行った結果、顧客固定IP変更が許可リストに未反映であることが確認されました。これにより、顧客側ネットワークが正常に機能しておらず、原因としてIP許可リストの更新漏れと推定されます。影響を受けたのは単一店舗であり、迅速な対応が求められます。今後、オンボーディング時の確認プロセスを見直す必要があります。', '本障害の調査を行った結果、顧客固定IP変更が許可リストに未反映であることが確認されました。これにより、顧客側ネットワークが正常に機能しておらず、原因としてIP許可リストの更新漏れと推定されます。影響を受けたのは単一店舗であり、迅速な対応が求められます。今後、オンボーディング時の確認プロセスを見直す必要があります。', TIMESTAMP WITH TIME ZONE '2025-09-22T05:17:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00979', 'INC-2025-00663', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-21T05:32:50+09:00', TIMESTAMP WITH TIME ZONE '2025-09-21T06:32:50+09:00', '【初期対応】【顧客ネットワーク障害】固定IP変更未連絡', '営業部の花子です。本件について、顧客固定IP変更の許可リスト未反映を確認しました。このため、顧客拠点NW（DRサイト）及び顧客側FWに影響が出ております。迅速に対応し、IP許可リストの更新を行います。今後同様の事象が発生しないよう、顧客オンボーディング時の確認体制の強化を図ります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00980', 'INC-2025-00663', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-09-21T07:02:50+09:00', TIMESTAMP WITH TIME ZONE '2025-09-21T08:02:50+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00673', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2025-01-09T23:21:59+09:00', TIMESTAMP WITH TIME ZONE '2025-01-10T00:21:59+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2025年1月9日23時21分59秒、株式会社ストッククラウドの顧客である架空食品店Aにおいて、顧客拠点NWにて特定拠点のみAPI呼び出しが失敗する事象が発生しました。発見者は営業部の花子であり、初回の検知は2025年1月10日0時22分59秒でした。この障害の発生は新規店舗追加の初日に起こり、単一店舗のみが影響を受けました。推定原因は店舗LANのスイッチ故障であり、顧客側FWにも影響を及ぼす可能性があります。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00673', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00673', 'INC-2025-00673', '本障害について調査を行った結果、特定拠点のLAN環境に問題がある可能性が高いと判断されました。具体的には、店舗LANのスイッチ故障が原因でAPI呼び出しが失敗していると推測されます。顧客ネットワークの監視データを確認したところ、故障の発生時刻に通信異常が記録されていることが確認されました。今後の対応としては、スイッチの再起動および交換を検討する必要があります。', '本障害について調査を行った結果、特定拠点のLAN環境に問題がある可能性が高いと判断されました。具体的には、店舗LANのスイッチ故障が原因でAPI呼び出しが失敗していると推測されます。顧客ネットワークの監視データを確認したところ、故障の発生時刻に通信異常が記録されていることが確認されました。今後の対応としては、スイッチの再起動および交換を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2025-01-11T00:21:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00995', 'INC-2025-00673', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-10T00:36:59+09:00', TIMESTAMP WITH TIME ZONE '2025-01-10T01:36:59+09:00', '【初動対応】【顧客ネットワーク障害】拠点限定API失敗', '2025年1月10日、初動対応として架空食品店Aの営業担当である花子が、顧客拠点NWの状況を確認しました。API呼び出しの失敗が継続していることが確認され、LAN環境のチェックを優先的に行うことが決定されました。顧客に対しては、障害の発生状況を報告し、必要な対応を進める旨を伝達しました。スイッチの状態を確認するため、保守担当者への連絡を行いました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00996', 'INC-2025-00673', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-01-10T02:06:59+09:00', TIMESTAMP WITH TIME ZONE '2025-01-10T03:06:59+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
