INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00706', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-01-09T20:00:15+09:00', TIMESTAMP WITH TIME ZONE '2025-01-09T20:30:15+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2025年1月9日20時00分頃、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店AでCookie SameSite設定により埋込画面が認証不可になる事象が発生しました。発見者は運用部の運用 一郎です。当該事象は定例リリース直後に確認され、影響範囲は単一店舗のみとなります。エラーコードはAUTH-06-00706です。技術的な詳細としては、定例リリース後にCookie SameSite設定が変更され、その結果、認証ができなくなったと考えられます。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00706', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00706', 'INC-2025-00706', '運用部の運用 一郎による初期調査の結果、定例リリースにおいてCookieのSameSite属性が変更されたことが影響していると特定されました。埋込画面の認証に失敗する原因としてこの設定変更が大きく関与しています。さらに、影響を受けるコンポーネントはVenus Azure APおよびセッションストアです。現在、同様の設定変更が他の店舗に及ぶかどうかを引き続き調査中です。', '運用部の運用 一郎による初期調査の結果、定例リリースにおいてCookieのSameSite属性が変更されたことが影響していると特定されました。埋込画面の認証に失敗する原因としてこの設定変更が大きく関与しています。さらに、影響を受けるコンポーネントはVenus Azure APおよびセッションストアです。現在、同様の設定変更が他の店舗に及ぶかどうかを引き続き調査中です。', TIMESTAMP WITH TIME ZONE '2025-01-10T20:30:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01047', 'INC-2025-00706', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-01-09T20:45:15+09:00', TIMESTAMP WITH TIME ZONE '2025-01-09T21:45:15+09:00', '初期対応', '運用部の運用 一郎からの報告を受け、直ちに技術チームに連絡し、Cookie SameSite設定の確認を行いました。また、影響を受けた架空食品店Aに対しては、状況を説明し、暫定的な対応策を提案しました。技術チームは設定の見直しを行い、問題解決に向けた手順を策定中です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00719', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2025-09-07T15:46:25+09:00', TIMESTAMP WITH TIME ZONE '2025-09-07T16:16:25+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2025年9月7日15時46分に、株式会社ストッククラウドのサービスMercuryにおいて、顧客「架空食品店B」に対し、マスター設定ミスによる在庫登録失敗が発生いたしました。具体的には、OAuthトークン失効によりPOS連携が中断し、顧客の店舗での業務に影響が出ております。この事象は、年末年始の稼働切替時に発生しており、リフレッシュトークン保存先の障害が原因と考えられます。影響範囲は単一店舗のみであり、エラーコードはEDI-05-00719です。問題の発見は16時30分であり、検知から44分後のことです。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00719', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00719', 'INC-2025-00719', '本事象の調査を進めた結果、OAuthトークン失効が確認されました。リフレッシュトークン保存先に障害が生じたため、POS連携が中断してしまったものと推測されます。システムログを元に調査を行ったところ、年末年始の稼働切替時に関連する設定が適切に行われていないことが明らかになりました。今後、再発防止のための対策を講じる必要があります。', '本事象の調査を進めた結果、OAuthトークン失効が確認されました。リフレッシュトークン保存先に障害が生じたため、POS連携が中断してしまったものと推測されます。システムログを元に調査を行ったところ、年末年始の稼働切替時に関連する設定が適切に行われていないことが明らかになりました。今後、再発防止のための対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2025-09-08T16:16:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01063', 'INC-2025-00719', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-09-07T16:31:25+09:00', TIMESTAMP WITH TIME ZONE '2025-09-07T17:31:25+09:00', '【対応】【CLU-07】OAuthトークン失効', '運用部の運用一郎が本事象の報告を受け、直ちに調査を開始いたしました。初期調査の結果、OAuthトークンの失効が原因でPOS連携が中断していることを確認しました。リフレッシュトークンの保存先に障害が発生したものと考えられます。顧客「架空食品店B」に対し、影響を最小限に抑えるための対応を迅速に行うことが求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00724', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2025-03-21T17:26:25+09:00', TIMESTAMP WITH TIME ZONE '2025-03-21T18:11:25+09:00', '【障害報告】【監視・可用性障害】可用性レポート誤集計', '2025年3月21日17時26分25秒、株式会社ストッククラウドのサービスMercuryにおいて、ストレージ溢れの障害が発生しました。この障害により、月次可用性レポートが実績より高く表示される事象が確認されました。エラーコードはMON-10-00724です。月末棚卸の開始時に発生し、運用部門のみが影響を受けました。原因としては、メンテナンス除外時間の二重計上が疑われています。検知には約36分を要し、18時02分25秒に発見されました。この問題はMercury AWS Storageに関連し、可用性レポートに影響を及ぼしました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00724', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00724', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00724', 'INC-2025-00724', '調査の結果、月末棚卸の開始時に月次可用性レポートが実績より高く表示されるという問題が発生しました。原因は、メンテナンス除外時間を二重に計上していたことに起因しています。このため、運用部門では誤った可用性レポートが生成され、システムの信頼性に影響を及ぼしました。再発防止策として、メンテナンス時間の取り扱いの見直しが求められます。また、監視体制の強化も必要です。', '調査の結果、月末棚卸の開始時に月次可用性レポートが実績より高く表示されるという問題が発生しました。原因は、メンテナンス除外時間を二重に計上していたことに起因しています。このため、運用部門では誤った可用性レポートが生成され、システムの信頼性に影響を及ぼしました。再発防止策として、メンテナンス時間の取り扱いの見直しが求められます。また、監視体制の強化も必要です。', TIMESTAMP WITH TIME ZONE '2025-03-22T18:11:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01071', 'INC-2025-00724', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-21T18:26:25+09:00', TIMESTAMP WITH TIME ZONE '2025-03-21T19:26:25+09:00', '【障害対応】初期対応レポート', '障害発生直後、運用部の運用 一郎が直ちにモニタリングを行い、可用性レポートの誤集計が発生していることを確認しました。その後、システムの状態を検証し、エラーコードMON-10-00724に基づいて迅速な初期対応を実施しました。運用部は問題の原因を特定し、必要な修正を行うために関連部門に連絡を取りました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00726', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-03-27T09:44:12+09:00', TIMESTAMP WITH TIME ZONE '2025-03-27T10:14:12+09:00', '【障害報告】【認証・セッション障害】リフレッシュトークン再利用', '2025年3月27日09時44分、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店B及び架空食品店Aでリフレッシュトークン再利用検知が発生し、全端末がログアウトしました。この事象は年末年始の稼働切替時に発生し、同一顧客の全店舗に影響を及ぼしました。推定される原因はトークンローテーション実装の不備であり、リフレッシュトークンの取り扱いに問題があったと考えられます。今回の障害を受けて、今後のトークン管理の強化が必要です。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00726', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00726', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00726', 'INC-2025-00726', '本件は2025年3月27日に発生し、検知まで29分の遅延がありました。運用部の運用 一郎が検知を行い、影響範囲は架空食品店Bと架空食品店Aの全店舗でした。調査の結果、リフレッシュトークンの再利用が確認され、これはトークンローテーション実装における不備に起因するものと特定しました。今後の対策として、実装の見直しとログアウト時のユーザーへの通知機能の実装が必要です。', '本件は2025年3月27日に発生し、検知まで29分の遅延がありました。運用部の運用 一郎が検知を行い、影響範囲は架空食品店Bと架空食品店Aの全店舗でした。調査の結果、リフレッシュトークンの再利用が確認され、これはトークンローテーション実装における不備に起因するものと特定しました。今後の対策として、実装の見直しとログアウト時のユーザーへの通知機能の実装が必要です。', TIMESTAMP WITH TIME ZONE '2025-03-28T10:14:12+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01073', 'INC-2025-00726', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-27T10:29:12+09:00', TIMESTAMP WITH TIME ZONE '2025-03-27T11:29:12+09:00', '【初期対応】【認証・セッション障害】リフレッシュトークン再利用', '初期対応として、影響を受けた全顧客に対し、障害発生の通知を行い、リフレッシュトークンの無効化を実施しました。運用部の担当者が即時に状況を把握し、影響範囲を特定して、各店舗と連携を取りました。また、ログアウトに伴う顧客への影響を最小限に抑えるため、サポート体制を強化し、障害に関するFAQを作成して配布しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01074', 'INC-2025-00726', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-03-27T11:59:12+09:00', TIMESTAMP WITH TIME ZONE '2025-03-27T12:59:12+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00751', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-06-23T21:52:30+09:00', TIMESTAMP WITH TIME ZONE '2025-06-23T23:52:30+09:00', '【障害報告】【CLU-07】Webhook再送嵐', '2025年6月23日21時52分30秒に、株式会社ストッククラウドのサービスMercuryにて、架空食品店Aにおいて棚卸突合失敗が発生。顧客店舗POSでのWebhook再送が嵐状になり、先方で拒否される事象が確認された。定例リリース直後に発生し、影響範囲は単一店舗のみに限定されました。エラーコードはEDI-02-00751です。原因として、再送間隔の指数バックオフ未設定が考えられる。検知は2025年6月24日01時20分30秒に行われ、検知までに208分を要した。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00751', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00751', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00751', 'INC-2025-00751', '調査の結果、Webhook再送が嵐状になり先方で拒否されている状況が確認された。これは、定例リリース直後に発生した事象であり、再送間隔の指数バックオフが未設定であったことが推定される。顧客店舗POSのWebhookディスパッチャにおいて、API連携・EDIに関連する問題が生じている。', '調査の結果、Webhook再送が嵐状になり先方で拒否されている状況が確認された。これは、定例リリース直後に発生した事象であり、再送間隔の指数バックオフが未設定であったことが推定される。顧客店舗POSのWebhookディスパッチャにおいて、API連携・EDIに関連する問題が生じている。', TIMESTAMP WITH TIME ZONE '2025-06-24T23:52:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01112', 'INC-2025-00751', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-06-24T00:07:30+09:00', TIMESTAMP WITH TIME ZONE '2025-06-24T01:07:30+09:00', '初期対応ログ', '初期対応として、問題の再現を試み、Webhookの設定や再送間隔についての確認を行った。現状では再送の閾値や条件設定に問題があることが明らかとなった。今後は迅速にバックオフの設定を行い、再発防止に努める。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01113', 'INC-2025-00751', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-06-24T01:37:30+09:00', TIMESTAMP WITH TIME ZONE '2025-06-24T02:37:30+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00758', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2025-10-21T02:21:59+09:00', TIMESTAMP WITH TIME ZONE '2025-10-21T02:51:59+09:00', '【障害報告】【監視・可用性障害】メトリクス欠損', '2025年10月21日02時21分59秒に株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aに対する応答遅延が発生しました。運用部の運用 一郎が発見した記録によると、主要メトリクス系列が15分間欠損しており、これはインフラメンテナンス明けの影響と考えられます。エラーコードはMON-04-00758で、影響を受けたのは運用部門のみです。この問題は、メトリクスエージェントの再起動失敗が原因である可能性が高く、迅速な対応が求められます。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00758', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00758', 'INC-2025-00758', '今回のインシデントは、インフラメンテナンス後に発生したメトリクス欠損によるもので、具体的にはメトリクスエージェントの再起動が失敗したことが疑われます。運用チームはこの問題を迅速に把握し、再発防止に向けた対策を検討する必要があります。監視システムの整合性を保つため、今後のメンテナンス時には関連するエージェントの状態確認を強化することが重要です。', '今回のインシデントは、インフラメンテナンス後に発生したメトリクス欠損によるもので、具体的にはメトリクスエージェントの再起動が失敗したことが疑われます。運用チームはこの問題を迅速に把握し、再発防止に向けた対策を検討する必要があります。監視システムの整合性を保つため、今後のメンテナンス時には関連するエージェントの状態確認を強化することが重要です。', TIMESTAMP WITH TIME ZONE '2025-10-22T02:51:59+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01123', 'INC-2025-00758', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-10-21T03:06:59+09:00', TIMESTAMP WITH TIME ZONE '2025-10-21T04:06:59+09:00', '【初動対応】【監視・可用性障害】メトリクス欠損への初動', '運用部の運用 一郎は、2025年10月21日03時07分59秒にメトリクス欠損を確認し、直ちに調査を開始しました。メトリクスエージェントの状態を確認したところ、再起動が失敗するとともに、影響を受けたコンポーネントが特定されました。迅速なエスカレーションを行い、関連部門と連携して修正作業に着手しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01124', 'INC-2025-00758', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-10-21T04:36:59+09:00', TIMESTAMP WITH TIME ZONE '2025-10-21T05:36:59+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00764', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-05-06T04:39:37+09:00', TIMESTAMP WITH TIME ZONE '2025-05-06T04:54:37+09:00', '【障害報告】【CLU-08】ブルートフォース誤検知', '2025年5月6日04時39分37秒に、株式会社ストッククラウドの運用コンソールにおいて、ブルートフォース検知が発生し、正常なIPアドレスを遮断しました。影響を受けたのは架空食品店Bの単一店舗であり、運用部の運用 一郎が04時55分37秒にこの事象を検知しました。問題の発生は大規模セール開始直前であり、WAF（Web Application Firewall）による誤検知が疑われます。検知閾値の過敏設定が原因と考えられ、運用部としては迅速な対応が求められています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00764', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00764', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00764', 'INC-2025-00764', '調査の結果、運用コンソールのWAFによって正常なIPが誤って遮断されたことが確認されました。検知閾値が過敏に設定されていたことが原因で、ブルートフォース攻撃と誤認され、影響を受けたのは架空食品店Bの単一店舗でした。今後の対策として、WAFの設定見直しが必要です。', '調査の結果、運用コンソールのWAFによって正常なIPが誤って遮断されたことが確認されました。検知閾値が過敏に設定されていたことが原因で、ブルートフォース攻撃と誤認され、影響を受けたのは架空食品店Bの単一店舗でした。今後の対策として、WAFの設定見直しが必要です。', TIMESTAMP WITH TIME ZONE '2025-05-07T04:54:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01134', 'INC-2025-00764', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-06T05:09:37+09:00', TIMESTAMP WITH TIME ZONE '2025-05-06T06:09:37+09:00', '【初期対応】【CLU-08】ブルートフォース誤検知の初期対応', '運用部は事象発生後、直ちに運用コンソールの設定を確認しました。正常なIPアドレスの遮断を解除し、影響を受けた架空食品店Bに対して説明を行いました。また、WAFの設定を見直し、ブルートフォース検知の閾値を調整する手続きを開始しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01135', 'INC-2025-00764', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-05-06T06:39:37+09:00', TIMESTAMP WITH TIME ZONE '2025-05-06T07:39:37+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00770', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-02-24T19:28:15+09:00', TIMESTAMP WITH TIME ZONE '2025-02-24T21:28:15+09:00', '【障害報告】【棚卸・POS突合障害】店舗間転送未反映', '2025年2月24日19時28分に、株式会社ストッククラウドの顧客である架空食品店Bにおいて、棚卸突合失敗が発生しました。症状としては、店舗間在庫転送が送信側のみ減算される現象が確認されました。本障害は、同一顧客の全店舗に影響を及ぼす可能性があり、特に新規店舗追加の初日に発生したため、影響が大きいと考えられます。発見者は営業部の花子であり、22時43分に検知されました。エラーコードはINV-08-00770で、原因としては転送トランザクションの二相コミット失敗が疑われています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00770', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00770', 'INC-2025-00770', '調査の結果、新規店舗追加の初日に店舗間在庫転送が送信側のみ減算される事象が確認されました。技術的には、在庫転送サービスにおける転送トランザクションの二相コミット失敗が主要因と考えられます。今後、トランザクション処理におけるエラーハンドリングの強化が必要です。', '調査の結果、新規店舗追加の初日に店舗間在庫転送が送信側のみ減算される事象が確認されました。技術的には、在庫転送サービスにおける転送トランザクションの二相コミット失敗が主要因と考えられます。今後、トランザクション処理におけるエラーハンドリングの強化が必要です。', TIMESTAMP WITH TIME ZONE '2025-02-25T21:28:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01144', 'INC-2025-00770', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-02-24T21:43:15+09:00', TIMESTAMP WITH TIME ZONE '2025-02-24T22:43:15+09:00', '【初期対応】【棚卸・POS突合障害】店舗間転送未反映', '初期対応として、影響を受けた顧客店舗POSの状態を確認し、在庫転送の問題を早急に修正する方針を立てました。さらに、同様の事象が他の店舗に発生しないかをチェックし、必要に応じて追加の対応策を講じる予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01145', 'INC-2025-00770', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-02-24T23:13:15+09:00', TIMESTAMP WITH TIME ZONE '2025-02-25T00:13:15+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00792', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2025-08-02T09:07:30+09:00', TIMESTAMP WITH TIME ZONE '2025-08-02T09:22:30+09:00', '【障害報告】【CLU-10】PagerDuty連携失敗', '2025年8月2日09:07:30、株式会社ストッククラウドの運用コンソールにてPagerDuty連携が失敗し、オンコール通知未達の事象が発生しました。発見者は運用部の運用 一郎で、検知は09:15:30でした。発生契機は年末年始の稼働切替時で、影響範囲は運用部門のみとなっています。エラーコードはMON-07-00792です。技術詳細として、年末年始の稼働切替時にPagerDuty連携が失敗し、通知未達の原因として連携APIキーの権限不足が疑われています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00792', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00792', 'INC-2025-00792', '運用部門において、PagerDuty連携の失敗が確認されました。原因として連携APIキーの権限不足が考えられます。詳細な調査を行った結果、オンコール通知未達の影響を受けたのは運用部門のみでした。現在、APIキーの権限を確認し、必要に応じて修正を行う方針です。', '運用部門において、PagerDuty連携の失敗が確認されました。原因として連携APIキーの権限不足が考えられます。詳細な調査を行った結果、オンコール通知未達の影響を受けたのは運用部門のみでした。現在、APIキーの権限を確認し、必要に応じて修正を行う方針です。', TIMESTAMP WITH TIME ZONE '2025-08-03T09:22:30+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01178', 'INC-2025-00792', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-08-02T09:37:30+09:00', TIMESTAMP WITH TIME ZONE '2025-08-02T10:37:30+09:00', '【初期対応】【CLU-10】PagerDuty連携失敗', '本事象の発生を受け、運用部門は直ちに調査を開始しました。連携APIキーの権限不足が原因と疑われるため、権限の確認を行っています。また、今後の再発防止策として、連携設定の見直しを行う予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01179', 'INC-2025-00792', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2025-08-02T11:07:30+09:00', TIMESTAMP WITH TIME ZONE '2025-08-02T12:07:30+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00802', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-05-28T06:49:24+09:00', TIMESTAMP WITH TIME ZONE '2025-05-28T08:49:24+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2025年5月28日06:49:24に、株式会社ストッククラウドの顧客店舗POSにて、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けする事象が発生しました。この影響により、単一店舗のみでエラーが発生し、顧客名は不明です。検知は2025年5月28日10:09:24で、検知までに200分の時間を要しました。推定原因は文字コード変換テーブルの誤選択であると考えられます。影響コンポーネントは顧客店舗POS（ゾーンA）およびEDIアダプタです。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00802', 'INC-2025-00802', '発生した事象に関して、データ移行バッチが実行中にShift_JIS変換を行った際に、商品名が正常に処理されず文字化けが発生したことを確認しました。調査の結果、文字コード変換テーブルが誤って選択されたことが原因であると判断されました。また、影響範囲は単一店舗に限定されており、他の店舗には影響を及ぼしていません。', '発生した事象に関して、データ移行バッチが実行中にShift_JIS変換を行った際に、商品名が正常に処理されず文字化けが発生したことを確認しました。調査の結果、文字コード変換テーブルが誤って選択されたことが原因であると判断されました。また、影響範囲は単一店舗に限定されており、他の店舗には影響を及ぼしていません。', TIMESTAMP WITH TIME ZONE '2025-05-29T08:49:24+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01195', 'INC-2025-00802', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-05-28T09:04:24+09:00', TIMESTAMP WITH TIME ZONE '2025-05-28T10:04:24+09:00', '初動対応', '初動対応として、発生した文字化けの事象についてエンジニアリングチームに報告し、原因究明を委託しました。また、影響を受けている店舗に対しては、暫定的な対応策を講じ、関係者にも状況を周知しました。エラーログの収集や、データ移行バッチの設定確認を進めることを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01196', 'INC-2025-00802', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-05-28T10:34:24+09:00', TIMESTAMP WITH TIME ZONE '2025-05-28T11:34:24+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2025-00815', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2025-06-18T05:16:21+09:00', TIMESTAMP WITH TIME ZONE '2025-06-18T07:16:21+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2025年06月18日05時16分21秒、株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aの顧客店舗POSにて夜間整合性チェックで不一致アラートが多発しました。発生契機は月末棚卸の開始時です。整合性チェックが行われた結果、複数の不一致が報告され、それによりデータ同期・整合性に影響が及んでいます。エラーコードはSYNC-06-00815で、影響範囲はバッチ処理のみとなっており、オンラインには影響がありません。推定原因としては、整合性チェック基準の変更未反映が考えられます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2025-00815', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00815', 'INC-2025-00815', '不一致アラートが多発した理由について調査を行いました。整合性チェック基準の変更が最近行われましたが、その変更が夜間の整合性チェックに反映されていないことが確認されました。これにより、整合性チェックが正常に機能せず、不一致が発生していると考えられます。さらなる詳細な調査が必要です。', '不一致アラートが多発した理由について調査を行いました。整合性チェック基準の変更が最近行われましたが、その変更が夜間の整合性チェックに反映されていないことが確認されました。これにより、整合性チェックが正常に機能せず、不一致が発生していると考えられます。さらなる詳細な調査が必要です。', TIMESTAMP WITH TIME ZONE '2025-06-19T07:16:21+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01213', 'INC-2025-00815', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2025-06-18T07:31:21+09:00', TIMESTAMP WITH TIME ZONE '2025-06-18T08:31:21+09:00', '【初期対応】【データ同期・整合性障害】整合性チェックアラートの初期対応', '初期対応として、整合性チェック基準の変更内容を確認し、これを夜間整合性チェックに反映させる作業を開始しました。影響を受けた顧客店舗POSの状況を監視し、必要に応じて手動での整合性チェックを行う方針です。また、問題の全貌を把握するため、さらなる情報収集を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00039', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2026-06-24T21:48:38+09:00', TIMESTAMP WITH TIME ZONE '2026-06-24T22:33:38+09:00', '【障害報告】【監視・可用性障害】合成監視失敗', '発生日時: 2026年6月24日 21:48:38
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00039', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00039', 'CUST-0002');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00056', 'INC-2026-00039', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-06-24T22:48:38+09:00', NULL, '【初期対応】【監視・可用性障害】合成監視失敗への初期対応', '合成監視の失敗を受け、初期対応を実施しました。テストデータの確認を行い、期限切れのデータを修正しました。また、監視ランナーの再起動を行い、正常動作を確認しました。今後は、定期的なテストデータの更新と監視機能の見直しを行い、同様の問題が発生しないよう対策を講じます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00048', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-03-26T05:48:34+09:00', TIMESTAMP WITH TIME ZONE '2026-03-26T07:48:34+09:00', '【障害報告】【データ同期・整合性障害】整合性チェックアラート', '2026年3月26日05:48に、株式会社ストッククラウドの顧客である架空食品店Bにおいて、棚卸突合失敗が発生しました。5時48分に発生し、8時02分に検知されるまでの間に、夜間整合性チェックで不一致アラートが多発しました。整合性チェック基準の変更が未反映のため、バッチ処理において影響が出ていることが想定されます。これによる影響はオンラインには及んでおらず、顧客店舗POS（DRサイト）での整合性チェックジョブに関連しています。月末の棚卸開始時に発生したことが発覚し、その後の調査が必要です。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00048', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00048', 'INC-2026-00048', '本インシデントに関して、影響範囲はバッチ処理のみに限られ、整合性チェックでの不一致が著しいことが判明しました。整合性チェック基準の変更が未反映であることが原因と考えられ、その詳細な確認が進められています。夜間のデータ同期・整合性における問題によって、特に月末棚卸のタイミングでの影響が顕在化しました。', '本インシデントに関して、影響範囲はバッチ処理のみに限られ、整合性チェックでの不一致が著しいことが判明しました。整合性チェック基準の変更が未反映であることが原因と考えられ、その詳細な確認が進められています。夜間のデータ同期・整合性における問題によって、特に月末棚卸のタイミングでの影響が顕在化しました。', TIMESTAMP WITH TIME ZONE '2026-03-27T07:48:34+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00067', 'INC-2026-00048', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-03-26T08:03:34+09:00', TIMESTAMP WITH TIME ZONE '2026-03-26T09:03:34+09:00', '初期対応ログ', '本件について初期対応を行いました。発生直後に、監視システムによる整合性チェックを確認し、アラートが多発していることを確認しました。営業部の花子が発見し、迅速に技術チームにエスカレーションしました。技術チームは問題の原因を追求中であり、今後の進捗を報告する予定です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00068', 'INC-2026-00048', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-03-26T09:33:34+09:00', TIMESTAMP WITH TIME ZONE '2026-03-26T10:33:34+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00054', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-06-10T15:46:41+09:00', TIMESTAMP WITH TIME ZONE '2026-06-10T17:46:41+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2026年6月10日15時46分41秒、株式会社ストッククラウドの顧客である架空食品店A及び架空食品店Bにおいて、EDI経由の棚卸ファイル取込で件数不一致が発生しました。影響範囲はバッチ処理のみであり、オンラインサービスには影響がありません。この事象はデータ移行バッチ実行中に発生しました。発見者は営業部の花子で、2026年6月10日17時50分41秒に問題を検知しました。エラーコードはINV-06-00054で、EDI連携ファイルの文字コード不一致が推定原因と考えられます。技術的詳細としては、データ移行バッチ実行中にEDI経由の棚卸ファイル取込で件数不一致が確認されました。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00054', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00054', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00054', 'INC-2026-00054', '調査の結果、EDI経由の棚卸ファイル取込において、件数不一致が発生したことが確認されました。原因として、EDI連携ファイルの文字コードの不一致が疑われます。影響を受けたのは顧客店舗POS（ゾーンA）及びEDIアダプタであり、バッチ処理の実行中に問題が発生しました。今後、データ移行バッチの実行前にファイルの文字コードを確認するプロセスを追加することが推奨されます。', '調査の結果、EDI経由の棚卸ファイル取込において、件数不一致が発生したことが確認されました。原因として、EDI連携ファイルの文字コードの不一致が疑われます。影響を受けたのは顧客店舗POS（ゾーンA）及びEDIアダプタであり、バッチ処理の実行中に問題が発生しました。今後、データ移行バッチの実行前にファイルの文字コードを確認するプロセスを追加することが推奨されます。', TIMESTAMP WITH TIME ZONE '2026-06-11T17:46:41+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00077', 'INC-2026-00054', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-10T18:01:41+09:00', TIMESTAMP WITH TIME ZONE '2026-06-10T19:01:41+09:00', '初期対応ログ', '2026年6月10日17時50分41秒、営業部の花子がEDI棚卸ファイルの異常を発見し、初期対応を開始しました。まず、エラーコードINV-06-00054に基づいて、関連のシステムログを確認し、影響範囲を特定しました。次に、データ移行バッチの実行状況を調査し、EDIファイルの内容を精査しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00062', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2026-02-26T02:21:38+09:00', TIMESTAMP WITH TIME ZONE '2026-02-26T02:36:38+09:00', '【障害報告】【CLU-08】Cookie SameSite拒否', '2026年2月26日02時21分38秒、株式会社ストッククラウドの顧客である架空食品店Aにて、運用コンソールでCookie SameSite設定に起因する認証不可事象が発生しました。運用部の運用 一郎が発見し、検知までに21分を要しました。影響を受けたのは架空食品店Aのみで、定例リリース直後のタイミングで発生したため、SameSite属性の変更が影響していると推定されます。エラーコードはAUTH-06-00062となります。技術詳細として、埋込画面の認証に関する問題が確認されています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00062', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00062', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00062', 'INC-2026-00062', '運用 一郎が発見した障害について、運用部が調査を開始しました。埋込画面が認証不可となった原因を特定するために、定例リリースにおけるCookie SameSite設定の変更を詳細に確認しています。影響範囲は架空食品店Aの単一店舗のみであるため、範囲を絞った迅速な調査が可能です。今後の調査結果に基づいて、適切な対応策を検討します。', '運用 一郎が発見した障害について、運用部が調査を開始しました。埋込画面が認証不可となった原因を特定するために、定例リリースにおけるCookie SameSite設定の変更を詳細に確認しています。影響範囲は架空食品店Aの単一店舗のみであるため、範囲を絞った迅速な調査が可能です。今後の調査結果に基づいて、適切な対応策を検討します。', TIMESTAMP WITH TIME ZONE '2026-02-27T02:36:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00088', 'INC-2026-00062', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-02-26T02:51:38+09:00', TIMESTAMP WITH TIME ZONE '2026-02-26T03:51:38+09:00', '【初期対応】【CLU-08】Cookie SameSite拒否', '運用部の運用 一郎です。現在、Cookie SameSite設定による埋込画面の認証不可事象の原因を特定中です。定例リリース直後の影響を疑っており、早急に修正を行う予定です。影響店舗は架空食品店Aとなっていますが、他の店舗への影響は確認されていません。今後の進捗については随時報告します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00063', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-04-29T12:05:49+09:00', TIMESTAMP WITH TIME ZONE '2026-04-29T13:05:49+09:00', '【障害報告】【顧客ネットワーク障害】固定IP変更未連絡', '2026年4月29日12時05分49秒に、株式会社ストッククラウドのサービスVenusにおいて顧客固定IP変更が許可リストに未反映の事象が発生しました。営業部の花子が発見し、検知までに36分を要しました。影響範囲は単一店舗で、顧客拠点NWにおける顧客側FWが影響を受けています。発生契機は顧客オンボーディング当日であり、IP許可リストの更新漏れが推定原因です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00063', 'INC-2026-00063', '調査の結果、顧客オンボーディング当日に顧客固定IP変更が許可リストに未反映であったことが確認されました。今回の問題はIP許可リストの更新漏れが原因とされており、今後の対策としては、許可リストの更新を確実に行うプロセスの見直しが必要です。', '調査の結果、顧客オンボーディング当日に顧客固定IP変更が許可リストに未反映であったことが確認されました。今回の問題はIP許可リストの更新漏れが原因とされており、今後の対策としては、許可リストの更新を確実に行うプロセスの見直しが必要です。', TIMESTAMP WITH TIME ZONE '2026-04-30T13:05:49+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00089', 'INC-2026-00063', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-29T13:20:49+09:00', TIMESTAMP WITH TIME ZONE '2026-04-29T14:20:49+09:00', '【初期対応】【顧客ネットワーク障害】固定IP変更未連絡', '営業部の花子が固定IP変更の未反映を確認し、速やかに技術部門にエスカレーションしました。顧客ネットワークの正常化に向けて、IP許可リストの修正を依頼しています。今後は、顧客のオンボーディング前に確認項目を増やすことが必要です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00096', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-03-03T09:05:32+09:00', TIMESTAMP WITH TIME ZONE '2026-03-03T11:05:32+09:00', '【障害報告】【API連携・EDI障害】配送連携ステータス停滞', '2026年3月3日09時05分32秒に、株式会社ストッククラウドのサービスVenusにおいて、顧客店舗POSでの棚卸突合に失敗した事象が発生しました。本事象では、配送連携のステータスが出荷済みで停滞しております。この影響は架空服飾店Aに限定されており、重大度はLOWと判断しております。検知は同日12時24分32秒に行われ、検知までの時間は199分に及びました。発生契機としては、大規模セール開始直前であったため、配送連携の影響が特に顕著になっております。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00096', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00096', 'INC-2026-00096', '調査の結果、配送連携のステータスが出荷済みで停滞した原因として、ステータスマッピング表の更新漏れが疑われます。特に、大規模セール開始直前のタイミングで発生したため、通常とは異なる負荷がかかった可能性があります。これにより、配送連携アダプタの動作にも影響が出たと考えられます。', '調査の結果、配送連携のステータスが出荷済みで停滞した原因として、ステータスマッピング表の更新漏れが疑われます。特に、大規模セール開始直前のタイミングで発生したため、通常とは異なる負荷がかかった可能性があります。これにより、配送連携アダプタの動作にも影響が出たと考えられます。', TIMESTAMP WITH TIME ZONE '2026-03-04T11:05:32+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00142', 'INC-2026-00096', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-03-03T11:20:32+09:00', TIMESTAMP WITH TIME ZONE '2026-03-03T12:20:32+09:00', '【初動対応】【API連携・EDI障害】配送連携ステータス停滞', '初動対応として、まずは影響を受けている顧客店舗POSの状況を確認し、配送連携のステータスを再確認しました。ステータスマッピング表の確認も行い、必要に応じて修正作業を実施しました。引き続き、顧客店舗からの情報を集め、状況が改善されるまで監視を続けてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00100', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-05-15T03:57:36+09:00', TIMESTAMP WITH TIME ZONE '2026-05-15T04:27:36+09:00', '【障害報告】【在庫マスター設定障害】ロット管理初回入庫不可', '2026年5月15日の午前3時57分頃、株式会社ストッククラウドのVenusサービスにおいて、架空服飾店Aでロット管理初回入庫処理が失敗しました。この障害は、ロット番号の採番に失敗するという症状を引き起こしました。影響範囲は単一店舗に限定され、エラーコードはMST-08-00100です。発生契機は顧客オンボーディングの当日であり、ロット管理フラグの誤った有効化が推定原因として考えられます。この問題により、在庫マスター設定が適切に行われず、在庫の管理に影響が出る可能性があります。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00100', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00100', 'INC-2026-00100', '初回入庫処理でのロット番号採番失敗を調査中です。原因としてロット管理フラグの誤った有効化が疑われます。影響コンポーネントはMercury AWS AP及びロット管理サービスです。現時点では、顧客オンボーディング当日にこの問題が発生したことが確認されています。今後は、ロット管理フラグの設定を見直し、必要な修正を実施する予定です。', '初回入庫処理でのロット番号採番失敗を調査中です。原因としてロット管理フラグの誤った有効化が疑われます。影響コンポーネントはMercury AWS AP及びロット管理サービスです。現時点では、顧客オンボーディング当日にこの問題が発生したことが確認されています。今後は、ロット管理フラグの設定を見直し、必要な修正を実施する予定です。', TIMESTAMP WITH TIME ZONE '2026-05-16T04:27:36+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00146', 'INC-2026-00100', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-05-15T04:42:36+09:00', TIMESTAMP WITH TIME ZONE '2026-05-15T05:42:36+09:00', '【初期対応】ロット管理初回入庫不可', '初回入庫処理でのロット番号採番失敗の事象に対し、迅速に原因を特定し、ロット管理フラグの設定を確認します。また、架空服飾店Aに対して影響の説明を行い、必要なサポートを提供します。今後、この問題が発生しないよう、再発防止策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00105', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2026-05-10T07:26:31+09:00', TIMESTAMP WITH TIME ZONE '2026-05-10T07:41:31+09:00', '【障害報告】【CLU-10】ログ相関ID欠落', '2026年5月10日、株式会社ストッククラウドの運用コンソールにおいて、運用部の運用 一郎が発見したアクセス障害について報告いたします。本事象は定例リリース直後に発生し、ログに相関IDが欠落しているため横断検索が不可となっております。この問題は運用部門にのみ影響を及ぼし、エラーコードはMON-09-00105です。ログフォーマット変更のロールアウト漏れが推定される原因であり、監視・可用性障害として、高い重大度が認識されています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00105', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00105', 'INC-2026-00105', '本障害の調査に着手しました。定例リリース直後という発生契機から、ログフォーマット変更のロールアウト漏れが原因である可能性が高いです。運用コンソールおよびログパイプラインの設定を確認し、相関IDの欠落がどのように発生したのかを詳細に解析する必要があります。今後の対応策を検討し、影響範囲を最小限に抑えることが求められます。', '本障害の調査に着手しました。定例リリース直後という発生契機から、ログフォーマット変更のロールアウト漏れが原因である可能性が高いです。運用コンソールおよびログパイプラインの設定を確認し、相関IDの欠落がどのように発生したのかを詳細に解析する必要があります。今後の対応策を検討し、影響範囲を最小限に抑えることが求められます。', TIMESTAMP WITH TIME ZONE '2026-05-11T07:41:31+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00153', 'INC-2026-00105', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-05-10T07:56:31+09:00', TIMESTAMP WITH TIME ZONE '2026-05-10T08:56:31+09:00', '【初期対応】【CLU-10】ログ相関ID欠落', '初期対応として、運用部門に対して影響範囲の確認を行い、ログパイプラインの状態を調査しました。相関IDの欠落が確認され、運用コンソールの設定ミスが原因であることが判明しました。今後、ログフォーマット変更の適用状況を見直し、再発防止策を実施する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00154', 'INC-2026-00105', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-05-10T09:26:31+09:00', TIMESTAMP WITH TIME ZONE '2026-05-10T10:26:31+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00119', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-04-14T04:49:07+09:00', TIMESTAMP WITH TIME ZONE '2026-04-14T05:49:07+09:00', '【障害報告】【顧客ネットワーク障害】BGP経路障害波及', '2026年4月14日04時49分、株式会社ストッククラウドの顧客である架空食品店Aおよび架空食品店Bにおいて、ISP側BGP経路障害により複数拠点が同時不通となった。影響は同一顧客の全店舗に及び、顧客拠点NWが主な影響コンポーネントであり、DNSリゾルバにも影響が出た可能性がある。発生契機としてインフラメンテナンス明けが考えられ、2026年4月14日06時09分に問題を検知した。検知までの時間は80分。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00119', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00119', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00119', 'INC-2026-00119', '調査を実施した結果、ISP側のBGP経路障害が原因であると推定される。インフラメンテナンス明けに発生したため、メンテナンス後のネットワーク状態が影響した可能性が高い。今後、ISPとの連携を強化し、再発防止策を検討する必要がある。具体的な経路障害の詳細はISP側からの情報待ちである。', '調査を実施した結果、ISP側のBGP経路障害が原因であると推定される。インフラメンテナンス明けに発生したため、メンテナンス後のネットワーク状態が影響した可能性が高い。今後、ISPとの連携を強化し、再発防止策を検討する必要がある。具体的な経路障害の詳細はISP側からの情報待ちである。', TIMESTAMP WITH TIME ZONE '2026-04-15T05:49:07+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00172', 'INC-2026-00119', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-14T06:04:07+09:00', TIMESTAMP WITH TIME ZONE '2026-04-14T07:04:07+09:00', '【対応ログ】【顧客ネットワーク障害】初期対応', '2026年4月14日06時10分、営業部の花子が顧客に対し、障害発生の旨を通知し、確認を行った。顧客からの情報を収集するため、経路障害の詳細について迅速にISPへ問い合わせを実施した。影響範囲を把握するため、顧客の各拠点の状態を確認するための準備を始めた。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00173', 'INC-2026-00119', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-14T07:34:07+09:00', TIMESTAMP WITH TIME ZONE '2026-04-14T08:34:07+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00126', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-05-07T09:15:06+09:00', TIMESTAMP WITH TIME ZONE '2026-05-07T10:15:06+09:00', '【障害報告】【顧客ネットワーク障害】店舗VPN到達不可', '2026年5月7日09時15分頃、株式会社ストッククラウドのサービスMercuryにおいて、顧客拠点NWにおけるネットワーク障害が発生しました。障害の症状として、店舗VPN経由でSaaSに到達できない状況が報告されております。影響を受けた顧客は架空食品店Aおよび架空食品店Bの2店舗であり、各店舗のみが影響範囲となっています。推定される原因は、拠点FWのルール変更であり、顧客オンボーディング当日に発生したため、即時対応が求められました。エラーコードはNW-01-00126です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00126', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00126', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00126', 'INC-2026-00126', '障害発生後の調査において、顧客拠点NWのFW設定に変更が行われていたことが確認されました。この変更が原因で店舗VPN経由でのSaaS接続が不可能になったものと考えられます。調査は迅速に進められ、影響を受けた店舗が特定されました。今後は同様の障害が発生しないよう、FWの設定について再確認及び記録を徹底する必要があります。', '障害発生後の調査において、顧客拠点NWのFW設定に変更が行われていたことが確認されました。この変更が原因で店舗VPN経由でのSaaS接続が不可能になったものと考えられます。調査は迅速に進められ、影響を受けた店舗が特定されました。今後は同様の障害が発生しないよう、FWの設定について再確認及び記録を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2026-05-08T10:15:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00183', 'INC-2026-00126', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-05-07T10:30:06+09:00', TIMESTAMP WITH TIME ZONE '2026-05-07T11:30:06+09:00', '【初動対応】【顧客ネットワーク障害】店舗VPN到達不可', '初動対応として、2026年5月7日10時25分に障害を検知し、直ちに担当営業の花子が顧客に連絡を取りました。顧客には問題の概要と現在の状況を説明し、FWの設定確認を行う旨を伝えました。また、影響を受けた架空食品店Aおよび架空食品店Bには、店舗VPNの接続状況を確認するよう指示しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00130', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-02-01T14:11:10+09:00', TIMESTAMP WITH TIME ZONE '2026-02-01T14:41:10+09:00', '【障害報告】【在庫マスター設定障害】CSVバッチ取込欠損', '2026年2月1日14時11分10秒、架空服飾店Aにて在庫マスター設定ミスによる在庫登録失敗が発生。データ移行バッチ実行中に、在庫CSVの3行目以降が取込されないという症状が確認された。原因としてJANコード重複チェックの誤設定が疑われており、影響範囲はバッチ処理のみで、オンライン影響はない。エラーコードはMST-03-00130で、影響コンポーネントはMercury AWS AP（ゾーンB）のバッチ取込ワーカーである。検知は14時48分10秒に行われ、発見者は運用部の運用 一郎である。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00130', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00130', 'INC-2026-00130', '調査の結果、データ移行バッチ実行中に在庫CSVの3行目以降が取込されない現象が発生していることを確認した。JANコード重複チェックの誤設定が原因であると推測され、この設定の見直しを行う必要がある。今後、バッチ取込の処理を改善し、類似の問題が再発しないように対策を検討する。', '調査の結果、データ移行バッチ実行中に在庫CSVの3行目以降が取込されない現象が発生していることを確認した。JANコード重複チェックの誤設定が原因であると推測され、この設定の見直しを行う必要がある。今後、バッチ取込の処理を改善し、類似の問題が再発しないように対策を検討する。', TIMESTAMP WITH TIME ZONE '2026-02-02T14:41:10+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00189', 'INC-2026-00130', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-02-01T14:56:10+09:00', TIMESTAMP WITH TIME ZONE '2026-02-01T15:56:10+09:00', '【初動対応】【在庫マスター設定障害】CSVバッチ取込欠損', '初動対応として、既存のJANコード重複チェックの設定を確認し、必要な修正を行うことを提案する。また、バッチ処理のログを精査し、取込されなかった行の特定を行う。顧客への通知を行い、影響範囲や今後の対応策について説明することが重要である。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00190', 'INC-2026-00130', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-02-01T16:26:10+09:00', TIMESTAMP WITH TIME ZONE '2026-02-01T17:26:10+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00142', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-03-03T23:02:37+09:00', TIMESTAMP WITH TIME ZONE '2026-03-04T01:02:37+09:00', '【障害報告】【API連携・EDI障害】文字コード変換事故', '2026年3月3日23時02分37秒に、架空食品店Bの顧客店舗POSにおいて、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けするという事象が発生しました。この影響により、単一店舗のみの商品名が正しく表示されず、顧客に混乱を招く可能性がありました。発見者は営業部の花子で、発生から81分後の2026年3月4日0時23分37秒にこの問題が検知されました。エラーコードはEDI-07-00142です。原因としては、文字コード変換テーブルの誤選択が考えられます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00142', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00142', 'INC-2026-00142', '調査によると、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしたことが確認されました。この問題は顧客店舗POSおよびEDIアダプタに関連しており、影響範囲は単一店舗に限られています。文字コード変換テーブルの誤選択が原因として疑われており、早急な対策が必要です。', '調査によると、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしたことが確認されました。この問題は顧客店舗POSおよびEDIアダプタに関連しており、影響範囲は単一店舗に限られています。文字コード変換テーブルの誤選択が原因として疑われており、早急な対策が必要です。', TIMESTAMP WITH TIME ZONE '2026-03-05T01:02:37+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00208', 'INC-2026-00142', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-03-04T01:17:37+09:00', TIMESTAMP WITH TIME ZONE '2026-03-04T02:17:37+09:00', '初期対応', '初期対応として、問題の詳細を確認するために顧客店舗POSシステムのログを調査し、データ移行バッチの実行状況を確認しました。また、文字コード変換テーブルの設定を確認し、正しいテーブルが選択されているかの再チェックを行いました。問題の再発防止に向けて、今後のバッチ処理時には事前確認を徹底する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00148', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-03-27T20:46:15+09:00', TIMESTAMP WITH TIME ZONE '2026-03-27T21:46:15+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2026年3月27日20:46:15、株式会社ストッククラウドの顧客である架空服飾店Aにて、特定拠点のみAPI呼び出しが失敗する事象が発生しました。この障害は新規店舗追加の初日に発生し、顧客拠点NW及び顧客側FWに影響を及ぼしています。86分後の22:12:15に検知されました。推定原因として店舗LANのスイッチ故障が考えられ、影響範囲は単一店舗のみとなっています。エラーコードはNW-02-00148です。', '顧客拠点NW', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00148', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00148', 'INC-2026-00148', '障害発生の原因を調査する中で、新規店舗追加の日に特定拠点のみAPI呼び出しが失敗していることが確認されました。問題の切り分けのため、店舗LANのスイッチの状態を確認し、故障の有無を調査する必要があります。また、顧客側FWの設定状態も併せて確認し、API呼び出しの失敗原因を特定することが求められます。', '障害発生の原因を調査する中で、新規店舗追加の日に特定拠点のみAPI呼び出しが失敗していることが確認されました。問題の切り分けのため、店舗LANのスイッチの状態を確認し、故障の有無を調査する必要があります。また、顧客側FWの設定状態も併せて確認し、API呼び出しの失敗原因を特定することが求められます。', TIMESTAMP WITH TIME ZONE '2026-03-28T21:46:15+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00215', 'INC-2026-00148', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-03-27T22:01:15+09:00', NULL, '【初動対応】【顧客ネットワーク障害】拠点限定API失敗の初動対応', '発生した障害に対し、即座に顧客拠点NWの確認を行いました。特定拠点のLAN機器に異常がないかをチェックし、スイッチの状態をモニタリングしました。顧客側のネットワーク構成も見直し、設定ミスや機器の不具合がないか詳細に調査しました。必要に応じて、代替のネットワーク経路も提案し、顧客への影響を最小限に抑える対応を実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00158', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-06-10T11:39:01+09:00', TIMESTAMP WITH TIME ZONE '2026-06-10T13:39:01+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2026年6月10日11時39分、株式会社ストッククラウドの顧客である架空食品店Aにおいて、POS連携の売上が翌営業日まで在庫に反映されないという症状が発生しました。発見者は営業部の花子で、13時30分にこの問題が検知されました。問題の影響範囲は単一店舗のみに留まっています。エラーコードはINV-02-00158です。発生契機は年末年始の稼働切替時であり、その際に前日締め処理の二重実行が原因であると推測されます。POS連携ハブとの連携において、売上遅延が確認されています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00158', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00158', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00158', 'INC-2026-00158', '調査の結果、年末年始の稼働切替時にPOS連携の売上が在庫に反映されない原因として、前日締め処理の二重実行が疑われます。具体的には、システムログを調査したところ、締め処理が重複して実行されていることが確認されました。このため、売上遅延が発生し、顧客店舗POSにおいて正確な在庫情報が表示されなくなっています。', '調査の結果、年末年始の稼働切替時にPOS連携の売上が在庫に反映されない原因として、前日締め処理の二重実行が疑われます。具体的には、システムログを調査したところ、締め処理が重複して実行されていることが確認されました。このため、売上遅延が発生し、顧客店舗POSにおいて正確な在庫情報が表示されなくなっています。', TIMESTAMP WITH TIME ZONE '2026-06-11T13:39:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00229', 'INC-2026-00158', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-10T13:54:01+09:00', TIMESTAMP WITH TIME ZONE '2026-06-10T14:54:01+09:00', '初動対応', 'このインシデントに対して、初動対応としてログを確認し、前日締め処理の実行状況を詳細に調査しました。該当店舗のPOSシステムに対して、異常が発生していることを確認し、対応策として二重実行の防止策を講じることを決定しました。また、顧客には状況説明を行い、必要なサポートを提供することとしました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00230', 'INC-2026-00158', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-10T15:24:01+09:00', TIMESTAMP WITH TIME ZONE '2026-06-10T16:24:01+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00172', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-06-07T21:20:35+09:00', TIMESTAMP WITH TIME ZONE '2026-06-07T23:20:35+09:00', '【障害報告】【棚卸・POS突合障害】移動平均単価異常', '2026年6月7日21時20分35秒、株式会社ストッククラウドの顧客店舗POSにおいて、棚卸後の評価単価が想定外の値になる事象が発生しました。この事象は、定例リリース直後に起こったもので、移動平均計算式の適用期間誤りが推定原因です。影響範囲としては、サービス全体の一部機能に影響が及んでいます。特に在庫評価エンジンにおける評価単価の異常が報告されており、顧客へは影響がないものの、内部プロセスには影響を与えています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00172', 'INC-2026-00172', 'インシデント発生後、関係部署が調査を行った結果、移動平均計算式の適用期間に誤りがあったことが確認されました。この誤りにより、棚卸後の評価単価が想定外の値を示すことになったと考えられます。さらに、定例リリースにおける変更点が原因である可能性が高いとされています。今後の再発防止策としては、定期的な計算式の見直しおよびリリース前の徹底したテストを実施することが必要です。', 'インシデント発生後、関係部署が調査を行った結果、移動平均計算式の適用期間に誤りがあったことが確認されました。この誤りにより、棚卸後の評価単価が想定外の値を示すことになったと考えられます。さらに、定例リリースにおける変更点が原因である可能性が高いとされています。今後の再発防止策としては、定期的な計算式の見直しおよびリリース前の徹底したテストを実施することが必要です。', TIMESTAMP WITH TIME ZONE '2026-06-08T23:20:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00253', 'INC-2026-00172', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-07T23:35:35+09:00', TIMESTAMP WITH TIME ZONE '2026-06-08T00:35:35+09:00', '【初期対応】【棚卸・POS突合障害】移動平均単価異常への初期対応', 'インシデント発生の通知を受けた後、営業部の花子が関係者に連絡を取り、事象の確認を行いました。初期調査において、棚卸後の評価単価の異常が確認され、迅速に技術チームと連携して問題の切り分けを行いました。その結果、移動平均計算式の適用期間に誤りがあったことが判明し、技術チームは修正作業に着手しました。修正後は再発防止策を講じることが求められます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00254', 'INC-2026-00172', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-08T01:05:35+09:00', TIMESTAMP WITH TIME ZONE '2026-06-08T02:05:35+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00179', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-01-12T20:49:13+09:00', TIMESTAMP WITH TIME ZONE '2026-01-12T21:19:13+09:00', '【障害報告】【CLU-07】OAuthトークン失効', '2026年1月12日20時49分13秒に、株式会社ストッククラウドのサービスMercuryにおいて、OAuthトークン失効が原因でPOS連携が中断しました。この事象は、架空食品店Aおよび架空食品店Bに影響を及ぼしました。特に、Mercury AWS AP（ゾーンB）において発生したこの障害は、年末年始の稼働切替時におけるリフレッシュトークン保存先の障害が推定されており、影響範囲は単一店舗に限られています。エラーコードはEDI-05-00179であり、初期検知が2026年1月12日21時25分13秒までかかりました。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00179', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00179', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00179', 'INC-2026-00179', '本障害の調査を進めた結果、年末年始の稼働切替時にOAuthトークンが失効し、POS連携が中断する事象が確認されました。リフレッシュトークン保存先に障害があったことが原因として特定されており、今後の運用においては、このような障害を未然に防ぐための対策が求められます。', '本障害の調査を進めた結果、年末年始の稼働切替時にOAuthトークンが失効し、POS連携が中断する事象が確認されました。リフレッシュトークン保存先に障害があったことが原因として特定されており、今後の運用においては、このような障害を未然に防ぐための対策が求められます。', TIMESTAMP WITH TIME ZONE '2026-01-13T21:19:13+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00264', 'INC-2026-00179', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-12T21:34:13+09:00', TIMESTAMP WITH TIME ZONE '2026-01-12T22:34:13+09:00', '初期対応', '初期対応として、運用部の運用一郎がこの障害に対して迅速に調査を開始しました。まずは影響を受けている店舗への通知を行い、現場での対応を指示しました。次に、OAuthトークンの再発行を行い、POS連携の復旧を試みました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00191', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-05-26T18:36:42+09:00', TIMESTAMP WITH TIME ZONE '2026-05-26T19:06:42+09:00', '【障害報告】【在庫マスター設定障害】ロット管理初回入庫不可', '発生日時: 2026-05-26T18:36:42+09:00
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00191', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00191', 'INC-2026-00191', '本事象について技術的な調査を実施した結果、顧客オンボーディング当日に初回入庫処理でロット番号採番に失敗していることが確認された。原因としてロット管理フラグの誤った有効化が疑われる。今後の対策として、フラグ設定の見直しを提案する。現状では、架空食品店Aにおいてのみ影響が出ているため、早急に修正が必要である。', '本事象について技術的な調査を実施した結果、顧客オンボーディング当日に初回入庫処理でロット番号採番に失敗していることが確認された。原因としてロット管理フラグの誤った有効化が疑われる。今後の対策として、フラグ設定の見直しを提案する。現状では、架空食品店Aにおいてのみ影響が出ているため、早急に修正が必要である。', TIMESTAMP WITH TIME ZONE '2026-05-27T19:06:42+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00281', 'INC-2026-00191', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-05-26T19:21:42+09:00', NULL, '【初期対応】【在庫マスター設定障害】ロット管理初回入庫不可', '2026-05-26T19:09:42+09:00に事象を検知し、直ちに運用部にて初期対応を開始。影響範囲の確認及び顧客への状況報告を実施。今後は、同様の事象が再発しないよう、ロット管理フラグの設定手順を見直し、必要に応じてシステムの修正を行う。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00198', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-06-22T00:12:33+09:00', TIMESTAMP WITH TIME ZONE '2026-06-22T00:42:33+09:00', '【障害報告】【データ同期・整合性障害】スナップショット復元不整合', '2026年6月22日00時12分33秒に、株式会社ストッククラウドのサービスMercuryにおいて、マスター設定ミスによる在庫登録失敗が発生しました。発見者は運用部の運用 一郎であり、00時56分33秒にこの障害が検知されました。今回の障害は、スナップショット復元後に在庫整合が崩れるという症状が確認され、全テナントに波及する影響を及ぼしました。エラーコードはSYNC-09-00198であり、発生契機はデータ移行バッチの実行中にあります。技術的な詳細としましては、データ移行バッチ実行中にスナップショット復元後に在庫整合が崩れたことが挙げられ、復元ポイントのトランザクションログ欠落が原因として疑われています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00198', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00198', 'INC-2026-00198', '調査の結果、スナップショット復元後に発生した在庫整合の崩れは、復元ポイントのトランザクションログが欠落していることに起因していることが確認されました。この問題は、データ移行バッチの実行中に発生し、全テナントに影響を及ぼしました。今後、再発防止策として、スナップショット復元作業時のトランザクションログの整合性チェックを強化する必要があります。', '調査の結果、スナップショット復元後に発生した在庫整合の崩れは、復元ポイントのトランザクションログが欠落していることに起因していることが確認されました。この問題は、データ移行バッチの実行中に発生し、全テナントに影響を及ぼしました。今後、再発防止策として、スナップショット復元作業時のトランザクションログの整合性チェックを強化する必要があります。', TIMESTAMP WITH TIME ZONE '2026-06-23T00:42:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00291', 'INC-2026-00198', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-06-22T00:57:33+09:00', NULL, '【対応ログ】【データ同期・整合性障害】スナップショット復元不整合', '初期対応として、障害発生直後に運用部が関連ログの確認を行い、スナップショット復元による整合性の崩れを確認しました。影響範囲を特定するために、全テナントの在庫状況を調査し、必要に応じて復元作業を実施しました。また、トランザクションログのバックアップ状況についても詳細に確認を行い、今後の対策を講じるための情報を収集しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00207', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-04-25T06:33:00+09:00', TIMESTAMP WITH TIME ZONE '2026-04-25T08:33:00+09:00', '【障害報告】【API連携・EDI障害】バルクAPI部分失敗', '2026年4月25日06時33分に、株式会社ストッククラウドのMercuryサービスにおいて、顧客店舗POSにおける棚卸突合が失敗しました。バルクAPIが部分失敗し、ロールバックが未完了となり、影響範囲はサービス全体の一部機能に及びました。この事象は、データ移行バッチ実行中に発生し、発見者である営業部の花子が08時31分に検知しました。エラーコードはEDI-10-00207で、推定原因としては部分成功時の補償トランザクション欠如が考えられています。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00207', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00207', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00207', 'INC-2026-00207', '本インシデントの調査を行った結果、データ移行バッチ実行中にバルクAPIが部分失敗し、ロールバックが実施されなかったことが判明しました。原因として、部分成功時の補償トランザクションが欠如していたことが指摘されます。このため、サービス全体の一部機能に影響が及びました。今後はこのような事象を防ぐため、補償トランザクションの適切なハンドリングを行う必要があります。', '本インシデントの調査を行った結果、データ移行バッチ実行中にバルクAPIが部分失敗し、ロールバックが実施されなかったことが判明しました。原因として、部分成功時の補償トランザクションが欠如していたことが指摘されます。このため、サービス全体の一部機能に影響が及びました。今後はこのような事象を防ぐため、補償トランザクションの適切なハンドリングを行う必要があります。', TIMESTAMP WITH TIME ZONE '2026-04-26T08:33:00+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00305', 'INC-2026-00207', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-25T08:48:00+09:00', TIMESTAMP WITH TIME ZONE '2026-04-25T09:48:00+09:00', '【初期対応】【API連携・EDI障害】バルクAPI部分失敗への初期対応', 'インシデント発生後、営業部の花子が速やかに対応を開始しました。影響を受けた顧客店舗POSの状況確認を行い、バルクAPIの状態を調査しました。また、データ移行バッチの状況も確認し、必要に応じて対策を講じる準備を進めました。ロールバックが未完了であることから、影響を最小限に抑えるための対応が求められました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00223', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-02-10T12:06:06+09:00', TIMESTAMP WITH TIME ZONE '2026-02-10T12:36:06+09:00', '【障害報告】【CLU-07】文字コード変換事故', '2026年2月10日12時06分06秒、株式会社ストッククラウドのサービスMercuryにおいて、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けする事象が発生しました。発見者は運用部の運用 一郎です。発生後47分後の12時53分06秒にこの事象が検知され、Mercury AWS APに影響が及んでいることが確認されました。影響範囲は単一店舗のみで、エラーコードはEDI-07-00223です。推定原因として、文字コード変換テーブルの誤選択が考えられています。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'LOW', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00223', 'INC-2026-00223', '本事象に関して、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしていることが確認されています。原因として、文字コード変換テーブルの誤選択を疑っており、詳細な調査を進めています。影響を受けているコンポーネントはMercury AWS AP及びEDIアダプタであり、API連携・EDIの正常な動作に支障をきたしています。', '本事象に関して、データ移行バッチ実行中にShift_JIS変換で商品名が文字化けしていることが確認されています。原因として、文字コード変換テーブルの誤選択を疑っており、詳細な調査を進めています。影響を受けているコンポーネントはMercury AWS AP及びEDIアダプタであり、API連携・EDIの正常な動作に支障をきたしています。', TIMESTAMP WITH TIME ZONE '2026-02-11T12:36:06+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00329', 'INC-2026-00223', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-02-10T12:51:06+09:00', TIMESTAMP WITH TIME ZONE '2026-02-10T13:51:06+09:00', '【初期対応】【CLU-07】文字コード変換事故', '初期対応として、運用部によりデータ移行バッチの状況を確認しました。Shift_JIS変換での文字化けが発生していることが確認され、エラーコードEDI-07-00223の原因分析を開始しました。対象の文字コード変換テーブルを見直し、適切なテーブルへの修正を検討しています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00227', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-03-14T17:27:25+09:00', TIMESTAMP WITH TIME ZONE '2026-03-14T17:57:25+09:00', '【障害報告】【CLU-07】JSONスキーマ不一致', '2026年3月14日17時27分25秒に発生した障害について報告します。本事象は、株式会社ストッククラウドのサービスMercuryにおいて、連携JSONのスキーマ不一致が発生し、全件拒否となりました。影響範囲はバッチ処理のみで、オンライン環境には影響はありませんでした。この問題は定例リリース直後に確認され、発見者は運用部の運用 一郎です。推定原因として、スキーマバージョンの同期漏れが考えられ、エラーコードはEDI-04-00227となります。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00227', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00227', 'INC-2026-00227', '本事象の調査において、定例リリース後に連携JSONのスキーマ不一致が原因で全件が拒否される事態が発生しました。スキーマのバージョン管理が徹底されておらず、同期漏れがあったと推測されます。特に、Mercury AWS APのEDIアダプタにおいて、スキーマの不一致が顕在化しました。今後はスキーマバージョンの管理とリリース後の確認を徹底し、同様の事象が再発しないよう対策を講じる必要があります。', '本事象の調査において、定例リリース後に連携JSONのスキーマ不一致が原因で全件が拒否される事態が発生しました。スキーマのバージョン管理が徹底されておらず、同期漏れがあったと推測されます。特に、Mercury AWS APのEDIアダプタにおいて、スキーマの不一致が顕在化しました。今後はスキーマバージョンの管理とリリース後の確認を徹底し、同様の事象が再発しないよう対策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2026-03-15T17:57:25+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00335', 'INC-2026-00227', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-03-14T18:12:25+09:00', TIMESTAMP WITH TIME ZONE '2026-03-14T19:12:25+09:00', '【初動対応】【CLU-07】JSONスキーマ不一致', '障害を確認後、運用部は即座に対応を開始しました。エラーコードEDI-04-00227に基づき、スキーマ不一致の原因を特定し、影響を受けたバッチ処理の停止を指示しました。さらに、関連するチームに通知し、スキーマバージョンの確認を行いました。必要な修正を速やかに実施するための方針を立て、関係者全員に共有しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00229', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-03-06T06:20:01+09:00', TIMESTAMP WITH TIME ZONE '2026-03-06T07:20:01+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2026年3月6日06時20分に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bの全店舗でDNS解決成功後にTLS握手で接続が切断されるという顧客側ネットワーク障害が発生しました。これにより同一顧客の全店舗に影響が及びました。エラーコードNW-03-00229が記録されており、発生契機としてはインフラメンテナンス明けが考えられます。技術的には、インフラメンテナンス明けにDNS解決が成功したものの、その後のTLS握手で接続が切断されました。原因としてプロキシ証明書の期限切れが疑われています。今回の障害は、顧客ネットワークにおいて重要なTLS接続に影響を与えたため、迅速な対応が求められました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00229', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00229', 'INC-2026-00229', '本件の障害に関する調査を行いました。発生した症状は、DNS解決成功後にTLS握手で接続が切断されることでした。影響範囲は架空食品店Bの全店舗に及び、事象の発生契機はインフラメンテナンス明けでした。技術詳細としては、プロキシ証明書の期限切れが推定原因となっており、TLS接続の確立に失敗し得る要因となっています。この調査を基に、今後の対策を検討する必要があります。', '本件の障害に関する調査を行いました。発生した症状は、DNS解決成功後にTLS握手で接続が切断されることでした。影響範囲は架空食品店Bの全店舗に及び、事象の発生契機はインフラメンテナンス明けでした。技術詳細としては、プロキシ証明書の期限切れが推定原因となっており、TLS接続の確立に失敗し得る要因となっています。この調査を基に、今後の対策を検討する必要があります。', TIMESTAMP WITH TIME ZONE '2026-03-07T07:20:01+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00337', 'INC-2026-00229', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-03-06T07:35:01+09:00', TIMESTAMP WITH TIME ZONE '2026-03-06T08:35:01+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', '障害発生後、営業部の花子が初動対応を行いました。顧客からの報告を受け、直ちに技術チームにエスカレーションしました。DNS解決後のTLS接続切断に関する情報を共有し、プロキシ証明書の確認を指示しました。影響を受けた全店舗の状況を把握するため、顧客と密に連携を取り、迅速な復旧を図る方針を決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00236', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-06-23T12:22:46+09:00', TIMESTAMP WITH TIME ZONE '2026-06-23T12:52:46+09:00', '【障害報告】【CLU-07】冪等キー重複', '・発生日時: 2026年6月23日 12:22:46
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00236', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00236', 'INC-2026-00236', '今回の問題について、定例リリース直後に冪等キーの重複が発生し、在庫更新がスキップされる事象が確認されました。冪等キー生成ロジックの衝突が原因とされ、同一顧客の全店舗に影響が及んでいます。現在、冪等キーの生成ロジックを見直し、再発防止策を検討中です。さらに、エラーコード EDI-08-00236 に関する詳細なログの確認を進めています。', '今回の問題について、定例リリース直後に冪等キーの重複が発生し、在庫更新がスキップされる事象が確認されました。冪等キー生成ロジックの衝突が原因とされ、同一顧客の全店舗に影響が及んでいます。現在、冪等キーの生成ロジックを見直し、再発防止策を検討中です。さらに、エラーコード EDI-08-00236 に関する詳細なログの確認を進めています。', TIMESTAMP WITH TIME ZONE '2026-06-24T12:52:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00349', 'INC-2026-00236', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-06-23T13:07:46+09:00', TIMESTAMP WITH TIME ZONE '2026-06-23T14:07:46+09:00', '初期対応', '今回の冪等キー重複による在庫更新スキップの事象について、直ちに運用部の運用 一郎が担当し、初期対応を開始しました。影響範囲を確認し、同一顧客の全店舗での在庫登録APIの状況を調査しました。今後の対応として、冪等キー生成ロジックの変更を検討する必要があります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00350', 'INC-2026-00236', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-06-23T14:37:46+09:00', TIMESTAMP WITH TIME ZONE '2026-06-23T15:37:46+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00262', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2026-01-26T21:39:55+09:00', TIMESTAMP WITH TIME ZONE '2026-01-26T21:54:55+09:00', '【障害報告】【CLU-10】可用性レポート誤集計', '2026年1月26日21時39分55秒に株式会社ストッククラウドの運用者による作業ミスが原因で、運用コンソールにおいて月次可用性レポートが実績より高く表示される障害が発生しました。この問題は運用部門にのみ影響を及ぼし、月末棚卸の開始時に発生したため、多くの顧客に対して誤った可用性情報を提供してしまいました。検知は同日21時55分55秒に行われ、約16分後に問題が明らかとなりました。推定原因として、メンテナンス除外時間の二重計上が考えられています。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00262', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00262', 'INC-2026-00262', '運用コンソールにて、月末棚卸の開始時に月次可用性レポートが誤集計される事象が確認されました。この誤集計は、メンテナンス除外時間の二重計上によるものであり、運用部門の監視・可用性障害に関連しています。運用部門はこの問題を早急に解決し、再発防止策を講じる必要があります。', '運用コンソールにて、月末棚卸の開始時に月次可用性レポートが誤集計される事象が確認されました。この誤集計は、メンテナンス除外時間の二重計上によるものであり、運用部門の監視・可用性障害に関連しています。運用部門はこの問題を早急に解決し、再発防止策を講じる必要があります。', TIMESTAMP WITH TIME ZONE '2026-01-27T21:54:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00388', 'INC-2026-00262', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-26T22:09:55+09:00', TIMESTAMP WITH TIME ZONE '2026-01-26T23:09:55+09:00', '初期対応', '初期対応として、運用部門では即座に問題の確認を行い、運用コンソール上での可用性レポートの表示内容について精査を開始しました。また、関係者間での情報共有を迅速に行い、顧客への影響を最小限に抑えるための対応策を検討しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00283', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2026-06-15T20:29:57+09:00', TIMESTAMP WITH TIME ZONE '2026-06-15T20:44:57+09:00', '【障害報告】【CLU-08】ブルートフォース誤検知', '株式会社ストッククラウドのサービスMercuryにおいて、2026年6月15日20時29分57秒に運用者の作業ミスによるアクセス障害が発生しました。具体的には、運用コンソールにて、ブルートフォース検知が正常IPを遮断しました。発生の契機は、大規模セール開始直前であり、影響範囲は架空食品店Aのみに及んでいます。この際、エラーコードはAUTH-08-00283です。検知は20時50分57秒に行われ、正常IPの遮断が確認されました。運用部の運用一郎が発見者です。主な原因としては、検知閾値の過敏設定が疑われます。', '運用コンソール', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'CRITICAL', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00283', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00283', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00283', 'INC-2026-00283', '運用コンソールにおけるブルートフォース誤検知の調査において、正常IPの遮断が確認されました。大規模セール開始前の状況で、WAFの設定が過敏すぎたと考えられます。運用者の作業ミスにより、検知閾値が適切に設定されていなかったため、正当なアクセスも遮断されました。影響を受けたのは架空食品店Aのみであり、早急な修正が求められます。', '運用コンソールにおけるブルートフォース誤検知の調査において、正常IPの遮断が確認されました。大規模セール開始前の状況で、WAFの設定が過敏すぎたと考えられます。運用者の作業ミスにより、検知閾値が適切に設定されていなかったため、正当なアクセスも遮断されました。影響を受けたのは架空食品店Aのみであり、早急な修正が求められます。', TIMESTAMP WITH TIME ZONE '2026-06-16T20:44:57+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00418', 'INC-2026-00283', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-06-15T20:59:57+09:00', NULL, '【初期対応】【CLU-08】ブルートフォース誤検知への初期対応', '発生直後に運用部により、運用コンソールの設定確認が行われました。ブルートフォース検知の過敏設定が障害の原因であることが特定され、WAFの設定を見直し、正常IPの遮断解除が実施されました。影響を受けた架空食品店Aの顧客に対し、障害発生の旨を連絡し、状況を説明しました。今後、このような誤検知が発生しないよう、検知閾値の適正化を進めます。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00288', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-06-20T06:18:17+09:00', TIMESTAMP WITH TIME ZONE '2026-06-20T08:18:17+09:00', '【障害報告】【棚卸・POS突合障害】EDI棚卸ファイル異常', '2026年6月20日06時18分、株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aの顧客店舗POSにてEDI経由の棚卸ファイル取込で件数不一致の事象が発生しました。発見者は営業部の花子で、問題はデータ移行バッチ実行中に発生しました。これにより、バッチ処理のみが影響を受け、オンラインでの影響は確認されていません。また、エラーコードはINV-06-00288です。推定原因としては、EDI連携ファイルの文字コード不一致が考えられます。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00288', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00288', 'INC-2026-00288', 'この事象は、データ移行バッチ実行中にEDI経由の棚卸ファイル取込で件数不一致が発生したもので、原因は主にEDI連携ファイルの文字コード不一致が疑われます。調査では、関連するEDIアダプタの設定やファイルの文字コードを確認し、問題の特定を進めていきます。影響範囲は顧客店舗POSのバッチ処理に限定されているため、早急に修正対応を行います。', 'この事象は、データ移行バッチ実行中にEDI経由の棚卸ファイル取込で件数不一致が発生したもので、原因は主にEDI連携ファイルの文字コード不一致が疑われます。調査では、関連するEDIアダプタの設定やファイルの文字コードを確認し、問題の特定を進めていきます。影響範囲は顧客店舗POSのバッチ処理に限定されているため、早急に修正対応を行います。', TIMESTAMP WITH TIME ZONE '2026-06-21T08:18:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00425', 'INC-2026-00288', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-20T08:33:17+09:00', TIMESTAMP WITH TIME ZONE '2026-06-20T09:33:17+09:00', '初期対応', '初期対応として、営業部の花子が問題の詳細を確認し、EDI連携ファイルの文字コード設定を調査しています。また、影響を受けた顧客店舗POSに対して、バッチ処理の再実行を検討しています。今後は、他の顧客への影響がないか確認を行い、必要に応じて情報を提供する方針です。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00313', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-01-30T05:20:35+09:00', TIMESTAMP WITH TIME ZONE '2026-01-30T06:20:35+09:00', '【障害報告】【顧客ネットワーク障害】Wi-Fi captive portal', '2026年1月30日05時20分35分に株式会社ストッククラウドの顧客において、店舗Wi-Fiの認証ページでAPI通信が遮断される問題が発生しました。この障害は、新規店舗追加の初日に発生し、影響範囲は単一店舗に限定されました。推定原因はキャプティブポータルによるHTTPSインターセプトであり、顧客拠点NWおよび顧客側FWに影響を及ぼしました。障害を最初に発見したのは、営業部の花子であり、検知までに62分を要しました。発生したエラーコードはNW-09-00313です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00313', 'INC-2026-00313', '障害の調査を行った結果、新規店舗追加の初日に店舗Wi-Fiの認証ページでAPI通信が遮断されていることが確認されました。原因として、キャプティブポータルがHTTPS通信をインターセプトしている可能性が高いと考えられます。今後の対応として、キャプティブポータルの設定確認および修正が必要です。', '障害の調査を行った結果、新規店舗追加の初日に店舗Wi-Fiの認証ページでAPI通信が遮断されていることが確認されました。原因として、キャプティブポータルがHTTPS通信をインターセプトしている可能性が高いと考えられます。今後の対応として、キャプティブポータルの設定確認および修正が必要です。', TIMESTAMP WITH TIME ZONE '2026-01-31T06:20:35+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00460', 'INC-2026-00313', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-01-30T06:35:35+09:00', TIMESTAMP WITH TIME ZONE '2026-01-30T07:35:35+09:00', '【初動対応】【顧客ネットワーク障害】Wi-Fi captive portal', '2026年1月30日06時22分35分にこの問題を認識しました。初動対応として、顧客に状況を報告し、Wi-Fi設定の見直しを指示しました。また、技術チームにはキャプティブポータルの設定を確認するよう依頼しました。今後は、問題を解決するための詳細な調査を実施し、再発防止策を検討いたします。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00461', 'INC-2026-00313', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-01-30T08:05:35+09:00', TIMESTAMP WITH TIME ZONE '2026-01-30T09:05:35+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00315', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-02-13T08:18:29+09:00', TIMESTAMP WITH TIME ZONE '2026-02-13T09:18:29+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2026年2月13日08時18分29分に、株式会社ストッククラウドの顧客である架空食品店Bにおいて、顧客拠点NWでDNS解決成功後にTLS握手で接続が切断されるという障害が発生しました。障害の検知は09時14分29分であり、発生から56分後に確認されました。この影響は同一顧客の全店舗に及ぶと考えられ、特にインフラメンテナンス明けにおけるプロキシ証明書の期限切れが原因である可能性があります。技術的には、DNS解決は成功していたもののTLS握手が完了せず、接続が切断されました。今後の教訓として、定期的な証明書のチェックを行うことが重要です。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00315', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00315', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00315', 'INC-2026-00315', '本障害の調査を行った結果、発生したタイミングがインフラメンテナンス明けであることが確認されました。プロキシ証明書の有効期限が切れていたため、TLS握手が正常に行われず接続が切断された可能性が高いです。今後、この事象の再発を防ぐために、証明書の適切な管理と更新を推進する必要があります。また、障害発生時には迅速に情報を共有し、対応を行う重要性も確認されています。', '本障害の調査を行った結果、発生したタイミングがインフラメンテナンス明けであることが確認されました。プロキシ証明書の有効期限が切れていたため、TLS握手が正常に行われず接続が切断された可能性が高いです。今後、この事象の再発を防ぐために、証明書の適切な管理と更新を推進する必要があります。また、障害発生時には迅速に情報を共有し、対応を行う重要性も確認されています。', TIMESTAMP WITH TIME ZONE '2026-02-14T09:18:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00464', 'INC-2026-00315', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-02-13T09:33:29+09:00', TIMESTAMP WITH TIME ZONE '2026-02-13T10:33:29+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断の初期対応', 'インフラメンテナンス後の接続切断を受け、迅速に障害調査を開始しました。営業部の花子が顧客からの情報を収集し、DNSが正常に解決されていたことを確認しました。その後、TLS握手において接続が切断されていることが判明し、プロキシ証明書の確認を行いました。証明書の期限切れが原因であることが予想され、対応策として証明書の更新手続きを即座に行うことを決定しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00327', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-06-19T04:06:50+09:00', TIMESTAMP WITH TIME ZONE '2026-06-19T05:06:50+09:00', '【障害報告】【顧客ネットワーク障害】拠点限定API失敗', '2026年6月19日04:06に株式会社ストッククラウドの顧客拠点NWにおいて、特定拠点のみAPI呼び出しが失敗する事象が発生しました。新規店舗追加の初日であり、05:20に検知されました。影響は単一店舗のみで、エラーコードはNW-02-00327です。推定される原因は店舗LANのスイッチ故障です。特定拠点におけるAPI失敗が顧客ネットワークに影響を及ぼしています。問題が解決されるまでの間、営業部の花子が発見者として状況を監視しています。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00327', 'INC-2026-00327', '問題の調査を開始しました。最初の確認で、特定拠点のLANが正常に動作していないことが判明しました。スイッチの状態をチェックしたところ、異常な動作が確認されました。LANのスイッチ故障が原因でAPI呼び出しが失敗している可能性が高いため、スイッチの交換作業を検討中です。', '問題の調査を開始しました。最初の確認で、特定拠点のLANが正常に動作していないことが判明しました。スイッチの状態をチェックしたところ、異常な動作が確認されました。LANのスイッチ故障が原因でAPI呼び出しが失敗している可能性が高いため、スイッチの交換作業を検討中です。', TIMESTAMP WITH TIME ZONE '2026-06-20T05:06:50+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00479', 'INC-2026-00327', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-19T05:21:50+09:00', NULL, '【初期対応】【顧客ネットワーク障害】拠点限定API失敗', '問題が発生したことを受けて、専門チームに連絡し、現地調査を行う手配をしました。まずは特定拠点のLAN環境を確認し、スイッチの状態を監視します。顧客に対しても最新情報を提供し、必要に応じて代替手段を検討する旨を伝達しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00333', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-01-26T23:26:55+09:00', TIMESTAMP WITH TIME ZONE '2026-01-26T23:56:55+09:00', '【障害報告】【在庫マスター設定障害】セット商品分解失敗', '2026年1月26日23時26分55分に、株式会社ストッククラウドのサービスMercuryにおいて、セット商品の在庫分解時に構成エラーが発生いたしました。この問題は、定例リリース直後に発生し、影響を受けたのは架空食品店Aおよび架空食品店Bの全店舗です。エラーコードはMST-07-00333であり、BOM構成テーブルの親子関係に不整合があることが推定されています。影響範囲は、同一顧客の全店舗に及び、在庫計算エンジンにも影響が出ております。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00333', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00333', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00333', 'INC-2026-00333', '本障害に関する調査を行った結果、定例リリース直後にBOM構成テーブルの親子関係に不整合が生じたことが原因であると考えられます。特に、在庫分解処理において構造上のエラーが発生し、セット商品の在庫が正しく分解できない状況が確認されました。現在、具体的な修正方法について検討を進めております。', '本障害に関する調査を行った結果、定例リリース直後にBOM構成テーブルの親子関係に不整合が生じたことが原因であると考えられます。特に、在庫分解処理において構造上のエラーが発生し、セット商品の在庫が正しく分解できない状況が確認されました。現在、具体的な修正方法について検討を進めております。', TIMESTAMP WITH TIME ZONE '2026-01-27T23:56:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00488', 'INC-2026-00333', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-27T00:11:55+09:00', TIMESTAMP WITH TIME ZONE '2026-01-27T01:11:55+09:00', '【初期対応】【在庫マスター設定障害】セット商品分解失敗', '本件につきまして、運用部の運用 一郎が迅速に対応を開始いたしました。影響を受けた顧客には直ちに通知を行い、障害の詳細と今後の対応について説明を行いました。また、BOM構成テーブルの調査を始め、親子関係の不整合の特定を優先的に進め、適切な修正策を講じる予定です。顧客の業務に影響が出ているため、できるだけ早く解決できるよう努めてまいります。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00334', 'COMP-001', 'ITYP-004', TIMESTAMP WITH TIME ZONE '2026-04-10T20:22:17+09:00', TIMESTAMP WITH TIME ZONE '2026-04-10T21:22:17+09:00', '【障害報告】【顧客ネットワーク障害】TLS握手切断', '2026年4月10日20時22分17秒に、株式会社ストッククラウドの顧客である架空食品店Aにおいて、顧客側ネットワークの障害が発生しました。症状としてはDNS解決成功後にTLS握手で接続切断が発生しました。発生契機はインフラメンテナンス明けであり、全店舗に影響を及ぼしました。推定原因としてはプロキシ証明書の期限切れが考えられ、影響コンポーネントは顧客拠点NWおよびTLS終端です。この問題は検知までに96分を要しました。', '顧客拠点NW', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00334', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00334', 'INC-2026-00334', '調査の結果、DNS解決が成功したにもかかわらず、TLS握手で接続が切断される事象が確認されました。この原因としてプロキシ証明書の期限切れの可能性が高いと考えられ、インフラメンテナンス明けのタイミングでこの問題が顕在化しました。同一顧客の全店舗に影響が及ぶため、早急な対応が必要です。', '調査の結果、DNS解決が成功したにもかかわらず、TLS握手で接続が切断される事象が確認されました。この原因としてプロキシ証明書の期限切れの可能性が高いと考えられ、インフラメンテナンス明けのタイミングでこの問題が顕在化しました。同一顧客の全店舗に影響が及ぶため、早急な対応が必要です。', TIMESTAMP WITH TIME ZONE '2026-04-11T21:22:17+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00489', 'INC-2026-00334', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-10T21:37:17+09:00', TIMESTAMP WITH TIME ZONE '2026-04-10T22:37:17+09:00', '【初期対応】【顧客ネットワーク障害】TLS握手切断', '初期対応として、すぐに架空食品店Aの担当者に連絡を取り、状況を確認しました。また、プロキシ証明書の状態を調査するために、必要なログを収集しました。初期段階での情報収集により、問題解決に向けた次のステップを明確にすることができました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00371', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2026-01-15T10:12:38+09:00', TIMESTAMP WITH TIME ZONE '2026-01-15T10:42:38+09:00', '【障害報告】【CLU-08】セッション突然切断', '2026年1月15日10時12分38秒に、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Bと架空食品店Aの利用者からの報告がありました。操作中にセッションが突然切断される障害が発生しました。この問題は、特定リージョンのユーザーのみに影響を及ぼし、インフラメンテナンス明けに発生しています。エラーコードはAUTH-02-00371であり、セッションTTL設定の短縮反映が推定される原因です。影響を受けたコンポーネントはVenus Azure AP（DRサイト）とセッションストアです。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00371', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00371', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00371', 'INC-2026-00371', '本件について調査を開始しました。まず、インフラメンテナンス明け直後に発生したため、セッションTTL設定の短縮反映が原因である可能性を考慮しています。該当するリージョンのログを精査し、切断が発生したタイミングと関連性を確認します。また、他のユーザーにも同様の障害があったか調査を行います。', '本件について調査を開始しました。まず、インフラメンテナンス明け直後に発生したため、セッションTTL設定の短縮反映が原因である可能性を考慮しています。該当するリージョンのログを精査し、切断が発生したタイミングと関連性を確認します。また、他のユーザーにも同様の障害があったか調査を行います。', TIMESTAMP WITH TIME ZONE '2026-01-16T10:42:38+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00543', 'INC-2026-00371', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-15T10:57:38+09:00', TIMESTAMP WITH TIME ZONE '2026-01-15T11:57:38+09:00', '初期対応', '運用部の運用 一郎が本件に関する初期対応を行いました。問題の特定に向けて影響を受けたユーザーとの連絡を開始し、必要な情報を収集しました。また、セッションTTLに関する設定を確認し、短縮された理由の確認を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00544', 'INC-2026-00371', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-15T12:27:38+09:00', TIMESTAMP WITH TIME ZONE '2026-01-15T13:27:38+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00383', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2026-01-13T20:45:33+09:00', TIMESTAMP WITH TIME ZONE '2026-01-13T21:15:33+09:00', '【障害報告】【CLU-08】JWT署名鍵ローテ漏れ', '2026年1月13日20時45分、株式会社ストッククラウドのサービスMercuryにおいて、JWT署名鍵ローテ後に旧トークン検証失敗の事象が発生しました。発生時点では、顧客である架空食品店Bおよび架空食品店Aに影響が及び、全テナントに波及する事態となりました。21時22分に検知され、検知までに37分を要しました。発生契機はインフラメンテナンス明けであり、影響を受けたコンポーネントはVenus Azure AP（Primary）及び認証サービスです。この障害により、顧客はサービスの利用が困難となりました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00383', 'CUST-0002');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00383', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00383', 'INC-2026-00383', '本事象の調査を行った結果、鍵ローテの段階的切替未実施が推定原因として浮上しました。JWT署名鍵をローテーション後、古いトークンの検証に失敗したことが確認されました。全テナントに影響があるため、迅速な対応が求められます。今後、鍵ローテーションの手順を見直し、段階的な切替の実施を徹底する必要があります。', '本事象の調査を行った結果、鍵ローテの段階的切替未実施が推定原因として浮上しました。JWT署名鍵をローテーション後、古いトークンの検証に失敗したことが確認されました。全テナントに影響があるため、迅速な対応が求められます。今後、鍵ローテーションの手順を見直し、段階的な切替の実施を徹底する必要があります。', TIMESTAMP WITH TIME ZONE '2026-01-14T21:15:33+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00562', 'INC-2026-00383', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-13T21:30:33+09:00', TIMESTAMP WITH TIME ZONE '2026-01-13T22:30:33+09:00', '【初期対応】【CLU-08】JWT署名鍵ローテ漏れ', 'インフラメンテナンス明け直後のJWT署名鍵ローテ後、旧トークンの認証失敗が発生したため、迅速に調査を開始しました。影響範囲を確認し、経過時間を記録しています。現在、暫定的な対応として新しいトークンの発行を進めると共に、鍵ローテーション手順の改訂を行っています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00488', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-06-24T16:04:29+09:00', TIMESTAMP WITH TIME ZONE '2026-06-24T18:04:29+09:00', '【障害報告】【データ同期・整合性障害】デッドレター蓄積', '2026年6月24日16時04分に、株式会社ストッククラウドのサービスMercuryにおいて、顧客店舗POSにおける棚卸突合失敗が発生しました。発見者は営業部の花子で、16時04分に発生後、17時20分に検知されました。この問題の症状として、同期メッセージがデッドレターに大量蓄積していることが確認されました。影響範囲はバッチ処理に限定され、オンラインには影響がありませんでした。推定原因としてデッドレター再処理ジョブの未設定が考えられます。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'IN_PROGRESS', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00488', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00488', 'INC-2026-00488', '本障害に関する調査を実施しました。調査の結果、データ移行バッチ実行中に顧客店舗POSのメッセージキューに蓄積された同期メッセージがデッドレターに大量に移動したことが確認されました。この状況はデッドレター再処理ジョブが未設定であるために発生したと考えられます。今後の対応として、再処理ジョブの設定を進め、デッドレターの解消を図ります。', '本障害に関する調査を実施しました。調査の結果、データ移行バッチ実行中に顧客店舗POSのメッセージキューに蓄積された同期メッセージがデッドレターに大量に移動したことが確認されました。この状況はデッドレター再処理ジョブが未設定であるために発生したと考えられます。今後の対応として、再処理ジョブの設定を進め、デッドレターの解消を図ります。', TIMESTAMP WITH TIME ZONE '2026-06-25T18:04:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00719', 'INC-2026-00488', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-24T18:19:29+09:00', NULL, '【初期対応】【データ同期・整合性障害】', '営業部の花子です。本障害の発生に対し、まずはデータ移行バッチの設定を確認し、デッドレター再処理ジョブが未設定であることを特定しました。次に、メッセージキューの状態を監視し、デッドレターの蓄積状況を定期的に確認していきます。必要に応じて、技術チームと連携し、迅速な対応を行います。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00502', 'COMP-001', 'ITYP-003', TIMESTAMP WITH TIME ZONE '2026-03-18T22:00:14+09:00', TIMESTAMP WITH TIME ZONE '2026-03-18T22:15:14+09:00', '【障害報告】【CLU-10】メトリクス欠損', '2026年3月18日22時00分14秒に、株式会社ストッククラウドのVenusサービスにおいて、運用者の作業ミスによるアクセス障害が発生しました。主要メトリクス系列が15分間欠損しており、運用部門にのみ影響が及んでいます。この障害は、インフラメンテナンス明けに発生しました。検知は22時14分14秒で、14分間の遅延がありました。発見者は運用部の運用 一郎で、エラーコードはMON-04-00502です。原因として、メトリクスエージェントの再起動失敗が疑われています。', '運用コンソール', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00502', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00502', 'INC-2026-00502', '調査の結果、インフラメンテナンス明けに主要メトリクス系列が15分間欠損した理由は、メトリクスエージェントの再起動失敗に起因していることが明らかになりました。再起動が行われなかったため、運用コンソール（DRサイト）でメトリクスコレクタが正しく機能せず、監視・可用性に影響を与えました。今後の対策としては、エージェントの再起動プロセスを見直し、障害監視体制を強化する必要があります。', '調査の結果、インフラメンテナンス明けに主要メトリクス系列が15分間欠損した理由は、メトリクスエージェントの再起動失敗に起因していることが明らかになりました。再起動が行われなかったため、運用コンソール（DRサイト）でメトリクスコレクタが正しく機能せず、監視・可用性に影響を与えました。今後の対策としては、エージェントの再起動プロセスを見直し、障害監視体制を強化する必要があります。', TIMESTAMP WITH TIME ZONE '2026-03-19T22:15:14+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00740', 'INC-2026-00502', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-03-18T22:30:14+09:00', TIMESTAMP WITH TIME ZONE '2026-03-18T23:30:14+09:00', '【初期対応】メトリクス欠損', '発見後すぐに、運用部の運用 一郎が対応を開始しました。初期対応として、メトリクスエージェントの再起動を試みましたが、再起動がうまくいかないことが確認されました。さらに、ログを確認し、メトリクス欠損の原因を特定するために調査を進めました。運用部は、他のリソースへの影響を最小限に抑えるための対策を講じました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00504', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2026-02-25T07:54:46+09:00', TIMESTAMP WITH TIME ZONE '2026-02-25T08:39:46+09:00', '【障害報告】【ストレージ・容量障害】WALアーカイブ滞留', '2026年2月25日07時54分46秒に、株式会社ストッククラウドのサービスMercuryにおいて、WALアーカイブが滞留しディスクを圧迫するストレージ溢れの問題が発生しました。この問題は、定例リリース直後に発生したもので、影響範囲は全テナントに波及しました。発見者は運用部の運用 一郎であり、08時52分46秒に検知されました。アーカイブ先のマウントポイントの枯渇が推定原因として疑われています。エラーコードはSTR-08-00504です。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00504', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00504', 'INC-2026-00504', '調査の結果、定例リリース直後にWALアーカイブが滞留し、Mercury AWS Storage（ゾーンA）のディスクを圧迫していることが確認されました。影響を受けるバックアップ領域においては、アーカイブ先のマウントポイントが枯渇している状況が見受けられます。このため、全テナントに影響を及ぼす事態となっています。今後の対応が急務です。', '調査の結果、定例リリース直後にWALアーカイブが滞留し、Mercury AWS Storage（ゾーンA）のディスクを圧迫していることが確認されました。影響を受けるバックアップ領域においては、アーカイブ先のマウントポイントが枯渇している状況が見受けられます。このため、全テナントに影響を及ぼす事態となっています。今後の対応が急務です。', TIMESTAMP WITH TIME ZONE '2026-02-26T08:39:46+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00743', 'INC-2026-00504', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-02-25T08:54:46+09:00', NULL, '【対応ログ】【ストレージ・容量障害】初期対応', '初期対応として、運用部によるアーカイブ先のマウントポイントの状況確認を行いました。その結果、マウントポイントの枯渇が確認され、アーカイブの手動削除及び設定変更を行う必要があることが判明しました。全テナントへの影響を最小限に抑えるため、即時対応を実施します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00508', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-06-06T14:19:29+09:00', TIMESTAMP WITH TIME ZONE '2026-06-06T16:19:29+09:00', '【障害報告】【データ同期・整合性障害】CDCイベント欠損', '2026年6月6日14時19分29秒、株式会社ストッククラウドの顧客である架空食品店Aにおいて、CDCイベント欠損により下流倉庫が未更新の状態が発生しました。これはデータ移行バッチ実行中に起こり、影響範囲はバッチ処理のみでオンラインには影響しませんでした。検知は2026年6月6日16時32分29秒で、検知までに133分を要しました。エラーコードはSYNC-03-00508です。症状としては、CDCイベント欠損が確認され、推定原因はCDCコネクタのオフセット巻戻しと考えられます。影響を受けたコンポーネントは顧客店舗POS（DRサイト）およびCDCパイプラインです。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00508', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00508', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00508', 'INC-2026-00508', '発生したCDCイベント欠損の調査を行った結果、データ移行バッチ実行中にCDCコネクタのオフセットが巻き戻される事象が発生していることが確認されました。このため、下流倉庫が未更新となり、データの整合性が損なわれました。調査を通じて、事象発生の原因特定に向けた詳細な解析が進められており、同様の問題を防ぐための施策を検討しています。', '発生したCDCイベント欠損の調査を行った結果、データ移行バッチ実行中にCDCコネクタのオフセットが巻き戻される事象が発生していることが確認されました。このため、下流倉庫が未更新となり、データの整合性が損なわれました。調査を通じて、事象発生の原因特定に向けた詳細な解析が進められており、同様の問題を防ぐための施策を検討しています。', TIMESTAMP WITH TIME ZONE '2026-06-07T16:19:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00749', 'INC-2026-00508', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-06T16:34:29+09:00', TIMESTAMP WITH TIME ZONE '2026-06-06T17:34:29+09:00', '【初期対応】【データ同期・整合性障害】CDCイベント欠損の初期対応', '初期対応として、影響を受けた顧客店舗POSの運用チームに連絡し、CDCイベント欠損の影響を受けたデータの確認を行いました。また、CDCコネクタのオフセット巻戻しの原因を特定するための調査を開始し、必要に応じてデータの手動修正を検討しました。顧客には状況を報告し、問題解決に向けた進捗を随時連絡する旨を伝えました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00750', 'INC-2026-00508', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-06-06T18:04:29+09:00', TIMESTAMP WITH TIME ZONE '2026-06-06T19:04:29+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00584', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-04-24T04:18:29+09:00', TIMESTAMP WITH TIME ZONE '2026-04-24T06:18:29+09:00', '【障害報告】【棚卸・POS突合障害】POS売上遅延反映', '2026年4月24日04:18:29、株式会社ストッククラウドの顧客である架空食品店Aにて、棚卸突合失敗が発生した。症状として、POS連携の売上が翌営業日まで在庫に反映されない状況が確認された。この問題は、顧客店舗POSで発生しており、発見者は営業部の花子である。影響範囲は単一店舗に限定されており、エラーコードはINV-02-00584である。推定原因として前日締め処理の二重実行が考えられ、この問題が年末年始の稼働切替時に発生したことが影響を与えていると推測される。', '顧客店舗POS', 'SVC-001', 'EMP-00002', 'DEPT-SAL', 'LOW', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00584', 'CUST-0001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00584', 'CUST-0002');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00584', 'INC-2026-00584', '本件について、営業部の花子が発見した通り、POS連携の売上情報が翌営業日まで在庫に反映されない事象が確認された。年末年始の稼働切替時に発生したため、前日締め処理が二重に実行されたことが原因と考えられる。今後、対応策として締め処理の実行状況を監視し、二重実行を防止するための対策を講じる必要がある。', '本件について、営業部の花子が発見した通り、POS連携の売上情報が翌営業日まで在庫に反映されない事象が確認された。年末年始の稼働切替時に発生したため、前日締め処理が二重に実行されたことが原因と考えられる。今後、対応策として締め処理の実行状況を監視し、二重実行を防止するための対策を講じる必要がある。', TIMESTAMP WITH TIME ZONE '2026-04-25T06:18:29+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00864', 'INC-2026-00584', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-24T06:33:29+09:00', TIMESTAMP WITH TIME ZONE '2026-04-24T07:33:29+09:00', '初期対応', 'インシデント発生後、迅速に状況を確認し、営業部の花子から詳細な情報を取得した。再現テストを行い、前日締め処理が二重に実行されていたことを確認。影響を受けた店舗に対して、状況説明と今後の対応について連絡を行った。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00865', 'INC-2026-00584', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-04-24T08:03:29+09:00', TIMESTAMP WITH TIME ZONE '2026-04-24T09:03:29+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00593', 'COMP-001', 'ITYP-005', TIMESTAMP WITH TIME ZONE '2026-03-14T15:37:55+09:00', TIMESTAMP WITH TIME ZONE '2026-03-14T16:22:55+09:00', '【障害報告】【ストレージ・容量障害】インデックス再構築膨張', '2026年3月14日15時37分55秒、株式会社ストッククラウドのサービスMercuryにおいて、インデックス再構築中に一時領域が枯渇する事象が発生しました。これにより、特定リージョンのユーザーに影響が及び、ストレージ・容量の問題が懸念されました。本事象は、インフラメンテナンス明けに再構築が開始されたことが発生契機とされています。エラーコードはSTR-07-00593です。運用部の運用 一郎がこの事象を最初に確認し、2026年3月14日16時28分55秒に検知しました。', 'Mercury AWS Storage', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'HIGH', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00593', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00593', 'INC-2026-00593', '本事象の調査を行った結果、インフラメンテナンス明けにインデックス再構築中に一時領域が枯渇したことが確認されました。再構築用一時領域のサイズ見積不足が推定原因として挙げられます。これにより、ユーザーに不便を強いる結果となりました。今後、再構築の際は一時領域のサイズ設定を見直し、影響を最小限に抑えることが求められます。', '本事象の調査を行った結果、インフラメンテナンス明けにインデックス再構築中に一時領域が枯渇したことが確認されました。再構築用一時領域のサイズ見積不足が推定原因として挙げられます。これにより、ユーザーに不便を強いる結果となりました。今後、再構築の際は一時領域のサイズ設定を見直し、影響を最小限に抑えることが求められます。', TIMESTAMP WITH TIME ZONE '2026-03-15T16:22:55+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00878', 'INC-2026-00593', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-03-14T16:37:55+09:00', TIMESTAMP WITH TIME ZONE '2026-03-14T17:37:55+09:00', '【初期対応】【ストレージ・容量障害】インデックス再構築膨張', '運用部の運用 一郎が問題を初めて確認した際、早急にインフラメンテナンスの影響を調査しました。再構築用一時領域のサイズを見直すよう、技術チームに指示を出しました。さらに、影響を受けた顧客に対して、状況を説明し、改善策を講じる旨を報告しました。今後、同様の事象が発生しないよう、再発防止策を早急に立案し実施します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00879', 'INC-2026-00593', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-03-14T18:07:55+09:00', TIMESTAMP WITH TIME ZONE '2026-03-14T19:07:55+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00608', 'COMP-001', 'ITYP-002', TIMESTAMP WITH TIME ZONE '2026-05-17T21:44:43+09:00', TIMESTAMP WITH TIME ZONE '2026-05-17T23:44:43+09:00', '【障害報告】【棚卸・POS突合障害】棚卸確定不可', '2026年5月17日21時44分43秒に、株式会社ストッククラウドのサービスVenusにおいて、顧客である架空服飾店Aの店舗POSにて棚卸確定ボタンがグレーアウトし、操作できない事象が発生しました。発見者は営業部の花子で、発生後78分で検知されました。未処理の差異調整レコードが残留していることが推定され、影響範囲は単一店舗のみであることが確認されています。月末棚卸の開始時に発生したことが影響を及ぼしている可能性があります。', '顧客店舗POS', 'SVC-002', 'EMP-00002', 'DEPT-SAL', 'MEDIUM', 'RESOLVED', 'SALES_INQUIRY', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00608', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00608', 'INC-2026-00608', '調査の結果、顧客店舗POS（ゾーンB）において、未処理の差異調整レコードが原因で棚卸確定ボタンがグレーアウトしたままになっていることが明らかとなりました。月末棚卸の開始時にこの問題が発生したため、店舗在庫ビューにも影響が出ている模様です。今後、同様の事象を防ぐための対策が必要です。', '調査の結果、顧客店舗POS（ゾーンB）において、未処理の差異調整レコードが原因で棚卸確定ボタンがグレーアウトしたままになっていることが明らかとなりました。月末棚卸の開始時にこの問題が発生したため、店舗在庫ビューにも影響が出ている模様です。今後、同様の事象を防ぐための対策が必要です。', TIMESTAMP WITH TIME ZONE '2026-05-18T23:44:43+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00900', 'INC-2026-00608', 'INITIAL', 1, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-05-17T23:59:43+09:00', TIMESTAMP WITH TIME ZONE '2026-05-18T00:59:43+09:00', '【初期対応】【棚卸・POS突合障害】棚卸確定不可に関する初期対応', '営業部の花子です。顧客店舗POSにおける棚卸確定ボタンのグレーアウトについて、現在未処理の差異調整レコードが存在していることを確認しました。早急に差異調整を行い、棚卸確定が可能となるよう取り組みます。進捗状況は随時報告いたしますので、関係者の皆様はご留意ください。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00901', 'INC-2026-00608', 'PERMANENT', 2, 'EMP-00002', TIMESTAMP WITH TIME ZONE '2026-05-18T01:29:43+09:00', TIMESTAMP WITH TIME ZONE '2026-05-18T02:29:43+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00638', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-06-01T06:25:11+09:00', TIMESTAMP WITH TIME ZONE '2026-06-01T06:55:11+09:00', '【障害報告】【CLU-09】読取レプリカ遅延', '2026年6月1日06時25分に、株式会社ストッククラウドのVenusにおいて、架空服飾店Aに対する在庫登録に失敗が発生しました。具体的には、読取レプリカ遅延により在庫照会が古い値を返す事象が確認されました。この問題は、大規模セール開始直前に発生したため、影響を受けたのは特定リージョンのユーザーのみです。今後の運用に影響を及ぼす可能性があり、レプリケーション遅延の監視閾値を超過していることが推定されます。検知は06時57分となり、発見者は運用部の運用 一郎です。', 'Mercury AWS AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'IN_PROGRESS', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00638', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00638', 'INC-2026-00638', '調査の結果、Mercury AWS APにおける読取専用レプリカのレプリケーション遅延が発生していることが確認されました。これにより、在庫照会が古い値を返す状態が持続しており、特定の顧客に影響を与えています。原因として、レプリケーション遅延の監視閾値を超過したことが考えられ、データ同期・整合性に関わる問題が発生していることが示唆されます。', '調査の結果、Mercury AWS APにおける読取専用レプリカのレプリケーション遅延が発生していることが確認されました。これにより、在庫照会が古い値を返す状態が持続しており、特定の顧客に影響を与えています。原因として、レプリケーション遅延の監視閾値を超過したことが考えられ、データ同期・整合性に関わる問題が発生していることが示唆されます。', TIMESTAMP WITH TIME ZONE '2026-06-02T06:55:11+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-00942', 'INC-2026-00638', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-06-01T07:10:11+09:00', NULL, '【初期対応】レプリカ遅延による在庫照会問題', '初期対応として、データ同期の状態を確認し、レプリケーション遅延の原因を特定するために、システムログを詳細に調査しています。また、運用部の運用 一郎が中心となり、問題の影響を受けた顧客へ連絡し、在庫情報の確認を行うよう指示を出しました。今後の対応として、監視体制を強化し、レプリケーションのパフォーマンスを向上させる方策を検討します。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00748', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2026-05-09T21:24:53+09:00', TIMESTAMP WITH TIME ZONE '2026-05-09T21:54:53+09:00', '【障害報告】【認証・セッション障害】SSOリダイレクトループ', '2026年5月9日21時24分53秒に、株式会社ストッククラウドのサービスVenusにおいて、架空服飾店Aに対する応答遅延が発生しました。SSOログインを試みた際にリダイレクトループが発生し、全テナントに影響を及ぼしたことを確認しました。発生契機は定例リリース直後であり、原因としてSAMLメタデータのURL不一致が疑われます。検知は21時48分53秒に行われ、検知までに24分が経過しました。影響コンポーネントはVenus Azure AP（Primary）および認証サービスです。', 'Venus Azure AP', 'SVC-002', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00748', 'CUST-0010');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00748', 'INC-2026-00748', 'リダイレクトループの原因を調査した結果、SAMLメタデータのURL不一致が主要因であることが確認されました。定例リリース直後に発生したため、リリースの影響範囲を精査し、SSOログイン機能の使用状況を確認しました。全テナントにおいて同様の症状が確認され、緊急対応が必要と判断されました。', 'リダイレクトループの原因を調査した結果、SAMLメタデータのURL不一致が主要因であることが確認されました。定例リリース直後に発生したため、リリースの影響範囲を精査し、SSOログイン機能の使用状況を確認しました。全テナントにおいて同様の症状が確認され、緊急対応が必要と判断されました。', TIMESTAMP WITH TIME ZONE '2026-05-10T21:54:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01107', 'INC-2026-00748', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-05-09T22:09:53+09:00', TIMESTAMP WITH TIME ZONE '2026-05-09T23:09:53+09:00', '【初期対応】【認証・セッション障害】SSOリダイレクトループへの初期対応', '初期対応として、運用部の運用 一郎がSSOログイン機能の確認を行い、リダイレクトループの症状を再現しました。エラーコードAUTH-01-00748が確認され、問題の早急な解決に向けて、開発チームへのエスカレーションを実施しました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01108', 'INC-2026-00748', 'PERMANENT', 2, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-05-09T23:39:53+09:00', TIMESTAMP WITH TIME ZONE '2026-05-10T00:39:53+09:00', '【対応】PERMANENT', '', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00781', 'COMP-001', 'ITYP-001', TIMESTAMP WITH TIME ZONE '2026-01-16T06:46:53+09:00', TIMESTAMP WITH TIME ZONE '2026-01-16T07:16:53+09:00', '【障害報告】【CLU-01】ロット管理初回入庫不可', '2026年1月16日、株式会社ストッククラウドのサービスMercuryにおいて、架空食品店Aに対して実施された顧客オンボーディング当日に、初回入庫処理でロット番号採番に失敗する事象が発生しました。発生時刻は06:46であり、検知時刻は07:33でした。エラーコードはMST-08-00781で、影響範囲は単一店舗のみです。技術的な詳細としては、Mercury AWS APのロット管理サービスにおいて、ロット管理フラグの誤った有効化が原因と推定されます。', 'Mercury AWS AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00781', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00781', 'INC-2026-00781', '本事象を調査した結果、初回入庫処理におけるロット番号採番の失敗は、ロット管理フラグの誤った有効化によるものであることが確認されました。調査の過程で、Mercury AWS APにおいて設定ミスがあったことが判明しました。再発防止策として、設定手順の見直し及び確認プロセスの強化を提案します。', '本事象を調査した結果、初回入庫処理におけるロット番号採番の失敗は、ロット管理フラグの誤った有効化によるものであることが確認されました。調査の過程で、Mercury AWS APにおいて設定ミスがあったことが判明しました。再発防止策として、設定手順の見直し及び確認プロセスの強化を提案します。', TIMESTAMP WITH TIME ZONE '2026-01-17T07:16:53+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01162', 'INC-2026-00781', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-01-16T07:31:53+09:00', TIMESTAMP WITH TIME ZONE '2026-01-16T08:31:53+09:00', '【初期対応】【CLU-01】ロット管理初回入庫不可', '初期対応として、架空食品店Aに対して状況の説明を行い、発生した問題について理解を得ることが重要です。さらに、システムログを確認し、ロット管理フラグの設定状況を詳細に調査しました。お客様には、問題解決までの経過を逐次報告し、安心感を提供するよう努めました。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incidents (incident_id, company_id, type_id, occurred_at, detected_at, title, description, location_name, affected_service_ids, detector_employee_id, detector_department_id, severity, status, detection_source, related_event_id, row_version, updated_at, updated_by_employee_id) VALUES ('INC-2026-00789', 'COMP-001', 'ITYP-006', TIMESTAMP WITH TIME ZONE '2026-02-18T01:26:22+09:00', TIMESTAMP WITH TIME ZONE '2026-02-18T01:56:22+09:00', '【障害報告】【監視・可用性障害】アラート疲労', '2026年2月18日01:26に発生した利用者増による応答遅延により、同一アラートが短時間に数百件発報する事象が発生しました。発見者は運用部の運用 一郎で、検知までの時間は26分でした。この問題は架空食品店Aの運用部門に影響を及ぼしました。原因として、アラート抑制ルールの未設定が疑われ、影響を受けたコンポーネントはVenus Azure AP（ゾーンB）およびアラートマネージャです。大規模セール開始直前の状況で、監視・可用性障害が起こりました。', 'Venus Azure AP', 'SVC-001', 'EMP-00001', 'DEPT-OPS', 'MEDIUM', 'RESOLVED', 'OPS_MONITORING', NULL, 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_customers (incident_id, customer_id) VALUES ('INC-2026-00789', 'CUST-0001');
INSERT INTO oil_incident_investigations (investigation_id, incident_id, root_cause_summary, investigation_detail, completed_at, row_version, updated_at, updated_by_employee_id) VALUES ('INV-00789', 'INC-2026-00789', '影響を受けた架空食品店Aの運用部門で発報した同一アラートの件数が数百件に達していることが確認されました。アラート抑制ルールが未設定であったため、短時間に数百件のアラートが発生したことが原因と考えられます。運用部門はこの事象を軽減するための対策を進める必要があります。', '影響を受けた架空食品店Aの運用部門で発報した同一アラートの件数が数百件に達していることが確認されました。アラート抑制ルールが未設定であったため、短時間に数百件のアラートが発生したことが原因と考えられます。運用部門はこの事象を軽減するための対策を進める必要があります。', TIMESTAMP WITH TIME ZONE '2026-02-19T01:56:22+09:00', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
INSERT INTO oil_incident_responses (response_id, incident_id, response_type, sequence_no, assignee_employee_id, started_at, ended_at, summary, detail, row_version, updated_at, updated_by_employee_id) VALUES ('RSP-01174', 'INC-2026-00789', 'INITIAL', 1, 'EMP-00001', TIMESTAMP WITH TIME ZONE '2026-02-18T02:11:22+09:00', TIMESTAMP WITH TIME ZONE '2026-02-18T03:11:22+09:00', '【障害報告】【監視・可用性障害】アラート疲労に関する初期対応', '運用部の運用 一郎が本事象を発見し、すぐに対応を開始しました。架空食品店Aの関係者に状況を報告し、今後の対応策について協議を行っています。アラート抑制ルールの設定を早急に実施し、再発防止策を講じるための計画を立てています。', 1, TIMESTAMP WITH TIME ZONE '2020-05-01T00:00:00+09:00', 'EMP-00001');
